public class SolB {
    public static void main(String arg[]){
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long m = in.nextLong();
        long xc = in.nextLong();
        long yc = in.nextLong();
        int k = in.nextInt();
        long x[] = new long[k];
        long y[] = new long[k];
        for(int i=0;i<k;i++){
            x[i] = in.nextLong();
            y[i] = in.nextLong();
        }
        int i=0;
        long count=0;
        while(i<k){

            long stepX = 0;
            if(x[i]>0){
                stepX = (n-xc)/x[i];
            }else if(x[i]<0){
                stepX = (xc-1)/(-x[i]);
            }else stepX = Integer.MAX_VALUE;

            long stepY = 0;
            if(y[i]>0){
                stepY = (m-yc)/y[i];
            }else if(y[i]<0){
                stepY = (yc-1)/(-y[i]);
            }else stepY = Integer.MAX_VALUE;

            long step = Math.min(stepX,stepY);

            System.out.println("xc  = "+xc+", yc= "+yc);
            System.out.println("x  = "+x[i]+", y= "+y[i]);
            xc += step*x[i];
            yc += step*y[i];
            System.out.println("after move --- xc  = "+xc+", yc= "+yc);
            count+=step;
            i++;
        }
        System.out.println(count);
    }
}

