struct RLAQ {
  long long sst[1 << 18];
  long long adt[1 << 18];
  RLAQ() {
    fill(sst, sst + (1 << 18), 0);
    fill(adt, adt + (1 << 18), 0);
  }
  void add(int p, int q, long long x, int k = 0, int l = 0, int r = (1 << 17)) {
    if (r <= p || q <= l) return;
    if (p <= l && r <= q) {
      adt[k] += x;
      return;
    }
    add(p, q, x, 2 * k + 1, l, (l + r) / 2);
    add(p, q, x, 2 * k + 2, (l + r) / 2, r);
    sst[k] =
        max(sst[2 * k + 1] + adt[2 * k + 1], sst[2 * k + 2] + adt[2 * k + 2]);
  }
  long long find(int p, int q, int k = 0, int l = 0, int r = (1 << 17)) {
    if (r <= p || q <= l) return LLONG_MIN / 2;
    if (p <= l && r <= q) return sst[k] + adt[k];
    long long m1, m2;
    m1 = find(p, q, 2 * k + 1, l, (l + r) / 2);
    m2 = find(p, q, 2 * k + 2, (l + r) / 2, r);
    return max(m1, m2) + adt[k];
  }
};
