void Eratosthenes(int N) {
  for (int i = 0; i < N; i++) {
    arr[i] = 1;
  }
  for (int i = 2; i < sqrt(N); i++) {
    if (arr[i]) {
      for (int j = i * 2; j <= N; j += i) {
        arr[j] = 0;
      }
    }
  }
  int cou = 0;
  for (int i = 2; i < N; i++) {
    if (arr[i] == 1) {
      arr[cou] = i;
      cou++;
    }
  }
  pc = cou;
}
int main() {
