			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int ni() {
			return Integer.parseInt(next());
		}

		long nl() {
			return Long.parseLong(next());
		}

		double nd() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}


	public static void main(String[] args) throws java.lang.Exception {
		FastReader fr = new FastReader();
		PrintWriter out = new PrintWriter(System.out);
		int t = fr.ni();
		while(t-->0) {
			int n = fr.ni();
			int a = fr.ni();
			int b = fr.ni();
			boolean ans = false;
			if(a == 1) {
				if((n-1)%b == 0)ans = true;
			}else {
				if((n-1)%b == 0) {
					ans = true;
				}
				while(a > 0 && a <= n) {
					if((n-a)%b == 0) {
						ans = true;
						break;
					}else {
						a*=a;
					}
				}
			}
			if(ans)out.println("Yes");
			else out.println("No");
		}
		out.close();
	}

