int rec(int pos, int av0, int av1) {
    if (av0+av1 == 0) return 1;

    int &ret = pd2[pos][av0][av1];
    if (ret == -1) {
        ret = 0;

        if (pos != n && s[pos] == '0') {
            ret = (ret + rec(pos+1, av0, av1)) % mod;
        }
        else if (av0) {
            ret = (ret + rec(pos, av0-1, av1)) % mod;
        }

        if (pos != n && s[pos] == '1') {
            ret = (ret + rec(pos+1, av0, av1)) % mod;
        }
        else if (av1) {
            ret = (ret + rec(pos, av0, av1-1)) % mod;
        }
    }

    // cout << pos << " " << av0 << " " << av1 << " -> " << ret << endl;
    return ret;
}


int main() {
