    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) cnt[j][i+1] = cnt[j][i];
        cnt[s[i]-'0'][i+1]++;
    }

    pd[0][0][0] = 1;
    for (int pos = 0; pos < n; pos++) {
        for (int del0 = 0; del0 <= cnt[0][n]; del0++) {
            for (int del1 = 0; del1 <= cnt[1][n]; del1++) if (pd[pos][del0][del1]) {

                if (pos+2 <= n) {
                    // delete first value
                    int nd0 = del0, nd1 = del1;
                    if (s[pos] == '0') nd0++;
                    if (s[pos] == '1') nd1++;

                    pd[pos+2][nd0][nd1]=1;

                    // delete second value
                    nd0 = del0; nd1 = del1;
                    if (s[pos+1] == '0') nd0++;
                    if (s[pos+1] == '1') nd1++;
                    pd[pos+2][nd0][nd1]=1;
                }

                // delete extras
                int av0 = cnt[0][pos] - del0, av1 = cnt[1][pos] - del1;

                if (av0) pd[pos+1][del0+1][del1]=1;
                if (av1) pd[pos+1][del0][del1+1]=1;


                // delete values using extras
                int nd0 = del0, nd1 = del1;
                if (s[pos] == '0') nd0++;
                if (s[pos] == '1') nd1++;
                if (av0 || av1) pd[pos+1][nd0][nd1]=1;
            }
        }
    }

    int ans = 0;
    for (int del0 = 0; del0 <= cnt[0][n]; del0++) {
        for (int del1 = 0; del1 <= cnt[1][n]; del1++) {
            // if (del0 != 1 || del1 != 1) continue;
            for (int pos = n; pos >= 0; pos--) if (pd[pos][del0][del1]) {
