void func() {
  int N;
  scanf("%d", &N);
  int table[N];
  for (int i = 0; i < N; i++) scanf("%d", &table[i]);
  int dp[N][N];
  for (int i = 0; i < N; i++) {
    for (int k = 0; k < N; k++) {
      dp[i][k] = 0;
    }
  }
  for (int i = 0; i < N; i++) {
    for (int length = 0; length <= N - 1; length++) {
      for (int k = 0; k < length; k++) {
        dp[i][length] =
            max(dp[i][length], dp[i][k] + dp[(i + k + 1) % N][length - k - 1] +
                                   abs(table[i] - table[(i + k + 1) % N]));
      }
    }
  }
  int ans = 0;
  for (int i = 0; i < N; i++) {
    ans = max(ans, dp[i][N - 1]);
  }
