}
pair<int, int> bul(int x, int y, int z, int l, int r, int v) {
  if (T[v].first < z) return {0, 0};
  if (y < l || r < x) return {0, 0};
  if (l == r) return T[v];
  pair<int, int> t1 = bul(x, y, z, l, (l + r) / 2, v << 1);
  if (t1.first > 0) return t1;
  pair<int, int> t2 = bul(x, y, z, (l + r) / 2 + 1, r, v << 1 | 1);
  return t2;
}
