#include <bits/stdc++.h>
using namespace std;
const long long N = 2e5 + 10;
namespace SegmentTree {
const long long M = N << 5;
long long tot, root[N], lc[M], rc[M];
long long sum[M], tag[M];
inline void pushup(long long p) { sum[p] = sum[lc[p]] + sum[rc[p]]; }
inline void pushdown(long long p, long long l, long long r) {
  if (!tag[p]) return;
  if (!lc[p]) lc[p] = ++tot;
  if (!rc[p]) rc[p] = ++tot;
  long long mid = (l + r) >> 1;
  tag[lc[p]] += tag[p];
  sum[lc[p]] += tag[p] * (mid - l + 1);
  tag[rc[p]] += tag[p];
  sum[rc[p]] += tag[p] * (r - mid);
  tag[p] = 0;
}
inline void change(long long &p, long long l, long long r, long long L,
                   long long R, long long val) {
  if (!p) p = ++tot;
  if (L <= l && r <= R) {
    tag[p] += val;
    sum[p] += val * (r - l + 1);
    return;
  }
  pushdown(p, l, r);
  long long mid = (l + r) >> 1;
  if (L <= mid) change(lc[p], l, mid, L, R, val);
  if (R > mid) change(rc[p], mid + 1, r, L, R, val);
  pushup(p);
}
inline long long query(long long p, long long l, long long r, long long L,
                       long long R) {
  if (!p) return 0;
  if (L <= l && r <= R) return sum[p];
  pushdown(p, l, r);
  long long mid = (l + r) >> 1;
  long long res = 0;
  if (L <= mid) res += query(lc[p], l, mid, L, R);
  if (R > mid) res += query(rc[p], mid + 1, r, L, R);
  return res;
}
}  // namespace SegmentTree
long long tot, head[N], ver[N], Next[N];
inline void add(long long x, long long y) {
  ver[++tot] = y;
  Next[tot] = head[x];
  head[x] = tot;
}
long long size[N], dep[N], fa[N], son[N], top[N], seg[N], num;
inline void dfs1(long long x) {
  size[x] = 1;
  dep[x] = dep[fa[x]] + 1;
  for (long long i = head[x]; i; i = Next[i]) {
    long long y = ver[i];
    fa[y] = x;
    dfs1(y);
    size[x] += size[y];
    if (size[y] > size[son[x]]) son[x] = y;
  }
}
inline void dfs2(long long x, long long t) {
  seg[x] = ++num;
  top[x] = t;
  if (son[x]) dfs2(son[x], t);
  for (long long i = head[x]; i; i = Next[i]) {
    long long y = ver[i];
    if (y == son[x]) continue;
    dfs2(y, y);
  }
}
long long n, m, Q, C;
inline long long ask(long long col, long long x) {
  long long res = 0;
  for (; x; x = fa[top[x]])
    res +=
        SegmentTree::query(SegmentTree::root[col], 1, n, seg[top[x]], seg[x]);
  return res;
}
inline void add(long long col, long long x, long long val) {
  for (; x; x = fa[top[x]])
    SegmentTree::change(SegmentTree::root[col], 1, n, seg[top[x]], top[x], val);
}
long long s[N], sum[N];
inline void ins(long long col, long long x) {
  sum[col] += dep[x];
  s[col] += 2ll * ask(col, x);
  s[col] += dep[x];
  add(col, x, 1);
}
inline void del(long long col, long long x) {
  sum[col] -= dep[x];
  add(col, x, -1);
  s[col] -= 2ll * ask(col, x);
  s[col] -= dep[x];
}
long long a[N], b[N];
signed main() {
