#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 9;
const long long MOD = 1e9 + 7;
const int mod = 998244353;
inline long long qpow(long long b, long long e, long long m) {
  long long a = 1;
  for (; e; e >>= 1, b = b * b % m)
    if (e & 1) a = a * b % m;
  return a;
}
long long exgcd(long long a, long long b, long long &x, long long &y) {
  if (b == 0) {
    x = 1, y = 0;
    return a;
  }
  long long d = exgcd(b, a % b, x, y);
  long long z = x;
  x = y, y = z - y * (a / b);
  return d;
}
struct node {
  int a, b, dx, dy;
} l;
int n, m, a, b, c, d, p;
bool vis[maxn << 1][2][2];
int change(int x) {
  if (x == 1) return 1;
  return 0;
}
void solve(node &l) {
  l.a += l.dx;
  l.b += l.dy;
  if (l.dx == 1) {
    if (l.a == n) {
      l.dx = -1;
    }
  } else {
    if (l.a == 1) {
      l.dx = 1;
    }
  }
  if (l.dy == 1 && l.b == m) {
    l.dy = -1;
  }
  if (l.dy == -1 && l.b == 1) {
    l.dy = 1;
  }
}
int main() {
  int _;
  scanf("%d", &_);
  while (_--) {
    memset(vis, 0, sizeof(vis));
    scanf("%d%d%d%d%d%d%d", &n, &m, &a, &b, &c, &d, &p);
    vector<node> ve;
    long long pp = (long long)(100 - p) * qpow(100, MOD - 2, MOD) % MOD;
    l = {a, b, 1, 1};
    if (l.a == n) l.dx = -1;
    if (l.b == m) l.dy = -1;
    while (!vis[l.a * m + l.b][change(l.dx)][change(l.dy)]) {
      vis[l.a * m + l.b][change(l.dx)][change(l.dy)] = 1;
      solve(l);
      ve.push_back(l);
    }
    reverse(ve.begin(), ve.end());
    pair<long long, long long> par = {0, 1};
    for (int i = 0; i < ve.size(); i++) {
      par.first++;
      par.first %= MOD;
      if (ve[i].a == c || ve[i].b == d) {
        par.first = par.first * pp % MOD;
        par.second = par.second * pp % MOD;
      }
    }
    long long ans = par.first * qpow(1 - par.second + MOD, MOD - 2, MOD) % MOD;
    if (a != c && b != d) ans++;
    printf("%lld\n", ans % MOD);
  }
}

import java.io.*; import java.util.*;
public class CF1140E {

    /**
     * Key observation:
     * Note a sequence is good iff it doesn't have a[i]=a[i+2] for some i
     * Key observation 2:
     * Connected Components: even and odd (*)
     * Suppose among a[2i]s, a[m], a[n] are fixed (D&C)
     * 
     * Then we can dp: 
     * let dp1[a] be the number of ways to fill in an interval of length if initial & final numbers are the same
     * dp2[a]: be the number of ways to fill in an interval of length if initial & final numbers are different
     * dpe[a]: the number of ways to fill in an interval of length if one of the initial or final numbers don't exist
     * dp1[0]=0, dp2[0]=1, dpe[1]=1
     * dp1[1]=k-1, dp2[1]=k-2, dpe[1]=k-1
     * dp1[a]=(k-1)dp2[a-1] and dp2[a]=(k-2)dp2[a-1]+dp1[a-1], and dpe[a]=(k-1)dpe[a-1]
     * If initial & final don't exist take k*dpe[a-1]
     * Now we simply take the product of dp's and take MOD
     * Remark: dp1[a]-dp2[a]=(-1)^a
     */
    static int MOD=998244353;
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        int N=Integer.parseInt(st.nextToken());
        int k=Integer.parseInt(st.nextToken());
        int[] arr=new int[N];
        st=new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            arr[i]=Integer.parseInt(st.nextToken());
        }
        long[] dp1=new long[N];
        long[] dp2=new long[N]; dp2[0]=1;
        long[] dpe=new long[N]; dpe[0]=1;
        for (int i = 1; i < N; i++) {
            dp1[i]=(k-1)*dp2[i-1]; dp1[i]%=MOD;
            dp2[i]=(k-2)*dp2[i-1]+dp1[i-1]; dp2[i]%=MOD;
            dpe[i]=(k-1)*dpe[i-1]; dpe[i]%=MOD;
        }
        long ans=1;
        int prev=0; 
        for (int i = 0; i <N; i+=2) {
            if(arr[i]!=-1){
                if(prev==0){
                    ans*=dpe[i/2];
                }else if(arr[prev-2]==arr[i]){
                    ans*=dp1[(i-prev)/2];
                }else{
                    ans*=dp2[(i-prev)/2];
                }
                ans%=MOD;
                prev=i+2;
            }
        }
        //System.out.println("0 "+prev);
        if(prev==0){
            ans*=k*dpe[N/2-1];
            ans%=MOD;
        }else{
            ans*=dpe[(N-prev+1)/2]; ans%=MOD;
        }
        //System.out.println(ans);
        prev=1;
        for (int i = 1; i <N; i+=2) {
            if(arr[i]!=-1){
                if(prev==1){
                    ans*=dpe[(i-prev)/2];
                }else if(arr[prev]==arr[i]){
                    ans*=dp1[(i-prev)/2];
                }else{
                    ans*=dp2[(i-prev)/2];
                }
                ans%=MOD;
                prev=i+2;
            }
        }
       if(prev==1){
            ans*=k*dpe[N/2-1];
            ans%=MOD;
        }else{
            ans*=dpe[(N-prev)/2]; ans%=MOD;
        }
        System.out.println(ans);
    }

}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class C {

    FastScanner scanner;
    PrintWriter writer;

    void solve() throws IOException {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int k = scanner.nextInt();

        int[][] f = new int[4][n];

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < n; j++) {
                f[i][j] = scanner.nextInt();
            }
        }

        int[] p = new int[]{1, 0};

        List<int[]> moves = new ArrayList<>();

        while (k > 0) {
            int[] lot = lot(p);
            int[] nxt = next(p, n);

            int x = get(f, p);
            if (x != 0) {
                if (x == get(f, lot)) {
                    move(f, p, lot, moves);
                    k--;
                } else {
                    if (get(f, nxt) == 0) {
                        move(f, p, nxt, moves);
                    }
                }
            }
            p = nxt;

            if (p[0] == 1 && p[1] == 0 && moves.isEmpty()) {
                writer.println(-1);
                writer.close();
                return;
            }
        }

        writer.println(moves.size());

        for (int[] m : moves) {
            for (int x : m) {
                writer.print((x) + " ");
            }
            writer.println();
        }

        writer.close();
    }

    int[] next(int[] p, int n) {
        if (p[0] == 1) {
            if (p[1] == 0) {
                return new int[]{2, 0};
            } else {
                return new int[]{1, p[1] - 1};
            }
        } else {
            if (p[1] == n - 1) {
                return new int[]{1, n - 1};
            } else {
                return new int[]{2, p[1] + 1};
            }
        }
    }

    int[] lot(int[] p) {
        if (p[0] == 1) {
            return new int[]{0, p[1]};
        } else {
            return new int[]{3, p[1]};
        }
    }

    void move(int[][] f, int[] from, int[] to, List<int[]> moves) {
        int x = get(f, from);
        moves.add(new int[]{x, to[0] + 1, to[1] + 1});
        f[to[0]][to[1]] = x;
        f[from[0]][from[1]] = 0;
    }

    int get(int[][] f, int[] p) {
        return f[p[0]][p[1]];
    }

    public static void main(String... args) throws IOException {
        new C().solve();
    }

    static class FastScanner {

        BufferedReader br;
        StringTokenizer tokenizer;

        FastScanner(String fileName) throws FileNotFoundException {
            this(new FileInputStream(new File(fileName)));
        }

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String nextLine() throws IOException {
            tokenizer = null;
            return br.readLine();
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
vector<string> per[11][120000];
int ind[11];
inline void push(int id, vector<string> &v) { per[id][ind[id]++] = v; }
void change(vector<string> &v, char *t, vector<string> &out) {
  out = v;
  for (int i = 0; i < out.size(); i++) {
    for (int j = 0; j < out[i].length(); j++) {
      out[i][j] = t[out[i][j] - '0'];
    }
  }
}
void init() {
  ind[1] = 1;
  vector<string> v;
  v.push_back("0");
  per[1][0] = v;
  int i, j, k;
  char t[11];
  for (i = 2; i <= 10; i++) {
    for (int state = 0; state < (1 << (i - 1)); state++) {
      if (state == (1 << (i - 1)) - 1) {
        string s = "";
        for (j = 0; j < i; j++) s += (char)('0' + j);
        v.clear();
        v.push_back(s);
        push(i, v);
        break;
      }
      string s = "";
      int num = 0;
      for (j = 0; j < i - 1; j++) {
        if (state & (1 << j))
          s += char(j + '0');
        else {
          t[num++] = '0' + j;
        }
      }
      s += char(i - 1 + '0');
      for (j = 0; j < ind[num]; j++) {
        change(per[num][j], t, v);
        v.push_back(s);
        push(i, v);
      }
    }
  }
}
void output(vector<string> &v) {
  for (int i = 0; i < v.size(); i++) {
    if (i) putchar(',');
    putchar('{');
    for (int j = 0; j < v[i].length(); j++) {
      if (j) putchar(',');
      putchar(char(1 + v[i][j]));
    }
    putchar('}');
  }
  puts("");
}
int main() {
  init();
  int n;
  while (cin >> n) {
    int i, j, k;
    for (i = 0; i < ind[n]; i++) {
      sort(per[n][i].begin(), per[n][i].end());
    }
    sort(per[n], per[n] + ind[n]);
    for (i = 0; i < ind[n]; i++) {
      output(per[n][i]);
    }
  }
}

