            int n = inp.nextInt();
            int m = inp.nextInt();
            int c = inp.nextInt();
            int arr[] = new int[n];
            int b[] = new int[m];
            for(int i=0;i<n;i++)
            {
                arr[i] = inp.nextInt();
            }

            for(int i=0;i<m;i++)
            {
                b[i] = inp.nextInt();
            }

            int pre[] = new int[m];

            int suf[] = new int[m];

            pre[0]=b[0];
            for(int i=1;i<m;i++)
            {
                pre[i]=(b[i]+pre[i-1])%c;
            }
            suf[m-1]=b[m-1];
            for(int i=m-2;i>=0;i--)
            {
                suf[i]=(suf[i+1]+b[i])%c;
            }

            for(int i=0;i<=n-m;i++)
            {
                if(i>=0&&i<=m-1)
                {
                    arr[i]=(arr[i]+pre[i])%c;
                    continue;
                }
                arr[i] = (arr[i]+pre[m-1])%c;
            }

            for(int i=n-m+1;i<=n-1;i++)
            {

                if(i+1>=m)
                {
                    arr[i] = (arr[i] + suf[i-n+m])%c;

                }
                else
                {
                    arr[i] = (arr[i]+ suf[i-n+m] - suf[i+1])%c;
                }
            }

            for(int i=0;i<n;i++)
            {
                out1.print(arr[i]+" ");
            }
        }
