int n;
long long f[5005], inv[5005], mod = 998244353, ans[5005], por[5005][5005],
                              w[5005];
long long pwr(long long a, long long p) {
  if (!a && !p) return 1;
  if (!p) return 1;
  long long t = pwr(a, p / 2);
  t *= t;
  t %= mod;
  if (p % 2) t *= a, t %= mod;
  return t;
}
long long comb(long long n, long long k) {
  return f[n] * inv[k] % mod * inv[n - k] % mod;
}
int32_t main() {
  ios_base ::sync_with_stdio(0);
  cin.tie();
  cout.tie();
  cin >> n;
  f[0] = 1;
  inv[0] = 1;
  for (int i = 1; i <= n; i++) {
    f[i] = f[i - 1] * i % mod;
    inv[i] = pwr(f[i], mod - 2);
    w[i] = pwr(i, mod - 2);
  }
  for (int i = 0; i <= n; i++) {
    por[i][0] = 1;
    for (int j = 1; j <= n; j++) {
      por[i][j] = por[i][j - 1] * i % mod;
    }
  }
  for (int t = 1; t <= n; t++) {
    long long p = 0;
    for (int s = t; s <= n; s++) {
      p += comb(s - 1, t - 1) * por[t - 1][s - t] % mod * por[t][n - s] % mod;
      p %= mod;
    }
    p *= n * w[t] % mod;
    p %= mod;
    for (int i = 1; i <= t; i++) {
      ans[i] += p;
      ans[i] %= mod;
    }
  }
  for (int i = 1; i <= n; i++) cout << ans[i] << ' ';
}

