#include <bits/stdc++.h>
using namespace std;
unsigned long long A[410005], SM;
unsigned int poz, X, Val, st, dr;
unsigned int v[100005], MX[410005];
void build(int nod, int l, int r) {
  if (l == r) {
    A[nod] = v[l];
    MX[nod] = v[l];
    return;
  }
  int div = (l + r) / 2;
  build(2 * nod, l, div);
  build(2 * nod + 1, div + 1, r);
  A[nod] = A[2 * nod] + A[2 * nod + 1];
  MX[nod] = max(MX[2 * nod], MX[2 * nod + 1]);
}
void update(int nod, int l, int r) {
  if (l == r) {
    A[nod] = Val;
    return;
  }
  int div = (l + r) / 2;
  if (poz <= div)
    update(2 * nod, l, div);
  else
    update(2 * nod + 1, div + 1, r);
  A[nod] = A[2 * nod] + A[2 * nod + 1];
  MX[nod] = max(MX[2 * nod], MX[2 * nod + 1]);
}
void modulo(int nod, int l, int r) {
  if (MX[nod] < X) return;
  if (l == r) {
    A[nod] %= X;
    return;
  }
  int div = (l + r) / 2;
  if (st <= div) modulo(2 * nod, l, div);
  if (dr > div) modulo(2 * nod + 1, div + 1, r);
  A[nod] = A[2 * nod] + A[2 * nod + 1];
}
void SUM(int nod, int l, int r) {
  if (st <= l && r <= dr) {
    SM += A[nod];
    return;
  }
  int div = (l + r) / 2;
  if (st <= div) SUM(2 * nod, l, div);
  if (dr > div) SUM(2 * nod + 1, div + 1, r);
}
int main() {
  int N, Q, i, j, op;
  cin >> N >> Q;
  for (i = 1; i <= N; ++i) cin >> v[i];
  build(1, 1, N);
  while (Q--) {
    cin >> op;
    if (op == 1) {
      cin >> st >> dr;
      SM = 0;
      SUM(1, 1, N);
      cout << SM << '\n';
    }
    if (op == 2) {
      cin >> st >> dr >> X;
      modulo(1, 1, N);
    }
    if (op == 3) {
      cin >> poz >> Val;
      update(1, 1, N);
    }
  }
  return 0;
}

