void seive() {
  mind[1] = 1;
  for (int i = 2, s; i < M; i++) {
    if (!ist[i]) {
      pri[++pcnt] = i;
      mind[i] = i;
    }
    for (int j = 1; j <= pcnt && (s = pri[j] * i) < M; j++) {
      ist[s] = true;
      mind[s] = pri[j];
      if (i % pri[j] == 0) break;
    }
  }
}
