int low(int p) { return p & (-p); }
void merg(int x, int y, int n, int m, int k) {
  while (x <= n) {
    int p = y;
    while (p <= m) {
      bit[x][p] += k;
      p = p + low(p);
    }
    x = x + low(x);
  }
}
int sum(int x, int y) {
  int s = 0;
  while (x) {
    int p = y;
    while (p) {
      s += bit[x][p];
      p = p - low(p);
    }
    x = x - low(x);
  }
  return s;
}
