int find(int x1, int y1, int x2, int y2) {
  int w = sum(x2, y2);
  w -= sum(x2, y1 - 1);
  w -= sum(x1 - 1, y2);
  w += sum(x1 - 1, y1 - 1);
  return w;
}
void solve(vector<pi> g, int l, int r) {
  if (l == r) {
    for (pi v : g) {
      ans[v.id] = l;
    }
    for (p1 v : gg[l]) {
      merg(v.x, v.y, n, m, 1);
    }
    return;
  }
  int mid = (l + r) / 2;
  vector<pi> g1, g2;
  g1.clear();
  g2.clear();
  for (int i = mid + 1; i <= r; i++) {
    for (p1 v : gg[i]) {
      merg(v.x, v.y, n, m, 1);
    }
  }
  for (pi v : g) {
    if (v.x2 - v.x1 < mid || v.y2 - v.y1 < mid) {
      g1.push_back(v);
    } else {
      if (find(v.x1 + mid, v.y1 + mid, v.x2, v.y2) > 0) {
        g2.push_back(v);
      } else
        g1.push_back(v);
    }
  }
  for (int i = mid + 1; i <= r; i++) {
    for (p1 v : gg[i]) {
      merg(v.x, v.y, n, m, -1);
    }
  }
  solve(g2, mid + 1, r);
  solve(g1, l, mid);
}
