bool Valid(long long col) {
  col--;
  for (long long row = 1; row < n; ++row)
    if ((grid[row][col] + grid[row][col + 1] + grid[row + 1][col] +
         grid[row + 1][col + 1]) %
            2 ==
        0)
      return false;
  return true;
}
long long dfs(long long col, long long sum = 0) {
  if (col == m + 1) return 0;
  long long &res = Dp[sum][col], cost, s = 0, bit, passed = 0, Prev[4];
  if (res != -1) return res;
  res = (long long)1e7;
  for (long long i = 1; i <= n; ++i) Prev[i] = grid[i][col];
  for (long long x = 0; x < (1 << n); ++x) {
    cost = s = 0;
    for (long long i = 0; i < n; ++i)
      grid[i + 1][col] = (bool)(x & (1 << i)),
               cost += (bool)(grid[i + 1][col] != Prev[i + 1]), bit = (1 << i),
               s += bit * grid[i + 1][col];
    if (Valid(col)) res = min(res, cost + dfs(col + 1, s)), passed = 1;
  }
  for (long long i = 1; i <= n; ++i) grid[i][col] = Prev[i];
  if (!passed) res = -1;
  return res;
}
