int lcs(string s, string t){
	int n = s.size();
	int dp[n][n] = {{0}};
	fr(i, 0, n){
		fr(j, 0, n){
			if(i == 0 and j == 0){
				dp[i][j] = (s[i] == t[j]);
				continue;
			}
			else if(i == 0){
				if(s[i] == t[j]) dp[i][j] = 1;
				else dp[i][j] = dp[i][j - 1];
			}
			else if(j == 0){
				if(s[i] == t[j]) dp[i][j] = 1;
				else dp[i][j] = dp[i - 1][j];
			}
			else{
				if(s[i] == t[j]){
					dp[i][j] = dp[i - 1][j - 1] + 1;
				}
				else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
			}
		}
	}

	return dp[n - 1][n - 1];
}
