  set<long long> t;
  for (long long i = 1; i <= n; i++) t.insert(i);
  long long temp = s;
  usin.insert(min(n, s));
  temp -= min(n, s);
  t.erase(min(n, s));
  while (temp) {
    auto it = t.lower_bound(temp);
    if (it == t.end()) it--;
    temp -= *it;
    t.erase(it);
    usin.insert(*it);
  }
  while (usin.size() < r - l + 1) {
    long long u = *usin.begin();
    bool c = true;
    for (long long i = 1; i <= n; i++) {
      if (t.find(i) != t.end() and t.find(u - i) != t.end()) {
        usin.erase(u);
        t.insert(u);
        usin.insert(i);
        usin.insert(u - i);
        t.erase(i);
        t.erase(u - i);
        c = false;
        break;
      }
    }
    if (c) break;
  }
  if (usin.size() != r - l + 1) {
