        if ((mask >> i) & 1) {
          sum += a[i];
          if (sum >= 1000000007) {
            sum = 1000000007;
          }
        } else {
          ret += dp[mask | (1 << i)];
          if (ret >= 1000000007) ret -= 1000000007;
        }
      }
      if (sum == bad[0] || sum == bad[1]) {
        ret = 0;
      }
      dp[mask] = ret;
    }
    cout << dp[0] << endl;
  }
