#include <bits/stdc++.h>
using namespace std;
const int maxN = 100 * 1000 + 5;
const int mod = 1000 * 1000 * 1000 + 7;
const int SQ = 400;
int fen[SQ][maxN], a[maxN];
void add(int ps, int n, int k) {
  for (; n < maxN; n += n & (-n)) fen[ps][n] += k;
}
int get(int ps, int n) {
  int res = 0;
  for (; n > 0; n -= n & (-n)) res += fen[ps][n];
  return res;
}
deque<int> d[SQ];
void shift(int l, int r) {
  int stl = l / SQ;
  int str = r / SQ;
  if (stl == str) {
    int ck = d[stl][r % SQ];
    for (int i = (r % SQ) - 1; i >= l % SQ; i--) d[stl][i + 1] = d[stl][i];
    d[stl][l] = ck;
    return;
  }
  vector<int> fake;
  int tmp = r % SQ;
  while (tmp) fake.push_back(d[str].front()), d[str].pop_front(), tmp--;
  int ck = fake.back();
  fake.pop_back();
  add(str, ck, -1);
  while (fake.size()) d[str].push_front(fake.back()), fake.pop_back();
  while (d[stl].size() > l % SQ)
    fake.push_back(d[stl].back()), d[stl].pop_back();
  d[stl].push_back(ck);
  ck = fake.back();
  fake.pop_back();
  while (fake.size() > 1) d[stl].push_back(fake.back()), fake.pop_back();
  add(stl, ck, 1);
  ck = fake.back();
  add(stl, ck, -1);
  for (int i = stl + 1; i < str; i++) {
    add(i, ck, 1);
    d[i].push_front(ck);
    ck = d[i].back();
    d[i].pop_back();
    add(i, ck, -1);
  }
  add(str, ck, 1);
  d[str].push_front(ck);
}
int gett(int l, int r, int k) {
  int stl = l / SQ;
  int str = r / SQ;
  int cnt = 0;
  for (int i = stl + 1; i < str; i++) cnt += get(i, k);
  for (int i = l % SQ; i < d[stl].size(); i++) {
    if (d[stl][i] == k) cnt++;
    if (stl == str && r == i) break;
  }
  if (stl < str) {
    for (int i = 0; i < (r % SQ) + 1; i++)
      if (d[str][i] == k) cnt++;
  }
  return cnt;
}
