void convex_hull(vector<pt> a) {
  if (a.size() == 1) return;
  sort(a.begin(), a.end(), &cmp);
  pt p1 = a[0], p2 = a.back();
  vector<pt> up, down;
  up.push_back(p1);
  down.push_back(p1);
  for (size_t i = 1; i < a.size(); ++i) {
    if (i == a.size() - 1 || cw(p1, a[i], p2)) {
      while (up.size() >= 2 && !cw(up[up.size() - 2], up[up.size() - 1], a[i]))
        up.pop_back();
      up.push_back(a[i]);
    }
    if (i == a.size() - 1 || ccw(p1, a[i], p2)) {
      while (down.size() >= 2 &&
             !ccw(down[down.size() - 2], down[down.size() - 1], a[i]))
        down.pop_back();
      down.push_back(a[i]);
    }
  }
  for (auto it : up) {
    if (it.x % 2 == 1) winA();
    if (it.y % 2 == 1) winA();
  }
}
const int N = 2e5 + 10;
vector<pt> del_up[N];
vector<pt> del_down[N];
void convex_hull2(vector<pt> a) {
  if (a.size() == 1) return;
  sort(a.begin(), a.end(), &cmp);
  pt p1 = a[0], p2 = a.back();
  vector<pt> up, down;
  up.push_back(p1);
  down.push_back(p1);
  vector<int> ind_up, ind_down;
  ind_up.push_back(0);
  ind_down.push_back(1);
  for (size_t i = 1; i < a.size(); ++i) {
    if (i == a.size() - 1 || cw(p1, a[i], p2)) {
      while (up.size() >= 2 &&
             !cw(up[up.size() - 2], up[up.size() - 1], a[i])) {
        del_up[i].push_back(up.back());
        up.pop_back();
        ind_up.pop_back();
      }
      up.push_back(a[i]);
      ind_up.push_back(i);
    }
    if (i == a.size() - 1 || ccw(p1, a[i], p2)) {
      while (down.size() >= 2 &&
             !ccw(down[down.size() - 2], down[down.size() - 1], a[i])) {
        del_down[i].push_back(down.back());
        down.pop_back();
        ind_down.pop_back();
      }
      down.push_back(a[i]);
      ind_down.push_back(i);
    }
  }
  for (int i = 1; i + 1 < ind_up.size(); i++) {
    int v = ind_up[i];
    int l = 0;
    while (l < del_up[v].size() && !cw(up[i - 1], del_up[v][l], up[i + 1])) l++;
    while (l < del_up[v].size()) {
      if (del_up[v][l].x % 2 == 1 || del_up[v][l].y % 2 == 1) winA();
      l++;
    }
  }
  for (int i = 1; i + 1 < ind_down.size(); i++) {
    int v = ind_down[i];
    int l = 0;
    while (l < del_down[v].size() &&
           !ccw(down[i - 1], del_down[v][l], down[i + 1]))
      l++;
    while (l < del_down[v].size()) {
      if (del_down[v][l].x % 2 == 1 || del_down[v][l].y % 2 == 1) winA();
      l++;
    }
  }
}
