ll ksm(ll a,ll b=mod-2)
{
	if(b==0) return 1;
	if(b==1) return a;
	ll q=ksm(a,b>>1);
	if(b&1) return q*q%mod*a%mod;
	return q*q%mod;
}
ll C(int a,int b)
{
	if(b>a || b<0) return 0;
	if(a==b || b==0) return 1;
	return fac[a]*inv[b]%mod*inv[a-b]%mod;
}
