	for(int i=0;i<=mn;i++)
	ans=(ans+(i&1?-1:1)*C(n,i)*C(m,i)%mod*fac[i]%mod*ksm(n+1,m-i)%mod*ksm(m+1,n-i)%mod+mod)%mod;
