typedef long long lol;
const lol mo=1073741823;
int a[N],head[N],list[N<<1],next[N<<1],w[N<<1],ap=1;
int n,q,fa[N],val[N],sz[N],son[N];
int dfn[N],cnt,top[N],id[N],last;
int root[N],tot,ls[S],rs[S],L,R,t[S];
