IL int rd(){
	int res=0;char c;while((c=getchar())<'0'||c>'9');
	while(c>='0'&&c<='9')res=res*10+c-'0',c=getchar();return res;
}
IL void output(lol x){
	static char str[23];
	if(!x){putchar('0'),putchar('\n');return;}
	int top=0;while(x)str[++top]=x%10,x/=10;
	while(top)putchar(str[top--]+'0');putchar('\n');
}
IL void link(int a,int b,int c){
	list[++ap]=b,next[ap]=head[a],head[a]=ap,w[ap]=c;
	list[++ap]=a,next[ap]=head[b],head[b]=ap,w[ap]=c;
}
IL void dfs(int u){
	int x,v;sz[u]=1;
	for(x=head[u];x;x=next[x])
		if((v=list[x])!=fa[u]){
			fa[v]=u,dep[v]=dep[u]+(val[v]=w[x]);dfs(v);
			if(sz[v]>sz[son[u]])son[u]=v;
		}
}
IL void dfs2(int u,int tp){
	top[u]=tp;id[dfn[u]=++cnt]=u;
	if(son[u]){
		dfs2(son[u],tp);
		int x;
		for(x=head[u];x;x=next[x])
			if(list[x]!=fa[u] && list[x]!=son[u])
				dfs2(list[x],list[x]);
	}
}
IL void cover(int &np,int l,int r){
	if(np<=last)
	t[++tot]=t[np],sum[tot]=sum[np],ls[tot]=ls[np],rs[tot]=rs[np],np=tot;
	if(tot>=S-10){
		printf("Memery used");
		exit(0);
	}
	if(L<=l && R>=r){t[np]++,sum[np]+=s[r]-s[l-1];return;}
	int mid=(l+r)>>1;
	if(L<=mid)cover(ls[np],l,mid);if(R>mid)cover(rs[np],mid+1,r);
	sum[np]=sum[ls[np]]+sum[rs[np]]+t[np]*(s[r]-s[l-1]);
}
IL lol ask(int np,int l,int r,int bs){
	lol res=0;
	if(L<=l && R>=r){return res+sum[np]+(s[r]-s[l-1])*bs;}
	int mid=(l+r)>>1;bs+=t[np];
	if(L<=mid)res+=ask(ls[np],l,mid,bs);
	if(R>mid)res+=ask(rs[np],mid+1,r,bs);
	return res;
}
IL lol Q(int l,int r,int v){
	lol res=0;l--;
	while(v){
		L=dfn[top[v]],R=dfn[v];
		if(l)res-=ask(root[l],1,n,0);
		res+=ask(root[r],1,n,0);
		v=fa[top[v]];
	}
	return res;
}
IL void rebuild(int u){
	int x=a[u];last=tot;
	while(x){
		L=dfn[top[x]],R=dfn[x];
		cover(root[u],1,n),x=fa[top[x]];
	}
}
int main(){
	n=rd(),q=rd();int i,j,u,v,w;
	REP(i,1,n)a[i]=rd();
	REP(i,2,n){
		u=rd(),v=rd(),w=rd();
		link(u,v,w);
	}
	dfs(1);dfs2(1,1);
	REP(i,1,n)s[i]=s[i-1]+val[id[i]];
	REP(i,1,n)pre[i]=pre[i-1]+dep[a[i]];
	REP(i,1,n)root[i]=root[i-1],rebuild(i);
	REP(j,1,q){
		if(tot>S-25000){
			tot=0;
			REP(i,1,n)root[i]=root[i-1],rebuild(i);
		}
		i=rd(),u=(rd()^ans)&mo;
		if(i==1){
			v=(rd()^ans)&mo,w=(rd()^ans)&mo;
			ans=pre[v]-pre[u-1]+(v-u+1)*dep[w]-(Q(u,v,w)<<1);
			output(ans);
		}	else{
			pre[u]=pre[u-1]+dep[a[u+1]],swap(a[u],a[u+1]);
			root[u]=root[u-1];rebuild(u);
		}
	}
	return 0;
}

