        {
            if(input[i] == '?')
                arr[i] = -1;
            else
                arr[i] = input[i]-'a';
        }
        int low = 0;
        int high = N/K;
        while(low != high)
        {
            int mid = (low+high+1)>>1;
            int[][] right = new int[K][N];
            for(int c=0; c < K; c++)
            {
                Arrays.fill(right[c], INF);
                int tot = 0;
                for(int i=0; i < mid; i++)
                    if(arr[i] == c || arr[i] == -1)
                        tot++;
                if(tot == mid)
                    right[c][0] = mid;
                for(int i=mid; i < N; i++)
                {
                    if(arr[i-mid] == c || arr[i-mid] == -1)
                        tot--;
                    if(arr[i] == c || arr[i] == -1)
                        tot++;
                    if(tot == mid)
                        right[c][i-mid+1] = i+1;
                }
                for(int i=N-2; i >= 0; i--)
                    right[c][i] = min(right[c][i], right[c][i+1]);
            }
            int[] dp = new int[1<<K];
            Arrays.fill(dp, INF);
            dp[0] = 0;
            for(int mask=0; mask < 1<<K; mask++)
                if(dp[mask] < N)
