final class Task {
	public static InputReader in;
	public static OutputWriter out;
	public static DebugWriter dout;

	public void solve() {
		n = in.readInt();
		int k = in.readInt();

		boolean[][] g = new boolean[n][m];
		while (k-- > 0) {
			int pj = in.readInt() - 1;
			int pi = in.readInt() - 1;
			g[pj][pi] = true;
		}

		dp = new int[n + 1][3][3];
		was = new boolean[n + 1][3][3];
		tmp = new boolean[n + 1][3][3][300];

		int res = 0;
		int l = 0;


		// dout.printLine(g);

		while (l < n) {
			if (g[l][0] || g[l][1]) {
				++l;
			} else {
				int left;
				if (l == 0) left = 2;
				else if (g[l - 1][0]) left = 0;
				else if (g[l - 1][1]) left = 1;
				else throw new RuntimeException("lal");

				int r = l;
				while (r < n && !g[r][0] && !g[r][1])
					++r;

				int right;
				if (r == n) right = 2;
				else if (g[r][0]) right = 0;
				else if (g[r][1]) right = 1;
				else throw new RuntimeException("lal");

				// dout.printLine(r - l);
				// dout.printLine(left);
				// dout.printLine(right);

				res ^= f(r - l, left, right);

				l = r;				
			}

		}

		if (res == 0) {
			out.printLine("LOSE");
		} else {
			out.printLine("WIN");
		}
	}

	int n;
	int m = 2;

	int[][][] dp;
	boolean[][][] was;

	boolean[][][][] tmp;

	int f(int len, int left, int right) {
		if (was[len][left][right]) return dp[len][left][right];
		was[len][left][right] = true;

		// dout.printLine("len = " + len);

		if (len == 0) return dp[len][left][right] = 0;

		int value = 0;

		for (int j = 0; j < len; ++j)
			for (int i = 0; i < 2; ++i) {
				if (j == 0 && left != 2 && left != i) continue;

				if (j == len - 1 && right != 2 && right != i) continue;

				value = f(j, left, i);

				if (len - 1 - j > 0)
					value ^= f(len - 1 - j, i, right);

				if (value < tmp[len][left][right].length)
					tmp[len][left][right][value] = true;

			}

		// if (len == 2)
			// dout.printLine(tmp[len][left][right]);

		for (int i = 0; i < tmp[len][left][right].length; ++i)
			if (!tmp[len][left][right][i])
				return dp[len][left][right] = i;

		throw new RuntimeException("lal");
	}
}

final class InputReader {
	private boolean finished = false;

	private InputStream stream;
	private byte[] buf = new byte[1 << 13];
	private int curChar;
	private int numChars;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	private int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}

	public int peek() {
		if (numChars == -1)
			return -1;
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				return -1;
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar];
	}

	public int readInt() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		int res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

	public long readLong() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		long res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

	public String readString() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
			c = read();
		} while (!isSpaceChar(c));
		return res.toString();
	}

	public static boolean isSpaceChar(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}

	private String readLine0() {
		StringBuilder buf = new StringBuilder();
		int c = read();
		while (c != '\n' && c != -1) {
			if (c != '\r')
				buf.appendCodePoint(c);
			c = read();
		}
		return buf.toString();
	}

	public String readLine() {
		String s = readLine0();
		while (s.trim().length() == 0)
			s = readLine0();
		return s;
	}

	public String readLine(boolean ignoreEmptyLines) {
		if (ignoreEmptyLines)
			return readLine();
		else
			return readLine0();
	}

	public String readToEnd() {
		StringBuilder buf = new StringBuilder();
		int c = read();
		while (c != -1) {
			if (c != '\r')
				buf.appendCodePoint(c);
			c = read();
		}
		return buf.toString();
	}

	public BigInteger readBigInteger() {
		try {
			return new BigInteger(readString());
		} catch (NumberFormatException e) {
			throw new InputMismatchException();
		}
	}

	public char readCharacter() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		return (char) c;
	}

	public double readDouble() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		double res = 0;
		while (!isSpaceChar(c) && c != '.') {
			if (c == 'e' || c == 'E')
				return res * Math.pow(10, readInt());
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		}
		if (c == '.') {
			c = read();
			double m = 1;
			while (!isSpaceChar(c)) {
				if (c == 'e' || c == 'E')
					return res * Math.pow(10, readInt());
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				m /= 10;
				res += (c - '0') * m;
				c = read();
			}
		}
		return res * sgn;
	}

	public boolean isExhausted() {
		int value;
		while (isSpaceChar(value = peek()) && value != -1)
			read();
		return value == -1;
	}

	public void close() {
		try {
			stream.close();
		} catch (IOException e) {
			throw new RuntimeException();           
		}
	}
}

