  memset(adj, 0, sizeof adj);
  scanf("%d%I64d%d", &n, &y, &m);
  for (i = (0); i < (m); i++) {
    scanf("%d%d", &a, &b);
    adj[b - 1] |= (1 << (a - 1));
  }
  imprimir(y - 2001LL + 1LL);
  return 0;
}

