  {
    int c = cen[0];
    for (auto v : e[c])
      if (!isCen[v]) solve(v, c);
  }
  if (cen.size() > 1) {
    int c = cen[1];
    for (auto v : e[c])
      if (!isCen[v]) solve(v, c);
