    scanf("%d%d", &n, &l);
    root = new trie();
    for (int i = 1; i <= n; i++) {
        scanf("%s", buf);
        Insert();
    }
    DFS(root, 0);
    puts(ans ? "Alice" : "Bob");
    return 0;
}

