#include <bits/stdc++.h>
using namespace std;
int N, M;
string s;
vector<pair<int, int> > vec;
int r[3005];
long long dp[3005][3005];
int main(void) {
  cin >> N >> M;
  cin >> s;
  int a, b;
  for (int i = 0; i < M; i++) {
    cin >> a >> b;
    vec.push_back(make_pair(a, b));
  }
  for (int i = 1; i < vec.size(); i++) {
    if (vec[i].second <= vec[i - 1].second) {
      vec.erase(vec.begin() + i);
      i--;
    }
  }
  for (int i = 0; i < vec.size() - 1; i++) {
    if (vec[i].first == vec[i + 1].first) {
      vec.erase(vec.begin() + i);
      i--;
    }
  }
  int cur = 1, prev = 0;
  for (int i = 0; i < vec.size(); i++) {
    for (int j = cur; j < vec[i].first; j++) r[j] = max(j, prev);
    r[vec[i].first] = vec[i].second;
    cur = vec[i].first + 1;
    prev = vec[i].second;
  }
  for (int j = cur; j <= N; j++) r[j] = prev;
  r[N + 1] = N;
  dp[0][0] = 1;
  for (int i = 0; i <= N; i++) {
    int Y = 0;
    for (int j = r[i] + 1; j <= r[i + 1]; j++)
      if (s[j - 1] == '1') Y++;
    for (int j = 0; j <= N - Y; j++) {
      if (j < r[i] - i + 1) {
        dp[i + 1][j + Y] += dp[i][j];
        dp[i + 1][j + Y] %= 1000000007;
      }
      if (j > 0) {
        dp[i + 1][j - 1 + Y] += dp[i][j];
        dp[i + 1][j - 1 + Y] %= 1000000007;
      }
    }
  }
  cout << dp[N + 1][0] << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long N = 3000;
std::vector<pair<long long, long long> > v[N];
bool visited[N];
long long color[N];
bool flag;
void dfs(long long n) {
  visited[n] = 1;
  for (auto i : v[n]) {
    if (visited[i.first] == 0)
      color[i.first] = color[n] ^ i.second, dfs(i.first);
    else {
      if (color[i.first] != (color[n] ^ i.second)) {
        flag = 0;
      }
    }
  }
}
long long mod_expo(long long a, long long b, long long c) {
  long long ans = 1;
  while (b) {
    if (b & (long long)1) ans = (ans * a) % c;
    a = (a * a) % c;
    b = b >> 1;
  }
  return ans;
}
void check(long long n, bool now, long long k) {
  if (n == k) {
    if (now == true) {
      flag = 0;
      return;
    }
  }
  visited[n] = 1;
  for (auto i : v[n]) {
    if (visited[i.first] == 0) {
      if (i.second) {
        check(i.first, !now, k);
      } else {
        check(i.first, now, k);
      }
    }
  }
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  string s;
  cin >> s;
  string a;
  a = s;
  long long n = s.size();
  reverse(s.begin(), s.end());
  long long ans = 0;
  for (long long k = 1; k < n; k++) {
    long long index = n + 2;
    for (long long i = 0; i < (index + k); i++)
      v[i].clear(), visited[i] = 0, color[i] = 0;
    for (long long i = 0; i < n / 2; i++) {
      v[i].push_back(make_pair(n - 1 - i, 0));
      v[n - 1 - i].push_back(make_pair(i, 0));
    }
    for (long long i = 0; i < k / 2; i++) {
      v[index + i].push_back(make_pair(index + k - 1 - i, 0));
      v[index + k - 1 - i].push_back(make_pair(index + i, 0));
    }
    for (long long i = 0; i < k; i++) {
      if (s[i] == '0') {
        v[i].push_back(make_pair(index + i, 0));
        v[index + i].push_back(make_pair(i, 0));
      } else if (s[i] == '1') {
        v[i].push_back(make_pair(index + i, 1));
        v[index + i].push_back(make_pair(i, 1));
      }
    }
    for (long long i = k; i < n; i++) {
      if (s[i] == '0') {
        v[i].push_back(make_pair(n + 1, 0));
        v[n + 1].push_back(make_pair(i, 0));
      } else if (s[i] == '1') {
        v[i].push_back(make_pair(n, 0));
        v[n].push_back(make_pair(i, 0));
      }
    }
    v[index + k - 1].push_back(make_pair(n, 0));
    v[n].push_back(make_pair(index + k - 1, 0));
    flag = 1;
    memset(visited, 0, sizeof(visited));
    visited[n] = visited[n + 1] = 1;
    color[n] = 1;
    color[n + 1] = 0;
    dfs(n);
    {
      dfs(n + 1);
      long long count = 0;
      for (long long i = 0; i < (index + k); i++) {
        if (visited[i] == 0) {
          dfs(i);
          count++;
        }
      }
      if (flag) ans = (ans + mod_expo(2, count, 998244353)) % 998244353;
    }
  }
  cout << ans << endl;
  return 0;
}

