    for (int i = 0; i < n; ++i) {
      cin >> b[i];
      idx[b[i]].push_back(i);
    }
    int subs;
    for (int i = 1; i <= n + 1; ++i) {
      cnt[idx[i].size()].push_back(i);
      if (idx[i].size() == 0) subs = i;
    }
