    for (int i = 0; i < x; ++i) {
      while (cnt[j].empty()) --j;
      int clr = cnt[j].back();
      cnt[j].pop_back();
      cnt[j - 1].push_back(clr);
      a[idx[clr].back()] = clr;
      idx[clr].pop_back();
    }
    while (cnt[j].empty()) --j;
    if (2 * j > 2 * n - y - x) {
      cout << "NO" << endl;
      continue;
    }
    vector<int> ve;
    while (j > 0) {
      for (int q = 0; q < cnt[j].size(); q++)
        ve.insert(ve.end(), idx[cnt[j][q]].begin(), idx[cnt[j][q]].end());
      --j;
    }
    int ves = ve.size(), mismatch = y - x;
    for (int i = 0; i < ves; ++i) {
      if (mismatch > 0) {
        j = (i + (n - x) / 2) % ves;
        if (b[ve[i]] == b[ve[j]]) {
          a[ve[i]] = subs;
        } else {
          a[ve[i]] = b[ve[j]];
          --mismatch;
        }
      } else
        a[ve[i]] = subs;
    }
    cout << "YES" << endl;
    for (int i = 0; i < n; ++i) cout << a[i] << " ";
    cout << endl;
  }
  return 0;
}

