#include <bits/stdc++.h>
using namespace std;
struct Query {
  int i, a, t, x, ans;
};
vector<Query> query;
vector<int> xset, tset, ans;
map<int, int> xmap, tmap;
vector<vector<Query> > house;
struct Fenwick {
  int N;
  vector<int> tree;
  Fenwick(int _N) {
    N = _N + 10;
    tree = vector<int>(N + 10, 0);
  }
  void add(int idx, int value) {
    idx += 1;
    for (int i = idx; i <= N; i += (i & -i)) {
      tree[i] += value;
    }
  }
  int Sum(int idx) {
    idx += 1;
    int ans = 0;
    for (int i = idx; i >= 1; i -= (i & -i)) {
      ans += tree[i];
    }
    return ans;
  }
};
int main() {
  int N;
  scanf("%d", &N);
  query.resize(N + 1);
  for (int i = 1, a, t, x; i <= N; i++) {
    scanf("%d%d%d", &a, &t, &x);
    query[i] = {i, a, t, x, 0};
    xset.push_back(x);
  }
  sort(xset.begin(), xset.end());
  xset.erase(unique(xset.begin(), xset.end()), xset.end());
  for (int i = 0; i < xset.size(); i++) {
    xmap[xset[i]] = i;
  }
  int xsize = (int)xset.size();
  house.resize(xsize + 5);
  for (int i = 1; i <= N; i++) {
    int x = query[i].x;
    int idx = xmap[x];
    house[idx].push_back(query[i]);
  }
  for (int i = 0; i < house.size(); i++) {
    if (house[i].size() <= 0) continue;
    tset.clear();
    tmap.clear();
    for (int j = 0; j < house[i].size(); j++) {
      Query nowq = house[i][j];
      tset.push_back(nowq.t);
    }
    sort(tset.begin(), tset.end());
    tset.erase(unique(tset.begin(), tset.end()), tset.end());
    for (int j = 0; j < tset.size(); j++) {
      tmap[tset[j]] = j;
    }
    Fenwick fenwick((int)tset.size() + 5);
    for (int j = 0; j < house[i].size(); j++) {
      Query nowq = house[i][j];
      int idx = tmap[nowq.t];
      if (nowq.a == 1) {
        fenwick.add(idx, 1);
      } else if (nowq.a == 2) {
        fenwick.add(idx, -1);
      } else {
        query[nowq.i].ans = fenwick.Sum(idx);
      }
    }
  }
  for (int i = 1; i <= N; i++) {
    if (query[i].a == 3) {
      printf("%d\n", query[i].ans);
    }
  }
  return 0;
}

