const int N = 1e6 + 100;
int n, fa[N], sz[N], vis[N];
int head[N], ce;
struct Nd {
  int val, id;
  bool operator<(const Nd& tp) const { return val < tp.val; }
} p[N];
struct edge {
  int to, nxt;
} e[N << 1];
long long Ans;
void lnk(int a, int b) { e[++ce] = (edge){b, head[a]}, head[a] = ce; }
int find(int x) {
  if (x == fa[x]) return x;
  return fa[x] = find(fa[x]);
}
void calc() {
  for (int i = 1; i <= n; ++i) fa[i] = i, vis[i] = 0, sz[i] = 1;
  for (int j = 1; j <= n; ++j) {
    int u = p[j].id;
    long long tmp = 1;
    vector<long long> vec;
    for (int i = head[u]; i; i = e[i].nxt) {
      int v = e[i].to;
      v = find(v);
      if (vis[v]) sz[u] += sz[v], fa[v] = u, vec.push_back(sz[v]);
    }
    vis[u] = 1;
    for (int i = 0, tp = 0; i < vec.size(); ++i)
      tmp += vec[i] * (sz[u] - vec[i] - tp), tp += vec[i];
    tmp *= 1ll * p[j].val, Ans += tmp;
  }
}
int main() {
  n = gi();
  for (int i = 1; i <= n; ++i) scanf("%d", &p[i].val), p[i].id = i;
  for (int i = 1; i < n; ++i) {
    int u = gi(), v = gi();
    lnk(u, v), lnk(v, u);
  }
  sort(p + 1, p + n + 1), calc();
  for (int i = 1; i <= n; ++i) p[i].val = -p[i].val;
  for (int i = 1; i < n - i + 1; ++i) swap(p[i], p[n - i + 1]);
  calc();
  printf("%lld", Ans);
  return 0;
}

