				al2.add(a[i]);
			}			
		}
		boolean yes = false;

		Collections.sort(al1);		
		for (int i = 0; i < al1.size(); i++)
			if (al1.get(i) != al2.get(i))
				yes = true;

		int[] b = new int[k];		
		for (int i = 0; i < k; i++) 
			b[i] = in.nextInt();	

