#include <bits/stdc++.h>
using namespace std;
const long long K = 1009, N = 12;
const long long INF = 1e9;
long long k, standard_dist;
char table[K][N][N];
long long dist[K][K];
bool used[N];
long long parent[N], far[N];
vector<long long> order;
void calc_distances() {
  long long n, m, w;
  cin >> n >> m >> k >> w;
  standard_dist = n * m;
  for (long long t = 1; t <= k; ++t) {
    for (long long i = 1; i <= n; ++i) {
      for (long long j = 1; j <= m; ++j) {
        cin >> table[t][i][j];
      }
    }
  }
  for (long long t1 = 1; t1 <= k; ++t1) {
    for (long long t2 = t1 + 1; t2 <= k; ++t2) {
      for (long long i = 1; i <= n; ++i) {
        for (long long j = 1; j <= m; ++j) {
          if (table[t1][i][j] != table[t2][i][j]) dist[t1][t2]++;
        }
      }
      dist[t1][t2] *= w;
      dist[t2][t1] = dist[t1][t2];
    }
  }
}
void dijkstra() {
  for (long long i = 1; i <= k; ++i) dist[0][i] = standard_dist;
  far[0] = standard_dist;
  for (long long i = 1; i <= k; ++i) {
    far[i] = INF;
    parent[i] = 0;
  }
  for (long long it = 0; it <= k; ++it) {
    long long v = -1;
    for (long long j = 0; j <= k; ++j) {
      if (!used[j] && (v == -1 || far[j] < far[v])) v = j;
    }
    used[v] = true;
    order.push_back(v);
    for (long long j = 0; j <= k; ++j) {
      if (!used[j] && far[j] > dist[v][j]) {
        far[j] = dist[v][j];
        parent[j] = v;
      }
    }
  }
}
int main() {
  ios::sync_with_stdio(NULL);
  cin.tie(NULL);
  calc_distances();
  dijkstra();
  long long ans = 0;
  for (long long i = 1; i <= k; ++i) ans += far[i];
  cout << ans << '\n';
  for (long long to : order) {
    if (to == 0) continue;
    cout << to << ' ' << parent[to] << '\n';
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define F first
