typedef pair<int,int> P;
typedef pair<P,P> P2;
typedef pair<int,P2> PP;
bool check(int n,int m,int x,int y){return x>=0&&x<n&&y>=0&&y<m;}
int d[55][55][1<<10][2],dx[4]={-1,0,1,0},dy[4]={0,-1,0,1};

int main() {
  int n,m;
  cin >> m >> n;
  string s[n];
  for(int i=0; i<n; i++) cin >> s[i];
  int N;
  cin >> N;
  string t[N][n];
  for(int i=0;i<N;i++)for(int j=0;j<n;j++)cin >> t[i][j];
  for(int i=0;i<n;i++)for(int j=0;j<m;j++)for(int k=0;k<(1<<N);k++)for(int l=0;l<2;l++) d[i][j][k][l]=1<<29;
  priority_queue<PP,vector<PP>,greater<PP> > que;
  for(int i=0; i<n; i++) {
    for(int j=0; j<m; j++) {
      if(s[i][j]=='%') {
        d[i][j][0][0]=0;
        que.push(PP(0,P2(P(i,j),P(0,0))));
      }
    }
  }
  map<char,int> ma;
  ma['_']=0;ma['^']=1;ma['%']=0;ma['&']=0;
  for(int i=0; i<N; i++) {
    ma[(char)('a'+i)]=0;
    ma[(char)('A'+i)]=1;
  }
  while(!que.empty()) {
    PP p=que.top();que.pop();
    int xx=p.S.F.F,yy=p.S.F.S,tt=p.S.S.F,k=p.S.S.S,cc=p.F;
    if(s[xx][yy]=='&') {
      cout << cc << endl;
      return 0;
    }
    if(d[xx][yy][tt][k]>cc) continue;
    for(int i=0; i<4; i++) {
      int x=xx+dx[i],y=yy+dy[i];
      if(!check(n,m,x,y)||s[x][y]=='#') continue;
      int c=0;
      for(int j=0; j<N; j++) {
        if((tt&(1<<j))&&t[j][x][y]=='*') c++;
      }
      if(ma.count(s[x][y])&&(ma[s[x][y]]^(c%2))!=k) continue;
      if(d[x][y][tt][k]>d[xx][yy][tt][k]+1) {
        d[x][y][tt][k]=d[xx][yy][tt][k]+1;
        que.push(PP(d[x][y][tt][k],P2(P(x,y),P(tt,k))));
      }
    }
    if(isalpha(s[xx][yy])) {
      int r=islower(s[xx][yy])?(s[xx][yy]-'a'):(s[xx][yy]-'A');
      int f=t[r][xx][yy]=='*';
      if(d[xx][yy][tt^(1<<r)][k^f]>d[xx][yy][tt][k]+1) {
        d[xx][yy][tt^(1<<r)][k^f]=d[xx][yy][tt][k]+1;
        que.push(PP(d[xx][yy][tt^(1<<r)][k^f],P2(P(xx,yy),P(tt^(1<<r),k^f))));
      }
    }
    if(s[xx][yy]=='|') {
      if(d[xx][yy][tt][k^1]>d[xx][yy][tt][k]+1) {
        d[xx][yy][tt][k^1]=d[xx][yy][tt][k]+1;
        que.push(PP(d[xx][yy][tt][k^1],P2(P(xx,yy),P(tt,k^1))));
      }
    }
  }
  cout << -1 << endl;
  return 0;
}

