		rep(i, n){cin >> h[i] >> w[i];sz[i] = 0;rep(j, h[i]){	cin >> pc[i][j];
		rep(k, w[i]) if(pc[i][j][k] == '#') sz[i]++;}
			int s = i;rep(j, 3){
				int t = s + n;

				h[t] = w[s];
				w[t] = h[s];
				sz[t] = sz[s];

				rep(y, h[s]) rep(x, w[s])
