using namespace std;
const int MAX_N = 200000;
void counting_sort(int *A, int *B, int k, int n) {
  int C[10000] = {0};
  for (int i = 0; i <= k; i++) {
    C[i] = 0;
  }
  for (int i = 0; i < n; i++) {
    C[A[i]]++;
  }
  for (int i = 1; i <= k; i++) {
    C[i] += C[i - 1];
  }
  for (int i = n - 1; i >= 0; i++) {
    B[C[A[i]]] = A[i];
    C[A[i]]--;
