	class UnionFind{
		int[] tree;
		public UnionFind(int n){
			tree = new int[n];
			for(int i = 0; i < n; i++){
				tree[i] = -1;
			}
		}

		public int root(int x){
			if(tree[x] < 0) return x;
			else return tree[x] = root(tree[x]);
		}

		public boolean find(int x, int y){
			return root(x) == root(y);
		}

		public int union(int x, int y){
			x = root(x);
			y = root(y);
			if(x != y){
				if(tree[x] < tree[y]){
					tree[y] += tree[x];
					tree[x] = y;
					return -tree[y];
				}else{
					tree[x] += tree[y];
					tree[y] = x;
					return -tree[x];
				}
			}
			return -tree[x];
		}

		public int size(int x){
			return -tree[root(x)];
		}
	}

