long long count() {
  fill(dp, dp + (1 << n), 0);
  dp[0] = 1;
  for (int mask = 0; mask < (1 << n); ++mask) {
    if (dp[mask] == 0) continue;
    int cnt = 0, tmp = mask;
    while (tmp > 0) {
      if (tmp & 1 == 1) cnt++;
      tmp /= 2;
    }
    for (int i = 0; i < n; i++)
      if ((pref[i] == -1 || pref[i] == n - cnt - 1) &&
          ((ls[i] & mask) == ls[i]) && ((mask & (1 << i)) == 0))
        dp[mask | (1 << i)] += dp[mask];
  }
  return dp[(1 << n) - 1];
}
