#include <bits/stdc++.h>
using namespace std;
const int MAXH = 31;
const int MAXW = 31;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};
int H, W;
char G[MAXH][MAXW];
int vis[MAXH][MAXW];
int ans;
void show(int x, int y) {
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      if (i == y && j == x)
        cout << '*';
      else
        cout << G[i][j];
    }
    cout << endl;
  }
}
void dfs(int x, int y, int c) {
  if (c >= ans) return;
  if (vis[y][x]) return;
  ++vis[y][x];
  for (int i = 0; i < 4; ++i) {
    const int rx = x + dx[(i + 2) % 4];
    const int ry = y + dy[(i + 2) % 4];
    bool wall = false;
    if (G[ry][rx] == '^') continue;
    if (vis[ry][rx]) continue;
    if (G[ry][rx] == '_') {
      wall = true;
      G[ry][rx] = '#';
    }
    int nc = c + wall;
    int nx = x;
    int ny = y;
    int px = -1;
    int py = -1;
    while (1) {
      px = nx;
      py = ny;
      nx += dx[i];
      ny += dy[i];
      if (G[py][px] == '>') {
        ans = min(ans, nc);
        break;
      }
      if (G[py][px] == '^') break;
      if (G[py][px] == '#') break;
      if (G[ny][nx] == '#') {
        dfs(px, py, nc);
      } else if (G[ny][nx] == '_' && !vis[ny][nx]) {
        G[ny][nx] = '#';
        dfs(px, py, nc + 1);
        G[ny][nx] = '_';
      }
      ++vis[py][px];
    }
    while (1) {
      if (x == px && y == py) break;
      px -= dx[i];
      py -= dy[i];
      --vis[py][px];
    }
    if (wall) G[ry][rx] = '_';
  }
  --vis[y][x];
}
int main() {
  int Tc;
  cin >> Tc;
  for (int tc = 0; tc < Tc; ++tc) {
    cin >> H >> W;
    int x, y;
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        cin >> G[i][j];
        if (G[i][j] == 'A') {
          G[i][j] = '_';
          x = j;
          y = i;
        }
      }
    }
    ans = 11;
    fill(vis[0], vis[MAXH], 0);
    dfs(x, y, 0);
    cout << ans << endl;
  }
  return 0;
}

