#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int cocoon[5][5];
bool used[10], sameRev[10];

int solve(vector<string>& slit, int cnt)
{
	int ans = 0;

	if (cnt < 5) {
		for (unsigned int i = 0; i < slit.size(); ++i) {
			if (used[i])
				continue;

			used[i] = true;
			for (int j = 0; j < 5; ++j)
				cocoon[cnt][j] += (slit[i][j] - '0');
			ans += solve(slit, cnt+1);
			for (int j = 0; j < 5; ++j)
				cocoon[cnt][j] -= (slit[i][j] - '0');

			if (!sameRev[i]) {
				for (int j = 0; j < 5; ++j)
					cocoon[cnt][j] += (slit[i][5-j-1] - '0');
				ans += solve(slit, cnt+1);
				for (int j = 0; j < 5; ++j)
					cocoon[cnt][j] -= (slit[i][5-j-1] - '0');
			}
			used[i] = false;
		}
	} else {
		for (unsigned int i = 0; i < slit.size(); ++i) {
			if (used[i])
				continue;

			used[i] = true;

			bool straight = true;
			for (int j = 0; j < 5; ++j) {
				cocoon[j][cnt-5] += (slit[i][j] - '0');
				if (cocoon[j][cnt-5] != 1)
					straight = false;
			}

			if (straight) {
				if (cnt == 9) {
					bool valid = true;
					for (int y = 0; y < 5 && valid; ++y) {
						for (int x = 0; x < 5 && valid; ++x) {
							if (cocoon[y][x] != 1)
								valid = false;
						}
					}
					if (valid)
						++ans;
				} else {
					ans += solve(slit, cnt+1);
				}
			}
			for (int j = 0; j < 5; ++j)
				cocoon[j][cnt-5] -= (slit[i][j] - '0');


			if (!sameRev[i]) {
				bool rev = true;
				for (int j = 0; j < 5; ++j) {
					cocoon[j][cnt-5] += (slit[i][5-j-1] - '0');
					if (cocoon[j][cnt-5] != 1)
						rev = false;
				}

				if (rev) {
					if (cnt == 9) {
						bool valid = true;
						for (int y = 0; y < 5 && valid; ++y) {
							for (int x = 0; x < 5 && valid; ++x) {
								if (cocoon[y][x] != 1)
									valid = false;
							}
						}
						if (valid)
							++ans;
					} else {
						ans += solve(slit, cnt+1);
					}
				}
				for (int j = 0; j < 5; ++j)
					cocoon[j][cnt-5] -= (slit[i][5-j-1] - '0');
			}
			used[i] = false;
		}
	}
	return ans;
}

