long long calc(int x) {
  ar.clear();
  ar.emplace_back(1);
  int res = n - 1;
  long long ret = 1;
  for (int i = 1; res; i++) {
    ar.emplace_back(((res) > (ar[i - 1] * x) ? (ar[i - 1] * x) : (res)));
    res -= ((res) > (ar[i - 1] * x) ? (ar[i - 1] * x) : (res));
    ret += ar[i] * (i + 1);
  }
  return ret;
}
void Build(int x, long long k) {
  long long ret = calc(x);
  int lower_bound = ar.size() - 1;
  while (k) {
    while (ar[lower_bound] == 1) --lower_bound;
    if (ar.size() - lower_bound <= k) {
      k -= ar.size() - lower_bound;
      --ar[lower_bound];
      ar.emplace_back(1);
    } else {
      --ar[lower_bound];
      ++ar[k + lower_bound];
      break;
    }
  }
  int cur_step = 1, cur_stage = 1;
  depth[1] = 1;
  memset(first_one, 0x3f, sizeof(first_one));
  for (int i = 2; i <= n; i++) {
    if (son[cur_step] >= x || !ar[cur_stage]) {
      if (!ar[cur_stage]) {
        cur_stage++;
        cur_step = first_one[cur_stage];
      } else
        cur_step++;
    }
    fa[i] = cur_step;
    depth[i] = depth[fa[i]] + 1;
    UpdateMin(first_one[depth[i]], i);
    son[cur_step]++;
    --ar[cur_stage];
  }
}
