const int MAXN = 100 * 1000 + 17, MAXM = 17, SQ = 350;
int n, m, q;
pair<int, int> nxt[MAXN][MAXM];
bool mark[MAXN][MAXM];
char a[MAXN][MAXM];
vector<pair<int, int> > path;
int gp(int x) { return x / SQ; }
bool isok(int x, int y) { return 0 < x && x <= n && 0 < y && y <= m; }
void dfs(int x, int y, int gr) {
  mark[x][y] = true;
  pair<int, int> nx;
  if (a[x][y] == '^')
    nx = {x - 1, y};
  else if (a[x][y] == '<')
    nx = {x, y - 1};
  else
    nx = {x, y + 1};
  if (!isok(nx.first, nx.second)) {
    nxt[x][y] = nx;
    return;
  }
  if (gp(nx.first) != gr) {
    nxt[x][y] = nx;
    return;
  }
  if (mark[nx.first][nx.second]) {
    if (nxt[nx.first][nx.second] == pair<int, int>(0, 0))
      nxt[x][y] = {-1, -1};
    else
      nxt[x][y] = nxt[nx.first][nx.second];
    return;
  }
  dfs(nx.first, nx.second, gr);
  nxt[x][y] = nxt[nx.first][nx.second];
}
pair<int, int> get(int x, int y) {
  if (nxt[x][y].first == -1) return {-1, -1};
  path.push_back({x, y});
  mark[x][y] = true;
  if (!isok(x, y)) return {x, y};
  if (mark[nxt[x][y].first][nxt[x][y].second]) return {-1, -1};
  return get(nxt[x][y].first, nxt[x][y].second);
}
