  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++)
      if (!mark[i][j]) dfs(i, j, gp(i));
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) mark[i][j] = false;
  for (int i = 1; i <= q; i++) {
