        for (int k = 1; k <= m; k++) nxt[j][k] = {0, 0};
      for (int j = max(1, gp(x) * SQ); j < min(n + 1, (gp(x) + 1) * SQ); j++)
        for (int k = 1; k <= m; k++)
          if (!mark[j][k]) dfs(j, k, gp(j));
      for (int j = max(1, gp(x) * SQ); j < min(n + 1, (gp(x) + 1) * SQ); j++)
        for (int k = 1; k <= m; k++) mark[j][k] = false;
