long long int gcd(long long int a, long long int b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}
long long int LCM(long long int a, long long int b) {
  if (a >= 10000000000007LL || b >= 10000000000007LL) return 10000000000007LL;
  long long int g = gcd(max(a, b), min(a, b));
  double x = (double)a * b / g;
  if (x > 10000000000007LL) return 10000000000007LL;
  return a * b / g;
}
void dfs(long long int cur, long long int par) {
  long long int childs, l;
  DP[cur] = 1;
  for (int i = 0; i < (int)G[cur].size(); i++) {
    if (G[cur][i] != par) dfs(G[cur][i], cur);
  }
  childs = (int)G[cur].size();
  if (cur != par) childs--;
  if (childs == 0) return;
  l = 1;
  for (int i = 0; i < (int)G[cur].size(); i++) {
    if (G[cur][i] != par) {
      l = LCM(l, DP[G[cur][i]]);
    }
  }
  if (l >= 10000000000007LL)
    DP[cur] = 10000000000007LL;
  else
    DP[cur] = childs * l;
}
bool chk(long long int cur, long long int par, long long int val) {
  bool flag = true;
  long long int childs;
  childs = (int)G[cur].size();
  if (cur != par) childs--;
  if (childs == 0) {
    if (Apples[cur] >= val) return true;
    return false;
  }
  for (int i = 0; i < (int)G[cur].size(); i++) {
    if (G[cur][i] != par) {
      flag = flag && chk(G[cur][i], cur, val / childs);
    }
  }
  return flag;
}
