long long area(const pair<int, int> &a, const pair<int, int> &b,
               const pair<int, int> &c) {
  return (long long)a.first * (b.second - c.second) +
         (long long)b.first * (c.second - a.second) +
         (long long)c.first * (a.second - b.second);
}
long long dist(const pair<int, int> &a, const pair<int, int> &b) {
  return (long long)(a.first - b.first) * (a.first - b.first) +
         (long long)(a.second - b.second) * (a.second - b.second);
}
bool cmp(const pair<int, int> &a, const pair<int, int> &b) {
  if (area(a, c[1], b) == 0) return dist(a, c[1]) < dist(b, c[1]);
  return area(a, c[1], b) < 0;
}
void gethull(vector<long long> &p, int l) {
  for (int i = 2; i <= l; i++)
    if (c[i].second < c[1].second ||
        (c[i].second == c[1].second && c[i].first < c[1].first))
      swap(c[1], c[i]);
  sort(c + 2, c + l + 1, cmp);
  top = 0;
  stk[++top] = c[1];
  stk[++top] = c[2];
  for (int i = 3; i <= l; i++) {
    while (top >= 2 && area(stk[top - 1], stk[top], c[i]) <= 0) top--;
    stk[++top] = c[i];
  }
  for (int i = 1; i <= top; i++) {
    p.push_back(dist(stk[i], stk[i % top + 1]));
    p.push_back(dist(stk[i % top + 1], stk[(i + 1) % top + 1]));
    p.push_back(dist(stk[i], stk[(i + 1) % top + 1]));
  }
}
long long getHash(int l, int r) {
  return ((H[r] - H[l - 1] * MUL[r - l + 1]) % MOD + MOD) % MOD;
}
bool ok() {
  long long HH = 0;
  for (int i = 1; i <= ret1.size(); i++) HH = (HH * MUL[1] + ret1[i - 1]) % MOD;
  for (int i = 1; i <= ret2.size(); i++)
    H[i] = (H[i - 1] * MUL[1] + ret2[i - 1]) % MOD;
  for (int i = 1; i <= ret2.size(); i++) {
    long long HH_ =
        (getHash(i, ret2.size()) * MUL[i - 1] + getHash(1, i - 1)) % MOD;
    if (HH_ == HH) return true;
  }
  return false;
}
int main() {
