  cin >> n >> m;
  for (int i = 1; i <= n; i++) cin >> c[i].first >> c[i].second;
  gethull(ret1, n);
  for (int i = 1; i <= m; i++) cin >> c[i].first >> c[i].second;
  gethull(ret2, m);
  if (ret1.size() != ret2.size()) {
    cout << "NO" << endl;
    return 0;
  }
  MUL[0] = 1;
  for (int i = 0; i < 4; i++) {
    MUL[1] = mul[i];
    MOD = prime[i];
    for (int j = 2; j <= ret1.size(); j++) MUL[j] = MUL[j - 1] * MUL[1] % MOD;
    if (!ok()) {
