int lowbit(int x) { return x & (-x); }
void Add(int Pos, int Num, int Tree[]) {
  for (int i = Pos; i <= N; i += lowbit(i)) {
    Tree[i] += Num;
  }
}
int Sum(int Pos, int Tree[]) {
  int sum = 0;
  for (int i = Pos; i > 0; i -= lowbit(i)) {
    sum += Tree[i];
  }
  return sum;
}
