  L[u] = ++idx;
  Depth[u] = depth;
  for (int i = Edge[u].size() - 1; i >= 0; i--) {
    if (f != Edge[u][i]) {
      DFS(Edge[u][i], u, !depth);
    }
  }
  R[u] = idx;
}
