const int N = 1010, p = 1e9 + 7;
int T, ans1, ans2;
int inc(int x, int y) {
  x += y;
  return x >= p ? x - p : x;
}
struct seq {
  unsigned long long f[N];
  int cnt, ans1, ans2;
  void init(int start) {
    for (cnt = start + 1; f[cnt - 1] + f[cnt - 2] <= 1e18; cnt++)
      f[cnt] = f[cnt - 1] + f[cnt - 2];
    cnt--;
    for (int i = cnt + 1; i < N; i++) f[i] = 1e18 + 1;
  }
  inline int rank(register unsigned long long x) {
    register int l = 1, r = cnt, mid;
    while (l < r) {
      mid = (l + r) >> 1;
      if (f[mid + 1] <= x)
        l = mid + 1;
      else
        r = mid;
    }
    return l;
  }
  inline void calc(register unsigned long long x,
                   register unsigned long long y) {
    register int a = rank(x);
    if (y < f[a + 1]) {
      ans1 = --a;
      ans2 = ((y - f[a - 1]) / f[a] + (x - f[a - 1]) / f[a]) % p;
    } else {
      ans1 = a;
      ans2 = (y - f[a - 1]) / f[a] % p;
    }
  }
} A[N];
unsigned long long n, m, fib[N];
int times[N][N], Max[N][N], cnt[N][N];
void init_times() {
  for (int i = 1; i < N; i++)
    for (int j = 1; j < N; j++) {
      int x = i, y = j;
      if (x < y) swap(x, y);
      times[i][j] = times[y][x % y] + 1;
      Max[i][j] = max(times[i][j], max(Max[i - 1][j], Max[i][j - 1]));
      if (Max[i][j] == times[i][j]) cnt[i][j]++;
      if (Max[i][j] == Max[i - 1][j]) cnt[i][j] += cnt[i - 1][j];
      if (Max[i][j] == Max[i][j - 1]) cnt[i][j] += cnt[i][j - 1];
      if (Max[i][j] == Max[i - 1][j - 1]) cnt[i][j] -= cnt[i - 1][j - 1];
    }
}
