using namespace std;
struct custom_hash {
  static uint64_t splitmix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
    x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
    return x ^ (x >> 31);
  }
  size_t operator()(uint64_t x) const {
    static const uint64_t FIXED_RANDOM =
        chrono::steady_clock::now().time_since_epoch().count();
    return splitmix64(x + FIXED_RANDOM);
  }
};
class TaskF {
  int n, k;
  vector<unordered_set<int, custom_hash>> l, g;

 public:
  TaskF(int n, int k) {
    this->n = n;
    this->k = k;
    l.resize(n);
    g.resize(n);
    for (int i = 1; i < n; i++) {
      int u, v;
      cin >> u >> v;
      u--, v--;
      g[u].insert(v);
      g[v].insert(u);
    }
  }
  void solve() {
    for (int u = 0; u < n; u++) {
      if (g[u].size() == 1) {
        for (int v : g[u]) {
          l[v].insert(u);
        }
      }
    }
    set<pair<int, int>, greater<pair<int, int>>> pq;
    for (int u = 0; u < n; u++) {
      pq.insert(make_pair(l[u].size(), u));
    }
    int res = 0;
    while (!pq.empty()) {
      auto x = *pq.begin();
      pq.erase(pq.begin());
      if (x.first < k) {
        break;
      }
      res++;
      int u = x.second;
      for (int i = 0; i < k; i++) {
        int v = *l[u].begin();
        l[u].erase(v);
        pq.erase(make_pair(l[v].size(), v));
        l[v].erase(u);
        pq.insert(make_pair(l[v].size(), v));
        g[u].erase(v);
        g[v].erase(u);
      }
      pq.insert(make_pair(l[u].size(), u));
      if (g[u].size() == 1) {
        for (int v : g[u]) {
          pq.erase(make_pair(l[v].size(), v));
          l[v].insert(u);
          pq.insert(make_pair(l[v].size(), v));
        }
      }
    }
    cout << res << '\n';
  }
};
