#include <bits/stdc++.h>
const int charCount = 'z' - 'a' + 1;
struct node {
  long long hash;
  node *next[charCount] = {};
  node(long long hash) : hash(hash) {}
  ~node() {
    for (int i = 0; i < charCount; i++) {
      if (next[i]) {
        delete next[i];
      }
    }
  }
  node *traverse(int pos) {
    if (!next[pos]) {
      next[pos] = new node(hash + (1 << pos));
    }
    return next[pos];
  }
};
int w, h;
char map[255][255];
int currCount[255][charCount];
int currOdd[255];
node *currPath[255];
node *tree = 0;
template <class RandomAccessIterator>
std::vector<int> manacher(RandomAccessIterator first, RandomAccessIterator last,
                          bool even) {
  int n = last - first;
  std::vector<int> result(n);
  int l = 0, r = -1;
  for (int i = 0; i < n; i++) {
    int dist = i > r ? 1 - even : std::min(result[l + r - i + even], r - i + 1);
    while (i - dist - even >= 0 && i + dist < n &&
           first[i - dist - even] == first[i + dist]) {
      dist++;
    }
    result[i] = dist--;
    if (i + dist > r) {
      l = i - dist - even;
      r = i + dist;
    }
  }
  return result;
}
int main() {
  scanf("%d %d", &h, &w);
  for (int y = 0; y < h; y++) {
    scanf("%s", map[y]);
  }
  long long ans = 0;
  for (int x1 = 0; x1 < w; x1++) {
    memset(currCount, 0, sizeof(currCount));
    memset(currOdd, 0, sizeof(currOdd));
    tree = new node(0);
    for (int y = 0; y < h; y++) currPath[y] = tree;
    for (int x2 = x1; x2 < w; x2++) {
      std::vector<long long> nodes;
      for (int y = 0; y < h; y++) {
        int pos = map[y][x2] - 'a';
        currCount[y][pos]++;
        currOdd[y] += currCount[y][pos] % 2 == 0 ? -1 : 1;
        currPath[y] = currPath[y]->traverse(pos);
        nodes.push_back(currPath[y]->hash);
      }
      std::vector<int> distancesOdd =
          manacher(nodes.begin(), nodes.end(), false);
      std::vector<int> distancesEven =
          manacher(nodes.begin(), nodes.end(), true);
      int lastFail = -1;
      for (int y = 0; y < h; y++) {
        if (currOdd[y] > 1) {
          lastFail = y;
        }
        ans += std::min(y - lastFail, distancesOdd[y]);
        ans += std::min(y - lastFail, distancesEven[y]);
      }
    }
    delete tree;
  }
  printf("%lld\n", ans);
  return 0;
}

