struct treap;
using treap_ptr = treap*;

struct treap {
  treap(int x_, lli v_) : l(0), r(0), heap(rand()), x(x_), value(v_), sum(v_), size(1){ }
  treap_ptr l, r;
  int heap;

  int x;
  lli value;
  lli sum;

  int size;

  static int get_size(treap_ptr a){ return a?a->size:0; }
  static lli get_sum(treap_ptr a){ return a?a->sum:0; }

  static void update(treap_ptr a){
    if(a){
      a->size = 1;
      if(a->l) a->size += a->l->size;
      if(a->r) a->size += a->r->size;
      a->sum = a->value;
      if(a->l) a->sum += a->l->sum;
      if(a->r) a->sum += a->r->sum;
    }
  }

  static treap_ptr merge(treap_ptr a, treap_ptr b){
    if(a == 0) return b;
    if(b == 0) return a;
    if(a->heap < b->heap){
      a->r = merge(a->r, b);
      update(a);
      return a;
    }else{
      b->l = merge(a, b->l);
      update(b);
      return b;
    }
  }

  static tpl<treap_ptr, treap_ptr> split_key(treap_ptr a, int x){
    if(a == 0) return mt(nullptr, nullptr);
    if(x <= a->x){
      auto p = split_key(a->l, x);
      a->l = p.y();
      update(a);
      return mt(p.x(), a);
    }else{
      auto p = split_key(a->r, x);
      a->r = p.x();
      update(a);
      return mt(a, p.y());
    }
  }

  static void queryL(treap_ptr a, int l, lli& v, int &c){
    if(!a) return;
    if(a->x >= l) {
      v+=a->value+get_sum(a->r);
      c+=1+get_size(a->r);
      queryL(a->l,l,v,c);
    }else{
      queryL(a->r,l,v,c);
    }
  }

  static void queryR(treap_ptr a, int r, lli& v, int &c){
    if(!a) return;
    if(a->x <= r) {
      v+=a->value+get_sum(a->l);
      c+=1+get_size(a->l);
      queryR(a->r,r,v,c);
    }else{
      queryR(a->l,r,v,c);
    }
  }

  static void query(treap_ptr a, int l, int r, lli& v, int &c){
    if(!a) return;
    if(a->x < l) query(a->r,l,r,v,c);
    else if(a->x > r) query(a->l,l,r,v,c);
    else {
      v += a->value;
      c++;
      queryL(a->l,l,v,c);
      queryR(a->r,r,v,c);
    }
  }

  static tpl<treap_ptr, treap_ptr> split_pos(treap_ptr a, int i){
    if(a == 0) return mt(nullptr, nullptr);
    if(i <= get_size(a->l)){
      auto p = split_pos(a->l, i);
      a->l = p.y();
      update(a);
      return mt(p.x(), a);
    }else{
      auto p = split_pos(a->r, i - get_size(a->l) - 1);
      a->r = p.x();
      update(a);
      return mt(a, p.y());
    }
  }

  static treap_ptr insert_key(treap_ptr a, int x, lli v){
    auto p = split_key(a, x);
    return merge(merge(p.x(), new treap(x,v)), p.y());
  }

  static void treap_val(treap* a, vi& b) {
    if(!a) return;
    assert(a!=a->l);
    assert(a!=a->r);
    treap_val(a->l,b);
    b.pb(a->x);
    treap_val(a->r,b);
  }
  static vi treap_val_(treap* a) {
    vi b;
    treap_val(a,b);
    return b;
  }

  static treap_ptr delete_key(treap_ptr a, int x){
    if(a->x == x) {
      auto b = merge(a->l,a->r);
      // delete a;
      return b;
    }else if(x <= a->x) {
      a->l = delete_key(a->l,x);
      update(a);
      return a;
    }else{
      a->r = delete_key(a->r,x);
      update(a);
      return a;
    }
  }


};

