struct rmq {
  static int ilog2(int x){ return 31 - __builtin_clz(x); }
  rmq(){
    FOR(i,LN+1) FOR(j,N+N) A[i][j]=1<<30;
  }
  int n;
  int A[LN+1][N+N];

  inline void build(){
    FOR(a, LN+2) if(a) {
      int sa=1<<(a-1);
      FOR(i, n-(1<<a)) A[a][i] = min(A[a-1][i], A[a-1][i+sa]);
    }
  }

  inline int query(int x1, int x2) {
    int dx = x2-x1+1;
    int sx = ilog2(dx);
    int ax = 1<<sx;
    int v = A[sx][x1];
    v = min(v,A[sx][x2+1-ax]);
    return v;
  };

};

