int n, m, k, p;
vector<Pii> e[1000];
vector<Pii> st;

vector<int> dij(int v){
	vector<int> ct(n,0x3f3f3f3f);
	priority_queue < Pii, vector<Pii>, greater<Pii>> pq;
	ct[v] = 0;
	pq.push(Pii(0, v));
	while (!pq.empty()) {
		Pii p = pq.top(); pq.pop();
		if (p.first > ct[p.second]) continue;
		for (auto to : e[p.second]) {
			int nto = to.first;
			int nc = p.first + to.second;
			if (nc < ct[nto]) {
				ct[nto] = nc;
				pq.push(Pii(nc, nto));
			}
		}
	}
	return ct;
}

int main(){
	cin >> n >> m >> k >> p;
	p--;
	FOR(i, m){
		int x, y, w; cin >> x >> y >> w;
		x--; y--;
		e[x].push_back(Pii(y, w));
		e[y].push_back(Pii(x, w));
	}

	FOR(i, k) {
		int s, t; cin >> s >> t;
		s--; t--;
		st.emplace_back(s, t);
	}

	vector<int> use;
	for (auto kv : st) {
		use.push_back(kv.first);
		use.push_back(kv.second);
	}
	use.push_back(p);

	vector<vector<int> > tbl;

	for (auto x : use) {
		auto ct = dij(x);
		tbl.emplace_back();
		for(auto u :use) {
			tbl.back().push_back(ct[u]);
		}
	}

	static int dp[13][1 << 13];
	memset(dp, 0x3f, sizeof(dp));
	dp[sz(use)-1][1 << (sz(use) - 1)] = 0;
	for (int S = 1; S < (1 << sz(use)); S++) {
		FOR(j, sz(use)){
			if (dp[j][S] >= 0x3f3f3f3f) continue;
			FOR(k, sz(use)) {
				// j -> k
				if (k % 2 == 1) {
					if ((S & (1 << k - 1)) == 0) continue;
				}
				dp[k][S | (1 << k)] = min(dp[k][S | (1 << k)], dp[j][S] + tbl[j][k]);
			}
		}
	}

	int ans = 0x3f3f3f3f;
	FOR(i, sz(use)){
		ans = min(ans, dp[i][(1 << sz(use)) - 1]);
	}

	if (ans >= 0x3f3f3f3f) puts("Cannot deliver");
	else cout << ans << endl;
}

