const int maxn = 2e5 + 5;
int n, q, a[maxn];
int primes[maxn], tot, vis[maxn], mu[maxn];
vector<int> fac[maxn];
long long ans;
int g[maxn];
bool mark[maxn];
void Pre() {
  mu[1] = 1;
  for (int i = 2; i <= maxn - 5; i++) {
    if (!vis[i]) {
      primes[++tot] = i;
      mu[i] = -1;
    }
    for (int j = 1; j <= tot && (long long)primes[j] * i <= maxn - 5; j++) {
      vis[primes[j] * i] = 1;
      if (i % primes[j] == 0) break;
      mu[primes[j] * i] = -mu[i];
    }
  }
  for (int i = 1; i <= maxn - 5; i++)
    for (int j = 1; (long long)j * i <= maxn - 5; j++) fac[j * i].push_back(i);
}
int main() {
  read(n), read(q);
  for (int i = 1; i <= n; i++) read(a[i]);
  Pre();
  for (int i; q; q--) {
    read(i);
    if (!mark[i]) {
      mark[i] = 1;
      for (int d : fac[a[i]]) {
        ans += mu[d] * g[d];
        g[d]++;
      }
    } else {
      mark[i] = 0;
      for (int d : fac[a[i]]) {
        g[d]--;
        ans -= mu[d] * g[d];
      }
    }
    writeln(ans);
  }
  return 0;
}

