#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct edge {
  int dst, time;
};
vector<vector<edge>> g;
int n, m;
int main() {
  while (cin >> n >> m) {
    g.assign(n, {});
    for (int i = 0; i < m; i++) {
      int a, b, c;
      cin >> a >> b >> c;
      --a;
      --b;
      g[a].push_back({b, c});
    }
    priority_queue<pair<int, int>> q;
    static int min_t[100010];
    fill(min_t, min_t + n, 1.5e9);
    min_t[0] = 0;
    q.push({0, 0});
    while (q.size()) {
      int t, v;
      tie(t, v) = q.top();
      q.pop();
      t = -t;
      if (min_t[v] < t) continue;
      for (auto &e : g[v]) {
        if (e.dst == n - 1) continue;
        if (e.time < t) continue;
        if (min_t[e.dst] > t) {
          min_t[e.dst] = e.time;
          q.push({-e.time, e.dst});
        }
      }
    }
    int ans = -1;
    for (int i = 0; i < n; i++) {
      for (auto &e : g[i]) {
        if (e.dst == n - 1 && min_t[i] <= e.time) {
          ans = max(ans, e.time);
        }
      }
    }
    cout << ans << endl;
  }
}

