using namespace std;
const int N = 100500;
vector<int> a[N];
long long sum[N], mn[N], d[N];
int n, g[N];
long long lcm[N];
bool u[N];
const long long inf = 1LL << 60;
int gcd(int x, int y) { return (y ? gcd(y, x % y) : x); }
long long Lcm(int x, int y) {
  int g = gcd(x, y);
  x /= g;
  if (x * 1LL * y > inf) return inf;
  return x * 1LL * y;
}
void dfs(int x, int pr = -1) {
  u[x] = 1;
  sum[x] = g[x];
  lcm[x] = 1;
  mn[x] = 1LL << 60;
  d[x] = 0;
  for (int i = 0; i < a[x].size(); i++) {
    int j = a[x][i];
    if (!u[j]) {
      dfs(j, x);
      sum[x] += sum[j];
      mn[x] = min(mn[x], sum[j]);
    }
  }
  for (int i = 0; i < a[x].size(); i++) {
    int j = a[x][i];
    if (j != pr) {
      lcm[x] = Lcm(lcm[x], lcm[j]);
      if (lcm[x] > mn[x]) {
        sum[x] = 0;
        return;
      }
    }
  }
  if (mn[x] == (1LL << 60)) mn[x] = g[x];
  long long k = (mn[x] / lcm[x]) * 1LL * lcm[x];
  sum[x] = k * 1LL * int(a[x].size() - 1) + g[x];
  if (pr == -1) sum[x] += k;
  if (a[x].size() > 1) lcm[x] = lcm[x] * 1LL * int(a[x].size() - 1);
}
