long extgcd(long a) {
  long b = (long)1E9 + 7;
  long u, v, q, tmp;
  long x = 1;
  long y = 0;
  u = 0;
  v = 1;
  while (b > 0) {
    q = a / b;
    tmp = u;
    u = x - q * u;
    x = tmp;
    tmp = v;
    v = y - q * v;
    y = tmp;
    tmp = b;
    b = a - q * b;
    a = tmp;
  }
  x %= (long int)1E9 + 7;
  while (x < 0) x += (long)1E9 + 7;
  return x;
}
long comb(long n, long k) {
  long t = 1;
  long j = k;
  for (long i = n; i >= n - k + 1; i--) {
    t *= i;
    t *= extgcd(j);
    j--;
    t %= (long)1E9 + 7;
  }
  return t;
}
int main() {
