vector<long long> generate(vector<int> primes) {
  vector<long long> ans;
  queue<pair<long long, int>> q;
  q.emplace(1, 0);
  while (!q.empty()) {
    auto x = q.front();
    q.pop();
    ans.push_back(x.first);
    long long y = MAX / x.first;
    for (int i = x.second; i < primes.size(); i++) {
      if (primes[i] > y) break;
      q.emplace(x.first * primes[i], i);
    }
  }
  sort(ans.begin(), ans.end());
  return ans;
}
int cnt(vector<long long> &a, vector<long long> &b, long long z) {
  long long res = 0, ind = b.size() - 1;
  for (auto i : a) {
    while (ind >= 0 && (long double)b[ind] * i > z) --ind;
    if (ind < 0) break;
    res += ind + 1;
  }
  return res;
}
