long long int bigmod(long long int b, long long int a) {
  long long int g = 1;
  while (a != 0) {
    if (a % 2 == 1) g = (g * b) % 1000000007;
    a = a / 2;
    b = (b * b) % 1000000007;
  }
  return (g % 1000000007);
}
