        int t = 1;
        int m = 1;
        while (m*m < n) { m*=2; t++; }
        return t;
    }
    public void solve(InputStream in, PrintWriter out) {
        Scanner scanner = new Scanner(in);

        int m = scanner.nextInt();
        int A[] = new int[10006];
