            A[i] = scanner.nextInt();
        }

        Arrays.sort(A, 0, m);
        BigInteger sum = new BigInteger("0");

        int nextStep = 1;
        int curStep = 1;
        int times = getTimes(m);
        for (int i = m-1; i >= 0; i--) {
            if (curStep > nextStep) {
                nextStep = nextStep*4;
                times--;
            }
            sum = sum.add(new BigInteger(A[i]*times + ""));
            curStep++;
        }

        out.println(sum);
    }
}

