struct SEG {
  long long siz;
  long long s[4800010];
  void init(long long n) {
    siz = 1;
    while (siz < n) siz *= 2;
    for (long long i = 0; i < siz * 2 - 1; i++) s[i] = 0;
  }
  void updata(long long a, long long b, long long x, long long k, long long l,
              long long r) {
    if (b <= l || r <= a) return;
    if (a <= l && r <= b) {
      s[k] += x;
      return;
    }
    updata(a, b, x, 2 * k + 1, l, (l + r) / 2);
    updata(a, b, x, 2 * k + 2, (l + r) / 2, r);
  }
  long long query(long long a) {
    a += siz - 1;
    long long ret = s[a];
    while (a > 0) {
      a = (a - 1) / 2;
      ret += s[a];
    }
    return ret;
  }
} seg0, seg1;
struct SEG_ {
  long long siz;
  long long s[4800010];
  long long t[4800010];
  void init(long long n) {
    siz = 1;
    while (siz < n) siz *= 2;
    for (long long i = 0; i < siz; i++) {
      s[i + siz - 1] = INF;
      t[i + siz - 1] = 0;
    }
  }
  void updata() {
    for (long long i = siz - 1 - 1; i >= 0; i--) {
      if (s[2 * i + 1] <= s[2 * i + 2]) {
        s[i] = s[2 * i + 1];
        t[i] = t[2 * i + 1];
      } else {
        s[i] = s[2 * i + 2];
        t[i] = t[2 * i + 2];
      }
    }
  }
  pair<long long, long long> query(long long a, long long b, long long k,
                                   long long l, long long r) {
    if (b <= l || r <= a) return pair<long long, long long>(INF, 0);
    if (a <= l && r <= b) return pair<long long, long long>(s[k], t[k]);
    pair<long long, long long> vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
    pair<long long, long long> vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
    if (vl.first <= vr.first) return vl;
    return vr;
  }
} seg2;
vector<long long> G[600010];
vector<long long> vs(1200010);
long long L[600010], R[600010], D[600010];
void Euler_Tour(long long v, long long p, long long d) {
  D[v] = d;
  L[v] = vs.size();
  R[v] = vs.size();
  vs.push_back(v);
  for (long long i = 0; i < G[v].size(); i++) {
    if (G[v][i] == p) continue;
    Euler_Tour(G[v][i], v, d + 1);
    R[v] = vs.size();
    vs.push_back(v);
  }
}
long long dist(long long v) {
  return D[v] * seg0.query(L[v]) + seg1.query(L[v]);
}
int main() {
