    cnt[b[i]]++;
  }
  for (long long i = 0; i < n; i++) {
    G[i].reserve(cnt[i]);
  }
  for (long long i = 0; i < n - 1; i++) {
    G[a[i]].push_back(b[i]);
    G[b[i]].push_back(a[i]);
  }
  Euler_Tour(0, -1, 0);
  seg0.init(vs.size() + 10);
  seg1.init(vs.size() + 10);
  seg2.init(vs.size() + 10);
  for (long long i = 0; i < vs.size(); i++) {
    seg2.s[i + seg2.siz - 1] = D[vs[i]];
    seg2.t[i + seg2.siz - 1] = vs[i];
  }
  seg2.updata();
  for (long long ppp = 0; ppp < q; ppp++) {
    long long t;
    scanf("%lld", &t);
    if (t == 0) {
      long long u, v;
      scanf("%lld%lld", &u, &v);
      long long LCA =
          seg2.query(min(L[u], L[v]), max(L[u], L[v]) + 1, 0, 0, seg2.siz)
