#include<bits/stdc++.h>

#define REP(i,s,n) for(int i=s;i<n;i++)
#define rep(i,n) REP(i,0,n)
#define EPS (1e-8)
#define COUNTER_CLOCKWISE 1
#define CLOCKWISE -1 
#define ONLINE_BACK 2
#define ONLINE_FRONT -2
#define ON_SEGMENT 0
#define equals(a,b) (fabs((a)-(b)) < EPS)

using namespace std;

const int IINF = INT_MAX;

class Point{
public:
  double x,y;

  Point(double x = 0,double y = 0): x(x),y(y){}

  Point operator + (Point p){return Point(x+p.x,y+p.y);}
  Point operator - (Point p){return Point(x-p.x,y-p.y);}
  Point operator * (double a){return Point(a*x,a*y);}
  Point operator / (double a){return Point(x/a,y/a);}

  bool operator < (const Point& p) const{ return !equals(x,p.x)?x<p.x:(!equals(y,p.y)&&y<p.y); }
  bool operator == (const Point& p)const{ return fabs(x-p.x) < EPS && fabs(y-p.y) < EPS; }

};

struct Segment{
  Point p1,p2;
  Segment(Point p1 = Point(),Point p2 = Point()):p1(p1),p2(p2){}
 bool operator == (const Segment& p) const { return ( p.p1 == p1 && p.p2 == p2 ) || ( p.p1 == p2 && p.p2 == p1 ); }
  bool operator < (const Segment& s) const { return !(p1==s.p1)? p1 < s.p1 : p2 < s.p2; }
};

typedef Point Vector;
typedef Segment Line;
typedef vector<Point> Polygon;

double dot(Point a,Point b){ return a.x*b.x + a.y*b.y; }
double cross(Point a,Point b){ return a.x*b.y - a.y*b.x; }
double norm(Point a){ return a.x*a.x+a.y*a.y; }
double abs(Point a){ return sqrt(norm(a)); }

int ccw(Point p0,Point p1,Point p2){
  Point a = p1-p0;
  Point b = p2-p0;
  if(cross(a,b) > EPS)return COUNTER_CLOCKWISE;
  if(cross(a,b) < -EPS)return CLOCKWISE;
  if(dot(a,b) < -EPS)return ONLINE_BACK;
  if(norm(a) < norm(b))return ONLINE_FRONT;
  return ON_SEGMENT;
}

bool intersectLS(Line l, Line s) {
  return cross(l.p2-l.p1, s.p1-l.p1)*       // s[0] is left of l
         cross(l.p2-l.p1, s.p2-l.p1) < EPS; // s[1] is right of l
}

bool intersectSS(Line s, Line t) {
  return ccw(s.p1,s.p2,t.p1)*ccw(s.p1,s.p2,t.p2) <= 0 &&
         ccw(t.p1,t.p2,s.p1)*ccw(t.p1,t.p2,s.p2) <= 0;
}

Point crosspoint(Line l,Line m){
  double A = cross(l.p2-l.p1,m.p2-m.p1);
  double B = cross(l.p2-l.p1,l.p2-m.p1);
  if(abs(A) < EPS && abs(B) < EPS){
    vector<Point> vec;
    vec.push_back(l.p1),vec.push_back(l.p2),vec.push_back(m.p1),vec.push_back(m.p2);
    sort(vec.begin(),vec.end());
    assert(vec[1] == vec[2]); 
    return vec[1];
  }
  if(abs(A) < EPS)assert(false);
  return m.p1 + (m.p2-m.p1)*(B/A);
}

double cross3p(Point p,Point q,Point r){ return (r.x-q.x) * (p.y -q.y) - (r.y - q.y) * (p.x - q.x); }
bool collinear(Point p,Point q,Point r){ return fabs(cross3p(p,q,r)) < EPS; }
bool ccwtest(Point p,Point q,Point r){ return cross3p(p,q,r) > 0; }
bool onSegment(Point p,Point q,Point r){
  return collinear(p,q,r) && equals(sqrt(pow(p.x-r.x,2)+pow(p.y-r.y,2)) + sqrt(pow(r.x-q.x,2) + pow(r.y-q.y,2) ),sqrt(pow(p.x-q.x,2)+pow(p.y-q.y,2)) ) ;
}

double angle(Point a,Point b,Point c){
  double ux = b.x - a.x, uy = b.y - a.y;
  double vx = c.x - a.x, vy = c.y - a.y;
  return acos((ux*vx + uy*vy)/sqrt((ux*ux + uy*uy) * (vx*vx + vy*vy)));
}  

bool inPolygon(Polygon poly,Point p){
  if((int)poly.size() == 0)return false;
  rep(i,poly.size()) if(onSegment(poly[i],poly[(i+1)%poly.size()],p))return true;
  double sum = 0;
  for(int i=0; i < (int)poly.size() ;i++){
    if( equals(cross(poly[i]-p,poly[(i+1)%poly.size()]-p),0.0) ) continue; 
    if(cross3p(p,poly[i],poly[(i+1)%poly.size()]) < 0) sum -= angle(p,poly[i],poly[(i+1)%poly.size()]);
      else sum += angle(p,poly[i],poly[(i+1)%poly.size()]);
  }
  const double eps = 1e-5;
  return (fabs(sum - 2*M_PI) < eps || fabs(sum + 2*M_PI) < eps);
}  

const int MAX_V = 16 * 20+2000;
int n,bc[1<<16];
Point ps[16];
Polygon poly;
vector<Segment> segs;

bool check(int bitmask){
  int V = segs.size();
  assert( V < MAX_V );
  vector<Point> sp;
  rep(i,n) if( (bitmask>>i) & 1 ) sp.push_back(ps[i]);
  rep(i,V){
    Point mp = ( segs[i].p1 + segs[i].p2 ) / 2.0;
    bool ok = false;
    rep(j,bc[bitmask]){
      Segment seg = Segment(sp[j],mp);
      Point middle = ( seg.p1 + seg.p2 ) / 2.0;
      if( !inPolygon(poly,middle) ) continue;
      bool failed = false;
      rep(k,n) {
        if( equals(cross(seg.p1-seg.p2,poly[k]-poly[(k+1)%n]),0.0) ) continue;
        if( intersectSS(seg,Segment(poly[k],poly[(k+1)%n])) ){
          if( onSegment(poly[k],poly[(k+1)%n],seg.p1) || onSegment(poly[k],poly[(k+1)%n],seg.p2) ) continue;
          if( onSegment(seg.p1,seg.p2,poly[k]) || onSegment(seg.p1,seg.p2,poly[(k+1)%n]) ) continue;
          failed = true;
          break;
        } 
      }
      if( !failed ) { ok = true; break; }
    }
    if( !ok ) return false;
  }

  return true;
}

Point vir;
bool comp(const Point& p1,const Point& p2){ return !equals(abs(vir-p1),abs(vir-p2)) && abs(vir-p1) < abs(vir-p2); }

vector<Segment> makeGraph(){
  vector<Segment> vs;
  rep(i,n) vs.push_back(Segment(ps[i],ps[(i+1)%n]));
  vector<Segment> ret;
  rep(i,vs.size()){
    vector<Point> vp;
    vp.push_back(vs[i].p1);
    vp.push_back(vs[i].p2);
    rep(j,n) REP(k,j+1,n) {
      Segment seg = Segment(ps[j],ps[k]);
      if( equals(cross(vs[i].p1-vs[i].p2,seg.p1-seg.p2),0.0) ) {
        if( onSegment(vs[i].p1,vs[i].p2,seg.p1) ) vp.push_back(seg.p1);
        if( onSegment(vs[i].p1,vs[i].p2,seg.p2) ) vp.push_back(seg.p2);
      } else if( intersectLS(seg,vs[i]) ) vp.push_back(crosspoint(vs[i],seg));
    }
    vir = vs[i].p1;
    sort(vp.begin(),vp.end(),comp);
    vp.erase(unique(vp.begin(),vp.end()),vp.end());
    rep(j,(int)vp.size()-1) ret.push_back(Segment(vp[j],vp[j+1]));
  }
  return ret;
}

