int n;
void solveodd(vector<int> newarr) {
  vector<pair<int, int> > answer;
  int i = 0, j = newarr.size() - 1;
  int counter = 0, p = 1, q = j;
  while (i < j) {
    answer.push_back(make_pair(p, newarr[i]));
    answer.push_back(make_pair(q, newarr[j]));
    i++;
    j--;
    p += 2;
    q -= 2;
    counter += 2;
  }
  sort(answer.begin(), answer.end());
  answer.push_back(make_pair(counter++, newarr[i]));
  for (int i = 0; i < answer.size(); ++i) {
    int x = arr[answer[i].second];
    int y = arr[answer[(i + 1) % counter].second];
    ans[x] = y;
  }
}
void solveeven(vector<int> A, vector<int> B) {
  vector<int> answer;
  for (int i = 0; i < A.size(); i++) {
    answer.push_back(A[i]);
    answer.push_back(B[i]);
  }
  int counter = A.size() + B.size();
  for (int i = 0; i < answer.size(); ++i) {
    int x = arr[answer[i]];
    int y = arr[answer[(i + 1) % counter]];
    ans[x] = y;
  }
}
int main() {
