    scanf("%d", &arr[i]);
  }
  for (int i = 1; i <= n; i++) {
    if (vis[i] == 1) continue;
    int len = 0;
    int x = i;
    while (vis[x] == 0) {
      len++;
      vis[x] = 1;
      x = arr[x];
    }
    counter[len]++;
  }
  bool flag = true;
  for (int i = 2; i <= n; i += 2) {
    if (counter[i] % 2 == 1) {
      flag = false;
      break;
    }
  }
  if (flag == false) {
    printf("-1");
    return 0;
  }
  memset(vis, 0, sizeof vis);
  for (int i = 1; i <= n; i++) {
    if (vis[i] == 1) continue;
    int len = 0;
    int x = i;
    vector<int> cur;
    while (vis[x] == 0) {
      len++;
      cur.push_back(x);
      vis[x] = 1;
      x = arr[x];
    }
    adj[len].push_back(cur);
  }
  for (int i = 1; i <= n; i++) {
