/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author amalev
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            long P = 2000000011;
            int n = in.nextInt();
            int k = in.nextInt();
            long[] a = new long[n + 1];
            int unknown = 0;
            for (int i = 0; i <= n; i++) {
                String s = in.nextLine();
                if (s.equals("?")) {
                    unknown++;
                    a[i] = Integer.MAX_VALUE;
                } else {
                    a[i] = Integer.parseInt(s);
                }
            }

            boolean win = false;
            if (k == 0) {
                boolean isHuman = (n + 1 - unknown) % 2 == 1;
                if (isHuman) {
                    if (a[0] == Integer.MAX_VALUE) {
                        win = true;
                    } else {
                        win = (a[0] == 0);
                    }
                } else {
                    if (a[0] == Integer.MAX_VALUE) {
                        win = false;
                    } else {
                        win = (a[0] == 0);
                    }
                }
            } else {
                if (unknown != 0) {
                    win = (n + 1) % 2 == 0;
                } else {
                    int i = n;
                    long b = a[i];
                    i--;
                    while (i >= 0) {
                        b = (b * k + a[i]) % P;

                        i--;
                    }
                    win = (b == 0);
                }
            }
            out.println(win ? "Yes" : "No");
        }

    }

    static class FastScanner {
        final BufferedReader input;
        String[] buffer;
        int pos;
        final static Pattern SEPARATOR = Pattern.compile("\\s+");

        public FastScanner(InputStream inputStream) {
            input = new BufferedReader(new InputStreamReader(inputStream));
        }

        private String read() {
            try {
                if (buffer == null || pos >= buffer.length) {
                    buffer = SEPARATOR.split(input.readLine());
                    pos = 0;
                }
                return buffer[pos++];
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }

        public int nextInt() {
            return Integer.parseInt(read());
        }

        public String nextLine() {
            if (buffer != null && pos < buffer.length) {
                throw new RuntimeException("Buffer is not empty");
            }
            try {
                return input.readLine();
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }

    }
}

