int tim(int x, int sz) {
  int dau = 1, cuoi = sz;
  while (dau <= cuoi) {
    int giua = (dau + cuoi) >> 1;
    if (p[giua].first >= x)
      cuoi = giua - 1;
    else
      dau = giua + 1;
  }
