enum ClusterType { NONE, BASE, RAKE, COMPRESS, HARDRAKE };
template <class ClusterInfoUtil>
struct TopTree {
  using Info = typename ClusterInfoUtil::Info;
  struct Cluster {
    TopTree* belongingTree;
    ClusterType type;
    Cluster *l, *r, *m, *p;
    Info info, tmpInfo;
    int a, b;
    Cluster(TopTree* tree) : info(-1, -1), tmpInfo(-1, -1) {
      belongingTree = tree;
      Clear();
    }
    void Clear() {
      type = NONE;
      l = nullptr;
      r = nullptr;
      m = nullptr;
      p = nullptr;
      info = Info(-1, -1);
      tmpInfo = Info(-1, -1);
      a = -1;
      b = -1;
    }
    void UpdateHandles() {
      if (type == BASE) {
        belongingTree->handles[a] = this;
        belongingTree->handles[b] = this;
      } else if (type == COMPRESS) {
        belongingTree->handles[l->a] = this;
        belongingTree->handles[l->b] = this;
        belongingTree->handles[r->a] = this;
        belongingTree->handles[r->b] = this;
      }
    }
    void Update() {
      if (type == COMPRESS) {
        if (m) {
          tmpInfo = Info(l->a, l->b);
          tmpInfo.Join(l->a, l->b, m->a, m->b, m->info, l->a, l->b, l->info,
                       RAKE);
        }
        a = l->a;
        b = r->b;
        UpdateHandles();
        info = Info(a, b);
        info.Join(a, b, l->a, l->b, m ? tmpInfo : l->info, r->a, r->b, r->info,
                  COMPRESS);
      } else if (type == RAKE) {
        a = r->a;
        b = r->b;
        info = Info(a, b);
        info.Join(a, b, l->a, l->b, l->info, r->a, r->b, r->info, RAKE);
      } else if (type == HARDRAKE) {
        int la = l->a, lb = l->b;
        int ra = r->a, rb = r->b;
        if (la == ra || la == rb) swap(la, lb);
        if (lb == ra) swap(ra, rb);
        a = ra;
        b = rb;
        info = Info(a, b);
        info.Join(a, b, la, lb, l->info, ra, rb, r->info, RAKE);
      }
