const int maxn = 1<<17, rt = 1<<10;
int n, a[maxn][3];
int id(int x) {
	if(a[x][0] + 1 == a[x][1] && a[x][1] + 1 == a[x][2]) return a[x][2]/3;
	if(a[x][0] - 1 == a[x][1] && a[x][1] - 1 == a[x][2]) return -a[x][0]/3;
	return -(1<<30);
}
struct fenwick {
	int a[maxn], n;
	void init(int n) {
		this->n = n;
		memset(a, 0, sizeof a);
	}
	void add(int i) {
		for(; i <= n; i += i&-i) a[i] ^= 1;
	}
	int get(int i) {
		int r = 0;
		for(; i; i -= i&-i) r ^= a[i];
		return r;
	}
};

int count(vi a) {
	fenwick f;
	f.init(2*a.size() + 2);
	int ans = 0, t = 0;
	for(auto i : a) {
		ans ^= f.get(i)^t;
		f.add(i);
		t ^= 1;
	}
	return ans;
}

