const int MAX_N = 100000 + 3, MOD = 1e9 + 7;
struct Edge {
  Edge *next;
  int to, cost;
  Edge(Edge *next = NULL, int to = 0, int cost = 0)
      : next(next), to(to), cost(cost) {}
} pool[MAX_N * 2], *pit = pool, *first[MAX_N];
int n, d[MAX_N], a[MAX_N], b[MAX_N];
inline int modPow(long long a, int b) {
  long long res = 1;
  while (b) {
    if (b & 1) (res *= a) %= MOD;
    (a *= a) %= MOD;
    b >>= 1;
  }
  return res;
}
void dfs(int u, int fa) {
  a[u] = b[u] = 0;
  if (d[u] == 1) return;
  int t = d[u];
  for (Edge *e = first[u]; e; e = e->next)
    if (e->to != fa) {
      dfs(e->to, u);
      b[u] += e->cost + b[e->to];
      (t -= a[e->to]) %= MOD;
    } else
      b[u] += e->cost;
  int inv = modPow((t + MOD) % MOD, MOD - 2);
  a[u] = inv, b[u] = (long long)b[u] * inv % MOD;
}
