public static  class segtree {
	long[] t,  lazy;
	void update(int l, int r, long a) {update(1, 0, t.length/4-1, l, r, a);}
	long query(int l, int r) {return query(1,0,t.length/4-1,l,r);}
	public segtree(int len) {t = new long[len*4];  lazy = new long[len*4];}	

	void push(int  v) {
		lazy[v*2+1]+=lazy[v];
		t[v*2+1]+=lazy[v];
		t[v*2]+=lazy[v];
		lazy[v*2]+=lazy[v];
		lazy[v]=0;
	}

	void update(int v, int tl, int tr, int l, int r, long new_val) {
		if (l > r) return;
		if (l == tl && r == tr) {
			t[v] += new_val;
			lazy[v]+=new_val;
		}
		else {
			push(v);
			int tm = (tl+tr)/2;
			update(v*2, tl, tm, l, min(r, tm), new_val);
			update(v*2+1, tm+1,tr, max(l, tm+1),r, new_val);
			t[v] = gcd(t[v*2] , t[v*2+1]);
		}
	}

	long query(int v, int tl, int tr, int l, int r) {
		if (l > r) return 0;
		if (l <= tl && tr <= r) return t[v];
		int tm = (tl+tr)/2;
		push(v);
		return gcd(query(v*2, tl, tm, l, min(r, tm)) , query(v*2+1, tm+1, tr, max(l, tm+1), r));
	}
}


