int sortin(int a, int b) { return (a < b); }
int binsearch(int B[], int val, int n) {
  int start = 0, end = n - 1, mid = (start + end) / 2;
  while (start <= end) {
    mid = (start + end) / 2;
    if (B[mid] == val)
      return B[mid - 1];
    else if (B[mid] < val)
      start = mid + 1;
    else
      end = mid - 1;
  }
  return B[end];
}
