int n, m, h[N], x, y, p[N], d[N], c[N], t, L, R, v[M];
vector<int> a[N];
void D(int k, int f) {
  p[k] = ++x, c[k] = 1;
  for (int i = 0; i < a[k].size(); i++)
    if (a[k][i] != f) d[a[k][i]] = d[k] + 1, D(a[k][i], k), c[k] += c[a[k][i]];
}
void D(int k) {
  v[2 * k] += v[k];
  v[2 * k + 1] += v[k];
  v[k] = 0;
}
void C(int k, int l, int r) {
  if (L <= l && r <= R) {
    v[k] += x;
    return;
  }
  D(k);
  int d = (l + r) / 2;
  if (L <= d) C(2 * k, l, d);
  if (R > d) C(2 * k + 1, d + 1, r);
}
int Q(int k, int l, int r) {
  if (l == r) return v[k];
  D(k);
  int d = (l + r) / 2;
  if (x <= d) return Q(2 * k, l, d);
  return Q(2 * k + 1, d + 1, r);
}
