  }
  x = 0, D(1, 0);
  while (m-- && cin >> t >> x)
    if (t == 1 && cin >> y) {
      if (d[x] & 1) y = -y;
      L = p[x], R = L + c[x] - 1, x = y, C(1, 1, n);
    } else if (d[x] & 1)
      cout << h[p[x]] - Q(1, 1, n) << '\n';
    else
      cout << h[p[x]] + Q(1, 1, n) << '\n';
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n, m, k;
map<int, vector<pair<int, int> > > h, v;
vector<int> games, type, pos;
vector<vector<pair<int, int> > > wheres;
void getcut() {
  int a, b, c, d;
  scanf("%d%d%d%d", &a, &b, &c, &d);
  if (a == c) {
    if (b > d) swap(b, d);
    v[a].push_back(make_pair(b, d));
  } else {
    if (a > c) swap(a, c);
    h[b].push_back(make_pair(a, c));
  }
}
void build(map<int, vector<pair<int, int> > >& m, int W, int H, int t) {
  int z = 1, top = 0, k = -1;
  for (typeof(m.begin()) it = m.begin(); it != m.end(); ++it) {
    int big = 0;
    top += it->first - z;
    if (it->first - z > 0) k = z;
    z = it->first + 1;
    sort(it->second.begin(), it->second.end());
    vector<int> col;
    for (int i = 0; i < it->second.size(); ++i)
      col.push_back(it->second[i].first), col.push_back(it->second[i].second);
    col.push_back(H);
    sort(col.begin(), col.end());
    set<int> o;
    int now = 0, pp = 0, qq = 0;
    type.push_back(t);
    pos.push_back(it->first);
    vector<pair<int, int> > where;
    while (pp < col.size()) {
      int last = now;
      now = col[pp++];
      while (qq < it->second.size() && it->second[qq].first < now)
        o.insert(it->second[qq].second), ++qq;
      while (!o.empty() && *o.begin() < now) o.erase(o.begin());
      if (o.empty()) {
        big += now - last;
        where.push_back(make_pair(last, now));
      }
    }
    wheres.push_back(where);
    games.push_back(big);
  }
  if (z != W) top += W - z, k = W - 1;
  if (top & 1) {
    games.push_back(H);
    type.push_back(t);
    vector<pair<int, int> > where;
    where.push_back(make_pair(0, H));
    wheres.push_back(where);
    pos.push_back(k);
  }
}
void solve(int x) {
  int p = 0, a = x, z;
  while (a) {
    a >>= 1;
    ++p;
  }
  --p;
  for (int i = 0; i < games.size(); ++i) {
    if ((long long)games[i] & 1 << p) {
      z = i;
      break;
    }
  }
  int g = x ^ games[z], start = wheres[z][0].first, end = start;
  p = 0;
  g = games[z] - g;
  while (g) {
    if (wheres[z][p].second - wheres[z][p].first >= g) {
      end = wheres[z][p].first + g;
      g = 0;
    } else
      g -= wheres[z][p].second - wheres[z][p].first;
    ++p;
  }
  if (type[z] == 0)
    printf("%d %d %d %d\n", pos[z], start, pos[z], end);
  else
    printf("%d %d %d %d\n", start, pos[z], end, pos[z]);
}
int main() {
  scanf("%d%d%d", &n, &m, &k);
  while (k--) getcut();
  build(h, m, n, 1);
  build(v, n, m, 0);
  int x = 0;
  for (int i = 0; i < games.size(); ++i) x ^= games[i];
  if (x) {
    printf("FIRST\n");
    solve(x);
  } else
    printf("SECOND\n");
}

