#include <bits/stdc++.h>
using namespace std;
const long long N = 300005;
vector<long long> v[N];
long long w[N];
long long cnt;
long long S[N], E[N];
long long depth[N];
void dfs(long long at, long long from) {
  depth[at] = depth[from] + 1;
  S[at] = cnt;
  w[cnt++] = at;
  for (long long nxt : v[at]) {
    dfs(nxt, at);
  }
  E[at] = cnt - 1;
}
struct node {
  long long s, e;
  long long x, k;
  bool dirty;
  node *l, *r;
};
node no[1231234];
long long counter;
const long long mod = 1000000007;
void fix(long long& v) {
  v %= mod;
  v += mod;
  v %= mod;
}
void unlazy(node* x) {
  if (!x || x->dirty == 0) return;
  x->dirty = 0;
  if (!x->l) return;
  x->l->k += x->k;
  x->r->k += x->k;
  x->l->x += x->x;
  x->r->x += x->x;
  fix(x->l->x);
  fix(x->r->x);
  fix(x->l->k);
  fix(x->r->k);
  x->k = 0;
  x->x = 0;
  x->l->dirty = 1;
  x->r->dirty = 1;
}
node* build(long long s, long long e) {
  node* x = &no[counter++];
  x->s = s;
  x->e = e;
  if (s == e) return x;
  long long m = s + e;
  m /= 2;
  x->l = build(s, m);
  x->r = build(m + 1, e);
  return x;
}
void update(node* r, long long s, long long e, long long x, long long k) {
  unlazy(r);
  if (r->s == s && r->e == e) {
    r->x += x;
    r->k += k;
    r->dirty = 1;
    fix(r->x);
    fix(r->k);
    return;
  }
  long long m = r->s + r->e;
  m /= 2;
  if (e <= m)
    update(r->l, s, e, x, k);
  else if (s > m)
    update(r->r, s, e, x, k);
  else {
    update(r->l, s, m, x, k);
    update(r->r, m + 1, e, x, k);
  }
}
long long qry(node* x, long long at) {
  unlazy(x);
  if (x->s == x->e) {
    long long ans = x->x - (long long)depth[w[at]] * x->k;
    fix(ans);
    return ans;
  }
  long long m = x->s + x->e;
  m /= 2;
  if (at <= m) return qry(x->l, at);
  return qry(x->r, at);
}
int main() {
  int n;
  scanf("%d", &n);
  for (auto(i) = (0); (i) < (n - 1); (i)++) {
    int a;
    scanf("%d ", &a);
    v[a].push_back(i + 2);
  }
  dfs(1, 1);
  int q;
  auto root = build(0, n - 1);
  scanf("%d", &q);
  for (auto(i) = (0); (i) < (q); (i)++) {
    int a;
    scanf("%d", &a);
    if (a == 1) {
      long long x, v, k;
      scanf("%I64d %I64d %I64d", &v, &x, &k);
      x += depth[v] * k;
      fix(x);
      update(root, S[v], E[v], x, k);
    } else {
      scanf("%d", &a);
      printf("%d\n", (int)qry(root, S[a]));
    }
  }
  return 0;
}

