public class Main {

    private static void mark(int[] res, ArrayList<Integer> list, int value) {
        for (int index : list) {
            res[index] = value;
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner scan = new Scanner(new BufferedInputStream(System.in));
        int m = scan.nextInt();
        int[] type = new int[m];
        int[] value = new int[m];
        int[] l = new int[m];
        int[] c = new int[m];
        for (int i = 0; i < m; i++) {
            type[i] = scan.nextInt();
            if (type[i] == 1) {
                value[i] = scan.nextInt();
            } else {
                l[i] = scan.nextInt();
                c[i] = scan.nextInt();
            }
        }
        int n = scan.nextInt();
        long[] pos = new long[n];
        for (int i = 0; i < n; i++) {
            pos[i] = scan.nextLong() - 1;
        }

        long[] len = new long[m];
        len[0] = 1; // assert: type[0] == 1
        for (int i = 1; i < m; i++) {
            if (type[i] == 1) {
                len[i] = len[i - 1] + 1;
            } else {
                len[i] = len[i - 1] + 1L * l[i] * c[i];
            }
        }

        TreeMap<Long, ArrayList<Integer>> map = new TreeMap<Long, ArrayList<Integer>>();
        for (int i = 0; i < n; i++) {
            ArrayList<Integer> list = new ArrayList<Integer>();
            list.add(i);
            map.put(pos[i], list);
        }

        int[] res = new int[n];
        int index = m - 1;
        while (index > 0 && !map.isEmpty()) {
            long target = map.lastKey();
            while (index > 0 && len[index - 1] > target) {
                index--;
            }
            if (index == 0) {
                break;
            }
            ArrayList<Integer> list = map.remove(target);
            if (type[index] == 1) {
                mark(res, list, value[index]);
            } else {
                long from = (target - len[index - 1]) % l[index];
                if (!map.containsKey(from)) {
                    map.put(from, list);
                } else {
                    map.get(from).addAll(list);
                }
            }
        }
        for (ArrayList<Integer> list : map.values()) {
            mark(res, list, value[0]);
        }

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                builder.append(' ');
            }
            builder.append(Integer.toString(res[i]));
        }
        System.out.println(builder.toString());
    }
}

