#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1e5 + 3;
int n, k, kill[MAXN], sz[MAXN], par[MAXN], ans = 0;
vector<int> tree[MAXN];
vector<int> heavy[MAXN];
void predfs(int here, int dad) {
  sz[here] = 1;
  par[here] = dad;
  for (auto x : tree[here]) {
    if (x == dad) continue;
    predfs(x, here);
    sz[here] += sz[x];
  }
}
int getSz(int here, int dad) {
  sz[here] = 1;
  for (auto x : tree[here]) {
    if (x == dad || kill[x]) continue;
    getSz(x, here);
    sz[here] += sz[x];
  }
  return sz[here];
}
int getCenter(int here, int dad, int cap) {
  for (auto x : tree[here]) {
    if (x == dad || kill[x]) continue;
    if (sz[x] > cap) return getCenter(x, here, cap);
  }
  return here;
}
void preProcess() {
  predfs(1, -1);
  for (int x = 1; x <= n; x++) {
    for (auto &y : tree[x]) {
      if (par[x] == y && sz[1] - sz[x] >= k) heavy[x].push_back(y);
      if (par[x] != y && sz[y] >= k) heavy[x].push_back(y);
    }
  }
  for (int x = 1; x <= n; x++) sort(heavy[x].begin(), heavy[x].end());
}
int in(int i, int j) {
  if (heavy[i].size() == 0) return 0;
  if (heavy[i].back() < j) return 0;
  return *lower_bound(heavy[i].begin(), heavy[i].end(), j) == j;
}
void dfs(int here, int dad, int &mx) {
  if (dad != -1)
    mx = max(mx, (int)heavy[here].size() - in(here, dad));
  else
    mx = max(mx, (int)heavy[here].size());
  for (auto x : tree[here]) {
    if (kill[x] || x == dad) continue;
    dfs(x, here, mx);
  }
}
void decompose(int x) {
  int cen = getCenter(x, -1, getSz(x, -1) / 2);
  kill[cen] = 1;
  vector<int> vc;
  for (auto x : tree[cen]) {
    if (kill[x]) continue;
    int temp = 0;
    dfs(x, cen, temp);
    ans = max(ans, temp + (int)heavy[cen].size() - in(cen, x));
    vc.push_back(temp - in(cen, x));
  }
  sort(vc.begin(), vc.end());
  if (vc.size() >= 2) {
    ans = max(ans,
              vc[vc.size() - 1] + vc[vc.size() - 2] + (int)heavy[cen].size());
  }
  for (auto x : tree[cen]) {
    if (kill[x]) continue;
    decompose(x);
  }
}
