const int MAXN = 305, MOD = 998244353;
inline long long dmy(long long first) {
  return first >= MOD ? first - MOD : first;
}
inline void inc(long long &first, long long second) {
  first = dmy(first + second);
}
long long n;
char s[MAXN];
long long f[MAXN][MAXN][MAXN], cnt[2];
long long g[MAXN][MAXN][MAXN];
signed main() {
  scanf("%s", s + 1);
  n = strlen(s + 1);
  for (long long i = 1; i <= n; ++i) ++cnt[s[i] - '0'];
  for (long long j = 0; j <= cnt[1]; ++j) f[n + 1][0][j] = 1;
  for (long long i = 1; i <= cnt[0]; ++i) {
    f[n + 1][i][0] = 1;
    for (long long j = 1; j <= cnt[1]; ++j)
      f[n + 1][i][j] = dmy(f[n + 1][i - 1][j] + f[n + 1][i][j - 1]);
  }
  for (long long k = n; k; --k)
    for (long long i = 0; i <= cnt[0]; ++i)
      for (long long j = 0; j <= cnt[1]; ++j) {
        if (i) inc(f[k][i][j], f[k + (s[k] == '0')][i - 1][j]);
        if (j) inc(f[k][i][j], f[k + (s[k] == '1')][i][j - 1]);
      }
  g[0][0][0] = 1;
  for (long long k = 1; k <= n; ++k)
    for (long long i = 0; i <= k && i <= cnt[0]; ++i)
      for (long long j = 0; j <= k - i && j <= cnt[1]; ++j) {
        if (s[k] == '0') {
          if (i) g[k][i][j] += g[k - 1][i - 1][j];
          if (i && k >= 2) g[k][i][j] += g[k - 2][i - 1][j];
        } else {
          if (j) g[k][i][j] += g[k - 1][i][j - 1];
          if (j && k >= 2) g[k][i][j] += g[k - 2][i][j - 1];
        }
        if (s[k - 1] == '0' && i)
          g[k][i][j] += g[k - 2][i - 1][j];
        else if (s[k - 1] == '1' && j)
          g[k][i][j] += g[k - 2][i][j - 1];
        if (g[k][i][j]) g[k][i][j] = 1;
      }
  long long ans = 0;
  for (long long i = 0; i <= cnt[0]; ++i)
    for (long long j = 0; j <= cnt[1]; ++j) {
      long long pos = -1;
      for (long long k = n; k >= 0; --k)
        if (g[k][i][j]) {
          pos = k;
          break;
        }
      if (pos < 0) continue;
      inc(ans, f[pos + 1][cnt[0] - i][cnt[1] - j]);
    }
  printf("%d\n", dmy(ans + MOD - 1));
  return 0;
}

