  long long tot1 = min(b1, a1), tot2 = min(a2, b2), tot3 = min(a3, b3);
  long long ans11 = n - ans1 - tot1 - tot2 - tot3;
  ans1 = min(A1, B1) + min(A2, B2) + min(A3, B3);
  A1 -= min(A1, B1);
  A2 -= min(A2, B2);
  A3 -= min(A3, B3);
  B1 -= min(A1, B1);
  B2 -= min(A2, B2);
  B3 -= min(A3, B3);
  tot1 = min(B1, A2);
  tot2 = min(B2, A3);
  tot3 = min(B3, A1);
  long long ans12 = n - ans1 - tot1 - tot2 - tot3;
  cout << min(ans11, ans12) << ' ' << ans2 << endl;
  return 0;
}

