double eps = 1e-6;
int n;
double pd, nd;
int sgn(double x) {
  if (fabs(x) <= eps)
    return 0;
  else if (x > 0)
    return 1;
  else
    return -1;
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    double x;
    scanf("%lf", &x);
    int t = sgn(x);
