    if (!sgn(x - l))
      printf("%d\n", l);
    else {
      if (t < 0) {
        int temp = (int)ceil(x);
        double delt = temp - x;
        nd += delt;
        if (sgn(nd - 1.0) >= 0) temp--, nd -= 1.0;
        printf("%d\n", temp);
      } else {
        int temp = (int)floor(x);
        double delt = x - temp;
        pd += delt;
