//import net.leksi.cf.*;

public class C2 {

    public static void main(String[] args) throws IOException {
        new C2().run();
    }

    private void load_inputs(final BufferedReader br) throws IOException {
        try (
                PrintWriter pw = select_output();
        ) {
            int t = Integer.valueOf(br.readLine().trim());
            while(t-- > 0) {
                int[] nm = Arrays.stream(br.readLine().trim().split("\\s+")).mapToInt(v -> Integer.valueOf(v)).toArray();
                long[][] ab = new long[nm[1]][];
                for(int i = 0; i < nm[1]; i++) {
                    ab[i] = Arrays.stream((br.readLine().trim()).split("\\s+")).mapToLong(v -> Long.valueOf(v)).toArray();
                }
                if(t > 0) {
                    br.readLine();
                }
                solve(nm[0], nm[1], ab, pw);
            }
        }
    }

    private void solve(final int n, final int m, final long[][] ab, final PrintWriter pw) {
//        System.out.println("-----------");
        if(n == 1) {
            PriorityQueue<Integer> pq = new PriorityQueue<>((x, y) -> Long.compare(ab[y][0], ab[x][0]));
            pq.addAll(IntStream.range(0, m).mapToObj(v -> v).collect(Collectors.toList()));
            pw.println(ab[pq.poll()][0]);
        } else if(m == 1) {
            pw.println(ab[0][0] + (n - 1) * ab[0][1]);
        } else {
            PriorityQueue<Integer> pq_a = new PriorityQueue<>((x, y) -> Long.compare(ab[y][0], ab[x][0]));
            PriorityQueue<Integer> pq_b = new PriorityQueue<>((x, y) -> {
                int r = Long.compare(ab[y][1], ab[x][1]);
                if(r == 0) {
                    r = Long.compare(ab[y][0], ab[x][0]);
                }
                return r;
            });
            pq_b.addAll(IntStream.range(0, m).mapToObj(v -> v).collect(Collectors.toList()));
//            System.out.println(pq_b.stream().map(i -> String.format("{%d, %d}", ab[i][0], ab[i][1])).collect(Collectors.joining(" ")));
            PriorityQueue<Integer> pq_a1 = new PriorityQueue<>((x, y) -> Long.compare(ab[x][0], ab[y][0]));
            int max_b_i = pq_b.poll();
            long res = ab[max_b_i][0] + (n - 1) * ab[max_b_i][1];
            pq_a.addAll(IntStream.range(0, m).filter(i -> i != max_b_i).mapToObj(v -> v).collect(Collectors.toList()));
//            System.out.println(pq_a.stream().map(i -> String.format("{%d, %d}", ab[i][0], ab[i][1])).collect(Collectors.joining(" ")));
            int cnt = n - 1;
            for(; cnt > 0 && !pq_a.isEmpty(); cnt--) {
                int i = pq_a.peek();
                if(ab[i][0] <= ab[max_b_i][1]) {
                    break;
                }
                pq_a.poll();
                res += ab[i][0] - ab[max_b_i][1];
                pq_a1.offer(i);
            }
            if(cnt == 0) {
                while(!pq_a.isEmpty() && ab[pq_a.peek()][0] > ab[pq_a1.peek()][0]) {
                    int i = pq_a.poll();
                    res += ab[i][0];
                    res -= ab[pq_a1.poll()][0];
                    pq_a1.offer(i);
                }
            }

            pw.println(res);
        }
    }

    String nameIn = "C.in";
    String nameOut = null;

    private void run() throws IOException {
        File input = null;
        if (nameIn != null && (input = new File(nameIn)).exists()) {
            try (
                    FileReader fr = new FileReader(input);
                    BufferedReader br = new BufferedReader(fr);) {
                load_inputs(br);
            }
        } else {
            try (
                    InputStreamReader fr = new InputStreamReader(System.in);
                    BufferedReader br = new BufferedReader(fr);) {
                load_inputs(br);
            }
        }
    }

    PrintWriter select_output() throws FileNotFoundException {
        if (nameOut != null) {
            return new PrintWriter(nameOut);
        }
        return new PrintWriter(System.out);
    }

}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int S1 = (N * N + 1) * N / 2;
        //        boolean[] taken = new boolean[N * N + 1];
        Set<Integer> left = new HashSet<>();
        for (int i = 1; i <= N * N; i++) {
            left.add(i);
        }
        int[][] M = new int[N][];
        for (int i = 0; i < N; i++) {
            M[i] = new int[N];
        }
        int[] colSums = new int[N];
        int[] rowSums = new int[N];
        if (!fill(M, N, S1, left, 0, 0, rowSums, colSums)) {
            throw new IllegalStateException();
        }
        for (int row = 0; row < N; row++) {
            for (int col = 0; col < N; col++) {
                System.out.print(M[row][col] + " ");
            }
            System.out.println();
        }
    }

    private static Set<Integer> union(Set<Integer> a, Set<Integer> b) {
        Set<Integer> result = new HashSet<>(a);
        result.addAll(b);
        return result;
    }

    private static Set<Integer> minus(Set<Integer> a, Set<Integer> b) {
        Set<Integer> result = new HashSet<>(a);
        result.removeAll(b);
        return result;
    }

    private static Set<Integer> minus(Set<Integer> a, int i) {
        Set<Integer> result = new HashSet<>(a);
        result.remove(i);
        return result;
    }

    private static boolean fill(int[][] M, int N, int S1, Set<Integer> left,
            int row, int col, int[] rowSums, int[] colSums) {
        if (row == N - 1 && col == N - 1) {
            //            System.err.println("FINAL");
            return true;
        }
        if (col == N - 1) {
            //            System.err.println("EOL");
            int candidate = S1 - rowSums[row];
            if (candidate <= 0 || candidate > N * N
                || !left.contains(candidate)) {
                return false;
            } else {
                int nextColSum = colSums[col] + candidate;
                if (nextColSum > S1) {
                    return false;
                }
                colSums[col] = nextColSum;
                rowSums[row] = S1;
                M[row][col] = candidate;
                if (fill(M, N, S1, minus(left, candidate), row + 1, 0, rowSums, colSums)) {
                    return true;
                }
                colSums[col] -= candidate;
                rowSums[row] -= candidate;
                M[row][col] = -1;
                return false;
            }
        }
        if (row == N - 1) {
            //            System.err.println("EOC");
            int candidate = S1 - colSums[col];
            if (candidate <= 0 || candidate > N * N
                || !left.contains(candidate)) {
                return false;
            } else {
                int nextRowSum = rowSums[row] + candidate;
                if (nextRowSum > S1) {
                    return false;
                }
                rowSums[row] = nextRowSum;
                colSums[col] = S1;
                M[row][col] = candidate;
                if (fill(M, N, S1, minus(left, candidate), row, col + 1, rowSums, colSums)) {
                    return true;
                }
                rowSums[row] -= candidate;
                colSums[col] -= candidate;
                M[row][col] = -1;
                return false;
            }
        }
        //        System.err.println("IN");
        for (int i : left) {
            int nextRowSum = rowSums[row] + i;
            if (nextRowSum >= S1) {
                continue;
            }
            int nextColSum = colSums[col] + i;
            if (nextColSum >= S1) {
                continue;
            }
            colSums[col] = nextColSum;
            rowSums[row] = nextRowSum;
            M[row][col] = i;
            if (fill(M, N, S1, minus(left, i), row, col + 1, rowSums, colSums)) {
                return true;
            }
            colSums[col] -= i;
            rowSums[row] -= i;
            M[row][col] = -1;
        }
        return false;
    }
}

