using M9 = IntMod<998244353>;

string S;
bool DP[301][301][301];
M9 EP[301][301][301];
M9 EQ[301][301][301];
void pre() {
	string T = S;
	reverse(T.begin(), T.end());
	int N = T.size();

	EP[0][0][0] = 1;
	REP(i, 1, N + 1) {
		REP(j, 0, N + 1) {
			REP(k, 0, N + 1) {
				if (T[i - 1] == '0') {
					REP(dk, 0, k + 1) {
						EP[i][j][k] += EP[i - 1][j][k - dk];
					}
				} else {
					REP(dj, 0, j + 1) {
						EP[i][j][k] += EP[i - 1][j - dj][k];
					}
				}
			}
		}
	}
}

M9 sub(int i, int j, int k) {
	M9 sum = 0;
	REP(dj, 0, j + 1) {
		REP(dk, 0, k + 1) {
			sum += EP[i][j - dj][k - dk] * M9::combi(dj + dk, dj);
		}
	}
	return sum;
}

int main() {
	cin >> S;
	pre();

	int N = S.size();
	DP[0][0][0] = true;
	REP(i, 0, N + 1) {
		REP(j, 0, N + 1) {
			REP(k, 0, N + 1) {
				if (i + 1 < N) {
					if (S[i] == '0' || S[i + 1] == '0') DP[i + 2][j + 1][k] |= DP[i][j][k];
					if (S[i] == '1' || S[i + 1] == '1') DP[i + 2][j][k + 1] |= DP[i][j][k];
				}
				if (j > 0 && S[i] == '1') DP[i + 1][j - 1][k + 1] |= DP[i][j][k];
				if (k > 0 && S[i] == '0') DP[i + 1][j + 1][k - 1] |= DP[i][j][k];
				if (j + k > 0) DP[i + 1][j][k] |= DP[i][j][k];
			}
		}
	}

	M9 sum = 0;
	REP(i, 0, N + 1) {
		REP(j, 0, N + 1) {
			REP(k, 0, N + 1) {
				if (!DP[i][j][k]) continue;
				if (S[i] == '0' && DP[i + 1][j + 1][k]) continue;
				if (S[i] == '1' && DP[i + 1][j][k + 1]) continue;
				sum += sub(N - i, j, k);
			}
		}
	}
	cout << sum << endl;
	return 0;
}

