using namespace std;
typedef int Elem;
typedef int Alt;
const Elem neutro = 0;
const Alt neutro2 = 0;
struct RMQ {
  int sz;
  Elem t[4 * 100010];
  Alt dirty[4 * 100010];
  Elem &operator[](int p) { return t[sz + p]; }
  void init(int n) {
    sz = 1 << (32 - __builtin_clz(n));
    for (int i = (sz); i < (2 * sz); i++) t[i] = neutro;
    for (int i = (0); i < (2 * sz); i++) dirty[i] = neutro2;
  }
  void push(int n, int a, int b) {
    if (dirty[n] != 0) {
      t[n] |= dirty[n];
      if (n < sz) {
        dirty[2 * n] |= dirty[n];
        dirty[2 * n + 1] |= dirty[n];
      }
      dirty[n] = 0;
    }
  }
  Elem get(int i, int j, int n, int a, int b) {
    if (j <= a || i >= b) return neutro;
    push(n, a, b);
    if (i <= a && b <= j) return t[n];
    int c = (a + b) / 2;
    return (get(i, j, 2 * n, a, c) | get(i, j, 2 * n + 1, c, b));
  }
  Elem get(int i, int j) { return get(i, j, 1, 0, sz); }
  void alterar(Alt val, int i, int j, int n, int a, int b) {
    push(n, a, b);
    if (j <= a || i >= b) return;
    if (i <= a && b <= j) {
      dirty[n] |= val;
      push(n, a, b);
      return;
    }
    int c = (a + b) / 2;
    alterar(val, i, j, 2 * n, a, c), alterar(val, i, j, 2 * n + 1, c, b);
    t[n] = (t[2 * n] | t[2 * n + 1]);
  }
  void alterar(Alt val, int i, int j) { alterar(val, i, j, 1, 0, sz); }
} rmq;
struct RMQ2 {
  struct nodo {
    int k, s;
  } t[4 * 100010];
  int sz;
  nodo &operator[](int p) { return t[sz + p]; }
  void init(int n) {
    sz = 1 << (32 - __builtin_clz(n));
    for (int i = (0); i < (2 * sz); i++) t[i].k = t[i].s = 0;
  }
  long long get(int K, int n = 1) {
    if (!K) return 0;
    if (t[n].k < K) return 1000;
    if (n >= sz) return (t[n].s / t[n].k) * K;
    if (t[2 * n].k >= K) return get(K, 2 * n);
    return t[2 * n].s + get(K - t[2 * n].k, 2 * n + 1);
  }
  void insert(int p, long long val) {
    for (p += sz; p > 0;) {
      t[p].s &= val;
      t[p].k++;
      p /= 2;
    }
  }
} rmq2;
struct RMQ3 {
  int vec[18][1 << (18 + 1)];
  int &operator[](int p) { return vec[0][p]; }
  int get(int i, int j) {
    int p = 31 - __builtin_clz(j - i);
    return vec[p][i] & vec[p][j - (1 << p)];
  }
  void build(int n) {
    int mp = 31 - __builtin_clz(n);
    for (int p = (0); p < (mp); p++)
      for (int x = (0); x < (n - (1 << p)); x++)
        vec[p + 1][x] = vec[p][x] & vec[p][x + (1 << p)];
  }
};
