void sieve(int n) {
  pm[1] = 1, pk[1] = 1;
  for (int i = 2; i <= n; ++i) {
    if (!pm[i]) p[++ptop] = i, pm[i] = i, pk[i] = i;
    for (int j = 1; j <= ptop; ++j) {
      int t = i * p[j];
      if (t > n) break;
      pm[t] = p[j];
      if (i % p[j])
        pk[t] = pk[p[j]];
      else {
        pk[t] = pk[i] * p[j];
        break;
      }
    }
  }
}
