bool solveLP(int L, int P) {
  for (int t = 198; t; --t) {
    int r = rnd() % P;
    if (r == 1 || r == P - 1) continue;
    if (qpow(r, L, P) == 1) {
      int R = 1, D = (P - 1) / L;
      for (int k = 1; k <= L; ++k) {
        R = 1LL * R * r % P;
        if (R == 1 || R == P - 1) continue;
        if (solveLPR(L, P, R)) {
          printf("%d %d\n", P, R);
          return 1;
        }
      }
    }
  }
  return 0;
}
