public class Main {
	public static int[][] array = new int[4][4];
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		for (int i = 0; i < 4; i++) {
			String s = sc.next();
			for (int j = 0; j < 4; j++) {
				char c = s.toCharArray()[j];
				switch (c) {
