			for (int j = 0; j < 4; j++) {
				if (array[i][j] != 0) continue;
				int loc = i*4+j+1;
				switch (loc) {
					case 1:
					case 2:
					case 5:
					case 6:
						if (checkRight(i, j)) {System.out.print("YES");return;}
						if (checkDown(i, j)) {System.out.print("YES");return;}
						if (checkRightDown(i, j)) {System.out.print("YES");return;}
