			return true;
		}
		return false;
	}
	public static boolean checkUp(int x,int y){
		if (array[x-1][y] == 1 && array[x-2][y] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkDown(int x,int y){
		if (array[x+1][y] == 1 && array[x+2][y] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkLeftUp(int x, int y){
		if (array[x-1][y-1] == 1 && array[x-2][y-2] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkLeftDown(int x, int y){
		if (array[x+1][y-1] == 1 && array[x+2][y-2] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkRightDown(int x, int y){
		if (array[x+1][y+1] == 1 && array[x+2][y+2] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkRightUp(int x, int y){
		if (array[x-1][y+1] == 1 && array[x-2][y+2] == 1) {
			return true;
		}
		return false;
	}
	public static boolean checkCenterRight(int x, int y){
		if (array[x+1][y+1] == 1 && array[x-1][y-1] == 1) {
			return true;
		}
		return false;
