	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF106D o = new CF106D(); o.main(); o.flush();
	}

	static final int A = 26;
	void main() {
		int n = sc.nextInt();
		int m = sc.nextInt();
		byte[][] cc = new byte[n][];
		int[] ii = new int[A];
		int[] jj = new int[A];
		for (int i = 0; i < n; i++) {
			cc[i] = sc.next().getBytes();
			for (int j = 0; j < m; j++) {
				byte c = cc[i][j];
				if ('A' <= c && c <= 'Z') {
					int a = c - 'A';
					cc[i][j] = '.';
					ii[a] = i;
					jj[a] = j;
				}
			}
		}
		int k = sc.nextInt();
		char[] dd = new char[k];
		int[] xx = new int[k];
		for (int h = 0; h < k; h++) {
			dd[h] = sc.next().charAt(0);
			xx[h] = sc.nextInt();
		}
		int[][] nn = new int[n][m];
		int[][] ww = new int[n][m];
		int[][] ss = new int[n][m];
		int[][] ee = new int[n][m];
		for (int i = 1; i < n - 1; i++)
			for (int j = 1; j < m - 1; j++)
				if (cc[i][j] == '.') {
					nn[i][j] = 1 + nn[i - 1][j];
					ww[i][j] = 1 + ww[i][j - 1];
				}
		for (int i = n - 2; i > 0; i--)
			for (int j = m - 2; j > 0; j--)
				if (cc[i][j] == '.') {
					ss[i][j] = 1 + ss[i + 1][j];
					ee[i][j] = 1 + ee[i][j + 1];
				}
		char[] qu = new char[A]; int cnt = 0;
		for (int a = 0; a < A; a++) {
			if (ii[a] == 0)
				continue;
			boolean yes = true;
			int i = ii[a], j = jj[a];
			for (int h = 0; h < k; h++) {
				char d = dd[h];
				int x = xx[h];
				int[][] aa;
				if (d == 'N')
					aa = nn;
				else if (d == 'S')
					aa = ss;
				else if (d == 'W')
					aa = ww;
				else
					aa = ee;
				if (aa[i][j] <= x) {
					yes = false;
					break;
				}
				if (d == 'N')
					i -= x;
				else if (d == 'S')
					i += x;
				else if (d == 'W')
					j -= x;
				else
					j += x;
			}
			if (yes)
				qu[cnt++] = (char) ('A' + a);
		}
		if (cnt == 0)
			println("no solution");
		else
			println(new String(qu, 0, cnt));
	}
}

