bool compare() {
  long long hasz1 = zamien(t1[n - 2]), hasz2 = t2[n - 2];
  for (int i = 1; i < n - 1; ++i) {
    if (hasz1 == hasz2) return false;
    hasz1 = ((hasz1 * B) % M + zamien(t1[n - 2 - i]) + M) % M;
    hasz2 = (hasz2 + (t2[n - 2 - i] * Be[i]) % M + M) % M;
  }
  return true;
}
