int depth[1000001];
vector<vector<int> > arr(1000001);
int ans[1000001];
int cnt[1000001];
pair<int, int> val[100001];
int subtree[100001];
pair<int, int> temp;
void dfspre(int u, int h, int par) {
  depth[u] = h;
  subtree[u]++;
  int i;
  for (i = 0; i < arr[u].size(); i++) {
    if (arr[u][i] == par) continue;
    dfspre(arr[u][i], h + 1, u);
    subtree[u] += subtree[arr[u][i]];
  }
}
void add(int u, int x, int biggy, int par) {
  cnt[depth[u]] += x;
  if (cnt[depth[u]] > temp.first)
    temp.first = cnt[depth[u]], temp.second = depth[u];
  else if (cnt[depth[u]] == temp.first)
    temp.second = min(temp.second, depth[u]);
  for (int i = 0; i < arr[u].size(); i++) {
    if (arr[u][i] == par) continue;
    if (arr[u][i] != biggy) add(arr[u][i], x, biggy, u);
  }
}
void dfs(int u, bool keep, int par) {
  int tot = 0, bigchild = -1;
  int i;
  for (i = 0; i < arr[u].size(); i++) {
    if (arr[u][i] == par) continue;
    if (subtree[arr[u][i]] > tot)
      tot = subtree[arr[u][i]], bigchild = arr[u][i];
  }
  for (i = 0; i < arr[u].size(); i++) {
    if (arr[u][i] == par) continue;
    if (arr[u][i] != bigchild) dfs(arr[u][i], 0, u);
  }
  temp.first = 1, temp.second = depth[u];
  if (bigchild != -1) {
    dfs(bigchild, 1, u);
    if (val[bigchild].first > temp.first) temp = val[bigchild];
  }
  add(u, 1, bigchild, par);
  bigchild = -1;
  ans[u] = temp.second;
  val[u] = temp;
  if (keep == 0) add(u, -1, bigchild, par);
}
