                sum += a[i][j];
                if (a[i][j] == 1) {
                    if (p != -1 && p != j - 1) return -1;
                    p = j;
                }
            }

            if (sum == 0) return -1;
        }

        for (int j = 0; j < m; j++) {
            int sum = 0;
            int p = -1;

            for (int i = 0; i < n; i++) {
                sum += a[i][j];
                if (a[i][j] == 1) {
                    if (p != -1 && p != i - 1) return -1;
                    p = i;
                }
            }

            if (sum == 0) return -1;
        }

        int res = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == 1) {
                    res++;
                    bfs(n, m, a, i, j);
                }
            }
        }

        return res;
    }

    void bfs(int n, int m, int[][] a, int r, int c) {
        Queue<Cell> queue = new LinkedList<>();
        queue.add(new Cell(r, c));
        a[r][c] = 0;

        while (!queue.isEmpty()) {
            Cell now = queue.poll();

            for (int i = 0; i < 4; i++) {
                Cell next = new Cell(now.r + dr[i], now.c + dc[i]);

                if (next.inside(n, m) && a[next.r][next.c] == 1) {
                    a[next.r][next.c] = 0;
                    queue.add(next);
                }
            }
        }
    }

    static final int[] dr = {-1, 0, +1, 0};
    static final int[] dc = {0, +1, 0, -1};

    static class Cell {
        int r;
        int c;

        public Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }

        public boolean inside(int nrow, int ncol) {
            return 0 <= r && r < nrow && 0 <= c && c < ncol;
        }
    }

    private InputReader reader;
    private PrintWriter writer;

    public Solution(InputReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solution solution = new Solution(reader, writer);
        solution.solve();

        writer.flush();
    }

    static class InputReader {
        private static final int BUFFER_SIZE = 1 << 20;

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), BUFFER_SIZE);
            tokenizer = null;
        }

        public String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
const int SQRT = 317;
const int MAXN = 100001;
int a[SQRT][SQRT];
int head[SQRT], front[SQRT];
int cnt[SQRT][MAXN];
int sz[SQRT];
void shift_block(int block, int l_pos, int r_pos) {
  int j = (r_pos + sz[block] - 1) % sz[block];
  for (int i = r_pos; i != l_pos; i = j, j = (j + sz[block] - 1) % sz[block]) {
    a[block][i] = a[block][j];
  }
}
void shift(int l, int r) {
  int l_bl = l / SQRT;
  int l_pos = (l + head[l_bl]) % sz[l_bl];
  int r_bl = r / SQRT;
  int r_pos = (r + head[r_bl]) % sz[r_bl];
  int push_val = a[r_bl][r_pos];
  if (l_bl == r_bl) {
    shift_block(l_bl, l_pos, r_pos);
    a[l_bl][l_pos] = push_val;
    return;
  }
  int last_val = a[l_bl][front[l_bl]];
  cnt[l_bl][last_val]--;
  shift_block(l_bl, l_pos, front[l_bl]);
  a[l_bl][l_pos] = push_val;
  cnt[l_bl][push_val]++;
  cnt[r_bl][push_val]--;
  push_val = last_val;
  for (int i = l_bl + 1; i < r_bl; i++) {
    last_val = a[i][front[i]];
    cnt[i][last_val]--;
    cnt[i][push_val]++;
    front[i] = head[i];
    head[i] = front[i];
    front[i] = (front[i] + SQRT - 1) % sz[i];
    a[i][head[i]] = push_val;
    push_val = last_val;
  }
  cnt[r_bl][push_val]++;
  shift_block(r_bl, head[r_bl], r_pos);
  a[r_bl][head[r_bl]] = push_val;
}
int get_block(int block, int l_pos, int r_pos, int k) {
  int res = 0;
  for (int i = r_pos;; i = (i + sz[block] - 1) % sz[block]) {
    if (a[block][i] == k) {
      res++;
    }
    if (i == l_pos) {
      break;
    }
  }
  return res;
}
int get(int l, int r, int k) {
  int l_bl = l / SQRT;
  int l_pos = (l + head[l_bl]) % sz[l_bl];
  int r_bl = r / SQRT;
  int r_pos = (r + head[r_bl]) % sz[r_bl];
  if (l_bl == r_bl) {
    return get_block(l_bl, l_pos, r_pos, k);
  }
  int res = 0;
  res += get_block(l_bl, l_pos, front[l_bl], k);
  for (int i = l_bl + 1; i < r_bl; i++) {
    res += cnt[i][k];
  }
  res += get_block(r_bl, head[r_bl], r_pos, k);
  return res;
}
void solve() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    int bl = i / SQRT;
    int pos = i % SQRT;
    front[bl] = pos;
    sz[bl]++;
    int val;
    scanf("%d", &val);
    a[bl][pos] = val;
    cnt[bl][val]++;
  }
  int q;
  scanf("%d", &q);
  int res = 0;
  for (int i = 0; i < q; i++) {
    int t, l, r, k;
    scanf("%d%d%d", &t, &l, &r);
    l = (l + res - 1) % n;
    r = (r + res - 1) % n;
    if (l > r) {
      swap(l, r);
    }
    if (t == 1) {
      shift(l, r);
    } else {
      scanf("%d", &k);
      res = get(l, r, k);
      printf("%d\n", res);
    }
  }
}
int main() { solve(); }

