class StarrySkyTree {
 public:
  static const int N = 1 << 20;
  vector<long long> segMin, segMax, segAdd;
  StarrySkyTree()
      : segMin(N * 2, (long long)1e18),
        segMax(N * 2, (long long)-1e18),
        segAdd(N * 2, 0) {}
  void update(int k, long long x) {
    k += N - 1;
    segMin[k] = x;
    segMax[k] = x;
    while (k) {
      k = (k - 1) / 2;
      segMin[k] = min(segMin[k * 2 + 1], segMin[k * 2 + 2]);
      segMax[k] = max(segMax[k * 2 + 1], segMax[k * 2 + 2]);
    }
  }
  void add(int a, int b, long long x, int k = 0, int l = 0, int r = N) {
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      segAdd[k] += x;
      while (k) {
        k = (k - 1) / 2;
        segMin[k] = min(segMin[k * 2 + 1] + segAdd[k * 2 + 1],
                        segMin[k * 2 + 2] + segAdd[k * 2 + 2]);
        segMax[k] = max(segMax[k * 2 + 1] + segAdd[k * 2 + 1],
                        segMax[k * 2 + 2] + segAdd[k * 2 + 2]);
      }
      return;
    }
    add(a, b, x, k * 2 + 1, l, (l + r) / 2);
    add(a, b, x, k * 2 + 2, (l + r) / 2, r);
  }
  long long getMin(int a, int b, int k = 0, int l = 0, int r = N) {
    if (r <= a || b <= l) return 1e18;
    if (a <= l && r <= b) return (segMin[k] + segAdd[k]);
    long long x = getMin(a, b, k * 2 + 1, l, (l + r) / 2);
    long long y = getMin(a, b, k * 2 + 2, (l + r) / 2, r);
    return (min(x, y) + segAdd[k]);
  }
  long long getMax(int a, int b, int k = 0, int l = 0, int r = N) {
    if (r <= a || b <= l) return -1e18;
    if (a <= l && r <= b) return (segMax[k] + segAdd[k]);
    long long x = getMax(a, b, k * 2 + 1, l, (l + r) / 2);
    long long y = getMax(a, b, k * 2 + 2, (l + r) / 2, r);
    return (max(x, y) + segAdd[k]);
  }
};
int main() {
  cin.tie(0);
  ios::sync_with_stdio(0);
  int N;
  cin >> N;
  vector<int> S(N);
  int sz = N / 2;
  for (int i = (int)(0); i < (int)(N); i++) cin >> S[i];
  for (int i = (int)(0); i < (int)(sz); i++) {
    S[i] -= S[N - i - 1];
  }
  int Q;
  cin >> Q;
  vector<int> L(Q), R(Q), X(Q);
  for (int i = (int)(0); i < (int)(Q); i++)
    cin >> L[i] >> R[i] >> X[i], L[i]--, R[i]--;
  StarrySkyTree sst;
  for (int i = (int)(0); i < (int)(sz); i++) sst.update(i, S[i]);
  for (int i = (int)(0); i < (int)(Q); i++) {
    if (R[i] < sz) {
      sst.add(L[i], R[i] + 1, X[i]);
    } else if (L[i] >= (N + 1) / 2) {
      sst.add(N - R[i] - 1, N - L[i], -X[i]);
    } else {
      sst.add(L[i], sz, X[i]);
      sst.add(N - R[i] - 1, sz, -X[i]);
    }
    if (sst.getMax(0, sz) == sst.getMin(0, sz)) {
      output(1, 0);
    } else {
      output(0, 0);
    }
  }
  return 0;
}

