int main() {
  cin >> n >> m >> k;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) cin >> a[i][j];
  int mid = n / 2;
  dp[0][0][a[0][0]] = 1;
  for (int i = 0; i < mid; i++)
    for (int j = 0; j < m; j++) {
      if (i > 0) {
        for (map<long long, int>::iterator it = dp[i - 1][j].begin();
             it != dp[i - 1][j].end(); it++) {
          dp[i][j][a[i][j] ^ (it->first)] += it->second;
        }
      }
      if (j > 0) {
        for (map<long long, int>::iterator it = dp[i][j - 1].begin();
             it != dp[i][j - 1].end(); it++) {
          dp[i][j][a[i][j] ^ (it->first)] += it->second;
        }
      }
    }
  dp[n - 1][m - 1][a[n - 1][m - 1]] = 1;
  for (int i = n - 1; i >= mid; i--)
    for (int j = m - 1; j >= 0; j--) {
      if (i < n - 1) {
        for (map<long long, int>::iterator it = dp[i + 1][j].begin();
             it != dp[i + 1][j].end(); it++) {
          dp[i][j][a[i][j] ^ (it->first)] += it->second;
        }
      }
      if (j < m - 1) {
        for (map<long long, int>::iterator it = dp[i][j + 1].begin();
             it != dp[i][j + 1].end(); it++) {
          dp[i][j][a[i][j] ^ (it->first)] += it->second;
        }
      }
    }
  for (int j = 0; j < m; j++) {
