pair<vector<int>, map<int, int> > compress(vector<int>& v) {
  vector<int> k;
  map<int, int> m;
  for (int i = 0; i < v.size(); i++) {
    if (v[i] - 1 >= 1) m[v[i] - 1] = -1;
    m[v[i]] = -1;
    if (v[i] + 1 <= R) m[v[i] + 1] = -1;
  }
  int id = 0;
  for (auto p : m) {
    m[p.first] = id++;
    k.push_back(p.first);
  }
  return {k, m};
}
using ll = long long;
struct edge {
  int tx, ty, tz;
  ll cost;
  edge(int tx, int ty, int tz, int cost) : tx(tx), ty(ty), tz(tz), cost(cost) {}
};
vector<edge> G[800][800][11];
ll dist[800][800][11];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};
struct S {
  int x, y, z;
  ll cost;
  bool operator<(const S& s) const { return cost > s.cost; }
};
