    yt.resize(M);
    xr.resize(M);
    yb.resize(M);
    h.resize(M);
    vector<int> xs, ys;
    for (int i = 0; i < N; i++) {
      cin >> x[i] >> y[i] >> z[i];
      xs.push_back(x[i]);
      ys.push_back(y[i]);
    }
    for (int i = 0; i < M; i++) {
      cin >> xl[i] >> yt[i] >> xr[i] >> yb[i] >> h[i];
      xs.push_back(xl[i]);
      xs.push_back(xr[i]);
      ys.push_back(yt[i]);
      ys.push_back(yb[i]);
    }
    auto resX = compress(xs);
    auto resY = compress(ys);
    int XN = resX.first.size();
    int YN = resY.first.size();
    for (int k = 1; k <= 10; k++) {
      for (int i = 0; i < 800; i++) {
        for (int j = 0; j < 800; j++) {
          G[i][j][k].clear();
        }
      }
    }
    const ll INF = 1LL << 60;
    for (int k = 1; k <= K; k++) {
      for (int i = 0; i < XN; i++) {
        for (int j = 0; j < YN; j++) {
          int cx = resX.first[i], cy = resY.first[j];
          for (int l = 0; l < 4; l++) {
            if (i + dx[l] < 0 || XN <= i + dx[l]) continue;
            if (j + dy[l] < 0 || YN <= j + dy[l]) continue;
            int nx = resX.first[i + dx[l]];
            int ny = resY.first[j + dy[l]];
            ll cost = abs(cx - nx) + abs(cy - ny);
            G[i][j][k].push_back(edge(i + dx[l], j + dy[l], k, cost));
          }
          if (k + 1 <= K) {
            for (int m = 0; m < M; m++) {
              if (k + 1 == h[m] && xl[m] <= cx && cx <= xr[m] && yt[m] <= cy &&
                  cy <= yb[m]) {
                G[i][j][k].push_back(edge(i, j, k + 1, 100));
                G[i][j][k + 1].push_back(edge(i, j, k, 100));
                break;
              }
            }
          }
        }
      }
    }
    vector<pair<int, int> > goal;
    for (int i = 0; i < XN; i++) {
      for (int j = 0; j < YN; j++) {
        bool ok = 1;
        int cx = resX.first[i], cy = resY.first[j];
        for (int m = 0; m < M; m++) {
          if (h[m] == K && xl[m] <= cx && cx <= xr[m] && yt[m] <= cy &&
              cy <= yb[m]) {
            ok = 0;
            break;
          }
        }
        if (ok) goal.push_back(pair<int, int>(i, j));
      }
    }
    for (int i = 0; i < N; i++) {
      if (z[i] == K) {
      }
    }
    ll ans = INF;
    for (pair<int, int> g : goal) {
      for (int k = 1; k <= K; k++) {
        for (int i = 0; i < XN; i++) {
          for (int j = 0; j < YN; j++) {
            dist[i][j][k] = INF;
          }
        }
      }
      dist[g.first][g.second][K] = 0;
      priority_queue<S> q;
      q.push({g.first, g.second, K, 0});
      while (q.size()) {
        S s = q.top();
        q.pop();
        if (dist[s.x][s.y][s.z] < s.cost) continue;
        for (edge e : G[s.x][s.y][s.z]) {
          ll ncost = s.cost + e.cost;
          if (dist[e.tx][e.ty][e.tz] > ncost) {
            dist[e.tx][e.ty][e.tz] = ncost;
            q.push({e.tx, e.ty, e.tz, ncost});
          }
        }
      }
      ll sum = 0;
      for (int i = 0; i < N; i++) {
        sum += dist[resX.second[x[i]]][resY.second[y[i]]][z[i]];
      }
      ans = min(ans, sum);
    }
    cout << ans << endl;
  }
  return 0;
}

