bool get(long long a, long long n) {
  if (n == 0)
    return true;
  else if (n == 1)
    return false;
  else if (a & 1) {
    return n % 2 == 0;
  } else {
    n -= 2;
    long long s = a + 1;
    n %= s;
    if (n == s - 3 || n == s - 2)
      return true;
    else if (n == s - 1)
      return false;
    else
      return n % 2 == 0;
  }
}
bool gcd(long long a, long long b) {
  if (b == 0) return false;
  bool p = gcd(b, a % b);
  if (!p)
    return true;
  else
    return get(b, a / b);
}
