int R[MAXN], N, M, dp[MAXN][MAXN];
bool S[MAXN];

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> N >> M;
	for (int i = 1; i <= N; ++i) {
		char ch;
