		for (int j = R[i - 1] + 1; j <= R[i]; ++j) add += S[j];

		for (int j = 0; j <= N; ++j) if (dp[i - 1][j]) {
			if (j + add <= R[i] - i) {
				dp[i][j + add] += dp[i - 1][j];
