#include <bits/stdc++.h>
using namespace std;
unsigned int L[100000], R[100000];
int k, v[200010], sum[2][100000], sum2[100000], ans[2][100000];
struct node {
  unsigned int l, r;
  node(unsigned int _l = 0, unsigned int _r = 0) : l(_l), r(_r) {}
} x[200010], a[200010], b[200010];
inline int Blo(unsigned int x) { return x >> k; }
void update(int k, int l, int r) {
  sum[k][l]++;
  sum[k][r + 1]--;
}
int query(int k, int l, int r) {
  return sum[k][r] - (l > 0 ? sum[k][l - 1] : 0);
}
int query2(int l, int r) { return sum2[r] - (l > 0 ? sum2[l - 1] : 0); }
int main() {
  int q, tot1 = 0, tot2 = 0;
  unsigned int l, r;
  cin >> k >> q;
  for (int i = 1; i <= q; i++) scanf("%u%u%d", &x[i].l, &x[i].r, &v[i]);
  for (int i = 0; i < (1 << k); i++)
    L[i] = i * (1 << k), R[i] = 1ll * (i + 1) * (1 << k) - 1;
  bool flag = 1;
  for (int i = 0; i < 16; i++) {
    memset(sum, 0, sizeof(sum));
    memset(sum2, 0, sizeof(sum2));
    tot1 = tot2 = 0;
    for (int j = 1; j <= q; j++)
      if (v[j] & (1 << i))
        a[++tot1] = node(x[j].l, x[j].r);
      else
        b[++tot2] = node(x[j].l, x[j].r);
    for (int j = 1; j <= tot1; j++) {
      l = a[j].l;
      r = a[j].r;
      int x = Blo(l), y = Blo(r), tx = x, ty = y;
      update(1, x, y);
      if (l != L[x]) tx++;
      if (r != R[y]) ty--;
      if (tx <= ty)
        update(0, 0, (1 << k) - 1);
      else
        update(0, l % (1 << k), x < y ? (1 << k) - 1 : r % (1 << k)),
            update(0, x < y ? 0 : l % (1 << k), r % (1 << k));
    }
    for (int j = 1; j < (1 << k); j++)
      sum[0][j] += sum[0][j - 1], sum[1][j] += sum[1][j - 1];
    for (int j = 0; j < (1 << k); j++)
      sum[0][j] = (sum[0][j] > 0), sum[1][j] = (sum[1][j] > 0);
    for (int j = 1; j < (1 << k); j++) sum[0][j] += sum[0][j - 1];
    sum2[0] = (sum[1][0] & query(0, 0, (1 << k) - 1));
    for (int j = 1; j < (1 << k); j++)
      sum2[j] = sum2[j - 1] + (sum[1][j] & query(0, 0, (1 << k) - 1)),
      sum[1][j] += sum[1][j - 1];
    bool ok = 1;
    for (int j = 1; j <= tot2; j++) {
      l = b[j].l;
      r = b[j].r;
      int x = Blo(l), y = Blo(r), tx = x, ty = y;
      if (l != L[x]) tx++;
      if (r != R[y]) ty--;
      if (tx <= ty) ok &= (!query2(tx, ty));
      ok &= (!query(1, x, x) ||
             !query(0, l % (1 << k), x < y ? (1 << k) - 1 : r % (1 << k)));
      ok &= (!query(1, y, y) ||
             !query(0, x < y ? 0 : l % (1 << k), r % (1 << k)));
      if (!ok) break;
    }
    flag &= ok;
    if (!flag) break;
    for (int j = 0; j < (1 << k); j++)
      ans[0][j] |= (query(0, j, j) << i), ans[1][j] |= (query(1, j, j) << i);
  }
  if (!flag) return puts("impossible"), 0;
  puts("possible");
  for (int i = 0; i < (1 << k); i++) printf("%d\n", ans[0][i]);
  for (int i = 0; i < (1 << k); i++) printf("%d\n", ans[1][i]);
  return 0;
}

