import java.io.*;
import java.util.*;


public class Driver {

	public static class Cost implements Comparable<Cost> {
		int cost;
		int pos;

		Cost (int c, int p) {
			this.cost = c;
			this.pos = p;
		}

		public int compareTo(Cost c) {
			if (this.cost > c.cost) {
				return 1;
			}
			else {
				return -1;
			}
		}
	}

    public static void main(String[] args) throws IOException {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String expression = br.readLine();

        // if odd number of (), we know it is invalid
        if (expression.length() % 2 == 1) {
        	System.out.println("-1");
        	System.exit(0);
        }


        char[] seq = expression.toCharArray();
        Queue<Cost> costs = new PriorityQueue<Cost>();
        //if pcount != 0 in the end the )( are out of balance
        int pCount = 0;
        long cost = 0;

        for (int i = 0; i < seq.length; i++) {
        	switch (seq[i]){
        		case '(': 
        			pCount++;
        			break;
        		case ')':
					pCount--;
					break;
				case '?':
					// get corrisponding cost line
					String [] line = br.readLine().split(" ");
					int first = Integer.parseInt(line[0]);
					int second = Integer.parseInt(line[1]);
					costs.add(new Cost(first - second, i));
					seq[i] = ')';
					cost += second;
					pCount--;
        	}

        	if (costs.size() > 0 && pCount == -1) {
        		//out of balance so lets fix that
        		Cost c = costs.poll();
        		seq[c.pos] = '(';
        		cost += c.cost;
        		pCount += 2;
        	}
        	else if (pCount == -1) {
        		break;
        	}
        }

        if (0 == pCount) {
        	System.out.println(cost);
        	System.out.println(new String(seq));
        }
        else {
        	System.out.println("-1");
        }

        System.exit(0);
    }
}

