    void solve() throws IOException
	{
    	int n=ni(),k=ni();
    	int[] a=na(n);
    	ArrayList<Integer> even=new ArrayList<>();
    	ArrayList<Integer> odd=new ArrayList<>();
    	for(int i=0;i<n;i++)
    	{
    		if(i%2==0)even.add(a[i]);
    		else odd.add(a[i]);
    	}
    	long ans=comp(even,k);
    	ans=(ans*comp(odd,k))%mod;
    	out.println(ans);
	}

    static long comp(ArrayList<Integer> l,long k)
    {
    	int curr=0;
    	int sz=l.size();
    	while(curr<sz && l.get(curr)==-1)curr++;
    	if(curr==sz)
    	{
    		return (pow((int)k-1,sz-1,(int)mod)*k)%mod;
    	}
    	long ans=pow((int)k-1,curr,(int)mod);
    	int prev=curr;
    	curr++;
    	while(curr<sz)
    	{
    		if(l.get(curr)!=-1)
    		{
    			ans=(ans*ways(curr-prev+1,k,l.get(curr)==l.get(prev)))%mod;
    			prev=curr;
    		}
    		curr++;
    	}
    	curr=curr-prev-1;
    	if(curr>=0)ans=(ans*pow((int)k-1,curr,(int)mod))%mod;
    	return ans;
    }

    private static long ways(int n, long k, boolean b) {
		// TODO Auto-generated method stub
    	long[][] dp=new long[n][2];
    	if(b)
    	{
    		dp[1][0]=0;
    		dp[1][1]=k-1;
    	}
    	else 
    	{
    		dp[1][0]=1;
    		dp[1][1]=k-2;
    	}
    	for(int i=2;i<n;i++)
    	{
    		dp[i][0]=dp[i-1][1];
    		dp[i][1]=(dp[i-1][0]*(k-1)+dp[i-1][1]*(k-2))%mod;
    	}
		return dp[n-1][0];
	}

