const double PI = 3.14159265358979;
const double EPS = 1e-9;

class Point {
public:
    double x, y;
    Point(double x = 0.0, double y = 0.0) :x(x), y(y) {}
};

class Wind {
public:
    double w, a;
};

bool include(double angle, double low, double high) {
    if(low < 0 + EPS) {
        double l = low + 2.0 * PI;
        if(l <= angle + EPS) return true;
    }
    if(high > 2.0 * PI + EPS) {
        double h = high - 2.0 * PI;
        if(angle <= h + EPS) return true;
    }
    return low <= angle + EPS && angle <= high + EPS;
}

bool savor(const Point &home, const Wind &wind, const vector<Point> &blossom, double d) {
//     cout << "home: " << home.x << ", " << home.y << endl;
//     cout << "blossom" << endl; for(const auto &i: blossom) cout << "  " << i.x << "," << i.y; cout << endl;
//     cout << "d: " << d << endl;
//     cout << "wind: " << wind.w << ", " << wind.a << endl;
//     cout << endl;
    d /= 2.0;
    for(const auto &b: blossom) {
        Point dif(home.x - b.x, home.y - b.y);
        double angle = atan2(dif.y, dif.x);
        double dist = hypot(dif.y, dif.x);
        if(angle < 0) angle = 2 * PI + angle;
//         cout<<"angle: "<<angle<<endl;
//         cout<<"wind.w +- d: "<<wind.w - d<<" - "<<wind.w + d<<endl;
//         cout<<"dist: "<<dist<<endl;
        if(dist <= wind.a + EPS && include(angle, wind.w - d, wind.w + d)) return true;
    }
    return false;
}

double toRadian(double d) {
    return d * PI / 180.0;
}

