            for(int i=0;i<n;i++)
            {
                int a=input.nextInt();
                if(map.containsKey(a))
                {
                    map.put(a,map.get(a)+1);
                }
                else
                {
                    map.put(a,1);
                }
            }
            ArrayList<Integer> list=new ArrayList<>();
            Iterator it=map.entrySet().iterator();
            int m=0;
            while(it.hasNext())
            {
                Map.Entry e=(Map.Entry)it.next();
                int r=(int)e.getValue();
                list.add(r);
                m=Math.max(m,r);
            }
            mergeSort(list,0,list.size()-1);
            int max=0;
            HashSet<Integer> set=new HashSet<>();
            for(int i=1;i<=m;i++)
            {
                int v=i;
                int pre=0;
                int sum=0;
                while(true)
                {
                    int index=greaterIndex(list,pre,v);
                    if(index>=list.size())
                    {
                        break;
                    }
                    else
                    {
                        sum+=v;
                        v*=2;
                        pre=index+1;
                    }
                }
                max=Math.max(max,sum);
            }
            out.println(max);
        }
        out.close();
    }
    public static int greaterIndex(ArrayList<Integer> a,int i,int k)
    {
        int j=a.size();
        while(i<j)
        {
            int mid=(i+j)/2;
            if(k<=a.get(mid))
            {
                j=mid;
            }
            else
            {
                i=mid+1;
            }
        }
        return i;
    }
    public static void mergeSort(ArrayList<Integer> a,int p,int r)
    {
        if(p<r)
        {
            int q=(p+r)/2;
            mergeSort(a,p,q);
            mergeSort(a,q+1,r);
            merge(a,p,q,r);
        }
    }
    public static void merge(ArrayList<Integer> a,int p,int q,int r)
    {
        int n1=q-p+2;
        int L[]=new int[n1];
        int n2=r-q+1;
        int R[]=new int[n2];
        for(int i=p;i<=q;i++)
        {
            L[i-p]=a.get(i);
        }
        L[n1-1]=Integer.MAX_VALUE;
        for(int i=q+1;i<=r;i++)
        {
            R[i-q-1]=a.get(i);
        }
        R[n2-1]=Integer.MAX_VALUE;
