  cin >> n;
  while (n--) {
    int a;
    cin >> a;
    int u = 1;
    for (int i = 2; i * i <= a; i++) {
      int q = 0;
      while (a % i == 0) {
        a /= i;
        q ^= 1;
      }
      if (q) {
        u *= i;
      }
    }
    u *= a;
    kek[u]++;
  }
  int h = 0;
  for (auto& p : kek) {
    grs.push_back(p.second);
    h += p.second;
  }
  facts[0] = 1;
  for (int i = 1; i <= 1500; i++) {
    facts[i] = mul(facts[i - 1], i);
  }
  dp[0][grs[0] - 1] = facts[grs[0]];
  int total = 0;
  for (int i = 0; i < grs.size() - 1; i++) {
    int sz = grs[i + 1];
    total += grs[i];
    for (int j = 0; j < h; j++) {
      if (!dp[i][j]) {
        continue;
      }
      for (int s = 1; s <= min(sz, total + 1); s++) {
        for (int d = 0; d <= min(j, s); d++) {
          int t = mul(facts[sz], mul(c(sz - 1, s - 1),
                                     mul(c(j, d), c(total + 1 - j, s - d))));
          dp[i + 1][j - d + sz - s] =
              add(dp[i + 1][j - d + sz - s], mul(t, dp[i][j]));
        }
      }
    }
  }
