#include <bits/stdc++.h>
using namespace std;
int main() {
  int N, M, C, s, g;
  long long int INF = 1e15;
  while (cin >> N >> M >> C >> s >> g, N) {
    --s;
    --g;
    vector<vector<long long int> > G(N, vector<long long int>(N, INF));
    vector<vector<vector<long long int> > > D(C, G);
    long long int x, y, d, c;
    for (int i = 0; i < M; ++i) {
      cin >> x >> y >> d >> c;
      --x;
      --y;
      --c;
      D[c][x][y] = min(D[c][x][y], d);
      D[c][y][x] = d;
    }
    for (int c = 0; c < C; ++c) {
      for (int k = 0; k < N; ++k) {
        for (int i = 0; i < N; ++i) {
          for (int j = 0; j < N; ++j) {
            D[c][i][j] = min(D[c][i][j], D[c][i][k] + D[c][k][j]);
          }
        }
      }
    }
    vector<int> P(C);
    for (int i = 0; i < C; ++i) cin >> P[i];
    vector<vector<long long int> > Q(C), R(C), F(C);
    for (int c = 0; c < C; ++c) {
      int q, r;
      Q[c].push_back(0);
      for (int i = 0; i < P[c] - 1; ++i) {
        cin >> q;
        Q[c].push_back(q);
      }
      for (int i = 0; i < P[c]; ++i) {
        cin >> r;
        R[c].push_back(r);
      }
      F[c].push_back(0);
      for (int i = 0; i < P[c] - 1; ++i) {
        F[c].push_back((Q[c][i + 1] - Q[c][i]) * R[c][i] + F[c].back());
      }
    }
    for (int c = 0; c < C; ++c) {
      for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
          long long int d = D[c][i][j];
          int t = upper_bound(Q[c].begin(), Q[c].end(), d) - Q[c].begin() - 1;
          G[i][j] = min(G[i][j], F[c][t] + R[c][t] * (d - Q[c][t]));
          G[j][i] = G[i][j];
        }
      }
    }
    for (int k = 0; k < N; ++k) {
      for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
          G[i][j] = min(G[i][j], G[i][k] + G[k][j]);
        }
      }
    }
    if (G[s][g] >= INF)
      cout << -1 << endl;
    else
      cout << G[s][g] << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
int N;
long long Q;
long long A[200005];
long long mxa;
long long sm;
long long cnt[450][450];
long long psm[200005];
long long cal1(long long x) {
  long long rtn = sm;
  for (int i = 0; i <= x - 1; i++) rtn -= cnt[x][i] * i;
  return rtn;
}
long long cal2(long long x) {
  long long rtn = 0;
  for (long long i = x; i <= mxa; i += x) {
    long long r = min(mxa, i + x - 1);
    rtn += i * (psm[r] - psm[i - 1]);
  }
  return rtn;
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> N;
  for (int i = 1; i <= N; i++) {
    cin >> A[i];
    sm += A[i];
    mxa = max(A[i], mxa);
  }
  Q = (long long)sqrt(mxa);
  for (int i = 1; i <= N; i++) {
    psm[A[i]]++;
    for (int j = 1; j <= Q - 1; j++) cnt[j][A[i] % j]++;
  }
  for (int i = 2; i <= mxa; i++) psm[i] += psm[i - 1];
  long long ans = 0;
  for (int i = 1; i <= N; i++) {
    long long res;
    if (A[i] < Q)
      res = cal1(A[i]);
    else
      res = cal2(A[i]);
    ans = max(ans, res);
  }
  cout << ans << '\n';
  return 0;
}

