int solve(int l, int r, int Mod, int deep) {
  if (Mod == 1) return 1;
  long long now = a[l] % Mod;
  if (!now) return 0;
  if (l == r) return now;
  int nxt = min(l + 5, r);
  for (int i = l + 1; i < nxt; i++)
    if (a[i] == 1) {
      nxt = r = i;
      break;
    }
  long long last = a[nxt], x;
  if (last >= p[deep])
    return Pow(now, solve(l + 1, r, p[deep], deep + 1) + p[deep], Mod);
  for (int i = nxt - 1; i > l; i--) {
    long long mi = last;
    last = 1;
    x = a[i];
    for (int j = 1; j <= mi; j++) {
      last = last * x;
      if (last >= p[deep])
        return Pow(now, solve(l + 1, r, p[deep], deep + 1), Mod);
    }
  }
  return Pow(now, solve(l + 1, r, p[deep], deep + 1), Mod);
}
int Pow(int a, int b, int Mod) {
  int Ans = 1;
  for (; b; b >>= 1, a = 1LL * a * a % Mod)
    if (b & 1) Ans = 1LL * Ans * a % Mod;
  return Ans;
}
int Getphi(int x) {
  int ans = x;
  for (int i = 2; i * i <= x; i++) {
    if (x % i == 0) {
      ans = ans / i * (i - 1);
      while (x % i == 0) x /= i;
    }
  }
  if (x > 1) ans = ans / x * (x - 1);
  return ans;
}
