public class StonedGame {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int tt = sc.nextInt();
        StringBuffer sb = new StringBuffer();
        while (tt--> 0){
            int n = sc.nextInt();
            int[] arr = sc.readArray(n);
            int maxIdx = maxIdx(arr);
            int maxVal = arr[maxIdx];
            arr[maxIdx] = 0;
            int secMaxIdx = maxIdx(arr);
            int secMaxVal = arr[secMaxIdx];
            arr[secMaxIdx] = 0;
            int restSum = (int)sum(arr);
            if(restSum % 2 == 0){
                if(maxVal > secMaxVal)
                    sb.append("T").append("\n");
                else sb.append("HL").append("\n");
            }
            else{
                if(maxVal > secMaxVal)
                    sb.append("HL").append("\n");
                else sb.append("T").append("\n");
            }

        }

        System.out.println(sb.toString());
    }

    private static long sum(int...arr){
        long sum = 0L;
        for(int a : arr)
            sum += a;
        return sum;
    }
    private static int maxIdx(int...arr){
        int maxIdx = 0;
        for(int i = 0; i < arr.length; ++i){
            if(arr[maxIdx] < arr[i]){
                maxIdx = i;
            }
        }

        return maxIdx;
    }
    private static class FastReader {
        private BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] readArray(int n){
            int[] arr = new int[n];
            for(int i = 0; i < n; ++i)
                arr[i] = nextInt();

            return arr;
        }
        long[] readLongArray(int n){
            long[] arr = new long[n];
            for(int i = 0; i < n; ++i)
                arr[i] = nextLong();

            return arr;
        }

        double[] readDoubleArray(int n){
            double[] arr = new double[n];
            for(int i = 0; i < n; ++i)
                arr[i] = nextDouble();
            return arr;
        }
    }
}

