bool dfs(int now, int f) {
  if (visited[now]) {
    return id[now] == f;
  }
  visited[now] = true;
  id[now] = f;
  counter[f]++;
  for (int i = 0; i < (int)way[now].size(); i++)
    if (dfs(way[now][i], !f) == false) return false;
  return true;
}
