  counter[0] = counter[1] = 0;
  for (int i = 0; i < m; i++) {
    scanf("%d%d", &a, &b);
    a--;
    b--;
    way[a].push_back(b);
    way[b].push_back(a);
  }
  if (!dfs(0, 0)) {
    puts("0");
