long long per[N];
long long n, m, k;
vector<long long> graph[N];
vector<long long> cycle[N];
bool mark[N];
long long w[N];
long long cnt_cycle = 0;
void dfs(long long v, long long c) {
  cycle[c].push_back(v);
  w[v] = c;
  mark[v] = true;
  for (auto u : graph[v]) {
    if (!mark[u]) {
      dfs(u, c);
    }
  }
}
int main() {
