    cin >> a[i];
  }
  for (long long i = 0; i < n - 1; i++) {
    d[i] = x[i + 1] - x[i];
  }
  for (long long i = 0; i < m; i++) {
    graph[a[i] - 2].push_back(a[i] - 1);
    graph[a[i] - 1].push_back(a[i] - 2);
  }
  for (long long i = 0; i < n - 1; i++) {
    if (!mark[i]) {
      dfs(i, cnt_cycle++);
    }
  }
