#include <bits/stdc++.h>
using namespace std;
const int sz = 51;
int dp[sz][sz];
int solve(int p1, int p2, int x[]) {
  if (p1 >= p2) return 0;
  if (dp[p1][p2] != -1) return dp[p1][p2];
  int i = p1, j = p2;
  int ans = 0, dif = ((p2 - p1) / 2) + (((p2 - p1) & 1) ? 1 : 0),
      sum = x[p1] + x[p2];
  for (; i < p1 + dif; i++, j--) {
    if (x[i] + x[j] == sum) ans++;
  }
  return dp[p1][p2] = max(solve(p1 + 1, p2, x), max(solve(p1, p2 - 1, x), ans));
}
int main() {
  int t;
  scanf("%d", &t);
  while (t--) {
    int n;
    scanf("%d", &n);
    ;
    int x[n], p1 = 0, p2 = n - 1, ans = 1;
    for (int i = 0; i < n; i++) scanf("%d", &x[i]);
    sort(x, x + n);
    while (p2 > 0) {
      int temp = 0, sum = x[p1] + x[p2], i = p1, j = p2;
      while (i < j) {
        if (x[i] + x[j] < sum) {
          i++;
          continue;
        }
        if (x[i] + x[j] > sum) {
          j--;
          continue;
        } else {
          temp++;
          i++, j--;
        }
      }
      ans = max(ans, temp);
      p2--;
    }
    cout << ans << endl;
  }
}

