#include <bits/stdc++.h>
using namespace std;
int n, m, p, d[110000], cnt, a[110000], b[110000], r[110000], f[110000];
long long ans;
int qmod(int a, int b, long long mmod) {
  int t = 1;
  while (b) {
    if (b % 2) t = 1ll * t * a % mmod;
    b /= 2;
    a = 1ll * a * a % mmod;
  }
  return t;
}
int gcd(int a, int b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}
void make(int x) {
  int q = sqrt(x);
  cnt = 0;
  for (int i = 1; i <= q; i++) {
    if (x % i) continue;
    d[++cnt] = i;
    if (i * i != x) d[++cnt] = x / i;
  }
  sort(d + 1, d + cnt + 1);
}
void solve(int x) {
  make(p - 1);
  for (int i = 1; i <= n; i++) {
    if (a[i] == 1) continue;
    for (int j = 1; j <= cnt; j++) {
      if (qmod(a[i], d[j], p) != 1) continue;
      r[i] = gcd((p - 1) / d[j], x);
      break;
    }
  }
  make(x);
  for (int i = 1; i <= n; i++) {
    if (r[i] == 0) continue;
    for (int j = 1; j <= cnt; j++)
