#include <bits/stdc++.h>
using namespace std;
const long long N = 2e5 + 5, INF = 1e18;
struct tt {
  int l, r;
  long long sum, num;
} t[N * 4];
int a[N];
int n, q;
inline void push_up(int i) { t[i].sum = t[i << 1].sum + t[i << 1 | 1].sum; }
inline void push_down(int i) {
  if (t[i].num != 0) {
    t[i << 1].num = t[i].num;
    t[i << 1 | 1].num = t[i].num;
    t[i].num = 0;
    t[i << 1].sum = (t[i << 1].r - t[i << 1].l + 1) * (long long)t[i << 1].num;
    t[i << 1 | 1].sum =
        (t[i << 1 | 1].r - t[i << 1 | 1].l + 1) * (long long)(t[i << 1]).num;
  }
}
void build(int i, int l, int r) {
  if (l == r) {
    t[i].l = t[i].r = l;
    t[i].sum = a[l];
    return;
  }
  int mid = l + r >> 1;
  build(i << 1, l, mid);
  build(i << 1 | 1, mid + 1, r);
  t[i].l = l, t[i].r = r;
  push_up(i);
}
inline void modify(int i, int l, int r, int x) {
  if (t[i].l >= l && t[i].r <= r) {
    t[i].sum = (long long)x * (t[i].r - t[i].l + 1);
    t[i].num = x;
    return;
  }
  push_down(i);
  if (t[i << 1 | 1].l <= r) modify(i << 1 | 1, l, r, x);
  if (t[i << 1].r >= l) modify(i << 1, l, r, x);
  push_up(i);
}
inline long long query(int i, int l, int r) {
  if (t[i].l >= l && t[i].r <= r) {
    return t[i].sum;
  }
  push_down(i);
  long long res = 0;
  if (t[i << 1 | 1].l <= r) res += query(i << 1 | 1, l, r);
  if (t[i << 1].r >= l) res += query(i << 1, l, r);
  return res;
}
int main() {
  cin >> n >> q;
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
  }
  build(1, 1, n);
  while (q--) {
    int op;
    scanf("%d", &op);
    op--;
    int x, y;
    scanf("%d%d", &x, &y);
    if (op) {
      int l = x, r = n;
      int cnt = 0;
      int w = query(1, n, n);
      while (y >= w && l <= n) {
        while (l <= r) {
          int mid = (l + r) >> 1;
          if (query(1, mid, mid) <= y)
            r = mid - 1;
          else
            l = mid + 1;
        }
        r = n;
        if (l > n) break;
        while (l <= r) {
          int mid = l + r >> 1;
          long long sum = query(1, l, mid);
          if (sum > y)
            r = mid - 1;
          else
            cnt += mid - l + 1, y -= sum, l = mid + 1;
        }
        r = n;
      }
      printf("%d\n", cnt);
    } else {
      int l = 1, r = x;
      while (l <= r) {
        int mid = l + r >> 1;
        if (query(1, mid, mid) > y)
          l = mid + 1;
        else
          r = mid - 1;
      }
      if (l > x) continue;
      modify(1, l, x, y);
    }
  }
}

