#include <bits/stdc++.h>
using namespace std;
int R, W[2], H[2], X[2], Y[2], L[2][501][501], d[2][501][501],
    dd[4] = {0, -1, 0, 1};
map<int, int> m[2];
map<int, int>::iterator ite;
void solve() {
  for (;;) {
    cin >> R;
    if (!R) return;
    for (int i = 0; i < (int)(2); i++) {
      cin >> W[i] >> H[i] >> X[i] >> Y[i];
      X[i]--;
      Y[i]--;
      for (int j = 0; j < (int)(H[i]); j++)
        for (int k = 0; k < (int)(W[i]); k++) cin >> L[i][j][k];
      for (int j = 0; j < (int)(H[i]); j++)
        for (int k = 0; k < (int)(W[i]); k++) d[i][j][k] = INT_MAX / 3;
      d[i][X[i]][Y[i]] = 1;
      priority_queue<pair<int, int>, vector<pair<int, int>>,
                     greater<pair<int, int>>>
          pque;
      pque.push(make_pair(1, X[i] * W[i] + Y[i]));
      while (!pque.empty()) {
        pair<int, int> p = pque.top();
        pque.pop();
        int x = p.second / W[i], y = p.second - x * W[i];
        if (d[i][x][y] < p.first) continue;
        for (int j = 0; j < (int)(4); j++) {
          int nx = x + dd[j], ny = y + dd[j ^ 1];
          if (nx < 0 || ny < 0 || nx >= H[i] || ny >= W[i]) continue;
          if (d[i][nx][ny] > max(d[i][x][y], L[i][nx][ny])) {
            d[i][nx][ny] = max(d[i][x][y], L[i][nx][ny]);
            pque.push(make_pair(d[i][nx][ny], nx * W[i] + ny));
          }
        }
      }
      for (int j = 0; j < (int)(H[i]); j++)
        for (int k = 0; k < (int)(W[i]); k++) m[i][d[i][j][k]]++;
      for (ite = m[i].begin(); ite != m[i].end(); ite++) {
        if (ite == m[i].begin()) continue;
        m[i][ite->first] += m[i][(--ite)->first];
        ite++;
      }
    }
    int mi = m[1].lower_bound(R)->first;
    for (ite = m[0].begin(); ite != m[0].end(); ite++) {
      mi = min(mi, (ite->first) + (m[1].lower_bound(R - (ite->second))->first));
    }
    cout << mi << endl;
    for (int i = 0; i < (int)(2); i++) m[i].clear();
  }
}
int main() {
  solve();
  return 0;
}

