using namespace std;
static const long double EPS = 1e-10;
double calc(double x0, double y0, double vx, double vy, double vh, double dx,
            double dy) {
  x0 -= dx;
  y0 -= dy;
  double a = vh * vh - (vx * vx + vy * vy);
  double b = -2 * (x0 * vx + y0 * vy);
  double c = -(x0 * x0 + y0 * y0);
  if (a == 0) {
    if (b == 0) {
      if (c == 0) {
        return 0.0;
      } else {
        return 1e15;
      }
    } else {
      if (-c / b < -EPS) {
        return 1e15;
      } else {
        return -c / b;
      }
    }
  } else {
    double D = b * b - 4 * a * c;
    if (D < -EPS) {
      return 1e9;
    } else {
      if (D < EPS) D = 0;
      double x1 = (-b - sqrt(D)) / (2 * a);
      double x2 = (-b + sqrt(D)) / (2 * a);
      if (x1 < 0) x1 = 1e15;
      if (x2 < 0) x2 = 1e15;
      return min(x1, x2);
    }
  }
}
