    for (int j = 1; j <= m; j++) {
      mask[i][j] = mask[i][j - 1];
      mask[i][j] ^= (1 << (M[i][j - 1] - 'a'));
      for (int k = 0; k < 26; k++) cnt[i][j][k] = cnt[i][j - 1][k];
      cnt[i][j][M[i][j - 1] - 'a']++;
    }
  }
