public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskE2 solver = new TaskE2();
            int testCount = Integer.parseInt(in.next());
            for (int i = 1; i <= testCount; i++)
                solver.solve(i, in, out);
            out.close();
        }
    }

    static class TaskE2 {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            Vote[] votes = new Vote[n];
            for (int i = 0; i < n; i++) {
                votes[i] = new Vote();
                votes[i].m = in.readInt();
                votes[i].p = in.readInt();
            }

            Arrays.sort(votes, (a, b) -> a.m - b.m);
            long total = 0;
            Deque<Vote> deque = new ArrayDeque<>(n);
            PriorityQueue<Vote> pq = new PriorityQueue<>(n, (a, b) -> -(a.p - b.p));
            for (int i = 0; i < n; i++) {
                while (!deque.isEmpty() && deque.peekFirst().m <= i) {
                    pq.add(deque.removeFirst());
                }
                if (votes[i].m <= i) {
                    if (pq.size() > 0 && pq.peek().p > votes[i].p) {
                        total -= pq.remove().p;
                        total += votes[i].p;
                        pq.add(votes[i]);
                    }
                } else {
                    if (pq.size() == 0) {
                        total += votes[i].p;
                        deque.addLast(votes[i]);
                    } else {
                        total -= pq.remove().p;
                        total += votes[i].p;
                        deque.addLast(votes[i]);
                    }
                }
            }

            out.println(total);
        }

    }

    static class FastInput {
        private final InputStream is;
        private StringBuilder defaultStringBuf = new StringBuilder(1 << 13);
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public String next() {
            return readString();
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public String readString(StringBuilder builder) {
            skipBlank();

            while (next > 32) {
                builder.append((char) next);
                next = read();
            }

            return builder.toString();
        }

        public String readString() {
            defaultStringBuf.setLength(0);
            return readString(defaultStringBuf);
        }

    }

    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(1 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(long c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

    }

    static class Vote {
        int p;
        int m;

    }
}

