		for(int i = 0; i<n-1; i++){
		    st = new StringTokenizer(br.readLine());
		    int a = Integer.parseInt(st.nextToken());
		    int b = Integer.parseInt(st.nextToken());
		    nodes.get(a).add(b);
		    nodes.get(b).add(a);
		}

		final int mod = 1000000007;
		Set<Integer> handled = new HashSet<>();
		Queue<Integer> q = new LinkedList<>();
		Queue<Map<Long,Long>> q2 = new LinkedList<>();
		q.add(1);
		q2.add(new HashMap<>());
		long sum = 0;
		while(!q.isEmpty()){
		    int curr = q.remove();
		    Map<Long,Long> curr3 = new HashMap<>();
		    curr3.put(x[curr-1], 1L);

	        sum =  (sum + x[curr-1])  % mod ;
		    for(Map.Entry<Long,Long> pair: q2.remove().entrySet()){
		        long gcd = gcd(x[curr-1], pair.getKey());
		        curr3.put(gcd, curr3.getOrDefault(gcd, 0L) + pair.getValue());
		        sum =  (sum  + ((gcd % mod)*(pair.getValue())) % mod)%mod;
		    }

		    for(Integer i : nodes.get(curr)){
		        if(handled.contains(i)) continue;
		        q.add(i);
		        q2.add(curr3);
		    }
		    handled.add(curr);
		}
		System.out.println(sum);
	}

	private static long gcd(long a, long b) {
	    long c = a;
	    long d = b;
	    if(c<d){
	        long temp = d;
	        d = c;
	        c = temp;
	    }
	    if(d ==0) return c;
	    c = c % d;
	    while(c !=0){
	        long temp = d;
	        d = c;
	        c = temp;
    	    c = c % d;
	    }
	    return d;
	}
}

