const int N = 2e5 + 500;
const int mod = 1e9 + 7;
const int INF = INT_MAX >> 1;
const ll LINF = LLONG_MAX >> 1;
const ld eps = 1e-9;
int a[1050][1050];
bool us[1050][1050];
bool wasr[1050], wasc[1050];
vector<int> row[1050], col[1050];
int dd[4][2] = {{0, 1}, {-1, 0}, {0, -1}, {1, 0}};
void bfs(int x, int y) {
  queue<pair<int, int>> q;
  q.push(make_pair(x, y));
  us[x][y] = true;
  wasr[x] |= 1, wasc[y] |= 1;
  while (!q.empty()) {
    tie(x, y) = q.front();
    q.pop();
    for (auto e : dd) {
      int tx = x + e[0], ty = y + e[1];
      if (a[tx][ty] && !us[tx][ty]) {
        us[tx][ty] = true;
        wasr[tx] |= 1, wasc[ty] |= 1;
        q.push(make_pair(tx, ty));
      }
    }
  }
}
bool solve() {
  int n, m;
  cin >> n >> m;
  for (int i = 1; i <= n; i++) {
    string s;
    cin >> s;
    for (int j = 1; j <= m; j++) {
      a[i][j] = (s[j - 1] == '#');
      if (a[i][j]) {
        row[i].emplace_back(j);
        col[j].emplace_back(i);
      }
    }
  }
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) {
      if (!(int)row[i].size() && !(int)col[j].size())
        wasr[i] |= 1, wasc[j] |= 1;
    }
  for (int i = 1; i <= n; i++) {
    sort(row[i].begin(), row[i].end());
    for (int k = 1; k < (int)row[i].size(); k++) {
      if (row[i][k] != row[i][k - 1] + 1) return false;
    }
  }
  for (int j = 1; j <= m; j++) {
    sort(col[j].begin(), col[j].end());
    for (int k = 1; k < (int)col[j].size(); k++) {
      if (col[j][k] != col[j][k - 1] + 1) return false;
    }
  }
  int ans = 0;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) {
      if (!a[i][j] || us[i][j]) continue;
      bfs(i, j);
      ans++;
    }
  for (int i = 1; i <= n; i++)
    if (!wasr[i] && ans) return false;
  for (int i = 1; i <= m; i++)
    if (!wasc[i] && ans) return false;
  cout << ans << endl;
  return true;
}
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout << fixed << setprecision(20);
  int t = 1;
  while (t--) cout << (solve() ? "" : "-1");
  return 0;
}

