import java.io.*;
import java.util.*;
public class A
{
    /******************** Pre-Processing *******************/
    private static int tin[], tout[], timer=0, N, logN, anc[][], height[];
    private static ArrayDeque<Integer> edge[];

    private static void DFS(int u, int p) //Making LCA array
    {
        tin[u]=timer++;
        anc[u][0]=p;

        for(int i=1;i<=logN;i++)
            anc[u][i]=anc[anc[u][i-1]][i-1];

        for(int v:edge[u])
        {
            if(v==p) continue;
            height[v]=height[u]+1;
            DFS(v,u);
        }

        tout[u]=timer++;
    }
    private static boolean isAncestor(int u, int v)
    {
        return tin[u]<=tin[v]&&tout[v]<=tout[u];
    }
    private static int LCA(int u, int v)
    {
        if(isAncestor(u,v)) return u;
        if(isAncestor(v,u)) return v;

        for(int i=logN;i>=0;i--)
        {
            if (!isAncestor(anc[u][i], v))
                u = anc[u][i];
        }
        return anc[u][0];
    }
    private static int dist(int u, int v){return height[u]+height[v]-2*height[LCA(u,v)];}
    private static void initLCA()
    {
        logN=Integer.numberOfTrailingZeros(Integer.highestOneBit(N));
        tin=new int[N]; tout=new int[N];
        anc=new int[N][logN+1]; height=new int[N];
    }
    /*********************** Decomposition **************************/
    private static int[] par, size;
    private static boolean[] found;

    private static int DFS2(int u, int p)
    {
        size[u]=1;
        for(int v:edge[u])
        {
            if(v==p||found[v]) continue;
            size[u]+=DFS2(v,u);
        }
        return size[u];
    }
    private static int getCentroid(int u, int p, int NN) //get the centroid of this component
    {
        for(int v:edge[u])
        {
            if(found[v]||v==p) continue;
            if(size[v]>NN/2) return getCentroid(v,u,NN);
        }
        return u;
    }
    private static void decompose(int u, int p)
    {
        u=getCentroid(u,-1,DFS2(u,u)); found[u]=true; par[u]=p;
        for(int v:edge[u]) if(!found[v]) decompose(v,u);
    }
    private static void initDecompo(){par=new int[N]; size=new int[N]; found=new boolean[N];}
    /********************* Queries *********************/
    private static int[] ans;
    private static final int INF=(int)1e8;
    private static void update(int u)
    {
        int p=u;
        while (p!=-1)
        {
            ans[p]=Math.min(ans[p], dist(u,p));
            p=par[p];
        }
    }
    private static int query(int u)
    {
        int p=u, ret=INF;
        while (p!=-1)
        {
            ret=Math.min(ret,ans[p]+dist(u,p));
            p=par[p];
        }
        return ret;
    }
    private static void initQuery()
    {
        ans=new int[N];
        Arrays.fill(ans,INF);
    }
    /*********************** Driver ************************/
    public static void main(String[] args) throws IOException
    {
        Reader r=new Reader();

        int i;

        N=r.nextInt();
        int Q=r.nextInt();
        StringBuilder sb=new StringBuilder();

        edge=new ArrayDeque[N]; for(i=0;i<N;i++) edge[i]=new ArrayDeque<>();
        for(i=0;i<N-1;i++)
        {
            int u=r.nextInt()-1;
            int v=r.nextInt()-1;

            edge[u].add(v); edge[v].add(u);
        }

        initLCA();
        DFS(0,0);

        initDecompo();
        decompose(0,-1);

        initQuery();
        update(0);

        while (Q-->0)
        {
            int type=r.nextInt();
            int u=r.nextInt()-1;

            if(type==1) update(u);
            else sb.append(query(u)).append("\n");
        }
        System.out.println(sb);
    }
    static class Reader 
    { 
        final private int BUFFER_SIZE = 1 << 16;private DataInputStream din;private byte[] buffer;private int bufferPointer, bytesRead;
        public Reader(){din=new DataInputStream(System.in);buffer=new byte[BUFFER_SIZE];bufferPointer=bytesRead=0;
        }public Reader(String file_name) throws IOException{din=new DataInputStream(new FileInputStream(file_name));buffer=new byte[BUFFER_SIZE];bufferPointer=bytesRead=0;
        }public String readLine() throws IOException{byte[] buf=new byte[64];int cnt=0,c;while((c=read())!=-1){if(c=='\n')break;buf[cnt++]=(byte)c;}return new String(buf,0,cnt);
        }public int nextInt() throws IOException{int ret=0;byte c=read();while(c<=' ')c=read();boolean neg=(c=='-');if(neg)c=read();do{ret=ret*10+c-'0';}while((c=read())>='0'&&c<='9');if(neg)return -ret;return ret;
        }public long nextLong() throws IOException{long ret=0;byte c=read();while(c<=' ')c=read();boolean neg=(c=='-');if(neg)c=read();do{ret=ret*10+c-'0';}while((c=read())>='0'&&c<='9');if(neg)return -ret;return ret;
        }public double nextDouble() throws IOException{double ret=0,div=1;byte c=read();while(c<=' ')c=read();boolean neg=(c=='-');if(neg)c = read();do {ret=ret*10+c-'0';}while((c=read())>='0'&&c<='9');if(c=='.')while((c=read())>='0'&&c<='9')ret+=(c-'0')/(div*=10);if(neg)return -ret;return ret;
        }private void fillBuffer() throws IOException{bytesRead=din.read(buffer,bufferPointer=0,BUFFER_SIZE);if(bytesRead==-1)buffer[0]=-1;
        }private byte read() throws IOException{if(bufferPointer==bytesRead)fillBuffer();return buffer[bufferPointer++];
        }public void close() throws IOException{if(din==null) return;din.close();}
    }
}

