public class Coding {

    private static BufferedReader bi = new BufferedReader(new InputStreamReader(System.in));
    private static BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
    static List<Integer> primes = new ArrayList<>();

    public static void main(String[] args) {
        try {
            run();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void run() throws Exception {
        InputModule inp = new InputModule();
        OutputModule out = new OutputModule();
        for(int i=2;i<1000;++i) {
            boolean ok = true;
            for(int j=2;j*j<=i;++j) {
                if (i%j==0) {
                    ok = false;
                    break;
                }
            }
            if (ok) primes.add(i);
        }
        int t = inp.cinInt();
        while (t > 0) {
            int n = inp.cinInt();
            int[] ar = inp.cinIntArray(n);
            int[] valL = new int[n];
            mergeSort(ar, 0, n-1);
            Map<Integer, Integer> mp = new HashMap<>();
            int oddMax = 1;
            int eveMax = 0;
            int evSum = 0;
            for(int i=0;i<n;++i) {
                if (i>0) {
                    if (ar[i]==ar[i-1]) {
                        valL[i] = valL[i-1];
                        mp.put(valL[i], mp.get(valL[i]) + 1);
                        continue;
                    }
                }
                int value = 1;
                int cur = ar[i];
                for(int j=0;j<primes.size();++j) {
                    int div = primes.get(j);
                    if (div>cur) break;
                    int ct = 0;
                    while (cur%div==0) {
                        cur/=div;
                        ct++;
                    }
                    if (ct%2==1) {
                        value = value*div;
                    }
                }
                value = value*cur;

                //System.out.println("value of " + ar[i] + " is " + value);
                valL[i] = value;
                mp.put(value, mp.getOrDefault(value, 0) + 1);
            }
            for(int val : mp.keySet()) {
                int count = mp.get(val);
                if ((count%2==1) && (val!=1)) oddMax = Math.max(oddMax, count);
                else {
                    eveMax = Math.max(eveMax, count);
                    evSum+=count;
                }
            }
            //System.out.println(oddMax + "  " + eveMax + " " + evSum);
            int q = inp.cinInt();
            while (q>0) {
                long w = inp.cinLong();
                if (w==0) out.printInt(Math.max(oddMax, eveMax));
                else out.printInt(Math.max(oddMax, evSum));
                q--;
            }
            t--;
        }
    }

    private static void mergeSort(int[] ar, int st, int en) {
        if (st>=en) {
            return;
        }
        int mi = (st+en)/2;
        mergeSort(ar, st, mi);
        mergeSort(ar, mi+1, en);
        int[] tmp = new int[en-st+1];
        int p1 = st;
        int p2 = mi+1;
        int cur = 0;
        while (p1<=mi && p2<=en) {
            if (ar[p1]<=ar[p2]) {
                tmp[cur] = ar[p1];cur++;p1++;
            } else {
                tmp[cur] = ar[p2];cur++;p2++;
            }
        }

        while (p1<=mi) {
            tmp[cur] = ar[p1];cur++;p1++;
        }

        while (p2<=en) {
            tmp[cur] = ar[p2];cur++;p2++;
        }

        for(int i=st;i<=en;++i) {
            ar[i] = tmp[i-st];
        }
    }


