#include <bits/stdc++.h>
using namespace std;
const int N = 5e5 + 2;
const int MAX = 1e5;
const long long INF = 0x3f3f3f3f3f3f3f;
const long long mod = 1e9 + 7;
int n;
int m;
int tot;
int op[N];
int in[N];
int out[N];
int que[N];
vector<int> edge[N];
void dfs(int u, int fa) {
  que[++tot] = u;
  in[u] = tot;
  for (int i = 0; i < edge[u].size(); i++) {
    int v = edge[u][i];
    if (v == fa) continue;
    dfs(v, u);
  }
  out[u] = tot;
}
struct T {
  int l, r;
  int val, amax, set;
} tr[N << 2];
void update(int rt) {
  tr[rt].amax = max(tr[rt << 1].amax, tr[rt << 1 | 1].amax);
}
void spread(int rt) {
  if (tr[rt].set != -1) {
    tr[rt << 1].val = tr[rt << 1 | 1].val = tr[rt].set;
    tr[rt << 1].set = tr[rt << 1 | 1].set = tr[rt].set;
    tr[rt << 1].amax = tr[rt << 1 | 1].amax = tr[rt].set;
    tr[rt].set = -1;
  }
}
void build(int rt, int l, int r) {
  tr[rt].l = l, tr[rt].r = r;
  if (l == r) {
    tr[rt].val = 0;
    tr[rt].set = -1;
    tr[rt].amax = 0;
    return;
  }
  int mid = (l + r) >> 1;
  build(rt << 1, l, mid);
  build(rt << 1 | 1, mid + 1, r);
  update(rt);
  return;
}
void change(int rt, int l, int r, int v) {
  if (tr[rt].l >= l && tr[rt].r <= r) {
    tr[rt].amax = v;
    tr[rt].val = v;
    tr[rt].set = v;
    return;
  }
  int mid = (tr[rt].l + tr[rt].r) >> 1;
  spread(rt);
  if (l <= mid) change(rt << 1, l, r, v);
  if (mid < r) change(rt << 1 | 1, l, r, v);
  update(rt);
}
int query(int rt, int l, int r) {
  if (tr[rt].l >= l && tr[rt].r <= r) {
    return tr[rt].amax;
  }
  int mid = (tr[rt].l + tr[rt].r) >> 1;
  spread(rt);
  int ans = 0;
  if (l <= mid) ans = max(ans, query(rt << 1, l, r));
  if (r > mid) ans = max(ans, query(rt << 1 | 1, l, r));
  return ans;
}
int main() {
  ios::sync_with_stdio(0);
  cin >> n;
  int u, v;
  for (int i = 1; i <= n - 1; i++) {
    cin >> u >> v;
    edge[u].push_back(v);
    edge[v].push_back(u);
  }
  dfs(1, 0);
  build(1, 1, n);
  cin >> m;
  for (int i = 1; i <= m; i++) {
    cin >> op[i] >> v;
    switch (op[i]) {
      case 1:
        change(1, in[v], out[v], i);
        break;
      case 2:
        change(1, in[v], in[v], i);
        break;
      case 3:
        int pos = query(1, in[v], out[v]);
        if (op[pos] == 2)
          cout << 0 << endl;
        else
          cout << 1 << endl;
    }
  }
  return 0;
}

