int main() {
  int n, m, seniority[16];
  long long y;
  long N, pre[16];
  bool state[16];
  scanf("%d%I64d%d", &n, &y, &m);
  N = (1 << n) - 1;
  y -= 2000;
  memset(pre, 0, sizeof(pre));
  while (m--) {
    int a, b;
    scanf("%d%d", &a, &b);
    pre[--b] |= 1 << --a;
  }
  memset(seniority, -1, sizeof(seniority));
  memset(state, 0, sizeof(state));
  for (int i = 0; i < n; i++)
    for (seniority[i] = 0;; seniority[i]++) {
      if (seniority[i] >= n) {
        printf("The times have changed\n");
        return 0;
      }
      if (state[seniority[i]]) continue;
      memset(f, 0, sizeof(f));
      f[0] = 1;
      for (long j = 0; j <= N; j++)
        if (f[j]) {
          int c = count(j);
          for (int k = 0; k < n; k++)
            if (!(j & (1 << k)) && (seniority[k] == -1 || seniority[k] == c) &&
                (pre[k] & j) == pre[k])
              f[j | 1 << k] += f[j];
        }
      if (y > f[N]) {
        y -= f[N];
        continue;
      } else {
        state[seniority[i]] = 1;
        break;
      }
    }
