  struct Point{
    int x,y;
    inline bool operator<(const Point&b)const{
        if(y!=b.y)return y<b.y;
        return x<b.x;
    }
  };
  namespace Hull{
    Point pivot;
    int ccw(const Point&a,const Point&b,const Point&c){
        ll area=ll(b.x-a.x)*(c.y-a.y)-ll(b.y-a.y)*(c.x-a.x);
        if(area>0)return-1;
        else if(area<0)return 1;
        return 0;
    }
    ll sqrDist(const Point&a,const Point&b){
        ll dx=a.x-b.x,dy=a.y-b.y;
        return dx*dx+dy*dy;
    }
    bool POLAR_ORDER(const Point&a,const Point&b){
        int order=ccw(pivot,a,b);
        if(order==0)return sqrDist(pivot,a)<sqrDist(pivot,b);
        return order==-1;
    }
    vector<Point>grahamScan(Point points[],int N){
        vector<Point>hull;
        if(N<3)return hull;
        int leastY=0;
        for(int i=1;i<N;i++)
            if(points[i]<points[leastY])
                leastY=i;
        Point temp=points[0];
        points[0]=points[leastY];
        points[leastY]=temp;
        pivot=points[0];
        sort(points+1,points+N,POLAR_ORDER);
        hull.push_back(points[0]);
        hull.push_back(points[1]);
        hull.push_back(points[2]);
        for(int i=3;i<N;i++){
            Point top=*hull.rbegin();
            hull.pop_back();
            while(ccw(*hull.rbegin(),top,points[i])!=-1){
                top=*hull.rbegin();
                hull.pop_back();
            }
            hull.push_back(top);
            hull.push_back(points[i]);
        }
        int sz=hull.size();
        while(sz>=3&&(ccw(hull[0],hull[sz-1],hull[sz-2])==0||ccw(hull[0],hull[1],hull[sz-1])==0))
          hull.pop_back(),sz--;
        return hull;
    }
  };
