long long int getSetBitsFromOneToN(long long int N) {
  long long int two = 2, ans = 0;
  long long int n = N;
  while (n) {
    ans += (N / two) * (two >> 1);
    if ((N & (two - 1)) > (two >> 1) - 1)
      ans += (N & (two - 1)) - (two >> 1) + 1;
    two <<= 1;
    n >>= 1;
  }
  return ans;
}
long long int power(long long int a, long long int b) {
  long long int res = 1;
  while (b > 0) {
    if (b & 1) res = res * a;
    a = a * a;
    b >>= 1;
  }
  return res;
}
long long int mod_pow(long long int a, long long int b, long long int m) {
  long long int res = 1;
  while (b) {
    if (b & 1) {
      res = (res * a) % m;
    }
    a = (a * a) % m;
    b >>= 1;
  }
  return res;
}
long long int gcd(long long int a, long long int b) {
  if (a == 0) return b;
  return gcd(b % a, a);
}
long long int lcm(long long int a, long long int b) {
  return (max(a, b) / gcd(a, b)) * min(a, b);
}
