vector<pair<int, int> > p;
void med(vector<int> &a, int l, int r, int cnt) {
  if (l < r) {
    int mid;
    if ((r - l + 1) % 2)
      mid = (l + r) / 2;
    else
      mid = (l + r - 1) / 2;
    a[mid] = cnt;
    int len = a.size() - 1;
    if (len % 2) {
      med(a, l, mid - 1, cnt + 1);
      med(a, mid + 1, r, cnt + 2);
    } else {
      med(a, l, mid - 1, cnt + 2);
      med(a, mid + 1, r, cnt + 1);
    }
  }
}
bool cmp(const pair<int, int> &a, const pair<int, int> &b) {
  int l1 = a.second - a.first + 1;
  int l2 = b.second - b.first + 1;
  if (l1 == l2) return a.first < b.first;
  return l1 > l2;
}
