using namespace std;
long a[1000000];
long n, k;
vector<long> m;
void build(long i, long s, long e) {
  if (s == e) {
    a[i] = m[s] % k;
    return;
  }
  long mid = (s + e) / 2;
  build(2 * i + 1, s, mid);
  build(2 * i + 2, mid + 1, e);
  a[i] = (a[2 * i + 1] * a[2 * i + 2]) % k;
}
long query(long i, long s, long e, long l, long r) {
  if (s > r || l > e) return 1;
  if (s >= l && r >= e) return a[i];
  long mid = (s + e) / 2;
  return (query(2 * i + 1, s, mid, l, r) * query(2 * i + 2, mid + 1, e, l, r)) %
         k;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> k;
  m.resize(n);
  for (long i = 0; i < n; i++) cin >> m[i];
  build(0, 0, n - 1);
  long ans = 0;
  for (long i = 0; i < n; i++) {
    long l = i, h = n, mid;
    while (h - l > 1) {
      mid = (h + l) / 2;
      if (query(0, 0, n - 1, i, mid) == 0)
        h = mid;
      else
        l = mid;
    }
    if (query(0, 0, n - 1, i, l) == 0)
      ans += (n - l);
    else
      ans += (n - h);
  }
  cout << ans;
}

