using namespace std;
namespace std {
bool operator<(const complex<double> &a, const complex<double> &b) {
  return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
}
}  // namespace std
struct L : public vector<complex<double> > {
  L(const complex<double> &a, const complex<double> &b) {
    push_back(a);
    push_back(b);
  }
};
double cross(const complex<double> &a, const complex<double> &b) {
  return imag(conj(a) * b);
}
double dot(const complex<double> &a, const complex<double> &b) {
  return real(conj(a) * b);
}
int ccw(complex<double> a, complex<double> b, complex<double> c) {
  b -= a;
  c -= a;
  if (cross(b, c) > 0) return +1;
  if (cross(b, c) < 0) return -1;
  if (dot(b, c) < 0) return +2;
  if (norm(b) < norm(c)) return -2;
  return 0;
}
bool intersectLL(const L &l, const L &m) {
  return abs(cross(l[1] - l[0], m[1] - m[0])) > 1e-10 ||
         abs(cross(l[1] - l[0], m[0] - l[0])) < 1e-10;
}
bool intersectLS(const L &l, const L &s) {
  return cross(l[1] - l[0], s[0] - l[0]) * cross(l[1] - l[0], s[1] - l[0]) <
         1e-10;
}
bool intersectLP(const L &l, const complex<double> &p) {
  return abs(cross(l[1] - p, l[0] - p)) < 1e-10;
}
bool intersectSS(const L &s, const L &t) {
  return ccw(s[0], s[1], t[0]) * ccw(s[0], s[1], t[1]) <= 0 &&
         ccw(t[0], t[1], s[0]) * ccw(t[0], t[1], s[1]) <= 0;
}
bool intersectSP(const L &s, const complex<double> &p) {
  return abs(s[0] - p) + abs(s[1] - p) - abs(s[1] - s[0]) < 1e-10;
}
complex<double> projection(const L &l, const complex<double> &p) {
  double t = dot(p - l[0], l[0] - l[1]) / norm(l[0] - l[1]);
  return l[0] + t * (l[0] - l[1]);
}
complex<double> reflection(const L &l, const complex<double> &p) {
  return p + (projection(l, p) - p) * 2.0;
}
double distanceLP(const L &l, const complex<double> &p) {
  return abs(p - projection(l, p));
}
double distanceLL(const L &l, const L &m) {
  return intersectLL(l, m) ? 0 : distanceLP(l, m[0]);
}
double distanceLS(const L &l, const L &s) {
  if (intersectLS(l, s)) return 0;
  return min(distanceLP(l, s[0]), distanceLP(l, s[1]));
}
double distanceSP(const L &s, const complex<double> &p) {
  const complex<double> r = projection(s, p);
  if (intersectSP(s, r)) return abs(r - p);
  return min(abs(s[0] - p), abs(s[1] - p));
}
double distanceSS(const L &s, const L &t) {
  if (intersectSS(s, t)) return 0;
  return min(min(distanceSP(s, t[0]), distanceSP(s, t[1])),
             min(distanceSP(t, s[0]), distanceSP(t, s[1])));
}
complex<double> crosspoint(const L &l, const L &m) {
  double A = cross(l[1] - l[0], m[1] - m[0]);
  double B = cross(l[1] - l[0], l[1] - m[0]);
  return m[0] + B / A * (m[1] - m[0]);
}
L crosspointSS(complex<double> p1, int r1, complex<double> p2, int r2) {
  double d = norm(p2 - p1);
  double t = r2 * r2 - r1 * r1 - d;
  double aa = d, bb = t * (real(p2) - real(p1)),
         cc = t * t / 4.0 -
              (imag(p2) - imag(p1)) * (imag(p2) - imag(p1)) * r1 * r1;
  double x1 = (-bb - sqrt(bb * bb - 4 * aa * cc)) / (2 * aa),
         x2 = (-bb + sqrt(bb * bb - 4 * aa * cc)) / (2 * aa);
  double y1, y2;
  if (imag(p1) == imag(p2)) {
    y1 = -sqrt(r1 * r1 - x1 * x1);
    y2 = -y1;
  } else {
    y1 = (t + 2 * (real(p2) - real(p1)) * x1) / (-2 * (imag(p2) - imag(p1)));
    y2 = (t + 2 * (real(p2) - real(p1)) * x2) / (-2 * (imag(p2) - imag(p1)));
  }
  L ln = L(complex<double>(x1 + real(p1), y1 + imag(p1)),
           complex<double>(x2 + real(p1), y2 + imag(p1)));
  return ln;
}
vector<complex<double> > convex_hull(vector<complex<double> > ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  vector<complex<double> > ch(2 * n);
  for (int i = 0; i < n; ch[k++] = ps[i++]) {
    while (k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) k--;
  }
  for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) {
    while (k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) k--;
  }
  ch.resize(k - 1);
  return ch;
}
bool isconvex(const vector<complex<double> > &ps) {
  for (int i = 0; i < ps.size(); ++i) {
    if (ccw(ps[(i + ps.size() - 1) % ps.size()], ps[i],
            ps[(i + 1) % ps.size()]))
      return false;
  }
  return true;
}
double area(const vector<complex<double> > &ps) {
  double A = 0;
  for (int i = 0; i < ps.size(); ++i) {
    A += cross(ps[i], ps[(i + 1) % ps.size()]);
  }
  return A / 2.0;
}
vector<complex<double> > convex_cut(const vector<complex<double> > &ps,
                                    const L &l) {
  vector<complex<double> > Q;
  for (int i = 0; i < ps.size(); ++i) {
    complex<double> A = ps[i], B = ps[(i + 1) % ps.size()];
    if (ccw(l[0], l[1], A) != -1) Q.push_back(A);
    if (ccw(l[0], l[1], A) * ccw(l[0], l[1], B) < 0)
      Q.push_back(crosspoint(L(A, B), l));
  }
  return Q;
}
int main() {
  int n;
  cin >> n;
  vector<complex<double> > vec;
  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    vec.push_back(complex<double>(x, y));
  }
  int q;
  cin >> q;
  for (int i = 0; i < q; ++i) {
    vector<complex<double> > res;
    int w, x, y, z;
    cin >> w >> x >> y >> z;
    res = convex_cut(vec, L(complex<double>(w, x), complex<double>(y, z)));
    printf("%.10f\n", area(res));
  }
}

