template<typename T>
inline T max(const T &a,const T &b){
	return a>b?a:b;
}

template<typename T>
inline void swap(T &a,T &b){
	T tmp = a;a = b;b = tmp;
}

template<typename T>
inline T min(const T &a,const T &b){
	return a<b?a:b;
}

int n,m,f[maxn],phi[S];ll a[maxn],tag[S];

inline int where(int x){return (x-1)/S+1 ;}

inline int L(int id){return (id-1)*S+1;}
inline int R(int id){return min(id*S,n);}

inline int trans(int x){return max(a[x]-tag[where(x)],1ll);}

inline int Trans(int x){
	if(phi[where(x)]>=S) return trans(x) ;
	return f[x] ;
}

void rebuild(int id){
	if(phi[id]>=S) return ;
	for(int i=L(id);i<=R(id);i++){
		if(where(i)!=where(trans(i))) f[i] = trans(i);
		else
			f[i] = Trans(trans(i));
	}
}

void init(){
	f[1] = a[1] = 1;
	for(int i=1;i<=where(n);i++)
		rebuild(i);
}

int Pepper(int u,int v){
	while(Trans(u)!=Trans(v) && u!=1){
		if(Trans(u)<Trans(v)) swap(u,v);
		u = Trans(u);
	}
	while(trans(u)!=trans(v) && u!=1){
		if(trans(u)<trans(v)) swap(u,v);
		u = trans(u);
	}
	return u==v?u:trans(u) ;
}

void modify(int l,int r,const int &key){
	int idl = where(l) , idr = where(r) ;
	if(idl==idr){
		for(int i=l;i<=r;i++) a[i] -= key;
		return rebuild(idl) ;
	}
	for(int i=l;i<=R(idl);i++) a[i] -= key;
	rebuild(idl);
	for(int i=L(idr);i<=r;i++) a[i] -= key;
	rebuild(idr);
	for(int i=idl+1;i<idr;i++){
		tag[i] += key;
		if(phi[i]<S)
			rebuild(i),phi[i] ++ ;
	}
}

int main(){
	scanf("%d%d",&n,&m);for(int i=2;i<=n;i++) scanf("%lld",&a[i]);
	init();
	while(m--){
		int type ;scanf("%d",&type) ;
		if(type == 1){
			int l,r,key;scanf("%d%d%d",&l,&r,&key);
			modify(l,r,key);
		}
		if(type == 2){
			int u,v;scanf("%d%d",&u,&v);
			printf("%d\n",Pepper(u,v)) ;
		}
	}
	return 0 ;
}

