  map<pair<int, int>, int> done;
  for (int i = 1; i <= n; i++) {
    odds.push_back({i, n / 2 + 1});
    done[{i, n / 2 + 1}] = 1;
  }
  for (int j = 1; j <= n; j++) {
    if (!done[{n / 2 + 1, j}]) odds.push_back({n / 2 + 1, j});
