        odds.push_back({i, n - j + 1});
        done[{i, n - j + 1}] = 1;
      }
      if (!done[{n - i + 1, j}]) {
        odds.push_back({n - i + 1, j});
        done[{n - i + 1, j}] = 1;
      }
      if (!done[{n - i + 1, n - j + 1}]) {
        odds.push_back({n - i + 1, n - j + 1});
        done[{n - i + 1, n - j + 1}] = 1;
      }
      i++;
      j++;
    }
  }
  for (int i = 0, k = 1; k <= n * n; k += 2, i++) {
    int x = odds[i].first;
    int y = odds[i].second;
    ara[x][y] = k;
  }
  for (int i = 1, k = 2; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      if (!ara[i][j]) {
        ara[i][j] = k;
        k += 2;
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) cout << ara[i][j] << " ";
    cout << "\n";
  }
}
