public class Main {
	public static void main(String[] args) {
		InputReader in = new InputReader();
		StringBuilder out = new StringBuilder();

		int T = in.nextInt();
		while (T-- > 0) {
			int N = in.nextInt();
			int D = in.nextInt();
			int lb, x;
			lb = x = 0;
			for (int i = 2; i <= N; i++) {
				if ((i & (i - 1)) == 0) {
					x++;
				}
				lb += x;
			}
			if (D < lb || N * (N - 1) / 2 < D) {
				out.append("NO\n");
				continue;
			}
			int[] par = new int[N + 1];
			int[] deg = new int[N + 1];
			List<Integer>[] dep = new List[N];
			for (int i = 0; i < N; i++) {
				dep[i] = new ArrayList<>();
				dep[i].add(i + 1);
			}
			for (int i = 2; i <= N; i++) {
				par[i] = i - 1;
			}
			Arrays.fill(deg, 1);
			deg[N] = 0;
			int now, cur_depth;
			now = cur_depth = -1;
			int sum = N * (N - 1) / 2;
			while (sum > D) {
				for (int i = N - 1; now == -1; i--) {
					Iterator<Integer> it = dep[i].iterator();
					while (it.hasNext()) {
						x = it.next();
						if (deg[x] == 0) {
							now = x;
							cur_depth = i;
							break;
						}
					}
				}
				boolean flag = false;
				dep[cur_depth].remove((Integer)now);
				cur_depth--;
				dep[cur_depth].add(now);
				for (int y : dep[cur_depth - 1]) {
					if (deg[y] < 2) {
						deg[par[now]]--;
						par[now] = y;
						deg[y]++;
						flag = true;
						break;
					}
				}
				if (flag) {
					sum--;
				} else {
					dep[cur_depth].remove((Integer)now);
					dep[cur_depth + 1].add(now);
					now = -1;
				}
				if (cur_depth == 1) {
					now = -1;
				}
			}
			out.append("YES\n");
			for (int i = 2; i <= N; i++) {
				out.append(par[i]).append(' ');
			}
			out.setCharAt(out.length() - 1, '\n');
		}

		System.out.print(out);
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer st;

		public InputReader() {
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				st = new StringTokenizer(nextLine());
			}
			return st.nextToken();
		}

		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return null;
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}
	}
