def dfs(v,adj,curr_min,visited,data):
	# stack = v, curr_min, balance, total,neig_i
	stack = [[v,data[v][0],data[v][2]-data[v][1],abs(data[v][2]-data[v][1]),0]]
	res = 0
	balance = 0
	while stack:
		v, curr_min, curr_balance, curr_total,neig_i = stack[-1]
		curr_min = min(curr_min,data[v][0])
		stack[-1][1] = curr_min
		visited[v] = True
		if neig_i == 0:
			balance = curr_balance
			total = curr_total
		else:
			curr_balance += balance
			curr_total += abs(balance)
			stack[-1][2] = curr_balance
			stack[-1][3] = curr_total


		while neig_i < len(adj[v]):
			u = adj[v][neig_i]
			if visited[u]:
				neig_i+=1
				continue
			stack[-1][4] = neig_i +1
			stack.append([u,min(curr_min,data[u][0]),data[u][2]-data[u][1],abs(data[u][2]-data[u][1]),0])
			break
		if neig_i == len(adj[v]):
			stack.pop()
			# print(curr_min,v,total,balance)
			res+=curr_min * (curr_total-abs(curr_balance))
		balance = curr_balance
