	void ax(int x,int a){
		//贡献 ax
		add(S,x,a);
	}
	void a1_x(int x,int a){
		//贡献 a(1-x)
		add(x,T,a);
	}
	void cx1_y(int x,int y,int c){
		//贡献 cx(1-y)
		add(y,x,c);
	}
	int q[N],dis[N];
	int bfs(){
		rep(i,1,T)dis[i]=-1;
		q[q[0]=1]=S;
		dis[S]=0;
		rep(i,1,q[0]){
			int x=q[i];
			for(int u=head[x];u;u=np[u])if(dis[p[u]]==-1)if(flow[u]){
				dis[p[u]]=dis[x]+1;
				q[++q[0]]=p[u];
			}
		}
		return dis[T];
	}
	int dinic(int x,int ff){
		int res=0;
		if(x==T)return ff;
		for(int u=head[x];u;u=np[u])if(dis[p[u]]==dis[x]+1)if(flow[u]){
			int ret=dinic(p[u],min(ff,flow[u]));
			flow[u]-=ret;
			flow[u^1]+=ret;
			ff-=ret;
			res+=ret;
			if(!ff)break;
		}
		if(!res)dis[x]=-1;
		return res;
	}
	int calc(){
		int ans=0;
		while(bfs()!=-1)ans+=dinic(S,1e9);
		return ans;
	}
};
const int N=45;
int n,m,ca,cb,cc;
char s[N][N];
