bool ok[252][252][252];
long long pwr(long long a, long long b) {
  if (b == 0) return 1;
  long long p = pwr(a, b / 2);
  if (b & 1) return p * a % 123457 * p % 123457;
  return p * p % 123457;
}
long long v[252];
long long lg1[252], lg2[252];
long long manaher() {
  long long ans = 0;
  memset(lg1, 0, sizeof(lg1));
  memset(lg2, 0, sizeof(lg2));
  long long pog = -1, p = -1, pt = 0;
  for (int i = 1; i <= n; i++)
    if (v[i] != -1) {
      lg1[i] = 1;
      lg2[i] = 0;
      if (i <= pog) lg1[i] = min(lg1[p - (i - p) + pt], pog - i + 1);
      if (i < pog) lg2[i] = min(lg2[p - (i - p) - !pt], pog - i);
      while (i - lg1[i] >= 1 && i + lg1[i] <= n &&
             v[i - lg1[i]] == v[i + lg1[i]] && v[i - lg1[i]] != -1)
        lg1[i]++;
      while (i - lg2[i] >= 1 && i + lg2[i] + 1 <= n &&
             v[i - lg2[i]] == v[i + lg2[i] + 1] && v[i - lg1[i]] != -1)
        lg2[i]++;
      if (i + lg1[i] - 1 > pog) {
        pog = i + lg1[i] - 1;
        p = i;
        pt = 0;
      }
      if (i + lg2[i] > pog) {
        pog = i + lg2[i];
        p = i;
        pt = 1;
      }
      ans += lg1[i] + lg2[i];
    }
  return ans;
}
