    iota(depth.begin(), depth.end(), 0);
    int cur = (n * (n - 1)) / 2;
    while (cur > d) {
      int v = -1;
      for (int i = 0; i < n; i++) {
        if (bad[i] == 0 && cnt[i] == 0 && (v == -1 || depth[v] > depth[i])) {
