using namespace std;
const int maxn = 100000;
struct node {
  node *p;
  int l, dp[4];
  node *trans[4];
  node() {
    l = 0;
    p = NULL;
  }
  node(int _l, node *_p) {
    l = _l;
    p = _p;
    memset(trans, 0, sizeof(trans));
    fill(dp, dp + 4, maxn);
  }
};
node *root;
void build_SAM(char *A) {
  node *curnode;
  root = curnode = new node(0, NULL);
  for (int i = 0; A[i]; i++) {
    int x = A[i] - 'A';
    node *p = curnode;
    curnode = new node(i + 1, NULL);
    for (; p && p->trans[x] == NULL; p = p->p) p->trans[x] = curnode;
    if (!p)
      curnode->p = root;
    else {
      node *q = p->trans[x];
      if (q->l == p->l + 1)
        curnode->p = q;
      else {
        node *r = new node();
        r[0] = q[0];
        r->l = p->l + 1;
        q->p = r;
        curnode->p = r;
        for (; p && p->trans[x] == q; p = p->p) p->trans[x] = r;
      }
    }
  }
}
char s[maxn];
void DP(node *u) {
  if (u->dp[0] != maxn) return;
  for (int i = 0; i < 4; i++) {
    if (!u->trans[i])
      u->dp[i] = 1;
    else
      DP(u->trans[i]);
  }
  for (int i = 0; i < 4; i++)
    if (u->trans[i])
      for (int j = 0; j < 4; j++)
        u->dp[j] = min(u->dp[j], u->trans[i]->dp[j] + 1);
}
struct P {
  unsigned long long a[4][4];
};
P operator+(const P &x, const P &y) {
  P z;
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 4; j++) {
      z.a[i][j] = 18446744073709551615ULL;
      for (int k = 0; k < 4; k++)
        z.a[i][j] = min(z.a[i][j], x.a[i][k] + y.a[k][j]);
    }
  return z;
}
P len[63];
unsigned long long getlen(unsigned long long x) {
  P p;
  memset(p.a, 0, sizeof(p.a));
  for (int i = 0; i < 63 && x; i++)
    if (x & (1LL << i)) p = p + len[i], x ^= (1LL << i);
  unsigned long long ret = 18446744073709551615ULL;
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 4; j++) ret = min(ret, p.a[i][j]);
  return ret;
}
int main() {
  unsigned long long n;
  scanf("%I64u%s", &n, s);
  if (n == 1) {
    printf("1\n");
    return 0;
  }
  build_SAM(s);
  DP(root);
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 4; j++) len[0].a[i][j] = root->trans[i]->dp[j];
  for (int i = 1; i < 64; i++) len[i] = len[i - 1] + len[i - 1];
  unsigned long long l = 0, r = n - 1;
  while (r - l > 1) {
    unsigned long long mid = (r + l) / 2;
    if (getlen(mid) >= n - 1)
      r = mid;
    else
      l = mid;
  }
  printf("%I64u\n", r + 1);
}

