int mx[2][maxN];
int mi[2][maxN];
vector<int> ans;
int cnt;
void solve(int s, int e) {
  if (e - s < 0) return;
  int cur = cnt++;
  if (cur != s) {
    puts("IMPOSSIBLE");
    exit(0);
  }
  if (e - s == 0) {
    ans.push_back(cur);
    return;
  }
  solve(s + 1, mx[0][s]);
  if (mi[1][s] < cnt) {
    puts("IMPOSSIBLE");
    exit(0);
  }
  ans.push_back(cur);
  solve(cnt, max(mx[1][s], e));
}
