	public static Map<Pair, Integer> getDiffs(int[][] tree)
	{
		Map<Pair, Integer> weight = new HashMap<Pair, Integer>();
		Map<Pair, Integer> bestSplit = new HashMap<>();
		Map<Pair, Integer> diff = new HashMap<>();
		Deque<Pair> stack = new ArrayDeque<>();
		// Initialize stack with root edges
		int root = 1;
		for (int u : tree[root])
		{
			Pair p = new Pair(root, u);
			stack.addFirst(p);
		}
		while (!stack.isEmpty())
		{
			Pair p = stack.peekFirst();
			// Have we processed the children yet?
			if (!weight.containsKey(p))
			{
				// Placeholder value as visited flag
				weight.put(p, 0);
				bestSplit.put(p, weight.get(p));
				// Push the children
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						stack.addFirst(new Pair(u, v));
					}
				}
			}
			else
			{
				stack.removeFirst();
				// Sum the child weights
				int count = 1;
				int best = 0;
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						count += weight.get(new Pair(u, v));
						int w = bestSplit.get(new Pair(u, v));
						// Can't be a best edge of branch if w > n/2, no need to check
						best = (w > best) ? w : best;
					}
				}
				weight.put(p, count);
				weight.put(p.reverse(), tree.length - 1 - count);
				if (count > (tree.length - 1)/2)
				{
					bestSplit.put(p, best);
				}
				diff.put(p, weight.get(p) - bestSplit.get(p));
			}
		}
		// In-tree edges
		Queue<Pair> queue = new ArrayDeque<>();
		for (int u : tree[root])
		{
			Pair p = new Pair(u, root);
			queue.add(p);
		}
		while (!queue.isEmpty())
		{
			Pair p = queue.remove();
			if (weight.get(p) <= (tree.length - 1)/2)
			{
				bestSplit.put(p, weight.get(p));
				diff.put(p, weight.get(p) - bestSplit.get(p));
			}
			else
			{
				int best = 0;
				// Investigate the best edges of all out-branches, pick the one that maxes weight
				// i.e. in-edge towards the root, out-edges from v back down -- all are already evaluated
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						int w = bestSplit.get(new Pair(u, v));
						// Can't be a best edge of branch if w > n/2, no need to check
						if (w >= best)
						{
							best = w;
						}
					}
				}
				bestSplit.put(p, best);
				diff.put(p, weight.get(p) - bestSplit.get(p));
			}
			// Enqueue child in-tree edges
			for (int u : tree[p.u])
			{
				if (u != p.v)
				{
					Pair q = new Pair(u, p.u);
					queue.add(q);
				}
			}
		}
		return weight;
	}


	public static Map<Pair, Integer> countVertices(int[][] tree)
	{
		Map<Pair, Integer> weight = new HashMap<Pair, Integer>();
		Deque<Pair> stack = new ArrayDeque<>();
		// Initialize stack with root edges
		int root = 1;
		for (int u : tree[root])
		{
			Pair p = new Pair(root, u);
			stack.addFirst(p);
		}
		while (!stack.isEmpty())
		{
			Pair p = stack.peekFirst();
			// Have we processed the children yet?
			if (!weight.containsKey(p))
			{
				// Placeholder value as visited flag
				weight.put(p, 0);
				// Push the children
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						stack.addFirst(new Pair(u, v));
					}
				}
			}
			else
			{
				stack.removeFirst();
				// Sum the child weights
				int count = 1;
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						count += weight.get(new Pair(u, v));
					}
				}
				weight.put(p, count);
				weight.put(p.reverse(), tree.length - 1 - count);
			}
		}
		return weight;
	}

	public static Map<Pair, Integer> findBestSplits(int[][] tree,
			Map<Pair, Integer> weight)
	{
		Map<Pair, Integer> bestSplit = new HashMap<>();
		Deque<Pair> stack = new ArrayDeque<>();
		// Initialize stack with root edges
		int root = 1;
		for (int u : tree[root])
		{
			Pair p = new Pair(root, u);
			stack.addFirst(p);
		}
		// Find for out-tree pairs first
		while (!stack.isEmpty())
		{
			Pair p = stack.peekFirst();
			// Have we processed the children yet?
			if (!bestSplit.containsKey(p))
			{
				// Default value as visited flag
				bestSplit.put(p, weight.get(p));
				// Push the children
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						stack.addFirst(new Pair(u, v));
					}
				}
			}
			else
			{
				stack.removeFirst();
				// Only need to check children if p isn't good
				if (weight.get(p) > (tree.length - 1)/2)
				{
					int best = 0;
					// Investigate the best edges of all out-branches, pick the one that maxes weight
					int u = p.v, prev = p.u;
					for (int v : tree[u])
					{
						if (v != prev)
						{
							int w = bestSplit.get(new Pair(u, v));
							// Can't be a best edge of branch if w > n/2, no need to check
							if (w > best)
							{
								best = w;
							}
						}
					}
					bestSplit.put(p, best);
				}
			}
		}
		// In-tree edges
		Queue<Pair> queue = new ArrayDeque<>();
		for (int u : tree[root])
		{
			Pair p = new Pair(u, root);
			queue.add(p);
		}
		while (!queue.isEmpty())
		{
			Pair p = queue.remove();
			if (weight.get(p) <= (tree.length - 1)/2)
			{
				bestSplit.put(p, weight.get(p));
			}
			else
			{
				int best = 0;
				// Investigate the best edges of all out-branches, pick the one that maxes weight
				// i.e. in-edge towards the root, out-edges from v back down -- all are already evaluated
				int u = p.v, prev = p.u;
				for (int v : tree[u])
				{
					if (v != prev)
					{
						int w = bestSplit.get(new Pair(u, v));
						// Can't be a best edge of branch if w > n/2, no need to check
						if (w >= best)
						{
							best = w;
						}
					}
				}
				bestSplit.put(p, best);
			}
			// Enqueue child in-tree edges
			for (int u : tree[p.u])
			{
				if (u != p.v)
				{
					Pair q = new Pair(u, p.u);
					queue.add(q);
				}
			}
		}
		return bestSplit;
	}

