vector<vector<int> > move(const vector<vector<int> > &a, int y, int x, int co) {
  vector<vector<int> > b = a;
  int f[4][4] = {};
  if (++b[y][x] == 5) {
    b[y][x] = 0;
    f[y][x] = (1 << 4) - 1;
  }
  while (1) {
    bool update = 0;
    int pf[4][4];
    for (int i = 0; i < (int)4; i++)
      for (int j = 0; j < (int)4; j++) pf[i][j] = f[i][j], f[i][j] = 0;
    for (int i = 0; i < (int)4; i++)
      for (int j = 0; j < (int)4; j++)
        if (pf[i][j]) {
          update = 1;
          for (int d = 0; d < (int)4; d++)
            if (pf[i][j] & 1 << d) {
              int ny = i + dy[d], nx = j + dx[d];
              if (ny < 0 || nx < 0 || ny >= 4 || nx >= 4) continue;
              f[ny][nx] |= 1 << d;
            }
        }
    if (!update) break;
    for (int i = 0; i < (int)4; i++)
      for (int j = 0; j < (int)4; j++)
        if (b[i][j]) {
          b[i][j] += __builtin_popcount(f[i][j]);
          if (b[i][j] >= 5) {
            b[i][j] = 0;
            f[i][j] = (1 << 4) - 1;
          } else
            f[i][j] = 0;
        }
  }
