long long parsemask(long long m, bool pr = false) {
  for (int i = 0; i < n; i++) c[i] = 0;
  for (int i = 0; i < n; i++) {
    long long idx = (m & ((1LL << (4 * (i + 1))) - 1)) >> (4 * i);
    mas[idx][c[idx]++] = i;
  }
  int cntline = 0;
  for (int idx = 0; idx < n; idx++) {
    if (c[idx] != 0) {
      if (idx != cntline) {
        swap(c[idx], c[cntline]);
        for (int i = 0; i < c[cntline]; i++) swap(mas[idx][i], mas[cntline][i]);
      }
      cntline++;
    }
  }
  for (int idx = 0; idx < cntline; idx++) {
    for (int i = 0; i < c[idx]; i++) {
      for (int j = i + 1; j < c[idx]; j++) {
        if (mas[idx][i] > mas[idx][j]) swap(mas[idx][i], mas[idx][j]);
      }
    }
  }
  for (int idx1 = 0; idx1 < cntline; idx1++) {
    for (int idx2 = idx1 + 1; idx2 < cntline; idx2++) {
      if (mas[idx1][0] > mas[idx2][0]) {
        int maxlen = max(c[idx1], c[idx2]);
        for (int i = 0; i < maxlen; i++) {
          swap(mas[idx1][i], mas[idx2][i]);
        }
        swap(c[idx1], c[idx2]);
      }
    }
  }
  if (pr) {
    for (int i = 0; i < cntline; i++) {
      if (i != 0) printf(",");
      printf("{");
      for (int j = 0; j < c[i]; j++) {
