        printf("%d", mas[i][j] + 1);
      }
      printf("}");
    }
    printf("\n");
    return 0;
  }
  long long res = 0;
  for (int i = 0; i < cntline; i++) {
    for (int j = 0; j < c[i]; j++) {
      int val = mas[i][j];
      res += ((long long)i << (val << 2));
    }
  }
  return res;
}
