#include <bits/stdc++.h>
using namespace std;
const int Zero1(0);
const pair<bool, int> Zero2(make_pair(false, 0));
struct Node {
  int sum;
  pair<bool, int> lazy;
  Node() : sum(Zero1) { lazy = Zero2; }
};
struct lazy_segtree {
  int N;
  vector<Node> dat;
  lazy_segtree(int n) : N(1) {
    while (N < n) N *= 2;
    dat.resize(2 * N);
  }
  pair<bool, int> lazy_connect(const pair<bool, int> l,
                               const pair<bool, int> r) {
    if (l.first || r.first)
      return make_pair(1, -1);
    else {
      return make_pair(0, l.second + r.second);
    }
  }
  void lazy_func(const int k, const int a, const int b) {
    if (dat[k].lazy.first)
      dat[k].sum = 0;
    else {
      dat[k].sum += dat[k].lazy.second * (b - a + 1);
    }
  }
  int connect(const int l, const int r) { return l + r; }
  inline void lazy_evaluate_node(int k, int a, int b) {
    lazy_func(k, a, b);
    if (k < N) {
      dat[2 * k].lazy = lazy_connect(dat[2 * k].lazy, dat[k].lazy);
      dat[2 * k + 1].lazy = lazy_connect(dat[2 * k + 1].lazy, dat[k].lazy);
    }
    dat[k].lazy = Zero2;
  }
  inline void update_node(int k) {
    dat[k].sum = connect(dat[2 * k].sum, dat[2 * k + 1].sum);
  }
  void update(int l, int r, pair<bool, int> v, int k = 1, int a = 1,
              int b = -1) {
    if (b == -1) b = N;
    if (l < 0 || r < 0) assert(false);
    lazy_evaluate_node(k, a, b);
    if (b < l || r < a) return;
    if (l <= a && b <= r) {
      dat[k].lazy = lazy_connect(dat[k].lazy, v);
      lazy_evaluate_node(k, a, b);
      return;
    }
    int m = (a + b) / 2;
    update(l, r, v, 2 * k, a, m);
    update(l, r, v, 2 * k + 1, m + 1, b);
    update_node(k);
  }
  int get(int l, int r, int k = 1, int a = 1, int b = -1) {
    if (b == -1) b = N;
    if (l < 0 || r < 0) assert(false);
    lazy_evaluate_node(k, a, b);
    if (b < l || r < a) return Zero1;
    if (l <= a && b <= r) {
      return dat[k].sum;
    }
    int m = (a + b) / 2;
    int vl = get(l, r, 2 * k, a, m);
    int vr = get(l, r, 2 * k + 1, m + 1, b);
    update_node(k);
    return connect(vl, vr);
  }
};
struct query {
  int type;
  long long int a;
  long long int b;
};
template <typename T>
struct Compress {
  map<T, int> mp;
  map<int, T> revmp;
  Compress(vector<T> vs) { setmp(vs); }
  Compress() : mp(), revmp() {}
  void setmp(vector<T> vs) {
    sort(vs.begin(), vs.end());
    vs.erase(unique(vs.begin(), vs.end()), vs.end());
    for (int i = 0; i < static_cast<int>(vs.size()); ++i) {
      mp[vs[i]] = i;
      revmp[i] = vs[i];
    }
  }
};
int main() {
