          qs.push_back(query{a, k, -1});
        } else if (a == 3) {
          int x, r;
          cin >> x >> r;
          xs.push_back(nowdis + x + r);
          xs.push_back(nowdis + x - r);
          qs.push_back(query{a, nowdis + x - r, nowdis + x + r});
        } else if (a == 4) {
          int k;
          cin >> k;
          qs.push_back(query{a, k, -1});
        }
      }
      cp.setmp(xs);
    }
    lazy_segtree seg(cp.mp.size());
    long long int nowx = 0;
    for (auto q : qs) {
      switch (q.type) {
        case 0:
          seg.update(cp.mp[nowx + L] + 1, cp.mp[nowx + L] + 1, make_pair(0, 1));
          break;
        case 1: {
