          int amax = 3e5;
          while (amin + 1 != amax) {
            int amid((amin + amax) / 2);
            if (seg.get(cp.mp[nowx] + 2, cp.mp[nowx] + 2 + amid) >= q.a) {
              amax = amid;
            } else {
              amin = amid;
            }
          }
          if (amax != 3e5) {
            cout << "hit" << endl;
            seg.update(cp.mp[nowx] + 1 + amax, cp.mp[nowx] + 1 + amax,
                       make_pair(0, -1));
          } else {
            cout << "miss" << endl;
          }
        } break;
        case 3: {
          int bomb = seg.get(cp.mp[q.a] + 1, cp.mp[q.b] + 1);
          cout << "bomb " << bomb << endl;
          seg.update(cp.mp[q.a] + 1, cp.mp[q.b] + 1, make_pair(1, -1));
        } break;
        case 4: {
          int amin = -1;
          int amax = 3e5;
          while (amin + 1 != amax) {
            int amid((amin + amax) / 2);
            if (seg.get(cp.mp[nowx] + 2, cp.mp[nowx] + 2 + amid) >= q.a) {
              amax = amid;
            } else {
              amin = amid;
            }
          }
          if (amax != 3e5) {
            long long int dis = cp.revmp[cp.mp[nowx] + 1 + amax] - nowx;
            cout << "distance " << dis << endl;
          } else {
            cout << "distance -1" << endl;
          }
        } break;
        default:
          assert(false);
          break;
      }
    }
    cout << "end" << endl;
  }
  return 0;
}

