  bool operator<(const edge a) const { return val < a.val; }
} e[500001];
int n, m;
bool cmp(const edge x, const edge y) { return x.id < y.id; }
int main() {
  n = gi(), m = gi();
  for (int i = 1; i <= n; i++) fa[i] = i;
  for (int i = 1; i <= m; i++)
    e[i].x = gi(), e[i].y = gi(), e[i].val = gi(), e[i].id = i;
  sort(e + 1, e + m + 1);
  e[0].val = -1;
  for (int i = 1; i <= m;) {
    int j = i;
    do {
      e[j].tx = find(e[j].x);
      e[j].ty = find(e[j].y);
      j++;
    } while (j <= m && e[j].val == e[j - 1].val);
    while (i < j) {
      while (find(e[i].x) == find(e[i].y) && i < j) i++;
      if (i < j) merge(e[i].x, e[i].y);
    }
  }
  int q = gi();
  sort(e + 1, e + m + 1, cmp);
  for (int i = 1; i <= n; i++) fa[i] = i;
  while (q--) {
    int k = gi();
    vector<edge> v;
    for (int i = 1; i <= k; i++) {
      int a = gi();
      v.push_back({e[a].tx, e[a].ty, e[a].val});
    }
    sort(v.begin(), v.end());
    bool flag = 1;
    for (int i = 0, sz = v.size() - 1; i <= sz && flag;) {
      if (find(v[i].x) == find(v[i].y)) {
        flag = 0;
        break;
      }
      merge(v[i].x, v[i].y);
      int j = i + 1;
      while (j <= sz && v[j].val == v[i].val) {
        if (find(v[j].x) == find(v[j].y)) {
          flag = 0;
          break;
        }
        merge(v[j].x, v[j].y), j++;
      }
      while (i < j) fa[v[i].x] = v[i].x, fa[v[i].y] = v[i].y, i++;
    }
    puts(flag ? "YES" : "NO");
  }
  return 0;
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

	static int n, m, sq;
	static int[] jumps, dp, last, original;

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out), false);
		String[] parts = br.readLine().split(" ");
		n = Integer.parseInt(parts[0]);
		m = Integer.parseInt(parts[1]);
		sq = ((int) Math.sqrt(n)) + 10;
		jumps = new int[n];
		dp = new int[n];
		last = new int[n];
		original = new int[n];
		parts = br.readLine().split(" ");
		for (int i = 0; i < parts.length; i++) {
			original[i] = jumps[i] = i + Integer.parseInt(parts[i]);
		}
		updateBuckets(0, n - 1);
		for (int i = 0; i < m; i++) {
			parts = br.readLine().split(" ");
			int type = Integer.parseInt(parts[0]);
//			System.out.println(Arrays.toString(dp));
//			System.out.println(Arrays.toString(jumps));
//			System.out.println(Arrays.toString(last));
			if (type == 0) {
				int hole = Integer.parseInt(parts[1]) - 1;
				int newJump = Integer.parseInt(parts[2]);
				original[hole] = hole + newJump;
				int z = hole / sq;
				int lower = z*sq;
				int upper = Math.min(z*sq + sq - 1, n - 1);
				updateBuckets(lower, upper);
//				System.out.println("UPDATED!");
			} else {
				int count = 0;
				int lst = 0;
				int curr = Integer.parseInt(parts[1]) - 1;
				while (curr < jumps.length) {
					lst = last[curr];
					count += dp[curr];
//					System.out.println("Added: " + dp[curr] + ", curr: " + curr);
					curr = jumps[curr];
				}
				lst++;
				pw.write(String.format("%d %d%n", lst, count));
//				System.out.println(lst + " " + count);
			}
		}
		pw.flush();
	}

	private static void updateBuckets(int l, int r) {
		Arrays.fill(dp, l, r + 1, 1);
		for (int i = r; i >= l; i--) {
			int destination = original[i]; 
			int destinationBucket = destination/sq;
			int myBucket = i/sq;
			if (destination < jumps.length && destinationBucket == myBucket) {
				dp[i] = dp[destination] + 1;
				jumps[i] = jumps[destination];
				last[i] = last[destination];
			} else {
				dp[i] = 1;
				last[i] = i;
			}
		}
	}

}

#include<bits/stdc++.h>

int main() {
	using namespace std;
	ios_base::sync_with_stdio(false), cin.tie(nullptr);
	int N; cin >> N;
	struct constraint {
		bool z;
		uint64_t v;
	};
	vector<constraint> rows[2] = {vector<constraint>(N), vector<constraint>(N)};
	for (int d = 0; d < 2; d++) {
		for (int i = 0; i < N; i++) {
			cin >> rows[d][i].z;
		}
	}

	for (int d = 0; d < 2; d++) {
		for (int i = 0; i < N; i++) {
			cin >> rows[d][i].v;
		}
	}

	auto id = [](bool z) -> uint64_t { return z ? uint64_t(0) : ~uint64_t(0); };
	auto op = [](bool z, uint64_t a, uint64_t b) -> uint64_t { return z ? (a | b) : (a & b); };

	uint64_t accum[2][2] = {{id(0), id(1)}, {id(0), id(1)}};
	for (int d = 0; d < 2; d++) {
		for (int i = 0; i < N; i++) {
			for (int z = 0; z < 2; z++) {
				accum[d][z] = op(z, accum[d][z], rows[d][i].v);
			}
		}
	}

	vector<bool> parity[2] = {vector<bool>(N), vector<bool>(N)};
	for (int d = 0; d < 2; d++) {
		bool cur_parity[2] = {true, true};
		for (int i = 0; i < N; i++) {
			parity[d][i] = (cur_parity[rows[d][i].z] ^= 1);
		}
	}

	auto get_cell = [&](int i, int j) -> uint64_t {
		const auto& [rz, rv] = rows[0][i];
		const auto& [cz, cv] = rows[1][j];
		if (rz == cz) {
			return op(!rz, rv, cv);
		} else {
			if (parity[0][i] ^ parity[1][j]) {
				return op(!cz, cv, op(!rz, ~accum[0][cz], rv));
			} else {
				return op(!rz, rv, op(!cz, ~accum[1][rz], cv));
			}
		}
	};

	vector<vector<uint64_t>> ans(N, vector<uint64_t>(N));
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			ans[i][j] = get_cell(i, j);
		}
	}

	vector<uint64_t> ansVal[2] = {vector<uint64_t>(N), vector<uint64_t>(N)};
	for (int d = 0; d < 2; d++) {
		for (int i = 0; i < N; i++) {
			ansVal[d][i] = id(rows[d][i].z);
		}
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			ansVal[0][i] = op(rows[0][i].z, ansVal[0][i], ans[i][j]);
			ansVal[1][j] = op(rows[1][j].z, ansVal[1][j], ans[i][j]);
		}
	}
	for (int d = 0; d < 2; d++) {
		for (int i = 0; i < N; i++) {
			if (ansVal[d][i] != rows[d][i].v) {
				cout << -1 << '\n';
				exit(0);
			}
		}
	}

	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			cout << ans[i][j] << " \n"[j+1==N];
		}
	}

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int M = 20020;
const int G = 2020;
const int N = M * G;
const int INF = 2e9 + 9;
int id(int v, int r) { return G * v + r; }
int n;
int m;
int g;
int s;
int coord[M];
int dist[N];
deque<int> q;
signed main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> m;
  for (int i = 0; i < m; ++i) {
    cin >> coord[i];
  }
  sort(coord, coord + m);
  cin >> g >> s;
  fill_n(dist, N, INF);
  dist[0] = 0;
  q.emplace_back(0);
  while (q.size()) {
    int v = q.front();
    q.pop_front();
    int i = v / G;
    int r = v % G;
    if (r == g) {
      int u = id(i, 0);
      if (dist[u] > dist[v] + s) {
        dist[u] = dist[v] + s;
        q.emplace_back(u);
      }
      continue;
    }
    if (i > 0) {
      int w = coord[i] - coord[i - 1];
      if (r + w <= g) {
        int u = id(i - 1, r + w);
        if (dist[u] > dist[v] + w) {
          dist[u] = dist[v] + w;
          q.emplace_front(u);
        }
      }
    }
    if (i + 1 < m) {
      int w = coord[i + 1] - coord[i];
      if (r + w <= g) {
        int u = id(i + 1, r + w);
        if (dist[u] > dist[v] + w) {
          dist[u] = dist[v] + w;
          q.emplace_front(u);
        }
      }
    }
  }
  int answer = INF;
  for (int r = 0; r <= g; ++r) {
    answer = min(answer, dist[id(m - 1, r)]);
  }
  if (answer < INF) {
    cout << answer << "\n";
  } else {
    cout << "-1\n";
  }
  return 0;
}

