        if (sb.length() > 1000) {
          System.out.println(sb.toString());
          sb.setLength(0);
        }
      }
    }
    System.out.println(sb.toString());
  }

  static void myAssert(boolean cond) {
    if (!cond) {
      throw new RuntimeException("Unexpected");
    }
  }

  static String trace(int[] a) {
    StringBuilder sb = new StringBuilder(7 * a.length);
    for (int v : a) {
     if (sb.length() > 0) {
       sb.append(' ');
     }
     sb.append(v);
    }
    return sb.toString();
  }

  static void doTest() {
