void build() {
    for (int i = n-1; i >= 0; i--) {
        sz[i]++;
        sz[r[i]] += sz[i];
    }
    rep (at, n) {
        if (at) {
            p[at].push_back(r[at]);
            for (int ch = 1, k = 0; ch*2 <= h[at]; ch *= 2, k++) {
                p[at].push_back(p[p[at][k]][k]);
            }
        }
        int t = x[at] + 1;
        rep (i, g[at].size()) {
            int to = g[at][i];
            h[to] = h[at] + 1;
            x[to] = t;
            t += sz[to];
        }
        y[at] = t;
    }
}

int get(int at, int h) {
    if (h == 0) return at;
    int ch = 1, k = 0;
    while (ch*2 <= h) ch*=2, k++;
    return get(p[at][k], h-ch);
}

int common(int a, int b) {
    if (h[a] < h[b]) swap(a, b);
    if (get(a, h[a]-h[b]) == b) return b;
    int l = 0, r = h[b];
    while (r-l > 1) {
        const int mid = (l+r)/2;
        if (get(a, h[a]-mid) == get(b, h[b]-mid)) l = mid;
        else r = mid;
    }
    return get(a, h[a]-l);
}


