	static int[] d(int[][] g, int s) {
		final int M = Integer.MAX_VALUE;
		int[] d = new int[10];
		Arrays.fill(d, M);
		d[s] = 0;

		boolean[] visited = new boolean[10];
		while (true) {
			int u = -1;
			int min = M;

			for (int i = 0; i < 10; i++) {
				if (!visited[i] && d[i] < min) {
					u = i;
					min = d[i];
				}
			}
			if (min == M) break;
			visited[u] = true;
			for (int i = 0; i < 10; i++)
				d[i] = Math.min(d[i], d[u] + g[u][i]);
		}
		return d;
	}
