		vector<long long int> data2;
		int elemnum;

	public:
		RMQ(int n)
		{
			elemnum = 1;
			while(elemnum < n) elemnum *= 2;
			data1 = vector<long long int>(2 * elemnum, 0);
			data2 = vector<long long int>(2 * elemnum, 0);
		}

		int getelemnum()
		{
			return elemnum;
		}

		// [a, b)???x???????????????
		//  k : ??????????????????[l, r)?????????
		void add(int a, int b, int l, int r, int k, long long int x)
		{
			if(a <= l && r <= b){
				data1[k] += x;
			} else if(l < b && a < r){
				data2[k] += x * (min(b, r) - max(a, l));
				add(a, b, l, (l + r) / 2, 2 * k, x);
				add(a, b, (l + r) / 2, r, 2 * k + 1, x);
			}
		}

		long long int getsum(int a, int b, int l, int r, int k)
		{
			if(a <= l && r <= b){
				return data1[k] * (r - l) + data2[k];
			} else if(b <= l || r <= a){
				return 0;
			} else {
				long long int ans = data1[k] * (min(b, r) - max(a, l));
				ans += getsum(a, b, l, (l + r) / 2, 2 * k);
				ans += getsum(a, b, (l + r) / 2, r, 2 * k + 1);
				return ans;
			}
		}

		void print()
		{
			for(int i = 0; i < 2 * elemnum; i++){
				cout << data1[i] << " ";
			}
			cout << endl;
			for(int i = 0; i < 2 * elemnum; i++){
				cout << data2[i] << " ";
			}
			cout << endl;
		}
};

