      cout << "Path" << '\n';
      for (int i = 1; i < p[0].a; i++) {
        cout << "dec 1" << '\n';
      }
    } else {
      cout << "No" << '\n';
    }
    exit(0);
  }
  if (tot % 2 == 0) {
    for (int i = 1; i < m; i++) {
      if (p[i].a % 2 == 0) {
        swap(p[0], p[i]);
        break;
      }
    }
    vector<vector<int> > cycle = getCycle(p[0], p[1]);
    for (int i = 2; i < m; i++) {
      cycle = processCycle(cycle, p[i]);
    }
    for (auto &x : cycle) {
      vector<int> vec(m);
      for (int i = 0; i < m; i++) {
        vec[p[i].i] = x[i];
      }
      x = vec;
    }
    cycle.push_back(cycle.front());
    vector<array<int, 2> > answer = parse(cycle);
    cout << "Cycle" << '\n';
    for (auto x : answer) {
      if (x[0] == 1)
        cout << "inc";
      else
        cout << "dec";
      cout << " " << x[1] + 1 << '\n';
    }
    exit(0);
  }
  if (!check(p, m)) {
    cout << "No" << '\n';
    exit(0);
  }
  for (int i = 0; i < m; i++) {
    for (int j = i + 1; j < m; j++) {
      if (p[j].b % 2 == 0) {
        swap(p[i], p[j]);
        break;
      }
    }
  }
  int ind = 0;
  vector<vector<int> > path;
  for (; ind < m; ind += 2) {
    if (p[ind].b % 2 != 0) break;
    assert(p[ind + 1].b % 2 == 0);
    vector<vector<int> > curpath = getPath(p[ind], p[ind + 1]);
    if (path.empty()) {
      path = curpath;
    } else {
      path = processPaths2(path, curpath);
    }
  }
  if (path.empty()) {
    path = getPath(p[ind], p[ind + 1]);
    ind += 2;
  }
  for (int i = ind; i < m; i++) {
    assert(p[i].b % 2 == 1);
    path = processPaths1(path, p[i]);
  }
  for (auto &x : path) {
    vector<int> vec(m);
    for (int i = 0; i < m; i++) {
      vec[p[i].i] = x[i];
    }
    x = vec;
  }
  vector<array<int, 2> > answer = parse(path);
  cout << "Path" << '\n';
  for (auto x : answer) {
    if (x[0] == 1)
      cout << "inc";
    else
      cout << "dec";
    cout << " " << x[1] + 1 << '\n';
  }
  return 0;
}

