import java.io.*;
import java.util.*;

public class Template {

    BufferedReader in;
    PrintWriter out;
    StringTokenizer st;

    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(in.readLine());
            } catch (Exception e) {
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    public void run() throws Exception {
        //in = new BufferedReader(new FileReader("input.txt"));
        //out = new PrintWriter(new FileWriter("output.txt"));
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.flush();
        out.close();
        in.close();
    }
    long mod = 1000000007;
    ArrayList<Integer> d = new ArrayList<Integer>();
    long[] s = new long[100002];

    long power(long x, long n) {
        if (n == 0) {
            return 1;
        }
        long y = power(x, n / 2);
        y = y * y % mod;
        if (n % 2 == 1) {
            y = y * x % mod;
        }
        return y % mod;
    }

    long go(int x) {
        d.clear();
        for (int i = 1; i * i <= x; i++) {
            if (x % i == 0) {
                d.add(i);
                if (i * i != x) {
                    d.add(x / i);
                }
            }
        }
        Collections.sort(d);
        long res1 = 1, res2 = 1;
        int dn = d.size();
        long last = 0, current;
        for (int i = dn - 1; i >= 0; i--) {
            current = s[d.get(i)];
            if (current != last) {
                res1 *= power(i + 1, current - last);
                res1 %= mod;
                last = current;
            }
        }
        last = 0;
        for (int i = dn - 2; i >= 0; i--) {
            current = s[d.get(i)];
            if (current != last) {
                res2 *= power(i + 1, current - last);
                res2 %= mod;
                last = current;
            }
        }
        return res1 - res2;
    }

    public void solve() throws Exception {
        int n = nextInt();
        int max = 0;
        for (int i = 0; i < n; i++) {
            int a = nextInt();
            s[a]++;
            if (a > max) {
                max = a;
            }
        }
        for (int i = max - 1; i >= 1; i--) {
            s[i] += s[i + 1];
        }
        long ans = 1;
        for (int i = max; i >= 2; i--) {
            ans += go(i);
            ans %= mod;
        }
        out.println(ans);
    }

    public static void main(String[] args) throws Exception {
        new Template().run();
    }
}

