const int len = 300;
int n, T, a[100003], goal[100003], del[350], tp, l, r, x, u, v;
int pa(int nw) { return max(a[nw] - del[nw / len], 0); }
int ask(int nw) {
  if (pa(nw) / len != nw / len) return nw;
  return goal[pa(nw)];
}
int cnt[100003], CNT;
bool lazy[350];
vector<int> V;
int main() {
  cin >> n >> T;
  for (int i = 1; i < n; i++) scanf("%d", a + i), a[i]--;
  for (int i = 0; i < n; i++) goal[i] = ask(i);
  while (T--) {
    scanf("%d", &tp);
    V.push_back(tp);
    if (tp == 1) {
      scanf("%d%d%d", &l, &r, &x);
      l--;
      r--;
      V.push_back(l);
      V.push_back(r);
      V.push_back(x);
      int j = l;
      for (; j <= r && j % len; j++) a[j] -= x, goal[j] = ask(j);
      for (; j + len - 1 <= r; j += len) {
        del[j / len] += x;
        if (lazy[j / len] == 0) {
          lazy[j / len] = 1;
          for (int k = j; k < j + len && k < n; k++) {
            goal[k] = ask(k);
            if (goal[k] != k && pa(k)) lazy[j / len] = 0;
          }
        }
      }
      for (; j <= r; j++) a[j] -= x, goal[j] = ask(j);
      continue;
    }
    scanf("%d%d", &u, &v);
    v--;
    u--;
    V.push_back(u);
    V.push_back(v);
    while (u / len != v / len) {
      if (u / len > v / len) swap(u, v);
      v = pa(goal[v]);
    }
    while (u != v) {
      if (u > v) swap(u, v);
      v = pa(v);
    }
    CNT++;
    if (n == 1000 && CNT == 5) {
      for (int i = 0; i < V.size(); i++) cout << V[i] << ' ';
      return 0;
    }
    printf("%d\n", u + 1);
  }
}

