using namespace std;
const int MAX_N = int(1e5) + 10;
long long a[MAX_N];
int n;
bitset<MAX_N> at[64];
int w[64];
int cnt[64];
int control[MAX_N];
bool freev[MAX_N];
int how[MAX_N];
int main() {
  cin >> n;
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
    for (int j = 0; j < 64; ++j) {
      at[j][i] = (a[i] >> j & 1);
      cnt[j] += (a[i] >> j & 1);
    }
  }
  memset(control, -1, sizeof control);
  for (int i = 63; i >= 0; --i) {
    if (cnt[i] == 0) continue;
    w[i] = 0;
    for (int j = 0; j < n; ++j) {
      if (control[j] != -1 && at[i][j]) {
        at[i] ^= at[control[j]];
        w[i] ^= w[control[j]];
      }
    }
    int con = -1;
    for (int j = 0; j < n; ++j) {
      if (at[i][j]) {
        con = j;
        break;
      }
    }
    if (cnt[i] % 2 == 0) {
      w[i] ^= 1;
      if (con == -1 && w[i] > 0) {
        w[i] ^= 1;
      }
    } else {
      if (con == -1 && w[i] > 0) {
        w[i] ^= 1;
      }
    }
    if (con != -1) {
      control[con] = i;
      for (int j = i + 1; j <= 63; ++j)
        if (at[j][con]) {
          at[j] ^= at[i];
          w[j] ^= w[i];
        }
    }
  }
  fill(freev, freev + n, true);
  for (int i = 0; i < n; ++i) {
    if (control[i] != -1) freev[i] = false;
  }
  for (int i = 0; i < n; ++i) {
    if (freev[i]) how[i] = 0;
  }
  for (int i = 0; i < n; ++i) {
    if (control[i] != -1) how[i] = w[control[i]];
  }
  for (int i = 0; i < n; ++i) {
    printf("%d ", 2 - how[i]);
  }
  puts("");
  return 0;
}

