long long cl(const vector<long long>& v) {
  long long r = 0;
  for (long long i = 0; i < (1 << n); i++) s[i] = 1;
  for (long long i : v)
    for (long long j = 0; j < (1 << n); j++) s[j] *= b[i][j];
  for (long long i = 0; i < (1 << n); i++) {
    if ((n - bc[i]) & 1)
      r -= s[i];
    else
      r += s[i];
  }
  return r;
}
