    for (long long j = 0; j < n; j++)
      if (i & (1 << j)) {
        for (long long k = 0; k < n; k++)
          if ((!(i & (1 << k))) && c[j][k] == '1')
            a[i | (1 << k)][k] += a[i][j];
        b[bc[i]][i] += a[i][j];
      }
  for (long long i = 0; i <= n; i++)
    for (long long j = 0; j < n; j++)
      for (long long k = 0; k < (1 << n); k++)
        if (k & (1 << j)) b[i][k] += b[i][k - (1 << j)];
  for (long long i = 0; i < (1 << (n - 1)); i++) {
