import java.util.*;
import java.io.*;

public class A {
    public static void main(String[] args) {
        new A().run();
    }

    public void run() {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = reader.nextInt();
        double loss = 0.0;
        int count = 0;
        for (int i = 0; i < 2 * n; i++) {
            double a = reader.nextDouble();
            double diff = a - (int)(a + 1e-9);
            loss += diff;
            if (diff == 0.0) {
                count++;
            }
        }
        int threshold = Math.min(n, 2 * n - count);
        double ans = 1e-9;

        if (threshold >= loss) {
            double lossDiff = loss - (int)(loss + 1e-9);
//          System.out.println(loss);
            ans = Math.min(lossDiff, 1.0 - lossDiff);
        } else {
            ans = Math.abs(threshold - loss);
        }

        writer.format(Locale.US, "%.3f\n", ans);
        writer.close();
    }

    public class InputReader {
        private static final int HEAP_SIZE = 128;
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String nextLine() {
            tokenizer = null;
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public boolean hasNext() {
            if (tokenizer != null && tokenizer.hasMoreTokens()) {
                return true;
            }
            try {
                reader.mark(HEAP_SIZE);
                if (reader.readLine() == null) {
                    return false;
                }
                reader.reset();
            } catch (IOException e) {}
            return true;
        }
    }
}

