struct info {
  long long fs, sm, id;
} bd[100001];
int cmp(info a, info b) { return a.fs < b.fs; }
int main() {
  ios_base::sync_with_stdio(0);
  long long int i, j, x, n, cnt = 0, m, y, k, ans = 0, cf, cm, a, rr1 = 0, l, r,
                            md, r1, r2, xxx, flg;
  cin >> n >> a >> cf >> cm >> m;
  long long in[n + 1], bs[n + 1];
  for (i = 1; i <= n; i++) {
    cin >> in[i];
    bd[i].fs = a - in[i];
    bd[i].id = i;
    bs[i] = a - in[i];
  }
  sort(bd + 1, bd + 1 + n, cmp);
  sort(bs + 1, bs + 1 + n);
  for (i = 2; i <= n; i++) {
    bd[i].fs += bd[i - 1].fs;
  }
  bd[n].sm = 0;
  for (i = n - 1; i >= 1; i--) {
    x = abs(in[bd[i + 1].id] - in[bd[i].id]);
    bd[i].sm = bd[i + 1].sm + x * (n - i);
  }
  bd[0].fs = bd[0].id = 0;
  bd[0].sm = (a - in[bd[1].id]) * n + bd[1].sm;
  for (i = 1; i <= n; i++) {
    if (bs[i] > 0) break;
    cnt++;
  }
  ans = cnt * cf + cm * in[bd[n].id];
  for (i = n; i >= 0; i--) {
    x = m;
    y = cnt * cf;
    rr1 = cnt;
    flg = 0;
    if (x >= bd[i].fs) {
      flg = 1;
      y = i * cf;
      x -= bd[i].fs;
      rr1 = i;
    }
    l = i;
    r = n;
    while (r - l > 1) {
      md = (l + r) / 2;
      if (bd[md].sm > x)
        l = md;
      else
        r = md;
    }
    if (bd[l].sm <= x && i != 0) r = l;
    x -= bd[r].sm;
    y += cm * (min(a, in[bd[r].id] + x / (n - i + 1)));
    if (r == i && flg) {
      y = a * cm + n * cf;
      if (ans <= y) {
        ans = y;
        r1 = n;
        r2 = n + 1;
      }
      continue;
    }
    if (y >= ans) {
      ans = y;
      r1 = rr1;
      r2 = r;
      xxx = min(a, in[bd[r].id] + x / (n - i + 1));
    }
  }
  for (i = 1; i <= r1; i++) {
    in[bd[i].id] = a;
  }
  for (i = r2; i <= n; i++) {
    in[bd[i].id] = xxx;
  }
  if (n == 1000) {
    cout << r1 << " " << r2 << " " << xxx << " " << bd[r1].fs << " "
         << bd[r2].sm << " " << bs[n] << endl;
  }
  cout << ans << endl;
  for (i = 1; i <= n; i++) cout << in[i] << " ";
}

#include <bits/stdc++.h>
using namespace std;
struct E {
  int to, nxt;
} b[400005];
int fst[200005], tot;
void insert(int f, int t) {
  b[++tot] = (E){t, fst[f]};
  fst[f] = tot;
  b[++tot] = (E){f, fst[t]};
  fst[t] = tot;
}
int deep[200005];
int m, ans, sz[200005];
bool use[200005];
void dfs(int x) {
  if (use[x]) sz[x] = 1;
  for (int i = fst[x]; i; i = b[i].nxt) {
    int v = b[i].to;
    if (!deep[v]) {
      deep[v] = deep[x] + 1;
      dfs(v);
      sz[x] += sz[v];
    }
  }
  while (sz[x] > m / 2) {
    sz[x] -= 2;
    m -= 2;
  }
  ans += sz[x];
}
int main() {
  int n, x;
  scanf("%d%d", &n, &m);
  m *= 2;
  for (int i = 1; i <= m; i++) {
    scanf("%d", &x);
    use[x] = 1;
  }
  int y;
  for (int i = 1; i < n; i++) {
    scanf("%d%d", &x, &y);
    insert(x, y);
  }
  deep[1] = 1;
  dfs(1);
  cout << ans << endl;
}

