/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FArrayStabilizationGCDVersion solver = new FArrayStabilizationGCDVersion();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class FArrayStabilizationGCDVersion {
        int n;
        List<Integer> prime = new ArrayList<>();
        int N = (int) (1e6 + 5);
        int[] sieve = new int[N + 1];

        // sieve存每个数的最小质因子
        {
            sieve[1] = 1;
            for (int i = 2; i <= N; i++) {
                if (sieve[i] == 0) {
                    sieve[i] = i;
                    prime.add(i);
                }
                for (int j = 0; j < prime.size() && prime.get(j) <= sieve[i] && i * prime.get(j) <= N; j++) {
                    sieve[i * prime.get(j)] = prime.get(j);
                }
            }
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            int[] a = in.nextIntArray(n);
            int common = a[0];
            for (int i = 1; i < n; i++) {
                common = gcd(common, a[i]);
            }
            Set<Integer>[] fact = new Set[n];
            for (int i = 0; i < n; i++) {
                fact[i] = new HashSet<>();
                int t = a[i] / common;
                while (t != 1) {
                    fact[i].add(sieve[t]);
                    t /= sieve[t];
                }
            }
            int res = 0;
            for (int i = 0; i < n; i++) {
                Set<Integer> set = fact[i];
                for (Integer p : set) {
                    int l = (i + n - 1) % n;
                    int r = i;
                    int cnt = 0;
                    while (fact[l].contains(p)) {
                        fact[l].remove(p);
                        l--;
                        cnt++;
                        if (l < 0) {
                            l = n - 1;
                        }
                    }
                    while (fact[r].contains(p)) {
                        if (r != i) {
                            fact[r].remove(p);
                        }
                        ++r;
                        r %= n;
                        cnt++;
                    }
                    res = Math.max(res, cnt);
                }
            }
            out.println(res);

        }

        int gcd(int a, int b) {
            return b != 0 ? gcd(b, a % b) : a;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return nextString();
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; ++i) array[i] = nextInt();
            return array;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }
}

