const long long INF = 1LL << 60;
const long long MOD = 1000000007LL;
const long long int B = 60;
long long int N, a[B], b[B];
long long int func(vector<pair<long long int, long long int> > &ope) {
  long long int ans = 0;
  for (long long int(z) = (0); (z) < (N); (z)++) {
    long long int i = ope[z].second;
    long long int s = a[i], t = b[i];
    if (s < t) {
      return INF;
    }
    vector<long long int> dist(B, INF), mon(B);
    dist[s] = 0;
    for (long long int(k) = (0); (k) < (B); (k)++) {
      if (!(ans >> k & 1)) mon[k] = (1LL << k);
    }
    priority_queue<pair<long long int, long long int>,
                   vector<pair<long long int, long long int> >,
                   greater<pair<long long int, long long int> > >
        que;
    que.push(make_pair(dist[s], s));
    while (que.size()) {
      pair<long long int, long long int> cur = que.top();
      que.pop();
      long long int cost = cur.first, mo = cur.second;
      for (long long int k = 1; k <= mo; k++) {
        long long int n_mo = mo % k;
        long long int n_cost = cost + mon[k];
        if (dist[n_mo] > n_cost) {
          dist[n_mo] = n_cost;
          que.push(make_pair(dist[n_mo], n_mo));
        }
      }
    }
    ans |= dist[t];
  }
  return ans;
}
