const int MOD = 998244353;

struct Node {
    int l, r;
    long long ans, b, c;
    bool lazy = false;

    void leaf(int val) {
        ans = val;
    }

    void pull(Node &a, Node &b) {
        ans = a.ans + b.ans;
        if (ans >= MOD)
            ans -= MOD;
    }

    void push(int _b, int _c) {
        if (lazy) {
            b = b * _b % MOD;
            c = (_b * c % MOD + _c) % MOD;
        } else {
            lazy = true;
            b = _b;
            c = _c;
        }
    }

    void apply() {
        ans = (b * ans % MOD + c * (r - l + 1) % MOD) % MOD;
        lazy = false;
    }
};

struct SegmentTree {
    int n;
    vector<int> a;
    vector<Node> st;

    SegmentTree(const vector<int> &_a) : n(_a.size()), a(_a), st(4*n) {
        build(1, 0, n-1);
    }

    void build(int p, int l, int r) {
        st[p].l = l;
        st[p].r = r;
        if (l == r) {
            st[p].leaf(a[l]);
            return;
        }

        int m = (l + r) / 2;
        build(2*p, l, m);
        build(2*p+1, m+1, r);
        st[p].pull(st[2*p], st[2*p+1]);
    }

    void push(int p) {
        if (st[p].lazy) {
            if (st[p].l != st[p].r) {
                st[2*p].push(st[p].b, st[p].c);
                st[2*p+1].push(st[p].b, st[p].c);
            }
            st[p].apply();
        }
    }

    Node query(int p, int i, int j) {
        push(p);

        if (st[p].l == i && st[p].r == j)
            return st[p];

        int m = (st[p].l + st[p].r) / 2;
        if (j <= m)
            return query(2*p, i, j);
        else if (i > m)
            return query(2*p+1, i, j);
        Node ret, ls = query(2*p, i, m), rs = query(2*p+1, m+1, j);
        ret.pull(ls, rs);
        return ret;
    }

    int query(int i, int j) {
        return query(1, i, j).ans;
    }

    void update(int p, int i, int j, int b, int c) {
        if (st[p].l == i && st[p].r == j) {
            st[p].push(b, c);
            push(p);
            return;
        }

        push(p);

        int m = (st[p].l + st[p].r) / 2;
        if (j <= m) {
            update(2*p, i, j, b, c);
            push(2*p+1);
        } else if (i > m) {
            push(2*p);
            update(2*p+1, i, j, b, c);
        } else {
            update(2*p, i, m, b, c);
            update(2*p+1, m+1, j, b, c);
        }
        st[p].pull(st[2*p], st[2*p+1]);
    }

    void update(int i, int j, int b, int c) {
        update(1, i, j, b, c);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
