  roots[0] = 1;
  for (int i = (1); i < (n); ++i) roots[i] = roots[i - 1] * r;
}
void genRoots(vector<complex<double> >& roots) {
  int n = (int)roots.size();
  double ang = 2 * PI / n;
  for (int i = (0); i < (n); ++i)
    roots[i] = complex<double>(cos(ang * i), sin(ang * i));
}
