template <class T>
void fft(vector<T>& a, const vector<T>& rts, bool inv = 0) {
  int n = (int)a.size();
  for (int i = 1, j = 0; i < n; i++) {
    int bit = n >> 1;
    for (; j & bit; bit /= 2) j ^= bit;
    j ^= bit;
    if (i < j) swap(a[i], a[j]);
  }
  for (int len = 1; len < n; len *= 2)
    for (int i = 0; i < n; i += 2 * len)
      for (int j = (0); j < (len); ++j) {
        T u = a[i + j], v = a[i + j + len] * rts[n / 2 / len * j];
        a[i + j] = u + v, a[i + j + len] = u - v;
      }
  if (inv) {
    reverse(1 + begin(a), end(a));
    T i = T(1) / T(n);
    for (auto& x : a) x *= i;
  }
}
template <class T>
vector<T> mul(vector<T> a, vector<T> b) {
  if (!min((int)a.size(), (int)b.size())) return {};
  int second = (int)a.size() + (int)b.size() - 1, n = 1 << size(second);
  vector<T> roots(n);
  genRoots(roots);
  a.resize(n), fft(a, roots);
  b.resize(n), fft(b, roots);
  for (int i = (0); i < (n); ++i) a[i] *= b[i];
  fft(a, roots, 1);
  a.resize(second);
  return a;
}
vector<long long> mulMod(const vector<long long>& a,
                         const vector<long long>& b) {
  if (!min((int)a.size(), (int)b.size())) return {};
  int second = (int)a.size() + (int)b.size() - 1, n = 1 << size(second),
      cut = sqrt(MOD);
  vector<complex<double> > roots(n);
  genRoots(roots);
  vector<complex<double> > ax(n), bx(n);
  for (int i = (0); i < ((int)a.size()); ++i)
    ax[i] = complex<double>((int)a[i] / cut, (int)a[i] % cut);
  for (int i = (0); i < ((int)b.size()); ++i)
    bx[i] = complex<double>((int)b[i] / cut, (int)b[i] % cut);
  fft(ax, roots), fft(bx, roots);
  vector<complex<double> > v1(n), v0(n);
  for (int i = (0); i < (n); ++i) {
    int j = (i ? (n - i) : i);
    v1[i] = (ax[i] + conj(ax[j])) * complex<double>(0.5, 0) * bx[i];
    v0[i] = (ax[i] - conj(ax[j])) * complex<double>(0, -0.5) * bx[i];
  }
  fft(v1, roots, 1), fft(v0, roots, 1);
  vector<long long> ret(n);
  for (int i = (0); i < (n); ++i) {
    long long V2 = (long long)round(v1[i].real());
    long long V1 =
        (long long)round(v1[i].imag()) + (long long)round(v0[i].real());
    long long V0 = (long long)round(v0[i].imag());
    ret[i] = ((V2 % MOD * cut + V1) % MOD * cut + V0) % MOD;
  }
  ret.resize(second);
  return ret;
}
