long long solve(int a, int st, int fi) {
  int s = ke[a], f = ve[a];
  if (st > f || fi < s) return 0;
  if (st <= s && f <= fi) {
    int tav = f + 1 - s;
    return sum[a ^ (xo / tav)];
  }
  return solve(2 * a, st, fi) + solve(2 * a + 1, st, fi);
}
