        up_p[y] = inv[deg[y]] * (sum_up_p[y] + 1) % MOD;
        up[y] = (inv[deg[y]] * (sum[y] + sum_up[y]) % MOD) *
                getInv(1 - sum_up_p[y] + MOD) % MOD;
      }
      sum_up[x] = (sum_up[x] + up[y]) % MOD;
      sum_up_p[x] = (sum_up_p[x] + up_p[y]) % MOD;
    }
}
void dfs2(int x, int fa) {
  for (int i = p[x]; i; i = e[i].next)
    if (e[i].to != fa) {
      int y = e[i].to;
      down_p[y] = inv[deg[x]] * (down_p[x] + sum_up_p[x] - up_p[y] + MOD) % MOD;
      down[y] =
          (inv[deg[x]] * (sum[x] + down[x] + sum_up[x] - up[y] + MOD) % MOD) *
          getInv(1 - down_p[x] - sum_up_p[x] + up_p[y] + 2 * MOD) % MOD;
      dfs2(y, x);
    }
}
