void brute() {
  fill(vals, vals + N, 0);
  int s1 = 0, s2 = 0;
  for (int h = 0; h < queriesLen; ++h) {
    switch (queries[h].second.second) {
      case +1: {
        const int u = queries[h].second.first;
        for (int v = u; v != -1; v = P[v]) {
          ++s1;
          s2 += vals[v];
        }
        for (int v = u; v != -1; v = P[v]) {
          ++vals[v];
        }
      } break;
      case -1: {
        const int u = queries[h].second.first;
        for (int v = u; v != -1; v = P[v]) {
          --vals[v];
        }
        for (int v = u; v != -1; v = P[v]) {
          --s1;
          s2 -= vals[v];
