using namespace std;

const int N = 1e5 + 10;

int A[N], B[N], n;
int fa[N];

int find(int x){
	return x == fa[x] ? x : fa[x] = find(fa[x]);
}

void Union(int u, int v){
	u = find(u), v = find(v);
	if(u ^ v) fa[u] = v;
}

map<int, int> M;
map<int, queue<int> > T;

int main(){

	scanf("%d", &n);

	int S = 0;
	For(i, 1, n) scanf("%d", &A[i]), S ^= A[i];
	For(i, 1, n) scanf("%d", &B[i]);

	int x = 0;
	For(i, 1, n) if(A[i] != B[i]) A[++x] = A[i], B[x] = B[i];
	n = x;

	For(i, 1, n) fa[i] = i, M[A[i]]++;

	int pos = 0;
	For(i, 1, n) if(!M[B[i]]){
		if(pos || B[i] != S){
			puts("-1");
			return 0;
		}
		pos = i;
	}
	else --M[B[i]];

	int ans = n;
	For(i, 1, n) if(B[i] == S){
		--ans;
		break;
	}

	For(i, 1, n){
		auto &q = T[A[i]];
		if(!q.empty()) Union(i, q.front());
		q.push(i);
	}
	For(i, 1, n){
		auto &q = T[B[i]];
		if(!q.empty()) Union(i, q.front()), q.pop();
	}

	For(i, 1, n) if(fa[i] == i) ++ans;
	printf("%d\n", ans);

	return 0;
}

