const int INF = 1e9 + 10;
int main() {
  int n, m, c, s, g;
  while (cin >> n >> m >> c >> s >> g) {
    if (!n && !m && !c && !s && !g) {
      break;
    }

    // K[from][to][company]
    vector<vector<vector<int>>> K(
        n + 1, vector<vector<int>>(n + 1, vector<int>(c + 1, INF)));
    for (int i = 0; i < m; i++) {
      int x, y, d, comp;
      cin >> x >> y >> d >> comp;
      // bug:同じ区間に距離の違う同じ路線が存在することもある
      K[x][y][comp] = min(K[x][y][comp], d);
      K[y][x][comp] = min(K[x][y][comp], d);
    }
    for (int company = 1; company <= c; company++) {
      for (int k = 1; k <= n; k++) {
        for (int i = 1; i <= n; i++) {
          for (int j = 1; j <= n; j++) {
            if (K[i][j][company] > K[i][k][company] + K[k][j][company]) {
              K[i][j][company] = K[i][k][company] + K[k][j][company];
            }
          }
        }
      }
    }

    // 運賃を予め距離ごとに計算しておく
    vector<int> P(c);
    vector<vector<int>> fare(c + 1, vector<int>(200020));
    for (int i = 0; i < c; i++) {
      cin >> P[i];
    }
    for (int i = 0; i < c; i++) {
      vector<int> q(P[i]);
      for (int j = 0; j < P[i] - 1; j++) {
        cin >> q[j];
      }
      int now = 1;
      for (int j = 0; j < P[i]; j++) {
        int r;
        cin >> r;
        if (j == P[i] - 1) {
          for (; now < 200020; now++) {
            fare[i + 1][now] = fare[i + 1][now - 1] + r;
          }
        } else {
          for (; now <= q[j]; now++) {
            fare[i + 1][now] = fare[i + 1][now - 1] + r;
          }
        }
      }
    }

    // Floyd-Warshall
    vector<vector<int>> D(n + 1, vector<int>(n + 1, INF));
    for (int company = 1; company <= c; company++) {
      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
          if (K[i][j][company] != INF) {
            D[i][j] = min(D[i][j], fare[company][K[i][j][company]]);
          }
        }
      }
    }
    for (int k = 1; k <= n; k++) {
      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
          if (D[i][j] > D[i][k] + D[k][j]) {
            D[i][j] = D[i][k] + D[k][j];
          }
        }
      }
    }
    cout << (D[s][g] == INF ? -1 : D[s][g]) << endl;
  }
}

