void up(long long x, long long y) {
  (tree[x][y] = tree[x << 1][y] + tree[x << 1 | 1][y]) %= 1000000007;
}
void hok(long long x, long long l, long long r, long long addv, long long y) {
  (lazy[x][y] += addv) %= 1000000007;
  tree[x][y] = (r - l + 1) * addv % 1000000007;
}
void down(long long x, long long l, long long r, long long y) {
  if (lazy[x][y] == -1) return;
  long long m = l + r >> 1;
  hok(x << 1, l, m, lazy[x][y], y);
  hok(x << 1 | 1, m + 1, r, lazy[x][y], y);
  lazy[x][y] = -1;
}
void update(long long cnt, long long l, long long r, long long ql, long long qr,
            long long addv, long long y) {
  if (ql <= l && r <= qr) {
    hok(cnt, l, r, addv, y);
    return;
  }
  down(cnt, l, r, y);
  long long m = l + r >> 1;
  if (ql <= m) update(cnt << 1, l, m, ql, qr, addv, y);
  if (qr > m) update(cnt << 1 | 1, m + 1, r, ql, qr, addv, y);
  up(cnt, y);
}
long long query(long long cnt, long long l, long long r, long long ql,
                long long qr, long long y) {
  if (ql <= l && r <= qr) return tree[cnt][y];
  down(cnt, l, r, y);
  long long m = l + r >> 1, ans = 0;
  if (ql <= m) ans = query(cnt << 1, l, m, ql, qr, y);
  if (qr > m) (ans += query(cnt << 1 | 1, m + 1, r, ql, qr, y)) %= 1000000007;
  return ans;
}
