public class Day7_2_EqualSums {

	public static void main(String[] args) {
		InputReader reader = new InputReader(System.in);
		int n = reader.nextInt();

		StringBuilder outBuffer = new StringBuilder();
		boolean possible = false;
		List<Sum> sums = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			int length = reader.nextInt();
			int sum = 0;
			int[] numbers = new int[length];
			for (int j = 0; j < length; j++) {
				numbers[j] = reader.nextInt();
				sum += numbers[j];
			}
			for (int j = 0; j < length; j++) {
				int tempSum = sum - numbers[j];
				sums.add(new Sum(tempSum, i + 1, j + 1));
			}
		}
		sums.sort((sum1, sum2) -> {
			int compare = Integer.compare(sum1.sum, sum2.sum);
			if (compare != 0)
				return compare;
			compare = Integer.compare(sum1.i, sum2.i);
			if (compare != 0)
				return compare;
			compare = Integer.compare(sum1.j, sum2.j);
			return 0;
		});
		for (int i = 0; i < sums.size() - 1; i++) {
			if (sums.get(i).sum == sums.get(i + 1).sum && sums.get(i).i != sums.get(i + 1).i
					&& sums.get(i).j != sums.get(i + 1).j) {
				outBuffer.append("YES\n");
				outBuffer.append(sums.get(i).i + " " + sums.get(i).j + "\n");
				outBuffer.append(sums.get(i + 1).i + " " + sums.get(i + 1).j + "\n");
				possible = true;
				break;
			}
		}
		if (possible)
			System.out.print(outBuffer);
		else
			System.out.print("NO");

	}

	static class Sum {
		public int sum;
		public int i;
		public int j;

		public Sum(int sum, int i, int j) {
			super();
			this.sum = sum;
			this.i = i;
			this.j = j;
		}

	}

