using namespace std;
const int mod = 1e9 + 7;
const long long oo = 1e18 + 300;
long long way[330][330], p[330][330];
pair<int, int> dp[330][330];
vector<int> path;
void floyd(int n) {
  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (way[i][k] + way[k][j] < way[i][j]) {
          way[i][j] = way[i][k] + way[k][j];
          p[i][j] = p[k][j];
        }
      }
    }
  }
}
void solve(int a, int b) {
  if (a != b) solve(a, p[a][b]);
  path.push_back(b);
}
void init(int n) {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      p[i][j] = i;
      way[i][j] = oo;
      dp[i][j] = {oo, oo};
    }
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  long long n, a, b, c, m, q, l;
  cin >> n >> m >> l;
  init(n);
  for (int i = 0; i < m; i++) {
    cin >> a >> b >> c;
    a--, b--;
    if (c <= l) {
      way[b][a] = way[a][b] = c;
      dp[a][b] = dp[b][a] = {0, l - c};
    }
  }
  floyd(n);
  cin >> q;
  for (int i = 0; i < q; i++) {
    cin >> a >> b;
    a--, b--;
    long long ans = 0;
    if (way[a][b] == oo)
      cout << "-1" << endl;
    else {
      solve(a, b);
      long long li = l;
      for (int i = 0; i < (int)path.size() - 1; i++) {
        if (way[path[i]][path[i + 1]] > li) ans++, li = l;
        li -= way[path[i]][path[i + 1]];
      }
      cout << ans << endl;
    }
    path.clear();
  }
  return 0;
}

