int n, m;

vector<vi> visibility(const G &g){
	int n = g.size();

	vector<P> tar;
	REP(i, n){
		const S &s = g.edge(i);
		vector<P> intr;
		REP(j, n)REP(k, j)
			if(sig(outp(s.dir(), g[j] - g[k])) && intersect(s, L(g[j], g[k])))
				intr.push_back(crosspoint(s, L(g[j], g[k])));
		sort(ALL(intr));UNIQUE(intr);
		REP(j, (int)intr.size()-1) tar.push_back((intr[j]+intr[j+1])*.5);
	}
	sort(ALL(tar));UNIQUE(tar);
	int m = tar.size();
	vector<vi> vg(n, vi(m));
	REP(i, n)REP(j, m){
		const S s = S(g[i], tar[j]);
		if(!sig(norm(s.dir())) || (g.contains((g[i]+tar[j])*.5) && [&](){
			REP(k, n)if(intersect(g.edge(k), s) == TRUE)
				return false;
			return true;
		}())) vg[i][j] = 1;
	}
	return vg;
}


int main(){
	ios::sync_with_stdio(false);
	while(cin >> n, n){
		G g(n);
		REP(i, n) cin >> g[i];
		vector<vi> vg = visibility(g);
		int m = vg[0].size();
		int ans = n;
		REP(i, 1<<n){
			vi f(m);
			REP(j, n)if((i>>j)&1)REP(k, m){
				f[k] |= vg[j][k];
			}
			if(accumulate(ALL(f), 0) == m) ans = min(ans, __builtin_popcount(i));
		}
		cout << ans << endl;
	}
	return 0;
}

