#include <bits/stdc++.h>
using namespace std;
const int maxn = 100000 + 5;
long long inf = 1 << 30;
long long a[maxn];
long long tmp[maxn];
int main() {
  int n, s;
  scanf("%d%d", &n, &s);
  for (int i = 0; i < n; i++) {
    scanf("%I64d", &a[i]);
  }
  long long sum;
  long long ans = inf;
  int l = 0, r = n + 1;
  while (l < r - 1) {
    int mid = l + (r - l) / 2;
    for (int i = 0; i < n; i++) tmp[i] = a[i] + (i + 1) * mid;
    sum = 0;
    sort(tmp, tmp + n);
    for (int i = 0; i < mid; i++) sum += tmp[i];
