class TaskB {
	public void solve(int testNumber, InputReader in, OutputWriter out) {
		final int n = in.readInt();
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = in.readInt();
		}
		Arrays.sort(a);
		int ans = 0;
		for (int i = n - 2; i >= 0; i--) if (i == 0 || a[i] != a[i - 1]) {
			for (int prod = a[i]; prod <= a[n - 1]; prod += a[i]) {
				if (a[i] - 1 <= ans) {
					break;
				}
				int l = Arrays.binarySearch(a, i + 1, n, prod);
				if (l < 0) {
					l = -(l + 1);
				}
				int r = Arrays.binarySearch(a, i + 1, n, prod + a[i] - 1);
				if (r < 0) {
					r = -(r + 1) - 1;
				}
				if (l <= r) {
					ans = Math.max(ans, a[r] - prod);
				}
			}
		}
		out.println(ans);
	}
}

