long long fastPow(long long a, long long b, long long c) {
  if (b == 0) return 1LL;
  long long temp = fastPow(a, b / 2, c);
  temp = (temp * temp) % c;
  if (b % 2 == 0) {
    return temp;
  }
  return (a * temp) % c;
}
long long gcd(long long a, long long b, long long &x, long long &y) {
  if (b == 0) {
    if (a >= 0) {
      x = 1;
    } else {
      x = -1;
    }
    y = 0;
    return abs(a);
  }
  long long x2, y2;
  long long g = gcd(b, a % b, x2, y2);
  x = y2;
  y = x2 - (a / b) * y2;
  return g;
}
long long modInverse(long long a, long long mod) {
  long long x, y;
  long long g = gcd(a, mod, x, y);
  if (x >= 0)
    return x;
  else
    return x + mod;
}
long long div(long long a, long long b, long long m) {
  return (a * modInverse(b, m)) % m;
}
