import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Task3 {
    int mod;
    int n;
    int x;
    int pos;
    long[][] dp;
    int smaller;
    int larger;

    public static void main(String[] args) throws IOException {
        new Task3().solve();
    }

    private void solve() throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        StringTokenizer tokenizer = new StringTokenizer(f.readLine());
        n = Integer.parseInt(tokenizer.nextToken());
        x = Integer.parseInt(tokenizer.nextToken());
        pos = Integer.parseInt(tokenizer.nextToken());
        mod = 1000000007;
        smaller = 0;
        larger = 0;

        numOfGood(0, n - 1);
        long res = 1;
        int bigger = n - x;
        for (int i = 0; i < larger; i++) {
            res *= bigger;
            res %= mod;
            if (bigger == 0) break;
            bigger--;
        }
        int numSmaller = x - 1;
        for (int i = 0; i < smaller; i++) {
            res *= numSmaller;
            res %= mod;
            if (numSmaller == 0) break;
            numSmaller--;
        }
        res %= mod;
        res *= factorial(n - smaller - larger - 1);
        res %= mod;

        out.println(res);
        out.close();
    }

    private long numOfGood(int from, int to) {
        if (from == to) {
            if (from == pos) return 1;
            return 0;
        }

        int mid = (from + to) / 2;
        if ((from + to) % 2 == 1) mid++;
        if (pos < mid) {
            larger++;
            return numOfGood(from, mid - 1);
        }

        if (pos != mid) {
            smaller++;
        }
        return numOfGood(mid, to);
    }

    private long factorial(int power) {
        long res = 1;
        for (int i = 1; i<= power; i++) {
            res *= i;
            res %= mod;
        }

        return res;
    }
}

