inline void write(int x) {
  static char box[20];
  if (x == 0) {
    putchar('0');
    putchar('\n');
    return;
  }
  int pos(0);
  while (x) {
    box[pos] = x % 10 + '0';
    x /= 10;
    ++pos;
  }
  for (pos = pos - 1; pos >= 0; --pos) putchar(box[pos]);
  putchar('\n');
}
inline char getc() {
  static char buf[1 << 12], *p1 = buf, *p2 = buf;
  return (p1 == p2) &&
                 (p2 = (p1 = buf) + fread(buf, 1, 1 << 12, stdin), p1 == p2)
             ? EOF
             : *p1++;
}
inline int read() {
  static int x;
  x = 0;
  char ch(getc());
  while (ch < '0' || ch > '9') {
    ch = getc();
  }
  while (ch >= '0' && ch <= '9') {
    x = (x << 1) + (x << 3) + ch - '0';
    ch = getc();
  }
  return x;
}

