            for(int i = 0; i < n; i++) {
                if(visited[i]) continue;
                visited[i] = true;
                cmpnts++;
                dfs(gp,visited,i);
            }
            out.println(powMod(2,cmpnts));
        }

        private void dfs(ArrayList<Integer>[] gp, boolean[] visited, int src) {
            for(int v : gp[src]) {
                if(visited[v]) continue;
                visited[v] = true;
                dfs(gp,visited,v);
            }
        }

