            a %= mod;
            long res = 1;
            while(b>0) {
                if(b%2!=0) res = multMod(res,a);
                a = multMod(a,a);
                b /= 2;
            }
            return res;
        }

        private long multMod(long a, long b) {
            long ret = (a*b)%mod;
            if(ret<0) ret += mod;
            return ret;
        }

        private long addmod(long prevsw, long prevor) {
            return (prevor+prevsw) % mod;
