using namespace std;
bool win(long long a, long long b) {
  if (a > b) swap(a, b);
  if (a == 0) return false;
  bool type = win(b % a, a);
  if (!type) return true;
  b /= a;
  if (a % 2 == 1) {
    if (b % 2 == 0) return true;
    return false;
  } else {
    if ((b % (a + 1)) % 2 == 0) return true;
    return false;
  }
}
int main() {
  int N;
  cin >> N;
  while (N--) {
    long long a, b;
    cin >> a >> b;
    if (win(a, b))
      cout << "First\n";
    else
      cout << "Second\n";
  }
  return 0;
}

