const int MAX1 = 2020;
const int MAX2 = 2020;
int SIZE1, SIZE2;

template<class T> struct BIT2D {    
    T dat[2][2][MAX1 + 1][MAX2 + 1];

    void init(int n = 1, int m = 1) {
        SIZE1 = n, SIZE2 = m;
        for (int i = 0; i <= SIZE1; ++i) 
            for (int j = 0; j <= SIZE2; ++j) 
                dat[0][0][i][j] = dat[0][1][i][j] = dat[1][0][i][j] = dat[1][1][i][j] = 0;
    }

    inline void subsub_add(int f, int s, int a, int b, T x) {
        for (int i = a; i <= SIZE1; i += i & -i) 
            for (int j = b; j <= SIZE2; j += j & -j) 
                dat[f][s][i][j] = dat[f][s][i][j] + x;
    }

    inline void sub_add(int a1, int a2, long long x) {
        subsub_add(0, 0, a1, a2, x*(a1-1)*(a2-1));
        subsub_add(1, 0, a1, a2, -x*(a1-1));
        subsub_add(0, 1, a1, a2, -x*(a2-1));
        subsub_add(1, 1, a1, a2, x);
    }

    // a1 <= x < b1, a2 <= y < b2
    inline void add(int a1, int a2, int b1, int b2, long long x) {
        sub_add(a1, a2, x);
        sub_add(a1, b2, -x);
        sub_add(b1, a2, -x);
        sub_add(b1, b2, x);
    }

    inline T subsub_sum(int f, int s, int a, int b) {
        T res = 0;
        for (int i = a; i > 0; i -= i & -i) 
            for (int j = b; j > 0; j -= j & -j) 
                res = res + dat[f][s][i][j];
        return res;
    }

    inline T sub_sum(int a1, int a2) {
        T res = 0;
        res += subsub_sum(0, 0, a1-1, a2-1);
        res += subsub_sum(1, 0, a1-1, a2-1) * (a2-1);
        res += subsub_sum(0, 1, a1-1, a2-1) * (a1-1);
        res += subsub_sum(1, 1, a1-1, a2-1) * (a1-1) * (a2-1);
        return res;
    }

    // a1 <= x < b1, a2 <= y < b2
    inline T sum(int a1, int a2, int b1, int b2) {
        return sub_sum(b1, b2) - sub_sum(a1, b2) - sub_sum(b1, a2) + sub_sum(a1, a2);
    }

    void print() {
        for (int i = 1; i <= SIZE1; ++i) {
            for (int j = 1; j <= SIZE2; ++j) 
                cout << sum(i, j, i+1, j+1) << ",";
            cout << endl;
        }
    }
};

