pair<long long, long long> D(long long n) {
  vector<pair<long long, long long> > v;
  for (long long i = 2; i * i <= n; i++) {
    pair<long long, long long> p = pair<long long, long long>(0, i);
    while (n % i == 0) {
      n /= i;
      p.first++;
    }
    if (p.first) v.push_back(p);
  }
  if (n > 1) v.push_back(pair<long long, long long>(1, n));
  sort(v.begin(), v.end(), greater<pair<long long, long long> >());
  return v[0];
}
