        int nxt_a = down[pre][a][b][d] + 1;
        if(nxt_a > c) return true;
        if(down[pre][nxt_a][b][d] >= c) return true;
    }
    if(right[pre][b][a][c] != -1) {
        int nxt_b = right[pre][b][a][c] + 1;
        if(nxt_b > d) return true;
        if(right[pre][nxt_b][a][c] >= d) return true;
    }
    return false;
};

template<typename Func>
void trans(Func chk) {
    for(int x = 1 ; x <= n ; x++)
    for(int l = 1 ; l <= m ; l++)
    for(int r = l ; r <= m ; r++) {
        if(!chk(x , l , x , r)) {down[now][x][l][r] = -1; continue;}
        int L = x , R = n , mid;
        while(L < R) {
            mid = (L + R + 1) >> 1;
            if(chk(x , l , mid , r)) L = mid;
            else R = mid - 1;
        }
        down[now][x][l][r] = L;
    }
    for(int y = 1 ; y <= m ; y++)
    for(int l = 1 ; l <= n ; l++)
    for(int r = l ; r <= n ; r++) {
        if(!chk(l , y , r , y)) {right[now][y][l][r] = -1; continue;}
        int L = y , R = m , mid;
        while(L < R) {
            mid = (L + R + 1) >> 1;
            if(chk(l , y , r , mid)) L = mid;
            else R = mid - 1;
        }
        right[now][y][l][r] = L;
    }    
}
