vector<pair<ll, ll>> getPrimes(ll x) {
  vector<pair<ll, ll>> ans;
  for (ll i = 2; i * i <= x; i++) {
    if (x % i) continue;
    ans.push_back({i, 0});
    while (x % i == 0) {
      x /= i;
      ans[ans.size() - 1].second++;
    }
  }
  if (x > 1) {
    ans.push_back({x, 1});
  }
  return ans;
}
vector<ll> getD(ll x) {
  vector<ll> ans;
  for (ll i = 1; i * i <= x; i++) {
    if (x % i) continue;
    ans.push_back(i);
    ans.push_back(x / i);
  }
  sort((ans).begin(), (ans).end());
  ans.resize(unique((ans).begin(), (ans).end()) - ans.begin());
  return ans;
}
ll gcd(ll a, ll b) {
  while (b) {
    a %= b;
    swap(a, b);
  }
  return a;
}
ll binpow(ll a, ll n, ll mod) {
  ll ans = 1;
  while (n) {
    if (n & 1) {
      ans = (ll)ans * a % mod;
    }
    a = (ll)a * a % mod;
    n >>= 1;
  }
  return ans;
}
ll n, m, p;
vector<ll> a;
ll h;
vector<ll> d;
vector<pair<ll, ll>> primes;
void init() { d = getD(p - 1); }
ll getOrd(ll a) {
  for (auto i : d) {
    if (binpow(a, i, p) == 1) {
      return i;
    }
  }
  assert(false);
  return -1;
}
