const int maxn = 2e6 + 85 - 69;
int ans[maxn], n;
long long int sum;
void solve(int n, int st = 0) {
  int id = 0;
  while ((1 << (id + 1)) <= n) id++;
  if (n & (n - 1)) {
    int rem = n & ((1 << id) - 1);
    sum += 2 * rem * (1 << id);
    for (int i = 0; i < rem; i++) ans[st + n - rem - i - 1] += 1 << id;
    solve(n - rem, st);
    solve(rem, st + n - rem);
    return;
  }
  sum += (n - 1) * n;
  for (int i = 0; i < n; i++) ans[st + n - 1 - i] += i;
  return;
}
