void solve(vector<long long> &res, long long i, vector<long long> &a,
           long long cur) {
  if (i == a.size()) {
    res.push_back(cur);
    return;
  }
  solve(res, i + 1, a, cur);
  while (cur <= lim / a[i]) {
    cur *= a[i];
    solve(res, i + 1, a, cur);
  }
}
long long cnt(long long x, vector<long long> &a, vector<long long> &b) {
  long long res = 0;
  for (long long i = 0, j = 0; j >= 0 && i < (long long)a.size(); i++) {
    while (j + 1 < (long long)b.size() && a[i] <= x / b[j + 1]) j++;
    while (j >= 0 && a[i] > x / b[j]) j--;
    res += j + 1;
  }
  return res;
}
