  if (x == '4')
    ans += '4', --a;
  else
    ans += '7', --b;
  while (c > 0 || d > 0) {
    if (ans.back() == '4')
      ans.push_back('7'), --c, --b;
    else
      ans.push_back('4'), --d, --a;
  }
  if (a < 0 || b < 0 || c < 0 || d < 0) return "-1";
  for (int i = 0; i < ans.size(); ++i) {
    if (ans[i] == '4' && f_idx == -1) f_idx = i;
    if (ans[i] == '7') s_idx = i;
  }
  for (int i = 0; i < ans.size(); ++i) {
    ret += ans[i];
    if (i == f_idx)
      while (a > 0) ret += '4', --a;
    if (i == s_idx)
      while (b > 0) ret += '7', --b;
  }
  return ret;
}
