int n, cnt = 1, head[maxn], d[maxn];
long long a[maxn], b[maxn];
struct edge {
  int to, next, c;
} e[maxn << 1];
inline void add_edge(int from, int to, int cost) {
  e[cnt].to = to;
  e[cnt].c = cost;
  e[cnt].next = head[from];
  head[from] = cnt++;
  e[cnt].to = from;
  e[cnt].c = cost;
  e[cnt].next = head[to];
  head[to] = cnt++;
}
long long q_pow(long long x, int y) {
  long long res = 1;
  while (y) {
    if (y & 1) res = res * x % 1000000007;
    y >>= 1;
    x = x * x % 1000000007;
  }
  return res;
}
void dfs(int x, int fa, int pre) {
  if (fa && d[x] == 1) return;
  long long sum = pre, A = 0;
  for (int i = head[x]; i; i = e[i].next) {
    int y = e[i].to;
    if (y == fa) continue;
    dfs(y, x, e[i].c);
    sum = (sum + e[i].c + b[y]) % 1000000007;
    A = (A + a[y]) % 1000000007;
  }
  a[x] = q_pow(((d[x] - A) % 1000000007 + 1000000007) % 1000000007,
               1000000007 - 2);
  b[x] = sum * a[x] % 1000000007;
}
