template<class Str> struct SA{
	Str s;
	vi sa,rsa,lcp;
	SA(){}
	SA(Str _s,vi _sa):s(_s),sa(_sa){
		int n=s.size();
		rsa=vi(n+1);
		REP(i,n+1)
			rsa[sa[i]]=i;
		lcp=vi(n);
		int h=0;
		REP(i,n){
			int j=sa[rsa[i]-1];
			if(h>0)h--;
			for(;j+h<n&&i+h<n;h++)
				if(s[j+h]!=s[i+h])
					break;
			lcp[rsa[i]-1]=h;
		}
	}
};

template<class Str> vi doublingSA(Str s){
	int n=s.size();
	vi sa(n+1);
	vi rsa(n+1);
	iota(ALL(sa),0);
	REP(i,n+1){
		rsa[i]=i<n?s[i]:-1;
	}
	vi tmp(n+1);
	for(int k=1;k<=n;k*=2){
		auto cmp=[&](int x,int y){
			if(rsa[x]!=rsa[y]) return rsa[x]<rsa[y];
			int rx=x+k<=n?rsa[x+k]:-1;
			int ry=y+k<=n?rsa[y+k]:-1;
			return rx<ry;
		};
		sort(ALL(sa),cmp);
		tmp[sa[0]]=0;
		FOR(i,1,n+1){
			tmp[sa[i]]=tmp[sa[i-1]]+cmp(sa[i-1],sa[i]);
		}
		copy(ALL(tmp),rsa.begin());
	}
	return sa;
}

