const int inf=INT_MAX/2-100;

struct SparseTable{
	vector<vi> data;
	SparseTable(vi v){
		int n=v.size();
		if(n==0)return;
		int lg=bsr(n)+1;
		data.resize(lg);
		data[0]=v;
		int l=1;
		FOR(s,1,lg){
			data[s]=vi(n);
			REP(i,n-l)
				data[s][i]=min(data[s-1][i],data[s-1][i+l]);
			l<<=1;
		}
	}
	int Query(int l,int r){
		if(r<=l)return inf;
		int u=bsr(r-l);
		return min(data[u][l],data[u][r-(1<<u)]);
	}
};

struct SegTree{
	int s;
	vi buf;
	SegTree(int n){
		s=1;
		while(s<n)s*=2;
		buf.resize(s*2,inf);
	}
	void Update(int i,int v){
		i+=s;
		buf[i]=v;
		while(i>>=1){
			buf[i]=min(buf[i*2],buf[i*2+1]);
		}
	}
	int Get(int b,int e,int l,int r,int i){
		if(e<=l||r<=b)return inf;
		if(b<=l&&r<=e)return buf[i];
		return min(Get(b,e,l,(l+r)/2,i*2),Get(b,e,(l+r)/2,r,i*2+1));
	}
	int Get(int b,int e){
		assert(b<e);
		return Get(b,e,0,s,1);
	}
};

