      points[i] = matrix_t::rotation(1) * points[i];

    double a = 0;

    for (int i = 0; i < n; i ++)
      a += dfs(i, 0, 2 * M_PI, 0);

    std::cout << std::setprecision(14) << a << std::endl;
  }

