const int N = 1e5 + 7, K = 333;
int L[N], R[N], bl[N], g[N], a[N], cnt[N], tag[N], i, j, B, n, m, tot, op, l, r,
    x;
int F(int x, int y) {
  while (x != y) {
    if (a[x] < a[y]) swap(x, y);
    x = max(1, a[x] - tag[bl[x]]);
    if (x == 1 || y == 1) return 1;
  }
  return x;
}
int lca(int u, int v) {
  while (u != v) {
    if (bl[u] == bl[v]) {
      if (g[u] == g[v])
        return F(u, v);
      else {
        if (g[u] < g[v])
          v = max(1, g[v] - tag[bl[v]]);
        else
          v = max(1, g[u] - tag[bl[u]]);
      }
    } else {
      if (g[u] < g[v])
        v = max(g[v] + tag[bl[v]], 1);
      else
        u = max(g[u] - tag[bl[v]], 1);
    }
  }
  return v;
}
void rebuild(int x) {
  g[L[x]] = a[L[x]];
  for (int i = L[x]; i <= R[x]; ++i)
    if (bl[a[i]] == bl[i])
      g[i] = g[a[i]];
    else
      g[i] = a[i];
}
void go(int l, int r, int x) {
  if (tag[bl[l]])
    for (int i = l; i <= r; ++i) a[i] = g[i] = max(a[i] - x, 1);
  else {
    for (int i = l; i <= r; ++i) a[i] = max(a[i] - x, 1);
    rebuild(bl[l]);
  }
}
void update(int x, int val) {
  cnt[x]++;
  if (cnt[x] > K)
    tag[x] = max(tag[x], val);
  else {
    for (int i = L[x]; i <= R[x]; ++i) a[i] = max(1, a[i] - val);
    rebuild(x);
  }
}
void modify(int l, int r, int x) {
  if (bl[l] == bl[r])
    go(l, r, x);
  else {
    go(l, R[bl[l]], x);
    go(L[bl[r]], r, x);
    for (int i = bl[l] + 1; i < bl[r]; ++i) update(i, x);
  }
}
