  for (scanf("%d%d", &n, &m), B = sqrt(n), a[1] = 1, i = 2; i <= n; ++i) {
    scanf("%d", a + i);
    tot = bl[i] = i / B + 1;
    if (!L[bl[i]]) L[bl[i]] = i;
