const decimal pi = acos(-1), eps = 1e-15;
inline decimal move(decimal x) {
  if (x >= 2 * pi) x -= 2 * pi;
  if (x < 0) x += 2 * pi;
  return x;
}
decimal left[500005], right[500005], app[500005];
int stk[500005], goal[500005], nxt[500005][25];
std::pair<int, int> eve[500005];
bool check(int n, int lim, decimal rad) {
  memset(left, 0, sizeof(left));
  memset(right, 0, sizeof(right));
  memset(app, 0, sizeof(app));
  memset(stk, 0, sizeof(stk));
  memset(goal, 0, sizeof(goal));
  memset(nxt, 0, sizeof(nxt));
  int cnt = 0;
  for (int i = 0; i < n; i++) {
    decimal d = sqrtl(sqr(arr[i].x) + sqr(arr[i].y));
    decimal alpha = atan2l(arr[i].y, arr[i].x);
    decimal delta = acosl(rad / d);
    alpha = move(alpha);
    left[i] = move(alpha - delta);
    right[i] = move(alpha + delta);
    app[cnt++] = left[i];
    app[cnt++] = right[i];
  }
  std::sort(app, app + cnt);
  for (int i = 0; i < cnt * 2; i++) goal[i] = 1e9;
  for (int i = 0; i < n; i++) {
    int l = std::lower_bound(app, app + cnt, left[i] - eps) - app,
        r = std::lower_bound(app, app + cnt, right[i] - eps) - app;
    if (l <= r) {
      goal[l] = std::min(goal[l], r);
      goal[l + cnt] = std::min(goal[l + cnt], r + cnt);
    } else
      goal[l] = std::min(goal[l], r + cnt);
  }
  int m = 0;
  for (int i = 0; i < cnt * 2; i++) {
    if (goal[i] == 1e9) continue;
    while (m && goal[stk[m]] >= goal[i]) m--;
    stk[++m] = i;
  }
  for (int i = 1; i <= m; i++) eve[i - 1] = {stk[i], goal[stk[i]]};
  for (int i = 0; i < m; i++)
    eve[i + m] = {eve[i].first + cnt, eve[i].second + cnt};
  std::sort(eve, eve + m * 2);
  for (int i = 0; i < m * 2; i++)
    nxt[i][0] = std::lower_bound(eve, eve + m * 2,
                                 std::make_pair(eve[i].second + 1, -1)) -
                eve;
  nxt[m * 2][0] = m * 2;
  for (int j = 1; j < 20; j++) {
    for (int i = 0; i <= m * 2; i++) nxt[i][j] = nxt[nxt[i][j - 1]][j - 1];
  }
  for (int i = 0; i < m; i++) {
    int cur = i, res = 1;
    for (int j = 19; j >= 0; j--) {
      if (nxt[cur][j] < i + m) {
        res += 1 << j;
        cur = nxt[cur][j];
      }
    }
    if (res <= lim) return true;
  }
  return false;
}
int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  decimal l = 0, r = 1e9;
  for (int i = 0; i < n; i++) {
    int x, y;
    scanf("%d%d", &x, &y);
    arr[i].x = x;
    arr[i].y = y;
    r = std::min(r, sqrtl(sqr(arr[i].x) + sqr(arr[i].y)));
  }
  while (r - l > 1e-7) {
    decimal mid = (l + r) / 2;
    if (check(n, m, mid))
      l = mid;
    else
      r = mid;
  }
  printf("%.10lf\n", (double)l);
  return 0;
}

