#include <bits/stdc++.h>
using namespace std;
int pen[500005];
void update(int ind, int add) {
  while (ind < 500005) {
    pen[ind] += add;
    ind += ind & (-ind);
  }
}
int query(int ind) {
  int ret = 0;
  while (ind > 0) {
    ret = ret + pen[ind];
    ind = ind & (ind - 1);
  }
  return ret;
}
int a[500005];
long long getSum(int r, int bit, int n, int len) {
  long long ret = 0;
  if (r == len) {
    return query(pen[len]);
  }
  if (r == 0) {
    return 0;
  }
  int mybit = 0;
  for (int i = n; i >= 0; --i) {
    if (bit & (1 << i)) {
      mybit ^= (1 << i);
    }
    if (r & (1 << i)) {
      ret += query(mybit + (1 << i)) - query(mybit);
      mybit ^= (1 << i);
    }
  }
  return ret;
}
void solve() {
  int n, q;
  scanf(" %d %d ", &n, &q);
  int len = (1 << n);
  for (int i = 0; i < len; ++i) {
    scanf("%d ", &a[i]);
    update(i + 1, a[i]);
  }
  int bit = 0;
  while (q--) {
    int type, x;
    scanf("%d %d ", &type, &x);
    if (type == 1) {
      int k;
      scanf("%d ", &k);
      int nind = (x - 1) ^ bit;
      update(nind + 1, k - a[nind]);
      a[nind] = k;
    } else if (type == 2) {
      bit ^= (1 << x) - 1;
    } else if (type == 3) {
      bit ^= (1 << x);
    } else {
      int y;
      scanf("%d ", &y);
      printf("%lld\n", getSum(y, bit, n, len) - getSum(x - 1, bit, n, len));
    }
  }
}
int main() {
  solve();
  return 0;
}

