pair<int, int> f(int n, vector<int>& a, vector<int>& b) {
  int m = a.size();
  union_find uf(n);
  for (int i = 0; i < m; i++) uf.unite(a[i], b[i]);
  vector<vector<int> > as(n), bs(n);
  for (int i = 0; i < m; i++) {
    int u = uf.find(a[i]);
    as[u].push_back(a[i]);
    bs[u].push_back(b[i]);
  }
  pair<int, int> ans(0, 1);
  for (int u = 0; u < n; u++) {
    if (uf.find(u) != u) continue;
    pair<int, int> p = g(as[u], bs[u]);
    ans.first += p.first;
    ans.second = (long long)ans.second * p.second % MOD;
  }
  return ans;
}
