    a[i] = lower_bound(v.begin(), v.end(), a[i]) - v.begin();
    b[i] = lower_bound(v.begin(), v.end(), b[i]) - v.begin();
  }
  if (m == (long long)n * (n - 1) / 2) return pair<int, int>(1, n);
  vector<int> d(n);
  for (int i = 0; i < m; i++) {
    d[a[i]]++;
