		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int n = in.nextInt();
			int k = in.nextInt();
			List<Integer> p = new ArrayList<Integer>(n);
			for (int i = 0; i < n; i++) {
				p.add(in.nextInt());
			}
			int resSum = 255*n;
			List<Integer> respt = null;
			for(int x = 0 ; x < k ; x++){
				int sum = 0;
				List<Integer> pt = new ArrayList<Integer>(n);
				for(int color : p){
					for (int j = x; j <= 255; j += k) {
						if(color < x){
							pt.add(0);
							break;
						}
						if (color >= j && color <= (j + k - 1)) {
							pt.add(j);
							sum += j;
							break;
						}
					}
				}
				if(resSum > sum){
					resSum = sum;
					respt = pt;
				}
			}
