int fun(int i, int g1, int g2, int r1, int r2, string &a) {
  if (i == a.size()) {
    return 10;
  }
  if (g1 > g2 + r2) {
    return i;
  }
  if (g2 > g1 + r1) {
    return i;
  }
  if (a[i] == '1') {
    if (i % 2 == 0) {
      g1++;
      r1--;
    } else {
      g2++;
      r2--;
    }
    return fun(i + 1, g1, g2, r1, r2, a);
  } else if (a[i] == '0') {
    if (i % 2 == 0) {
      r1--;
    } else {
      r2--;
    }
    return fun(i + 1, g1, g2, r1, r2, a);
  } else {
    if (i % 2 == 0) {
      return min(fun(i + 1, g1 + 1, g2, r1 - 1, r2, a),
                 fun(i + 1, g1, g2, r1 - 1, r2, a));
    } else {
      return min(fun(i + 1, g1, g2 + 1, r1, r2 - 1, a),
                 fun(i + 1, g1, g2, r1, r2 - 1, a));
    }
  }
}
