vector<int> same_bit(int n) {
  if (n <= 5 || n - (n & -n) == 0) return {-1};
  map<int, vector<int>> biti;
  vector<int> ans = {0};
  for (int i(1); i <= n; i++) ans.push_back(i);
  ans[1] = 5, ans[5] = 1;
  ans[2] = 3, ans[3] = 2;
  biti[1].push_back(4);
  for (int i(6), sz(1); i <= n; i++) {
    if (i - (i & -i) == 0) sz++;
    biti[sz].push_back(i);
  }
  for (auto v : biti) {
    for (int j(0); j < v.second.size() - 1; j++)
      ans[v.second[j]] = v.second[j + 1];
    ans[v.second.back()] = v.second[0];
  }
  return ans;
}
