void dif_bit(int n, int bitmax) {
  if (n == 0) return;
  while ((1 << bitmax) > n) bitmax--;
  int cnt = (1 << bitmax) - 1, all = (1 << (bitmax + 1)) - 1;
  for (int i(1 << bitmax); i <= n; i++) {
    cuplat[i] = i ^ all;
    cuplat[i ^ all] = i;
    cnt--;
  }
  dif_bit(cnt, bitmax - 1);
}
