#include <iostream>
#include <vector>
#include <tuple>

template <class T>
std::vector<T> vec(int len, T elem) { return std::vector<T>(len, elem); }

const std::vector<std::pair<int, int>> dxys{{1, 0}, {0, 1}};

bool solve() {
    int h, w, n;
    std::cin >> h >> w >> n;
    if (h == 0) return false;

    auto way = vec(h, vec(w, 0));
    for (auto& v : way) {
        for (auto& x : v) std::cin >> x;
    }

    auto visit = vec(h, vec(w, 0));
    visit[0][0] = n - 1;

    for (int x = 0; x < h; ++x) {
        for (int y = 0; y < w; ++y) {
            int m = visit[x][y];
            for (int i = 0; i < 2; ++i) {
                int dx, dy;
                std::tie(dx, dy) = dxys[i];

                int nx = x + dx,
                    ny = y + dy;
                if (nx >= h || ny >= w) continue;

                visit[nx][ny] += m / 2 + (m % 2 == 1 && way[x][y] == i);
            }

            if (m % 2 == 1) way[x][y] = 1 - way[x][y];
        }
    }

    int x = 0, y = 0;
    while (x < h && y < w) {
        int dx, dy;
        std::tie(dx, dy) = dxys[way[x][y]];
        x += dx, y += dy;
    }

    std::cout << x + 1 << " " << y + 1 << "\n";
    return true;
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    while (solve()) {}

