class XMath {
	public static final long DEFAULT_MOD = (long)1e9 + 7;
	public static long mod(long n, long MOD) {
		if (n < MOD) {
			if (n < 0) {
				return MOD - mod(-n, MOD);
			}
			return n;
		}
		return n % MOD;
	}
	public static long mod(long n) {
		return mod(n, DEFAULT_MOD);
	}
}

