int dfs(int S, int T, int now)
{
    if(dp[S][T][now]>=0) return dp[S][T][now];

    int M=(1<<k)-1;
    if(S==M && T==M) return 0;

    int ret=INF;

    rep(i,k)
    {
        if(!(S>>i&1)) ret = min(ret, dfs(S|(1<<i), T, i+1)+dist[now][s[i]]);
    }
    rep(i,k)
    {
        if((S>>i&1) && !(T>>i&1)) ret = min(ret, dfs(S, T|(1<<i), 1+k+i)+dist[now][t[i]]);
    }

    return dp[S][T][now]=ret;
}

