public class TC
{
    static int[] a;
    static int N, p;
    static HashMap<Pair, ArrayList<Integer>> memo;
    static HashMap<Integer, BigInteger> fact;

    static BigInteger factorial( int n )
    {
        if( ( n==0 ) || (n==1 )|| ( n==2 ))
            return new BigInteger( Integer.toString( n ));

        if( fact.containsKey(n))
            return fact.get( n );

        BigInteger res=factorial( n-1 ).multiply( new BigInteger( Integer.toString( n )));
        fact.put( n, res );
        return res;
    }

    static void solve()
    {
        memo=new HashMap();
        fact=new HashMap();
        ArrayList<Integer> res=f( 0, p );
        BigInteger sum=new BigInteger( "0");

        for( int x : res )
        {
            BigInteger pf=factorial( x );
            BigInteger pcomp=factorial( N-x);
            BigInteger prod=pf.multiply( pcomp );
            prod=prod.multiply( new BigInteger( Integer.toString(x) ));
            sum=sum.add( prod );
        }

        BigInteger nf=factorial( N );
        BigDecimal out=new BigDecimal( sum.toString() );
        BigDecimal den=new BigDecimal( nf.toString() );
        BigDecimal C=new BigDecimal( "10000000000000");
        out=out.multiply( C );
        out=out.divide( den, BigDecimal.ROUND_UP );
        out=out.divide( C );

        System.out.println( out.toString() );
    }

    static ArrayList<Integer> f( int i, int sum )
    {
        if( i>=N )
        {
            return null;
        }

        Pair state=new Pair( i, sum );
        if( memo.containsKey( state ))
        {
            return memo.get( state);
        }

        ArrayList<Integer> a1=new ArrayList();

        if( a[i]<= sum )
        {
            ArrayList<Integer> temp=f( i+1, sum-a[i]);
            if( temp!= null )
            for( int x : temp )
                a1.add( x+1 );

            else
                a1.add( 1 );
        }

        ArrayList<Integer> temp=f( i+1, sum);

        if( temp!=null )
        for( int x : temp )
                a1.add( x );

        if( a1.size() == 0 )
            a1=null;
        memo.put( state, a1 );
        return a1;
    }

    public static void main( String[] args ) throws IOException
    {
        BufferedReader br=new BufferedReader( new InputStreamReader( System.in ));
        N=Integer.parseInt( br.readLine() );
        String s=br.readLine();
        StringTokenizer tok=new StringTokenizer( s );
        a=new int[N];

        for( int i=0; i<N; i++ )
        {
            a[i]=Integer.parseInt( tok.nextToken() );
        }

        p=Integer.parseInt( br.readLine() );
        solve();
    }
}

class Pair implements Comparable
{
    int first, second; // first -> primary key for sorting/comparison

    public Pair( int _x1, int _x2 )
    {
        first = _x1;
        second = _x2;
    }

    public int compareTo( Object o )
    {
        Pair n = ( Pair ) o ;

        if( first != n.first )
            return first-n.first;

        else
            return second-n.second;
    }

    public int hashCode() // Always check for equality after retrieving from hashtable to detect collisions ! 
    {
        int result = 23;
        result = 31*result + first;
        result = 31*result + second;
        return result;

    }

    public boolean equals( Object o )
    {
        Pair p = ( Pair ) o;

        if( first == p.first )
            if( second == p.second )
                return true;

        return false;
    }


}

