bool binary_search(int *seq, int n, int key) {
  int left = 0, right = n, mid;
  int flag = false;
  while (left < right) {
    mid = (left + right) / 2;
    cout << "mid" << mid << endl;
    if (seq[mid] == key) {
      flag = true;
      break;
    } else if (seq[mid] > key)
      right = mid;
    else
      left = mid + 1;
  }
  return flag;
}
