class A {
    public void solve(int testNumber, PandaScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] x = new int[n];
        int[] y = new int[n];
        int[] r = new int[m];
        for (int i = 0; i < n; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }
        for (int i = 0; i < m; i++) {
            r[i] = in.nextInt();
        }
        int fold[] = new int[n];
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            int k = (i - 1 + n) % n;
            fold[i] += Math.abs(x[i] - x[j]) + Math.abs(y[i] - y[j]);
            fold[i] += Math.abs(x[i] - x[k]) + Math.abs(y[i] - y[k]);
        }

        int[] res = new int[n];
        for (int start = 0; start < 2; start++) {
            Arrays.fill(res, -1);
            boolean good = true;
            int j = 0;
            for (int i = start; i < n; i += 2, j++) {
                while (j < m && fold[i] != r[j]) {
                    j++;
                }
                if (j >= m) {
                    good = false;
                    break;
                }
                res[i] = j + 1;
            }
            if (good) {
                StringBuilder assignment = new StringBuilder();
                for (int i = 0; i < n; i++) {
                    assignment.append(res[i]);
                    assignment.append(" ");
                }
                out.println("YES\n" + assignment);
                return;
            }
        }
        out.println("NO");

    }
}

