  for (int i = (int)0; i < (int)4; i++) {
    ret += pow(2, i) * ((x % 2) && (y % 2));
    x /= 2;
    y /= 2;
  }
  return ret;
}
int orr(int x, int y) {
  int ret = 0;
  for (int i = (int)0; i < (int)4; i++) {
    ret += pow(2, i) * ((x % 2) || (y % 2));
    x /= 2;
    y /= 2;
  }
  return ret;
}
int hashh(string s, string ss) {
  stack<int> st;
  int a, b, c, d;
  d = ss[3] - '0';
  c = ss[2] - '0';
  b = ss[1] - '0';
  a = ss[0] - '0';
  reverse((s).begin(), (s).end());
  for (int i = (int)0; i < (int)s.size(); i++) {
    if (s[i] == 'a')
      st.push(a);
    else if (s[i] == 'b')
      st.push(b);
    else if (s[i] == 'c')
      st.push(c);
    else if (s[i] == 'd')
      st.push(d);
    else if (s[i] == '+') {
      int x = st.top();
      st.pop();
      int y = st.top();
      st.pop();
      st.push(orr(x, y));
    } else if (s[i] == '*') {
      int x = st.top();
      st.pop();
      int y = st.top();
      st.pop();
      st.push(andd(x, y));
    } else if (s[i] == '^') {
      int x = st.top();
      st.pop();
      int y = st.top();
      st.pop();
      st.push(x ^ y);
    }
  }
  return st.top();
}
