    if ((1 << i) & d) u = dp[u][i];
  if (u == v) return u;
  for (int i = 20 - 1; i >= 0; i--) {
    if (dp[u][i] == dp[v][i]) continue;
    u = dp[u][i], v = dp[v][i];
  }
  return dp[u][0];
}
int dist(int u, int v) { return level[u] + level[v] - 2 * level[lca(u, v)]; }
int calc_size(int u, int p) {
  size[u] = 0;
  for (auto v : g[u]) {
    if (v == p) continue;
    size[u] += calc_size(v, u);
  }
  return size[u] += 1;
}
int find_centroid(int u, int t_size, int p) {
  layer++;
  if (layer > 100001) exit(-1);
  for (auto v : g[u])
    if (v != p && 2 * size[v] > t_size) return find_centroid(v, t_size, u);
  return u;
}
void decompose(int u, int l, int parent) {
  layer = 0;
  int n_nodes = calc_size(u, -1);
  int centroid = find_centroid(u, n_nodes, parent);
  if (parent == -1) parent = centroid;
  c_par[centroid] = parent;
  c_level[centroid] = l;
  for (auto v : g[centroid]) {
    g[v].erase(centroid);
    decompose(v, l + 1, centroid);
  }
  g[u].clear();
  return;
}
void update(int u) {
  ans[u] = 0;
  int v = u;
  while (v) {
    ans[v] = min(ans[v], dist(u, v));
    v = c_par[v];
  }
}
int query(int u) {
  int v = u, t_ans = ans[u];
  while (v) {
    t_ans = min(t_ans, ans[v] + dist(u, v));
    v = c_par[v];
  }
  return t_ans;
}
