        can[i][j] = 1;
  int t1 = cal(n);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (a[i][j] & 2)
        can[i][j] = 0;
      else
        can[i][j] = 1;
  int t2 = cal(n);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      if (a[i][j])
        can[i][j] = 0;
      else
        can[i][j] = 1;
  int t3 = cal(n);
  if (mask == 1) return (fac[n] - t2 + M) % M;
  if (mask == 2) return (fac[n] - t1 + M) % M;
  return ((fac[n] - t1 - t2 + t3) % M + M) % M;
}
