#include <bits/stdc++.h>
using namespace std;
const int N = 3000000, p2 = 1000007;
struct Hash {
  struct Edge {
    int x, y, nex;
  } g[N * 2];
  int sz, pos[p2];
  void Ins(int x, int y) {
    int x0 = x % p2;
    g[++sz] = (Edge){x, y, pos[x0]}, pos[x0] = sz;
  }
  int fd(int x) {
    int x0 = x % p2;
    for (int i = pos[x0]; i; i = g[i].nex)
      if (g[i].x == x) return g[i].y;
    return 0;
  }
} m1, m2;
int n, m, p, g = 1, d[N], dz, st, T, a[N], b[N], c[N];
long long sp = 1, f[N], Id[N], ans;
int gcd(int x, int y) { return !y ? x : gcd(y, x % y); }
int Pow(long long x, int y) {
  long long z = 1;
  while (y) {
    if (y & 1) (z *= x) %= p;
    (x *= x) %= p, y >>= 1;
  }
  return z;
}
bool Check(int x) {
  for (int i = 1; i <= dz; i++)
    if (d[i] != p - 1 && Pow(g, d[i]) == 1) return 0;
  return 1;
}
void Pre() {
  while (!Check(g)) g++;
  for (int i = 1; i <= st; i++) {
    (sp *= g) %= p;
    m1.Ins(sp, i);
  }
}
int Find(int x) {
  long long z = sp, x0 = Pow(x, p - 2), n1 = st;
  while (1) {
    long long z0 = z * x0 % p, mf = m1.fd(z0);
    if (mf) return n1 - mf;
    (z *= sp) %= p, n1 += st;
  }
}
int main() {
  scanf("%d%d%d", &n, &m, &p), T = p - 1;
  st = min(N, p - 1);
  for (int i = 1; i * i <= T; i++) {
    if (T % i == 0) {
      d[++dz] = i;
      if (i * i != T) d[++dz] = T / i;
    }
  }
  sort(d + 1, d + dz + 1);
  Pre();
  for (int i = 1; i <= dz; i++) m2.Ins(d[i], i);
  for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
  for (int i = 1; i <= m; i++) scanf("%d", &b[i]), T = gcd(T, b[i]);
  for (int i = 1; i <= n; i++) {
    Id[i] = Find(a[i]), c[i] = gcd(Id[i] * T % (p - 1), p - 1);
  }
  f[1] = -1;
  for (int i = 1; i <= n; i++) {
    for (int j = dz; j >= 1; j--) {
      int k = d[j] / gcd(d[j], c[i]) * c[i], k0 = m2.fd(k);
      f[k0] -= f[j];
    }
  }
  f[1]++;
  for (int i = 1; i <= dz; i++) ans += f[i] * ((p - 1) / d[i]);
  printf("%I64d\n", ans);
  return 0;
}

