long long mpow(long long a) { return a * a * a * a * a; }
long long test(long long search) {
  long long l = -4000, r = min(4000LL, search);
  while (l <= r) {
    long long m = l + (r - l) / 2LL;
    long long res = mpow(m);
    if (res == search) {
      return m;
    }
    if (res < search) {
      l = m + 1;
    } else {
      r = m - 1;
    }
  }
  return 1e9;
}
