long long cnt;
Node v[20 * arr];
void sons(long long u) {
  if (v[u].l == 0) v[u].l = ++cnt;
  if (v[u].r == 0) v[u].r = ++cnt;
}
void make_push(long long i, long long tl, long long tr) {
  if (tl == tr) return;
  sons(i);
  if (v[i].pusha == 0 && v[i].pushb == 0) return;
  long long l = v[i].l;
  long long r = v[i].r;
  long long pa = v[i].pusha;
  long long push_back = v[i].pushb;
  long long d = (tl + tr) / 2;
  long long nl = ++cnt;
  long long nr = ++cnt;
  v[nl] = v[l];
  v[nr] = v[r];
  l = nl;
  r = nr;
  v[i].l = l;
  v[i].r = r;
  v[l].a += pa * (d - tl + 1);
  v[r].a += pa * (tr - d);
  v[l].b += push_back * (d - tl + 1);
  v[r].b += push_back * (tr - d);
  v[l].pusha += pa;
  v[l].pushb += push_back;
  v[r].pusha += pa;
  v[r].pushb += push_back;
  v[i].pusha = 0;
  v[i].pushb = 0;
}
void pluss(long long i1, long long i2, long long tl, long long tr, long long l,
           long long r, long long pa, long long push_back) {
  make_push(i1, tl, tr);
  v[i2] = v[i1];
  if (tl > r || tr < l) return;
  if (tl >= l && tr <= r) {
    v[i2].a += pa * (tr - tl + 1);
    v[i2].b += push_back * (tr - tl + 1);
    v[i2].pusha += pa;
    v[i2].pushb += push_back;
    return;
  }
  long long d = (tl + tr) / 2;
  if (l <= d) {
    v[i2].l = ++cnt;
    pluss(v[i1].l, v[i2].l, tl, d, l, r, pa, push_back);
  }
  if (d < r) {
    v[i2].r = ++cnt;
    pluss(v[i1].r, v[i2].r, d + 1, tr, l, r, pa, push_back);
  }
  v[i2].a = v[v[i2].l].a + v[v[i2].r].a;
  v[i2].b = v[v[i2].l].b + v[v[i2].r].b;
}
pair<long long, long long> get(long long i, long long tl, long long tr,
                               long long x) {
  if (tl == tr) return (make_pair(v[i].a, v[i].b));
  make_push(i, tl, tr);
  long long d = (tl + tr) / 2;
  if (x <= d)
    return (get(v[i].l, tl, d, x));
  else
    return (get(v[i].r, d + 1, tr, x));
}
