template <int NV>
struct LazySegTreeMax {
  using V = pair<int, int>;
  vector<V> dat, lazy;
  LazySegTreeMax() {
    dat.resize(NV * 2, make_pair(0, 1));
    lazy.resize(NV * 2, ldef);
  }
  void init(vector<V> v, V _def) {
    int n = v.size();
    for (int i = 0; i < NV; i++) dat[i + NV - 1] = _def;
    for (int i = 0; i < n; i++) dat[i + NV - 1] = v[i];
    for (int i = NV - 2; i >= 0; i--)
      dat[i] = comp(dat[i * 2 + 1], dat[i * 2 + 2]);
  }
  void update(int a, int b, V v, int k, int l, int r) {
    push(k, l, r);
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      setLazy(k, v);
      push(k, l, r);
    } else {
      update(a, b, v, k * 2 + 1, l, (l + r) / 2);
      update(a, b, v, k * 2 + 2, (l + r) / 2, r);
      dat[k] = comp(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }
  V get(int a, int b, int k, int l, int r) {
    push(k, l, r);
    if (r <= a || b <= l) return def;
    if (a <= l && r <= b) return dat[k];
    auto x = get(a, b, k * 2 + 1, l, (l + r) / 2);
    auto y = get(a, b, k * 2 + 2, (l + r) / 2, r);
    return comp(x, y);
  }
  void update(int a, int b, V v) { update(a, b, v, 0, 0, NV); }
  V get(int a, int b) { return get(a, b, 0, 0, NV); }
  const V def = make_pair(-inf, 0), ldef = make_pair(0, 0);
  V comp(V l, V r) {
    if (l.first != r.first) {
      if (l < r)
        return r;
      else
        return l;
    }
    return make_pair(l.first, l.second + r.second);
  }
  void setLazy(int i, V v) {
    lazy[i].first += v.first;
    lazy[i].second += v.second;
  }
  void push(int k, int l, int r) {
    dat[k].first += lazy[k].first;
    if (r - l > 1) {
      setLazy(k * 2 + 1, lazy[k]);
      setLazy(k * 2 + 2, lazy[k]);
    }
    lazy[k] = ldef;
  }
};
