  void add_edge(ll i, ll j, ll s) {
    e[m] = {j, v[i].n, s};
    v[i].n = m;
    m++;
  }
  void dfs(ll i, ll p, ll f, ll a) {
    v[i].f = f;
    v[i].a = a;
    z0[f - 1] = min(z0[f - 1], a);
    ll f1 = f ^ 3;
    for (ll j = v[i].n; j >= 0; j = e[j].n) {
      Edge& o = e[j];
      if (o.i == p) continue;
      ll a1 = o.s - a;
      if (v[o.i].f < 0) {
        dfs(o.i, i, f1, a1);
      } else {
        if (v[o.i].f != f1) z = 1;
        if (v[o.i].a != a1) z1 = abs(v[o.i].a - a1);
      }
    }
  }
  void clear() {
    z0[0] = z0[1] = 1 << 30;
    z = z1 = 0;
    for (ll i = 0; i < n; i++) {
      v[i].f = -1;
      v[i].a = -1;
    }
  }
  ll ok() {
    ll t0 = 1 - z0[0];
    ll t1 = z0[1] - 1;
    if (t1 < 0) cout << t0 << ' ' << t1 << endl;
    if (t1 < 0) return 0;
    return max(t1 - t0 + 1, 0LL);
  }
  vector<Vertex> v;
  vector<Edge> e;
  ll n, m, z, z1, z0[2];
};
