vector<long long int> dijkstra(int s, int v, vector<vector<pii>> G) {
  PQ<pair<long long int, int>> wait;
  vector<long long int> result(v, INF);
  result[s] = 0;
  wait.push(make_pair(0, s));
  while (!wait.empty()) {
    long long int nowpoint = wait.top().second;
    long long int nowcost = wait.top().first;
    wait.pop();
    if (nowcost <= result[nowpoint]) {
      for (ll i = (0); i < (ll)(G[nowpoint].size()); ++i) {
        long long int nextpoint = G[nowpoint][i].second;
        long long int nextcost = G[nowpoint][i].first - nowcost;
        if (nextcost < result[nextpoint]) {
          wait.push(make_pair(-nextcost, nextpoint));
          result[nextpoint] = nextcost;
        }
      }
    }
  }
  return result;
}
