bool check(int p, int d) {
  bool f = false;
  for (int i = u; i <= u; i++) {
    double x = hx[p] - ux[i];
    double y = hy[p] - uy[i];
    if (x * x + y * y > a[d] * a[d]) continue;
    double c = (atan2(y, x)) * 180 / 3.141592653589793;
    if (c < 0) c = (double)360.0 + c;
    if ((double)w[d] - du / 2 <= c && c <= (double)w[d] + du / 2) f = true;
    if (c < (double)w[d] + du / 2 - 360) f = true;
  }
  if (!f) return false;
  for (int i = 0; i < u; i++) {
    double x = hx[p] - ux[i];
    double y = hy[p] - uy[i];
    if (x * x + y * y > a[d] * a[d]) continue;
    double c = (atan2(y, x)) * 180 / 3.141592653589793;
    if (c < 0) c = (double)360.0 + c;
    if ((double)w[d] - du / 2 <= c && c <= (double)w[d] + du / 2) return false;
    if (c < (double)w[d] + du / 2 - 360) return false;
  }
  for (int i = 0; i < m; i++) {
    double x = hx[p] - mx[i];
    double y = hy[p] - my[i];
    if (x * x + y * y > a[d] * a[d]) continue;
    double c = (atan2(y, x)) * 180 / 3.141592653589793;
    if (c < 0) c = (double)360.0 + c;
    if ((double)w[d] - dm / 2 <= c && c <= (double)w[d] + dm / 2) return false;
    if (c < (double)w[d] + dm / 2 - 360) return false;
  }
  for (int i = 0; i < s; i++) {
    double x = hx[p] - sx[i];
    double y = hy[p] - sy[i];
    if (x * x + y * y > a[d] * a[d]) continue;
    double c = (atan2(y, x)) * 180 / 3.141592653589793;
    if (c < 0) c = (double)360.0 + c;
    if ((double)w[d] - ds / 2 <= c && c <= (double)w[d] + ds / 2) return false;
    if (c < (double)w[d] + ds / 2 - 360) return false;
  }
