struct tree {
  struct node {
    node *l;
    node *r;
    int64_t val;
    node() : l(nullptr), r(nullptr), val(0) {}
  };
  node m_root;
  void update(node *root, int64_t tl, int64_t tr, int64_t pos, int64_t add) {
    if (pos < tl) return;
    if (tl > tr) return;
    if (tl == tr && tl == pos) {
      root->val += add;
      return;
    }
    int64_t tm = (tl + tr) / 2;
    if (pos <= tm) {
      if (!root->l) root->l = new node();
      update(root->l, tl, tm, pos, add);
    } else {
      if (!root->r) root->r = new node();
      update(root->r, tm + 1, tr, pos, add);
    }
    root->val = 0;
    if (root->l) root->val += root->l->val;
    if (root->r) root->val += root->r->val;
  }
  int64_t sum(node *root, int64_t tl, int64_t tr, int64_t l, int64_t r) {
    if (tl > tr) return 0;
    if (l > r) return 0;
    if (tl == l && tr == r) return root->val;
    int64_t tm = (tl + tr) / 2;
    int64_t ans = 0;
    if (root->l) ans += sum(root->l, tl, tm, l, min(r, tm));
    if (root->r) ans += sum(root->r, tm + 1, tr, max(tm + 1, l), r);
    return ans;
  }
};
struct type {
  tree seg;
};
int main(void) {
  std::ios_base::sync_with_stdio(false);
  int n;
