  map<int, type> v;
  for (int i = 0; i < n; ++i) {
    int a, t, x;
    cin >> a >> t >> x;
    if (a == 1) {
      auto &seg = v[x].seg;
      seg.update(&seg.m_root, 1, m, t, 1);
    } else if (a == 2) {
      auto &seg = v[x].seg;
      seg.update(&seg.m_root, 1, m, t, -1);
    } else {
      auto &seg = v[x].seg;
      int64_t ans = seg.sum(&seg.m_root, 1, m, 1, t);
      cout << ans << endl;
    }
  }
  return 0;
}

