}
inline long long F(long long x, long long _mod) {
  long long tmp1 = x, tmp2 = x + 1, tmp3 = x * 2 + 1;
  if (~tmp1 & 1)
    tmp1 /= 2;
  else if (~tmp2 & 1)
    tmp2 /= 2;
  else
