  } else if (x < y) {
    swap(x, y);
    tmp = sub(G(x, mod1), G(y, mod1), mod1);
    ret1 = add(ret1, mul(tmp, y, mod1), mod1);
    ret1 =
        add(ret1,
            mul(y & 1 ? mul(y, (y - 1) / 2, mod1) : mul(y / 2, (y - 1), mod1),
                sub(x, y, mod1), mod1),
            mod1);
    tmp = sub(G(x, mod2), G(y, mod2), mod2);
    ret2 = add(ret2, mul(tmp, y, mod2), mod2);
    ret2 =
        add(ret2,
            mul(y & 1 ? mul(y, (y - 1) / 2, mod2) : mul(y / 2, (y - 1), mod2),
                sub(x, y, mod2), mod2),
            mod2);
    swap(x, y);
  }
  if (inv == 1)
    ans = add(ans, ret1, mod1), pre = add(pre, ret2, mod2);
  else
    ans = sub(ans, ret1, mod1), pre = sub(pre, ret2, mod2);
}
int main() {
  int T = read<int>();
  while (T--) {
    x1 = read<int>(), y1 = read<int>(), x2 = read<int>(), y2 = read<int>();
    pre = 0, ans = 0, calc(x2, y2, 1), calc(x2, y1 - 1, -1),
    calc(x1 - 1, y2, -1), calc(x1 - 1, y1 - 1, 1);
    if (pre ^ ans)
      printf("...%.10lld\n", (long long)ans);
    else
      printf("%lld\n", (long long)ans);
  }
  return 0;
}
