#include <bits/stdc++.h>
using namespace std;
struct Edge {
  int dst;
  long long w;
};
struct Data {
  int cur;
  long long w;
  bool operator<(const Data &data) const {
    if (w != data.w) return w < data.w;
    return cur < data.cur;
  }
};
const int MAX_V = 100010;
int V, E;
vector<Edge> G[MAX_V], rG[MAX_V];
long long maxi[MAX_V];
bool valid[MAX_V];
map<int, set<int> > mp;
bool check(long long limit) {
  memset(maxi, -1, sizeof maxi);
  priority_queue<Data> Q;
  for (set<int>::iterator itr = mp[limit].begin(); itr != mp[limit].end();
       itr++) {
    maxi[*itr] = limit;
    Q.push((Data){*itr, limit});
  }
  while (!Q.empty()) {
    Data data = Q.top();
    Q.pop();
    if (data.cur == 0) {
      return true;
    }
    for (int i = 0; i < (int)G[data.cur].size(); ++i) {
      Edge &e = G[data.cur][i];
      if (e.dst == V - 1) continue;
      if (!valid[e.dst]) continue;
      if (!(data.w >= e.w)) continue;
      if (maxi[e.dst] < e.w) {
        maxi[e.dst] = e.w;
        Q.push((Data){e.dst, e.w});
      }
    }
  }
  return false;
}
void pre_calc() {
  memset(valid, false, sizeof valid);
  deque<int> deq;
  deq.push_back(0);
  valid[0] = valid[V - 1] = true;
  while (!deq.empty()) {
    int cur = deq.front();
    deq.pop_front();
    if (cur == V - 1) continue;
    for (int i = 0; i < (int)rG[cur].size(); ++i) {
      int next = rG[cur][i].dst;
      if (!valid[next]) {
        valid[next] = true;
        deq.push_back(next);
      }
    }
  }
}
void compute() {
  pre_calc();
  vector<long long> vec;
  for (int i = 0; i < (int)G[V - 1].size(); ++i) {
    if (valid[G[V - 1][i].dst]) {
      mp[G[V - 1][i].w].insert(G[V - 1][i].dst);
      vec.push_back(G[V - 1][i].w);
    }
  }
  if (vec.empty()) {
    puts("-1");
    return;
  }
  sort(vec.begin(), vec.end());
  int L = 0, R = (int)vec.size();
  while (R - L) {
    int M = (L + R) / 2;
    if (check(vec[M]))
      L = M + 1;
    else
      R = M;
  }
  if (L - 1 < 0) {
    puts("-1");
  } else {
    cout << vec[L - 1] << endl;
  }
}
int main() {
  cin >> V >> E;
  for (int i = 0; i < E; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    --a, --b;
    G[b].push_back((Edge){a, c});
    rG[a].push_back((Edge){b, c});
  }
  compute();
  return 0;
}

