public class E {
  static boolean[] uni;
  static int n, k;
  static List<List<Edge>> g = new ArrayList<>();

  static class Edge {
    int from, to;
    int count = -1;

    public Edge(int from, int to) {
      this.from = from;
      this.to = to;
    }
  }

  static void dfs(Edge e) {
    if (e.count >= 0) {
      return;
    }
    int i = e.to;
    e.count = uni[i] ? 1 : 0;
    Edge back = null;
    for (Edge j : g.get(i)) {
      if (j.to == e.from) {
        back = j;
        continue;
      }
      dfs(j);
      e.count += j.count;
    }
    back.count =  2 * k - e.count;
  }

  public static void main(String[] arg) throws IOException {
    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    String[] t = in.readLine().split(" ");
    n = Integer.valueOf(t[0]);
    k = Integer.valueOf(t[1]);
    uni = new boolean[n + 1];
    for (String u : in.readLine().split(" ")) {
      uni[Integer.valueOf(u)] = true;
    }
    for (int i = 0; i <= n; i++) {
      g.add(new ArrayList<>());
    }
    for (int i = 0; i < n-1; i++) {
      t = in.readLine().split(" ");
      int a = Integer.valueOf(t[0]);
      int b = Integer.valueOf(t[1]);
      g.get(a).add(new Edge(a, b));
      g.get(b).add(new Edge(b, a));
    }
    for (Edge e : g.get(1)) {
      dfs(e);
    }
    long res = 0;
    outer:
    for (int i = 1; i <= n; i++) {
      for (Edge j : g.get(i)) {
        if (j.count > k) {
          continue outer;
        }
      }
      res = dfs2(i, 0);
      break;
    }
    System.out.println(res);
  }

  private static long dfs2(int i, int p) {
    long res = 0;
    for (Edge j : g.get(i)) {
      if (j.to == p) {
        continue;
      }
      res += dfs2(j.to, i) + j.count;
    }
    return res;
  }
}

