using namespace std;
double dp[1000005][2];
int n, l[1000005];
char s[1000005];
void Calc(int k) {
  if (s[k] == '0')
    dp[k][0] = 1.0;
  else if (s[k] == '1')
    dp[k][1] = 1.0;
  else {
    dp[k][0] = 0.5;
    dp[k][1] = 0.5;
  }
}
void Change(int x, double L0, double R0, int O) {
  if (s[O] == '&')
    dp[x][1] = (1 - L0) * (1 - R0), dp[x][0] = 1 - dp[x][1];
  else if (s[O] == '|' || L0 != R0)
    dp[x][0] = L0 * R0, dp[x][1] = 1 - dp[x][0];
  else
    dp[x][0] = 0.5, dp[x][1] = 0.5;
}
int Dfs(int l) {
  int r = l + 1, L = -1, O = -1;
  while (s[r] != ')') {
    if ((s[r] == '?' || s[r] == '0' || s[r] == '1') && L == -1)
      Calc(r), L = r, O = r + 1;
    if (s[r] == '(') r = Dfs(r);
    r++;
    if (r - l >= 3 && s[r] != '(') {
      if (s[r] == '?' || s[r] == '1' || s[r] == '0') {
        Calc(r);
        if (L != -1) Change(r, dp[L][0], dp[r][0], O);
        L = r;
        O = r + 1;
        r++;
      } else {
        if (L != -1) Change(r - 1, dp[L][0], dp[r - 1][0], O);
        L = r - 1;
        O = r;
      }
      O = r;
    }
  }
  dp[r][0] = dp[r - 1][0];
  dp[r][1] = dp[r - 1][1];
  return r;
}
