#include <bits/stdc++.h>
using namespace std;
const int N = 1e6 + 6;
const int LAST = N - 1;
const int OO = 1 << 30;
char text[N];
struct Node {
  int sum;
  int maxv;
  int minv;
  Node() {
    sum = maxv = 0;
    minv = OO;
  }
  Node(int s, int mx, int mn) {
    sum = s;
    maxv = mx;
    minv = mn;
  }
  static Node merge(Node n1, Node n2) {
    int ns = n1.sum + n2.sum;
    int nmx = max(n1.maxv, n2.maxv);
    int nmn = min(n1.minv, n2.minv);
    return {ns, nmx, nmn};
  }
  void setNewMin(int val) {
    if (minv == OO)
      this->minv = val;
    else
      this->minv += val;
  }
};
Node tree[4 * N];
int lazy[4 * N];
void update(int node, int l, int r, int l2, int r2, int val) {
  int mid = (l + r) >> 1;
  int lnode = node << 1;
  int rnode = lnode + 1;
  if (lazy[node] != 0) {
    tree[node].sum += (r - l + 1) * lazy[node];
    tree[node].maxv += lazy[node];
    tree[node].setNewMin(lazy[node]);
    if (l != r) {
      lazy[lnode] += lazy[node];
      lazy[rnode] += lazy[node];
    }
    lazy[node] = 0;
  }
  if (r < l2 || l > r2) return;
  if (l >= l2 && r <= r2) {
    tree[node].sum += (r - l + 1) * val;
    tree[node].maxv += val;
    tree[node].setNewMin(val);
    if (l != r) {
      lazy[lnode] += val;
      lazy[rnode] += val;
    }
    return;
  }
  update(lnode, l, mid, l2, r2, val);
  update(rnode, mid + 1, r, l2, r2, val);
  tree[node] = Node::merge(tree[lnode], tree[rnode]);
}
Node query(int node, int l, int r, int l2, int r2) {
  int mid = (l + r) >> 1;
  int lnode = node << 1;
  int rnode = lnode + 1;
  if (r < l2 || l > r2) return {0, 0, OO};
  if (lazy[node] != 0) {
    tree[node].sum += (r - l + 1) * lazy[node];
    tree[node].maxv += lazy[node];
    tree[node].setNewMin(lazy[node]);
    if (l != r) {
      lazy[lnode] += lazy[node];
      lazy[rnode] += lazy[node];
    }
    lazy[node] = 0;
  }
  if (l >= l2 && r <= r2) return tree[node];
  Node n1 = query(lnode, l, mid, l2, r2);
  Node n2 = query(rnode, mid + 1, r, l2, r2);
  return Node::merge(n1, n2);
}
