    for (int j = 0; j < M; j++) {
      if (a[i] & (1 << j)) idx[j].push_back(i);
    }
  }
  for (int i = 0; i < M; i++) idx[i].push_back(n);
  int ans = 0;
  for (int i = 0; i < n; i++) {
