#include <bits/stdc++.h>
using namespace std;
using LL = long long;
LL bin(LL a, LL b, LL p) {
  LL res = 1;
  a = (a % p + p) % p;
  for (; b; b >>= 1, a = a * a % p)
    if (b & 1) res = res * a % p;
  return res;
}
const int N = 1e4 + 50, M = 1e3 + 50, NN = 1e6 + 50;
LL d[N][M];
int a[N], n, l;
int g, r;
void solve() {
  scanf("%d%d", &l, &n);
  for (int i = 1; i <= n; ++i) {
    scanf("%d", &a[i]);
  }
  scanf("%d%d", &g, &r);
  sort(a + 1, a + n + 1);
  if (a[1] > g) {
    puts("-1");
    return;
  }
  for (int i = 1; i <= n; ++i) {
    memset(d[i], 0x3f3f3f3f, sizeof d[i]);
  }
  d[1][a[1]] = a[1];
  queue<pair<LL, pair<int, int>>> pq;
  pq.emplace(a[1], pair<int, int>(1, a[1]));
  while (!pq.empty()) {
    auto now = pq.front();
    pq.pop();
    int np = now.second.first, ng = now.second.second;
    LL ndis = now.first;
    if (ndis > d[np][ng]) continue;
    if (np > 1) {
      int nng = ng + a[np] - a[np - 1], nw = a[np] - a[np - 1];
      if (nng == g) nng = 0, nw += r;
      if (nng <= g && d[np - 1][nng] > ndis + nw) {
        d[np - 1][nng] = ndis + nw;
        pq.emplace(ndis + nw, pair<int, int>(np - 1, nng));
      }
    }
    if (np + 1 <= n) {
      int nng = a[np + 1] - a[np] + ng, nw = a[np + 1] - a[np];
      if (nng == g) {
        nng = 0;
        if (np + 1 != n) nw += r;
      }
      if (nng <= g && d[np + 1][nng] > ndis + nw) {
        d[np + 1][nng] = ndis + nw;
        pq.emplace(ndis + nw, pair<int, int>(np + 1, nng));
      }
    }
  }
  LL ans = 1e18;
  for (int i = 0; i <= g - (l - a[n]); ++i) {
    ans = min(ans, d[n][i]);
  }
  if (ans < 1e17)
    printf("%lld\n", ans);
  else
    puts("-1");
}
int main() {
  solve();
  return 0;
}

