#include <bits/stdc++.h>
using namespace std;
inline int rev(int i, int N) { return N - i - 1; }
class zeroflags {
  std::bitset<65536 * 2 * 8> flag;
  int m;

 public:
  void init(int size) {
    m = 1;
    int bits = 1;
    while ((size >>= 1) != 0) {
      m++;
    }
    flag.set();
  }
  inline void update(int index, bool b) {
    int k = index;
    int j = m;
    bool pre = b;
    while (j >= 0) {
      if (flag[index] == pre) {
        break;
      }
      flag.set(index, pre);
      pre = flag[index] && flag[index ^ 1];
      index = (index - k) + (1 << j) + k / 2;
      j--;
      k /= 2;
    }
  }
  inline bool is_zero() {
    int i = (1 << (m + 1)) - 2;
    return flag[i];
  }
};
int main() {
  std::istream& c_in = cin;
  int N;
  c_in >> N;
  vector<int> sub;
  sub.resize(N / 2);
  for (int i = 0; i < N / 2; ++i) {
    c_in >> sub[i];
  }
  zeroflags zero;
  zero.init(sub.size());
  for (int i = N / 2; i < N; ++i) {
    int dat;
    c_in >> dat;
    sub[rev(i, N)] -= dat;
    zero.update(rev(i, N), sub[rev(i, N)] == 0);
  }
  int base = 0;
  int Q;
  c_in >> Q;
  for (int q = 0; q < Q; ++q) {
    int L, r, x;
    c_in >> L >> r >> x;
    if (x != 0) {
      L--;
      r--;
      int s, t;
      if (r < N / 2) {
        s = L;
        t = r;
      } else if (L >= N / 2) {
        s = rev(r, N);
        t = rev(L, N);
        x = -x;
      } else {
        r = rev(r, N);
        if (L < r) {
          s = L;
          t = r - 1;
        } else {
          s = r;
          t = L - 1;
          x = -x;
        }
      }
      if (s <= t) {
        for (int i = s; i <= t; ++i) {
          int v = (sub[i] += x);
          zero.update(i, v == 0);
        }
      }
    }
    cout << (zero.is_zero() ? '1' : '0') << endl;
  }
}

