map<int, int> tpoint;
int revt[200020];
int a[100020], b[100020], c[100020], d[100020];
bool event[200020];
int change[200020];
long long spd[200020], dif[520];
long long blow[520], bsend[520];
int bcount[520];
void solve() {
  int q;
  cin >> q;
  for (int i = 0; i < q; ++i) {
    cin >> a[i] >> b[i];
    if (a[i] == 1) {
      cin >> c[i];
      tpoint[b[i]] = 0;
    } else if (a[i] == 2) {
      tpoint[b[i]] = 0;
    } else {
      cin >> c[i] >> d[i];
      tpoint[b[i]] = 0;
      tpoint[c[i]] = 0;
    }
  }
  int id = 0;
  for (auto it = tpoint.begin(); it != tpoint.end(); it++) {
    revt[id] = (*it).first;
    (*it).second = id++;
  }
  int blast = (id - 1) / 450;
  for (int i = 0; i < q; ++i) {
    int post = tpoint[b[i]];
    int bi = post / 450;
    if (a[i] <= 2) {
      if (a[i] == 1) {
        event[post] = 1;
        change[post] = c[i];
        bcount[bi]++;
      } else {
        event[post] = 0;
        change[post] = 0;
        bcount[bi]--;
      }
      int speed = 0;
      if (bi > 0) speed = bsend[bi - 1];
      long long sum = 0;
      blow[bi] = 1e18;
      for (int j = bi * 450; j < min(id - 1, (bi + 1) * 450); ++j) {
        if (event[j]) speed = change[j];
        spd[j] = speed;
        sum += speed * (revt[j + 1] - revt[j]);
        blow[bi] = min(sum, blow[bi]);
      }
      bsend[bi] = speed;
      dif[bi] = sum;
      int jj = bi + 1;
      for (int j = bi + 1; j < blast + 1; ++j) {
        if (bcount[j] != 0) break;
        dif[j] = (revt[min((j + 1) * 450, id - 1)] - revt[j * 450]) * speed;
        blow[j] = min(0ll, dif[j]);
        bsend[j] = speed;
        jj = j + 1;
      }
      sum = 0;
      blow[jj] = 1e18;
      for (int j = jj * 450; j < min(id - 1, (jj + 1) * 450); ++j) {
        if (event[j]) speed = change[j];
        spd[j] = speed;
        sum += speed * (revt[j + 1] - revt[j]);
        blow[jj] = min(sum, blow[jj]);
      }
      bsend[jj] = speed;
      dif[jj] = sum;
    } else {
      int post2 = tpoint[c[i]];
      int bj = post2 / 450;
      bool stop = 0;
      long long v = d[i];
      if (v == 0) {
        cout << revt[post] << "\n";
        continue;
      }
      if (bi == bj) {
        long long speed = 0;
        for (int j = post; j < post2; ++j) {
          if (bcount[bi] == 0)
            speed = bsend[bi];
          else
            speed = spd[j];
          if (v + (revt[j + 1] - revt[j]) * speed <= 0) {
            cout << fixed << setprecision(12)
                 << revt[j] - ((long double)v / speed) << "\n";
            stop = 1;
            break;
          }
          v += (revt[j + 1] - revt[j]) * speed;
        }
        if (stop) continue;
      } else {
        bool stop = 0;
        long long speed = 0;
        for (int j = post; j < (bi + 1) * 450; ++j) {
          if (bcount[bi] == 0)
            speed = bsend[bi];
          else
