            stop = 1;
            break;
          }
          v += (revt[j + 1] - revt[j]) * speed;
        }
        if (stop) continue;
        for (int j = bi + 1; j < bj; ++j) {
          if (v + blow[j] <= 0) {
            long long speed = 0;
            for (int jj = j * 450; jj < (j + 1) * 450; ++jj) {
              if (bcount[j] == 0)
                speed = bsend[j];
              else
                speed = spd[jj];
              if (v + (revt[jj + 1] - revt[jj]) * speed <= 0) {
                cout << fixed << setprecision(12)
                     << revt[jj] - ((long double)v / speed) << "\n";
                stop = 1;
                break;
              }
              v += (revt[jj + 1] - revt[jj]) * speed;
            }
            if (stop) break;
          }
          v += dif[j];
        }
        if (stop) continue;
        speed = 0;
        for (int j = bj * 450; j < post2; ++j) {
          if (bcount[bj] == 0)
            speed = bsend[bj];
          else
            speed = spd[j];
          if (v + (revt[j + 1] - revt[j]) * speed <= 0) {
