long long func(long long idx, long long ut, long long dt) {
  if (idx == n) return 1;
  if (!(ut | dt)) return 1;
  long long x = a[idx] - 'a', y = b[idx] - 'a', z = s[idx] - 'a';
  if (ar[z] != -1) {
    if ((ut && ar[z] > y) || (dt && ar[z] < x)) return 0;
    fr[ar[z]]++;
    if (func(idx + 1, ut && (ar[z] == y), dt && (ar[z] == x))) return 1;
    fr[ar[z]]--;
  } else {
    for (int i = x; i < y + 1; i++) {
      if (fr[i] == 0) {
        if ((ut && i > y) || (dt && i < x)) continue;
        ar[z] = i;
        fr[ar[z]]++;
        if (func(idx + 1, ut && (i == y), dt && (i == x))) return 1;
        fr[ar[z]]--;
      }
    }
  }
  return 0;
}
