double x[100005], y[100005], L[100005], R[100005], D[100005];
const double pi = 3.1415926535897932384626433832, eps = 1e-9;
struct qaq {
  pair<double, double> a;
  int id;
} b[200005], s[200005];
double angle(double x, double y) {
  if (x == 0 && y > 0) return pi / 2;
  if (x == 0 && y < 0) return 3 * pi / 2;
  if (x > 0 && y == 0) return 0;
  if (x < 0 && y == 0) return pi;
  if (x > 0 && y > 0) return atan(y / x);
  if (x < 0 && y > 0) return pi + atan(y / x);
  if (x < 0 && y < 0) return pi + atan(y / x);
  if (x > 0 && y < 0) return pi * 2 + atan(y / x);
}
inline double dis(double x, double y, double X, double Y) {
  return sqrt((X - x) * (X - x) + (Y - y) * (Y - y));
}
inline bool cmp(qaq x, qaq y) { return x.a < y.a; }
inline bool check(double r) {
  int cnt = 0;
  for (int i = 1; i <= n; i++) del[i] = 0;
  for (int i = 1; i <= n; i++) {
    double qwq = angle(x[i], y[i]), cs = acos(r / D[i]);
    L[i] = qwq - cs, R[i] = qwq + cs;
    if (L[i] > R[i]) swap(L[i], R[i]);
    b[++cnt] = {{L[i], R[i]}, i};
    if (L[i] < eps) b[++cnt] = {{L[i] + 2 * pi, R[i] + 2 * pi}, i};
    if (R[i] >= 2 * pi - eps) b[++cnt] = {{L[i] - 2 * pi, R[i] - 2 * pi}, i};
  }
  for (int i = 1; i <= cnt; i++) b[i].a.second *= -1;
  sort(b + 1, b + cnt + 1, cmp);
  for (int i = 1; i <= cnt; i++) b[i].a.second *= -1;
  int cnts = 0;
  for (int i = 1; i <= cnt; i++) {
    while (cnts && s[cnts].a.second > b[i].a.second)
      del[s[cnts].id] = 1, --cnts;
    s[++cnts] = b[i];
  }
  cnt = 0;
  pair<double, double> a[300005];
  for (int i = 1; i <= n; i++) {
    if (!del[i])
      a[++cnt] = {L[i], R[i]}, a[++cnt] = {L[i] + 2 * pi, R[i] + 2 * pi},
      a[++cnt] = {L[i] + 4 * pi, R[i] + 4 * pi};
  }
  sort(a + 1, a + cnt + 1);
  int now = 1;
  a[cnt + 1] = {1e9, 1e9};
  for (int i = 1; i <= cnt; i++) {
    while (a[now + 1].first <= a[i].second) ++now;
    nxt[i] = now + 1;
  }
  for (int i = 1; i <= cnt + 1; i++) N[i] = i;
  nxt[cnt + 1] = cnt + 1;
  int k = m;
  while (k) {
    if (k & 1)
      for (int i = 1; i <= cnt; i++) N[i] = nxt[N[i]];
    for (int i = 1; i <= cnt; i++) nxt[i] = nxt[nxt[i]];
    k >>= 1;
  }
  for (int i = 1; i <= cnt; i++)
    if (N[i] - i >= cnt / 3) return 1;
  return 0;
}
signed main(int argc, char** argv) {
  cin >> n >> m;
  double mn = 1e9;
  for (int i = 1; i <= n; i++) {
    cin >> x[i] >> y[i];
    mn = min(mn, D[i] = dis(x[i], y[i], 0, 0));
  }
  double l = 0, r = mn, ans = 0;
  while (r - l > 1e-7) {
    double mid = (l + r) / 2;
    if (check(mid))
      ans = mid, l = mid;
    else
      r = mid;
  }
  printf("%.10lf", ans);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int Maxn = 1e5 + 500;
struct Dancer {
  int pos, delta;
  int index;
  inline int getMark() { return Maxn + pos - delta; }
} ver[Maxn + 50], hor[Maxn + 50];
int sVer, sHor, n, w, h;
pair<int, int> ans[Maxn + 50];
int idx[Maxn + 50];
deque<int> que[Maxn * 2 + 50];
inline bool cmpVer(Dancer a, Dancer b) { return a.pos < b.pos; }
inline bool cmpHor(Dancer a, Dancer b) {
  if (a.delta != b.delta) return a.delta < b.delta;
  return a.pos < b.pos;
}
int main() {
  sVer = sHor = 0;
  scanf("%d%d%d", &n, &w, &h);
  for (int i = 1; i <= n; i++) {
    int t, p, d;
    scanf("%d%d%d", &t, &p, &d);
    if (t == 1) {
      sVer++;
      ver[sVer].index = i;
      ver[sVer].pos = p;
      ver[sVer].delta = d;
      ans[i] = make_pair(p, h);
    } else {
      sHor++;
      hor[sHor].index = i;
      hor[sHor].pos = p;
      hor[sHor].delta = d;
      ans[i] = make_pair(w, p);
    }
  }
  sort(ver + 1, ver + sVer + 1, cmpVer);
  sort(hor + 1, hor + sHor + 1, cmpHor);
  for (int i = 1; i <= sVer; i++) que[ver[i].getMark()].push_back(ver[i].index);
  for (int i = 1; i <= sHor; i++) {
    int tag = hor[i].getMark();
    que[tag].push_back(hor[i].index);
    idx[hor[i].index] = que[tag].front();
    que[tag].pop_front();
  }
  for (int i = 1; i <= sVer; i++) {
    int tag = ver[i].getMark();
    idx[ver[i].index] = que[tag].front();
    que[tag].pop_front();
  }
  for (int i = 1; i <= n; i++)
    printf("%d %d\n", ans[idx[i]].first, ans[idx[i]].second);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n;
long long a[200005], b[200005];
string S;
bool done() {
  bool same = 1;
  for (int i = (1); i <= (n); i++) {
    same &= (a[i] == b[i]);
    if (!same) break;
  }
  if (same) return true;
  same = 1;
  for (int i = (1); i <= (n); i++) {
    same &= (a[i] == b[n - i + 1]);
    if (!same) break;
  }
  if (same) {
    S += "R";
    return true;
  }
  return false;
}
bool valid() {
  if (b[1] > b[2]) {
    reverse(b + 1, b + n + 1);
    S += "R";
  }
  for (int i = (2); i <= (n); i++) {
    if (b[i - 1] >= b[i] || b[i] <= 0) return false;
  }
  return true;
}
int main() {
  scanf("%d", &n);
  for (int i = (1); i <= (n); i++) {
    scanf("%lld", &a[i]);
  }
  for (int i = (1); i <= (n); i++) {
    scanf("%lld", &b[i]);
  }
  if (n >= 3) {
    int cntp = 0;
    while (true) {
      if (done()) {
        if (cntp <= 200000) {
          reverse(S.begin(), S.end());
          printf("SMALL\n%d\n%s\n", (int)S.length(), S.c_str());
        } else {
          printf("BIG\n%d\n", cntp);
        }
        return 0;
      }
      if (!valid()) {
        printf("IMPOSSIBLE\n");
        return 0;
      }
      for (int i = (n); i >= (2); i--) {
        b[i] -= b[i - 1];
      }
      S += "P";
      cntp++;
    }
  } else if (n == 2) {
    long long cntp = 0;
    bool flip = 0;
    if (a[1] > a[2]) {
      swap(a[1], a[2]);
      flip = 1;
    }
    while (true) {
      if (a[1] == b[1] && b[2] >= a[2] && (b[2] - a[2]) % a[1] == 0) {
        long long tp = (b[2] - a[2]) / a[1];
        cntp += tp;
        if (cntp <= 200000) {
          for (int i = (1); i <= (tp); i++) S += "P";
          if (flip) S += "R";
          reverse(S.begin(), S.end());
          printf("SMALL\n%d\n%s\n", (int)S.length(), S.c_str());
        } else {
          printf("BIG\n%lld\n", cntp);
        }
        return 0;
      } else if (a[1] >= b[1]) {
        printf("IMPOSSIBLE\n");
        return 0;
      } else {
        long long d = b[2] / b[1];
        cntp += d;
        if (cntp <= 200000) {
          for (int i = (1); i <= (d); i++) S += "P";
        }
        S += "R";
        b[2] %= b[1];
        swap(b[1], b[2]);
      }
    }
  } else {
    if (a[1] == b[1])
      printf("SMALL\n0\n\n");
    else
      printf("IMPOSSIBLE\n");
  }
  return 0;
}

