#include <bits/stdc++.h>
using namespace std;
struct reqest {
  int a, b, ind;
};
bool comp(reqest a, reqest b) {
  if (a.b == b.b) return a.a < b.a;
  return a.b < b.b;
}
int main() {
  int n;
  cin >> n;
  vector<int> w(n);
  for (int i = 0; i < n; ++i) cin >> w[i];
  int m;
  cin >> m;
  vector<reqest> req(m);
  for (int i = 0; i < m; ++i) {
    cin >> req[i].a >> req[i].b;
    --req[i].a;
    req[i].ind = i;
  }
  sort(req.begin(), req.end(), comp);
  int c = sqrt(n);
  vector<int> ans(m);
  vector<int> dp(n);
  for (int i = 0; i < req.size(); ++i) {
    if (req[i].b > c) {
      int sum = 0;
      for (int j = req[i].a; j < n; j += req[i].b) {
        sum += w[j];
      }
      ans[req[i].ind] = sum;
    } else {
      int res = 0;
      if (i != 0 && req[i - 1].b == req[i].b) {
        res = dp[req[i].a];
      } else {
        res = dp[req[i].a];
        dp.assign(n, 0);
        for (int j = n - 1; j >= 0; --j) {
          dp[j] = w[j];
          if (j + req[i].b < n) {
            dp[j] += dp[j + req[i].b];
          }
        }
        res = dp[req[i].a];
      }
      ans[req[i].ind] = res;
    }
  }
  for (int i = 0; i < ans.size(); ++i) cout << ans[i] << endl;
  puts("");
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e3 + 2;
const int inf = 1e9 + 7;
const int mod = 998244353;
int ar[N], dp[N][N], sum[N][N];
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  int n, i, j, k, l, num, max1 = 0, ans = 0;
  cin >> n >> num;
  for (i = 1; i <= n; i++) {
    cin >> ar[i];
    max1 = max(max1, ar[i]);
  }
  ar[0] = -inf;
  for (i = 0; i <= n; i++) {
    sum[0][i] = 1;
  }
  sort(ar + 1, ar + 1 + n);
  for (i = 1; i <= max1 / (num - 1) + 1; i++) {
    for (j = 1; j <= num; j++) {
      l = 0;
      for (k = 1; k <= n; k++) {
        while (l <= n && ar[l] + i <= ar[k]) {
          l++;
        }
        dp[j][k] = sum[j - 1][l - 1];
        sum[j][k] = sum[j][k - 1] + dp[j][k];
        if (sum[j][k] >= mod) {
          sum[j][k] -= mod;
        }
      }
    }
    ans += sum[num][n];
    if (ans >= mod) {
      ans -= mod;
    }
  }
  cout << ans;
}

#include <bits/stdc++.h>
using namespace std;
int n, w, h, tx[100005], ty[100005], ansx[100005], ansy[100005];
struct xx {
  int x, t, id;
  friend bool operator<(xx a, xx b) {
    if (a.x - a.t != b.x - b.t) return a.x - a.t < b.x - b.t;
    return a.x < b.x;
  }
} a[100005], b[100005];
int main() {
  ios::sync_with_stdio(0);
  cin >> n >> w >> h;
  int cnt1 = 0, cnt2 = 0;
  for (int i = 1; i <= n; i++) {
    int x, y, t;
    cin >> x >> y >> t;
    if (x == 1) {
      a[++cnt1].x = y;
      a[cnt1].t = t;
      a[cnt1].id = i;
      tx[i] = y;
      ty[i] = h;
    } else {
      b[++cnt2].x = y;
      b[cnt2].t = t;
      b[cnt2].id = i;
      tx[i] = w;
      ty[i] = y;
    }
  }
  sort(a + 1, a + 1 + cnt1);
  sort(b + 1, b + 1 + cnt2);
  int now1 = 1, now2 = 1;
  while (now1 <= cnt1 && now2 <= cnt2) {
    if (a[now1].x - a[now1].t == b[now2].x - b[now2].t) {
      int t1 = now1 + 1, t2 = now2 + 1;
      while (t1 <= cnt1 && a[now1].x - a[now1].t == a[t1].x - a[t1].t) t1++;
      while (t2 <= cnt2 && b[now2].x - b[now2].t == b[t2].x - b[t2].t) t2++;
      vector<int> v1, v2;
      for (int i = now1; i < t1; i++) v1.push_back(a[i].id);
      for (int i = t2 - 1; i >= now2; i--) v1.push_back(b[i].id);
      for (int i = t2 - 1; i >= now2; i--) v2.push_back(b[i].id);
      for (int i = now1; i < t1; i++) v2.push_back(a[i].id);
      for (int i = 0; i < v1.size(); i++) {
        ansx[v2[i]] = tx[v1[i]];
        ansy[v2[i]] = ty[v1[i]];
      }
      now1 = t1;
      now2 = t2;
    } else if (a[now1].x - a[now1].t < b[now2].x - b[now2].t) {
      ansx[a[now1].id] = tx[a[now1].id];
      ansy[a[now1].id] = ty[a[now1].id];
      now1++;
    } else {
      ansx[b[now2].id] = tx[b[now2].id];
      ansy[b[now2].id] = ty[b[now2].id];
      now2++;
    }
  }
  while (now1 <= cnt1) {
    ansx[a[now1].id] = tx[a[now1].id];
    ansy[a[now1].id] = ty[a[now1].id];
    now1++;
  }
  while (now2 <= cnt2) {
    ansx[b[now2].id] = tx[b[now2].id];
    ansy[b[now2].id] = ty[b[now2].id];
    now2++;
  }
  for (int i = 1; i <= n; i++) cout << ansx[i] << " " << ansy[i] << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int M = 2e5 + 10;
const int B = 1e9 + 7;
unsigned long long b[M];
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n, m;
  cin >> n >> m;
  vector<int> a(n, 0), d(n, 0);
  for (int i = 0; i < n; i++) cin >> a[i];
  sort(begin(a), end(a));
  for (int i = 0; i < n - 1; i++) d[i] = a[i + 1] - a[i];
  d[n - 1] = (m + a[0] - a[n - 1]) % m;
  b[0] = 1;
  for (int i = 1; i <= n; i++) b[i] = b[i - 1] * B;
  unsigned long long oh = 0;
  for (int i = 0; i < n; i++) {
    oh = oh * B + d[i];
  }
  unsigned long long th = 0;
  for (int i = n - 1; i >= 0; i--) {
    th = th * B + d[i];
  }
  set<int> res;
  unsigned long long lb = 1, rb = b[n];
  for (int i = 0; i < n; i++) {
    if (th == oh * lb) res.insert(2 * a[i] % m);
    th -= lb * d[i];
    oh -= b[n - 1] * d[i];
    if (th == oh * lb * B) res.insert((2 * a[i] + d[i]) % m);
    th += rb * d[i];
    oh = oh * B + d[i];
    lb *= B, rb *= B;
  }
  cout << res.size() << "\n";
  for (auto &x : res) cout << x << " ";
  cout << endl;
  return 0;
}

