ll array_size[256];
map<ll, ll > array[256];

class Parser
{
public:
	string exp;
	ll program (void );
	ll assignment (string );
};

ll stoll (string s )
{
	stringstream ss (s );
	ll res;
	ss >> res;

	return res;
}

ll Parser::program (void )
{
	ll res = SUCCESS;
	if (exp.find ('=') == string::npos ){
		array_size[(int)exp[0]] = stoll (exp.substr (2, exp.length() - 3 ) );
	}else{
		int i = (int)exp.find ('=');
		string left = exp.substr (2, i-3 );
		string right = exp.substr (i+1 );
		ll l = assignment (left );
		ll r = assignment (right );
#if DEBUG
		printf ("%c[%d]=%d\n", exp[0], l, r );
#endif
		if (l != FAIL && r != FAIL && array_size[(int)exp[0]] > l ){
			array[(int)exp[0]].insert (make_pair (l, r ) );
		}else{
			res = FAIL;
		} // end if
	} // end rep

	return res;
}

// ツ配ツ療アツづ鳴づ個妥」ツ禿シ
ll Parser::assignment (string str )
{
	if (isdigit (str[0] ) ){
		ll value = stoll (str );
		return value;
	}else{
		ll val = assignment (str.substr (2, str.length()-3 ) );
		if (array[(int)str[0]].find (val ) == array[(int)str[0]].end() ){
			return FAIL;
		}else{
			return array[(int)str[0]][val];
		} // end if
	} // end if

	return FAIL;	
}

int run (vector <string> row )
{
	Parser parser;
	int n = row.size();
	int res = 0;
	rep (i, n ){
		parser.exp = row[i];
		res = parser.program ();
		if (res == FAIL ){
			return i+1;
		} // end if
	} // end rep

	return 0;
}

void init_val (void )
{
	rep (i, 256 )
		array[i].clear();
	memset (array_size, 0, sizeof (array_size ) );
}

