import java.util.Stack;
import java.util.TreeSet;

public class Main {

	static int MAXN = (1000 * 1000) + 1;

	static char[] data = null;
	static char[] commands = null;
	static int n;

	static Stack<Integer> lS = new Stack<Integer>();
	static Stack<Integer> rS = new Stack<Integer>();
	static int lOpened = 0, rClosed = 0;

	static TreeSet<Pair> maxLeft = new TreeSet<Pair>();
	static TreeSet<Pair> maxRigth = new TreeSet<Pair>();
	static int pos = 0;

	static int[] deep;

	static int[] ans;

	public static void main(String[] args) throws Exception {

		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		//BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream("input")));
		n = Integer.parseInt(reader.readLine().trim());
		commands = reader.readLine().trim().toCharArray();
		reader.close();
		data = new char[n];
		deep = new int[n];
		ans = new int[n];

		StringBuilder answer = new StringBuilder();
		for(int i = 0; i < n ;i++) {

			if(commands[i] == '(') {
				if(data[pos] == ')') {
					maxLeft.remove(new Pair(deep[pos], pos));
					lOpened++;
				}
				else if(data[pos] != '(') {
					lOpened++;
					lS.push(pos);
				}
				data[pos] = commands[i];
			} else if(commands[i] == ')') {
				if(data[pos] == '(') {
					lOpened--;
					deep[pos] = (lOpened > 0 ? lOpened-- : MAXN);
					maxLeft.add(new Pair(deep[pos], pos));
				} else if(data[pos] != ')') {
					deep[pos] = (lOpened > 0 ? lOpened-- : MAXN);
					maxLeft.add(new Pair(deep[pos], pos));
					lS.push(pos);
				}
				data[pos] = commands[i];
			} else if(commands[i] == 'L' && pos > 0) {
				if(data[pos] == '(') {
					lOpened--;
					deep[pos] = (rClosed > 0 ? rClosed-- : MAXN);
					maxRigth.add(new Pair(deep[pos], pos));
					rS.push(pos);
					lS.pop();
				} else if(data[pos] == ')') {
					rClosed++;
					if(maxLeft.first().first != MAXN) lOpened++;
					maxLeft.remove(new Pair(deep[pos], pos));
					rS.push(pos);
					lS.pop();
				}
				pos--;
			} else if(commands[i] == 'R') {
				pos++;
				if(data[pos] == '(') { // ( ( )
					lOpened++;
					if(maxRigth.first().first != MAXN) rClosed++;
					maxRigth.remove(new Pair(deep[pos], pos));
					lS.push(pos);
					rS.pop();
				} else if(data[pos] == ')') {
					rClosed--;
					deep[pos] = (lOpened > 0 ? lOpened-- : MAXN);
					maxLeft.add(new Pair(deep[pos], pos));
					lS.push(pos);
					rS.pop();
				}
			} else {
				if(data[pos] == '(') {
					lOpened--;
					lS.pop();
				} else if(data[pos] == ')') {
					if(maxLeft.first().first != MAXN) lOpened++;
					maxLeft.remove(new Pair(deep[pos], pos));
					lS.pop();
				}
				data[pos] = commands[i];
			}
			if(rClosed == lOpened) {
				int rMax = (maxRigth.isEmpty() ? rClosed : maxRigth.first().first);
				int lMax = (maxLeft.isEmpty() ? lOpened : maxLeft.first().first);
				int tempAns = Math.max(rMax, lMax);
				answer.append((tempAns == MAXN ? -1 : tempAns) + " ");
			} else answer.append(-1 + " ");//ans[i] = -1;
		}		
		System.out.println(answer);
	}

	static class Pair implements Comparable<Pair> {
		Integer first, second;
		public Pair(Integer first, Integer second) {
			super();
			this.first = first;
			this.second = second;
		}
		@Override
		public int compareTo(Pair o) {
			if(first.compareTo(o.first) == 0) return second.compareTo(o.second);
			else return first.compareTo(o.first) * -1;			
		}		
	}

}

