using namespace std;
using LLONG = long long;
const LLONG MOD = 1000000007;
void Comb(vector<vector<LLONG>> &v) {
  for (int n = 0; n < v.size(); ++n) {
    v[n][0] = 1;
    v[n][n] = 1;
  }
  for (int n = 1; n < v.size(); ++n) {
    for (int r = 1; r < n; ++r) {
      v[n][r] = v[n - 1][r - 1] + v[n - 1][r];
    }
  }
}
int main() {
  int n;
  cin >> n;
  vector<LLONG> as(n);
  for (int i = 0; i < n; ++i) cin >> as[i];
  sort(as.begin(), as.end());
  const LLONG N = as.back();
  int pos = std::distance(as.begin(), lower_bound(as.begin(), as.end(), N / 2));
  vector<vector<LLONG>> v(N + 1, vector<LLONG>(N + 1));
  Comb(v);
  LLONG maxComb = 0;
  int maxR = -1;
  for (const LLONG r : as) {
    if (v[N][r] > maxComb) {
      maxComb = v[N][r];
      maxR = r;
    }
  }
  cout << N << ' ' << maxR << endl;
}

