int f[111111];
void mtree(int x) {
  for (int i = 0; i < g[x].size(); i++) {
    int to = g[x][i];
    if (f[to] == -1) {
      f[to] = x;
      mtree(to);
    }
  }
}
long long dfs(int x) {
  if (g[x].size() == 1) return val[x];
  long long p = 0, n = 0;
  for (int i = 0; i < g[x].size(); i++) {
    if (g[x][i] == f[x]) continue;
    long long haha = dfs(g[x][i]);
    if (haha < 0)
      n = min(n, haha);
    else
      p = max(p, haha);
  }
  return p + n + val[x];
}
