/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 29);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            CCentroids solver = new CCentroids();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class CCentroids {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            Node[] nodes = new Node[n];
            for (int i = 0; i < n; i++) {
                nodes[i] = new Node();
            }
            for (int i = 0; i < n - 1; i++) {
                Node a = nodes[in.readInt() - 1];
                Node b = nodes[in.readInt() - 1];
                a.adj.add(b);
                b.adj.add(a);
            }

            dfsForSize(nodes[0], null, n);
            dfs(nodes[0], null, n, 0);
            for (Node node : nodes) {
                out.append(node.possible ? 1 : 0).append(' ');
            }
        }

        public void dfs(Node root, Node p, int n, int noMoreThan) {
            Node maxChild = p;
            int childSize = n - root.size;
            int m = root.adj.size();
            int[] pre = new int[m];
            int[] post = new int[m];

            for (Node node : root.adj) {
                if (node == p) {
                    continue;
                }
                if (childSize < node.size) {
                    childSize = node.size;
                    maxChild = node;
                }
            }

            int childNoMoreThan = maxChild == p ? noMoreThan : maxChild.noMoreThan;
            if ((childSize - childNoMoreThan) * 2 <= n) {
                root.possible = true;
            }


            for (int i = 0; i < m; i++) {
                Node node = root.adj.get(i);
                if (node == p) {
                    pre[i] = post[i] = noMoreThan;
                } else {
                    pre[i] = post[i] = node.noMoreThan;
                }
            }
            for (int i = 1; i < m; i++) {
                pre[i] = Math.max(pre[i], pre[i - 1]);
                post[m - 1 - i] = Math.max(post[m - 1 - i], post[m - i]);
            }

            for (int i = 0; i < m; i++) {
                Node node = root.adj.get(i);
                if (node == p) {
                    continue;
                }
                int top = 0;
                if (i > 0) {
                    top = Math.max(top, pre[i - 1]);
                }
                if (i + 1 < m) {
                    top = Math.max(top, post[i + 1]);
                }
                if ((n - node.size) * 2 <= n) {
                    top = Math.max(top, n - node.size);
                }
                dfs(node, root, n, top);
            }
        }

        public void dfsForSize(Node root, Node p, int n) {
            root.size = 1;
            for (Node node : root.adj) {
                if (node == p) {
                    continue;
                }
                dfsForSize(node, root, n);
                root.size += node.size;
                root.noMoreThan = Math.max(root.noMoreThan, node.noMoreThan);
            }
            if (root.size * 2 <= n) {
                root.noMoreThan = Math.max(root.noMoreThan, root.size);
            }
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(int c) {
            cache.append(c);
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

