    for (int j = 1; j <= i; j++) A += s[j - 1];
    if (check(A)) return 1;
  }
  return 0;
}
int prog(int siz) {
  if (siz == 1) return -1;
  if (siz == 2) {
    if (s[0] == s[1]) return -1;
    return 1;
  }
  if (try1(siz)) return 1;
  if (siz & 1) {
    if (try2(siz))
      return 2;
    else {
      int aux = prog(siz / 2);
      if (aux == -1) return aux;
      return aux * 2 + 2;
    }
  }
  if (!pal[siz / 2])
    return 1;
  else {
    if (try2(siz)) return 2;
    int aux = prog(siz / 2);
    if (aux == -1) return aux;
    return aux * 2 + 1;
  }
}
