int out[550000];
int tree[550000 * 8];
int pos[550000];
int lazy[550000 * 8];
int num = 0;
vector<int> lin[550000];
bool flag = false;
void dfs(int x, int pre) {
  in[x] = ++num;
  for (int i = 0; i < lin[x].size(); i++) {
    int v = lin[x][i];
    if (v != pre) {
      pos[v] = x;
      dfs(v, x);
    }
  }
  out[x] = num;
}
void push_down(int id, int l, int mid, int r) {
  if (lazy[id] == 0) return;
  tree[(id * 2)] = tree[(id * 2 + 1)] = lazy[(id * 2)] = lazy[(id * 2 + 1)] = 1;
  lazy[id] = 0;
}
void push_up(int id) {
  if (tree[(id * 2)] + tree[(id * 2 + 1)] == 2)
    tree[id] = 1;
  else
    tree[id] = 0;
}
void add(int id, int l, int r, int L, int R, int V) {
  if (l == 0) return;
  if (l > R || r < L) return;
  if (l >= L && r <= R) {
    if (tree[id] == 0) flag = 1;
    tree[id] = V;
    if (V == 1) lazy[id] = V;
    return;
  }
  int mid = (l + r) / 2;
  push_down(id, l, mid, r);
  add((id * 2), l, mid, L, R, V);
  add((id * 2 + 1), mid + 1, r, L, R, V);
  push_up(id);
}
void query(int id, int l, int r, int L, int R) {
  if (l > R || r < L) return;
  if (l >= L && r <= R) {
    if (tree[id] == 0) flag = 1;
    return;
  }
  int mid = (l + r) >> 1;
  push_down(id, l, mid, l);
  query((id * 2), l, mid, L, R);
  query((id * 2 + 1), mid + 1, r, L, R);
}
