    cin >> Wn;
    vector<int> w_max(N + 1);
    {
      vector<vector<int>> dp(N + 1, vector<int>(W + 1));
      for (int i = 0; i < (int)(N); i++) dp[i][0] = 1;
      for (int n = 0; n < (int)(N); n++) {
        for (int w = 0; w < (int)(W + 1); w++) {
          int ww = w + Wn[n];
          set_max(dp[n + 1][w], dp[n][w]);
          if (ww <= W) set_max(dp[n + 1][ww], dp[n][w]);
        }
      }
      for (int n = 0; n < (int)(N + 1); n++)
        for (int w = 0; w < (int)(W + 1); w++)
          if (dp[n][w]) set_max(w_max[n], w);
