bool isRange(int r, int c) {
	return (0 <= r && r < 2 && 0 <= c && c < 2);
}

bool isLegal(int id, int tr, int tc) {
	int i, j, k;
	for (i = 0; i < 2; i++) {
		for (j = 0; j < 2; j++) {
			for (k = 0; k < 2; k++) {
				if (c[id][i][j][k] != '#') continue;
				if (!isRange(j + tr, k + tc)) return false;
			}
		}
	}
	return true;
}

bool isAll(int z) {
	int i, j;
	for (i = 0; i < 2; i++) {
		for (j = 0; j < 2; j++) {
			if (b[z][i][j] != '#') return false;
		}
	}
	return true;
}

int getDropHeight(int id, int tr, int tc) {
	int i, j, k, l;
	int ret = -114514;

	for (i = 0; i < 2; i++) {
		for (j = 0; j < 2; j++) {
			for (k = 0; k < 2; k++) {
				if (c[id][i][j][k] != '#') continue;

				int row = j + tr;
				int col = k + tc;

				for (l = 19; l >= 0; l--) {
					if (b[l][row][col] == '#') break;
				}
				l++;
				ret = max(ret, l - i);
			}
		}
	}
	return ret;
}

int drop(int id, int tr, int tc) {
	int i, j, k, l;

	i = getDropHeight(id, tr, tc);
	for (j = 0; j < 2; j++) {
		for (k = 0; k < 2; k++) {
			for (l = 0; l < 2; l++) {
				if (c[id][j][k][l] != '#') continue;
				b[i + j][k + tr][l + tc] = '#';
			}
		}
	}

	int eraseNum = 0;

	for (i = 19; i >= 0; i--) {
		if (!isAll(i)) continue;

		eraseNum++;
		for (j = i + 1; j < 20; j++) {
			for (k = 0; k < 2; k++) {
				for (l = 0; l < 2; l++) {
					b[j-1][k][l] = b[j][k][l];
				}
			}
			for (k = 0; k < 2; k++) {
				for (l = 0; l < 2; l++) {
					b[j][k][l] = '.';
				}
			}
		}
	}
	return eraseNum;
}

int dfs(int id) {
	int tr, tc;
	int i, j, k;
	char backup[20][2][2];

	if (id == n) { return 0; }

	int ret = -114514;
	for (tr = -1; tr <= 1; tr++) {
		for (tc = -1; tc <= 1; tc++) {
			if (!isLegal(id, tr, tc)) continue;
			for (i = 0; i < 20; i++) for (j = 0; j < 2; j++) for (k = 0; k < 2; k++) backup[i][j][k] = b[i][j][k];
			ret = max(ret, drop(id, tr, tc) + dfs(id + 1));
			for (i = 0; i < 20; i++) for (j = 0; j < 2; j++) for (k = 0; k < 2; k++) b[i][j][k] = backup[i][j][k];
		}
	}
	return ret;
}

