vector<vector<int>> time_play;
vector<pair<pair<int, int>, pair<int, int>>> ans;
int get_max_time() {
  int MAX = 0;
  for (int i = 1; i <= n; i++) MAX = max(MAX, time_A[i]);
  for (int i = 1; i <= m; i++) MAX = max(MAX, time_B[i]);
  return MAX;
};
inline bool cmpA(int x, int y) { return time_A[x] > time_A[y]; };
inline bool cmpB(int x, int y) { return time_B[x] > time_B[y]; };
bool get_match(int p) {
  for (int i = 1; i <= m; i++)
    if (time_play[p][q2[i]] && !arenda[q2[i]]) {
      arenda[q2[i]] = 1;
      if (!match[q2[i]] || get_match(match[q2[i]])) {
        match[q2[i]] = p;
        return true;
      };
    };
  return false;
};
int main() {
  p.resize(M);
  time_play.resize(N);
  time_A.resize(N);
  time_B.resize(M);
  ycl.resize(M);
  q1.resize(N);
  q2.resize(M);
  for (int i = 0; i < N; i++) {
    time_play[i].resize(M);
  };
