      time_play[i][x] = t;
      time_A[i] += t;
      time_B[x] += t;
    };
  };
  for (int i = 1; i <= m; i++) ycl[i] = i;
  int jz = m;
  bool flag = true;
  while (flag) {
    int mx = get_max_time();
    flag = false;
    for (int i = 1; i <= jz; i++) {
      if (time_B[i] == mx && !arenda[i]) {
        if (C < p[i]) break;
        C -= p[i];
        flag = true;
        time_B[i] = time_B[++m] = 0;
        ycl[m] = i;
        arenda[i] = 1;
        for (int o = 1; o <= n; o++) {
          if (time_B[i] <= time_B[m])
            time_play[o][m] = time_play[o][i] / 2;
          else
            time_play[o][m] = (time_play[o][i] + 1) / 2;
          time_play[o][i] -= time_play[o][m];
          time_B[m] += time_play[o][m];
          time_B[i] += time_play[o][i];
        };
      };
    };
  };
  int T = get_max_time();
  cout << T << endl;
  for (int i = 1; i <= jz; i++) cout << arenda[i];
  cout << endl;
  for (int i = 1; i <= n; i++) q1[i] = i;
  for (int i = 1; i <= m; i++) q2[i] = i;
