    sort(&q1[1], &q1[n + 1], cmpA);
    sort(&q2[1], &q2[m + 1], cmpB);
    memset(match, 0, sizeof(match));
    int tmp = 1000000000, mx = 0;
    for (int i = 1; i <= n; i++) {
      memset(arenda, 0, sizeof(arenda));
      if (!get_match(q1[i])) mx = max(mx, time_A[q1[i]]);
    };
    for (int i = 1; i <= m; i++)
      if (match[i])
        tmp = min(tmp, time_play[match[i]][i]);
      else
        mx = max(mx, time_B[i]);
    tmp = min(tmp, max(time_A[q1[1]], time_B[q2[1]]) - mx);
    for (int i = 1; i <= m; i++)
      if (match[i]) {
        time_play[match[i]][i] -= tmp;
        time_B[i] -= tmp;
        time_A[match[i]] -= tmp;
        ans.push_back(
