using namespace std;
const int N = 4e5 + 5;
vector<int> adj[N];
bool can[N];
int size_down[N];
int largest_possible_down[N];
multiset<int> possible_descendant_sizes[N];
int n;
void SolveDown(int node, int parent) {
  size_down[node] = 1;
  largest_possible_down[node] = 0;
  possible_descendant_sizes[node].emplace(0);
  can[node] = true;
  for (int v : adj[node]) {
    if (v == parent) continue;
    SolveDown(v, node);
    size_down[node] += size_down[v];
    largest_possible_down[node] =
        max(largest_possible_down[node], largest_possible_down[v]);
    if (size_down[v] <= n / 2) {
      largest_possible_down[node] =
          max(largest_possible_down[node], size_down[v]);
    }
    if (size_down[v] - largest_possible_down[v] > n / 2) {
      can[node] = false;
    }
    possible_descendant_sizes[node].emplace(largest_possible_down[v]);
  }
}
void SolveUp(int node, int parent) {
  if (parent != -1) {
    int size_up = n - size_down[node];
    possible_descendant_sizes[parent].erase(
        possible_descendant_sizes[parent].find(largest_possible_down[node]));
    int largest_possible_up = *possible_descendant_sizes[parent].rbegin();
    possible_descendant_sizes[parent].emplace(largest_possible_down[node]);
    if (size_up - largest_possible_up > n / 2) {
      can[node] = false;
    }
    ++size_up;
    if (size_up <= n / 2) {
      largest_possible_up = max(largest_possible_up, size_up);
    }
    possible_descendant_sizes[node].emplace(largest_possible_up);
  } else {
    possible_descendant_sizes[node].emplace(1);
  }
  for (int v : adj[node]) {
    if (v == parent) continue;
    SolveUp(v, node);
  }
}
