      long long q = (x & 1) ^ (vis[x][y]);
      if (mp[y][0] && mp[y][1]) ok--;
      mp[y][q]--;
      if (mp[y][0] && mp[y][1]) ok++;
      if (mp[y][0] == 0 && mp[y][1] == 0) num--;
      q = (y & 1) ^ vis[x][y];
      if (a[x][0] && a[x][1]) ok1--;
      a[x][q]--;
      if (a[x][0] && a[x][1]) ok1++;
