using namespace std;
class Line {
 public:
  long long int m, c;
  Line() { m = 0, c = 0; };
  Line(long long int a_, long long int b_) {
    m = a_;
    c = b_;
  }
  bool operator<(const Line &a) const { return m < a.m; }
  long long int get_value(long long int x) { return m * x + c; }
  bool is_parallel(Line a) { return m == a.m; }
  double get_x_intersection(Line a) { return 1.0 * (c - a.c) / (a.m - m); }
  friend ostream &operator<<(ostream &output, const Line &l) {
    output << l.m << ":" << l.c;
    return output;
  }
};
class ConvexHullTrick {
 public:
  set<Line> lines;
  set<double> x_cords;
  enum Type { MAX_QUERY, MIN_QUERY } type;
  map<double, Line> x_cord_line_map;
  map<Line, double> line_x_cord_map;
  double infinity;
  ConvexHullTrick() {}
  ConvexHullTrick(Type t, double inf) {
    type = t;
    infinity = inf;
  }
  bool has_previous(set<Line>::iterator it) { return it != lines.begin(); }
  bool has_next(set<Line>::iterator it) {
    return (it != lines.end() && next(it) != lines.end());
  }
  bool is_irrelavant(Line a, Line b, Line c) {
    return a.get_x_intersection(c) <= a.get_x_intersection(b);
  }
  bool is_irrelavant(set<Line>::iterator it) {
    if (has_previous(it) && has_next(it)) {
      if (type == MAX_QUERY) return is_irrelavant(*prev(it), *it, *next(it));
      return is_irrelavant(*next(it), *it, *prev(it));
    }
    return false;
  }
  void update_start_point(set<Line>::iterator it) {
    double x;
    Line l = *it;
    if (type == MAX_QUERY) {
      if (has_previous(it))
        x = l.get_x_intersection(*prev(it));
      else
        x = -infinity;
    } else {
      if (has_next(it))
        x = l.get_x_intersection(*next(it));
      else
        x = -infinity;
    }
    x_cords.insert(x);
    x_cord_line_map.insert(make_pair(x, *it));
    line_x_cord_map.insert(make_pair(*it, x));
  }
  void erase_line(Line a) {
    x_cords.erase(line_x_cord_map.find(a)->second);
    x_cord_line_map.erase(
        x_cord_line_map.find(line_x_cord_map.find(a)->second));
    line_x_cord_map.erase(line_x_cord_map.find(a));
    lines.erase(a);
  }
  void insert_line(Line a) {
    auto it = lines.lower_bound(a);
    if (it != lines.end() && a.is_parallel(*it)) {
      if (type == MAX_QUERY && it->c < a.c)
        erase_line(*it);
      else if (type == MIN_QUERY && it->c > a.c)
        erase_line(*it);
      else
        return;
    }
    lines.insert(a);
    it = lines.find(a);
    if (is_irrelavant(it)) {
      erase_line(a);
      return;
    };
    while (has_previous(it) && is_irrelavant(prev(it))) {
      erase_line(*prev(it));
      it = lines.find(a);
    }
    while (has_next(it) && is_irrelavant(next(it))) {
      erase_line(*next(it));
      it = lines.find(a);
    }
    it = lines.find(a);
    if (type == MAX_QUERY) {
      update_start_point(it);
      if (has_next(it)) update_start_point(next(it));
    } else {
      update_start_point(it);
      if (has_previous(it)) update_start_point(prev(it));
    }
  }
  double get_value(double x) {
    auto it = x_cords.lower_bound(x);
    it--;
    double x_cord = *it;
    Line line = x_cord_line_map.find(x_cord)->second;
    return line.get_value(x);
  }
  friend ostream &operator<<(ostream &output, const ConvexHullTrick &cvt) {
    output << "Line Set\n";
    for (auto it = cvt.lines.begin(); it != cvt.lines.end(); it++)
      output << *it << endl;
    output << "X_Cord Set\n";
    for (auto it = cvt.x_cords.begin(); it != cvt.x_cords.end(); it++)
      output << *it << endl;
    output << "Line map\n";
    for (auto it = cvt.line_x_cord_map.begin(); it != cvt.line_x_cord_map.end();
         it++) {
      output << it->first << " " << it->second << endl;
    }
    output << "X_Cord Map\n";
    for (auto it = cvt.x_cord_line_map.begin(); it != cvt.x_cord_line_map.end();
         it++)
      output << it->first << " " << it->second << endl;
    return output;
  }
};
