void solve() {
  int n;
  cin >> n;
  set<int> seen;
  vector<int> minimal(n);
  vector<int> maximal(n);
  for (int i = 0; i < n; i++) {
    int num;
    cin >> num;
    if (seen.count(num)) {
      continue;
    }
    minimal[i] = num;
    maximal[i] = num;
    seen.insert(num);
  }
  int min = 1;
  for (int i = 0; i < n; i++) {
    if (minimal[i]) {
      continue;
    }
    while (seen.count(min)) {
      min++;
    }
    minimal[i] = min;
    min++;
  }
  int max = n;
  for (int i = n - 1; i >= 0; i--) {
    if (maximal[i]) {
      continue;
    }
    while (seen.count(max)) {
      max--;
    }
    maximal[i] = max;
    max--;
  }
  for (auto m : minimal) {
    cout << m << " ";
  }
  cout << endl;
  for (auto m : maximal) {
    cout << m << " ";
  }
  cout << endl;
}
