#include <bits/stdc++.h>
using namespace std;
int N;
int X[1005];
vector<int> tree[1005];
bool dp[5000005];
pair<int, int> dfs(int i) {
  if ((int)tree[i].size() == 0) return make_pair(0, X[i]);
  vector<pair<int, int> > vec;
  for (int j = 0; j < (int)tree[i].size(); j++) {
    vec.push_back(dfs(tree[i][j]));
    if (vec.back().first == -1) return make_pair(-1, -1);
  }
  vector<int> dif;
  int min = 0, max = 0;
  for (int j = 0; j < (int)vec.size(); j++) {
    min += vec[j].first;
    max += vec[j].second;
    dif.push_back(max - min);
  }
  if (X[i] < min) return make_pair(-1, -1);
  if (X[i] >= max) return make_pair(min, X[i]);
  sort(dif.begin(), dif.end());
  for (int j = 0; j <= max; j++) dp[j] = false;
  dp[0] = true;
  for (int k = 0; k < (int)dif.size(); k++) {
    if (dif[k] > max) break;
    for (int j = max; j >= 0; j--) {
      if (j - dif[k] < 0) break;
      if (dp[j - dif[k]]) dp[j] = true;
    }
  }
  for (int j = max - X[i]; j <= max; j++) {
    if (dp[j]) {
      pair<int, int> ret = make_pair(min + j, X[i]);
      if (min + j > X[i]) ret = make_pair(X[i], min + j);
      return ret;
    }
  }
}
int main(void) {
  cin >> N;
  int p;
  for (int i = 2; i <= N; i++) {
    cin >> p;
    tree[p].push_back(i);
  }
  for (int i = 1; i <= N; i++) cin >> X[i];
  pair<int, int> ans = dfs(1);
  if (ans.first == -1)
    cout << "IMPOSSIBLE" << endl;
  else
    cout << "POSSIBLE" << endl;
  return 0;
}

