inline bool chmin(double &a, double b) {
  if (a + 1e-8 > b) {
    a = b;
    return true;
  }
  return false;
}
const int M = 256;
int N;
int I[257], R[257], O[257];
int cnt[257];
double calc(int s, int a, int c) {
  R[0] = s;
  for (int i = 1; i <= N; i++) {
    R[i] = (a * R[i - 1] + c) % M;
  }
  memset(cnt, 0, sizeof cnt);
  for (int i = 1; i <= N; i++) {
    O[i] = (I[i] + R[i]) % M;
    cnt[O[i]]++;
  }
  double H = 0;
  for (int i = 1; i <= 256; i++) {
    if (!cnt[i]) continue;
    H -= double(cnt[i]) / N * log(double(cnt[i]) / N);
  }
  return H;
}
int main() {
  while (scanf("%d", &N), N) {
    for (int i = 1; i <= N; i++) scanf("%d", I + i);
