    for (int s = 0; s < 16; s++)
      for (int a = 0; a < 16; a++)
        for (int c = 0; c < 16; c++)
          if (chmin(mini, calc(s, a, c))) {
            ress = s;
            resa = a;
            resc = c;
          }
