	class fraction{
		long num = 0, den = 1;

		void reduce(){
			long d = lib.gcd(num, den);
			num /= d;
			den /= d;
		}

		fraction(long ch, long zn) {
			num = ch;
			den = zn;
			reduce();
		}

		fraction add(fraction t) {
			long nd = lib.lcm(den, t.den);
			fraction r = new fraction(nd / den * num + nd / t.den * t.num, nd);
			r.reduce();
			return r;
		}

		public String toString(){
			return num + "/" + den;
		}
	} 

