#include <bits/stdc++.h>
using namespace std;
int N, M, K, W;
int SIMPLE_COST;
int DIST[1000][1000];
int TYPE[1000][1000];
char LEVEL[1000][10][11];
int USED[1000];
int MST[1000][1000];
enum { DIFF, FULL };
void init_dist(int u, int v) {
  int d = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      if (LEVEL[u][i][j] != LEVEL[v][i][j]) {
        ++d;
      }
    }
  }
  d *= W;
  if (d > SIMPLE_COST) {
    TYPE[u][v] = FULL;
    d = SIMPLE_COST;
  } else {
    TYPE[u][v] = DIFF;
  }
  DIST[u][v] = DIST[v][u] = d;
}
void init() {
  cin >> N >> M >> K >> W;
  SIMPLE_COST = N * M;
  for (int level = 0; level < K; ++level) {
    for (int r = 0; r < N; ++r) {
      scanf("%s", LEVEL[level][r]);
    }
  }
  for (int i = 0; i < K; ++i) {
    DIST[i][i] = 0;
    MST[i][i] = 0;
    for (int j = i + 1; j < K; ++j) {
      init_dist(i, j);
      MST[i][j] = MST[j][i] = 0;
    }
  }
}
void print_ans(int from, int curr) {
  if (from == -1 || TYPE[from][curr] == FULL) {
    cout << curr + 1 << " 0\n";
  } else {
    cout << curr + 1 << " " << from + 1 << endl;
  }
  USED[curr] = 1;
  for (int u = 0; u < K; ++u) {
    if (MST[curr][u] && !USED[u]) {
      print_ans(curr, u);
    }
  }
}
int main() {
  init();
  vector<pair<int, pair<int, int> > > edges;
  for (int i = 0; i < K; ++i) {
    for (int j = i + 1; j < K; ++j) {
      edges.push_back(make_pair(DIST[i][j], make_pair(i, j)));
    }
  }
  sort(edges.begin(), edges.end());
  vector<bool> comp(K, false);
  int ans = SIMPLE_COST;
  for (int i = 0; i < edges.size(); ++i) {
    auto edge = edges[i];
    int w = edge.first;
    int u = edge.second.first;
    int v = edge.second.second;
    if (comp[u] && comp[v]) {
      continue;
    }
    MST[u][v] = MST[v][u] = 1;
    ans += DIST[u][v];
    comp[u] = comp[v] = true;
  }
  cout << ans << endl;
  fill(USED, USED + K, 0);
  print_ans(-1, 0);
  return 0;
}

