public class VideoCards {
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MAX = (int)2e5 + 1;

        int n = reader.nextInt();
        int[] array = new int[n];
        int[] sieve = new int[MAX];
        int[] vaca = new int[MAX];
        long[] sum = new long[MAX];

        for (int i = 0; i < n; i++) {
            array[i] = reader.nextInt();
        }

        for (int i = 0; i < n; i++) {
            vaca[array[i]]++;
        }

        for (int i = 1; i < MAX; i++) {
            vaca[i] += vaca[i - 1];
        }

        for (int i = 0; i < n; i++) {
            int nr = array[i];
            if (sum[nr] != 0) {
                continue;
            }
            for (int j = nr; j < MAX; j += nr) {
                int top = Math.min(MAX, j + nr);
                sum[nr] += (long)(j) * (vaca[top - 1] - vaca[j - 1]);
            }
        }

        long result = 0;
        for (int i = 0; i < MAX; i++) {
            result = Math.max(result, sum[i]);
        }

        out.println(result);
        out.close();
