const int N = 1e6 + 10;
vector<int> V[N], G[N];
int ans[N], cnt = 0;
void dfs(int No, int par) {
  G[cnt++].push_back(1);
  int u = cnt;
  for (auto k : V[No]) {
    if (k != par) dfs(k, No);
  }
  int M = 0, L = 1, l = cnt;
  for (int k = u; k < l; k++) {
    int len = G[k].size();
    for (int j = 0; j < len; j++) {
      if (j + 1 >= G[u - 1].size())
        G[u - 1].push_back(G[k][j]);
      else
        G[u - 1][j + 1] += G[k][j];
      if (G[u - 1][j + 1] > L)
        M = j + 1, L = G[u - 1][j + 1];
      else if (G[u - 1][j + 1] == L && j + 1 < M)
        M = j + 1;
    }
    cnt--;
  }
  ans[No] = M;
}
int main() {
