public class Main
{
	public static void main(String[] args) {
		new Thread(null, new Runnable() {
			public void run() {
                solve();
            }
        }, "1", 1 << 26).start();
	}
	static void solve () {
		FastReader fr =new FastReader();	PrintWriter op =new PrintWriter(System.out);

 		int n =fr.nextInt() ,x =fr.nextInt() ,pos =fr.nextInt() ,gCt =n-x ,lCt =x-1 ,eCt =1 ,l ,r ,mid ;

 		long ct =1l ,mod =1000000007l ;

 		l =0 ;	r =n ;

 		while (l<r) {
 			mid =(l+r)/2 ;

 			if (mid < pos) {
 				ct =(ct * lCt)%mod ;

 				--lCt ;

 				l =mid+1 ;
 			}
 			else if (mid > pos) {
 				ct =(ct * gCt)%mod ;

 				--gCt ;

 				r =mid ;
 			}
 			else {
 				ct =(ct * eCt)%mod ;

 				--eCt ;

 				l =mid+1 ;
 			}
 		}

 		ct *= fact(gCt+lCt , mod) ;	ct %= mod ;

		op.println(ct) ;	op.flush();	op.close();
	}
	static long fact (long n , long mod) {
		long f =1l ;

		while (n>1l) {
			f *= n ;	f %= mod ;

			--n ;
		}

		return f ;
	}
	static class FastReader {
		BufferedReader br;
		StringTokenizer st;

		public FastReader() {
			br =new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
