int main() {
  scanf("%d", &N);
  priority_queue<pair<int, int>> que;
  for (int i = 1; i <= N; i++) {
    scanf("%d", arr + i);
    que.push(make_pair(arr[i], i));
  }
  while (!que.empty()) {
    pair<int, int> u = que.top();
    que.pop();
    int i = u.second, v = u.first;
    if (v <= num[i]) continue;
    if (v > num[i]) {
      num[i] = v;
      for (int j = i - 1; j >= 1 && v; j--) {
        num[j] = max(num[j], --v);
      }
    }
  }
  for (int i = 1; i <= N; i++) {
    num[i] = max(num[i], num[i - 1]);
  }
  int ans = 0;
  for (int i = 1; i <= N; i++) {
    ans += num[i] - arr[i];
  }
  printf("%d\n", ans);
}

