public class Solution {
	public static final boolean std = true;
	public static final boolean useFastIn = true;
	public static final String inputFile = "input.txt";
	public static final String outputFile = "output.txt";

	public final Scanner in;
	public final RFScanner fin;
	public final PrintWriter out;

	public Solution(Scanner i, PrintWriter o) {
		in = i;
		out = o;
		fin = null;
	}

	public Solution(RFScanner i, PrintWriter o) {
		in = null;
		out = o;
		fin = i;
	}

	public static void main(String[] args) throws Exception {
		Solution s;
		PrintWriter out;
		Reader is;
		Closeable in;

		Locale.setDefault(Locale.ENGLISH);

		if (std) {
			is = new InputStreamReader(System.in);
			out = new PrintWriter(System.out);
		} else {
			is = new FileReader(new File(inputFile));
			out = new PrintWriter(new File(outputFile));
		}

		if (useFastIn) {
			in = new RFScanner(is);
			s = new Solution((RFScanner) in, out);
		} else {
			in = new Scanner(is);
			s = new Solution((Scanner) in, out);
		}

		s.run();
		in.close();
		out.close();
	}



	int n;
	long x = 2;
	public void run() throws Exception {
		n = fin.nextInt();
		for (int i=1; i<=n; i++) {
			long t = ((long) i) * (i+1) * (i+1) - x / i;
			x = ((long) i) * (i+1);
			out.println(t);
		}
	}



	static class RFScanner implements Closeable {
		private BufferedReader reader;
		private StringTokenizer tokenizer;

		public RFScanner(Reader is) {
			reader = new BufferedReader(is);
			tokenizer = new StringTokenizer("");
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public float nextFloat() {
			return Float.parseFloat(next());
		}

		public BigInteger nextBigInteger() {
			return new BigInteger(next());
		}

		public String next() {
			boolean has = false;
			try {
				has = hasNext();
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
			if (has)
				return tokenizer.nextToken();
			return null;
		}

		public String nextLine() throws IOException {
			tokenizer = new StringTokenizer("");
			return reader.readLine();
		}

		public boolean hasNext() throws IOException {
			while (!tokenizer.hasMoreTokens()) {
				String s = reader.readLine();
				if (s == null) {
					return false;
				}
				tokenizer = new StringTokenizer(s);
			}
			return true;
		}

		@Override
		public void close() throws IOException {
			reader.close();
		}
	}
}

