int dfs(string str){
    int ret = 0;
    if('0' <= str[0] && str[0] <= '9'){
        rep(i,str.size()){
            ret = ret*10+str[i]-'0';
        }
        return ret;
    }
    char x = str[0];
    int y = dfs(str.substr(2,str.size()-3));
    if(si.count(x) == 0) return -1;
    if(ni.count(x) == 0) return -1;
    if(ni[x].count(y) == 0) return -1;
    return ni[x][y];
}

void solve(string str){
    si.clear();
    ni.clear();
    int ans = 0;
    bool end = false;
    do{
        ans++;
        if(str == ".") break;
        if(end) continue;
        bool eq = false;
        rep(i,str.size()) if(str[i] == '=') eq = true;
        if(!eq){
            int num = 0;
            for(int i = 2;;i++){
                if('0' > str[i] || str[i] > '9') break;
                num = num*10+str[i]-'0';
            }
            si[str[0]] = num;
        } else{
            char x = str[0];
            int xpos;
            int bla = 0;
            string s;
            int i;
            for(i = 2;; i++){
                if(str[i] == '[') bla++;
                if(str[i] == ']') bla--;
                if(bla < 0){
                    xpos = dfs(s);
                    break;
                }
                s.push_back(str[i]);
            }
            int val = dfs(str.substr(i+2));
            if(xpos == -1 || val == -1){
                cout << ans << endl;
                end = true;
                continue;
            }
            if(xpos >= si[x]){
                cout << ans << endl;
                end = true;
                continue;
            }
            ni[x][xpos] = val;
        }
    } while(cin >> str);
    if(!end) cout << 0 << endl;
}

int main(){
    string str;
    while(cin >> str){
        if(str == ".") break;
        solve(str);
    }
}

