void Del(int k, int x) {
  if (p[k].l == x && x == p[k].r) {
    p[k].Min = INF;
    p[k].index = 0;
    return;
  }
  if (x <= p[k << 1].r)
    Del(k << 1, x);
  else
    Del(k << 1 | 1, x);
  Update(k);
  return;
}
