using namespace std;
using ld = long double;
using Point = complex<ld>;
const ld eps = 1e-9;

vector<ld>quad_equa(ld a, ld b, ld c) {
	ld root = b*b - 4 * a*c;
	if (abs(root) < eps) {
		ld ans = -b / (2 * a);
		return vector<ld>(2, ans);
	}
	else if (root > 0) {
		ld ans = -b / (2 * a);
		vector<ld>anss(2);
		anss[0] = ans + sqrt(root) / (2 * a);
		anss[1] = ans - sqrt(root) / (2 * a);
		if (anss[0] > anss[1])swap(anss[0], anss[1]);
		return anss;
	}
	else {
		return vector<ld>();
	}
}

pair<ld, Point> getway(Point dp,const ld dv, Point fp, Point fv) {
	fp -= dp;
	auto ts= quad_equa(norm(fv)-dv*dv, 2 * fv.real()*fp.real() + 2 * fv.imag()*fp.imag(), norm(fp));
	if (ts.empty()) {
		return make_pair(1e18, Point(0.l, 0.l));
	}
	else {
		ld t;
		if (ts[0] < -eps) {
			if (ts.size()>1) {

				t = ts[1];
			}
			else {
				t = ts[0];
			}
		}
		else t = ts[0];
		if (t < -eps)return make_pair(1e18, Point(0.l, 0.l));
		Point catp = fp + fv*t;
		return make_pair(t, catp / ld(t));
	}
}

