	public static void main(String[] args) 
	{
		Scanner scan=new Scanner(System.in);
		int test=scan.nextInt();
		while(test-->0) 
		{

		int input=scan.nextInt();

		if(input<2) 
		{
			System.out.println("FastestFinger");
		}
		else if(input%2!=0) 
		{
			System.out.println("Ashishgup");
		}
		else //even number 
		{
			//if(getOddDivisor(input)==-1)//even number with no odd factors in it.
			if(isPowOf2(input)) 
			{
				if(input==2) 
				{

					System.out.println("Ashishgupxx");
				}
				else 
				{
				 System.out.println("FastestFinger");
				 }
			 }
			else if (input%4==0) //multiple even factors and one or more odd factors
			{
				System.out.println("Ashishgup4");
			}
			else if(chkPrime(input/2))//odd factor= primenumber (1)
			 {
				System.out.println("FastestFinger");
			 }
			else //multiple odd factors and 1 even factor
			{
				System.out.println("Ashishgup");
			}
		 }
		}
		scan.close();
	}
	static boolean chkPrime(long input) 
	 {
		for(int i=3;i*i<=input;i++) 
		{
			if(input%i==0) 
			{
				return false;
			}
		}
		return true;
	 }

	static boolean isPowOf2(long n) 
	{
		return n!=0 && ((n&(n-1)) == 0);
	}
}

