using namespace std;
const int abc = 26;
vector<vector<vector<int> > > f;
inline bool same(const vector<int>& a, const vector<int>& b) {
  int na = 0, nb = 0;
  for (int j = 0; j < abc; j++) {
    na += (a[j] & 1);
    nb += (b[j] & 1);
    if (a[j] != b[j]) {
      return false;
    }
  }
  if (na > 1 || nb > 1) {
    return false;
  }
  return true;
}
bool palindrome(vector<int>& a) {
  int na = 0;
  for (int j = 0; j < abc; j++) {
    na += (a[j] & 1);
  }
  return na < 2;
}
int solve(int s1, int s2, int n) {
  vector<vector<int> > myf(n, vector<int>(abc, 0));
  vector<bool> palr(n, false);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < abc; j++) {
      myf[i][j] = f[s2 + 1][i][j] - f[s1][i][j];
    }
    int neparny = 0;
    if (neparny < 2) {
      palr[i] = true;
    }
  }
  vector<int> d1(n, 0), d2(n, 0);
  int ans = 0;
  int l = 0, r = 0;
  for (int i = 0; i < n; i++) {
    if (i < r) {
      d1[i] = min(r - i, d1[l + r - i]);
    }
    int li = i - d1[i], ri = i + d1[i];
    while (li - 1 >= 0 && ri + 1 < n && same(myf[li - 1], myf[ri + 1])) {
      d1[i]++;
      li--;
      ri++;
    }
    if (ri > r) {
      r = ri;
      l = li;
    }
    if (palindrome(myf[i])) {
      ans += d1[i] + 1;
    }
  }
  l = 0, r = 0;
  for (int i = 0; i < n; i++) {
    if (i < r) {
      d2[i] = min(r - i + 1, d2[l + r - i + 1]);
    }
    int li = i - d2[i], ri = i + d2[i] - 1;
    while (li - 1 >= 0 && ri + 1 < n && same(myf[li - 1], myf[ri + 1])) {
      d2[i]++;
      li--;
      ri++;
    }
    if (ri > r) {
      r = ri;
      l = li;
    }
    ans += d2[i];
  }
  return ans;
}
