	public static boolean eight(final int c, final int deep, boolean[][] board,boolean[][] queens, Map<Integer, Integer> already) {

		if (deep >= c) {
			for (int i = 0; i < 8; i++) {
				for (int j = 0; j < 8; j++) {
					System.out.print(queens[i][j] ? "Q" : ".");
				}
				System.out.println();
			}

			return true;
		} else {
			if(already.containsKey(deep)){
				final int pos = already.get(deep);

				if(board[deep][pos]){
					return false;
				}

				boolean[][] copy = new boolean[8][8];
				for (int i = 0; i < 8; i++) {
					for (int j = 0; j < 8; j++) {
						copy[i][j] = board[i][j];
					}
				}
				queens[deep][pos] = true;

				for (int dx = -1; dx <= 1; dx++) {
					final int dy = 1;
					int y = deep, x = pos;

					while (y >= 0 && y < 8 && x >= 0 && x < 8) {
						board[y][x] = true;

						x += dx; y += dy;
					}
				}

				if (eight(c, deep + 1, board, queens, already)) {
					return true;
				}

				queens[deep][pos] = false;

				for (int i = 0; i < 8; i++) {
					for (int j = 0; j < 8; j++) {
						board[i][j] = copy[i][j];
					}
				}
			}else{
				for(int pos = 0; pos < 8; pos++){
					if(board[deep][pos]){
						continue;
					}

					boolean[][] copy = new boolean[8][8];
					for (int i = 0; i < 8; i++) {
						for (int j = 0; j < 8; j++) {
							copy[i][j] = board[i][j];
						}
					}
					queens[deep][pos] = true;

					for (int dx = -1; dx <= 1; dx++) {
						final int dy = 1;
						int y = deep, x = pos;

						while (y >= 0 && y < 8 && x >= 0 && x < 8) {
							board[y][x] = true;

							x += dx; y += dy;
						}
					}

					if (eight(c, deep + 1, board, queens, already)) {
						return true;
					}

					queens[deep][pos] = false;

					for (int i = 0; i < 8; i++) {
						for (int j = 0; j < 8; j++) {
							board[i][j] = copy[i][j];
						}
					}
				}
			}
		}

		return false;
	}

