    if (sum[o] > a) sum[o] = a;
    if (!is[o]) is[o] = 1;
    return;
  }
  int mid = (l + r) / 2;
  if (p <= mid)
    Update(o << 1, l, mid);
  else
    Update(o << 1 | 1, mid + 1, r);
  Push_up(o);
}
int query(int o, int l, int r) {
  if (ql <= l && r <= qr) {
    return is[o];
  }
  int mid = (l + r) / 2;
  int ans = 0;
  if (ql <= mid) ans += query(o << 1, l, mid);
  if (qr > mid) ans += query(o << 1 | 1, mid + 1, r);
  return ans;
}
long long Query(int o, int l, int r) {
  if (ql <= l && r <= qr) {
    return sum[o];
  }
  int mid = (l + r) / 2;
  long long ans = 0LL;
  if (ql <= mid) ans += Query(o << 1, l, mid);
  if (qr > mid) ans += Query(o << 1 | 1, mid + 1, r);
  return ans;
}
void solve() {
  int cmd, dd, aa, pp;
  memset(is, 0, sizeof(is));
  memset(sum, 0, sizeof(sum));
  for (int i = 1; i <= q; i++) {
    scanf("%d", &cmd);
    if (cmd == 1) {
      scanf("%d %d", &p, &v);
      Update(1, 1, n);
    } else {
      scanf("%d", &pp);
      ql = 1;
      qr = pp - 1;
      int qian, hou;
      long long tmpq, tmph;
      if (qr < ql) {
        qian = 0LL;
        tmpq = 0LL;
      } else {
        qian = query(1, 1, n);
        tmpq = Query(1, 1, n);
      }
      long long Qian = 1LL * qian * b;
      ql = pp + k;
      qr = n;
      hou = query(1, 1, n);
      long long Hou = 1LL * hou * a;
      tmph = Query(1, 1, n);
      long long res = min(Qian, tmpq) + min(Hou, tmph);
      printf("%I64d\n", res);
    }
  }
}
int main() {
  while (scanf("%d %d %d %d %d", &n, &k, &a, &b, &q) != EOF) {
    solve();
  }
  return 0;
}

