    for (int i = 0; i < move.length(); ++i) {
      if (move[i] == 'U')
        y--;
      else if (move[i] == 'D')
        y++;
      else if (move[i] == 'R')
        x++;
      else if (move[i] == 'L')
        x--;
      dam.push_back(trap[string(1, mp[y][x])]);
    }
    memset(dp, -1, sizeof(dp));
    dp[0][0] = hp;
    for (int i = 0; i < dam.size(); ++i) {
      for (int j = 0; j < (1 << p); ++j) {
        if (dp[i][j] > 0) {
          dp[i + 1][j] = dp[i][j];
          for (int k = 0; k < p; ++k) {
            if (j & (1 << k)) continue;
            dp[i + 1][j | (1 << k)] =
                max(dp[i + 1][j | (1 << k)], min(maxhp, dp[i][j] + pot[k]));
          }
        }
      }
      for (int j = 0; j < (1 << p); ++j) dp[i + 1][j] -= dam[i];
    }
    bool ok = false;
    for (int j = 0; j < (1 << p); ++j)
      if (dp[dam.size()][j] > 0) ok = true;
    if (ok)
      cout << "YES" << endl;
    else
      cout << "NO" << endl;
  }
}

