public class CF155D {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        boolean[] isOn = new boolean[n+1];

        int[] primes = new int[n+1];
        boolean[] isNotPrime = new boolean[n+1];
        int numPrimes = 0;
        isNotPrime[0] = isNotPrime[1] = true;
        for (int i = 2; i*i < n; i++) {
            if(!isNotPrime[i]) {
                primes[numPrimes++] = i;
                for (int j = i*2; j < n; j += i) {
                    isNotPrime[j] = true;
                }
            }
        }
        @SuppressWarnings("unchecked")
        SortedSet<Integer>[] primesHolding = new SortedSet[numPrimes];
        for (int i = 0; i < numPrimes; i++) {
            primesHolding[i]= new TreeSet<Integer>();
        }

        for (int i = 0; i < m; i++) {
            char command = sc.next().charAt(0);
            int nu = sc.nextInt();
            if (command == '+') {
                if (isOn[nu]) {
                    System.out.println("Already on");
                }
                else {
                    boolean found = false;
                    boolean conflict = false;
                    for (int j = 0; j < numPrimes; j++) {
                        if (nu % primes[j] == 0) {
                            found = true;
                            if (!primesHolding[j].isEmpty()) {
                                conflict = true;
                                System.out.println("Conflict with " + primesHolding[j].first());
                                break;
                            }
                        }
                    }
                    if (!found) {
                        isOn[nu] = true;
                        System.out.println("Success");
                    }
                    else if (!conflict) {
                        isOn[nu] = true;
                        System.out.println("Success");
                        for (int j = 0; j < numPrimes; j++) {
                            if (nu % primes[j] == 0) {
                                primesHolding[j].add(nu);
                            }
                        }
                    }
                }
            }
            else {
                if (!isOn[nu]) {
                    System.out.println("Already off");
                }
                else {
                    for (int j = 0; j < numPrimes; j++) {
                        if (nu % primes[j] == 0) {
                            primesHolding[j].remove(nu);
                        }
                    }

                    isOn[nu] = false;
                    System.out.println("Success");
                }

            }

        }
    }

}

