    }
    cerr << endl;
  }
};
long long combination(int n, int k) {
  long long ans = 1;
  for (int i = (1); i < (k + 1); ++i) {
    ans *= n - i + 1;
    ans /= i;
  }
  return ans;
}
const long double EPS = 1e-9;
int main() {
  cout.precision(16);
  int N, M, L;
  cin >> N >> M >> L;
  vector<Runner> runners;
  for (int i = (0); i < (N); ++i) {
    Runner runner;
    long double P;
    int T, V;
    cin >> P >> T >> V;
    P /= 100.0;
    long double base_time = V > 0 ? (long double)L / V : 1e20;
    for (int t_break = (0); t_break < (M + 1); ++t_break) {
      runner.goal_times.push_back(base_time + T * t_break);
      runner.probabilities.push_back(pow(P, t_break) * pow(1 - P, M - t_break) *
                                     combination(M, t_break));
    }
    runners.push_back(runner);
  }
  for (int i = (0); i < (runners.size()); ++i) {
    Runner &r = runners[i];
    long double ans = 0;
    for (int t = (0); t < (M + 1); ++t) {
      long double prize_prob = r.probabilities[t];
      for (int j = (0); j < (runners.size()); ++j) {
        if (i == j) continue;
        Runner &comp = runners[j];
        long double win_prob = 0;
        for (int k = (0); k < (M + 1); ++k) {
          if (comp.goal_times[k] > r.goal_times[t] + EPS) {
            win_prob += comp.probabilities[k];
          }
        }
        prize_prob *= win_prob;
      }
      ans += prize_prob;
    }
    printf("%.16f\n", ans);
  }
}

