	static void sieve() {
		smallestfac=new int[nax];
		primes=new ArrayList<>();
		Arrays.fill(smallestfac, -1);
		for(int i=2;i<nax;i++) {
			if(smallestfac[i]==-1) {
				primes.add(i);
				smallestfac[i]=i;
				for(int j=2*i;j<nax;j+=i) {
					if(smallestfac[j]==-1)smallestfac[j]=i;
				}
			}
		}
	}

	static Map<Integer,Integer> primefac(int n,int k) {
		Map<Integer,Integer> map=new HashMap<>();
		while(n>1) {
			int c=smallestfac[n],e=0;
			while(n%c==0) {
				n/=c;
				e++;
			}
			if(e%k>0)map.put(c,e%k);
		}
		return map;
	}

