void insert(int x) {
  for (int i = 30; i >= 0; i--) {
    if (!(x >> i) & 1) continue;
    if (base[i]) {
      x ^= base[i];
    } else {
      for (int j = i - 1; j >= 0; j--) {
        if ((x >> j) & 1) x ^= base[j];
      }
      for (int j = i + 1; j <= 30; j++) {
        if ((base[j] >> i) & 1) base[j] ^= x;
      }
