    x = b.x - a.x;
    y = b.y - a.y;
  }
};
long double operator%(Vector a, Vector b) { return a.x * b.y - a.y * b.x; }
long double dict(point a, point b) { return hypot(a.x - b.x, a.y - b.y); }
long double dist1(point a, point b, point c) {
  return abs(Vector(a, b) % Vector(a, c)) / dict(b, c);
}
