  while (right - left > EPS) {
    long double mid = (right + left) / 2;
    bool possible = true;
    for (int i = 0; i < n; ++i) {
      if (dist1(a[i + 1], a[i], a[i + 2]) < 2 * mid) {
        possible = false;
