inline void Dijkstra(int fi,int se)
{
  for(int i=0;i<maxn*maxn;++i)
    v[i].resize(0);

  const int Inf = 1000 * 1000 * 1000;
  for(int i=0;i<maxn;++i)
    for(int j=0;j<maxn;++j)
      best[i][j] = Inf;
  best[fi][se] = 0;

  v[0].push_back(pii(fi,se) );
  for(int i=0;i<maxn*maxn;++i){
    if(v[i].size() == 0)
      break;
    for(int j=0;j<v[i].size();++j){
      int nx,ny;
      nx = v[i][j].x;
      ny = v[i][j].y;
      if(best[nx][ny] != i)
	continue;
      for(int l=0;l<4;++l){
	int Nx,Ny;
	Nx = nx + move[l][0];
	Ny = ny + move[l][1];
	if(best[Nx][Ny] > best[nx][ny] + (a[nx][ny] != a[Nx][Ny]) ){
	  best[Nx][Ny] = best[nx][ny] + (a[nx][ny] != a[Nx][Ny]);
	  v[best[Nx][Ny]].push_back(pii(Nx,Ny) );
	}
      }
    }
  }

  for(int i=1;i<=n;++i)
    for(int j=1;j<=m;++j)
      if(a[i][j] == 1)
	Max[fi][se] = max(Max[fi][se],best[i][j]);
}

