const int MxN = (int)2e5 + 9;
long long p2[MxN + 9];
long long f(vector<int> &v, const int k) {
  const int n = (int)v.size();
  long long res1 = 1, res2 = v[0] == -1, spe = max(1, v[0]);
  v.erase(v.begin());
  for (const int &x : v) {
    if (x == -1) {
      long long t = res2 * (k - 2LL) + res2;
      res2 = res2 * (k - 2LL) + res1;
      res1 = t;
    } else {
      res1 = res2 * (k - 2LL) + (spe == x ? res2 : res1);
      res2 = 0;
      spe = x;
    }
    res1 %= mod;
    res2 %= mod;
  }
  const long long res = (res1 + res2 * (k - 1LL)) % mod;
  return res;
}
