int uset[MAXN];
int rank[MAXN];

class UnionSet{
public:
    void Init(int n){
        for(int i=1; i<=n; ++i){
            uset[i] = i; rank[i] = 0;
        }
    }
    int Find(int x)
    {
        if(x == uset[x]) return x;
        else {
            int fx = uset[x];
            uset[x] = Find(fx);
            return uset[x];
        }
    }
    bool Union(int x, int y) //x and y are different
    {
        int fx = Find(x), fy = Find(y);
        if(fx == fy) return false;
        if(rank[fx] > rank[fy])
            uset[fy] = fx;
        else{
            uset[fx] = fy;
            if(rank[fx] == rank[fy]) rank[fy]++;
        }
        return true;
    }

};

UnionSet us;


void dfs(int r, int pa)
{
    for(int i=0; i<tree[r].size(); i++){
        int x = tree[r][i];
        if(isMarked[x]) dfs(x, x);
        else dfs(x, pa);
    }
    us.Union(r, pa);
}


