    Matrix mat;
    *mat.m_Mat = *m_Mat;
    return mat;
  }
  void newLines(Matrix mat) {
    for (int x = 0; x < mat.m_Mat->size(); ++x) {
      for (int y = 0; y < (*mat.m_Mat)[0].size(); ++y) {
        (*m_Mat)[x].push_back((*mat.m_Mat)[x][y]);
      }
