  void newColums(Matrix mat) {
    for (auto it = mat.m_Mat->begin(); it != mat.m_Mat->end(); ++it) {
      m_Mat->push_back(*it);
    }
  }
  bool isInt() { return m_Mat->size() == 1 && (*m_Mat)[0].size() == 1; }
  Matrix& operator+=(Matrix mat) {
    for (auto w = 0; w < m_Mat->size(); ++w) {
      for (auto h = 0; h < (*m_Mat)[w].size(); ++h) {
        (*m_Mat)[w][h] += (*mat.m_Mat)[w][h];
      }
    }
    return *this;
  }
  Matrix& operator-=(Matrix mat) {
    for (auto w = 0; w < m_Mat->size(); ++w) {
      for (auto h = 0; h < (*m_Mat)[0].size(); ++h) {
        (*m_Mat)[w][h] -= (*mat.m_Mat)[w][h];
      }
    }
    return *this;
  }
  Matrix& operator*=(Matrix mat) {
    if (mat.isInt()) {
      *this *= (*mat.m_Mat)[0][0];
      return *this;
    } else if (isInt()) {
      mat *= (*this->m_Mat)[0][0];
      this->m_Mat = mat.m_Mat;
      return *this;
    }
    Matrix newMat;
    for (auto r = 0; r < mat.m_Mat->size(); ++r) {
      (*newMat.m_Mat).push_back(std::vector<long long>());
      for (auto l = 0; l < (*m_Mat)[0].size(); ++l) {
        (*newMat.m_Mat)[r].push_back(0);
        for (auto i = 0; i < m_Mat->size(); ++i) {
          (*newMat.m_Mat)[r][l] += (*m_Mat)[i][l] * (*mat.m_Mat)[r][i];
        }
      }
    }
    this->m_Mat = newMat.m_Mat;
    return *this;
  }
  Matrix& operator*=(int x) {
    for (auto w = 0; w < m_Mat->size(); ++w) {
      for (auto h = 0; h < (*m_Mat)[0].size(); ++h) {
        (*m_Mat)[w][h] *= x;
      }
    }
    return *this;
  }
  Matrix& indexed(Matrix h, Matrix w) {
    Matrix mat;
    for (auto x = (*w.m_Mat).begin(); x != (*w.m_Mat).end(); ++x) {
      mat.m_Mat->push_back(std::vector<long long>());
      for (auto y = (*h.m_Mat).begin(); y != (*h.m_Mat).end(); ++y) {
        (*mat.m_Mat)[mat.m_Mat->size() - 1].push_back(
            (*m_Mat)[(*x)[0] - 1][(*y)[0] - 1]);
      }
    }
    this->m_Mat = mat.m_Mat;
    return *this;
  }
  Matrix& trans() {
    Matrix mat;
    for (int x = 0; x < (*m_Mat)[0].size(); ++x) {
      mat.m_Mat->push_back(std::vector<long long>());
      for (int y = 0; y < m_Mat->size(); ++y) {
        (*mat.m_Mat)[mat.m_Mat->size() - 1].push_back((*m_Mat)[y][x]);
      }
    }
    m_Mat = mat.m_Mat;
    return *this;
  }

 private:
  std::shared_ptr<std::vector<std::vector<long long>>> m_Mat;
};
