    mat.newColums(rMat);
  }
  return mat;
}
Matrix parseRowSeq(std::string::iterator& it) {
  auto mat = parseRow(it);
  while (*it == ';') {
    ++it;
    auto rMat = parseRow(it);
    mat.newLines(rMat);
  }
  return mat;
}
Matrix parseMatrix(std::string::iterator& it) {
  ++it;
  auto mat = parseRowSeq(it);
  ++it;
  return mat;
}
Matrix parsePrimary(std::string::iterator& it) {
  Matrix mat;
  if (isalpha(*it)) {
    mat = g_Dict[*it - 'A'].clone();
    ++it;
  } else if (isdigit(*it)) {
    mat = parseInum(it);
  } else if (*it == '(') {
    ++it;
    mat = parseExpr(it);
    ++it;
    ++it;
  } else if (*it == '[') {
    mat = parseMatrix(it);
  }
  if (*it == '\'') {
    mat.trans();
  } else if (*it == '(') {
    ++it;
    auto h = parseExpr(it);
    ++it;
    auto w = parseExpr(it);
    ++it;
    mat.indexed(h, w);
  }
  return mat;
}
Matrix parseFactor(std::string::iterator& it) {
  if (*it == '-') {
    ++it;
    auto mat = parseFactor(it);
    mat *= -1;
    return mat;
  } else {
    return parsePrimary(it);
  }
}
Matrix parseTerm(std::string::iterator& it) {
  auto mat = parseFactor(it);
  while (*it == '*') {
    ++it;
    auto rMat = parseFactor(it);
    mat *= rMat;
  }
  return mat;
}
Matrix parseExpr(std::string::iterator& it) {
  auto mat = parseTerm(it);
  while (*it == '-' || *it == '+') {
    char op = *it;
    ++it;
    auto rMat = parseTerm(it);
    if (op == '-') {
      mat -= rMat;
    } else {
      mat += rMat;
    }
  }
  return mat;
}
