    cnt[cur_bl][a[i]]++;
    sz[cur_bl]++;
    if (cur == BLOCK_SIZE) {
      cur_bl++;
      cur = 0;
    }
  }
}
inline void recalc(int &l, int &r, int &k) {
  l = (l + lastans - 1) % n;
  r = (r + lastans - 1) % n;
  k = (k + lastans - 1) % n + 1;
  if (l > r) {
    swap(l, r);
  }
}
inline void shift(int l, int r) {
  auto coord = get_block(r);
  int b = coord.first;
  int pos = coord.second;
  int val = bl[b][pos];
  sz[b]--;
  cnt[b][val]--;
  for (int i = pos; i < sz[b]; i++) {
    bl[b][i] = bl[b][i + 1];
  }
  coord = get_block(l);
  b = coord.first;
  pos = coord.second;
  sz[b]++;
  cnt[b][val]++;
  for (int i = sz[b] - 1; i >= pos; i--) {
    bl[b][i] = bl[b][i - 1];
  }
  bl[b][pos] = val;
}
int count(int l, int r, int k) {
  auto coordl = get_block(l);
  auto coordr = get_block(r);
  int bll = coordl.first, posl = coordl.second;
  int blr = coordr.first, posr = coordr.second;
  int res = 0;
  if (bll == blr) {
    for (int i = posl; i <= posr; i++) {
      if (bl[bll][i] == k) {
        res++;
      }
    }
  } else {
    for (int i = posl; i < sz[bll]; i++) {
      if (bl[bll][i] == k) {
        res++;
      }
    }
    for (int i = 0; i <= posr; i++) {
      if (bl[blr][i] == k) {
        res++;
      }
    }
    for (int i = bll + 1; i < blr; i++) {
      res += cnt[i][k];
    }
  }
  return res;
}
