long long po(long long a, int b) {
  if (b == 0) return 1LL;
  long long z = po(a, b / 2);
  z = z * z % mod;
  if (b % 2 == 1) z = z * a % mod;
  return z;
}
vector<int> get(int a) {
  vector<int> r;
  for (int i = 1;; i++) {
    if (i * i > a) break;
    if (a % i == 0) {
      r.push_back(i);
      if (i * i != a) r.push_back(a / i);
    }
  }
  return r;
}
int gcd(int a, int b) {
  for (;;) {
    if (a < b) swap(a, b);
    a %= b;
    if (a == 0) return b;
  }
}
