using namespace std;
const int maxn = 1e7 + 7;
const int inf = 1e8;
int _min[maxn], _max[maxn], lazy[maxn];
void add(int rt, int l, int r, int L, int R, int val) {
  if (r < L || l > R)
    return;
  else if (l >= L && r <= R) {
    lazy[rt] += val;
    return;
  }
  int mid = (l + r) / 2;
  add(((rt) << 1), l, mid, L, R, val);
  add(((rt) << 1 | 1), mid + 1, r, L, R, val);
  _min[rt] = min(_min[((rt) << 1)] + lazy[((rt) << 1)],
                 _min[((rt) << 1 | 1)] + lazy[((rt) << 1 | 1)]);
  _max[rt] = max(_max[((rt) << 1)] + lazy[((rt) << 1)],
                 _max[((rt) << 1 | 1)] + lazy[((rt) << 1 | 1)]);
}
int q_min(int rt, int l, int r, int L, int R, int ad = 0) {
  if (r < L || l > R)
    return inf;
  else if (l >= L && r <= R) {
    return _min[rt] + lazy[rt] + ad;
  }
  int mid = (l + r) / 2;
  return min(q_min(((rt) << 1), l, mid, L, R, ad + lazy[rt]),
             q_min(((rt) << 1 | 1), mid + 1, r, L, R, ad + lazy[rt]));
}
int q_max(int rt, int l, int r, int L, int R, int ad = 0) {
  if (r < L || l > R)
    return -inf;
  else if (l >= L && r <= R) {
    return _max[rt] + lazy[rt] + ad;
  }
  int mid = (l + r) / 2;
  return max(q_max(((rt) << 1), l, mid, L, R, ad + lazy[rt]),
             q_max(((rt) << 1 | 1), mid + 1, r, L, R, ad + lazy[rt]));
}
