        int N = in.nextInt();
        // find smallest prime fators of all numbers in [2:N]
        int[] spf = new int[N + 1];
        for (int i = 2; i <= N; i++) {
            if (spf[i] > 0)
                continue;
            spf[i] = i;
            for (int j = i + i; j <= N; j += i) {
                if (spf[j] == 0)
                    spf[j] = i;
            }
        }

        long res = 1;
        for (int k = 2; k <= N; k++) {
            long fk = f(k, spf);
            res += k * fk;
        }
        out.println(res);
