    private int f(int x, int[] spf) {
        int cnt = 1, p = spf[x], cur = 0;
        while (x > 1) {
            if (spf[x] != p) {
                cnt *= 1 + cur;
                cur = 0;
                p = spf[x];
            }
            cur++;
            x /= p;
        }
        cnt *= 1 + cur;
        return cnt;
    }

