class FastScanner{
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream)
    {
        this.stream = stream;
    }

    int read()
    {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars){
            curChar = 0;
            try{
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c)
    {
        return c==' '||c=='\n'||c=='\r'||c=='\t'||c==-1;
    }

    boolean isEndline(int c)
    {
        return c=='\n'||c=='\r'||c==-1;
    }

    int nextInt()
    {
        return Integer.parseInt(next());
    }

    long nextLong()
    {
        return Long.parseLong(next());
    }

    double nextDouble()
    {
        return Double.parseDouble(next());
    }

    String next(){
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isSpaceChar(c));
        return res.toString();
    }

    String nextLine(){
        int c = read();
        while (isEndline(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isEndline(c));
        return res.toString();
    }
}

#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
namespace flow {
const int N = 100 * 1000;
struct Edge {
  int v, cap, flow;
  int back_ind;
  Edge* back;
  Edge(int vi, int ci) : v(vi), cap(ci) {}
};
int n, s, t;
int e[N], h[N];
vector<Edge> g[N];
vector<Edge>::iterator cur[N];
void bfs(int start, int start_h) {
  queue<int> q;
  h[start] = start_h;
  for (q.push(start); !q.empty(); q.pop()) {
    int u = q.front();
    for (__typeof((g[u]).begin()) i = (g[u]).begin(); i != (g[u]).end(); ++i)
      if (i->back->flow < i->back->cap && h[i->v] > h[u] + 1) {
        h[i->v] = h[u] + 1;
        q.push(i->v);
      }
  }
}
int compute_flow() {
  queue<int> q;
  for (int i = 0; i < (n); ++i) {
    for (__typeof((g[i]).begin()) j = (g[i]).begin(); j != (g[i]).end(); ++j) {
      j->flow = 0;
      j->back = &g[j->v][j->back_ind];
    }
    cur[i] = g[i].begin();
    h[i] = e[i] = 0;
  }
  for (__typeof((g[s]).begin()) i = (g[s]).begin(); i != (g[s]).end(); ++i) {
    i->flow = i->cap;
    i->back->flow = -i->flow;
    if (e[i->v] == 0 && i->v != t) q.push(i->v);
    e[i->v] += i->flow;
  }
  h[s] = n;
  int relabel_counter = 0;
  for (; !q.empty(); q.pop()) {
    int u = q.front();
    while (e[u] > 0) {
      if (cur[u] == g[u].end()) {
        relabel_counter++;
        h[u] = 2 * n + 1;
        for (__typeof((g[u]).begin()) i = (g[u]).begin(); i != (g[u]).end();
             ++i)
          if (i->flow < i->cap) h[u] = min(h[u], 1 + h[i->v]);
        cur[u] = g[u].begin();
        continue;
      }
      if (cur[u]->flow < cur[u]->cap && h[u] == h[cur[u]->v] + 1) {
        int d = min(e[u], cur[u]->cap - cur[u]->flow);
        cur[u]->flow += d;
        cur[u]->back->flow -= d;
        e[u] -= d;
        e[cur[u]->v] += d;
        if (e[cur[u]->v] == d && cur[u]->v != t && cur[u]->v != s)
          q.push(cur[u]->v);
      } else
        cur[u]++;
    }
    if (relabel_counter >= n) {
      for (int i = 0; i < (n); ++i) h[i] = 2 * n + 1;
      bfs(t, 0);
      bfs(s, n);
      relabel_counter = 0;
    }
  }
  return e[t];
}
void add_edge(int a, int b, int c, int c_back = 0) {
  assert(a != b);
  g[a].push_back(Edge(b, c));
  g[b].push_back(Edge(a, c_back));
