  if (cnt[1] == 1) {
    if (cnt[2] != (1 << (n - 1)) - 2) return 0;
    for (int i = 1; i <= (1 << n) - 2; ++i)
      if (nchild[i] == 1) {
        return i;
      }
    return 0;
  } else {
    if (cnt[2] != (1 << (n - 1)) - 3) return 0;
  }
  for (int i = 1; i <= (1 << n) - 2; ++i)
    if (nchild[i] == 3) {
      vector<int> x;
      for (int j : adj[i]) {
        if (d[j] > d[i]) {
          x.push_back(ndec[j]);
        }
      }
      sort(x.begin(), x.end());
      if (x[0] * 2 + 2 == x[2] && x[1] * 2 + 2 == x[2]) {
        return i;
      }
