  a = find_set(a);
  b = find_set(b);
  if (a != b) {
    if (rak[a] < rak[b]) swap(a, b);
    parent[b] = a;
    rak[a] += rak[b];
    return (rak[a] - rak[b]) * (rak[b]);
  }
  return 0;
}
struct hash_pair {
  template <class T1, class T2>
  size_t operator()(const pair<T1, T2> &p) const {
    auto hash1 = hash<T1>{}(p.first);
    auto hash2 = hash<T2>{}(p.second);
    return hash1 ^ hash2;
  }
};
long long bpow(long long a, long long b, long long m) {
  a %= m;
  long long res = 1;
  while (b > 0) {
    if (b & 1) res = res * a % m;
    a = a * a % m;
    b >>= 1;
  }
  return res;
}
long long int extend_gcd(long long int a, long long int b, long long int &x,
                         long long int &y) {
  if (b == 0) {
    x = 1;
    y = 0;
    return a;
  }
  long long int x1, y1;
  long long int ans = extend_gcd(b, a % b, x1, y1);
  x = y1;
  y = x1 - (a / b) * y1;
  return ans;
}
long long int inverse(long long int a, long long int m) {
  long long int x, y;
  extend_gcd(m, a, x, y);
  y %= m;
  y += m;
  y %= m;
  return y;
}
unsigned long long fhash(vector<long long int> p, long long int len) {
  unsigned long long h = 0xcbf29ce484222325ULL;
  for (long long int i = 0; i < len; i++) h = (h ^ p[i]) * 0x100000001b3ULL;
  return h;
}
