long long int phi(long long int a) {
  long long int ans = a;
  for (int i = 2; i * i <= a; i++) {
    if (a % i == 0) {
      while (a % i == 0) a /= i;
      ans -= ans / i;
    }
  }
  if (a > 1) ans -= ans / a;
  return ans;
}
long long int bow(long long a, long long b, long long m) {
  long long res = 1;
  while (b > 0) {
    if (b & 1)
      if (a >= m) return 1;
    res = res * a;
    if (res >= m) return 1;
    a = a * a;
    b >>= 1;
  }
  return 0;
}
vector<long long int> v;
long long int sg(long long int l, long long int r, long long int g) {
  if (l > r || g >= (long long int)m.size()) return 1;
  p = sg(l + 1, r, g + 1);
  q = m[g];
  return q * bow(v[l - 1], p, q) + bpow(v[l - 1], p, q);
}
