inline bool IsIn(int y,int x,int h,int w){
	return 0<=y&&y<h&&0<=x&&x<w;
}

void BFS(vector<vector<int> > &f,vector<vector<int> > &l,int sy,int sx,int h,int w){
	vector<vector<int> > done(h,vector<int>(w));
	vector<vector<int> > done_(h,vector<int>(w));
	l[sy][sx]=1;
	done[sy][sx]=done_[sy][sx]=1;
	queue<Pi> que;
	REP(i,0,4){
		int ny=sy+dy[i],nx=sx+dx[i];
		if(!IsIn(ny,nx,h,w)) continue;
		done_[ny][nx]=1;
		que.push(Pi(ny,nx));
	}
	while(!que.empty()){
		Pi p=que.front();
		que.pop();
		done[p.F_][p.S_]=1;
		bool flag=true;
		int tmp=INF;
		REP(i,0,4){
			int ny=p.F_+dy[i],nx=p.S_+dx[i];
			if(!IsIn(ny,nx,h,w)) continue;
			if(done[ny][nx]==1) tmp=min(tmp,l[ny][nx]);
			if(done[ny][nx]==1&&l[ny][nx]>=f[p.F_][p.S_]) flag=false;
			if(done_[ny][nx]!=1){
				done_[ny][nx]=1;
				que.push(Pi(ny,nx));
			}
		}
		if(flag) l[p.F_][p.S_]=f[p.F_][p.S_];
		else {
			if(tmp!=INF) l[p.F_][p.S_]=max(tmp,f[p.F_][p.S_]);
			else l[p.F_][p.S_]=f[p.F_][p.S_];
		}
	}
}

