void Djikstra(vector<vector<int> > &f,vector<vector<int> > &l,int sy,int sx,int h,int w){
	priority_queue<PP,vector<PP>,greater<PP> > que;
	REP(y,0,h) fill(l[y].begin(),l[y].end(),INF);
	l[sy][sx]=1;
	que.push(PP(1,Pi(sy,sx)));
	while(!que.empty()){
		PP p=que.top(); que.pop();
		Pi v=p.S_;
		if(l[v.F_][v.S_]<p.F_) continue;
		REP(i,0,4){
			int ny=v.F_+dy[i],nx=v.S_+dx[i];
			if(!IsIn(ny,nx,h,w)) continue;
			if(l[ny][nx]>max(f[ny][nx],l[v.F_][v.S_])){
				l[ny][nx]=max(f[ny][nx],l[v.F_][v.S_]);
				que.push(PP(l[ny][nx],Pi(ny,nx)));
			}
		}
	}
}

