  for (int v : a) {
    f1[x + v] = 1;
    f2[x - v] = 1;
  }
  vector<long long> res = fft.multiply(f1, f2);
  vector<int> difs;
  for (int i = 2 * x + 1; i < res.size(); i++)
    if (res[i]) difs.push_back(i - 2 * x);
  for (int &v : difs) v = 2 * (v + y);
