  long double a = fvx * fvx + fvy * fvy - v * v;
  long double b = 2 * fvx * px + 2 * fvy * py;
  long double c = px * px + py * py;
  if ((abs((a) - (0)) < EPS)) {
    if ((abs((b) - (0)) < EPS))
      return (abs((c) - (0)) < EPS) ? 0 : -1;
    else
      return (-c / b < -EPS) ? -1 : -c / b;
  } else {
    long double d = b * b - 4 * a * c;
    if (d < -EPS) return -1;
    if ((abs((d) - (0)) < EPS)) return (-b / 2 / a < -EPS) ? -1 : -b / 2 / a;
    long double t1 = (-b - sqrt(d)) / 2 / a, t2 = (-b + sqrt(d)) / 2 / a;
    if (t1 < -EPS) return (t2 < -EPS) ? -1 : t2;
    return t1;
  }
}
int main() {
  int n, m;
  while (scanf("%d%d", &n, &m), n) {
    vector<long double> dx(n), dy(n), v(n);
    for (int i = 0; i < (int)(n); i++)
      scanf("%Lf%Lf%Lf", &dx[i], &dy[i], &v[i]);
