      long double minT = 1e10, minID = -1;
      vector<long double> t(n);
      for (int i = 0; i < (int)(n); i++) {
        t[i] = getTime(dx[i], dy[i], v[i], fpx, fpy, fvx, fvy);
        if (t[i] > -EPS && minT > t[i] + EPS) {
          minT = t[i];
          minID = i;
        }
      }
      cnt[minID]++;
      for (int i = 0; i < (int)(n); i++) {
        if (t[i] > -EPS) {
          dx[i] += v[i] * minT;
