    yr[100009], ds[509][509];
vector<vector<edge> > g;
void add_edge(int v1, int v2, long long c) { g[v1].push_back(edge{v2, c}); }
void add_edge2(int v1, int v2, long long c) {
  add_edge(v1, v2, c);
  add_edge(v2, v1, c);
}
long long shortest_path(int start, int goal) {
  vector<long long> dist(g.size(), 1LL << 60);
  dist[start] = 0;
  priority_queue<state> que;
  que.push(state{start, 0});
  while (!que.empty()) {
    int u = que.top().pos;
    que.pop();
    for (edge e : g[u]) {
      long long nd = dist[u] + e.cost;
      if (dist[e.to] > nd) {
        dist[e.to] = nd;
        que.push(state{e.to, e.cost});
      }
    }
  }
  return dist[goal];
}
