        add_edge2(i * W + j, i * W + j - 1, C);
        add_edge2(H * W + i * W + j, H * W + i * W + j - 1, A);
      }
      if (i >= 1) {
        add_edge2(i * W + j, i * W + j - W, C);
        add_edge2(2 * H * W + i * W + j, 2 * H * W + i * W + j - W, A);
      }
      add_edge(i * W + j, H * W + i * W + j, B);
      add_edge(i * W + j, 2 * H * W + i * W + j, B);
      ds[i][j] = -1;
    }
