public class KFactorization {
	public KFactorization(Scanner scan, BufferedReader br, PrintWriter out) {
		int n = scan.nextInt(), k = scan.nextInt();
		List<Integer> factors = prime_f(n);
		if(factors.size() < k) {
			System.out.println(-1);
			return;
		}
		while(k --> 1) {
			out.print(factors.remove(0) + " ");
		}
		int last = 1;
		for(int i = 0 ; i < factors.size() ; i++)
			last = last*factors.get(i);
		out.println(last);
	}
	List<Integer> prime_f(int n) {
		List<Integer> factors = new ArrayList<>();
		for(int i = 2 ; i < Math.sqrt(n) ; i++)
			while(n%i == 0) {
				n/=i;
				factors.add(i);
			}
		if(n != 1)
			factors.add(n);
		return factors;
	}
	public static void main(String[] args) {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);
		Scanner scan = new Scanner(System.in);
		new KFactorization(scan, br, out);
		out.close();
	}
}

