class BinaryIndexedTree(object):
    def __init__(self, list_a):
        self.list_a = [0] * len(list_a)
        self.list_c = [0] * len(list_a)
        self.length = len(list_a)
        for i in range(self.length):
            self.update(i, list_a[i])

    def lowbit(self, i):
        return i & -i

    def update(self, pos, val):
        self.list_a[pos] = self.list_a[pos] + val
        while pos < len(self.list_a):
            self.list_c[pos] = self.list_c[pos] + val
            pos = pos + self.lowbit(pos + 1)

    def query(self, pos):
        sum = 0
        while pos >= 0:
            sum = sum + self.list_c[pos]
            pos = pos - self.lowbit(pos + 1)
        return sum

