point p[N];
bool jud(point t) {
  int l = 0, r = n - 1, cnt = 0;
  while (l <= r) {
    if (p[l] + p[r] == t)
      l++, r--;
    else if (p[l] + p[r] < t)
      l++, cnt++;
    else
      r--, cnt++;
    if (cnt > k) return 0;
  }
  return 1;
}
