long long findsg(int x, int k) {
  if (x < k) return 0;
  if (x % k == 0) return x / k;
  if (k >= 100000) {
    long long op = x - k * (x / k);
    long long oq = op % (x / k + 1);
    x = k * (x / k) + oq - (x / k) - 1;
    return findsg(x, k);
  } else
    return findsg(x - x / k - 1, k);
}
