template <class T>
struct RangeFenwick {
  static const int maxn = 5e5 + 5;
  int n;
  T fen0[maxn];
  long long fen1[maxn];
  RangeFenwick(int n) { this->n = n; }
  inline void upd(int p, T val) {
    p++;
    assert(p > 0);
    for (int pp = p; pp <= n; pp += pp & -pp) {
      fen0[pp] += val;
      fen1[pp] += val * p;
    }
  }
  void upd(int l, int r, T val) { upd(l, +val), upd(r + 1, -val); }
  inline long long query(int p) {
    p++;
    assert(p <= n);
    long long res = 0;
    for (int pp = p; pp > 0; pp -= pp & -pp) {
      res += (long long)fen0[pp] * (p + 1);
      res -= fen1[pp];
    }
    return res;
  }
};
const int maxn = 5e5 + 5;
