    } else {
      rt = i;
    }
  }
  firstdfs(rt, -1), dfs(rt, rt, -1);
  vector<pair<int, int> > v;
  for (int i = (0); i < (n); i++) v.push_back(make_pair(lev[i], i));
  sort((v).begin(), (v).end(), greater<pair<int, int> >());
  int ptr = 0;
  for (int i = (0); i < (n); i++) {
    while (ptr < n && v[ptr].first > v[i].first) {
      int u = v[ptr].second;
      upd(rt, u, -1);
      ptr++;
    }
    int u = v[i].second;
    ans[u] += query(rt, u) - lev[u] - 1;
  }
  for (int i = (0); i < (n); i++) printf("%I64d%c", ans[i], " \n"[i == n - 1]);
