  return PT(((P.x - O.x) * Y.y - (P.y - O.y) * Y.x) / (X.x * Y.y - X.y * Y.x),
            ((P.x - O.x) * X.y - (P.y - O.y) * X.x) / (X.y * Y.x - X.x * Y.y));
}
