  } else if (max(abs(bx - ax), abs(by - ay)) >= 4) {
    printf("Second\n");
    return 0;
  }
  int mx = min(ax, bx);
  int my = min(ay, by);
  ax -= mx;
  bx -= mx;
  ay -= my;
  by -= my;
  n = max(ax, bx) + 1;
  m = max(ay, by) + 1;
  memset(pd, -1, sizeof(pd));
  printf("%s\n", play(0, ax, ay, bx, by) ? "First" : "Second");
  return 0;
}

