import java.util.*;

public class beaver {
	static ArrayList<Integer>[] adj;
	static ArrayList<Integer> factors;
	static int n, m, k;
	static int[] nim;

	public static int dfs(int idx) {
		if (adj[idx].size() == 0) return nim[idx] = 0;
		else if (nim[idx] != -1) return nim[idx];

		HashSet<Integer> children = new HashSet<>();
		for (int child : adj[idx]) {
			int div = factors.get(idx) / factors.get(child);

			if ((div&1) == 1) children.add(dfs(child));
			else children.add(0);
		}

		nim[idx] = 0;
		while (children.contains(nim[idx])) nim[idx]++;

		return nim[idx];
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		n = sc.nextInt(); m = sc.nextInt(); k = sc.nextInt();

		if ((n&1) == 0) {
			System.out.println("Marsel");
			System.exit(0);
		}

		factors = new ArrayList<>();

		for (int i=1; i*i<=m; i++) {
			if (m%i != 0) continue;

			if (i >= k) factors.add(i);
			if (m/i != i && m/i >= k) factors.add(m/i);
		}

		int n = factors.size();

		if (n == 0) {
			System.out.println(k == 1 ? "Timur" : "Marsel");
			System.exit(0);
		}

		Collections.sort(factors);
		adj = new ArrayList[n];

		for (int i=0; i<n; i++) adj[i] = new ArrayList<>();

		for (int i=0; i<n; i++)
			for (int j=i+1; j<n; j++)
				if (factors.get(j) % factors.get(i) == 0)
					adj[j].add(i);

		nim = new int[n];
		Arrays.fill(nim, -1);

		System.out.println(dfs(n-1) == 0 ? "Marsel" : "Timur");
	}
}

