long long OFFSET = 11000;
bool mem[101][25001];
bool flag = false;
void Calculus(long long left, long long num) {
  if (flag) return;
  long long i;
  long long answer;
  if (left == 0) {
    if (num <= l && num >= 1) {
      flag = true;
      aL++;
      ans[aL] = num;
      return;
    } else {
      mem[left][num + OFFSET] = true;
      return;
    }
  }
  for (i = 1; i <= l; i++) {
    if (!mem[left - 1][i - num + OFFSET]) {
      aL++;
      ans[aL] = i;
      Calculus(left - 1, i - num);
      if (flag) return;
      aL--;
    }
  }
  mem[left][num + OFFSET] = true;
}
