		for(int i=1;i<=n;i++)
			if(a[i]!=a[i-1])
				freq.add(1);
			else
				freq.set(freq.size()-1,freq.get(freq.size()-1)+1);
		Collections.sort(freq);
		int ans=0;
		for(int i=0;i<freq.size();i++)
			for(int j=1;j<=freq.get(i);j++)
			{
				int curr=j;
				int pos=i;
				int cnt=j;
				while(true)
				{
					int next=bin_search(2*curr,freq,pos+1,freq.size()-1);
					if(next>=freq.size())
						break;
					curr*=2;
					cnt+=curr;
					pos=next;
				}
				ans=Math.max(ans,cnt);
			}
		out.println(ans);
	}
	int bin_search(int x,ArrayList<Integer> list,int low,int high)
	{
		int ret=high+1;
		while(low<=high)
		{
			int mid=(low+high)/2;
			if(list.get(mid)>=x)
			{
				ret=mid;
				high=mid-1;
			}
			else
				low=mid+1;
		}
		return ret;
	}


