#include <bits/stdc++.h>
using namespace std;
const int LimitOfGridNumber = 300, NumberOfFaces = 6, MaxTurn = 3000;
enum EAction {
  Right = 1,
  Stay = 0,
  Left = -1,
};
typedef struct {
  int dice;
  EAction direction;
} memo_t;
typedef struct {
  bool dice[NumberOfFaces + 1][2];
} check_t;
int move(int _position, int _a_dice, EAction _eaction, const int _N[]) {
  int pos = _position + _a_dice * _eaction;
  return pos += _N[pos];
}
EAction chooseAction(int _position, int _M, int _g, int _a_dice,
                     const int _N[]) {
  EAction eaction = Stay;
  int left_case = _position;
  int right_case = _position;
  if (_position + Left * _a_dice >= 1) {
    left_case = move(_position, _a_dice, Left, _N);
  }
  if (_position + Right * _a_dice <= _M) {
    right_case = move(_position, _a_dice, Right, _N);
  }
  int abs_l = abs(left_case - _g);
  int abs_r = abs(right_case - _g);
  int abs_s = abs(_position - _g);
  if (abs_l < abs_r && abs_l < abs_s)
    eaction = Left;
  else if (abs_r < abs_s)
    eaction = Right;
  else
    eaction = Stay;
  return eaction;
}
bool isConnected(int _position, int _f, int _lr, const int _a[],
                 check_t _is_checked[], const int _N[], int _M,
                 vector<memo_t> &_route, int _s) {
  if (_is_checked[_position].dice[_f][_lr]) return false;
  _is_checked[_position].dice[_f][_lr] = true;
  EAction direction;
  if (_lr == 0)
    direction = Right;
  else
    direction = Left;
  _position -= _a[_f] * direction;
  if (_position < 1 || _position > _M) return false;
  if (_route.size() >= MaxTurn) return false;
  memo_t tmp;
  tmp.dice = _f;
  tmp.direction = direction;
  _route.push_back(tmp);
  if (_position == _s) return true;
  for (int m = 1; m <= _M; m++) {
    if (_position - m == _N[m]) {
      for (int f = 1; f <= NumberOfFaces; f++) {
        for (int lr = 0; lr < 2; lr++) {
          if (isConnected(m, f, lr, _a, _is_checked, _N, _M, _route, _s))
            return true;
        }
      }
    }
  }
  _route.pop_back();
  return false;
}
void FindRoute(int _M, const int _a[], int _s, int _g, const int _N[],
               vector<memo_t> &_route) {
  check_t is_checked[LimitOfGridNumber + 1];
  for (int m = 1; m <= _M; m++) {
    for (int f = 1; f <= NumberOfFaces; f++) {
      for (int lr = 0; lr < 2; lr++) {
        is_checked[m].dice[f][lr] = false;
      }
    }
  }
  int position = _g;
  for (int f = 1; f <= NumberOfFaces; f++) {
    for (int lr = 0; lr < 2; lr++) {
      if (isConnected(position, f, lr, _a, is_checked, _N, _M, _route, _s))
        return;
    }
  }
  for (int m = 1; m <= _M; m++) {
    if (position - m == _N[m]) {
      for (int f = 1; f <= NumberOfFaces; f++) {
        for (int lr = 0; lr < 2; lr++) {
          if (isConnected(m, f, lr, _a, is_checked, _N, _M, _route, _s)) return;
        }
      }
    }
  }
}
int main() {
  int M, a[NumberOfFaces + 1], s, g, N[LimitOfGridNumber + 1];
  cin >> M;
  for (int f = 1; f <= NumberOfFaces; f++) cin >> a[f];
  cin >> s >> g;
  for (int m = 1; m <= M; m++) cin >> N[m];
  vector<memo_t> route;
  FindRoute(M, a, s, g, N, route);
  int clear_turn = route.size();
  int position = s;
