public class B {
    class Node {
        Node l;
        Node r;
        Node pl;
        Node pr;
        //        double gl;
//        double gr;
        double val = 0;
    }

    class Tree {
        Node root;
        int filled = 0;

        void build() {
            root = new Node();
//            root.gl = 1/2;
//            root.gr = 1/2;
            ArrayList<Node> lvl = new ArrayList<>();
            ArrayList<Node> nextlvl = new ArrayList<>();
            lvl.add(root);
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < lvl.size(); j++) {
                    Node n = lvl.get(j);
                    if (j != 0){
                        n.l = lvl.get(j - 1).r;
                    }else {
                        n.l = new Node();
                        nextlvl.add(n.l);
                    }
                    n.r = new Node();
                    nextlvl.add(n.r);
                }
//                for (Node n : lvl) {
//                    n.l = new Node();
//                    nextlvl.add(n.l);
//                    n.l = new Node();
//                    nextlvl.add(n.r);
//                }
                lvl = (ArrayList<Node>)nextlvl.clone();
                nextlvl.clear();
            }
        }

        void tick() {
            add(root, 1);
        }

        void add(Node n, double v) {
            if (n == null) {
                return;
            }
            n.val += v;
            if (n.val > 1) {
                add(n.r, (n.val - 1) / 2);
                add(n.l, (n.val - 1) / 2);
                n.val = 1;
            }
        }

        int countFilled(){
            ArrayList<Node> lvl = new ArrayList<>();
            ArrayList<Node> nextlvl = new ArrayList<>();
            lvl.add(root);
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < lvl.size(); j++) {
                    Node n = lvl.get(j);
                    if (n.val == 1)
                        filled++;
                    if (j == 0){
                        nextlvl.add(n.l);
                    }
                    nextlvl.add(n.r);
                }
                lvl = (ArrayList<Node>)nextlvl.clone();
                nextlvl.clear();
            }
            return filled;
        }
    }

    void solve() {
        int n = in.nextInt();
        int t = in.nextInt();
        Tree tree = new Tree();
        tree.build();
        for (int i = 0; i < t; i++) {
            tree.tick();
        }
        out.print(tree.countFilled());
    }

    FastScanner in;
    PrintWriter out;

    void run() {
        try {
            in = new FastScanner(new File("B.in"));
            out = new PrintWriter(new File("B.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
