class TaskF {

    boolean[] u;
    int[] x;
    int[] y;
    Integer[] order;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int k = in.nextInt();
        u = new boolean[n];
        x = new int[n];
        y = new int[n];
        order = new Integer[n];

        for (int i = 0; i < n; ++i) {
            x[i] = in.nextInt() * 2;
            y[i] = in.nextInt() * 2;
            order[i] = i;
        }

        if (n <= k) {
            out.println(-1);
            return;
        }
        if (n == 1) {
            out.println(1);
            out.println((x[0] / 2) + " " + (y[0] / 2));
            return;
        }

        HashSet<Point> res = new HashSet<Point>();
        Arrays.sort(order, new Comparator<Integer>() {
            public int compare(Integer o1, Integer o2) {
                if (x[o1] != x[o2]) return x[o1] - x[o2];
                return y[o1] - y[o2];
            }
        });

        for (int i = 0; i <= k; ++i) {
            for (int j = n - 1, c = 0; c <= k; --j, ++c) {
                if (i < n && j >= 0) {
                    if (check(i, j, k)) {
                        res.add(new Point((x[order[i]] + x[order[j]]) / 2, (y[order[i]] + y[order[j]]) / 2));
                    }
                }
            }
        }
        out.println(res.size());
        for (Point p : res) {
            int x = p.x;
            int y = p.y;
            out2(out, x);
            out.print(" ");
            out2(out, y);
            out.println();
        }
    }

    private void out2(PrintWriter out, int x) {
        if (x < 0) {
            out.print("-");
            x = -x;
        }
        out.print(x / 2);
        if (BitUtils.checkBit(x, 0)) {
            out.print(".5");
        }
    }

    private boolean check(int id1, int id2, int k) {
        int ptr2 = x.length - 1;
        Arrays.fill(u, false);
        int skip = x.length;
        boolean hasCenter = false;
        id1 = order[id1];
        id2 = order[id2];
        int midX = (x[id1] + x[id2]) >> 1;
        int midY = (y[id1] + y[id2]) >> 1;

        for (int i = 0; i < x.length; ++i) {
            int id = order[i];

            if (!u[id]) {
                if (!hasCenter && x[id] == midX && y[id] == midY) {
                    hasCenter = true;
                    u[id] = true;
                    --skip;
                    continue;
                }
                int needX = 2 * midX - x[id];
                int needY = 2 * midY - y[id];
                while (ptr2 >= 0) {
                    int i2 = order[ptr2];
                    if (x[i2] == needX && y[i2] == needY) {
                        u[i] = true;
                        u[ptr2] = true;
                        --skip;
                        --skip;
                        --ptr2;
                        break;
                    }
                    if (x[i2] > needX || (x[i2] == needX && y[i2] > needY)) {
                        --ptr2;
                    } else {
                        break;
                    }
                }
            }
        }
        return skip <= k;
    }

    class Point {
        int x, y;

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Point point = (Point) o;

            if (x != point.x) return false;
            if (y != point.y) return false;

            return true;
        }

        public int hashCode() {
            int result = x;
            result = 31 * result + y;
            return result;
        }

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

    }
}

