long long fun(long long idx, long long num) {
  if (dp[idx][num] != -1) return dp[idx][num];
  if (num == n + 1) {
    if (idx == 0)
      return dp[idx][num] = 0;
    else
      return dp[idx][num] = v[idx];
  }
  if (idx == 0) {
    if (num == n) {
      return dp[idx][num] = v[num];
    } else if (num == n - 1) {
      return dp[idx][num] = max(v[n - 1], v[n]);
    } else {
      long long c1 = max(v[num], v[num + 1]) + fun(idx, num + 2);
      long long c2 = max(v[num], v[num + 2]) + fun(num + 1, num + 3);
      long long c3 = max(v[num + 1], v[num + 2]) + fun(num, num + 3);
      dp[idx][num] = min({c1, c2, c3});
    }
  } else {
    if (num == n) {
      return dp[idx][num] = max(v[num], v[idx]);
    } else {
      long long c1 = max(v[idx], v[num]) + fun(0, num + 1);
      long long c2 = max(v[idx], v[num + 1]) + fun(num, num + 2);
      long long c3 = max(v[num], v[num + 1]) + fun(idx, num + 2);
      dp[idx][num] = min({c1, c2, c3});
    }
  }
  return dp[idx][num];
}
void findOrder(long long idx, long long num) {
  if (idx == 0) {
    if (num > n) {
