      long long c2 = max(v[num], v[num + 2]) + dp[num + 1][num + 3];
      long long c3 = max(v[num + 1], v[num + 2]) + dp[num][num + 3];
      if (dp[idx][num] == c1) {
        ans.push_back(num);
        ans.push_back(num + 1);
        findOrder(0, num + 2);
        return;
      }
      if (dp[idx][num] == c2) {
        ans.push_back(num);
        ans.push_back(num + 2);
        findOrder(num + 1, num + 3);
        return;
      }
      if (dp[idx][num] == c3) {
        ans.push_back(num + 1);
        ans.push_back(num + 2);
        findOrder(num, num + 3);
        return;
      }
    }
  } else {
    if (num > n) {
