long long mul_mod(long long a, long long b, long long m) {
  long long ans = 0;
  a %= m;
  b %= m;
  while (b) {
    if (b & 1ll) {
      ans = ans + a;
      if (ans >= m) ans -= m;
    }
    a <<= 1;
    if (a >= m) a -= m;
    b >>= 1;
  }
  return ans;
}
long long pow_mod(long long a, long long n, long long m) {
  long long ans = 1;
  while (n) {
    if (n & 1) {
      ans = mul_mod(ans, a, m);
    }
    n >>= 1;
    a = mul_mod(a, a, m);
  }
  return ans;
}
