int n, q, im[300005], it[300005 << 2], a[300005];
vector<int> t[300005 << 2];
void Build(int l, int r, int id) {
  if (l == r) {
    t[id].push_back(im[l]);
    return;
  }
  int mid = (l + r) >> 1;
  Build(l, mid, 2 * id);
  Build(mid + 1, r, 2 * id + 1);
  t[id].resize(r - l + 1);
  merge(t[2 * id].begin(), t[2 * id].end(), t[2 * id + 1].begin(),
        t[2 * id + 1].end(), t[id].begin());
}
int Get(int l, int r, int id, int u, int v) {
  if (l > v || r < u) return 0;
  if (u <= l && r <= v) {
    return upper_bound(t[id].begin(), t[id].end(), v) -
           lower_bound(t[id].begin(), t[id].end(), u);
  }
  int mid = (l + r) >> 1;
  return Get(l, mid, 2 * id, u, v) + Get(mid + 1, r, 2 * id + 1, u, v);
}
void Updateit(int l, int r, int id, int x) {
  ++it[id];
  if (l == r) return;
  int mid = (l + r) >> 1;
  if (x <= mid)
    Updateit(l, mid, 2 * id, x);
  else
    Updateit(mid + 1, r, 2 * id + 1, x);
}
int Getit(int l, int r, int id, int u, int v) {
  if (l > v || r < u) return 0;
  if (u <= l && r <= v) return it[id];
  int mid = (l + r) >> 1;
  return Getit(l, mid, 2 * id, u, v) + Getit(mid + 1, r, 2 * id + 1, u, v);
}
