  point &operator+=(const point &a) {
    x += a.x;
    y += a.y;
    return *this;
  }
  point operator-(const point &a) const { return point(x - a.x, y - a.y); }
  point &operator-=(const point &a) {
    x -= a.x;
    y -= a.y;
    return *this;
  }
