enum { CCW = 1, CW = -1, ON = 0 };
template <class T>
int ccw(const point<T> &a, point<T> b, point<T> c) {
  b -= a;
  c -= a;
  double rdir = cross(b, c);
  double len = abs(b) * abs(c);
  if (rdir > EPS * len) return CCW;
  if (rdir < -EPS * len) return CW;
  return ON;
}
