  if (max(S1.a.x, S1.b.x) + EPS < min(S2.a.x, S2.b.x) ||
      max(S1.a.y, S1.b.y) + EPS < min(S2.a.y, S2.b.y) ||
      max(S2.a.x, S2.b.x) + EPS < min(S1.a.x, S1.b.x) ||
      max(S2.a.y, S2.b.y) + EPS < min(S1.a.y, S1.b.y))
    return false;
  return ccw(S1.a, S1.b, S2.a) * ccw(S1.a, S1.b, S2.b) <= 0 &&
         ccw(S2.a, S2.b, S1.a) * ccw(S2.a, S2.b, S1.b) <= 0;
}
double dist2(const segment<double> &segment<double>, const point<double> &p) {
  if (dot(segment<double>.b - segment<double>.a, p - segment<double>.a) <= 0)
    return dist2(p, segment<double>.a);
  if (dot(segment<double>.a - segment<double>.b, p - segment<double>.b) <= 0)
    return dist2(p, segment<double>.b);
  return (double)SQ(cross(segment<double>.b - segment<double>.a,
                          p - segment<double>.a)) /
         dist2(segment<double>.a, segment<double>.b);
}
double dist(const segment<double> &segment<double>, const point<double> &p) {
  return sqrt(dist2(segment<double>, p));
}
double dist(const segment<double> &S1, const segment<double> &S2) {
  if (intersected(S1, S2)) return 0;
  return sqrt(min(min(dist2(S1, S2.a), dist2(S1, S2.b)),
                  min(dist2(S2, S1.a), dist2(S2, S1.b))));
}
double dist(const line<double> &line<double>, const point<double> &p) {
  return sqrt(
      (double)SQ(cross(line<double>.b - line<double>.a, p - line<double>.a)) /
      dist2(line<double>.a, line<double>.b));
}
double geodist(point<double> a, point<double> b, const circle<double> &c) {
  double r = c.r;
  segment<double> s(a, b);
  if (dist(s, c.c) > r) return abs(a - b);
  a -= c.c;
  b -= c.c;
  double L1 = abs(a);
  double t1 = arg(a) + acos(r / L1);
  if (t1 < 0) t1 += 2 * PI;
  double t2 = arg(a) - acos(r / L1);
  if (t2 < 0) t2 += 2 * PI;
  double L2 = abs(b);
  double t3 = arg(b) + acos(r / L2);
  if (t3 < 0) t3 += 2 * PI;
  double t4 = arg(b) - acos(r / L2);
  if (t4 < 0) t4 += 2 * PI;
  double theta = 2 * PI;
  theta = min(theta, min(abs(t1 - t4), 2 * PI - abs(t1 - t4)));
  theta = min(theta, min(abs(t2 - t3), 2 * PI - abs(t2 - t3)));
  return sqrt(L1 * L1 - r * r) + sqrt(L2 * L2 - r * r) + r * theta;
}
double area(const vector<point<double> > &v) {
  double ans = 0;
  for (int i = 2; i < (int)v.size(); i++) {
    ans += cross(v[i - 1] - v[0], v[i] - v[0]);
  }
  return abs(ans) / 2;
}
double area(const point<double> &a, const point<double> &b,
            const point<double> &c) {
  return abs(cross(b - a, c - a)) / 2;
}
vector<point<double> > convex_hull(vector<point<double> > &ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  vector<point<double> > ch(2 * n);
  for (int i = 0; i < n; ch[k++] = ps[i++])
    while (k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
  for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--])
    while (k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
  ch.resize(k - 1);
  return ch;
}
bool cover(const point<double> &a, const point<double> &b,
           const point<double> &c, const point<double> &p) {
  return area(a, b, c) + EPS >= area(a, b, p) + area(a, c, p) + area(b, c, p);
}
int intersect(const circle<double> &p, const circle<double> &q,
              point<double> *w = NULL, point<double> *z = NULL) {
  point<double> a = q.c - p.c;
  point<double> b(a.y, -a.x);
  double c = abs(a);
  if (c > p.r + q.r) return 0;
  b = b / c;
  double s = (p.r + q.r + c) / 2;
  double men = sqrt(s * (s - p.r) * (s - q.r) * (s - c));
  double l = 2 * men / c;
  double lp = sqrt(SQ(p.r) - SQ(l));
  a = a / c * lp;
  if (SQ(q.r) - SQ(p.r) - SQ(c) > 0) {
    a *= -1;
  }
  b = b * l;
  if (abs2(b) < EPS) {
    if (w && z) *w = *z = p.c + a;
    return 1;
  } else {
    if (w && z) *w = p.c + a + b, *z = p.c + a - b;
    return 2;
  }
}
inline void calc_abc(const line<double> &l, double &a, double &b, double &c) {
  a = l.a.y - l.b.y;
  b = l.b.x - l.a.x;
  c = l.a.x * l.b.y - l.b.x * l.a.y;
}
point<double> perp_foot(const point<double> &p, const line<double> &l) {
  double a, b, c;
  calc_abc(l, a, b, c);
  return p - point<double>(a, b) * ((a * p.x + b * p.y + c) / (a * a + b * b));
}
int intersect(const circle<double> &c, const line<double> &l,
              point<double> *p = NULL, point<double> *q = NULL) {
  point<double> m = perp_foot(c.c, l);
  double d2 = abs2(c.c - m);
  if (c.r * c.r + EPS < d2)
    return 0;
  else if (abs(c.r * c.r - d2) < EPS) {
    if (p && q) *p = *q = m;
    return 1;
  } else {
    if (p && q) {
      point<double> v;
      double n0 = abs2(l.a - m), n1 = abs2(l.b - m);
      if (n0 < n1)
        v = l.b - m, n0 = n1;
      else
        v = l.a - m;
      v *= sqrt((c.r * c.r - d2) / n0);
      *p = m + v, *q = m - v;
    }
    return 2;
  }
}
int intersect(const circle<double> &c, const segment<double> &s,
              point<double> *p = NULL, point<double> *q = NULL) {
  point<double> pp, qq;
  int n = intersect(c, line<double>(s.a, s.b), &pp, &qq);
  if (n == 0)
    return 0;
  else if (n == 1) {
    if (dot(pp - s.a, pp - s.b) < EPS) {
      if (p && q) *p = *q = pp;
      return 1;
    }
    return 0;
  } else {
    bool bp = (dot(pp - s.a, pp - s.b) < EPS);
    bool bq = (dot(qq - s.a, qq - s.b) < EPS);
    if (bp && bq) {
      if (p && q) *p = pp, *q = qq;
      return 2;
    }
    if (bp || bq) {
      if (p && q) *p = (bp ? pp : qq);
      return 1;
    }
    return 0;
  }
}
point<double> intersect(const line<double> &L1, const line<double> &L2) {
  double a1 = cross(L1.b - L1.a, L2.b - L2.a);
  double a2 = cross(L1.b - L1.a, L1.b - L2.a);
  if (abs(a1) < EPS) return L1.a;
  return L2.a + (L2.b - L2.a) * (a2 / a1);
}
class CMP {
  circle<double> c;

 public:
  CMP(const circle<double> &c) : c(c) {}
  bool operator()(const point<double> &p, const point<double> &q) const {
    double parg = arg(p - c.c);
    double qarg = arg(q - c.c);
    return parg < qarg;
  }
};
int main() {
  int n;
  while (cin >> n, n) {
    vector<circle<double> > vc(n);
    for (int i = 0; i < (n); i++) cin >> vc[i].c >> vc[i].r;
    double ans = 0;
    for (int i = 0; i < (n); i++) {
      vector<point<double> > vp;
      for (int j = 0; j < (n); j++)
        if (i != j) {
          point<double> p, q;
          int a = intersect(vc[i], vc[j], &p, &q);
          if (a == 1)
            vp.push_back(p);
          else if (a == 2)
            vp.push_back(p), vp.push_back(q);
        }
      sort(vp.begin(), vp.end(), CMP(vc[i]));
      ans += 2 * PI * vc[i].r;
      for (int j = 0; j < (((int)(vp).size())); j++) {
        point<double> &p = vp[j], &q = vp[(j + 1) % ((int)(vp).size())];
        double parg = arg(p - vc[i].c);
        double qarg = arg(q - vc[i].c);
        double dist, md;
        if (qarg < parg)
          dist = (qarg - parg + 2 * PI);
        else
