        point<double> a(cos(md), sin(md));
        a = a * vc[i].r + vc[i].c;
        bool covered = false;
        for (int k = 0; k < (n); k++)
          if (i != k) {
            if (abs2(a - vc[k].c) < SQ(vc[k].r)) {
