#include <bits/stdc++.h>
using namespace std;
const int N = 111111;
long long sum[N << 2 | 1];
long long cov[N << 2];
vector<int> vec[N];
int ra[N], idx[N], id_nn, top[N], fa[N], bottom[N];
int make_tree(int u, int Fa, int Top) {
  idx[u] = ++id_nn;
  ra[id_nn] = u;
  fa[u] = Fa;
  top[u] = Top;
  for (int i = 0; i < vec[u].size(); i++) {
    int v = vec[u][i];
    if (v != Fa) {
      bottom[u] = make_tree(v, u, Top);
    }
  }
  if (vec[u].size() <= 1) {
    return bottom[u] = u;
  }
  return bottom[u];
}
void push_down(int l, int r, int rt) {
  if (cov[rt] != 0) {
    sum[rt << 1] += (r - l + 1 - (r - l + 1) / 2) * cov[rt];
    sum[rt << 1 | 1] += (r - l + 1) / 2 * cov[rt];
    cov[rt << 1] += cov[rt];
    cov[rt << 1 | 1] += cov[rt];
  }
}
void push_up(int rt) { sum[rt] = sum[rt << 1] + sum[rt << 1 | 1]; }
int ql, qr, val;
void update(int l, int r, int rt) {
  if (ql <= l && r <= qr) {
    sum[rt] += (r - l + 1) * val;
    cov[rt] += val;
    return;
  }
  push_down(l, r, rt);
  int mid = (l + r) >> 1;
  if (ql <= mid) update(l, mid, rt << 1);
  if (qr > mid) update(mid + 1, r, rt << 1 | 1);
  push_up(rt);
}
long long query(int l, int r, int rt) {
  push_down(l, r, rt);
  if (ql <= l && r <= qr) {
    return sum[rt];
  }
  long long ans = 0;
  int mid = (l + r) >> 1;
  if (ql <= mid) ans += query(l, mid, rt << 1);
  if (qr > mid) ans += query(mid + 1, r, rt << 1 | 1);
  push_up(rt);
  return ans;
}
void UPDATE_tree(int d) {
  ql = qr = 1;
  update(1, id_nn, 1);
  d--;
  if (d == 0) return;
  for (int i = 0; i < vec[1].size(); i++) {
    int v = vec[1][i];
    int idv = idx[v];
    int botv = idx[bottom[v]];
    botv = min(botv, idv + d - 1);
    ql = idv, qr = botv;
    if (ql <= qr) update(1, id_nn, 1);
  }
}
void UPDATE(int v, int x, int d) {
  val = x;
  if (v == 1) {
    UPDATE_tree(d + 1);
  } else {
    int idv = idx[v];
    int idtopv = idx[top[v]];
    int beggg, enddd;
    if (idv - idtopv < d) {
      int dd = d - (idv - idtopv);
      beggg = idtopv + dd - 1;
      UPDATE_tree(dd);
    } else {
      beggg = idv - d;
    }
    enddd = min(idv + d, idx[bottom[v]]);
    ql = beggg, qr = enddd;
    if (ql <= qr) update(1, id_nn, 1);
  }
}
long long QUERY(int u) {
  ql = qr = idx[u];
  long long ans = query(1, id_nn, 1);
  return ans;
}
int main() {
  int n, m;
  while (scanf("%d %d", &n, &m) != EOF) {
    for (int i = 1; i <= n; i++) vec[i].clear();
    for (int i = 1, u, v; i < n; i++) {
      scanf("%d %d", &u, &v);
      vec[u].push_back(v);
      vec[v].push_back(u);
    }
    id_nn = 0;
    ra[1] = idx[1] = ++id_nn;
    for (int i = 0; i < vec[1].size(); i++) {
      make_tree(vec[1][i], 1, vec[1][i]);
    }
    memset(sum, 0, sizeof(sum));
    memset(cov, 0, sizeof(cov));
    for (int u, v, x, d; m--;) {
      scanf("%d %d", &u, &v);
      if (u == 0) {
        scanf("%d %d", &x, &d);
        UPDATE(v, x, d);
      } else {
        cout << QUERY(v) << endl;
      }
    }
  }
  return 0;
}

