bool solve(int a, int b, string s) {
  int x = 0, y = 0, cur = 0;
  for (int i = 1; i < s.length(); i++) {
    if (s[i] == '.')
      cur++;
    else {
      if (cur >= 2 * b) {
        if (x) return 0;
        x = cur;
      } else if (cur >= b) {
        if (cur < a) return 0;
        y++;
      }
      cur = 0;
    }
  }
  if (!x) return y & 1;
  for (int i = 0; i < b; i++) {
    if (i + a > x) break;
    int r = x - i - a;
    if (r >= 2 * b || (r < a && r >= b)) continue;
    int s = (r >= b) + y;
    if (s & 1) continue;
    return 1;
  }
  return 0;
}
