public class PlayingWithSuperglue {

	static int[][][][][][] dp;

	public static void main(String[] args) throws IOException {
		Kattio io = new Kattio(System.in);
		int n = io.getInt();
		int m = io.getInt();
		int x1 = io.getInt();
		int y1 = io.getInt();
		int x2 = io.getInt();
		int y2 = io.getInt();
		dp = new int[n+1][m+1][2][2][2][2];
		for (int i = 0; i <= n; i++) {
			for (int j = 0; j <= m; j++) {
				for (int k = 0; k < 2; k++) {
					for (int k2 = 0; k2 < 2; k2++) {
						for (int k3 = 0; k3 < 2; k3++) {
							Arrays.fill(dp[i][j][k][k2][k3], -1);
						}
					}
				}
			}
		}
		io.println(solve(Math.abs(x1-x2), Math.abs(y1-y2), 0, 0, 0, 0)==1?"First":"Second");
		io.close();
	}

	static int solve(int x, int y, int t, int tr, int r, int player) {
		int res = dp[x][y][t][tr][r][player];
		if (res != -1) return res;
		res = 0;
		if (player == 1) { // Glue
			if (solve(x, y, 1, tr, r, 0) == 0) {
				res = 1;
			} else if (solve(x, y, t, 1, r, 0) == 0) {
				res = 1;
			} else {
				res = (solve(x, y, t, tr, 1, 0)+1)%2;
			}
		} else {
			if (x+y <= 3 || tr == 0 && x != 0 && y != 0 && x+y <= 4) {
				res = 1;
			} else {
				if (t == 0 && x > 0) {
					if (solve(x-1, y, 0, 0, tr, 1) == 0) {
						res = 1;
					}
				}
				if (r == 0 && y > 0) {
					if (solve(x, y-1, tr, 0, 0, 1) == 0) {
						res = 1;
					}
				}
			}
		}
		return dp[x][y][t][tr][r][player] = res;
	}

	static class Kattio extends PrintWriter {
	    public Kattio(InputStream i) {
		super(new BufferedOutputStream(System.out));
		r = new BufferedReader(new InputStreamReader(i));
	    }
	    public Kattio(InputStream i, OutputStream o) {
		super(new BufferedOutputStream(o));
		r = new BufferedReader(new InputStreamReader(i));
	    }

	    public boolean hasMoreTokens() {
		return peekToken() != null;
	    }

	    public int getInt() {
		return Integer.parseInt(nextToken());
	    }

	    public double getDouble() { 
		return Double.parseDouble(nextToken());
	    }

	    public long getLong() {
		return Long.parseLong(nextToken());
	    }

	    public String getWord() {
		return nextToken();
	    }

	    private BufferedReader r;
	    private String line;
	    private StringTokenizer st;
	    private String token;

	    private String peekToken() {
		if (token == null) 
		    try {
			while (st == null || !st.hasMoreTokens()) {
			    line = r.readLine();
			    if (line == null) return null;
			    st = new StringTokenizer(line);
			}
			token = st.nextToken();
		    } catch (IOException e) { }
		return token;
	    }

	    private String nextToken() {
		String ans = peekToken();
		token = null;
		return ans;
	    }
	}
}

