pair<ll, ll> dfs(int source) {
  vis[source] = true;
  ll ch_dec = 0;
  ll ch_inc = 0;
  for (int child : tree[source]) {
    if (vis[child] == false) {
      pair<ll, ll> chs = dfs(child);
      ch_inc = max(ch_inc, chs.first);
      ch_dec = max(ch_dec, chs.second);
    }
  }
  int value = values[source] + ch_inc - ch_dec;
  if (value > 0) {
    ch_dec += value;
  } else {
    value = abs(value);
    ch_inc += value;
  }
  if (ch_inc < 0 || ch_dec < 0) {
    cout << 1 / 0;
  }
  return make_pair(ch_inc, ch_dec);
}
