const int mod = 998244353;
const int M = 5e3;
int main() {
  for (int i = 0; i <= M; i++) p[i][0] = c[i][0] = 1;
  for (int i = 1; i <= M; i++)
    for (int j = 1; j <= M; j++)
      p[i][j] =
          (1ll * p[i - 1][j - 1] * (i - j) + 1ll * p[i - 1][j] * (j + 1)) % mod,
      c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
  fac[0] = 1;
  for (int i = 1; i <= M; i++) fac[i] = 1ll * fac[i - 1] * i % mod;
