    rep(i, N) {
        int a = A[i];
        int k = 2;
        while((k * k) < a) {
            if (a % k == 0) {
                mp[k]++;
                a /= k;
            }
            else {
                k++;
            }
        }
        if (a > 1) mp[a]++;

