int solve(int i, int n) {
  if (i > m) {
    return d[0] * (n / c[0]);
  }
  if (dp[i][n] != -1) return dp[i][n];
  int ans = 0;
  if (n >= c[0]) ans = max(ans, solve(i + 1, n - c[0]) + d[0]);
  for (int j = 1; j <= min(a[i] / b[i], n / c[i]); j++) {
