int n, m;
int pfx[250][250 + 1][26];
bool eq(int lft, int rt, int x, int y) {
  for (int i = 0; i < 26; i++)
    if (pfx[x][rt + 1][i] - pfx[x][lft][i] !=
        pfx[y][rt + 1][i] - pfx[y][lft][i])
      return false;
  return true;
}
bool eq2(int lft, int rt, int x, int y, int shf) {
  if ((x % 2) == 1 && (y % 2) == 1)
    return true;
  else if ((x % 2) == 1 || (y % 2) == 1)
    return false;
  x /= 2;
  y /= 2;
  x += shf;
  y += shf;
  for (int i = 0; i < 26; i++)
    if (pfx[x][rt + 1][i] - pfx[x][lft][i] !=
        pfx[y][rt + 1][i] - pfx[y][lft][i])
      return false;
  return true;
}
bool chk(int lft, int rt, int x) {
  int cnt0 = 0;
  for (int i = 0; i < 26; i++)
    if ((pfx[x][rt + 1][i] - pfx[x][lft][i]) % 2) cnt0++;
  return cnt0 <= 1;
}
long long mancal(int lft, int rt, int lx, int rx) {
  int n2 = rx - lx + 1;
  if (n2 == 0) return 0;
  vector<int> res(2 * n2 - 1);
  int p = 0, pR = -1;
  for (int pos = 0; pos < 2 * n2 - 1; ++pos) {
    int R = pos <= 2 * pR ? min(p - res[2 * p - pos], pR) : pos / 2;
    int L = pos - R;
    while (L > 0 && R < n2 - 1 && eq(lft, rt, L - 1 + lx, R + 1 + lx)) {
      --L;
      ++R;
    }
    res[pos] = L;
    if (R > pR) {
      pR = R;
      p = pos;
    }
  }
  long long ans = 0;
  for (int i = 0; i < 2 * n2 - 1; i++) ans += (i - 2 * res[i] + 1 + 1) / 2;
  return ans;
}
long long manacher(int lft, int rt) {
  long long ans = 0;
  for (int i = 0; i < n; i++) {
    if (chk(lft, rt, i)) {
      int j = i;
      while (j + 1 < n && chk(lft, rt, j + 1)) j++;
      ans += mancal(lft, rt, i, j);
      i = j;
    }
  }
  return ans;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> m;
  string grid[n];
  for (int i = 0; i < n; i++) cin >> grid[i];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < 26; j++) pfx[i][0][j] = 0;
    for (int j = 0; j < m; j++) {
      for (int k = 0; k < 26; k++) pfx[i][j + 1][k] = pfx[i][j][k];
      pfx[i][j + 1][grid[i][j] - 'a']++;
    }
  }
  long long ans = 0;
  for (int i = 0; i < m; i++) {
    for (int j = i; j < m; j++) {
      ans += manacher(i, j);
    }
  }
  cout << ans;
  return 0;
}

