struct LCT {
  struct lct {
    int fa, son[2], pos;
    bool rev;
  } t[N];
  bool notroot(int p) {
    return t[t[p].fa].son[0] == p || t[t[p].fa].son[1] == p;
  }
  void pushrev(int p) { t[p].rev ^= 1, swap(t[p].son[0], t[p].son[1]); }
  void push(int p) {
    if (t[p].rev) {
      int ls = t[p].son[0], rs = t[p].son[1];
      if (ls) pushrev(ls);
      if (rs) pushrev(rs);
      t[p].rev = 0;
    }
  }
  void update(int p) {
    t[p].pos = p;
    int ls = t[p].son[0], rs = t[p].son[1];
    if (ls && a[t[ls].pos].w < a[t[p].pos].w) t[p].pos = t[ls].pos;
    if (rs && a[t[rs].pos].w < a[t[p].pos].w) t[p].pos = t[rs].pos;
  }
  int get(int p) { return t[t[p].fa].son[1] == p; }
  void rotate(int p) {
    int s = get(p), f = t[p].fa, ff = t[f].fa;
    t[f].son[s] = t[p].son[s ^ 1];
    if (t[f].son[s]) t[t[f].son[s]].fa = f;
    if (notroot(f)) t[ff].son[get(f)] = p;
    t[p].fa = ff;
    t[p].son[s ^ 1] = f, t[f].fa = p;
    update(f), update(p);
  }
  int st[N], z = 0;
  void splay(int p) {
    int y = p;
    st[z = 1] = y;
    while (notroot(y)) st[++z] = y = t[y].fa;
    while (z) push(st[z]), --z;
    while (notroot(p)) {
      int f = t[p].fa;
      if (notroot(f)) rotate(get(f) == get(p) ? f : p);
      rotate(p);
    }
  }
  void access(int p) {
    for (int y = 0; p; y = p, p = t[p].fa) splay(p), t[p].son[1] = y, update(p);
  }
  void makeroot(int p) {
    access(p);
    splay(p);
    pushrev(p);
  }
  int findroot(int p) {
    access(p), splay(p);
    while (t[p].son[0]) push(p), p = t[p].son[0];
    splay(p);
    return p;
  }
  void split(int x, int y) {
    makeroot(y);
    access(x), splay(x);
  }
  void link(int x, int y) {
    makeroot(y);
    t[y].fa = x;
  }
  void cut(int x, int y) {
    split(x, y);
    t[y].fa = t[x].son[0] = 0;
    update(x);
  }
  void init() {
    for (int i = 1; i <= n * 3; i++) t[i].pos = i;
  }
} T;
