struct treap // struct
{
  int data, priority;
  vector<treap *> kids;
  int subtree_size, sum, lazy;
};
int size(treap *node) // retorna o tamanho da subtree do no
{
  return (node == NULL) ? 0 : node->subtree_size;
}
void recalc(treap *node) // recalculo das informacoes do no
{
  if (node == NULL)
    return;
  node->subtree_size = size(node->kids[0]) + size(node->kids[1]) + 1;
}
void lazy_propagation(treap *node) // implicit treap lazy
{
  if (node == NULL || !(node->lazy))
    return;
  swap(node->kids[0], node->kids[1]); // swap kids
  for (auto const &i : node->kids)
  {
    if (i == NULL)
      continue;
    i->lazy ^= 1; // if kid exist, set lazy = true
  }
  node->lazy = 0;
}
vector<treap *> split(treap *node, int n) // n = quantidade de elementos na subarvore da esquerda
{
  if (node == NULL)
    return {NULL, NULL};
  lazy_propagation(node);
  if (size(node->kids[0]) >= n)
  {
    vector<treap *> left = split(node->kids[0], n);
    node->kids[0] = left[1];
    recalc(node);
    return {left[0], node};
  }
  else
  {
    vector<treap *> right = split(node->kids[1], n - size(node->kids[0]) - 1);
    node->kids[1] = right[0];
    recalc(node);
    return {node, right[1]};
  }
}
treap *merge(treap *l, treap *r) // merge entre duas treaps
{
  if (l == NULL)
    return r;
  if (r == NULL)
    return l;
  lazy_propagation(l);
  lazy_propagation(r);
  if (l->priority < r->priority)
  {
    l->kids[1] = merge(l->kids[1], r);
    recalc(l);
    return l;
  }
  else
  {
    r->kids[0] = merge(l, r->kids[0]);
    recalc(r);
    return r;
  }
}
treap *create_node(int data, int priority) // criar um novo no
{
  //cout << data << " " << priority << endl;
  treap *ret = new treap;
  ret->data = data;
  ret->priority = priority;
  ret->kids = {NULL, NULL};
  ret->subtree_size = 1;
  ret->sum = ret->data;
  ret->lazy = 0;
  return ret;
}
void print_treap(treap *t) // dfs in treap tree
{
  if (t == NULL)
    return;
  lazy_propagation(t);
  print_treap(t->kids[0]);
  cout << t->data << " "; // para printar na ordem correta
  //resp.pb(t->data);
  print_treap(t->kids[1]);
}
treap *shift(treap *t, int l, int r) // right shift
{
  vector<treap *> a = split(t, l);
  vector<treap *> b = split(a[1], r - l + 1);
  vector<treap *> c = split(b[0], r - l);             // separo o ultimo cara do intervalo
  return merge(merge(a[0], c[1]), merge(c[0], b[1])); // agora o ultimo cara do intervalo eh o primeiro
}
treap *reverse(treap *t, int l, int r) // reverse
{
  //we have to add boolean flag ‘rev’ and set it to true when the subtree
  //of the current node has to be reversed.
  vector<treap *> a = split(t, l);
  vector<treap *> b = split(a[1], r - l + 1);
  b[0]->lazy ^= 1;
  return merge(a[0], merge(b[0], b[1]));
}
