  }
  if (x != 1 && x <= 1000000000) pri[++tot] = x;
}
int q_pow(int x, int n, int mod) {
  int ret = 1;
  for (; n; n >>= 1, x = (long long)x * x % mod)
    if (n & 1) ret = (long long)ret * x % mod;
  return ret;
}
