class SegmentTree {
    int n;
    long[] tree;
    private long fun(long left, long right) {
        if(right==0) return left;
        else return fun(right,left%right);
    }
    public SegmentTree(int[] arr){
        n = arr.length;
        tree = new long[4*n];
        build(arr,1,0,n-1);
    }
    public SegmentTree(long[] arr){
        n = arr.length;
        tree = new long[4*n];
        build(arr,1,0,n-1);
    }
    private void build(long[] arr, int curr, int currL, int currR) {
        if(currL==currR){
            tree[curr] = arr[currL];
        }
        else{
            int middle = (currL + currR)>>1;
            build(arr,curr<<1,currL,middle);
            build(arr,(curr<<1)+1,middle+1,currR);
            long left = tree[curr<<1];
            long right = tree[(curr<<1)+1];
            tree[curr] = fun(left,right);
        }
    }

    private void build(int[] arr, int curr, int currL, int currR) {
        if(currL==currR){
            tree[curr] = arr[currL];
        }
        else{
            int middle = (currL + currR)>>1;
            build(arr,curr<<1,currL,middle);
            build(arr,(curr<<1)+1,middle+1,currR);
            long left = tree[curr<<1];
            long right = tree[(curr<<1)+1];
            tree[curr] = fun(left,right);
        }
    }
    public long rangeQ(int from, int to){
        return rangeQ(1,0,n-1,from, to);
    }
    private long rangeQ(int curr, int currL, int currR, int from, int to) {
        if(from>to) return 0;
        if(currL==from && currR==to) return tree[curr];
        int middle = (currL+currR)>>1;
        long left = rangeQ(curr<<1, currL, middle, from, Math.min(to,middle));
        long right = rangeQ((curr<<1)+1, middle+1, currR, Math.max(from,middle+1), to);
        return fun(left,right);
    }


    public void update(int ind,int new_val){
        update(1,0,n-1,ind,new_val);
    }
    public void update(int ind,long new_val){
        update(1,0,n-1,ind,new_val);
    }
    private void update(int i, int currL, int currR, int ind, long new_val) {
        if(currL == currR){
            tree[i]  = new_val;
         }
         else{
             int middle = (currL+currR)>>1;
             if(ind <= middle){
                 update(i<<1,currL,middle,ind,new_val);
             }
             else{
                 update((i<<1)+1,middle+1,currR,ind,new_val);
             }
             long nl = tree[i<<1];
             long nr = tree[(i<<1)+1];
             tree[i] = fun(nl,nr);
         }
    }
    private void update(int i, int currL, int currR, int ind, int new_val) {
        if(currL == currR){
           tree[i]  = new_val;
        }
        else{
            int middle = (currL+currR)>>1;
            if(ind <= middle){
                update(i<<1,currL,middle,ind,new_val);
            }
            else{
                update((i<<1)+1,middle+1,currR,ind,new_val);
            }
            long nl = tree[i<<1];
            long nr = tree[(i<<1)+1];
            tree[i] = fun(nl,nr);
        }
    }

}

