#include <bits/stdc++.h>
using namespace std;
const int maxn = 3e5 + 10;
int n, a[maxn];
struct segment {
  int mx[maxn << 2], opt;
  inline int cmp(int x, int y) { return opt ? max(x, y) : min(x, y); }
  void build(int o, int l, int r, int *a) {
    if (l == r) {
      mx[o] = a[l];
      return;
    }
    int mid = (l + r) >> 1;
    build(o << 1, l, mid, a);
    build(o << 1 | 1, mid + 1, r, a);
    mx[o] = cmp(mx[o << 1], mx[o << 1 | 1]);
  }
  int query(int o, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
      return mx[o];
    }
    int mid = (l + r) >> 1;
    if (ql <= mid && mid < qr)
      return cmp(query(o << 1, l, mid, ql, qr),
                 query(o << 1 | 1, mid + 1, r, ql, qr));
    if (ql <= mid) return query(o << 1, l, mid, ql, qr);
    if (mid < qr) return query(o << 1 | 1, mid + 1, r, ql, qr);
    return 0;
  }
} minv[20], maxv[20];
int l[20][maxn], r[20][maxn];
int main() {
  scanf("%d", &n);
  if (n == 1) {
    puts("0");
    return 0;
  }
  for (int i = 1; i <= n; ++i) scanf("%d", &a[i]);
  for (int i = n + 1; i <= n * 3; ++i) a[i] = a[i - n];
  for (int i = 1; i <= n * 3; ++i) {
    l[0][i] = max(1, i - a[i]);
    r[0][i] = min(n * 3, i + a[i]);
  }
  for (int i = 1; i < 20; ++i) {
    minv[i - 1].opt = 0;
    maxv[i - 1].opt = 1;
    minv[i - 1].build(1, 1, n * 3, l[i - 1]);
    maxv[i - 1].build(1, 1, n * 3, r[i - 1]);
    for (int j = 1; j <= n * 3; ++j) {
      l[i][j] = minv[i - 1].query(1, 1, n * 3, l[i - 1][j], r[i - 1][j]);
      r[i][j] = maxv[i - 1].query(1, 1, n * 3, l[i - 1][j], r[i - 1][j]);
    }
  }
  minv[19].opt = 0;
  maxv[19].opt = 1;
  minv[19].build(1, 1, n * 3, l[19]);
  maxv[19].build(1, 1, n * 3, r[19]);
  for (int i = n + 1; i <= n * 2; ++i) {
    int ans = 0, L = i, R = i;
    for (int j = 19; j >= 0; --j) {
      int ql = minv[j].query(1, 1, n * 3, L, R),
          qr = maxv[j].query(1, 1, n * 3, L, R);
      if (qr - ql + 1 < n) {
        L = ql;
        R = qr;
        ans += (1 << j);
      }
    }
    printf("%d ", ans + 1);
  }
}

#include<bits/stdc++.h>
typedef long long int ll;
typedef unsigned long long int ull;
#define BIG_NUM 2000000000
#define MOD 1000000007
#define EPS 0.000000001
using namespace std;


#define NUM 600001


int N = 1;
int euler_index,root;
int num_count[NUM][10],change_table[NUM][10];
int LEFT[100005],RIGHT[100005];
vector<int> G[100005];


void init(int first_N){
	while(N < first_N)N *= 2;
}

//最初、全ての電球の明るさは0
void add(int loc){
	loc += N-1;

	num_count[loc][0] += 1;

	while(loc > 0){
		loc = (loc-1)/2;
		num_count[loc][0] = num_count[2*loc+1][0]+num_count[2*loc+2][0];
	}
}

void update(int update_left,int update_right,int node_id,int node_left,int node_right,int x,int y){

	if(update_right < node_left || update_left > node_right)return; //範囲外なら何もしない
	else if(update_left <= node_left && update_right >= node_right){ //このノードのカバー区間が、更新区間の部分区間である場合

		//printf("部分区間 node_id:%d node_left:%d node_right:%d\n",node_id,node_left,node_right);

		for(int i = 0; i <= 9; i++){
			if((change_table[node_id][i] == x)){
				change_table[node_id][i] = y; //変換対応を更新
			}
		}
		int next_num_count[10];
		for(int i = 0; i <= 9; i++){
			next_num_count[i] = 0;
		}

		for(int i = 0; i <= 9; i++){
			next_num_count[change_table[i]] += num_count[node_id][i];
		}

		for(int i = 0; i <= 9; i++){
			num_count[node_id][i] = next_num_count[i];
		}

		return; //更新は子方向に伝えない

	}else{
		//このノードのカバー範囲と更新範囲に部分的な重なりがある場合
		//現在自分が★蓄積していた(子供に伝えていなかった)★変換情報を子に投げる(★★更新区間が、node_left～node_rightであることに注意★★)

		//printf("一部一致 node_id:%d node_left:%d node_right:%d\n",node_id,node_left,node_right);

		for(int i = 0; i <= 9; i++){

			if(i == change_table[node_id][i])continue;

			update(node_left,node_right,2*node_id+1,node_left,(node_left+node_right)/2,i,change_table[node_id][i]);
			update(node_left,node_right,2*node_id+2,(node_left+node_right)/2+1,node_right,i,change_table[node_id][i]);

			change_table[node_id][i] = i;
		}

		//改めて今回のクエリを投げる
		update(update_left,update_right,2*node_id+1,node_left,(node_left+node_right)/2,x,y);
		update(update_left,update_right,2*node_id+2,(node_left+node_right)/2+1,node_right,x,y);

		//★★子にクエリを投げた結果、このノードの以下の集計が変わるので、ボトムアップ的に再帰的に計算する
		for(int i = 0; i <= 9; i++){
			num_count[node_id][i] = num_count[2*node_id+1][i]+num_count[2*node_id+2][i];
		}
	}
}



int getSum(int search_left,int search_right,int node_id,int node_left,int node_right,int x,int y){
	if(search_right < node_left || search_left > node_right){
		return 0;
	}else if(search_left <= node_left && search_right >= node_right){

		int ret = 0;
		for(int i = x; i <= y; i++){
			ret += num_count[node_id][i];
		}

		return ret;

	}else{

		for(int i = 0; i <= 9; i++){

			if(i == change_table[node_id][i])continue;

			update(node_left,node_right,2*node_id+1,node_left,(node_left+node_right)/2,i,change_table[node_id][i]);
			update(node_left,node_right,2*node_id+2,(node_left+node_right)/2+1,node_right,i,change_table[node_id][i]);

			change_table[node_id][i] = i;
		}

		int left = getSum(search_left,search_right,2*node_id+1,node_left,(node_left+node_right)/2,x,y);
		int right = getSum(search_left,search_right,2*node_id+2,(node_left+node_right)/2+1,node_right,x,y);
		return left+right;
	}
}


//オイラーツアーで、ノードのカバー範囲を計算する
void euler_tour(int node_id,int pre_node){
	LEFT[node_id] = euler_index++;

	for(int i = 0; i < G[node_id].size(); i++){
		if(G[node_id][i] == pre_node)continue;
		euler_tour(G[node_id][i],node_id);
	}
	RIGHT[node_id] = euler_index++;
}

