		if(command == 1){ //計上

			//update(LEFT[node_id],RIGHT[node_id],0,0,N-1,-2,-2); //情報を下に伝播させるためのクエリ
			printf("%d\n",getSum(LEFT[node_id],RIGHT[node_id],0,0,N-1,x,y));

			debug++;
			if(debug == 149){

				//printf("%d\n",getSum(LEFT[node_id],RIGHT[node_id],0,0,N-1,x,y));
