int parent[2000005], ranks[2000005];
int dsuFind(int x) {
  if (x != parent[x]) {
    parent[x] = dsuFind(parent[x]);
  }
  return parent[x];
}
void dsuUnion(int a, int b) {
  int ra = dsuFind(a);
  int rb = dsuFind(b);
  if (ra != rb) {
    if (ranks[ra] < ranks[rb]) swap(ra, rb);
    parent[rb] = ra;
    if (ranks[ra] == ranks[rb]) ranks[ra]++;
  }
}
void solve() {
  int n;
  cin >> n;
  for (int i = 1; i <= n + 1; i++) {
    parent[i] = i;
    ranks[i] = 1;
  }
  int par[n + 1];
  int root = 0;
  for (int i = 1; i <= n; i++) {
    cin >> par[i];
    if (par[i] == i) root = i;
  }
  int count = 0;
  for (int i = 1; i <= n; i++) {
    int state1 = dsuFind(i), state2 = dsuFind(par[i]);
    if (i != root && state1 == state2) {
      if (root != 0) {
        count++;
        par[i] = root;
      } else {
        root = i;
        par[i] = i;
      }
    }
    dsuUnion(i, par[i]);
  }
  cout << count << "\n";
  for (int i = 1; i <= n; i++) {
    cout << par[i] << " ";
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
