void Calc(int _n, char *str) {
  n = _n;
  m = 0;
  for (int i = 1; i <= n; i++) {
    a[i] = str[i] - 'a' + 1;
    b[i] = i;
    m = max(m, a[i]);
  }
  Sort();
  int all = -1;
  for (int l = 1; all < n; l <<= 1) {
    all = 0;
    for (int i = n - l + 1; i <= n; i++) b[++all] = i;
    for (int i = 1; i <= n; i++)
      if (sa[i] > l) b[++all] = sa[i] - l;
