void Sieve(int n) {
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) {
      p[++pcnt] = i;
      minp[i] = i;
    }
    for (int j = 1; j <= pcnt && i * p[j] <= n; j++) {
      vis[i * p[j]] = true;
      minp[i * p[j]] = p[j];
      if (i % p[j] == 0) break;
    }
  }
}
void GetP(int x, int *a, int &acnt) {
  acnt = 0;
  while (x != 1) {
    int curp = minp[x];
    a[++acnt] = curp;
    while (x % curp == 0) x /= curp;
  }
}
