namespace DIV {
struct Seg {
  const static int SIZE = (::N)*2;
  struct Node {
    int ch[2];
    int tag;
  } a[SIZE];
  int nodeCnt;
  int rt;
  void Reset() { rt = nodeCnt = 0; }
  inline void MakeTag(int u, int x) { a[u].tag = min(a[u].tag, x); }
  void Build(int &u, int l, int r) {
    u = ++nodeCnt;
    a[u].tag = INF;
    if (l == r) return;
    int mid = (l + r) >> 1;
    Build(a[u].ch[0], l, mid);
    Build(a[u].ch[1], mid + 1, r);
  }
  void SegMin(int u, int l, int r, int ml, int mr, int x) {
    if (ml > mr) return;
    if (ml <= l && r <= mr) {
      MakeTag(u, x);
      return;
    }
    int mid = (l + r) >> 1;
    if (mr <= mid)
      SegMin(a[u].ch[0], l, mid, ml, mr, x);
    else if (mid < ml)
      SegMin(a[u].ch[1], mid + 1, r, ml, mr, x);
    else {
      SegMin(a[u].ch[0], l, mid, ml, mid, x);
      SegMin(a[u].ch[1], mid + 1, r, mid + 1, mr, x);
    }
  }
  void Extract(int u, int l, int r, int *arr, int tagSum = INF) {
    tagSum = min(tagSum, a[u].tag);
    if (l == r) {
      arr[l] = tagSum;
      return;
    }
    int mid = (l + r) >> 1;
    Extract(a[u].ch[0], l, mid, arr, tagSum);
    Extract(a[u].ch[1], mid + 1, r, arr, tagSum);
  }
} sl, sr;
