long long cal(long long x) {
  long long now = n, dep = 1;
  ans = 0;
  for (long long i = 1; now >= i; i *= x) {
    ans += i * dep;
    num[dep] = i;
    now -= i;
    dep++;
  }
  num[dep] = now;
  ans += now * dep;
  b = dep;
  return ans;
}
void adjust(int x) {
  cal(x - 1);
  a = 2;
  long long now, rest;
  while (1) {
    now = min(num[a - 1] * x - num[a], num[b]);
    if (ans - now * (b - a) <= m) break;
    ans -= now * (b - a);
    num[a] += now;
    num[b] -= now;
    if (num[a] == x * num[a - 1]) a++;
    if (!num[b]) b--;
  }
  rest = ans - m;
  now = rest / (b - a);
  num[a] += now;
  num[b] -= now;
  rest -= (b - a) * now;
  num[b]--;
  num[b - rest]++;
}
