using namespace std;
const long long inf = 4e18;
const int N = 123456;
long long gcd(long long a, long long b) {
  while (a > 0 && b > 0) {
    if (a > b) {
      a %= b;
    } else {
      b %= a;
    }
  }
  return a + b;
}
int n;
int a[N];
void kill() {
  long long ans = 0;
  for (int i = 0; i < n; ++i) {
    ans += a[i];
  }
  cout << ans;
  exit(0);
}
long long mul(long long a, long long b) {
  if (a == 0 || b == 0) return 0;
  if (a > inf / b) {
    kill();
  }
  return a * b;
}
long long get_lcm(long long a, long long b) { return mul(a / gcd(a, b), b); }
vector<int> g[N];
long long f[N];
long long lcm[N];
long long mx[N];
void dfs(int x, int pa = -1) {
  if (g[x].size() == 1 && pa != -1) {
    lcm[x] = 1;
    f[x] = 0;
    mx[x] = a[x];
    return;
  }
  for (int y : g[x]) {
    if (y == pa) {
      continue;
    }
    dfs(y, x);
  }
  lcm[x] = 1;
  for (int y : g[x]) {
    if (y == pa) {
      continue;
    }
    lcm[x] = get_lcm(lcm[x], lcm[y]);
  }
  long long coeff = inf;
  for (int y : g[x]) {
    if (y == pa) {
      continue;
    }
    assert(lcm[y] > 0);
    long long v = lcm[x] / lcm[y];
    coeff = min(coeff, mx[y] / v);
  }
  f[x] = 0;
  for (int y : g[x]) {
    if (y == pa) {
      continue;
    }
    f[x] += f[y];
    f[x] += mul(lcm[y], mx[y]) - mul(lcm[x], coeff);
  }
  mx[x] = coeff;
  lcm[x] = mul(lcm[x], (int)g[x].size() - (pa != -1));
}
