class Solution{
	int n,k;
	int[] p;
	int[] ans;
	public Solution(int n, int k, int[] p) {
		super();
		this.n = n;
		this.k = k;
		this.p = p;
		ans = new int[256];
		Arrays.fill(ans, -1);
	}

	public void solve() {
		ans[0] =0;
		for(int i=0 ; i<n ; ++i){
			int ret =0;
			if(ans[p[i]]!=-1)continue;
			int lower = Math.max(-1, p[i]-k);
			for(ret = p[i] ; ret >lower ; --ret){
				if(ans[ret] !=-1){
					if(ans[ret] > lower){
						ret = ans[ret];
					}else ret++;
					break;
				}
			}
			ret = Math.max(ret, lower+1);
			for(int j=ret ; j<=p[i] ; ++j)ans[j] = ret;
		}
	}
}

