bool IsIn(int y, int x, int h, int w) {
  return 0 <= y && y < h && 0 <= x && x < w;
}
void BFS(vector<vector<int> > &f, vector<vector<int> > &l, int sy, int sx,
         int h, int w) {
  vector<vector<int> > done(h, vector<int>(w));
  l[sy][sx] = 1;
  done[sy][sx] = 1;
  queue<pair<int, int> > que;
  for (int i = (0); i < (4); ++i) {
    int ny = sy + dy[i], nx = sx + dx[i];
    if (!IsIn(ny, nx, h, w)) continue;
    que.push(pair<int, int>(ny, nx));
  }
  while (!que.empty()) {
    pair<int, int> p = que.front();
    que.pop();
    done[p.first][p.second] = 1;
    bool flag = true;
    int tmp = INF;
    for (int i = (0); i < (4); ++i) {
      int ny = p.first + dy[i], nx = p.second + dx[i];
      if (!IsIn(ny, nx, h, w)) continue;
      tmp = min(tmp, l[ny][nx]);
      if (done[ny][nx] == 1 && l[ny][nx] >= f[p.first][p.second]) flag = false;
      if (done[ny][nx] != 1) que.push(pair<int, int>(ny, nx));
    }
    if (flag)
      l[p.first][p.second] = f[p.first][p.second];
    else
      l[p.first][p.second] = tmp;
  }
}
