void annihilate(int depth, int left, int right) {
  if (left == right) return;
  int mid = (left + right) >> 1;
  annihilate(depth + 1, left, mid);
  annihilate(depth + 1, mid + 1, right);
  fcuk(depth, left, mid + 1, right);
}
