  const Polygon convex_cut(const Line& l) const;

 private:
  std::vector<Point> vertex_;
  std::vector<Segment> edge_;
};
void Polygon::add(const Point& p) {
  if (!vertex_.empty()) {
    if (!edge_.empty()) edge_.pop_back();
    edge_.push_back(Segment(vertex_.back(), p));
    edge_.push_back(Segment(p, vertex_.front()));
  }
  vertex_.push_back(p);
}
void Polygon::clear() {
  vertex_.clear();
  edge_.clear();
};
int Polygon::size() const { return vertex_.size(); }
Point Polygon::vertex(const int n) const { return vertex_.at(n); }
Segment Polygon::edge(const int n) const { return edge_.at(n); }
const std::vector<Point>& Polygon::vertex() const { return vertex_; }
const std::vector<Segment>& Polygon::edge() const { return edge_; }
bool Polygon::touch(const Point& p) const {
  return std::any_of(std::begin(edge()), std::end(edge()),
                     [=](const Segment& s) {
                       return ccw(s.initial, s.terminal, p) == ON_SEGMENT;
                     });
}
bool Polygon::intersect(const Point& p) const {
  bool in = false;
  for (const auto& e : edge()) {
    if (::intersect(p, e)) return true;
    Point a = e.initial - p;
    Point b = e.terminal - p;
    if (a.y > b.y) std::swap(a, b);
    if (a.y < EPS && EPS <= b.y && cross(a, b) < EPS) in = !in;
  }
  return in;
}
double Polygon::area() const {
  return std::abs(std::accumulate(std::begin(edge()), std::end(edge()), 0.0,
                                  [=](const double sum, const Segment& e) {
                                    return sum + cross(e.initial, e.terminal);
                                  })) /
         2.0;
}
bool Polygon::convex() const {
  bool positive = false;
  bool negative = false;
  for (int i = 0; i < size(); ++i) {
    auto position =
        ccw(vertex(i), vertex((i + 1) % size()), vertex((i + 2) % size()));
    positive |= position == CLOCKWISE;
    negative |= position == COUNTER_CLOCKWISE;
    if (negative && positive) return false;
  }
  return true;
}
const Polygon Polygon::convex_hull() const {
  auto original = vertex();
  std::sort(std::begin(original), std::end(original));
  original.insert(std::end(original), original.rbegin() + 1, original.rend());
  std::vector<Point> point;
  for (const auto& p : original) {
    while (point.size() >= 2 &&
           ccw(point[point.size() - 2], point.back(), p) == CLOCKWISE)
      point.pop_back();
    point.push_back(p);
  }
  Polygon convex_hull;
  point.pop_back();
  for (const auto& p : point) convex_hull.add(p);
  return convex_hull;
}
double Polygon::convex_diameter() const {
  auto point = vertex();
  int p, q, start_p, start_q, max_p, max_q;
  p = start_p = max_p =
      std::min_element(std::begin(point), std::end(point)) - std::begin(point);
  q = start_q = max_q =
      std::max_element(std::begin(point), std::end(point)) - std::begin(point);
  double max_d = norm(vertex(p) - vertex(q));
  do {
    if (cross(vertex((p + 1) % size()) - vertex(p),
              vertex((q + 1) % size()) - vertex(q)) >= 0)
      q = (q + 1) % size();
    else
      p = (p + 1) % size();
    if (norm(vertex(p) - vertex(q)) > max_d) {
      max_d = norm(vertex(p) - vertex(q));
      max_p = p;
      max_q = q;
    }
  } while (start_p != q || start_q != p);
  return std::sqrt(max_d);
}
const Polygon Polygon::convex_cut(const Line& l) const {
  Polygon result;
  for (const auto& e : edge()) {
    if (ccw(l.initial, l.terminal, e.initial) == COUNTER_CLOCKWISE)
      result.add(e.initial);
    if (::intersect(e, l)) result.add(crosspoint(e, l));
  }
  return result;
}
using namespace std;
int solve(const vector<Point>& point) {
  int res = point.size();
  Polygon polygon;
  for (const auto& p : point) polygon.add(p);
  vector<Segment> edge;
  for (int i = 0; i < point.size(); ++i)
    edge.push_back(Segment(point[i], point[(i + 1) % point.size()]));
  for (int i = 0; i < point.size(); ++i)
    for (int j = i + 1; j < point.size(); ++j) {
      Segment s(point[i], point[j]);
      for (auto it = begin(edge); it != end(edge); ++it) {
        if (intersect(point[i], *it)) continue;
        if (intersect(point[j], *it)) continue;
        if (!intersect(s, *it)) continue;
        auto cp = crosspoint(s, *it);
        if (cp == point[i] || cp == point[j]) continue;
        if (cp == it->initial || cp == it->terminal) continue;
        Segment s1(it->initial, cp), s2(cp, it->terminal);
        it = edge.erase(it);
        it = edge.insert(it, s1);
        ++it;
        it = edge.insert(it, s2);
      }
    }
  map<tuple<int, int>, bool> memo;
  for (int bit = 1; bit < (1 << point.size()); ++bit) {
    set<int> vertex;
    for (int i = 0; i < point.size(); ++i)
      if ((bit >> i) & 1) vertex.insert(i);
    bool ok = true;
    for (int i = 0; i < edge.size(); ++i) {
      bool covered = false;
      for (const auto& v : vertex) {
        if (memo.count(tuple<int, int>(i, v))) {
          if (!memo[tuple<int, int>(i, v)]) continue;
          covered = true;
          break;
        }
        auto g = (point[v] + edge[i].initial + edge[i].terminal) / 3.0;
        if (!polygon.intersect(g)) {
          memo[tuple<int, int>(i, v)] = false;
          continue;
        }
        Segment s(point[v], (edge[i].terminal + edge[i].initial) / 2.0);
        bool f = true;
        for (int j = 0; j < edge.size(); ++j) {
          if (i == j) continue;
          if (!intersect(s, edge[j])) continue;
          auto cp = crosspoint(s, edge[j]);
          if (parallel(s, edge[j])) continue;
          if (cp == s.initial || cp == s.terminal) continue;
          if (cp == edge[j].initial || cp == edge[j].terminal) continue;
          f = false;
          break;
        }
        if (f) covered = true;
        memo[tuple<int, int>(i, v)] = f;
      }
      if (!covered) {
        ok = false;
        break;
      }
    }
    if (ok)
      if (vertex.size() < res) res = vertex.size();
  }
  return res;
}
