int NCR(int n, int r) {
  int C[n + 1][r + 1];
  int i, j;
  for (i = 0; i <= n; i++) {
    for (j = 0; j <= min(i, r); j++) {
      if (i == 0 || j == 0) {
        C[i][j] = 1;
      } else {
        C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
      }
    }
  }
  return C[n][r];
}
