}
long long cross(const pr& a, const pr& b, const pr& c) {
  return long long(b.x - a.x) * (c.y - a.y) -
         long long(c.x - a.x) * (b.y - a.y);
}
inline long long abs(const pr& a) {
  return (long long)a.x * a.x + (long long)a.y * a.y;
}
inline bool cmp0(const pr& x, const pr& y) {
  long long cs = cross(P, x, y);
  return cs ? cs > 0 : abs(x) > abs(y);
}
inline std::vector<pr> chk(std::vector<pr>& std::vector<pr>) {
  int min = 0;
  for (int i = 1; i < std::vector<pr>.size(); ++i) {
    if (std::vector<pr>[min].x > std::vector<pr>[i].x ||
        (std::vector<pr>[min].x == std::vector<pr>[i].x &&
         std::vector<pr>[min].y < std::vector<pr>[i].y)) {
      min = i;
    }
  }
  std::swap(std::vector<pr>[0], std::vector<pr>[min]);
  if (std::vector<pr>.size() > 1)
    P = std::vector<pr>[0],
    sort(std::vector<pr>.begin() + 1, std::vector<pr>.end(), cmp0);
  static pr st[maxn];
  int top = 0;
  for (int i = 0; i < std::vector<pr>.size(); ++i) {
    for (; top > 1 && cross(st[top - 1], st[top], std::vector<pr>[i]) >= 0;)
      --top;
    st[++top] = std::vector<pr>[i];
  }
  for (int i = 1; i <= top; ++i)
    if (st[i].x % 2 || st[i].y % 2) return {};
  return ::std::vector<pr>(st + 1, st + top + 1);
}
