    static boolean[] visited;
    static boolean[] d;
	public static void main(String[] args) {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        if(n%2 == 0) System.out.println("NO");
        else {
            g = new ArrayList<>();
            for(int i = 0; i < n; i++){
                g.add(new HashSet<>());
            }
            int root = 0;
            for(int i = 0; i < n; i++){
                int v = fr.nextInt();
                if(v == 0) {
                    root = i;
                }else{
                    g.get(i).add(v-1);
                    g.get(v-1).add(i);
                }
            }
            visited = new boolean[n];
            d = new boolean[n];
            dg = new ArrayList<>();
            for(int i = 0; i < n; i++) dg.add(new ArrayList<>());
            dfs(root);
            sb.append("YES\n");
            System.out.print(sb);
        }
    }
    static void dfs(int u){
        visited[u] = true;
        for(int v : g.get(u)){
            if(!visited[v]) {
                dfs(v);
                dg.get(u).add(v);
            }
        }
        if(g.get(u).size() % 2 == 0) {
            destroy(u);
        }
    }
    static void destroy(int u){
        d[u] = true;
        sb.append(u+1 + "\n");
        for(int v : dg.get(u)){
            if(!d[v]) destroy(v);
        }
    }
}

