ll ff(int c, ll t, int r) {
	if (c == 0)
		return r == 1 ? A : ar[c].first;
	ll need = ar[c - 1].first * (ll)c - sum[c];
	t -= need;
	if (t < 0)
		return 0;

	return min((ll)(r == c + 1 ? A : ar[c].first), ar[c - 1].first + t / (c));
}


pair<ll, pair<int, int>> f(int c) {
	ll t = m;
	t -= A * (n + 1 - c) - sum[n] + sum[c - 1];
	if (t < 0)
		return{ -1,{ -1, -1 } };
	int l = 0, r = c - 1;
	while (r - l > 1) {
		int p1 = l + (r - l) / 3, p2 = r - (r - l) / 3;
		if (ff(p1, t, c) < ff(p2, t, c)) {
			if (l == p1)
				break;
			l = p1;
		}
		else {
			if (r == p2)
				break;
			r = p2;
		}
	}
	ll pm;
	if (ff(r, t, c) > ff(l, t, c))
		pm = r;
	else
		pm = l;
	ll ans = ff(pm, t, c) * cm + (n + 1 - c) * cf;
	return { ans,{ pm, ff(pm, t, c) } };
}

