    if (flag == 0) return;
  }
}
long long init(int pos) {
  int l = vec[pos].size();
  if (l == 0) return 1;
  long long sum = 0;
  for (int i = 0; i < l; i++) {
    sum = max(sum, init(vec[pos][i]));
  }
  return (long long)(sum * l);
}
int bin(int l, int r) {
  if (l > r) {
    flag = 1;
    check(l * ct, gen);
    if (flag)
      return l;
    else
      return r;
  }
  int mid = (l + r) / 2;
  flag = 1;
  check(mid * ct, gen);
  if (flag)
    return bin(mid + 1, r);
  else
    return bin(l, mid - 1);
}
