    rep(i,q){
        double x1,y1,x2,y2;
        cin>>x1>>y1>>x2>>y2;
        VP cc = convexCut(ch,Point(x1,y1),Point(x2,y2));
        printf("%.9f\n",area(cc));
    }

    return 0;
}

