    private static final FastReader scanner = new FastReader();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        solve();
        out.close();
    }

    static class Pair implements Comparable<Pair> {
        int number;
        int amount;


        public Pair(int number, int amount) {
            this.number = number;
            this.amount = amount;
        }

        @Override
        public int compareTo(Pair o) {
            return this.amount - o.amount;
        }
    }

    private static void solve() {
        int n = scanner.nextInt();
        int[] a = new int[n];
        Map<Integer, Integer> distr = new HashMap<>();
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            distr.merge(a[i], 1, Integer::sum);
        }

        List<Pair> pairs = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry: distr.entrySet()) {
            pairs.add(new Pair(entry.getKey(), entry.getValue()));
        }
        Collections.sort(pairs);

        int[] prefixSum = new int[pairs.size() + 1];
        for (int i = 0; i < pairs.size(); i++) {
            prefixSum[i+1] = prefixSum[i] + pairs.get(i).amount;
        }

        int maxArea = 0;
        int bestWidth = 0;
        int bestHeight = 0;

        for (int height = 1; height <= Math.sqrt(n); height++) {
            int amountElementsUsable = 0;
            int low = -1;
            int high = pairs.size();
            while(high - low > 1) {
                int mid = (low + high) / 2;
                if (pairs.get(mid).amount < height) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            amountElementsUsable = prefixSum[high] + (pairs.size() - high) * height;

            int width = amountElementsUsable / height;
            if (width < height) {
                continue;
            }
            int area = width * height;
            if (area > maxArea) {
                maxArea = area;
                bestWidth = width;
                bestHeight = height;
            }
        }

        int pointerPairs = pairs.size() - 1;
        int currentRow = 0;
        int currentCol = 0;
        int startCol = 1;
        int[][] rect = new int[bestHeight][bestWidth];
        int amountCellsSet = 0;

        while (amountCellsSet < bestHeight * bestWidth) {
            rect[currentRow][currentCol] = pairs.get(pointerPairs).number;
            pairs.get(pointerPairs).amount--;
            if (pairs.get(pointerPairs).amount == 0) {
                pointerPairs--;
            }
            amountCellsSet++;
            currentRow++;
            currentCol = (currentCol + 1) % bestWidth;

            if (currentRow == bestHeight) {
                currentRow = 0;
                currentCol = startCol++;
            }
        }

        out.println(bestWidth * bestHeight);
        out.println(bestHeight + " " + bestWidth);
        for (int h = 0; h < bestHeight; h++) {
            StringBuilder s = new StringBuilder();
            for (int w = 0; w < bestWidth; w++) {
                s.append(rect[h][w])
                 .append(" ");
            }
            out.println(s);
        }
    }

    //REMINDERS:
    //- CHECK FOR INTEGER-OVERFLOW BEFORE SUBMITTING

    //- CAN U BRUTEFORCE OVER SOMETHING, TO MAKE IT EASIER TO CALCULATE THE SOLUTION
}

