    for (int i = 1; i < n; ++i) {
        sum[0][i] = sum[0][i - 1] + a[0][i];
        sum[i][0] = sum[i - 1][0] + a[i][0];
    }
    for (int i = 1; i < n; ++i)
        for (int j = 1; j < n; ++j)
            sum[i][j] = sum[i - 1][j] + sum[i][j - 1]
                - sum[i - 1][j - 1] + a[i][j];

