#include <bits/stdc++.h>
std::mt19937 rng(std::chrono::system_clock::now().time_since_epoch().count());
struct Treap* nil;
struct Treap {
  int priority;
  int64_t pos, pos_lazy;
  int life, life_min, life_lazy;
  int size;
  struct Treap *left, *right;
  int id;
  Treap()
      : priority(-1),
        pos(0),
        pos_lazy(0),
        life(1e9 + 7),
        life_min(1e9 + 7),
        life_lazy(0),
        size(0),
        left(nil),
        right(nil),
        id(-1) {}
  Treap(int64_t pos, int life, int id)
      : priority(std::uniform_int_distribution<int>(0, INT_MAX)(rng)),
        pos(pos),
        pos_lazy(0),
        life(life),
        life_min(life),
        life_lazy(0),
        size(1),
        left(nil),
        right(nil),
        id(id) {}
  void pull() {
    if (this != nil) {
      left->push();
      right->push();
      size = left->size + right->size + 1;
      life_min = std::min(life, std::min(left->life_min, right->life_min));
    }
  }
  void push() {
    if (this != nil) {
      left->pos_lazy += pos_lazy;
      right->pos_lazy += pos_lazy;
      pos += pos_lazy;
      pos_lazy = 0;
      left->life_lazy += life_lazy;
      right->life_lazy += life_lazy;
      life_min += life_lazy;
      life += life_lazy;
      life_lazy = 0;
    }
  }
};
struct TreapInitializer {
  TreapInitializer() { nil = new Treap(); }
} _treap_init;
void dump(struct Treap* x);
void split(struct Treap* x, int k, struct Treap*& L, struct Treap*& R) {
  assert(k >= 0 && k <= x->size);
  x->push();
  L = R = nil;
  if (x == nil) return;
  if (k <= x->left->size) {
    split(x->left, k, L, x->left);
    R = x;
  } else {
    split(x->right, k - x->left->size - 1, x->right, R);
    L = x;
  }
  x->pull();
}
struct Treap* concat(struct Treap* x, struct Treap* y) {
  x->push();
  y->push();
  if (x == nil) return y;
  if (y == nil) return x;
  if (x->priority > y->priority) {
    x->right = concat(x->right, y);
    x->pull();
    return x;
  } else {
    y->left = concat(x, y->left);
    y->pull();
    return y;
  }
}
int lower_bound(struct Treap* x, int64_t pos) {
  x->push();
  if (x == nil) return 0;
  if (pos <= x->pos) {
    return lower_bound(x->left, pos);
  } else {
    return lower_bound(x->right, pos) + x->left->size + 1;
  }
}
int upper_bound(struct Treap* x, int64_t pos) {
  x->push();
  if (x == nil) return 0;
  if (pos < x->pos) {
    return upper_bound(x->left, pos);
  } else {
    return upper_bound(x->right, pos) + x->left->size + 1;
  }
}
int argmin_life(struct Treap* x) {
  if (x == nil) return 0;
  x->push();
  x->left->push();
  x->right->push();
  if (x->left != nil && x->life_min == x->left->life_min) {
    return argmin_life(x->left);
  } else if (x->life_min == x->life) {
    return x->left->size;
  } else if (x->right != nil && x->life_min == x->right->life_min) {
    return argmin_life(x->right) + x->left->size + 1;
  } else {
    assert(false);
  }
}
struct Treap* kth(struct Treap* x, int k) {
  assert(k >= 0 && k < x->size);
  x->push();
  if (k < x->left->size) {
    return kth(x->left, k);
  } else if (k > x->left->size) {
    return kth(x->right, k - x->left->size - 1);
  } else {
    return x;
  }
}
struct Treap* merge(struct Treap* x, struct Treap* y) {
  struct Treap* res = nil;
  while (true) {
    if (x == nil) return concat(res, y);
    if (y == nil) return concat(res, x);
    if (kth(x, 0)->pos > kth(y, 0)->pos) {
      std::swap(x, y);
    }
    int k = upper_bound(x, kth(y, 0)->pos);
    assert(k > 0);
    struct Treap* L;
    split(x, k, L, x);
    res = concat(res, L);
  }
}
void dump(struct Treap* x) {
  x->push();
  if (x != nil) {
    printf("[");
    dump(x->left);
    printf("%I64d:%d", x->pos, x->life);
    dump(x->right);
    printf("]");
  }
}
