int64_t ans[100005];
int main() {
  int N, Q;
  scanf("%d %d", &N, &Q);
  for (int i = 0; i < N; i++) {
    scanf("%I64d", &holes[i]);
  }
  struct Treap* curr = nil;
  for (int i = 0; i < Q; i++) {
    int X, K;
    scanf("%d %d", &X, &K);
    if (X < holes[0]) {
      ans[i] = X;
    } else {
      curr = merge(curr, new Treap(X, K, i));
    }
  }
  holes[N] = 1e18;
  for (int i = 1; i <= N; i++) {
    struct Treap* next = nil;
    while (curr != nil) {
      {
        int k = lower_bound(curr, holes[i]);
        struct Treap* eject;
        split(curr, k, curr, eject);
        next = merge(next, eject);
      }
      if (curr == nil) break;
      int64_t moves = std::min<int64_t>(
          curr->life_min,
          (holes[i] - kth(curr, curr->size - 1)->pos + i - 1) / i);
      curr->pos_lazy += moves * i;
      curr->life_lazy -= moves;
      curr->push();
      {
        int k = lower_bound(curr, holes[i]);
        struct Treap* eject;
        split(curr, k, curr, eject);
        if (eject != nil) {
          eject->pos_lazy -= i;
          eject->life_lazy++;
          eject->push();
