    for(int i=h; i >= 1; --i) for(int j=w; j>= 1; --j) {
        if(board[i][j]) { R[i][j] = D[i][j] = 0; } else { R[i][j] = R[i][j+1] + 1; D[i][j] = D[i+1][j] + 1; }
    }
