template <class T>
T extgcd(T a, T b, T& x, T& y) {
  for (T u = y = 1, v = x = 0; a;) {
    T q = b / a;
    swap(x -= q * u, u);
    swap(y -= q * v, v);
    swap(b -= q * a, a);
  }
  return b;
}
template <class T>
T mod_inv(T a, T m) {
  T x, y;
  extgcd(a, m, x, y);
  return (m + x % m) % m;
}
long long pw(long long a, long long b) {
  long long x = 1;
  while (b) {
    while (!(b & 1)) {
      (a *= a) %= mod;
      b /= 2;
    }
    (x *= a) %= mod;
    b--;
  }
  return x;
}
void _ntt(vector<long long>& a, int sign) {
  int i, j, k, n = a.size(), m = 1;
  while (m < n || m == 1) m <<= 1;
  a.resize(m);
  n = m;
  const int g = 3;
  long long h = pw(g, (mod - 1) / n);
  if (sign == -1) h = (int)mod_inv(h, mod);
  i = 0;
  for (j = 1; j < n - 1; j++) {
    for (k = (n >> 1); k > (i ^= k); k >>= 1)
      ;
    if (j < i) swap(a[i], a[j]);
  }
  for (i = 1; i < n; i *= 2) {
    const int i2 = 2 * i;
    const long long base = pw(h, n / i2);
    long long w = 1;
    for (j = 0; j < i; j++) {
      for (k = j; k < n; k += i2) {
        long long u = a[k];
        long long d = a[k + i] * w % mod;
        a[k] = u + d;
        if (a[k] >= mod) a[k] -= mod;
        a[k + i] = u - d;
        if (a[k + i] < 0) a[k + i] += mod;
      }
      (w *= base) %= mod;
    }
  }
  for (long long x : a) {
    if (x < 0) x += mod;
  }
}
void ntt(vector<long long>& input) { _ntt(input, 1); }
void intt(vector<long long>& input) {
  _ntt(input, -1);
  long long x = input.size();
  const int n_inv = mod_inv(x, mod);
  for (auto& x : input) x = x * n_inv % mod;
}
