const int MAXN = 50;
int cost[3][3];
int dp[3][3][3][MAXN];
int solve(int a, int b, int c, int n) {
  if (dp[a][b][c][n] != -1) {
    return dp[a][b][c][n];
  }
  if (n == 1) {
    int c1 = cost[a][b];
    int c2 = cost[a][c] + cost[c][b];
    return dp[a][b][c][n] = min(cost[a][b], cost[a][c] + cost[c][b]);
  } else {
    int s1 = solve(a, c, b, n - 1);
    int s2 = solve(c, b, a, n - 1);
    return dp[a][b][c][n] =
               min(s1 + cost[a][b] + s2,
                   solve(a, b, c, n - 1) + cost[a][c] + solve(b, a, c, n - 1) +
                       cost[c][b] + solve(a, b, c, n - 1));
  }
}
