      if (inside(change, i, j + 1)) change[i][j + 1] = change[i][j] / 2;
      if (change[i][j] % 2) {
        if (f[i][j] == 0) {
          if (inside(change, i + 1, j)) change[i + 1][j]++;
        } else {
