#include <bits/stdc++.h>
using namespace std;
const int NMAX = 1e6 + 5, INF = 1e9;
int N;
vector<int> G[NMAX];
long long ans;
vector<int> Vals[NMAX];
bool Active[NMAX];
int Min = INF, Max = -INF;
class Sets {
 private:
  int T[NMAX];
  vector<int> List[NMAX];

 public:
  int Size[NMAX];
  inline int Find(int X) { return T[X]; }
  inline void Initialize(int N) {
    for (int i = 1; i <= N; ++i)
      List[i].clear(), List[i].push_back(i), T[i] = i, Size[i] = 1;
    return;
  }
  inline bool Unify(int X, int Y) {
    X = Find(X);
    Y = Find(Y);
    if (X == Y) return 0;
    if (Size[X] > Size[Y]) {
      for (auto it : List[Y]) {
        List[X].push_back(it);
        T[it] = X;
      }
      Size[X] += Size[Y];
      List[Y].clear();
      Size[Y] = 0;
      return 1;
    }
    for (auto it : List[X]) {
      List[Y].push_back(it);
      T[it] = Y;
    }
    Size[Y] += Size[X];
    List[X].clear();
    Size[X] = 0;
    return 1;
  }
} DSU;
static inline void Read() {
  ios_base ::sync_with_stdio(false);
  cin.tie(nullptr);
  cin >> N;
  for (int i = 1; i <= N; ++i) {
    int X = 0;
    cin >> X;
    Vals[X].push_back(i);
    Min = min(Min, X);
    Max = max(Max, X);
  }
  for (int i = 1; i < N; ++i) {
    int X = 0, Y = 0;
    cin >> X >> Y;
    G[X].push_back(Y);
    G[Y].push_back(X);
  }
  return;
}
static inline long long F(int Start, int Finish, int step) {
  long long r = 0;
  for (int i = 1; i <= N; ++i) Active[i] = 0;
  DSU.Initialize(N);
  for (int i = Start; ((step == 1) ? (i <= Finish) : (i >= Finish)); i += step)
    if (!Vals[i].empty())
      for (auto Node : Vals[i]) {
        int Sum = 1;
        for (auto Son : G[Node]) {
          if (!Active[Son]) continue;
          r += 1LL * i * Sum * (DSU.Size[DSU.Find(Son)]);
          DSU.Unify(Node, Son);
          Sum += DSU.Size[DSU.Find(Son)];
        }
        Active[Node] = 1;
      }
  return r;
}
