using namespace std;
struct seg {
  int tree[400001];
  int a[100001];
  int init(int node, int left, int right) {
    if (left == right) {
      return tree[node] = a[left];
    }
    return tree[node] = init(node * 2, left, (left + right) / 2) +
                        init(node * 2 + 1, (left + right) / 2 + 1, right);
  }
  int sum(int node, int left, int right, int l, int r) {
    if (right < l || r < left) return 0;
    if (l <= left && right <= r) return tree[node];
    return sum(node * 2, left, (left + right) / 2, l, r) +
           sum(node * 2 + 1, (left + right) / 2 + 1, right, l, r);
  }
  void update(int node, int left, int right, int idx, int diff) {
    if (idx < left) return;
    if (right < idx) return;
    tree[node] = tree[node] + diff;
    if (left != right) {
      update(node * 2, left, (left + right) / 2, idx, diff);
      update(node * 2 + 1, (left + right) / 2 + 1, right, idx, diff);
    }
  }
};
struct networkflow {
  struct Edge {
    int to, cap;
    Edge* rev;
    Edge(int v, int c) : to(v), cap(c) {}
  };
  int N, S, E;
  vector<vector<Edge*>> g;
  vector<pair<int, int>> from;
  networkflow(int n, int s, int e) : N(n), S(s), E(e) {
    g.resize(n);
    from.resize(n);
  }
  void makeEdge(int u, int v, int c) {
    Edge* ori = new Edge(v, c);
    Edge* rev = new Edge(c, 0);
    ori->rev = rev;
    rev->rev = ori;
    g[u].push_back(ori);
    g[v].push_back(rev);
  }
  void makeEdgeFromS(int v, int c) { makeEdge(S, v, c); }
  void makeEdgeFromSink(int u, int c) { makeEdge(u, E, c); }
  void flow() {
    int total = 0;
    while (true) {
      queue<int> q;
      q.push(S);
      fill(from.begin(), from.end(), make_pair(-1, -1));
      while (!q.empty()) {
        int curr = q.front();
        q.pop();
        for (int i = 0; i < g[curr].size(); i++) {
          int next = g[curr][i]->to;
          if (from[next].first == -1 && g[curr][i]->cap > 0) {
            q.push(next);
            from[next] = {curr, i};
          }
        }
      }
      if (from[E].first == -1) break;
      int x = E;
      int f = 987654321;
      while (x != S) {
        f = min(f, g[from[x].first][from[x].second]->cap);
        x = from[x].first;
      }
      x = E;
      while (x != S) {
        g[from[x].first][from[x].second]->cap -= f;
        g[from[x].first][from[x].second]->rev->cap += f;
        x = from[x].first;
      }
      total += f;
    }
  }
