struct P{
  int x, y, z;
  P() : x(0), y(0), z(0) {}
  P(int x, int y, int z) : x(x), y(y), z(z) {}
  bool operator < (const P& p) const {
    if(x != p.x) return x < p.x;
    if(y != p.y) return y < p.y;
    return z < p.z;
  }
  bool operator == (const P& p) const {
    return x == p.x && y == p.y && z == p.z;
  }
  P operator - (const P& p) const {
    return P(x - p.x, y - p.y, z - p.z);
  }
};
typedef pair<P, P> L;
vector<L> input(){
  int N; cin >> N;
