unordered_set<LL> q;
LL n,m,rowblock;
bool vis[2000009];

void dfs(int x){
	for(int i:adj[x]){
		if(vis[i])continue;
		vis[i]=1;dfs(i);
	}
}

LL solve(int bc){//block count
	REP(i,2000009)adj[i].clear();
	vector<LL> orow2;
	REP(i,bc){
		for(LL j:orow){
			orow2.PB(j+rowblock*i);
		}
	}
	MS0(vis);
	int nn=0;
	REP(i,SZ(orow2)){
		LL ri=orow2[i];
		REP(j,7){
			if(q.find((ri*7+j)%m)!=q.end())vis[nn+j]=1;
		}
		REP(j,6){
			if((!vis[nn+j])&&(!vis[nn+j+1])){
				adj[nn+j].PB(nn+j+1);
				adj[nn+j+1].PB(nn+j);
			}
		}
		if(i){
			REP(j,7){
				if((!vis[nn-7+j])&&(!vis[nn+j])){
					adj[nn-7+j].PB(nn+j);
					adj[nn+j].PB(nn-7+j);
				}
			}
		}
		nn+=7;
	}
	int con=0;
	REP(i,nn){
		if(vis[i])continue;
		dfs(i);
		con++;
	}
	return con;
}

int main(){
	scanf("%lld%lld",&n,&m);
	DRI(qn);//find m value for m rows ? D:
	rowblock=m;
	if(m%7==0)rowblock/=7;
	REP(i,qn){
		DRI(x);
		q.insert(x);
		while(x<rowblock*7){
			LL ri=x/7;
			orow.PB(ri);
			x+=m;
			if(ri+1<rowblock)orow.PB(ri+1);
		}
	}
	orow.PB(0);orow.PB(rowblock-1);
	sort(ALL(orow));
	orow.resize(unique(ALL(orow))-orow.begin());
	if(n/rowblock<=3){
		printf("%lld\n",solve(n/rowblock));
	}
	else{
