int N, M;

int solve(vector<vector<int> > G){
    queue<pair<int,int>> Q;
    vector<int> used(N+2, 0);

    int count = 0;

    Q.push(make_pair(1,1));

    while(!Q.empty()){
        pair<int,int> p = Q.front(); Q.pop();
        int now = p.first;
        //cout<<now<<" <><> "<<p.second<<endl;
        if(used[now]){
            if(used[now] != p.second) return -1;
            else continue;
        }
//cout<<now<<" [][]  "<<p.second<<endl;
        used[now] = p.second;

        if(p.second == 1) count++;

        for(int y : G[now]){
            if(p.second == 1)Q.push(make_pair(y, p.second+1));
            else Q.push(make_pair(y, p.second-1));
        }
    }

    return count;
}

