int n, q;
vector<int> g[101000];
struct BIT {
  vector<int> t;
  int lim;
  void init(int mx) {
    lim = mx;
    t.resize(mx + 3);
    for (int i = (0); i < (t.size()); i++) t[i] = 0;
  }
  void modify(int idx, int val) {
    if (!idx) return;
    for (; idx; idx -= idx & -idx) t[idx] += val;
  }
  int query(int idx) {
    int ret = 0;
    if (!idx) return 0;
    for (; idx <= lim; idx += idx & -idx) ret += t[idx];
    return ret;
  }
};
BIT rs;
vector<BIT> seg;
int dep[101000], id[101000], m, len[101000];
int main() {
  ios::sync_with_stdio(false);
  cin >> n >> q;
  int u, v, fa, tot;
  for (int i = (0); i < (n - 1); i++) {
    cin >> u >> v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  dep[1] = m = id[1] = 0;
  for (int i = (0); i < (g[1].size()); i++) {
    int v = g[1][i];
    ++m;
    u = v, fa = 1;
    tot = 0;
    bool flag = true;
    while (flag) {
      tot++;
      dep[u] = dep[fa] + 1;
      id[u] = m;
      flag = false;
      for (int j = (0); j < (g[u].size()); j++) {
        if (g[u][j] == fa) continue;
        fa = u;
        u = g[u][j];
        flag = true;
      }
    }
    BIT tmp;
    tmp.init(tot);
    seg.push_back(tmp);
  }
  int op, x, d, ans1 = 0;
  rs.init(n);
  while (q--) {
    cin >> op;
    if (op == 0) {
      cin >> v >> x >> d;
      if (v != 1) {
        seg[id[v] - 1].modify(dep[v], x);
        int res = d - dep[v];
        if (res >= 0) {
          rs.modify(res, x);
          seg[id[v] - 1].modify(min(res, dep[v]), -x);
          ans1 += x;
        } else if (res < 0) {
          seg[id[v] - 1].modify(dep[v] - d - 1, -x);
        }
      } else {
        rs.modify(d, x);
        ans1 += x;
      }
    } else {
      cin >> v;
      if (v == 1) {
        cout << ans1 << endl;
      } else {
        cout << rs.query(dep[v]) + seg[id[v] - 1].query(dep[v]) << endl;
      }
    }
