const int N = 105;
const long long INF = 0x3f3f3f3f3f3f3f3f;
int n, m, a[N], b[N];
void solve(int n, int* a) {
  if (n == 1)
    a[1] = 1;
  else if (n == 2)
    a[1] = 3, a[2] = 4;
  else if (n & 1) {
    for (int i = 1; i < n - 1; ++i) a[i] = 1;
    a[n - 1] = 2;
    a[n] = n / 2 + 1;
  } else {
    for (int i = 1; i < n; ++i) a[i] = 1;
    a[n] = n / 2 - 1;
  }
}
int main() {
  cin >> n >> m;
  solve(n, a);
