int W, H, S, T;
void update(int sy, int sx, vector<vector<int> > &v) {
  queue<pair<int, pair<int, int> > > open;
  open.push(pair<int, pair<int, int> >(0, pair<int, int>(sy, sx)));
  v[sy][sx] = 0;
  while (!open.empty()) {
    pair<int, pair<int, int> > pp = open.front();
    open.pop();
    int y = pp.second.first, x = pp.second.second, n = pp.first,
        t = (y % 2 == 0);
    for (int i = 0; i < (int)(6); ++i) {
      int ny = y + my[t][i], nx = x + mx[t][i];
      if (ny <= 0 || nx <= 0 || ny > H || nx > W || v[ny][nx] <= n + 1)
        continue;
      v[ny][nx] = n + 1;
      open.push(pair<int, pair<int, int> >(n + 1, pair<int, int>(ny, nx)));
    }
  }
}
int count(int sy, int sx, vector<vector<int> > &v) {
  queue<pair<int, pair<int, int> > > open;
  open.push(pair<int, pair<int, int> >(0, pair<int, int>(sy, sx)));
  vector<vector<bool> > visited(H + 1, vector<bool>(W + 1, 0));
  visited[sy][sx] = 1;
  int res = 0;
  while (!open.empty()) {
    pair<int, pair<int, int> > pp = open.front();
    open.pop();
    int y = pp.second.first, x = pp.second.second, n = pp.first,
        t = (y % 2 == 0);
    if (v[y][x] > n) ++res;
    for (int i = 0; i < (int)(6); ++i) {
      int ny = y + my[t][i], nx = x + mx[t][i];
      if (ny <= 0 || nx <= 0 || ny > H || nx > W || v[ny][nx] <= n + 1 ||
          visited[ny][nx])
        continue;
      visited[y][x] = 1;
      open.push(pair<int, pair<int, int> >(n + 1, pair<int, int>(ny, nx)));
    }
  }
  return res;
}
