int Get(int u) {
  if (mapa.count(u)) return mapa[u];
  mapa[u] = gid;
  gid++;
  return gid - 1;
}
map<int, int> dp;
int solve(int u) {
  if (u <= 1) return dp[u] = 0;
  if (dp.count(u)) return dp[u];
  int idx = -1;
  for (int i = 30; i >= 0; --i) {
    if ((1 << i) <= u) {
      idx = i;
      break;
    }
  }
  int v = u;
  int w = 0;
  int t = 0;
  int sh = idx;
  set<int> save;
  while (idx != 0) {
    v -= u & (1 << idx);
    t += u & (1 << idx);
    w = v | (t >> sh);
    save.insert(solve(w));
    --idx;
    --sh;
  }
  for (int i = 0;; ++i) {
    if (!save.count(i)) return dp[u] = i;
  }
}
