public class _1364D {
	static ArrayList<Integer>[] adj;
	static Stack<Integer> stack = new Stack<Integer>();
	static int mincycle = 1000000;
	static int[] visited;
	static int counter = 0, index = 1;
	static boolean found = false;
	static int[] ans;
	static int size = 0, y = 0;
	static boolean foundodd = false;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int k = sc.nextInt();
		adj = new ArrayList[n+1];
		visited = new int[n+1];
		Arrays.fill(visited, -1);
		for (int i = 0; i <= n; i++) {
			adj[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < m; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			adj[a].add(b);
			adj[b].add(a);
		}
		findCycle(1, 0);
		if (mincycle <= k) {
			ans = new int[mincycle];
			counter = 0;
			Arrays.fill(visited, -1);
			again(index, 0);
			System.out.println(2);
			for (int i = 0; i < mincycle; i++) {
				System.out.print(ans[i]+" ");
			}
			return;
		}
		Arrays.fill(visited, -1);
		System.out.println(1);
		y = (int) (Math.ceil(1.0*k/2));
		ans = new int[y];
		independent(index, 0, true);
		if (mincycle % 2 == 1) {
			for (int i = 1; i <= n; i++) {
				if (visited[i] == -1) {
					ans[size-1] = i;
					break;
				}
			}
		}
		for (int i = 0; i < y; i++) {
			System.out.print(ans[i]+" ");
		}
	}

	public static void independent(int x, int par, boolean contain) {
		if (size == y) {
			return;
		}
		if (contain) {
			if (mincycle % 2 == 1) {
				if (size == mincycle/2) {
					foundodd = true;
					return;
				}
			}
			ans[size] = x;
			size++;
		}
		visited[x] = 0;
		for (int u: adj[x]) {
			if (u != par) {
				independent(u, x, !contain);
			}
			if (foundodd) {
				return;
			}
			if (size == y) {
				return;
			}
		}
		if (foundodd) {
			return;
		}
		if (size == y) {
			return;
		}
		visited[x] = -1;
	}

	public static void findCycle(int x, int par) {
		if (visited[x] > -1) {
			if (counter-visited[x] < mincycle) {
				mincycle = counter-visited[x];
				index = x;
			}
			return;
		}
		visited[x] = counter;
		counter++;
		stack.push(x);
		for (int u: adj[x]) {
			if (u != par) {
				findCycle(u, x);
			}
		}
		counter--;
		visited[x] = -1;
		stack.pop();
	}

	public static void again(int x, int par) {
		if (visited[x] > -1) {
			if (counter == mincycle) {
				while (!stack.isEmpty()) {
					ans[size] = stack.pop();
					size++;
				}
				found = true;
			}
			return;
		}
		stack.push(x);
		visited[x] = counter;
		counter++;
		for (int u: adj[x]) {
			if (found) {
				break;
			}
			if (u != par) {
				again(u, x);
			}
		}
		if (found) {
			return;
		}
		counter--;
		visited[x] = -1;
		stack.pop();
	}

}

