const int maxn = 2005;
int dis[maxn];
vector<int> tree[maxn];
void dfs(int u, int p, int d) {
  dis[u] = d;
  for (int i = 0; i < ((int)((tree[u]).size())); i++) {
    int v = tree[u][i];
    if (v == p) continue;
    dfs(v, u, d + 1);
  }
}
int t, n, k;
int main() {
  scanf("%d", &n);
  int k;
  scanf("%d", &k);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    scanf("%d %d", &u, &v);
    --u;
    --v;
    tree[u].push_back(v);
    tree[v].push_back(u);
  }
  int ans = 1 << 30;
  for (int i = 0; i < n; ++i) {
    int tres = 0;
    memset(dis, 0, sizeof(dis));
    dfs(i, -1, 0);
    if (k & 1) {
      int cap = k - k / 2;
      int b = 0, e = 0;
      for (int j = 0; j < n; ++j) {
        if (j == i) continue;
        if (dis[j] == cap) ++e;
        if (dis[j] > cap) ++b;
      }
      ans = min(ans, b + max(0, e - 1));
    } else {
      int e = 0;
      for (int j = 0; j < n; ++j) {
        if (dis[j] > k / 2) ++tres;
        if (dis[j] == k / 2) ++e;
      }
      if (e == 0)
        ans = min(ans, max(0, tres - 1));
      else
        ans = min(ans, tres);
    }
  }
  cout << ans << "\n";
}

