#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1e5 + 50;
int fa[MAXN], p[MAXN], high[MAXN], a[MAXN], n, cnt = 0;
vector<int> e[MAXN], ans;
inline int read() {
  int res = 0;
  char ch;
  ch = getchar();
  while (!isdigit(ch)) ch = getchar();
  while (isdigit(ch)) {
    res = (res << 3) + (res << 1) + ch - 48;
    ch = getchar();
  }
  return res;
}
inline bool cmp(int i, int j) { return high[i] < high[j]; }
void dfs1(int u) {
  if (!e[u].size()) {
    high[u] = 1;
    return;
  }
  for (int i = 0; i < e[u].size(); i++) dfs1(e[u][i]);
  int maxx = 0;
  for (int i = 0; i < e[u].size(); i++) maxx = max(maxx, high[e[u][i]]);
  high[u] = maxx + 1;
  return;
}
void dfs2(int u) {
  a[++cnt] = u;
  sort(e[u].begin(), e[u].end(), cmp);
  for (int i = 0; i < e[u].size(); i++) dfs2(e[u][i]);
  return;
}
int main() {
  n = read();
  for (int i = 1; i < n; i++) {
    int t;
    t = read();
    e[t].push_back(i);
    fa[i] = t;
  }
  dfs1(0);
  dfs2(0);
  for (int i = 1; i <= n; i++) printf("%d%c", a[i], i == n ? '\n' : ' ');
  for (int i = 2; i <= n; i++) p[a[i]] = a[i - 1];
  for (int i = 2; i <= n; i++) {
    int u = a[i];
    while (p[u] != fa[u]) {
      ans.push_back(u);
      p[u] = p[p[u]];
    }
  }
  printf("%d\n", ans.size());
  for (int i = 0; i < ans.size(); i++) cout << ans[i] << " ";
  return 0;
}

import java.io.*;
import java.util.*;
public class Main
{
	public static void main(String[] args)throws Exception
	{
	    BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
	    PrintWriter pw=new PrintWriter(System.out);
	    int t=Integer.parseInt(br.readLine());
	    while(t-->0)
	    {
	        String s[]=(br.readLine()).split(" ");
	        double c=Double.parseDouble(s[0]);
	        double m=Double.parseDouble(s[1]);
	        double p=Double.parseDouble(s[2]);
	        double v=Double.parseDouble(s[3]);
	        double sum=0.0;
	        LinkedList<Node> q=new LinkedList<Node>();
	        Node root=new Node(c,m,p,1,1);//prod=1
	        sum+=p;
	        q.add(root);
	        while(q.size()>0)
	        {
	            int len=q.size();
	            while(len-->0)
	            {
	                Node node=q.poll();
	                if(node.C>0.000001)
	                {
	                    double minus=Math.min(node.C,v);
	                    double c1=node.C-minus;
	                    double m1=node.M+minus/2.0;
	                    double p1=node.P+minus/2.0;
	                    if(node.M<=0.000001)
	                    {
	                        m1=0.0;
	                        p1=node.P+minus;
	                    }
	                    Node node2=new Node(c1,m1,p1,(node.prod)*node.C,node.lev+1);
	                    sum+=(node.lev+1)*(node.prod)*(node.C)*p1;
	                    q.add(node2);
	                }
	                if(node.M>0.000001)
	                {
	                    double minus=Math.min(node.M,v);
	                    double m1=node.M-minus;
	                    double c1=node.C+minus/2.0;
	                    double p1=node.P+minus/2.0;
	                    if(node.C<=0.000001)
	                    {
	                        c1=0.0;
	                        p1=node.P+minus;
	                    }
	                    Node node2=new Node(c1,m1,p1,(node.prod)*node.M,node.lev+1);
	                    sum+=(node.lev+1)*(node.prod)*(node.M)*p1;
	                    q.add(node2);
	                }
	            }
	        }
	        pw.println(sum);
	    }
	    pw.flush();
	}
}
class Node 
{
    double C,M,P,prod;
    int lev;
    public Node(double C,double M,double P,double prod,int lev)
    {
        this.C=C;
        this.M=M;
        this.P=P;
        this.lev=lev;
        this.prod=prod;
    }
}

