    int temp,now;
    now=a[0]+a[2]+a[5];
    temp=now/10;
    now%=10;
    if(now!=a[8])return ;
    now=temp+a[1]+a[4];
    temp=now/10;
    now%=10;
    if(now!=a[7])return ;
    now=temp+a[3];
    temp=now/10;
    now%=10;
    if(temp>0)return ;
    if(now!=a[6])return ;
    ans++;
    return ;
}
