    else{
        if(a[now]==-1){
            for(int i=1;i<10;i++)if(used[i]==0){
                used[i]=1;
                a[now]=i;
                dfs(now+1);
                used[i]=0;
            }
            a[now]=-1;
        }
        else dfs(now+1);
