	static boolean multiples(long x , long  y )
	{

		if( gcd( x ,y ) == 1 )
		return false;

		else return true; 
	}


	static long gcd( long x , long y )
	{
		if( x == 0 ) return y ; 
		else if ( y == 0 ) return x ; 

		else if( x < y )
			return gcd( y%x , x );

		else
			return gcd( x%y, y ) ;
	}

