#include <bits/stdc++.h>
using namespace std;
int n, m, q;
vector<int> enter, color;
vector<vector<int> > d = {{0, -1, 0, 1}, {-1, 0, 1, 0}};
int main() {
  scanf("%d%d%d", &n, &m, &q);
  vector<vector<bool> > a(n, vector<bool>(m));
  for (int i = 0; i < n; ++i) {
    char c;
    for (int j = 0; j < m; ++j) {
      scanf(" %c", &c);
      a[i][j] = c == '1';
    }
  }
  enter = vector<int>(n * m, -1);
  color = vector<int>(n * m, -1);
  bool stable = true;
  vector<bool> vis(n * m);
  deque<int> bfs;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
      int idx = i * m + j;
      for (int k = 0; k < 4; ++k) {
        int ni = i + d[0][k], nj = j + d[1][k];
        if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
        int nidx = ni * m + nj;
        if (a[i][j] == a[ni][nj]) {
          enter[idx] = 0;
          enter[nidx] = 0;
          color[idx] = a[i][j];
          color[nidx] = a[i][j];
          if (!vis[idx]) {
            vis[idx] = true;
            bfs.push_back(idx);
          }
          if (!vis[nidx]) {
            vis[nidx] = true;
            bfs.push_back(nidx);
          }
          stable = false;
        }
      }
    }
  while (!bfs.empty()) {
    int idx = bfs.front();
    bfs.pop_front();
    int i = idx / m, j = idx % m;
    for (int k = 0; k < 4; ++k) {
      int ni = i + d[0][k], nj = j + d[1][k];
      if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
      int nidx = ni * m + nj;
      if (enter[nidx] != -1 || a[ni][nj] != (color[idx] + enter[idx] + 1) % 2)
        continue;
      enter[nidx] = enter[idx] + 1;
      color[nidx] = color[idx];
      bfs.push_back(nidx);
    }
  }
  string ans;
  while (q--) {
    int i, j;
    long long p;
    scanf("%d%d%lld", &i, &j, &p);
    int state;
    if (stable)
      state = a[i - 1][j - 1];
    else {
      int idx = (i - 1) * m + j - 1;
      if (p < enter[idx])
        state = a[i - 1][j - 1];
      else
        state = (color[idx] + p) % 2;
    }
    ans += to_string(state) + "\n";
  }
  printf("%s", ans.c_str());
}

