              (f[i + 1][j - 1][k] += t * j) %= MO;
            }
            (f[i + 1][j][k + 1] += t) %= MO;
          } else {
            (f[i + 1][j + 1][k] += t) %= MO;
            if (k) {
              (f[i + 1][j][k - 1] += t) %= MO;
            }
            (f[i + 1][j][k + 1] += t) %= MO;
          }
