vector<int> g2[MAXN + 5];
int in[MAXN + 5];
int out[MAXN + 5];
int res;
int trr;
int seg[4 * MAXN + 5];
void init(int node, int l, int r) {
  seg[node] = 0;
  if (l == r) return;
  int mid = (l + r) / 2;
  init(node * 2, l, mid);
  init(node * 2 + 1, mid + 1, r);
}
int query(int node, int l, int r, int tl, int tr) {
  if (tl > r || l > tr) return 0;
  if (tl <= l && r <= tr) {
    return seg[node];
  }
  int mid = (l + r) / 2;
  int a = query(node * 2, l, mid, tl, tr);
  int b = query(node * 2 + 1, mid + 1, r, tl, tr);
  if (in[a] >= in[b]) return a;
  return b;
}
void upd(int node, int l, int r, int x, int val) {
  if (l == r) {
    seg[node] = val;
    return;
  }
  int mid = (l + r) / 2;
  if (x <= mid) {
    upd(node * 2, l, mid, x, val);
  } else
    upd(node * 2 + 1, mid + 1, r, x, val);
  if (in[seg[node * 2]] >= in[seg[node * 2 + 1]])
    seg[node] = seg[node * 2];
  else
    seg[node] = seg[node * 2 + 1];
}
int n;
int chroot[MAXN + 5];
int prr[MAXN + 5];
int findparent(int v) {
  int k = prr[v];
  while (k) {
    int x = chroot[k];
    int g = query(1, 1, 2 * n, in[x], in[k]);
    if (g) {
      return g;
    }
    k = prr[x];
  }
  return 0;
}
void dodaj(int v) {
  int par = findparent(v);
  upd(1, 1, 2 * n, in[v], v);
  q.insert({in[v], v});
  if (kor[par]) {
    kor[par] = 0;
    kor[v] = 1;
    return;
  }
  auto c = q.lower_bound({in[v] + 1, -1});
  if (c == q.end() || (c->first > out[v])) {
    kor[v] = 1;
    trr++;
    return;
  }
}
void brisi(int v) {
  upd(1, 1, 2 * n, in[v], 0);
  q.erase({in[v], v});
  if (!kor[v]) return;
  kor[v] = 0;
  trr--;
  int par = findparent(v);
  if (!par) return;
  auto c = q.lower_bound({in[par] + 1, -1});
  if (c == q.end() || (c->first <= out[par])) {
    kor[par] = 1;
    trr++;
    return;
  }
}
void dfs1(int v) {
  dodaj(v);
  res = max(res, trr);
  for (auto c : g1[v]) dfs1(c);
  brisi(v);
}
int tjm;
int sz[MAXN + 5];
void dfs2(int v) {
  in[v] = ++tjm;
  if (g2[v].empty()) {
    out[v] = ++tjm;
    return;
  }
  int mxx = 0;
  for (auto c : g2[v]) {
    if (sz[c] > sz[mxx]) mxx = c;
  }
  chroot[mxx] = chroot[v];
  dfs2(mxx);
  for (auto c : g2[v]) {
    if (c == mxx) continue;
    chroot[c] = c;
    dfs2(c);
  }
  out[v] = ++tjm;
}
void dfs_sz(int v) {
  sz[v] = 1;
  for (auto c : g2[v]) {
    dfs_sz(c);
    sz[v] += sz[c];
  }
}
