#include <bits/stdc++.h>
using namespace std;
struct dsu {
  vector<int> chot;
  vector<int> time;
  int n;
  dsu(int n) : n(n) {
    chot.resize(n + 1, -1);
    time.resize(n + 1, -1);
  }
  int find(int u) { return chot[u] < 0 ? u : chot[u] = find(chot[u]); }
  void combine(int u, int v) {
    if ((u = find(u)) != (v = find(v))) {
      if (-chot[u] < -chot[v]) swap(u, v);
      chot[u] += chot[v];
      chot[v] = u;
    }
  }
};
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
