  for (int i = 1; i <= n; i++) {
    string s;
    cin >> s;
    for (int j = 1; j <= m; j++) a[i][j] = (s[j - 1] == '1');
  }
  dsu d(n * m);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (i < n && a[i][j] == a[i + 1][j])
        d.combine(rein(i, j), rein(i + 1, j));
      if (j < m && a[i][j] == a[i][j + 1])
        d.combine(rein(i, j), rein(i, j + 1));
    }
  }
  deque<pair<int, int>> D;
  vector<vector<bool>> kt(n + 2, vector<bool>(m + 2));
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (-d.chot[d.find(rein(i, j))] > 1) {
        if (d.find(rein(i, j)) == rein(i, j)) d.time[rein(i, j)] = 0;
        D.emplace_back(i, j), kt[i][j] = true;
      }
    }
  }
  for (int i = 0; i <= n + 1; i++) kt[i][0] = kt[i][m + 1] = true;
  for (int j = 1; j <= m; j++) kt[0][j] = kt[n + 1][j] = true;
  while ((int)D.size()) {
    pair<int, int> x = D.front();
    D.pop_front();
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++) {
        if (dx * dx + dy * dy == 1) {
          int nx = x.first + dx;
          int ny = x.second + dy;
          if (kt[nx][ny]) continue;
          D.emplace_back(nx, ny);
          kt[nx][ny] = true;
          d.time[d.find(rein(nx, ny))] =
              d.time[d.find(rein(x.first, x.second))] + 1;
        }
      }
    }
  }
  while (q--) {
    int x, y;
    long long time;
    cin >> x >> y >> time;
    int lim = d.time[d.find(rein(x, y))];
    if (lim == -1 || time < lim)
      cout << a[x][y] << "\n";
    else {
      int ans = a[x][y];
      if ((time - lim) & 1) ans ^= 1;
      cout << ans << "\n";
    }
  }
}

