long long phi(long long n) {
  long long result = n;
  for (long long i = 2; i * i <= n; ++i)
    if (n % i == 0) {
      while (n % i == 0) n /= i;
      result -= result / i;
    }
  if (n > 1) result -= result / n;
  return result;
}
long long pow(long long p) {
  if (p == 0) {
    return 1;
  }
  if (p == 1) {
    return x;
  }
  long long temp = pow(p / 2);
  if (p % 2) {
    return (((temp * temp) % m) * x) % m;
  }
  return ((temp * temp) % m);
}
signed main() {
