int binsearch(vector<long long> x, long long y, int z) {
  int l = -1, r = z, mid;
  while (r - l > 1) {
    mid = (l + r) / 2;
    if (y >= x[mid])
      l = mid;
    else
      r = mid;
  }
  return r;
}
