    /* ------------------- Binary Search ------------------- */
    private static int floorSearch(int[] arr, int st, int ed, int tar) {
        int ans = -1;
        while (st <= ed) {
            int mid = ((ed - st) >> 1) + st;
            if (arr[mid] <= tar) {
                ans = mid;
                st = mid + 1;
            } else {
                ed = mid - 1;
            }
        }
        return ans;
    }

    private static int ceilingSearch(int[] arr, int st, int ed, int tar) {
        int ans = -1;
        while (st <= ed) {
            int mid = ((ed - st) >> 1) + st;
            if (arr[mid] < tar) {
                st = mid + 1;
            } else {
                ans = mid;
                ed = mid - 1;
            }
        }
        return ans;
    }

    /* ------------------- Power Function ------------------- */
    public static long pow(long x, long y) {
        long res = 1;
		while (y > 0) {
            if ((y & 1) != 0) {
                res = (res * x);
				y--;
			}
			x = (x * x);
			y >>= 1;
		}
		return res;
	}

	public static long powMod(long x, long y, int mod) {
        long res = 1;
		while (y > 0) {
            if ((y & 1) != 0) {
                res = (res * x) % mod;
				y--;
			}
			x = (x * x) % mod;
			y >>= 1;
		}
		return res % mod;
	}

    /* ------------------- Disjoint Set(Union and Find) ------------------- */
    private static class DSU {
		public int[] parent, rank;
		DSU(int N) {
			parent = new int[N];
			rank = new int[N];
			for (int i = 0; i < N; i++) {
				parent[i] = i;
                rank[i] = 1;
            }
		}
		public int find(int a) {
			if (parent[a] == a) {
				return a;
            }
            return parent[a] = find(parent[a]);
		}
		public boolean union(int a, int b) {
			int parA = find(a), parB = find(b);
			if (parA == parB) return false;
			if (rank[parA] > rank[parB]) {
                parent[parB] = parA;
            } else if (rank[parA] < rank[parB]) {
                parent[parA] = parB;
            } else {
                parent[parA] = parB;
                rank[parB]++;
            }
            return true;
		}
	}

    /* ------------------- Scanner class for input ------------------- */

    private static class FasterScanner {
		private InputStream stream;
		private byte[] buffer = new byte[1024];
		private int curChar, numChars;
		private SpaceCharFilter filter;

		public FasterScanner() {
            // default
			this.stream = System.in;
		}

		public FasterScanner(InputStream stream) {
			this.stream = stream;
		}

		private int readChar() {
			if (numChars == -1) {
				throw new InputMismatchException();
            }
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException(e.getMessage());
				}
				if (numChars <= 0) {
					return -1;
                }
			}
			return buffer[curChar++];
		}

		private boolean isWhiteSpace(int c) {
			if (filter != null) {
				return filter.isWhiteSpace(c);
            }
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		private boolean isNewLine(int ch) {
			if (filter != null) {
				return filter.isNewLine(ch);
            }
			return ch == '\r' || ch == '\n' || ch == -1;
		}

        public char nextChar() {
            int ch = readChar();
            char res = '\0';
            while (isWhiteSpace(ch)) {
                ch = readChar();
            }
            do {
                res = (char)ch;
                ch = readChar();
            } while (!isWhiteSpace(ch));
            return res;
        }

		public String next() {
			int ch = readChar();
            StringBuilder res = new StringBuilder();
			while (isWhiteSpace(ch)) {
				ch = readChar();
            }
			do {
				res.appendCodePoint(ch);
				ch = readChar();
			} while (!isWhiteSpace(ch));
			return res.toString();
		}

		public String nextLine() {
			int ch = readChar();
            StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(ch);
				ch = readChar();
			} while (!isNewLine(ch));
			return res.toString();
		}

		public int nextInt() {
			int ch = -1, sgn = 1, res = 0;
            do {
                ch = readChar();
            } while (isWhiteSpace(ch));
			if (ch == '-') {
				sgn = -1;
				ch = readChar();
			}
			do {
				if (ch < '0' || ch > '9') {
					throw new InputMismatchException("not a number");
                }
				res = (res * 10) + (ch - '0');
				ch = readChar();
			} while (!isWhiteSpace(ch));

			return res * sgn;
		}

		public long nextLong() {
			int ch = -1, sgn = 1;
            long res = 0L;
            do {
                ch = readChar();
            } while (isWhiteSpace(ch));
			if (ch == '-') {
				sgn = -1;
				ch = readChar();
			}
			do {
				if (ch < '0' || ch > '9') {
					throw new InputMismatchException("not a number");
                }
				res = (10L * res) + (ch - '0');
				ch = readChar();
			} while (!isWhiteSpace(ch));

			return 1L * res * sgn;
		}

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        /* for custom delimiters */
		public interface SpaceCharFilter {
			public boolean isWhiteSpace(int ch);
			public boolean isNewLine(int ch);
		}
	}
