long long N, S, startS, BC;
long long P[MAXN], maxH;
vector<long long> VH[MAXN];
void output() {
  cout << "Yes\n";
  for (int i = 2; i <= N; i++) {
    cout << P[i] << (i == N ? "\n" : " ");
  }
}
void outP() {
  for (int i = 1; i <= N; i++) {
    cerr << P[i] << " ";
  }
  cerr << "\n";
}
int main() {
  ios_base::sync_with_stdio(0);
  cin >> N >> S;
  if (S < 2 * N - 1 || S > ((N + 1) * (N)) / 2) {
    cout << "No\n";
    return 0;
  }
  int a = 1, b = N - 1, c;
  while (a <= b) {
    c = (a + b) / 2;
    long long p = 1, l = N, s = 0;
    for (int i = 1; l > 0; i++) {
      s += min(l, p) * i;
      l -= min(l, p);
      p *= c;
    }
    if (s <= S) {
      BC = c;
      startS = s;
      b = c - 1;
    } else {
      a = c + 1;
    }
  }
  long long p = BC;
  long long start = 2;
  P[1] = -1;
  bool ok = true;
  for (int i = 2; ok; i++) {
    for (int j = start; j < start + p; j++) {
      if (j == N + 1) {
        ok = false;
        break;
      }
      maxH = i;
      VH[i].push_back(j);
      P[j] = start - p / BC + (j - start) / BC;
    }
    if (!ok) break;
    start += p;
    p *= BC;
  }
  S -= startS;
  if (S == 0) {
    output();
    return 0;
  }
  for (int i = maxH; i >= 1; i--) {
    while (VH[i].size() > 1) {
      int v = VH[i][(int)VH[i].size() - 1];
      VH[i].pop_back();
      if (maxH - i + 1 < S) {
        S -= maxH - i + 1;
        P[v] = VH[maxH][0];
        maxH++;
        VH[maxH].push_back(v);
      } else {
        P[v] = VH[i + S - 1][0];
        i = 0;
        break;
      }
    }
  }
  output();
}

