void pre() {
  int i, j;
  for (i = n - 1; i >= 1; i--) {
    if (i == n - 1) {
      mnara[i] = i - ara[i];
      mnid[i] = n - 1;
      continue;
    } else {
      if (i - ara[i] < mnara[i + 1]) {
        mnara[i] = i - ara[i];
        mnid[i] = i;
      } else if (i - ara[i] == mnara[i + 1]) {
        mnara[i] = i - ara[i];
        mnid[i] = i;
      } else {
        mnara[i] = mnara[i + 1];
        mnid[i] = mnid[i + 1];
