int centroid(int v, int prev, int total) {
  int heaviest = 0, mx = INT_MIN;
  for (int i = 0; i < tree[v].size(); i++) {
    int u = tree[v][i];
    if (!centroidMarked[u] && u != prev) {
      if (size[u] > mx) {
        mx = size[u], heaviest = u;
      }
    }
  }
  if (heaviest == 0 || mx <= total / 2)
    return v;
  else
    return centroid(heaviest, v, total);
}
pair<int, int> decomposeTree(int v) {
  int total = 0;
  parent[v] = -1;
  deep[v] = 0;
  dfs(v, -1, &total, 0);
  int cen = centroid(v, -1, total);
  int distToV = deep[cen] - deep[v];
  centroidMarked[cen] = 1;
  for (int i = 0; i < tree[cen].size(); i++) {
    int u = tree[cen][i];
    if (!centroidMarked[u]) {
      pair<int, int> subCen = decomposeTree(u);
      int sub = subCen.first;
      dist[sub] = 1 + subCen.second;
      cenParent[sub] = cen;
      centroidTree[cen].push_back(sub), centroidTree[sub].push_back(cen);
    }
  }
  return {cen, distToV};
}
