void preprocessmm() {
  for (int i = 1; i <= n; i++) {
    for (int j = 0; 1 << j <= n; j++) Pa1[i][j] = -1;
  }
  for (int i = 1; i <= n; i++) {
    sum1[i][0] = T[i] == -1 ? 0 : co[i];
    Pa1[i][0] = T[i];
  }
  for (int j = 1; 1 << j <= n; j++) {
    for (int i = 1; i <= n; i++) {
      if (Pa1[i][j - 1] != -1) {
        int i2 = Pa1[i][j - 1];
        sum1[i][j] = sum1[i][j - 1] + sum1[i2][j - 1];
        Pa1[i][j] = Pa1[Pa1[i][j - 1]][j - 1];
      } else
        sum1[i][j] = sum1[i][j - 1];
    }
  }
}
int lca1mm(int u, int v, int &su) {
  int log, i;
  su = 0;
  if (L[u] < L[v]) swap(u, v);
  if (!L[u]) {
    return u;
  }
  for (log = 0; 1 << log <= L[u]; log++)
    ;
  log--;
  for (i = log; i >= 0; i--) {
    if (L[u] - (1 << i) >= L[v]) {
      su += sum1[u][i];
      u = Pa1[u][i];
    }
  }
  if (u == v) return u;
  for (i = log; i >= 0; i--) {
    if (Pa1[u][i] != -1 && Pa1[u][i] != Pa1[v][i]) {
      su += sum1[u][i];
      su += sum1[v][i];
      u = Pa1[u][i], v = Pa1[v][i];
    }
  }
  su += co[u] + co[v];
  return T[u];
}
void update(int x, int w) {
  int sum;
  if (eachf[x] != -1) {
    int w1 = eachf[x];
    ans[w1] -=
        cost[w1] * cost[w1] * (totNum[w1] * dep[x] + totDep[w1] - dep[x]);
    ans[w1] += 2 * cost[w1] * c * dep[x];
    int tmpx = x, prev = -1;
    long long dd = 0;
    while (tmpx != -1) {
      lca1mm(x, tmpx, sum);
      ans[w1] += cost[w1] * cost[w1] *
                 (sum * (h[w1][tmpx] - (prev == -1 ? 0 : h[w1][prev])) +
                  (a[w1][tmpx] - (prev == -1 ? 0 : b[w1][prev])));
      prev = tmpx, tmpx = cenParent[tmpx];
    }
    totNum[w1]--, totDep[w1] -= dep[x];
    tmpx = x;
    dd = 0;
    while (tmpx != -1) {
      h[w1][tmpx]--;
      lca1mm(x, tmpx, sum);
      a[w1][tmpx] -= sum;
      if (cenParent[tmpx] != -1) {
        lca1mm(x, cenParent[tmpx], sum);
        b[w1][tmpx] -= sum;
      }
      tmpx = cenParent[tmpx];
    }
  }
  ans[w] += cost[w] * cost[w] * ((totNum[w] + 1) * dep[x] + totDep[w]);
  ans[w] -= 2 * cost[w] * c * dep[x];
  int tmpx = x, prev = -1;
  long long dd = 0;
  while (tmpx != -1) {
    lca1mm(x, tmpx, sum);
    ans[w] -= cost[w] * cost[w] *
              (sum * (h[w][tmpx] - (prev == -1 ? 0 : h[w][prev])) +
               (a[w][tmpx] - (prev == -1 ? 0 : b[w][prev])));
    prev = tmpx, tmpx = cenParent[tmpx];
  }
  totNum[w]++, totDep[w] += dep[x];
  tmpx = x;
  dd = 0;
  while (tmpx != -1) {
    h[w][tmpx]++;
    lca1mm(x, tmpx, sum);
    a[w][tmpx] += sum;
    if (cenParent[tmpx] != -1) {
      lca1mm(x, cenParent[tmpx], sum);
      b[w][tmpx] += sum;
    }
    tmpx = cenParent[tmpx];
  }
  eachf[x] = w;
}
