long long int solve(vector<long long int>& vec, long long int n) {
  long long int sum = accumulate(vec.begin(), vec.end(), 0);
  long long int eq = sum / n;
  long long int rem = sum % n;
  long long int ze = n - rem;
  if (rem == 0) return 0;
  return ze * rem * 1ll;
}
