const int N = 1E6 + 100;
char l[N], r[N], ss[N];
int K, n;
int mp[100];
bool used[100];
bool solved;
void go(int cur, bool limit_l, bool limit_r) {
  if (cur == n || (!limit_l && !limit_r)) solved = true;
  if (solved) return;
  int& s = mp[ss[cur] - 'a'];
  if (s != -1) {
    char ch = s + 'a';
    if ((limit_l && ch < l[cur]) || (limit_r && ch > r[cur])) return;
    go(cur + 1, limit_l && ch == l[cur], limit_r && ch == r[cur]);
  } else {
    for (decay<decltype('a' + K)>::type ch = ('a'), _ch = ('a' + K); ch < _ch;
         ++ch) {
      s = ch - 'a';
      if (used[s] || (limit_l && ch < l[cur]) || (limit_r && ch > r[cur]))
        continue;
      used[s] = true;
      go(cur + 1, limit_l && ch == l[cur], limit_r && ch == r[cur]);
      if (solved) return;
      used[s] = false;
    }
    s = -1;
  }
}
int main() {
  int T;
  cin >> T;
  while (T--) {
    cin >> K;
    scanf("%s%s%s", ss, l, r);
    n = strlen(ss);
    memset(mp, -1, sizeof mp);
    memset(used, 0, sizeof used);
    solved = false;
    go(0, true, true);
    if (!solved)
      puts("NO");
    else {
      puts("YES");
      ;
      ;
      for (decay<decltype(K)>::type i = (0), _i = (K); i < _i; ++i)
        if (mp[i] == -1)
          for (decay<decltype(K)>::type j = (0), _j = (K); j < _j; ++j)
            if (!used[j]) {
              mp[i] = j;
              used[j] = true;
              break;
            };
      ;
      for (decay<decltype(K)>::type i = (0), _i = (K); i < _i; ++i)
        putchar(mp[i] + 'a');
      puts("");
    }
  }
}

