struct Elm {
  int v;
  Elm *nxt;
  Elm(): v(), nxt() {}
  Elm(int _v): v(_v), nxt() {}
  Elm(int _v, Elm *_nxt): v(_v), nxt(_nxt) {}
};

static Elm buf[MAX_N], *bpt = buf;

struct SList {
  Elm *head, *tail;
  int sz;
  SList(): head(), tail(), sz(0) {}

  void clear() { tail = head = NULL, sz = 0; }

  int size() { return sz; }
  bool empty() { return (sz == 0); }
  int front() { return (head != NULL) ? head->v : -1; }

  void add(int v) {
    Elm *ept = bpt++;
    ept->v = v, ept->nxt = NULL;

    if (head == NULL)
      head = tail = ept, sz = 1;
    else {
      tail->nxt = ept;
      tail = ept;
      sz++;
    }
  }

  void erase() {
    if (head != NULL) {
      head = head->nxt;
      sz--;
      if (head == NULL) tail = NULL;
    }
  }

  void append(const SList &sl) {
    if (head == NULL)
      *this = sl;
    else {
      tail->nxt = sl.head;
      tail = sl.tail;
      sz += sl.sz;
    }
  }
};

template <typename T, const int MAX_E2>
struct SegTreeMin {
  int n, e2;
  T nodes[MAX_E2], def;
  SegTreeMin() {}

  void init(int _n, T _def) {
    n = _n; def = _def;
    for (e2 = 1; e2 < n; e2 <<= 1);
    fill(nodes, nodes + MAX_E2, def);
  }

  T &get(int i) { return nodes[e2 - 1 + i]; }

  void set(int i, T v) {
    int j = e2 - 1 + i;
    nodes[j] = v;
    while (j > 0) {
      j = (j - 1) / 2;
      nodes[j] = min<T>(nodes[j * 2 + 1], nodes[j * 2 + 2]);
    }
  }

  void setall() {
    for (int j = e2 - 2; j >= 0; j--)
      nodes[j] = min<T>(nodes[j * 2 + 1], nodes[j * 2 + 2]);
  }

  T min_range(int r0, int r1, int k, int i0, int i1) {
    if (r1 <= i0 || i1 <= r0) return def;
    if (r0 <= i0 && i1 <= r1) return nodes[k];

    int im = (i0 + i1) / 2;
    T v0 = min_range(r0, r1, k * 2 + 1, i0, im);
    T v1 = min_range(r0, r1, k * 2 + 2, im, i1);
    return min<T>(v0, v1);
  }
  T min_range(int r0, int r1) { return min_range(r0, r1, 0, 0, e2); }
};

