    while (right_pts.empty() || ranges[j].first <= right_pts.front().first) {
      j++;
      double v = ranges[j].second;
      while (!right_pts.empty() && right_pts.back().first >= v) {
        right_pts.pop_back();
      }
      right_pts.emplace_back(v, j);
    }
    assert(j <= i + N && j > i);
    nxt[i][0] = j - i;
    if (!right_pts.empty() && right_pts.front().second == i)
      right_pts.pop_front();
  }
  for (int l = 0; (1 << l) <= M; l++) {
    for (int i = 0; i < N; i++) {
      nxt[i][l + 1] = nxt[i][l] + nxt[(i + nxt[i][l]) % N][l];
    }
  }
  for (int i = 0; i < N; i++) {
    long long len = 0;
    for (int l = 0; (1 << l) <= M; l++) {
      if (M & (1 << l)) {
        len += nxt[(i + len) % N][l];
      }
    }
    if (len >= N) return true;
  }
  return false;
}
int main() {
  ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cin >> N >> M;
  for (int i = 0; i < N; i++) {
    long long x, y;
    cin >> x >> y;
    if (x == 0 && y == 0) {
      cout << fixed << setprecision(10) << 0. << '\n';
      exit(0);
    }
    pts[i].first = double(sqrt(x * x + y * y));
    pts[i].second = atan2(y, x);
    if (pts[i].second < 0) pts[i].second += 2 * PI;
  }
  double ma = pts[0].first;
  for (int i = 0; i < N; i++) ma = min(ma, pts[i].first);
  double mi = 0;
  for (int z = 0; z < 60; z++) {
    double md = mi + (ma - mi) / 2;
    if (numBarriers(md)) {
      mi = md;
    } else {
      ma = md;
    }
  }
  cout << fixed << setprecision(10) << mi << '\n';
