  }
  sort(vec.begin(), vec.end());
  for (int i = 0; i < vec.size(); i++) {
    int x = vec[i].first;
    int num1 =
        lower_bound(vec.begin(), vec.end(), make_pair(a - x, 0)) - vec.begin();
    int num2 =
        lower_bound(vec.begin(), vec.end(), make_pair(b - x, 0)) - vec.begin();
    if (vec[num1].first == a - x && vec[num2].first == b - x) {
      g[i + n + 1].push_back(num2 + 1 + n);
      g[num2 + 1].push_back(i + 1);
      g[num1 + 1 + n].push_back(i + 1 + n);
      g[i + 1].push_back(num1 + 1);
      g[num1 + 1 + n].push_back(num2 + 1 + n);
      g[num2 + 1].push_back(num1 + 1);
