      g[i + 1 + n].push_back(num1 + 1 + n);
      g[num1 + 1].push_back(i + 1);
      g[i + 1].push_back(num1 + 1);
      g[num1 + 1 + n].push_back(i + 1 + n);
      g[i + 1 + n].push_back(i + 1);
    } else if (vec[num2].first == b - x) {
      g[i + 1 + n].push_back(num2 + 1 + n);
      g[num2 + 1].push_back(i + 1);
      g[i + 1].push_back(num2 + 1);
      g[num2 + 1 + n].push_back(i + 1 + n);
      g[i + 1].push_back(i + 1 + n);
    } else
      return cout << "NO", 0;
  }
  for (int i = 1; i <= n + n; i++) {
    if (!used[i]) dfs1(i);
    for (int j = 0; j < g[i].size(); j++) {
      int to = g[i][j];
      gg[to].push_back(i);
    }
  }
  reverse(topol.begin(), topol.end());
  for (int i = 1; i <= n + n; i++) used[i] = 0;
  for (int i = 0; i < topol.size(); i++) {
    int v = topol[i];
    if (used[v]) continue;
    ++cnt;
    dfs2(v);
  }
  for (int i = 1; i <= n; i++) {
    if (cmp[i] > cmp[i + n]) {
      anss[vec[i - 1].second] = 1;
    }
    if (cmp[i] == cmp[i + n]) return cout << "NO", 0;
  }
  cout << "YES"
       << "\n";
  for (int i = 1; i <= n; i++) cout << (anss[i] ^ 1) << ' ';
}

