int isok(int l,int r){
  return l%3 <= r%3;
}

int solve(int prev,int l,int r,int now,const string &in){
  if (now == in.size())return 0;
  int &ret = dp[prev][l][r][now];
  if (ret != -1)return ret;
  ret=inf;
  int pl=now==0?0:(prev==0?1:0);//
  int pr=now==0?0:(prev==1?1:0);
  if (isok(in[now]%3,r%3)){
    ret=min(ret,pl+solve(0,in[now],r,now+1,in));
  }
  if (isok(l%3,in[now]%3)){
    ret=min(ret,pr+solve(1,l,in[now],now+1,in));
  }
  //cout << prev <<" " << 1+l<<" " << 1+r << " " << now <<" " << (int)1+in[now] << " " << 
  //pl <<" " << pr <<" " << ret << endl;
  return ret;
}

