long long int fact[500005];
long long int inv_fact[500005];
long long int bin_pow(long long int a, long long int b) {
  long long int ret = 1;
  while (b) {
    if (b & 1) {
      ret = (ret * a) % 998244353;
    }
    b >>= 1;
    a = (a * a) % 998244353;
  }
  return ret;
}
long long int cmb(long long int a, long long int b) {
  long long int ret;
  ret = (((fact[a] * inv_fact[b]) % 998244353) * inv_fact[a - b]) % 998244353;
  return ret;
}
int main() {
  long long int n, k, sm = 0, a, i;
  cin >> n >> k;
  a = max(n, k);
  fact[0] = 1;
  inv_fact[0] = 1;
  for (i = 1; i <= a; i++) {
    fact[i] = (fact[i - 1] * i) % 998244353;
    inv_fact[i] = bin_pow(fact[i], 998244353 - 2);
  }
  for (i = 1; i <= n; i++) {
    a = (n / i) - 1;
    a = cmb(a, k - 1);
    if (a < 0) {
      break;
    }
    sm = (sm + cmb(a, k - 1)) % 998244353;
  }
  cout << sm << "\n";
  return 0;
}

