const int INF = 1e9 + 10;
const long long INFL = 1e18 + 10;
const int MAX = 2e5 + 10;
struct op {
  int x, y, z;
};
int n, moment, trsz;
vector<int> es[MAX];
vector<op> res;
bool mark[MAX];
pair<int, int> sz[MAX];
void add_op(const op& x) {
  if (x.x < 1 || x.y < 1 || x.z < 1 || x.y == x.z) return;
  res.push_back(x);
}
void add(pair<int, int>& p, int value) {
  if (p.second < moment)
    p = make_pair(value, moment);
  else
    p.first += value;
}
pair<int, int> dfs_centroid(int u, int p) {
  for (auto v : es[u])
    if (!mark[v] && v != p) {
      if (sz[v].first > trsz / 2) return dfs_centroid(v, u);
      if (sz[v].first == (trsz + 1) / 2) return make_pair(u, v);
    }
  return make_pair(u, 0);
}
void dfs_size(int u, int p) {
  add(sz[u], 1);
  for (auto v : es[u])
    if (!mark[v] && v != p) {
      dfs_size(v, u);
      add(sz[u], sz[v].first);
    }
}
void find_centroid(int u, int pc) {
  moment++;
  dfs_size(u, 0);
  trsz = sz[u].first;
  pair<int, int> x = dfs_centroid(u, 0);
  mark[x.first] = mark[x.second] = true;
  add_op(op{pc, u, x.first});
  for (auto v : es[x.first])
    if (!mark[v]) find_centroid(v, x.first);
  for (auto v : es[x.second])
    if (!mark[v]) find_centroid(v, 0);
}
