	static int dfs(int now, int[] num, int[] c) {
		if(now == num.length) {
			return check(num)?1:0;
		}
		if(num[now] != -1) return dfs(now+1,num,c);
		int ret = 0;
		for(int i = 0; i < c.length; i++) {
			num[now] = c[i];
			ret += dfs(now+1,num,c);
		}
		num[now] = -1;
		return ret;
	}
	static boolean check(int[] a) {
		int sum = 0;
		for(int i = a.length-1; i >= 0; i--) {
			if((a.length - i) % 2 == 0) {
				int tmp = a[i]*2;
				if(tmp >= 10) {
					switch(tmp) {
					case 10: tmp = 1; break;
