					case 15: tmp = 6; break;
					case 16: tmp = 7; break;
					case 17: tmp = 8; break;
					case 18: tmp = 9; break;
					}
				}
				sum += tmp;
			}
			else {
				sum += a[i];
			}
		}
		return sum % 10 == 0;
	}
}

