        int[] index = new int[n + 1];
        for (int i = 0; i < n; i++){
            a[i] = new pair(nextInt(), i + 1);
        }
        Arrays.sort(a);
        int fmax, fmin;
        fmax = a[n - 1].a + a[n - 2].a;
        fmin = a[0].a + a[1].a;

        int df = fmax - fmin;
        Arrays.fill(index, 1);

        fmax = Math.max(a[0].a + h + a[n - 1].a, fmax);
        fmin = Math.min(a[0].a + h + a[1].a, a[1].a + a[2].a);

        if (df > fmax - fmin){
            df = fmax - fmin;
            index[a[0].i] = 2;
        }

        int k_old = 0;
        for (int k = 2; k < n - 1; k++){
            fmax = Math.max(a[k].a + h + a[n - 1].a, a[n - 1].a + a[n - 2].a);
            fmin = Math.min(a[0].a + a[1].a + h, a[0].a + a[k].a);

            if (df > fmax - fmin){
                df = fmax - fmin;
                index[k_old] = 1;
                index[a[0].i] = 2;
                index[a[2].i] = 2;
                k_old = k;
            }
        }

        fmax = Math.max(a[2].a + h + a[n - 1].a, fmax);
        fmin = a[1].a + a[2].a;

        for (int i = 0; i < n - 1; i++){
            if (i != 2 && i != 1)   fmin = Math.min(a[1].a + h + a[i].a, fmin);
            if (i != 2 && i != 1)   fmin = Math.min(a[2].a + h + a[i].a, fmin);
        }

        if (df > fmax - fmin){
            Arrays.fill(index, 1);
            df = fmax - fmin;
            index[a[1].i] = 2;
            index[a[2].i] = 2;
        }

        out.println(df);
        for (int i = 1; i <=n; i++){
            out.print(index[i]+" ");
        }
        out.close();

    }

