// 空白区切りで文字列を分割して返す
vector<string> split_words(string s){
	bool flag = false;
	vector<string> vs;
	string str;
	s.push_back(' ');
	for(int i=0 ; i < s.size() ; i++ ){
		char c = s[i];
		if( flag == false ){
			if( c != ' '){
				flag = true;
				str.clear();
				str.push_back( c );
			}
		}else{
			if( c != ' ' ){
				str.push_back( c );
			}
			if( c == ' ' ){
				flag = false;
				vs.push_back( str );
				str.clear();
			}
		}
	}
	return vs;
}

