int cnt_pre(string s){
	int a=0;
	for(int i=0 ; i < s.size() ; i++ ){
		if( s[i] == '.' ) return a;
		a++;
	}
	return a;
}

int cnt_zero(string s){
	int cnt=0;
	for(int i=0 ; i < s.size() ; i++ ){
		if( s[i] == '0' )
			cnt++;
		if( s[i] >= '1' && s[i] <= '9' )
			return cnt;
	}
	return cnt;
}

