		vector<string> vs = split_words( s );
		string unit, prefix;
		string num = vs[0];
		if( vs.size() == 3 ){
			prefix = vs[1];
			unit = vs[2];
		}else if( vs.size() == 2 ){
			if( h.count( vs[1] ) ){
				prefix = vs[1];
			}else{
				unit = vs[1];
			}
		}

		// '.' までの数値の個数
		int a = cnt_pre( num );
		// 先頭の '0' の数
		int pre_zero = cnt_zero( num );

		int b=0;
		if( !prefix.empty() ){
			b = h[prefix];
		}
		if( pre_zero == 0 ){
			cout << num[0];

			// 小数点以下が出力できるとき
			if( num.size() > 1 ) cout << ".";
			// 小数点以下の数値を出力
			for(int i=1 ; i < num.size() ; i++ ){
				if( num[i] == '.' ) continue;
				cout << num[i];
			}
			// 10^x の部分の出力
			cout << " * 10^" << (a+b-1);
			// 単位の部分の出力
			if( !unit.empty() ) 
				cout << " " << unit;
		}else{
			cout << num[pre_zero+1];

			// 小数点以下が出力できるとき
			if( num.size() > pre_zero+2 ) cout << "." ;
			// 小数点以下の数値を出力
			for(int i = pre_zero+2 ; i < num.size() ; i++ ){
				if( num[i] == '.' ) continue;
				cout << num[i];
			}
			// 10^x の部分の出力
			cout << " * 10^" << (a+b-1-pre_zero);
			// 単位の部分の出力
			if( !unit.empty() ) 
				cout << " " << unit;
		}
		cout << endl;
	}
}

