const int MX = 1 << 21, MD = 1e9 + 7;
using namespace std;
int n, q, ans[MX], a[MX], l[MX], X[MX];
vector<int> qw[MX];
int main() {
  cin >> n >> q;
  vector<int> V(1, 0);
  ans[0] = 1;
  bitset<1 << 21> B;
  B[0] = true;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }
  for (int i = 1; i <= q; i++) {
    cin >> l[i] >> X[i];
    qw[l[i]].push_back(X[i]);
  }
  map<pair<int, int>, int> Nig;
  for (int i = 1; i <= n; i++) {
    if (B[a[i]]) {
      ans[i] = (ans[i - 1] + ans[i - 1]) % MD;
    } else {
      int oldSize = V.size();
      for (int j = 0; j < oldSize; j++) {
        V.push_back(a[i] ^ V[j]);
        B[a[i] ^ V[j]] = 1;
      }
      ans[i] = ans[i - 1];
    }
    while (!qw[i].empty()) {
      Nig[{i, qw[i].back()}] = (B[qw[i].back()] ? ans[i] : 0) % MD;
      qw[i].pop_back();
    }
  }
