            ans[ind] = ii;
            int last = v1[ii][v1[ii].size() - 1];
            ans[last] = nvs;
            v1[ii].erase(v1[ii].end() - 1);
            vis1[last] = true;
            e -= 1;
            break;
          }
        }
        if (f == 1) pos = 1;
