          ind += 1;
        }
        for (int i = 0; i < e - 1; i++) ans[imp[i]] = v[imp[i + 1]];
        if (e > 0) ans[imp[e - 1]] = v[imp[0]];
        for (int i = 0; i < n; i++) {
          if (vis1[i] == false) ans[i] = nvs;
        }
        cout << "YES" << endl;
        for (int i = 0; i < n; i++) cout << ans[i] << " ";
        cout << endl;
      }
    }
  }
