#include <bits/stdc++.h>
int main() {
  const int INF = (1 << 29);
  int dp[200010], n, min, max, mid, a[200010], i, ans = 0;
  scanf("%d\n", &n);
  for (i = n - 1; i >= 0; i--) {
    scanf("%d", &a[i]);
  }
  for (i = 0; i <= n; i++) {
    dp[i] = INF;
  }
  dp[0] = a[0];
  for (i = 1; i < n; i++) {
    min = -1, max = n;
    while (abs(max - min) > 1) {
      mid = (min + max) / 2;
      if (a[i] <= dp[mid]) {
        max = mid;
      } else if (a[i] > dp[mid]) {
        min = mid;
      }
    }
    dp[max] = a[i];
  }
  for (i = 0; i <= n; i++) {
    if (dp[i] == INF) {
      break;
    }
    ans++;
  }
  printf("%d\n", ans);
  return 0;
}

