} e[M];
int n, Q, u, v, w, x, y, fl, ans, rt, du[N], hd[N], Fa[N], Hs[N], Dw[N];
void add(int u, int v, int w) {
  e[++fl] = (edge){hd[u], v, w};
  hd[u] = fl;
}
struct ele {
  int u, d;
  bool operator<(const ele a) const { return d > a.d; }
};
void dfs0(int u) {
  Hs[u] = u;
  for (int i = hd[u], v; v = e[i].v, i; i = e[i].n)
    if (v != Fa[u]) {
      Fa[v] = u;
      Dw[v] = Dw[u] + e[i].w;
      dfs0(v);
      if (Dw[Hs[v]] > Dw[Hs[u]]) Hs[u] = Hs[v];
    }
}
struct tree {
  int cq, pos[N], ans[N], dw[N], hs[N], f[N][LG + 2];
  ele q[N];
  void dfs1(int u, int dis) {
    for (int i = hd[u], v; v = e[i].v, i; i = e[i].n)
      if (v != f[u][0])
        hs[v] == hs[u] ? dfs1(v, dis + e[i].w) : dfs1(v, e[i].w);
    if (du[u] == 1) q[++cq] = (ele){u, dis};
  }
  void ini() {
    for (int i = 1; i <= n; i++) dw[i] = Dw[i], hs[i] = Hs[i], f[i][0] = Fa[i];
    for (int j = 1; j <= LG; j++)
      for (int i = 1; i <= n; i++) f[i][j] = f[f[i][j - 1]][j - 1];
    dfs1(rt, 0);
    sort(q + 1, q + cq + 1);
    for (int i = 1; i <= cq; i++) pos[q[i].u] = i, ans[i] = ans[i - 1] + q[i].d;
  }
  int ask(int u, int K) {
    K = min(K, cq);
    if (pos[hs[u]] <= K) return ans[K];
    int x = u;
    for (int j = LG; j >= 0; j--)
      if (f[x][j] && pos[hs[f[x][j]]] > K) x = f[x][j];
    x = f[x][0];
    return ans[K] - min(q[K].d, dw[hs[x]] - dw[x]) + dw[hs[u]] - dw[x];
  }
} T1, T2;
int main() {
  scanf("%d%d", &n, &Q);
  for (int i = 2; i <= n; i++)
    scanf("%d%d%d", &u, &v, &w), add(u, v, w), add(v, u, w), du[u]++, du[v]++;
  rt = 1;
  dfs0(1);
  rt = Hs[rt];
  Fa[rt] = Dw[rt] = 0;
  dfs0(rt);
  T1.ini();
  rt = Hs[rt];
  Fa[rt] = Dw[rt] = 0;
  dfs0(rt);
  T2.ini();
  while (Q--) {
    scanf("%d%d", &x, &y);
    x = (x + ans - 1) % n + 1;
    y = (y + ans - 1) % n + 1;
    y = 2 * y - 1;
    ans = max(T1.ask(x, y), T2.ask(x, y));
    printf("%d\n", ans);
  }
}

