   class SegmentTree 
   {
      //range query, non lazy
      private Pair NULL = new Pair(Integer.MAX_VALUE, 0);
      final Pair[] val;
      final int treeFrom;
      final int length;

      public SegmentTree(int treeTo) 
      {
         int treeFrom = 0;
         this.treeFrom = treeFrom;
         int length = treeTo - treeFrom + 1;
         int l;
         for (l = 0; (1 << l) < length; l++);
         val = new Pair[1 << (l + 1)];
         for(int i=0; i < val.length; i++)
            val[i] = NULL;
         this.length = 1 << l;
      }
      public void update(int index, int delta) 
      {
         //replaces value
         int node = index - treeFrom + length;
         val[node] = new Pair(delta, index);
         for (node >>= 1; node > 0; node >>= 1) 
           val[node] = comb(val[node << 1], val[(node << 1) + 1]);
      }
      public Pair query(int from, int to) 
      {
         //inclusive bounds
         if (to < from)
            return NULL; //0 or 1?
         from += length - treeFrom;
         to += length - treeFrom + 1;
         //0 or 1?
         Pair res = NULL;
         for (; from + (from & -from) <= to; from += from & -from) 
             res = comb(res, val[from / (from & -from)]);
         for (; to - (to & -to) >= from; to -= to & -to)
             res = comb(res, val[(to - (to & -to)) / (to & -to)]);
         return res;
      }
      private Pair comb(Pair left, Pair right)
      {
         if(left.min <= right.min)
            return left;
         return right;
      }
   }
   class Pair
    {
      public int min;
      public int loc;

      public Pair(int a, int b)
      {
         min = a;
         loc = b;
      }
    }

