#include <bits/stdc++.h>
using namespace std;
inline void getarrint(vector<int>& a, int n, istream& in) {
  for (int i = 0; i <= n - 1; i++) in >> a[i];
}
class Solution {
 public:
  void solve(std::istream& in, std::ostream& out) {
    int n;
    in >> n;
    if (n == 1)
      out << "Exemplary pages." << '\n';
    else {
      vector<int> v1(n), v2(n);
      getarrint(v1, n, in);
      for (int i = 0; i <= n - 1; i++) v2[i] = v1[i];
      sort((v1).begin(), (v1).end());
      int k = unique((v1).begin(), (v1).end()) - v1.begin();
      if (k == 1)
        out << "Exemplary pages." << '\n';
      else if (k > 3)
        out << "Unrecoverable configuration." << '\n';
      else if (k == 2) {
        if (n > 2)
          out << "Unrecoverable configuration." << '\n';
        else {
          int x = v1[0];
          int y = v1[1];
          int dif = y - x;
          if (dif % 2 == 0) {
            dif /= 2;
            int px, py;
            if (x == v2[0])
              px = 0;
            else
              px = 1;
            if (px == 0)
              py = 1;
            else
              py = 0;
            out << dif << " ml. from cup #" << px + 1 << " to cup #" << py + 1
                << "." << '\n';
          } else
            out << "Unrecoverable configuration." << '\n';
        }
      } else {
        int x = v1[0];
        int c = v1[1];
        int y = v1[2];
        int cnt = 0;
        for (int i = 0; i <= n - 1; i++) {
          if (v2[i] == c) cnt++;
        }
        if (cnt != n - 2)
          out << "Unrecoverable configuration." << '\n';
        else {
          int dif = y - x;
          if (dif % 2 == 0 && x + dif / 2 == c) {
            int px, py;
            dif /= 2;
            for (int i = 0; i <= n - 1; i++) {
              if (v2[i] == x) px = i;
              if (v2[i] == y) py = i;
            }
            out << dif << " ml. from cup #" << px + 1 << " to cup #" << py + 1
                << "." << '\n';
          } else
            out << "Unrecoverable configuration." << '\n';
        }
      }
    }
  }
};
void solve(std::istream& in, std::ostream& out) {
  out << fixed << std::setprecision(6);
  Solution solution;
  solution.solve(in, out);
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  istream& in = cin;
  ostream& out = cout;
  solve(in, out);
  return 0;
}

