void qsort(int l, int r) {
  if (l >= r) return;
  int p = ((arr[l] + arr[r]) / 2 + arr[(l + r) / 2]) / 2;
  int i = l, j = r, temp;
  while (i <= j) {
    while (arr[i] < p) i++;
    while (arr[j] > p) j--;
    if (i <= j) {
      temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
      i++;
      j--;
    }
  }
  qsort(l, j);
  qsort(i, r);
}
