vector<int> simple(string s){
	vector<int> v;
	for(int i = 0 ; i < s.size() ; i += 2 ){
		v.push_back((s[i]-'0')*16+s[i+1]-'0');
	}
	for(int i = 1 ; i <= v.size() ; i++){
		if( v.size() % i ) continue;
		int l = v.size() / i;
		int f = 1;
		for(int j = 0 ; j < v.size() ; j++){
			if( j % l && v[j] > 0 ) f = 0;
		}
		if(f){
			vector<int> t;
			for(int j = 0 ; j < v.size() ; j += l )
				t.push_back(v[j]);
			v = t;
			break;
		}
	}
	for(int i = 1 ; i <= v.size() ; i++){
		if( v.size() % i ) continue;
		int f = 1;
		for(int j = 0 ; j < v.size() ; j+=i){
			for(int k = 0 ; k < i ; k++){
				if( v[j+k] != v[k] ) f = 0;
			}
		}
		if(f){
			v.resize(i);
			return v;
		}
	}
	return v;
}
