class DSU
{
    int parent[];
    int rank[];
    DSU(int n)
    {
        this.parent=new int[n];
        this.rank=new int[n];
        Arrays.fill(parent,-1);
        Arrays.fill(rank,1);
    }

    int find(int s1)
    {
        if(parent[s1]==-1)
            return s1;
        return parent[s1]=find(parent[s1]);
    }

    void unite(int s1,int s2)
    {
        int p1=this.find(s1);
        int p2=this.find(s2);
        if(p1==p2)
            return;
        if(rank[p1]>rank[p2])
        {
            parent[p2]=p1;
            rank[p1]+=rank[p2];
        }
        else
        {
            parent[p1]=p2;
            rank[p2]+=rank[p1];
        }
    }


}


