using namespace std;
int c[10];
bool check() {
  int sum = 0, MOD = c[9];
  for (int i = 0; i < 3; i++) sum = (sum + c[i]) % MOD;
  if ((c[3] + c[4] + c[5]) % MOD != sum) return false;
  if ((c[6] + c[7] + c[8]) % MOD != sum) return false;
  if ((c[0] + c[3] + c[6]) % MOD != sum) return false;
  if ((c[1] + c[4] + c[7]) % MOD != sum) return false;
  if ((c[2] + c[5] + c[8]) % MOD != sum) return false;
  return true;
}
int rec(int p, int S) {
  int res = 0;
  if (p == 9) {
    return check();
  }
  if (!c[p]) {
    for (int i = 0; i < 10; i++) {
      if ((S >> i) & 1) continue;
      c[p] = i + 1;
      res += rec(p + 1, S | (1 << i));
      c[p] = 0;
    }
  } else {
    res += rec(p + 1, S);
  }
  return res;
}
