const int N = 100010;
struct Seg {
  int f, t, a, b;
} s[N];
bool cmp(const Seg &a, const Seg &b) {
  if (a.f != b.f) return a.f < b.f;
  if (a.t != b.t) return a.t < b.t;
  if (a.a != b.a) return a.a < b.a;
  return a.b < b.b;
}
vector<pair<int, int> > cn, cm, z;
int n, m;
void doit(int a, int b) {
  int now = a, nowy = s[a].b, ans = 0;
  for (int i = a + 1; i <= b; i++) {
    if (s[i].a > nowy) {
      ans += nowy - s[now].a;
      now = i, nowy = s[i].b;
    } else {
      nowy = max(nowy, s[i].b);
    }
  }
  ans += (nowy - s[now].a);
  if (s[a].f == 0)
    cm.push_back(make_pair(m - ans, s[a].t));
  else
    cn.push_back(make_pair(n - ans, s[a].t));
}
void output(int f, int p, int q) {
  if (f == 0) {
    printf("%d %d %d %d\n", p, 0, p, q);
  } else
    printf("%d %d %d %d\n", 0, p, q, p);
}
void find(int f, int p, int v, int k) {
  for (int i = 0; i < k; i++) {
    if (s[i].f == f && s[i].t == p) {
      z.push_back(make_pair(s[i].a, s[i].b));
    }
  }
  int now = 0, g = 0;
  for (int i = 0; i < z.size(); i++) {
    g += max(0, z[i].first - now);
    now = max(now, z[i].second);
    if (g >= v) {
      output(f, p, z[i].first + v - g);
      return;
    }
  }
  output(f, p, now + v - g);
}
