    scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
    if (x1 == x2) {
      s[i].f = 0, s[i].t = x1, s[i].a = min(y1, y2), s[i].b = max(y1, y2);
    } else {
      s[i].f = 1, s[i].t = y1, s[i].a = min(x1, x2), s[i].b = max(x1, x2);
    }
  }
  sort(s, s + k, cmp);
  for (int i = 0; i < k; i++) {
    if (s[i].f == 0 && s[i].t == mx)
      mx++;
    else if (s[i].f == 1 && s[i].t == my)
      my++;
  }
  int now = 0;
  for (int i = 1; i < k; i++) {
    if (s[i].f == s[now].f && s[i].t == s[now].t) continue;
    doit(now, i - 1);
    now = i;
