vector<vll> dp2;
ll addOcc(ll a, ll b) { return min(K, a + b); }
ll rec(int r, int c) {
  ll &ret = dp2[r][c];
  if (ret != -1) {
    return ret;
  }
  int len = dp1[r][c];
  ret = 0;
  if (r < n and c < n and in[r] == rev[c]) {
    ret = rec(r + 1, c + 1);
  } else {
    if (r < n and dp1[r + 1][c] == len + 1) {
      ret = addOcc(ret, rec(r + 1, c));
    }
    if (c < n and dp1[r][c + 1] == len + 1) {
      ret = addOcc(ret, rec(r, c + 1));
    }
  }
  if (len >= (optlen + 1) / 2) {
    chmin(ret, 1LL);
  }
  return ret;
}
string res;
void explore(int r, int c, ll rest) {
  if ((int)res.size() == (optlen + 1) / 2) return;
  if (in[r] == rev[c]) {
    res += in[r];
    explore(r + 1, c + 1, rest);
    return;
  }
  if (in[r] < rev[c]) {
    if (dp2[r + 1][c] >= rest) {
      res += in[r];
      explore(r + 1, c, rest);
    } else {
      res += rev[c];
      explore(r, c + 1, rest - dp2[r + 1][c]);
    }
  } else {
    if (dp2[r][c + 1] >= rest) {
      res += rev[c];
      explore(r, c + 1, rest);
    } else {
      res += in[r];
      explore(r + 1, c, rest - dp2[r][c + 1]);
    }
  }
}
