  for (int i = (int)(1); i < (int)(n + 1); ++i) {
    for (int j = (int)(1); j < (int)(n + 1); ++j) {
      int &cur = dp1[i][j];
      if (in[i - 1] == rev[j - 1]) {
        cur = dp1[i - 1][j - 1] + 1;
      } else {
        cur = min(dp1[i - 1][j] + 1, dp1[i][j - 1] + 1);
      }
    }
  }
  optlen = dp1[n][n];
  dp2 = vector<vll>(n + 1, vll(n + 1, -1));
  dp2[n][n] = 1;
  rec(0, 0);
  for (int i = (int)(0); i < (int)(n + 1); ++i)
    for (int j = (int)(0); j < (int)(n + 1); ++j)
      if (dp2[i][j] == -1) dp2[i][j] = 0;
  if (dp2[0][0] < K) {
    cout << "NONE" << endl;
    return 0;
  }
  explore(0, 0, K);
  string rres = res;
  reverse(begin(rres), end(rres));
  if (optlen % 2 == 1) {
