/* constant */

const int MAX_N = 100000;
const int INF = 1 << 30;

/* typedef */

typedef pair<int,int> pii;
typedef vector<pii> vpii;

/* global variables */

vpii nbrs[MAX_N];
int ds[MAX_N];

/* subroutines */

/* main */

int main() {
  int n, m;
  scanf("%d%d", &n, &m);

  for (int i = 0; i < m; i++) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    a--, b--;
    //nbrs[a].push_back(pii(b, c));
    nbrs[b].push_back(pii(a, c));
  }

  int st = 0, gl = n - 1;
  int maxd = -1;
  vpii &nbrgl = nbrs[gl];

  for (vpii::iterator git = nbrgl.begin(); git != nbrgl.end(); git++) {
    int &gv = git->first, &gd = git->second;
    fill(ds, ds + n, -1);
    ds[gl] = ds[gv] = gd;

    priority_queue<pii> q;
    q.push(pii(gd, gv));

    while (! q.empty()) {
      pii u = q.top(); q.pop();
      int &ud = u.first, &ui = u.second;
      if (ud != ds[ui]) continue;
      if (ui == st) break;

      vpii &nbru = nbrs[ui];

      for (vpii::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
	int &vi = vit->first, &vd = vit->second;
	if (vd <= ud && ds[vi] < vd) {
	  ds[vi] = vd;
	  q.push(pii(vd, vi));
	}
      }
    }

    if (ds[st] >= 0 && maxd < gd) maxd = gd;
  }

  printf("%d\n", maxd);
  return 0;
}

