using namespace std;
const int N = 1e5 + 5;
struct node {
  int nxt, ed, len;
} e[2 * N];
int head[N], num, vis[2 * N], p[40], ans, n, used[N], dp[N];
vector<int> v;
void add(int x, int y, int z) {
  e[num].ed = y;
  e[num].len = z;
  e[num].nxt = head[x];
  head[x] = num++;
}
void dfs(int u, int t) {
  used[u] = 1;
  dp[u] = t;
  if (u == n) {
    ans = t;
  }
  for (int i = head[u]; ~i; i = e[i].nxt) {
    int vv = e[i].ed;
    if (vis[i]) continue;
    vis[i] = vis[i ^ 1] = 1;
    if (used[vv])
      v.push_back(t ^ e[i].len ^ dp[vv]);
    else {
      dfs(vv, t ^ e[i].len);
    }
  }
}
int main() {
  int m, x, y, z;
  memset(head, -1, sizeof(head));
  scanf("%d%d", &n, &m);
  for (int i = 0; i < m; i++) {
    scanf("%d%d%d", &x, &y, &z);
    add(x, y, z), add(y, x, z);
  }
  dfs(1, 0);
  for (int i = 0; i < v.size(); i++) {
    for (int j = 30; j >= 0; j--) {
      if (!(v[i] >> j)) continue;
      if (!p[j]) {
        p[j] = v[i];
        break;
      }
      v[i] ^= p[j];
    }
  }
  for (int i = 30; i >= 0; i--) {
    if (ans & (1 << i)) {
      ans ^= p[i];
    }
  }
  printf("%d\n", ans);
  return 0;
}

