int gr(int x) {
  if (x == 1) return 0;
  if (dp.find(x) != dp.end()) return dp[x];
  int grundy = 0, j;
  for (j = 30; j > 0; j--)
    if (x & (1 << j)) break;
  for (int i = 1; i <= j; i++)
