const int N = 100005;
const int M = 12;
int n, m, pw2, Q, t[N * 4][M];
char a[N][M];
void init(int i) {
  for (int j = 1; j <= m; j++) {
    int p = j, k;
    for (k = 0; k < m + 5; k++) {
      if (a[i][p] == '~') break;
      if (a[i][p] == '^') break;
      if (a[i][p] == '<')
        p--;
      else
        p++;
    }
    if (k == m + 5)
      t[i + pw2 - 1][j] = m + 1;
    else if (a[i][p] == '~')
      t[i + pw2 - 1][j] = ((!p) ? 100000 : 200000) + i;
    else
      t[i + pw2 - 1][j] = p;
  }
  t[i + pw2 - 1][m + 1] = m + 1;
}
void update(int i) {
  for (int j = 1; j <= m; j++) {
    int k = i * 2 + 1, x;
    x = t[k][j];
    if (x <= m + 1) {
      t[i][j] = t[i * 2][x];
    } else {
      t[i][j] = x;
    }
  }
}
int query(int x, int y, int i, int l, int r) {
  if (x >= r) {
    return t[i][y];
  }
  int mid = (l + r) >> 1;
  if (x > mid) y = query(x, y, i * 2 + 1, mid, r);
  if (y > m + 1) return y;
  return query(x, y, i * 2, l, mid);
}
