    a[i][0] = '~';
    a[i][m + 1] = '~';
    a[i][m + 2] = '\0';
  }
  for (int i = 1; i <= m; i++) a[0][i] = a[n + 1][i] = '~';
  for (pw2 = 1; pw2 < n; pw2 <<= 1)
    ;
  for (int i = 1; i <= n; i++) init(i);
  for (int i = pw2 - 1; i > 0; i--) update(i);
  while (Q--) {
    char type;
    int x, y;
    scanf("%c %d %d", &type, &x, &y);
    getchar();
    if (type == 'A') {
      int ans = query(x, y, 1, 1, pw2);
      if (ans > 0 && ans <= m) {
        printf("0 %d\n", ans);
      } else if (ans == m + 1) {
        printf("-1 -1\n");
      } else if (ans > 100000 && ans < 200000) {
        printf("%d 0\n", ans - 100000);
      } else {
        printf("%d %d\n", ans - 200000, m + 1);
      }
    } else {
      char ch;
      ch = getchar();
      getchar();
      a[x][y] = ch;
      init(x);
      for (int i = (pw2 + x - 1) / 2; i > 0; i >>= 1) {
        update(i);
      }
    }
  }
  return 0;
}

