}
pair<long long, long long> getcor(long long n, long long m, long long x,
                                  long long y, long long vx, long long vy) {
  if (vx > 0) {
    x = n - x;
  }
  if (vy > 0) {
    y = m - y;
  }
  m = -m;
  x = y - x;
  if (x == 0) {
    return (make_pair(0, 0));
  } else {
    long long k1, k2;
    long long c = gcd(n, m, k1, k2);
    if (x % c != 0) {
      return (make_pair(-1, -1));
    }
    k1 *= x / c;
    k2 *= x / c;
    long long p1 = m / c;
    long long p2 = n / c;
    p1 *= 100;
    p2 *= 100;
    while (k1 < 0 || k2 < 0) {
      if (k1 < 0) {
        if (p1 < 0) {
          k1 -= p1;
          k2 += p2;
        } else {
          k1 += p1;
          k2 -= p2;
        }
      } else {
        if (p2 > 0) {
          k1 -= p1;
          k2 += p2;
        } else {
          k1 += p1;
          k2 -= p2;
        }
      }
    }
    while (k1 - p1 >= 0 && k2 + p2 >= 0 && p1 >= 0 && p2 <= 0) {
      k1 -= p1;
      k2 += p2;
    }
    while (k1 + p1 >= 0 && k2 - p2 >= 0 && p1 <= 0 && p2 >= 0) {
      k1 += p1;
      k2 -= p2;
    }
    p1 /= 100;
    p2 /= 100;
    while (k1 - p1 >= 0 && k2 + p2 >= 0 && p1 >= 0 && p2 <= 0) {
      k1 -= p1;
      k2 += p2;
    }
    while (k1 + p1 >= 0 && k2 - p2 >= 0 && p1 <= 0 && p2 >= 0) {
      k1 += p1;
      k2 -= p2;
    }
    return (make_pair(k1, k2));
  }
}
