int64_t n, m;
const int64_t maxN = 2e5 + 1;
int64_t tree[4 * maxN + 4];
pair<int64_t, int64_t> frogs[maxN];
pair<int64_t, int64_t> mos[maxN];
int64_t cnt[maxN];
int64_t pos[maxN];
vector<int64_t> order;
void Input() {
  read(n, m);
  for (int64_t i = (1); (n) > (1) ? i <= (n) : i >= (n);
       (n) > (1) ? i += 1 : i -= 1)
    read(frogs[i].first, frogs[i].second);
  for (int64_t i = (1); (m) > (1) ? i <= (m) : i >= (m);
       (m) > (1) ? i += 1 : i -= 1)
    read(mos[i].first, mos[i].second);
}
bool cmp(int64_t a, int64_t b) { return frogs[a].first < frogs[b].first; }
void buildTree(int64_t p = 1, int64_t b = 1, int64_t e = n) {
  if (b == e)
    tree[p] = frogs[order[b]].second + frogs[order[b]].first;
  else {
    int64_t mid = (b + e) / 2;
    buildTree(2 * p, b, mid);
    buildTree(2 * p + 1, mid + 1, e);
    tree[p] = max(tree[2 * p], tree[2 * p + 1]);
  }
}
void update(int64_t key, int64_t p = 1, int64_t b = 1, int64_t e = n) {
  if (key < b || e < key) return;
  if (b == e)
    tree[p] = frogs[order[b]].second + frogs[order[b]].first;
  else {
    int64_t mid = (b + e) / 2;
    if (key <= mid)
      update(key, 2 * p, b, mid);
    else
      update(key, 2 * p + 1, mid + 1, e);
    tree[p] = max(tree[2 * p], tree[2 * p + 1]);
  }
}
int64_t lowestFrog(int64_t pos, int64_t p = 1, int64_t b = 1, int64_t e = n) {
  while (b < e) {
    int64_t mid = (b + e) / 2;
    if (tree[2 * p] >= pos)
      e = mid, p = p * 2;
    else
      b = mid + 1, p = p * 2 + 1;
  }
  if (frogs[order[b]].first <= pos &&
      pos <= frogs[order[b]].second + frogs[order[b]].first)
    return order[b];
  else
    return -1;
}
void Solve() {
  order.resize(n + 1);
  iota((order).begin(), (order).end(), 0);
  sort(1 + (order).begin(), (order).end(), cmp);
  for (int64_t i = (1); (n) > (1) ? i <= (n) : i >= (n);
       (n) > (1) ? i += 1 : i -= 1)
    pos[order[i]] = i;
  buildTree();
  multiset<pair<int64_t, int64_t> > curMos;
  memset(cnt, 0, sizeof cnt);
  for (int64_t i = (1); (m) > (1) ? i <= (m) : i >= (m);
       (m) > (1) ? i += 1 : i -= 1) {
    int64_t j = lowestFrog(mos[i].first);
    if (j != -1) {
      frogs[j].second += mos[i].second;
      cnt[j]++;
      int64_t treePos = pos[j];
      while (1) {
        multiset<pair<int64_t, int64_t> >::iterator nearestMos =
            curMos.lower_bound(make_pair(frogs[j].first, 0ll));
        if (nearestMos == curMos.end() ||
            nearestMos->first > frogs[j].first + frogs[j].second)
          break;
        frogs[j].second += nearestMos->second;
        cnt[j]++;
        curMos.erase(nearestMos);
      }
      update(treePos);
    } else
      curMos.insert(mos[i]);
  }
  for (int64_t i = (1); (n) > (1) ? i <= (n) : i >= (n);
       (n) > (1) ? i += 1 : i -= 1)
    cout << cnt[i] << " " << frogs[i].second << "\n";
}
