void pl(int v = R, int p = 0) {
  dp[v] = dp[p] + 1;
  g[dp[v]].push_back(v);
  pa[v][0] = p;
  int k = 1, z;
  while (k < 19 && (z = pa[v][k - 1])) pa[v][k] = pa[z][k - 1], ++k;
  for (int i = 0; i < (int)tr[v].size(); ++i) pl(tr[v][i], v);
}
int lca(int a, int b) {
  if (dp[a] < dp[b]) swap(a, b);
  int d = dp[a] - dp[b], j = 0;
  while (d) {
    if (d & 1) a = pa[a][j];
    d >>= 1;
    ++j;
  }
  if (a == b) return a;
  for (int i = 18; i >= 0; --i)
    if (pa[a][i] != pa[b][i]) a = pa[a][i], b = pa[b][i];
  return pa[a][0];
}
void go(vector<int> &g) {
  if (g.empty()) return;
  stack<pair<int, int> > st;
  st.push(make_pair(dp[g[0]] - 1, 1));
  an[g[0]] += dp[g[0]] - 1;
  long long cr = dp[g[0]] - 1;
  for (int i = 1; i < (int)g.size(); ++i) {
    int b = dp[lca(g[i - 1], g[i])];
    pair<int, int> ad = st.top();
    cr -= (long long)ad.second * ad.first;
    st.pop();
    while (!st.empty() && st.top().first > b) {
      ad.second += st.top().second;
      cr -= (long long)st.top().first * st.top().second;
      st.pop();
    }
    ad.first = b;
    if (b == dp[g[i]] - 1)
      st.push(make_pair(ad.first, ad.second + 1));
    else
      st.push(ad), st.push(make_pair(dp[g[i]] - 1, 1));
    cr += (long long)ad.second * ad.first;
    cr += dp[g[i]] - 1;
    an[g[i]] += cr;
  }
}
