long long ans = 0;
void increase(Tree *pos, long long val) {
  if (pos->left == pos->right)
    pos->value += val;
  else
    pos->tag += val;
}
void update(Tree *pos) {
  pos->value = min(pos->left_child->value + pos->left_child->tag,
                   pos->right_child->value + pos->right_child->tag);
}
void downdate(Tree *pos) {
  increase(pos->left_child, pos->tag);
  increase(pos->right_child, pos->tag);
  pos->tag = 0LL;
}
void build(Tree *pos, int x, int y) {
  pos->left = x;
  pos->right = y;
  pos->value = 0LL;
  pos->tag = 0LL;
  if (x == y) return;
  int mid = (x + y) >> 1;
  pos->left_child = t + Size;
  pos->right_child = t + Size + 1;
  int siz = Size;
  Size += 2;
  build(t + siz, x, mid);
  build(t + siz + 1, mid + 1, y);
  update(pos);
}
void add(Tree *pos, int x, int y, long long val) {
  if (pos->left >= x && pos->right <= y) {
    increase(pos, val);
    return;
  }
  if (pos->right < x || pos->left > y) return;
  add(pos->left_child, x, y, val);
  add(pos->right_child, x, y, val);
  update(pos);
}
long long query(Tree *pos, int x, int y) {
  if (pos->left >= x && pos->right <= y) return pos->value + pos->tag;
  if (pos->right < x || pos->left > y) return 9223372036854775807LL;
  downdate(pos);
  update(pos);
  return min(query(pos->left_child, x, y), query(pos->right_child, x, y));
}
