      pos->left_child->right, pos->right_child->left, pos->right_child->right);
  debug(pos->left_child);
  debug(pos->right_child);
}
void ddb(Tree *pos, long long vl) {
  if (pos->left == pos->right) {
    printf("left:%d right:%d val:%I64d\n", pos->left, pos->right,
           pos->value + vl);
