    pre[--b] |= 1 << --a;
  }
  memset(seat, -1, sizeof(seat));
  memset(state, 0, sizeof(state));
  for (int i = 0; i < n; i++)
    for (seat[i] = 0;; seat[i]++) {
      if (seat[i] >= n) {
        printf("The times have changed\n");
        return 0;
      }
      if (state[seat[i]]) continue;
      memset(f, 0, sizeof(f));
      j = 0;
      for (int k = 0; k < n; k++)
        if (seat[k] >= 0 && state[seat[k]]) j += 1 << seat[k];
      if ((pre[seat[i]] & j) != pre[seat[i]]) continue;
      j += 1 << seat[i];
      f[j] = 1;
      for (; j <= N; j++)
        for (int k = 0; k < n; k++)
          if (f[j] && !state[k] && seat[i] != k && (pre[k] & j) == pre[k] &&
              !(j & 1 << k))
            f[j | 1 << k] += f[j];
      if (y > f[N]) {
        y -= f[N];
        continue;
      } else {
        state[seat[i]] = 1;
        break;
