			return true;
		} else if (start == end) {
			return false;
		} else {
			if (tElement < sArray[(start + end) / 2]) {
				return binarySearch(sArray, tElement, start,
						(start + end) / 2);
			} else {
				return binarySearch(sArray, tElement, (start + end) / 2+1, end);
			}
		}
	}
