const int MN = 20123, MOD = 1000 * 1000 * 1000 + 7, mod = MOD;
int inv[MN], fict[MN], invf[MN], dp[MN][MN];
void fact() {
  fict[0] = inv[0] = invf[0] = 1;
  fict[1] = inv[1] = invf[1] = 1;
  for (int i = 2; i < MN; i++) {
    inv[i] = 1ll * inv[MOD % i] * (MOD - MOD / i) % MOD;
    fict[i] = 1ll * fict[i - 1] * i % MOD;
    invf[i] = 1ll * invf[i - 1] * inv[i] % MOD;
  }
}
int chose(int a, int b) {
  return 1ll * fict[a] * invf[b] % MOD * invf[a - b] % MOD;
}
int main() {
