  dp[0][0] = 1;
  for (int i = 1; i <= n; i++)
    for (int j = 0; j <= n; j++)
      dp[i][j] =
          ((i >= j ? dp[i - 1][j] : 0) +
           (i >= j && j
                ? 1ll * dp[i][j - 1] *
                      chose(n * k - (j - 1) * (k - 1) - i - 1, k - 2) % MOD
                : 0)) %
          MOD;
  cout << 1ll * dp[n][n] * fict[n] % mod;
}

