vector<int> cur[2];
void ae(int x, int y, int r) {
  e[x].push_back(make_pair(y, r));
  e[y].push_back(make_pair(x, r));
}
int bad = 0;
void go(int x) {
  for (int i = 0; i < e[x].size(); i++) {
    int to = e[x][i].first;
    int r = e[x][i].second;
    if (was[to] != -1) {
      if (was[to] != was[x] ^ r) bad = 1;
      continue;
    }
    was[to] = was[x] ^ r;
    cur[was[to]].push_back(to);
    go(to);
  }
}
vector<int> solve(int ch) {
  for (int i = 0; i < n; i++) e[i].clear();
  for (int i = 0; i < n; i++)
    for (int j = 0; j < 2; j++)
      for (int k = 0; k < v[i][j].size(); k++) {
        int to = v[i][j][k];
        e[i].push_back(make_pair(to, j ^ ch));
      }
  vector<int> ans;
  for (int i = 0; i < n; i++) was[i] = -1;
  bad = 0;
  for (int i = 0; i < n; i++)
    if (was[i] == -1) {
      cur[0].clear();
      cur[1].clear();
      cur[0].push_back(i);
      was[i] = 0;
      go(i);
      if (cur[0].size() > cur[1].size()) swap(cur[0], cur[1]);
      for (int j = 0; j < cur[0].size(); j++) ans.push_back(cur[0][j]);
    }
  if (bad) {
    ans.clear();
    ans.push_back(-1);
  }
  return ans;
}
