long long int f(int ind, int x) {
  if (ind > n || ind < 1) return 0;
  if (dp[ind][x] != -1) return dp[ind][x];
  if (vis[ind][x] != -1) return dp[ind][x] = -100000000000005;
  vis[ind][x]++;
  if (ind == 1) return dp[ind][x] = -100000000000005;
  int tmp = 1;
  if (x == 0) tmp = -1;
  return dp[ind][x] = f(ind + tmp * ar[ind - 1], (x + 1) % 2) + ar[ind - 1];
}
