#include <bits/stdc++.h>
using namespace std;
const int maxn = 2010;
template <int mod, int Base>
class String_Hasher {
 public:
  char buf[maxn];
  int v[maxn], p[maxn];
  inline void init() {
    v[0] = 0;
    p[0] = 1;
    int L = strlen(buf + 1);
    for (int i = 1; i <= L; i++) v[i] = (1ll * v[i - 1] * Base + buf[i]) % mod;
    for (int i = 1; i <= L; i++) p[i] = 1ll * p[i - 1] * Base % mod;
  }
  inline int query(int l, int r) {
    return (v[r] - 1ll * p[r - l + 1] * v[l - 1] % mod + mod) % mod;
  }
};
struct Hasher {
  char buf[maxn];
  int L;
  String_Hasher<1000000007, 1313131> H1;
  String_Hasher<1000000009, 1313131> H2;
  inline void init() {
    L = strlen(buf + 1);
    for (int i = 1; i <= L + 1; i++) H1.buf[i] = H2.buf[i] = buf[i];
    H1.init();
    H2.init();
  }
  inline pair<int, int> query(int l, int r) {
    return make_pair(H1.query(l, r), H2.query(l, r));
  }
  inline pair<int, int> queryrev(int l, int r) {
    l = L - l + 1, r = L - r + 1;
    if (l > r) swap(l, r);
    return query(l, r);
  }
} h[2], revh[2], hs;
char s[2][maxn], t[maxn];
const int mod = 1000000007;
inline void Add(int &a, int b) { a = a + b >= mod ? a + b - mod : a + b; }
int n, m;
int f[maxn][maxn][2];
inline int getans() {
  int res = 0;
  for (int i = 0; i < 2; i++) {
    memcpy(h[i].buf, s[i], sizeof(s[i]));
    memcpy(revh[i].buf, s[i], sizeof(s[i]));
    reverse(revh[i].buf + 1, revh[i].buf + n + 1);
    h[i].init();
    revh[i].init();
  }
  memset(f, 0, sizeof(f));
  for (int i = 0; i <= n; i++) f[i][0][0] = f[i][0][1] = 1;
  for (int l = 1; l < n; l++)
    for (int r = l + 1; r <= n; r++) {
      int len = r - l + 1;
      if ((len << 1) > m) continue;
      bool flag0 = 1, flag1 = 1;
      if (h[0].query(l, r) != hs.query(len + 1, len << 1)) flag0 = 0;
      if (revh[1].queryrev(l, r) != hs.query(1, len)) flag0 = 0;
      if (flag0) f[r][len << 1][0] = 1;
      if (revh[0].queryrev(l, r) != hs.query(1, len)) flag1 = 0;
      if (h[1].query(l, r) != hs.query(len + 1, len << 1)) flag1 = 0;
      if (flag1) f[r][len << 1][1] = 1;
      if ((len << 1) == m) {
        if (flag0) res++;
        if (flag1) res++;
      }
    }
  for (int i = 0; i <= n; i++)
    for (int j = 0; j <= m; j++) {
      if (t[j + 1] == s[0][i + 1]) Add(f[i + 1][j + 1][0], f[i][j][0]);
      if (t[j + 1] == s[1][i + 1]) Add(f[i + 1][j + 1][1], f[i][j][1]);
      if (j < m - 1 && t[j + 1] == s[0][i + 1] && t[j + 2] == s[1][i + 1])
        Add(f[i + 1][j + 2][1], f[i][j][0]);
      if (j < m - 1 && t[j + 1] == s[1][i + 1] && t[j + 2] == s[0][i + 1])
        Add(f[i + 1][j + 2][0], f[i][j][1]);
    }
  int ans = 0;
  for (int i = 1; i <= n; i++) Add(ans, (f[i][m][0] + f[i][m][1]) % mod);
  for (int l = 1; l < n; l++)
    for (int r = l + 1; r <= n; r++) {
      int len = r - l + 1;
      if ((len << 1) > m) continue;
      int st = (m - (len << 1));
      bool flag0 = 1, flag1 = 1;
      if (h[0].query(l, r) != hs.query(st + 1, st + len)) flag0 = 0;
      if (revh[1].queryrev(l, r) != hs.query(st + len + 1, st + (len << 1)))
        flag0 = 0;
      if (flag0) Add(ans, f[l - 1][m - (len << 1)][0]);
      if (revh[0].queryrev(l, r) != hs.query(st + len + 1, st + (len << 1)))
        flag1 = 0;
      if (h[1].query(l, r) != hs.query(st + 1, st + len)) flag1 = 0;
      if (flag1) Add(ans, f[l - 1][m - (len << 1)][1]);
      if ((len << 1) == m) {
        if (flag0) res++;
        if (flag1) res++;
      }
    }
  Add(ans, ans);
  Add(ans, mod - res);
  return ans;
}
