      k++;
    }
    d1[c] = k;
    if (c + k - 1 > r) {
      l = c - k + 1;
      r = c + k - 1;
    }
  }
  l = 1;
  r = 0;
  for (int c = 1; c <= sz; c++) {
    if (c > r) {
      k = 0;
    } else {
