    }
    while (c - k - 1 >= 1 && c + k <= sz && mpp[c - k - 1] == mpp[c + k]) {
      k++;
    }
    d2[c] = k;
    if (c + k >= r) {
      l = c - k;
      r = c + k - 1;
    }
  }
