    s += bit[k - 1];
    k -= k & -k;
  }
  return s;
}
void add(long long int k, long long int x) {
  k++;
  long long int xA = min(x, a);
  long long int xB = min(x, b);
  while (k <= n) {
    bitA[k - 1] += xA;
    bitB[k - 1] += xB;
    k += k & -k;
  }
}
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> fixN >> a >> b >> q;
  while (q--) {
    cin >> type;
    if (type == 1) {
      cin >> x >> y;
      add(x - 1, y);
    } else {
      cin >> x;
      ans = sum(x - 2, bitB) + (sum(n - 1, bitA) - sum((x + fixN) - 2, bitA));
      cout << ans << "\n";
    }
  }
}

