namespace BIT {
int T[MAXN];
inline int lowbit(int x) { return x & (-x); }
inline void add(int x, int d) {
  while (x <= N) T[x] += d, x += lowbit(x);
}
inline int pref(int x) {
  int ret = 0;
  while (x >= 1) ret += T[x], x -= lowbit(x);
  return ret;
}
}  // namespace BIT
int main() {
