}

import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb=new StringBuilder();
        int t=Integer.parseInt(bu.readLine());
        while(t-->0)
        {
            int n=Integer.parseInt(bu.readLine());
            int i,a[]=new int[n];
            ArrayList<Integer> g[]=new ArrayList[n+1];
            for(i=0;i<=n;i++)
            g[i]=new ArrayList<>();
            String s[]=bu.readLine().split(" ");
            for(i=0;i<n;i++)
            {
                a[i]=Integer.parseInt(s[i]);
                g[a[i]].add(i);
            }

            int ans[]=new int[n];
            Arrays.fill(ans,Integer.MAX_VALUE);
            for(i=1;i<=n;i++)
            if(g[i].size()!=0)
            {
                if(g[i].size()==n) {ans[0]=i; continue;}
                int k=g[i].get(0),l=k,r=n-1,mid;
                while(l<=r)
                {
                    mid=(l+r)/2;
                    if(possible(g[i],mid,n-1))
                    {
                        k=mid;
                        r=mid-1;
                    }
                    else l=mid+1;
                }
                ans[k]=Math.min(ans[k],i);
            }
            for(i=1;i<n;i++)
            ans[i]=Math.min(ans[i],ans[i-1]);
            for(i=0;i<n;i++)
            if(ans[i]==Integer.MAX_VALUE) sb.append("-1 ");
            else sb.append(ans[i]+" ");
            sb.append("\n");
        }
        System.out.print(sb);
    }

    static boolean possible(ArrayList<Integer> a,int k,int must)
    {
        int n=a.size(),l=a.get(0)-k,r=a.get(0)+k,i;
        if(l>0) return false;
        for(i=1;i<n;i++)
        {
            int nl=a.get(i)-k;
            if(nl>r) return false;
            r=a.get(i)+k;
        }
        if(r<must) return false;
        return true;
    }
}

