#include <bits/stdc++.h>
using namespace std;
const int N = 300005;
inline int in() {
  int x;
  scanf("%d", &x);
  return x;
}
inline long long lin() {
  long long x;
  scanf("%I64d", &x);
  return x;
}
vector<int> G[N];
int n, q, T = 0;
int st[N], ed[N], H[N];
void dfs(int u, int h) {
  st[u] = ++T;
  H[u] = h;
  for (int i = 0; i < (int)G[u].size(); i++) {
    dfs(G[u][i], h + 1);
  }
  ed[u] = T;
}
struct ST {
  long long *X, *Y, *Z;
  ST() {
    X = new long long[4 * N];
    Y = new long long[4 * N];
    Z = new long long[4 * N];
    memset(X, 0, sizeof X);
    memset(Y, 0, sizeof Y);
    memset(Z, 0, sizeof Z);
  }
  ~ST() {
    delete[] X;
    delete[] Y;
    delete[] Z;
  }
  void Merge(int x) {
    X[x] = (X[x + x] + X[x + x + 1]) % 1000000007;
    Y[x] = (Y[x + x] + Y[x + x + 1]) % 1000000007;
  }
  void lazy(int x) {
    if (Z[x] == -1) {
      X[x + x] = (X[x + x] + X[x]) % 1000000007;
      Y[x + x] = (Y[x + x] + Y[x]) % 1000000007;
      Z[x + x] = -1;
      X[x + x + 1] = (X[x + x + 1] + X[x]) % 1000000007;
      Y[x + x + 1] = (Y[x + x + 1] + Y[x]) % 1000000007;
      Z[x + x + 1] = -1;
      Z[x] = 0;
    }
  }
  void modify(int x, int s, int e, int l, int r, long long a, long long b) {
    if (s >= l && e <= r) {
      X[x] = (X[x] + a) % 1000000007;
      Y[x] = (Y[x] + b) % 1000000007;
      Z[x] = -1;
      return;
    }
    int mid = (s + e) >> 1;
    if (r <= mid)
      modify(x + x, s, mid, l, r, a, b);
    else if (l > mid)
      modify(x + x + 1, mid + 1, e, l, r, a, b);
    else {
      modify(x + x, s, mid, l, r, a, b);
      modify(x + x + 1, mid + 1, e, l, r, a, b);
    }
  }
  long long Get_A(int x, int s, int e, int v, long long carry = 0) {
    if (s >= v && e <= v) return (X[x] + carry) % 1000000007;
    int mid = (s + e) >> 1;
    if (v <= mid)
      return Get_A(x + x, s, mid, v, (carry + X[x]) % 1000000007) % 1000000007;
    else if (v > mid)
      return Get_A(x + x + 1, mid + 1, e, v, (carry + X[x]) % 1000000007) %
             1000000007;
    else {
      return (Get_A(x + x, s, mid, v, (carry + X[x]) % 1000000007) %
                  1000000007 +
              Get_A(x + x + 1, mid + 1, e, v, (carry + X[x]) % 1000000007)) %
             1000000007;
    }
  }
  long long Get_B(int x, int s, int e, int v, long long carry = 0) {
    if (s >= v && e <= v) return (Y[x] + carry) % 1000000007;
    int mid = (s + e) >> 1;
    if (v <= mid)
      return Get_B(x + x, s, mid, v, (carry + Y[x]) % 1000000007) % 1000000007;
    else if (v > mid)
      return Get_B(x + x + 1, mid + 1, e, v, (carry + Y[x]) % 1000000007) %
             1000000007;
    else {
      return (Get_B(x + x, s, mid, v, (carry + Y[x]) % 1000000007) %
                  1000000007 +
              Get_B(x + x + 1, mid + 1, e, v, (carry + Y[x]) % 1000000007) %
                  1000000007) %
             1000000007;
    }
  }
};
int main() {
  n = in();
  for (int i = 2; i <= n; i++) {
    int x = in();
    G[x].push_back(i);
  }
  dfs(1, 0);
  ST A = ST(), B = ST();
  q = in();
  while (q--) {
    int ty = in();
    if (ty == 1) {
      int v = in();
      long long x = lin(), k = lin();
      long long up = x + (H[v] * k) % 1000000007;
      A.modify(1, 1, n, st[v], ed[v], up % 1000000007, 0);
      B.modify(1, 1, n, st[v], ed[v], 0, k);
    } else {
      int v = in();
      long long res = A.Get_A(1, 1, n, st[v]) -
                      (B.Get_B(1, 1, n, st[v]) * H[v]) % 1000000007;
      printf("%I64d\n", (res + 1000000007) % 1000000007);
    }
  }
  return 0;
}

