      for (int j = 1; j <= n; j++) dijkstra(i, j);
    }
    for (int i = 1; i <= c; i++) {
      for (int j = 1; j <= n; j++) {
        for (int k = 1; k <= n; k++) {
          if (dist[i][j][k] >= 22000) continue;
          dist2[j][k] = min(dist2[j][k], z[i][dist[i][j][k]]);
        }
      }
    }
    for (int i = 0; i < 102; i++) {
      dp[i] = 1 << 30;
    }
    dp[s] = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 1; j <= n; j++) {
        for (int k = 1; k <= n; k++) {
          dp[k] = min(dp[k], dp[j] + dist2[j][k]);
        }
      }
    }
    cout << dp[g] << endl;
  }
  return 0;
}

