public class Main {
    public static class Task {


        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int search = 5;
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }
            long[] dp = new long[search + 1];
            Arrays.fill(dp, -Long.MAX_VALUE / 2);
            {
                int md = arr[0] % 3;
                dp[md] = arr[0] / 3;
                while (md + 3 <= search && md < arr[0]) {
                    md += 3;
                    dp[md] = dp[md - 3] - 1;
                }
            }
            for (int i = 1; i < n; i++) {
                long[] nextDp = new long[search + 1];
                Arrays.fill(nextDp, -Long.MAX_VALUE / 2);
                for (int prev = 0; prev <= search; prev++) {
                    for (int j = 0; j <= prev; j++) {
                        if (j * 2 > arr[i]) break;
                        int prevLeft = prev - j;
                        int curLeft = arr[i] - 2 * j;
                        long valueGain = dp[prev] + j;
                        if (prevLeft + curLeft <= search) {
                            nextDp[prevLeft + curLeft] = Math.max(nextDp[prevLeft + curLeft], valueGain);
                        }
//                        for (int k = 0; k < 2; k++) {
                            for (int l = 0; l < 2; l++) {
                                int actualPrevLeft = prevLeft;
                                if (actualPrevLeft < 0) continue;
                                int actualCurLeft = (curLeft % 3) + l * 3;
                                if (actualCurLeft > curLeft) continue;
                                long ag = valueGain + curLeft / 3 - l;
                                if (actualCurLeft + actualPrevLeft <= search)
                                    nextDp[actualPrevLeft + actualCurLeft] = Math.max(nextDp[actualCurLeft + actualPrevLeft], ag);
                            }
//                        }
                    }
                }
                dp = nextDp;
            }
            long maxi = 0;
            for (int i = 0; i <= search; i++) {
                maxi = Math.max(maxi, dp[i]);
            }
            pw.println(maxi);

        }

        public void shuffle(long[] x) {
            Random rnd = new Random();
            for (int i = 0; i < x.length; i++) {
                int r = rnd.nextInt(x.length - i) + i;
                long t = x[r];
                x[r] = x[i];
                x[i] = t;
            }
        }
    }

