int visit[2][100001];
bool dfs(int now, int c, int goal) {
  for (auto& e : edges[now]) {
    int nextColor = c;
    if (goal != e.second) nextColor = c - (c - 1) % 2 + c % 2;
    if (visit[goal][e.first] == 0) {
      color[goal][nextColor].push_back(e.first);
      visit[goal][e.first] = nextColor;
      if (!dfs(e.first, nextColor, goal)) return false;
    } else if (visit[goal][e.first] != nextColor)
      return false;
  }
  return true;
}
int coloring(int goal) {
  int c = 1;
  int ans = 0;
  for (int i = 1; i <= n; i++) {
    if (visit[goal][i] != 0) continue;
    visit[goal][i] = c;
    color[goal][c].push_back(i);
    if (!dfs(i, c, goal)) return 987654321;
    ans += min(color[goal][c].size(), color[goal][c + 1].size());
    c += 2;
  }
  return ans;
}
