int mod = 998244353;
inline int mul(int x, int y) { return 1ll * x * y % mod; }
int add(int x, int y) { return x + y >= mod ? x + y - mod : x + y; }
int sub(int x, int y) { return x - y < 0 ? x - y + mod : x - y; }
int sq(int x) { return 1ll * x * x % mod; }
int pow(int a, int b) {
  return b == 0 ? 1 : (b & 1 ? mul(a, sq(pow(a, b / 2))) : sq(pow(a, b / 2)));
}
int n, m1, m, a[1050], dp[1050][1050], vis[1050][1050] = {0}, cdiv[1050],
                                       diff[1050], loc[550];
int solve(int l, int r) {
  if (l >= r) return 1;
  if (vis[l][r]) return dp[l][r];
  memset(cdiv, 0, sizeof(cdiv));
  memset(loc, 0, sizeof(loc));
  for (int i = l; i <= r; i++) {
    if (loc[a[i]]) {
      cdiv[loc[a[i]] + 1] += 1;
      cdiv[i + 1] -= 1;
    } else {
      loc[a[i]] = i;
    }
  }
  for (int i = l; i <= r + 1; i++) cdiv[i] += cdiv[i - 1];
  vis[l][r] = 1;
  int mi = 2000, mlp, mrp;
  for (int j = l; j <= r; j++) {
    if (a[j] < mi) {
      mi = a[j];
      mlp = j;
    }
    if (a[j] <= mi) mrp = j;
  }
  int cmul = 1, la = mlp - 1;
  for (int j = mlp; j <= mrp; j++) {
    if (a[j] == mi) {
      if (j - la > 1) {
        cmul = mul(cmul, solve(la + 1, j - 1));
      }
      la = j;
    }
  }
  int cl = 0, cr = 0;
  for (int hf = l; hf <= mlp; hf++) {
    if (cdiv[hf] == 0) {
      cl = add(cl, mul(solve(l, hf - 1), solve(hf, mlp - 1)));
    }
  }
  for (int hf = mrp + 1; hf <= r + 1; hf++) {
    if (cdiv[hf] == 0) cr = add(cr, mul(solve(mrp + 1, hf - 1), solve(hf, r)));
  }
  dp[l][r] = mul(cmul, mul(cl, cr));
  return dp[l][r];
}
