#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1 << 21;
struct segtree {
  int l[MAXN], r[MAXN], m[MAXN];
  int val[MAXN], tadd[MAXN];
  void pull(int o) { val[o] = max(val[(o << 1)], val[(o << 1 | 1)]); }
  void push_add(int o, int x) {
    val[o] += x;
    tadd[o] += x;
  }
  void push(int o) {
    if (l[o] == m[o]) return;
    if (tadd[o]) {
      push_add((o << 1), tadd[o]);
      push_add((o << 1 | 1), tadd[o]);
      tadd[o] = 0;
    }
  }
  void build(int o, int ll, int rr) {
    int mm = (ll + rr) / 2;
    l[o] = ll;
    r[o] = rr;
    m[o] = mm;
    if (ll == mm) return;
    build((o << 1), ll, mm);
    build((o << 1 | 1), mm, rr);
  }
  void add(int o, int ll, int rr, int x) {
    if (ll <= l[o] and r[o] <= rr) {
      push_add(o, x);
    } else {
      push(o);
      if (m[o] > ll) add((o << 1), ll, rr, x);
      if (m[o] < rr) add((o << 1 | 1), ll, rr, x);
      pull(o);
    }
  }
  void add(int l, int x) { add(1, l, l + 1, x); }
  void add(int l, int r, int x) {
    if (l < r) add(1, l, r, x);
  }
  int query(int o, int ll, int rr) {
    if (ll <= l[o] and r[o] <= rr) {
      return val[o];
    } else {
      push(o);
      if (rr <= m[o]) return query((o << 1), ll, rr);
      if (ll >= m[o]) return query((o << 1 | 1), ll, rr);
      return max(query((o << 1), ll, rr), query((o << 1 | 1), ll, rr));
    }
  }
  int query(int l) { return query(1, l, l + 1); }
  int query(int l, int r) { return query(1, l, r); }
} seg;
int n;
int a[1 << 20];
int fla[1 << 20], llb[1 << 20];
int main() {
  scanf("%d", &n);
  seg.build(1, 0, n + n + 1);
  for (int i = 0; i < int(n); i++) scanf("%d", a + i);
  copy(a, a + n, a + n);
  fill(begin(fla), end(fla), n + n);
  fill(begin(llb), end(llb), -1);
  stack<int> s;
  s.push(0);
  for (int i = 1; i < n + n; i++) {
    while (s.size() and a[s.top()] >= a[i]) {
      fla[s.top()] = i;
      s.pop();
    }
    s.push(i);
  }
  s = stack<int>();
  s.push(n + n - 1);
  for (int i = n + n - 2; i >= 0; i--) {
    while (s.size() and a[s.top()] >= a[i]) {
      llb[s.top()] = i;
      s.pop();
    }
    s.push(i);
  }
  for (int i = 0; i < n; i++) {
    if (llb[i] >= 0) seg.add(i, seg.query(llb[i]) + 1);
    seg.add(llb[i] + 1, i, 1);
  }
  int ans = INT_MAX, shift = -1;
  for (int i = 0; i < n; i++) {
    int cur = seg.query(i, i + n);
    if (cur < ans) {
      ans = cur;
      shift = i;
    }
    seg.add(i + 1, fla[i], -1);
    seg.add(llb[i + n] + 1, i + n, 1);
    if (i + n - llb[i + n] < n) seg.add(i + n, seg.query(llb[i + n]) + 1);
  }
  cout << ans + 1 << ' ' << shift << endl;
  return 0;
}

