class TaskF {
    public void solve(int testNumber, InputReader in, OutputWriter out){
	    int nhills = in.ri(), mfrogs = in.ri(), kmosq = in.ri();
	    int[] d = IOUtils.readIntArray(in, mfrogs);
	    IntPair[] res = new IntPair[mfrogs];
	    int[] mosq = IOUtils.readIntArray(in, kmosq);
	    for(int i = 0; i < d.length; i++) {
		    int jump = d[i], killed = 0;
		    for(int mos : mosq) if (mos % jump == 0) killed++;
		    res[i] = new IntPair(killed, i);
	    }
	    Arrays.sort(res);
	    ArrayList<Integer> ans = new ArrayList<>();
	    for(int i = 0; i < res.length; i++) {
		    if (res[0].first == res[i].first) ans.add(res[i].second);
	    }
	    out.printLine(ans.size());
	    for(int i : ans) out.print((i + 1) + " ");
    }
}

class InputReader {
	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;
	private SpaceCharFilter filter;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	public int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}
	public int ri(){
		return readInt();
	}

	public int readInt() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		int res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}
	public boolean isSpaceChar(int c) {
		if (filter != null)
			return filter.isSpaceChar(c);
		return isWhitespace(c);
	}

	public static boolean isWhitespace(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}
	public interface SpaceCharFilter {
		public boolean isSpaceChar(int ch);
	}
}

