/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int _2n = 2 * n;
            double[] a = new double[_2n];
            double sumA = 0;
            double sumB = 0;
            int dif = 0;
            for (int i = 0; i < _2n; i++) {
                a[i] = in.nextDouble();
                sumA += a[i];
                sumB += Math.floor(a[i]);
                dif += Math.ceil(a[i]) - Math.floor(a[i]);
            }
            double ans = Double.POSITIVE_INFINITY;
            int maxUP = Math.min(n, dif);
            for (int i = Math.max(0, dif - n); i <= maxUP; i++) {
                double absDif = Math.abs(sumA - sumB - i);
                ans = Math.min(ans, absDif);
            }
            out.println(String.format("%.3f", ans));
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

    }
}

