	public static int ste(int n){
		Map<Integer, Integer>mp = new TreeMap<Integer, Integer>();
		int prod = 1;
		if (n == 1)
			return prod;
        int count = 0; 

        // count the number of times 2 divides  
        while (!(n % 2 > 0)) { 
            // equivalent to n=n/2;  
            n >>= 1; 

            count++; 
        } 

        // if 2 divides it  
        if (count > 0) { 
        	if (count%2 == 1)
        		prod*=2;
        } 

        // check for all the possible  
        // numbers that can divide it  
        for (int i = 3; i*i <= n; i += 2) { 
            count = 0; 
            while (n % i == 0) { 
                count++; 
                n = n / i; 
            } 
            if (count > 0) { 
               if (count%2 == 1)
            	   prod*=i;
            } 
        } 

        // if n at the end is a prime number.  
        if (n > 2) { 
          prod*=n;
        } 
        return prod;
	}
	static class Number1{
		private static Map<Integer, Integer> mp;
		public Number1(int n){
			mp = new TreeMap<Integer, Integer>();
			if (n == 1)
				return;
	        int count = 0; 

	        // count the number of times 2 divides  
	        while (!(n % 2 > 0)) { 
	            // equivalent to n=n/2;  
	            n >>= 1; 

	            count++; 
	        } 

	        // if 2 divides it  
	        if (count > 0) { 
	            mp.put(2 , count%2);
	        } 

	        // check for all the possible  
	        // numbers that can divide it  
	        for (int i = 3; i*i <= n; i += 2) { 
	            count = 0; 
	            while (n % i == 0) { 
	                count++; 
	                n = n / i; 
	            } 
	            if (count > 0) { 
	                mp.put(i, count%2);
	            } 
	        } 

	        // if n at the end is a prime number.  
	        if (n > 2) { 
	           mp.put(n, 1);
	        } 
		}
		@Override
		public int hashCode(){
			int prod = 1;
			for(int j : mp.keySet()){
				for(int k = 0;k<mp.get(j);k++){
					prod*=j;
				}
			}
			return prod;
		}
		@Override
		public boolean equals(Object obj){
			Number1 n = (Number1)(obj);
			for(int j : this.mp.keySet()){
				if (!this.mp.containsKey(j) || this.mp.get(j) != n.mp.get(j))
					return false;
			}
			return true;
		}
	}
