#include <bits/stdc++.h>
using namespace std;
long long fib[100];
int M;
int G(long long a) {
  if (a == 0) return 0;
  if (a == 1) return 0;
  if (a == 2) return 1;
  int idx = lower_bound(fib, fib + M, a) - fib - 1;
  long long v = fib[idx];
  return G(a - v) + 1;
}
void init() {
  M = 2;
  fib[0] = 1;
  fib[1] = 2;
  M = 2;
  long long a = fib[0], b = fib[1];
  while (b <= 100000000000000000ll) {
    long long c = b + a;
    fib[M++] = c;
    a = b, b = c;
  }
}
long long dist(long long a, long long b, int n) {
  if (a > fib[n]) return 1000000;
  if (a < b) swap(a, b);
  if (a == b) return 0;
  if (n <= 0) return 100000000;
  long long C = fib[n - 1];
  assert(a >= b);
  if (a > C && b > C) {
    return dist(a - C, b - C, n - 2);
  } else if (a > C) {
    return G(a - C) + 1 + min((long long)G(b), dist(C, b, n - 1));
  } else {
    return dist(a, b, n - 1);
  }
}
int main() {
  init();
  int T, N;
  cin >> T >> N;
  if (N >= M) N = M - 1;
  long long a, b;
  for (int test = 0; test < (T); test++) {
    cin >> a >> b;
    if (b > a) swap(a, b);
    long long ans = dist(a, b, N);
    long long f = fib[lower_bound(fib, fib + M, b) - fib];
    long long ans2 = dist(f, a, N) + dist(f, b, N);
    ans = min(ans, ans2);
    cout << ans << endl;
  }
}

