		int ret = 0;
		while (!que.empty()) {
			state s1 = que.front(); que.pop();
			if (s1.steps == Q) {
				ret = max(ret, s1.result);
				continue;
			}
			vector<vector<int> > h1(2, vector<int>(2, -1));
			for (int i = 0; i < 2; i++) {
				for (int j = 0; j < 2; j++) {
					for (int k = 0; k < s1.v.size(); k++) {
						if (s1.v[k][i][j] == '#') h1[i][j] = k + 1;
					}
				}
			}
			for (int dy = -1; dy <= 1; dy++) {
				for (int dx = -1; dx <= 1; dx++) {
					bool ok = true;
					vector<vector<string> > v1(2, vector<string>(2, ".."));
					for (int i = 0; i < 2; i++) {
						for (int j = 0; j < 2; j++) {
							for (int k = 0; k < 2; k++) {
								int tx = k + dx, ty = j + dy;
								if (w[s1.steps][i][j][k] == '#') {
									if (0 <= tx && tx < 2 && 0 <= ty && ty < 2) v1[i][ty][tx] = '#';
									else ok = false;
								}
							}
						}
					}
					if (ok) {
						vector<vector<int> > h2(2, vector<int>(2, -1));
						for (int i = 0; i < 2; i++) {
							for (int j = 0; j < 2; j++) {
								for (int k = v1.size() - 1; k >= 0; k--) {
									if (v1[k][i][j] == '#') h2[i][j] = k;
								}
							}
						}
						int h3 = 0;
						for (int i = 0; i < 2; i++) {
							for (int j = 0; j < 2; j++) {
								if (h1[i][j] == -1 || h2[i][j] == -1) continue;
								h3 = max(h3, h1[i][j] - h2[i][j]);
							}
						}
						vector<vector<string> > v2 = s1.v; v2.resize(v2.size() + 2, vector<string>({ "..", ".." }));
						for (int i = 0; i < 2; i++) {
							for (int j = 0; j < 2; j++) {
								for (int k = 0; k < 2; k++) {
									if (v1[i][j][k] == '#') v2[h3 + i][j][k] = '#';
								}
							}
						}
						int cnt = 0;
						for (int i = v2.size() - 1; i >= 0; i--) {
							if (v2[i] == vector<string>({ "##", "##" })) v2.erase(v2.begin() + i), cnt++;
						}
						que.push(state{ v2, s1.steps + 1, s1.result + cnt });
					}
				}
			}
		}
