void _hash()
{
	memset(hash,0,sizeof(hash));
	for(int i=0;i<2;i++)
	{
		for(int j=0;j<n;j++)
			hash[i][0][j]=j==0?s[i][j]-'a':hash[i][0][j-1]*29+s[i][j]-'a';
		for(int j=n-1;j>=0;j--)
			hash[i][1][j]=hash[i][1][j+1]*29+s[i][j]-'a';
	}
	for(int i=0;i<m;i++)
		lover[i]=!i?0+p[i]-'a':lover[i-1]*29+p[i]-'a';
}
ui gethash(int k,int l,int r,int flag)
{
	ui res;
	if(flag==0)//positive
	{
		res=hash[k][0][r];
		res-=l==0?0:hash[k][0][l-1]*_pow[r-l+1];
		return res;
	}
	else
	{
		res=hash[k][1][l];
		res-=hash[k][1][r+1]*_pow[r-l+1];
		return res;
	}
}
ui getori(int l,int r)
{
	ui res;
	res=lover[r];
	res-=l==0?0:lover[l-1]*_pow[r-l+1];
	return res;
}
void solve()
{
	_hash();
	memset(dp,0,sizeof(dp));
	for(int j=0;j<2;j++)
			{
				for(int b=2;m-2*b>=0&&b<m;b++)
				{
					if(gethash(j,0,b-1,1)==getori(m-b,m-1)&&gethash(j^1,0,b-1,0)==getori(m-2*b,m-b-1))
						ans++;
				}
			}
	for(int i=0;i<n;i++)
	{
		if(i==3)
			i=3;
		dp[i][0][0]=dp[i][1][0]=1;
		for(int j=0;j<2;j++)
		{
			for(int a=2;i-a+1>=0;a++)
			{
				if(gethash(j,i-a+1,i,1)==getori(0,a-1)&&gethash(j^1,i-a+1,i,0)==getori(a,2*a-1))
					dp[i][j^1][2*a]++;
			}
			for(int k=1;k<=m;k++)
			{
				if(s[j][i]!=p[k-1])continue;
				dp[i][j][k]+=i==0?(k-1==0?1:0):dp[i-1][j][k-1];
				if(s[j^1][i]==p[k])
					dp[i][j^1][k+1]+=i==0?(k-1==0?1:0):dp[i-1][j][k-1];
			}
		}
		ans=(ans+dp[i][0][m])%zqf;
		ans=(ans+dp[i][1][m])%zqf;
		if(i<n-1)
		{
			for(int j=0;j<2;j++)
			{
				for(int b=2;m-2*b>=0&&i+b<m;b++)
				{
					if(gethash(j,i+1,i+b,1)==getori(m-b,m-1)&&gethash(j^1,i+1,i+b,0)==getori(m-2*b,m-b-1))
						ans=(ans+dp[i][j^1][m-2*b])%zqf;
				}
			}
		}
	}
