	public static void CountingSort(int[] A, int[] B, int k, int n) {
		int []C = new int[k + 1];
		Arrays.fill(C, 0);
		for(int j = 1; j <= n; j++) {
			C[A[j]] ++;
		}
		for(int i = 1; i <= k; i++) {
			C[i] = C[i] + C[i - 1];
		}
		for(int j = n; j >= 1; j--) {
			B[C[A[j]]] = A[j];
			C[A[j]] --;
		}
	}
