                visited[y] = true;
                ConnexComponent subresult = DFS(y, edges, visited);
                result.nodes += subresult.nodes;
                result.edges += subresult.edges;
            }
        }
        return result;
    }

    public static final class ConnexComponent {
        int nodes;
        int edges;

        public ConnexComponent(int nodes, int edges) {
            this.nodes = nodes;
            this.edges = edges;
        }
    }
}

