const int N = 4005;
const long long inf = 1e15;
int a[N], n, k, pos[N][N], tot;
map<int, int> mp;
bool g[N][N];
long long f[N][N];
long long solve(int L, int R, int m) {
  if (m < 0) return -inf;
  if (L > R) {
    if (m == 0) return 0;
    return -inf;
  }
  if (L == R) {
    if (m == 0) return 0;
    if (m == 1) return a[L] * (k - 1);
    return -inf;
  }
  if (!mp.count(L * n + R)) mp[L * n + R] = ++tot;
  int x = mp[L * n + R];
  if (g[x][m]) return f[x][m];
  g[x][m] = 1;
  int mid = pos[L][R];
  if (mid == L)
    return f[x][m] =
               max(solve(L + 1, R, m), solve(L + 1, R, m - 1) + a[L] * (k - 1) -
                                           2ll * a[L] * (m - 1));
  if (mid == R)
    return f[x][m] =
               max(solve(L, R - 1, m), solve(L, R - 1, m - 1) + a[R] * (k - 1) -
                                           2ll * a[R] * (m - 1));
  if (mid - L < R - mid)
    for (int i = 0; i <= min(m, mid - L + 1); ++i)
      f[x][m] = max(f[x][m], solve(L, mid, i) + solve(mid + 1, R, m - i) -
                                 2ll * i * (m - i) * a[mid]);
  else
    for (int i = 0; i <= min(m, R - mid + 1); ++i)
      f[x][m] = max(f[x][m], solve(L, mid, m - i) + solve(mid + 1, R, i) -
                                 2ll * i * (m - i) * a[mid]);
  return f[x][m];
}
