            while(k >= 0 && x[i] - x[j] > x[j] - x[k]) {
                --k;
            }
            if(k >= 0 && x[i] - x[j] == x[j] - x[k]) prv[i][j] = k;
            ++i;
        }
    }
    REP(i, 1, n) rep(j, i) {
        int k = prv[i][j];
        if(k == -1) continue;
        dp[i][j] = max(dp[i][j], dp[j][k]+1);
    } 
    int ans = 0;
    rep(i, n) rep(j, i) ans = max(ans, dp[i][j]);
    cout << ans << '\n';
    return 0;
}

