  for (auto it = cnt.begin(); it != cnt.end(); it++) {
    ans += (long long int)it->second * (it->second - 1) / 2;
    for (int i = 0; i < 26; i++) {
      if (it->first & pow_2[i]) {
        auto temp = cnt.find(it->first - pow_2[i]);
        if (temp != cnt.end()) ans += (long long int)temp->second * it->second;
      }
    }
  }
  cout << ans << endl;
