#include <bits/stdc++.h>
using namespace std;
struct c {
  int par, child;
  bool right;
  bool operator<(const c &S) const {
    if (par != S.par) return par < S.par;
    if (right != S.right) return right < S.right;
    return child < S.child;
  }
};
int N, C;
vector<c> con;
vector<int> left_v, right_v;
vector<int> res;
bool construct(int u, int st, int ed, int m) {
  if (st > ed) {
    for (int i = (u + 1); i < (m + 1); ++i) left_v[i - 1] = i;
    return true;
  }
  int max_left = -1;
  int min_right = N;
  int next_st;
  for (next_st = st; next_st <= ed; ++next_st) {
    int i = next_st;
    if (con[i].par != u) break;
    if (con[i].right) {
      min_right = min(min_right, con[i].child);
    } else {
      max_left = max(max_left, con[i].child);
    }
  }
  if (max_left >= min_right) return false;
  if (max_left == -1 && min_right == N) {
    left_v[u] = u + 1;
    return construct(u + 1, next_st, ed, m);
  }
  if (max_left == -1 && min_right != N) {
    right_v[u] = u + 1;
    return construct(u + 1, next_st, ed, m);
  }
  if (max_left != -1 && min_right == N) {
    left_v[u] = u + 1;
    return construct(u + 1, next_st, ed, m);
  }
  if (max_left != -1 && min_right != N) {
    int next_ed;
    for (next_ed = next_st; next_ed <= ed; ++next_ed) {
      int i = next_ed;
      if (con[i].par > max_left) break;
      max_left = max(max_left, max(con[i].par, con[i].child));
    }
    left_v[u] = u + 1;
    right_v[u] = max_left + 1;
    return construct(u + 1, next_st, next_ed - 1, max_left) &&
           construct(max_left + 1, next_ed, ed, m);
  }
  return false;
}
void output(int u) {
  if (u == -1) return;
  output(left_v[u]);
  res.push_back(u);
  output(right_v[u]);
}
int main(int argc, char **argv) {
  cin >> N >> C;
  con = vector<c>(C);
  left_v = vector<int>(N, -1);
  right_v = vector<int>(N, -1);
  for (int i = (0); i < (C); ++i) {
    string s;
    cin >> con[i].par >> con[i].child >> s;
    con[i].par--;
    con[i].child--;
    con[i].right = s == "RIGHT";
    if (con[i].par >= con[i].child) {
      puts("IMPOSSIBLE");
      return 0;
    }
  }
  sort(con.begin(), con.end());
  if (!construct(0, 0, C - 1, N - 1)) {
    puts("IMPOSSIBLE");
  } else {
    output(0);
    vector<int> pos(N, -1);
    for (int i = (0); i < (N); ++i) pos[res[i]] = i;
    for (int i = (0); i < (N); ++i)
      if (pos[i] == -1) {
        puts("IMPOSSIBLE");
        return 0;
      }
    for (int i = (0); i < (C); ++i) {
      if (con[i].right && pos[con[i].par] > pos[con[i].child]) {
        puts("IMPOSSIBLE");
        return 0;
      }
      if (!con[i].right && pos[con[i].par] < pos[con[i].child]) {
        puts("IMPOSSIBLE");
        return 0;
      }
    }
    for (int i = (0); i < (N); ++i) printf("%d ", res[i] + 1);
  }
  return 0;
}

