  for (int mask = 1; mask < (1 << N); mask++) {
    dp[mask] = sum = 0LL;
    for (i = 0; i < N; i++)
      if ((mask >> i) & 1) {
        dp[mask] += dp[mask ^ (1 << i)];
        sum += ((long long)n[i]);
      }
