public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        private int n;
        private int[] answer;
        private int[] value;
        private List<Integer>[] adj;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            value = new int[n + 1];
            answer = new int[n + 1];
            adj = new List[n + 1];
            for (int i = 1; i <= n; i++) {
                value[i] = in.nextInt();
                adj[i] = new ArrayList<>();
            }
            for (int i = 1; i <= n - 1; i++) {
                int u = in.nextInt(), v = in.nextInt();
                adj[u].add(v);
                adj[v].add(u);
            }
            dfs(1, -1, new TreeSet<>(Collections.singleton(0)));
            for (int i = 1; i <= n; i++) {
                if (i > 1) out.print(" ");
                out.print(answer[i]);
            }
        }

        private int gcd(int a, int b) {
            return b == 0 ? a : gcd(b, a % b);
        }

        private void dfs(int cur, int par, TreeSet<Integer> all) {
            TreeSet<Integer> nextAll = new TreeSet<>();
            nextAll.add(all.last());
            for (int value : all) {
                nextAll.add(gcd(value, this.value[cur]));
            }
            answer[cur] = nextAll.last();
            for (int adj : this.adj[cur]) {
                if (adj != par) {
                    dfs(adj, cur, nextAll);
                }
            }
        }

    }

    static class InputReader {
        private int lenbuf = 0;
        private int ptrbuf = 0;
        private InputStream in;
        private byte[] inbuf = new byte[1024];

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = in.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

    }
}

