const long long mod = 998244353;
const int maxn = 2013;
int n;
string s;
long long dpLeft[maxn][maxn];
long long dpRight[maxn][maxn];
void add(long long& x, long long y) {
  x %= mod;
  y %= mod;
  x += y;
  x %= mod;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> s;
  n = s.length();
  dpLeft[0][0] = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (dpLeft[i][j] == 0) continue;
      if (s[i] == '(') {
        add(dpLeft[i + 1][j + 1], dpLeft[i][j]);
      } else if (s[i] == ')') {
        add(dpLeft[i + 1][j], dpLeft[i][j]);
      } else {
        assert(s[i] == '?');
        add(dpLeft[i + 1][j + 1], dpLeft[i][j]);
        add(dpLeft[i + 1][j], dpLeft[i][j]);
      }
    }
  }
  dpRight[n + 1][0] = 1;
  for (int i = n; i > 0; i--) {
    for (int j = 0; j < n; j++) {
      if (dpRight[i + 1][j] == 0) continue;
      if (s[i - 1] == ')') {
        add(dpRight[i][j + 1], dpRight[i + 1][j]);
      } else if (s[i - 1] == '(') {
        add(dpRight[i][j], dpRight[i + 1][j]);
      } else {
        assert(s[i - 1] == '?');
        add(dpRight[i][j + 1], dpRight[i + 1][j]);
        add(dpRight[i][j], dpRight[i + 1][j]);
      }
    }
  }
  long long res = 0;
  for (int i = 1; i <= n - 1; i++) {
    for (long long j = 0; j <= n; j++) {
      add(res, j * dpLeft[i][j] % mod * dpRight[i + 1][j] % mod);
    }
  }
  res %= mod;
  res += mod;
  res %= mod;
  cout << res << endl;
  return 0;
}

