void oula() {
  for (int i = 2; i < maxn; i++) {
    if (vis[i] == 0) p[++x] = i, minn[i] = i;
    for (int j = 1; j <= x && i * p[j] < maxn; j++) {
      vis[i * p[j]] = 1;
      minn[i * p[j]] = p[j];
      if (i % p[j] == 0) break;
    }
  }
}
