#include <bits/stdc++.h>
using namespace std;
int main() {
  int n, a;
  scanf("%d", &n);
  unordered_map<int, int> cnt;
  for (int i = 0; i < n; ++i) {
    scanf(" %d", &a);
    ++cnt[a];
  }
  vector<pair<int, int>> A(cnt.begin(), cnt.end());
  sort(A.begin(), A.end(), [](pair<int, int>& x, pair<int, int>& y) {
    return x.second < y.second;
  });
  int h = 1, tot = 0, pre = 0, N = A.size();
  for (int i = 1, j = 0; i * i <= n; ++i) {
    while (j < N && A[j].second <= i) pre += A[j++].second;
    int v = (pre + i * (N - j)) / i * i;
    if (v > tot && v / i >= i) {
      tot = v;
      h = i;
    }
  }
  for (int i = 0; i < N; ++i) A[i].second = min(A[i].second, h);
  int w = tot / h;
  vector<vector<int>> mat(h, vector<int>(w));
  for (int i = 0, x = 0, y = 0; i < tot;
       ++i, x = (x + 1) % h, y = (y + 1) % w) {
    if (mat[x][y]) ++x;
    mat[x][y] = A.back().first;
    --A.back().second;
    if (!A.back().second) A.pop_back();
  }
  printf("%d\n%d %d\n", tot, h, w);
  for (auto row : mat) {
    for (int z : row) printf("%d ", z);
    printf("\n");
  }
  return 0;
}

