M = 998244353 

def fact(n, f=1):
    res = 1
    for i in range(f, n+1):
        res *= i
    return res 

def comb(n, k):
    k = max(k, n - k)
    return fact(n, k + 1) // fact(n - k)

def s(n, k):
    if k > n:
        return 0
    res = comb(n - k + k - 1, k - 1)
    return res % M

def solve(case):
    [n, k] = inlt()
    res = 0
    for i in range(1, n):
        if i * k <= n:
            res = (res + s(n // i, k)) % M
        else:
            break
    return res

