	}

	public class Problem
	{
		public Problem()
		{

		}

		public class Person
		{
			public Person()
			{

			}

			public int index = 0;
			public int endIndex = 0;
			public int startIndex = 0;
			public long clawLength = 0;
			public boolean isDead = false;

			public void setParams(int _index,int _endIndex,int _startIndex,long _clawLength)
			{
				index = _index;
				endIndex = _endIndex;
				startIndex = _startIndex;
				clawLength = _clawLength;
			}

			public void setDead()
			{
				isDead = true;
			}
		}

		public int solve(int n,long[] l)
		{
			int ans = 0;

			Person[] persons = new Person[n];
			int reach = 0;

			for(int i = 0; i < n; i++)
			{
				persons[i] = new Person();
				persons[i].setParams(i, -1, -1, l[i]);
			}

			for(int i = 1; i < n; i++)
			{
				if(persons[i].clawLength > 0)
				{
					reach = i - (int)persons[i].clawLength;
					if(reach >= 0)
					{
						persons[reach].endIndex = i - 1;
						persons[reach].startIndex = reach;
						persons[i - 1].startIndex = reach;
						persons[i - 1].endIndex = i - 1;
					}
					else
					{
						reach = 0;
						persons[reach].endIndex = i - 1;
						persons[reach].startIndex = reach;
						persons[i - 1].startIndex = reach;
						persons[i - 1].endIndex = i - 1;	
					}
				}
			}
			boolean doset = true;
			for(int i = 1,si = persons[0].startIndex,ei = persons[0].endIndex; i < n; i++)
			{	
				if(doset)
				{
					if(persons[i].startIndex == si && persons[i].endIndex == ei)
					{
						doset = false;
					}
					else
					{
						persons[i].setDead();
						persons[i].startIndex = si;
						persons[i].endIndex = ei;
					}
				}
				else
				{
					if(persons[i].startIndex > 0 && persons[i].endIndex > 0)
					{
						doset = true;
						si = persons[i].startIndex;
						ei = persons[i].endIndex;
					}
				}
			}
			for(int i = 0; i < n; i++)
			{	
				if(persons[i].startIndex == -1 && persons[i].endIndex == -1)
				{
					ans++;
				}
			}

			return ans;
		}
	}
}

