#include <iostream>

using namespace std;
using LL = long long;

const int maxN = 5e5 + 5;
const int mod = 998244353;

int n, m, ans;
int fac[maxN], inv[maxN];

inline void Mod(int& x)
{ x >= mod ? x -= mod : x < 0 ? x += mod : 0; }

int QPow(int bas, int ind)
{
    int res = 1;
    while (ind)
    {
        if (ind & 1)
            res = (LL)res * bas % mod;
        bas = (LL)bas * bas % mod;
        ind >>= 1;
    }
    return res;
}

void Init(int lim)
{
    fac[0] = inv[0] = 1;
    for (int i = 1; i <= lim; ++i)
        fac[i] = (LL)fac[i - 1] * i % mod;
    inv[lim] = QPow(fac[lim], mod - 2);
    for (int i = lim - 1; i; --i)
        inv[i] = (LL)inv[i + 1] * (i + 1) % mod;
}

inline int C(int n, int m)
{ return (LL)fac[n] * inv[m] % mod * inv[n - m] % mod; }

int main()
{
    cin >> n >> m;
    if (n > m)
        swap(n, m);
    Init(m);
    for (int i = 0; i <= n; ++i)
        if (i & 1)
            Mod(ans -= (LL)C(n, i) * C(m, i) % mod * fac[i] % mod * QPow(m + 1, n - i) % mod * QPow(n + 1, m - i) % mod);
        else
            Mod(ans += (LL)C(n, i) * C(m, i) % mod * fac[i] % mod * QPow(m + 1, n - i) % mod * QPow(n + 1, m - i) % mod);
    cout << ans << endl;
}

