using namespace std;
const int Maxn = 5e5 + 10;
int n;
long long ans;
vector<int> V[Maxn];
int read() {
  int ret = 0;
  char c = getchar();
  while (c < '0' || c > '9') c = getchar();
  while (c >= '0' && c <= '9') {
    ret = ret * 10 + c - '0';
    c = getchar();
  }
  return ret;
