namespace Seg {
int mx[Maxn << 2], num[Maxn << 2], tag[Maxn << 2];
void up(int u) {
  int x = u << 1, y = (u << 1) | 1;
  if (mx[x] < mx[y]) swap(x, y);
  mx[u] = mx[x];
  if (mx[x] == mx[y])
    num[u] = num[x] + num[y];
  else
    num[u] = num[x];
}
void put_tag(int u, int key) {
  mx[u] += key;
  tag[u] += key;
}
void down(int u) {
  if (tag[u]) {
    put_tag(u << 1, tag[u]);
    put_tag((u << 1) | 1, tag[u]);
    tag[u] = 0;
  }
}
void build(int u, int l, int r) {
  num[u] = r - l + 1;
  if (l == r) return;
  int mid = (l + r) >> 1;
  build(u << 1, l, mid);
  build((u << 1) | 1, mid + 1, r);
}
void update(int u, int l, int r, int li, int ri, int key) {
  if (l > r || li > r || l > ri || li > ri) return;
  if (l == li && r == ri) {
    put_tag(u, key);
    return;
  }
  int mid = (l + r) >> 1;
  down(u);
  update(u << 1, l, mid, li, min(mid, ri), key);
  update((u << 1) | 1, mid + 1, r, max(mid + 1, li), ri, key);
  up(u);
}
int query(int u, int l, int r, int li, int ri) {
  if (l > r || li > r || l > ri || li > ri) return 0;
  if (l == li && r == ri) return (mx[u] == n) ? num[u] : 0;
  int mid = (l + r) >> 1;
  down(u);
  return query(u << 1, l, mid, l, min(mid, ri)) +
         query((u << 1) | 1, mid + 1, r, max(mid + 1, li), ri);
}
}  // namespace Seg
int main() {
  n = read();
  Seg::build(1, 1, n);
  for (int i = 1; i <= n; i++) {
    V[i].push_back(0);
    Seg::update(1, 1, n, 1, n, 1);
  }
  for (int i = 1; i <= n; i++) {
    int key = read(), siz = V[key].size();
    if (siz >= 4)
      Seg::update(1, 1, n, V[key][siz - 4] + 1, V[key][siz - 3], -1);
    if (siz >= 3) Seg::update(1, 1, n, V[key][siz - 3] + 1, V[key][siz - 2], 1);
    Seg::update(1, 1, n, V[key][siz - 1] + 1, i, -1);
    V[key].push_back(i);
    ans += Seg::query(1, 1, n, 1, i);
  }
  printf("%lld\n", ans);
  return 0;
}

