#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 4000 + 5, MOD = 924844033;
int fac[MAX_N] = {1}, head[MAX_N], dp[MAX_N][MAX_N], m[MAX_N], n, k;
bool mark[MAX_N];
int dfs(int v) {
  mark[v] = true;
  vector<int> adj;
  if (v < n)
    v += n;
  else
    v -= n;
  if (v / n == (v - k) / n) adj.push_back(v - k);
  if (v / n == (v + k) / n) adj.push_back(v + k);
  int res = 1;
  for (int u : adj)
    if (u >= 0 && !mark[u]) res += dfs(u);
  return res;
}
void find_m() {
  int sz = 0;
  for (int i = 0; i < 2 * n; i++)
    if (!mark[i]) {
      head[sz + 1] = true;
      sz += dfs(i) - 1;
    }
  for (int i = 0; i <= sz; i++) dp[0][i] = 1;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= sz; j++)
      dp[i][j] = (dp[i][j - 1] + dp[i - 1][j - 2 + head[j]]) % MOD;
  for (int i = 0; i <= n; i++) m[i] = dp[i][sz];
}
int main() {
  cin >> n >> k;
  for (int i = 1; i <= n; i++) fac[i] = 1LL * fac[i - 1] * i % MOD;
  find_m();
  int ans = 0;
  for (int i = 0, s = 1; i <= n; i++, s *= -1)
    ans = (ans + 1LL * s * m[i] * fac[n - i]) % MOD;
  cout << ans;
}

