using namespace std;
int n;
int a[6], b[6], ord[6], c[6];
vector<pair<int, int> > v, nv;
struct S {
  vector<pair<int, int> > v;
  int from;
  S(vector<pair<int, int> > v, int from) : v(v), from(from) {}
  S() {}
};
vector<S> s;
void pr(int a, int b) {
  if (a == 1) {
    printf("inc %d\n", ord[b] + 1);
  } else {
    printf("dec %d\n", ord[b] + 1);
  }
}
S hor, ver, res;
bool invI, invJ;
void _incI() {
  assert(ver.from < (int)ver.v.size());
  res.v.push_back(ver.v[ver.from++]);
}
void _decI() {
  assert(ver.from > 0);
  pair<int, int> p = ver.v[--ver.from];
  p.first = -p.first;
  res.v.push_back(p);
}
void _incJ() {
  assert(hor.from < (int)hor.v.size());
  res.v.push_back(hor.v[hor.from++]);
}
void _decJ() {
  assert(hor.from > 0);
  pair<int, int> p = hor.v[--hor.from];
  p.first = -p.first;
  res.v.push_back(p);
}
void decI() {
  if (invI)
    _incI();
  else
    _decI();
}
void incI() {
  if (invI)
    _decI();
  else
    _incI();
}
void decJ() {
  if (invJ)
    _incJ();
  else
    _decJ();
}
void incJ() {
  if (invJ)
    _decJ();
  else
    _incJ();
}
S merge() {
  res.v.clear();
  res.from = 0;
  int i = ver.from;
  int j = hor.from;
  int n = (int)ver.v.size() + 1;
  int m = (int)hor.v.size() + 1;
  assert(i % 2 == j % 2);
  invI = invJ = false;
  if (i % 2 == 1) {
    for (int jj = j; jj >= 0; --jj) {
      if (jj & 1) {
        for (int _ = 0; _ < (int)(i); ++_) decI();
      } else {
        for (int _ = 0; _ < (int)(i); ++_) incI();
      }
      if (jj != 0)
        decJ();
      else
        incI();
    }
    for (int ii = i + 1; ii < n; ++ii) {
      if (ii & 1) {
        for (int _ = 0; _ < (int)(j); ++_) decJ();
      } else {
        for (int _ = 0; _ < (int)(j); ++_) incJ();
      }
      if (ii != n - 1)
        incI();
      else
        incJ();
    }
    for (int jj = j + 1; jj < m; ++jj) {
      if (jj & 1) {
        for (int _ = 0; _ < (int)(n - 1); ++_) incI();
      } else {
        for (int _ = 0; _ < (int)(n - 1); ++_) decI();
      }
      if (jj != m - 1) incJ();
    }
  } else {
    if (i == n - 1) {
      i = 0;
      invI = true;
    }
    if (j == 0) {
      j = m - 1;
      invJ = true;
    }
    for (int _ = 0; _ < (int)(i); ++_) decI();
    decJ();
    for (int ii = 0; ii < (int)(i + 1); ++ii) {
      if (ii & 1) {
        for (int _ = 0; _ < (int)(j - 1); ++_) incJ();
      } else {
        for (int _ = 0; _ < (int)(j - 1); ++_) decJ();
      }
      incI();
    }
    for (int jj = 0; jj < (int)(j + 1); ++jj) {
      if (jj & 1) {
        for (int _ = 0; _ < (int)(n - i - 2); ++_) decI();
      } else {
        for (int _ = 0; _ < (int)(n - i - 2); ++_) incI();
      }
      if (jj != j) incJ();
    }
    if (j != m - 1) {
      incJ();
      for (int jj = j + 1; jj < m; ++jj) {
        if (jj & 1) {
          for (int _ = 0; _ < (int)(n - 1); ++_) decI();
        } else {
          for (int _ = 0; _ < (int)(n - 1); ++_) incI();
        }
        if (jj != m - 1) incJ();
      }
    }
  }
  return res;
}
int main() {
