  }
  for (int i = 0; i < (int)(n); ++i) ord[i] = i;
  for (int i = 0; i < (int)(n - 1); ++i)
    if (a[i] % 2 == 0) {
      swap(a[i], a[n - 1]);
      swap(b[i], b[n - 1]);
      swap(ord[i], ord[n - 1]);
      break;
    }
  if (a[n - 1] % 2 == 0) {
    for (int i = 0; i < (int)(n - 1); ++i) {
      nv.clear();
      for (int j = 0; j < (int)(a[i]); ++j) {
        if (j & 1) {
          reverse(v.begin(), v.end());
