      pr(v[i].first, v[i].second);
    }
    for (int i = 0; i < ind; ++i) {
      pr(v[i].first, v[i].second);
    }
    return 0;
  }
  int sum = 0;
  for (int i = 0; i < (int)(n); ++i) sum += b[i] - 1;
  if (sum % 2 == 1) {
