    return 0;
  }
  cout << "Path" << endl;
  for (int i = 0; i < (int)(n); ++i) {
    vector<pair<int, int> > cur;
    for (int j = 0; j < (int)(a[i] - 1); ++j) {
      cur.push_back(make_pair(1, i));
    }
    s.push_back(S(cur, b[i] - 1));
  }
  while ((int)s.size() > 1) {
    bool done = false;
    for (int i = 0; i < (int)(s.size()); ++i) {
      for (int j = 0; j < (int)(i); ++j) {
        if ((s[i].from + s[j].from) % 2 == 0) {
          hor = s[i];
          ver = s[j];
          s[i] = merge();
          swap(s[j], s.back());
          s.pop_back();
          done = true;
          break;
        }
      }
      if (done) {
        break;
      }
    }
    assert(done);
  }
  for (pair<int, int> p : s[0].v) {
    pr(p.first, p.second);
  }
  return 0;
}

