bool dfs(int v) {
  was[v] = it;
  for (int j = 0; j < (int)g[v].size(); j++) {
    int u = g[v][j];
    if (alive_b[u] && pb[u] == -1) {
      pa[v] = u;
      pb[u] = v;
      return true;
    }
  }
  for (int j = 0; j < (int)g[v].size(); j++) {
    int u = g[v][j];
    if (alive_b[u] && was[pb[u]] != it) {
      if (dfs(pb[u])) {
        pa[v] = u;
        pb[u] = v;
        return true;
      }
    }
  }
  return false;
}
bool dfs_finish(int v, int finish) {
  if (pa[v] == finish) {
    return true;
  }
  int old = pa[v];
  pa[v] = -1;
  pb[old] = -1;
  it++;
  if (dfs(pb[finish])) {
    pa[v] = finish;
    pb[finish] = v;
    return true;
  }
  pa[v] = old;
  pb[old] = v;
  return false;
}
