void go(int org, int n, int p){
	if(can[org][n])
		return;
	can[org][n] = 1;
	if(!n)
		return;
	for(int i = min(n, p); i > 0; i--)
		go(org, n % i, p);
	for(int i = 0; i < with.size(); i++)
		if(with[i] <= n)
			go(org, n % with[i], p);
}

