    }
  } else {
    long long val2 = 1;
    for (int i = 0; i <= exponenti[unde]; ++i) {
      factorizare[nr_divizori + 1][unde] = val2;
      genereaza_divizori(unde - 1, val * val2);
      val2 *= factori[unde];
    }
  }
}
