  for (register int i = 1; i < n; ++i) e[i].w = max(a[e[i].u], a[e[i].v]);
  sort(e + 1, e + n);
  for (register int i = 1; i < n; ++i) merge(e[i].u, e[i].v, e[i].w);
  printf("%I64d", ans);
  return 0;
}

