public class A {

    private static final String problem = null;

    private static FastReader scan;
    private static PrintWriter pw;

    public static void main(String[] args) throws IOException {
        if(problem == null) {
            scan = new FastReader(new BufferedReader(new InputStreamReader(System.in)));
            pw = new PrintWriter(System.out);
        }else {
            scan = new FastReader(new BufferedReader(new FileReader(problem + ".in")));
            pw = new PrintWriter(new FileWriter(problem + ".out"));
        }
        solve();
        pw.close();
    }

    private static boolean colored[][];
    private static int n, m, k;

    private static boolean check(int x, int y) {
        try {
            if(colored[x - 1][y] && colored[x - 1][y - 1] && colored[x][y - 1]) return true;
        }catch(Exception ex) {}
        try {
            if(colored[x + 1][y] && colored[x + 1][y + 1] && colored[x][y + 1]) return true;
        }catch(Exception ex) {}
        try {
            if(colored[x - 1][y] && colored[x - 1][y + 1] && colored[x][y + 1]) return true;
        }catch(Exception ex) {}
        try {
            if(colored[x + 1][y] && colored[x + 1][y - 1] && colored[x][y - 1]) return true;
        }catch(Exception ex) {}
        return false;
    }

    private static void solve() throws IOException {
        n = scan.nextInt(); m = scan.nextInt(); k = scan.nextInt();
        colored = new boolean[m][n];
        for(int i = 0; i < k; ++i) {
            int y = scan.nextInt() - 1, x = scan.nextInt() - 1;
            colored[x][y] = true;
            if(check(x, y)) {
                pw.println(i + 1);
                return;
            }
        }
        pw.println(0);
    }

    private static class FastReader {

        private StringTokenizer tokens;
        private BufferedReader reader;

        public FastReader(BufferedReader reader) throws IOException {
            this.reader = reader;
            this.tokens = new StringTokenizer(reader.readLine());
        }

        public String next() throws IOException {
            if(tokens.hasMoreTokens()) return tokens.nextToken();
            tokens = new StringTokenizer(reader.readLine());
            return tokens.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.valueOf(next());
        }

        public long nextLong() throws IOException {
            return Long.valueOf(next());
        }

    }

