vector<int> sze(N);
vector<int> rnk(N);
vector<int> ans(N);
int n;
void init() {
  for (int i = 0; i < N; i++) {
    parent[i] = i;
    sze[i] = 1;
    rnk[i] = 1;
    mx[i] = make_pair(-1, -1);
  }
}
int find_set(int a) {
  if (parent[a] == a) return a;
  return parent[a] = find_set(parent[a]);
}
void union_set(int a, int b) {
  int x = find_set(a), y = find_set(b);
  if (x == y) return;
  if (rnk[x] == rnk[y]) rnk[x]++;
  if (rnk[x] > rnk[y]) {
    for (auto &i : best[y]) {
      best[x][i.first] += i.second;
      if (best[x][i.first] > mx[x].first ||
          (best[x][i.first] == mx[x].first && mx[x].second > i.first)) {
        mx[x].first = best[x][i.first];
        mx[x].second = i.first;
      }
    }
    parent[y] = x;
    sze[x] += sze[y];
  } else {
    for (auto &i : best[x]) {
      best[y][i.first] += i.second;
      if (best[y][i.first] > mx[y].first ||
          (best[y][i.first] == mx[y].first && mx[y].second > i.first)) {
        mx[y].first = best[y][i.first];
        mx[y].second = i.first;
      }
    }
    parent[x] = y;
    sze[y] += sze[x];
  }
}
void dfs(int a, int par, int dep) {
  int x = find_set(a);
  best[x][dep]++;
  if (mx[x].first < best[x][dep] ||
      (mx[x].first == best[x][dep] && mx[x].second > dep)) {
    mx[x].first = best[x][dep];
    mx[x].second = dep;
  }
  for (int i : v[a]) {
    if (i == par) continue;
    dfs(i, a, dep + 1);
    union_set(i, a);
  }
  ans[a] = mx[find_set(a)].second - dep;
}
void solve() {
  init();
  dfs(1, 0, 0);
  for (int i = 1; i <= n; i++) cout << ans[i] << "\n";
}
