  public static String get(long x, long y, boolean a) {
    if (x > y) return get(y, x, a);
    if (x == 1) return (y-1)+""+(a?"B":"A");

    long c = y % x;
    if (c == 0) return "-";

    String m = get(c, x, !a);
    if (m.equals("-")) return m;
    long w = y / x;
    StringBuilder ret = new StringBuilder();
    ret.append(w);
    ret.append(a?"B":"A");
    ret.append(m);
    return ret.toString();
  }

