{ 
       if (r==0) 
          return 1; 

    int fac[n+1]; 
    fac[0] = 1; 
    for (int i=1 ; i<=n; i++) 
        fac[i] = fac[i-1]*i%p; 

    return (fac[n]* modInverse(fac[r], p) % p * 
        modInverse(fac[n-r], p) % p) % p; 
} 
