	static int inversion(Element[] array){
		int result = 0;
		for(int i = 0 ; i < array.length ; i++){
			if(i > array[i].id){
				result += i - array[i].id;
			}
		}

		return result;
	}

	static int Merge (Element[] array, int left, int mid, int right){
		int n1 = mid - left;
		int n2 = right - mid;
		int result = 0;
		Element[] L = new Element[n1 + 1];
		Element[] R = new Element[n2 + 1];

		for(int i = 0; i < n1 ; i++){
			L[i] = array[left + i];
		}

		for(int i = 0; i < n2 ; i++){
			R[i] = array[mid + i];
		}
		L[n1] = new Element(-1, Integer.MAX_VALUE);
		R[n2] = new Element(-1, Integer.MAX_VALUE);
		int i = 0;
		int j = 0;
		for(int k = left ; k < right ; k++){
			if(L[i].data <= R[j].data){
				array[k] = L[i];
				//System.out.print(L[i].data+" ");
				i++;

			}
			else {
				array[k] = R[j];
				if(n1 + j - k + left > 0 ){
					result += n1 + j - (k - left);
					//System.out.println("n1 + j:"+(n1+j)+" k - left= "+(k - left));
					//System.out.println("R["+j+"](" +R[j].data+ ") moves " +(n1 + j - (k - left)) );
