//			for(int j = 0; j < cV[0].length; j++)
//				out.print( cV[i][j]? 'E': 'N' );
//			out.println();
//		}

		if( K == 1 ){
			int total = 0;
			for(int i = 0; i < cH.length; i++)
				for(int j = 0; j < cH[0].length; j++)
					if( cH[i][j] ) total++;

			for(int i = 0; i < cV.length; i++)
				for(int j = 0; j < cV[0].length; j++)
					if( cV[i][j] ) total++;

			if( (double)total/(H*W) >= 3.0/4 ){
				out.println("YES");
				for(int i = 0; i < H; i++){
					for(int j = 0; j < W; j++)
						out.print(1 + " ");
