void findrt(int x, int fa, int tot) {
  sz[x] = 1;
  maxsz[x] = 0;
  for (int i = h[x]; i; i = a[i].ne) {
    if (vis[a[i].to] || a[i].to == fa) continue;
    findrt(a[i].to, x, tot);
    sz[x] += sz[a[i].to];
    maxsz[x] = max(maxsz[x], sz[a[i].to]);
  }
  maxsz[x] = max(maxsz[x], tot - sz[x]);
  if (maxsz[x] < maxsz[now]) now = x;
}
