  }
}
bool cmp(int a, int b) { return Size[now][a].first < Size[now][b].first; }
void dfs(int x) {
  vis[x] = 1;
  work(x, 0, x);
  f[x].push_back(x);
  d[x].push_back(0);
  int z[Size[x].size()];
  for (int i = 0; i < Size[x].size(); i++) z[i] = i;
  memcpy(gg, &Size[x][0], sizeof(Size[x][0]) * Size[x].size());
  sort(z, z + Size[x].size(), cmp);
  for (int i = 0; i < Size[x].size(); i++) Size[x][i] = gg[z[i]];
  for (int i = 1; i < Size[x].size(); i++)
    Size[x][i].second += Size[x][i - 1].second;
  tot1[x].push_back(make_pair(id[x], 0));
