using namespace std;
template <typename T>
using Graph = vector<vector<T>>;
int N, K;
int A[2016], B[2016];
bool used[2016];
vector<int> G[2016];
pair<int, int> solve(int i, int d) {
  if (d > K) return {0, 0};
  int res = 1;
  int mx = 0;
  used[i] = true;
  for (auto j : G[i]) {
    if (!used[j]) {
      auto p = solve(j, d + 1);
      int n = p.first, r = p.second;
      if (r == -1 || r + mx >= K) {
        used[i] = false;
        return {-1, -1};
      }
      mx = max(mx, r);
      res += n;
    }
  }
  used[i] = false;
  return {res, mx + 1};
}
int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> N >> K;
  for (int i = (int)(0); i < (int)(N - 1); i++) {
    cin >> A[i] >> B[i];
    G[A[i] - 1].push_back(B[i] - 1);
    G[B[i] - 1].push_back(A[i] - 1);
  }
  int ans = N;
  for (int i = (int)(0); i < (int)(N); i++) {
    used[i] = true;
    for (auto j : G[i]) {
      auto p = solve(j, 1);
      if (p.second == -1) continue;
      ans = min(ans, N - p.first - 1);
    }
    used[i] = false;
  }
  cout << ans << '\n';
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
class BIT {
 public:
  int size;
  int* bit;
  BIT(int _size = 0) {
    size = _size;
    bit = new int[size];
    for (int i = 0; i < size; i++) bit[i] = 0;
  }
  ~BIT() { delete[] bit; }
  int sum(int i) {
    int s = 0;
    while (i > 0) {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }
  void add(int i, int x) {
    while (i <= size) {
      bit[i] += x;
      i += i & -i;
    }
  }
};
vector<int> make(const vector<int> v) {
  vector<int> tmp = v;
  sort(tmp.begin(), tmp.end());
  int cnt = 1, idx = 0;
  map<int, int> M;
  while (idx < (int)v.size()) {
    M[tmp[idx]] = cnt++;
    while (idx + 1 < (int)tmp.size() && tmp[idx] == tmp[idx + 1]) idx++;
    idx++;
  }
  vector<int> vec(v.size());
  for (int i = 0; i < (int)v.size(); i++) vec[i] = M[v[i]];
  return vec;
}
int main() {
