using namespace std;

typedef unsigned long long ull;
typedef pair<ull,ull> ull2;

ull N;
string M;

map<ull,int> prime_factor(ull n){
  map<ull,int> res;
  for(int i=2;i*i<=n;i++){
    while(n % i == 0){
      ++res[i];
      n /= i;
    }
  }
  if(n != 1ULL)res[n] = 1ULL;
  return res;
}

ull StoULL(){
  ull ret = 0;
  for(int i=0;i<M.size();i++){
    ret *= N;
    ull tmp = (('0'<=M[i]&&M[i]<='9')?(M[i]-'0'):(M[i]-'A')+10ULL);
    ret += tmp;
  }
  return ret;
}

ull calc(ull value,ull2 tmp){
  ull ret = 0;
  ull pf = tmp.first;
  ull denom = tmp.second;
  while(value){
    ret += value / pf;
    value /= pf;
  }
  return ret/denom;
}

void compute(){
  map<ull,int> ppf = prime_factor(N);
  vector<ull2> pf;

  for(map<ull,int>::iterator it = ppf.begin() ; it != ppf.end() ; it++ ){
    pf.push_back(ull2((it->first),(it->second)));
  }

  ull value = StoULL();
  //cout << "value = " << value << endl;
  ull ans = ULLINF;

  for(int i=0;i<pf.size();i++){
    ans = min(ans,calc(value,pf[i]));
  }

  cout << ans << endl;

}

int main(){
  //cout << ULLINF << endl;
  while(cin >> N >> M,(N!=0 || M!="0")){

    compute();

  }
  return 0;
}

