#include <bits/stdc++.h>
using namespace std;
const int maxn = 100000 + 10;
struct Node {
  int pos, val;
  Node() {}
  Node(int pos, int val) : pos(pos), val(val) {}
} st[maxn];
struct Tree {
  long long add, sum;
} tree[maxn << 2];
struct Query {
  int l, r, id;
  bool operator<(const Query& tmp) const { return r < tmp.r; }
} query[maxn];
int n, q, top;
int a[maxn];
long long ans[maxn];
inline int read() {
  int x = 0;
  char ch = getchar();
  while (ch < '0' || ch > '9') ch = getchar();
  while (ch >= '0' && ch <= '9') {
    x = x * 10 + ch - '0';
    ch = getchar();
  }
  return x;
}
inline void push_down(int o, int l, int r) {
  if (tree[o].add) {
    int mid = (l + r) >> 1, lson = o << 1, rson = lson | 1;
    tree[lson].add += tree[o].add;
    tree[rson].add += tree[o].add;
    tree[lson].sum += tree[o].add * (mid - l + 1);
    tree[rson].sum += tree[o].add * (r - mid);
    tree[o].add = 0;
  }
}
inline void push_up(int o, int l, int r) {
  int lson = o << 1, rson = lson | 1;
  tree[o].sum = tree[lson].sum + tree[rson].sum;
  tree[o].sum += tree[o].add * (r - l + 1);
}
void Modify(int o, int l, int r, int ql, int qr, int v) {
  if (ql <= l && r <= qr) {
    tree[o].add += v;
    tree[o].sum += (long long)v * (r - l + 1);
    return;
  }
  push_down(o, l, r);
  int mid = (l + r) >> 1, lson = o << 1, rson = lson | 1;
  if (qr <= mid)
    Modify(lson, l, mid, ql, qr, v);
  else if (ql > mid)
    Modify(rson, mid + 1, r, ql, qr, v);
  else {
    Modify(lson, l, mid, ql, qr, v);
    Modify(rson, mid + 1, r, ql, qr, v);
  }
  push_up(o, l, r);
}
long long Query(int o, int l, int r, int ql, int qr) {
  if (ql <= l && r <= qr) return tree[o].sum;
  push_down(o, l, r);
  int mid = (l + r) >> 1, lson = o << 1, rson = lson | 1;
  if (qr <= mid)
    return Query(lson, l, mid, ql, qr);
  else if (ql > mid)
    return Query(rson, mid + 1, r, ql, qr);
  else
    return Query(lson, l, mid, ql, qr) + Query(rson, mid + 1, r, ql, qr);
}
void Build(int o, int l, int r) {
  if (l == r) {
    tree[o].add = tree[o].sum = 0;
    return;
  }
  int mid = (l + r) >> 1, lson = o << 1, rson = lson | 1;
  Build(lson, l, mid);
  Build(rson, mid + 1, r);
  tree[o].add = tree[o].sum = 0;
}
