		for (int i = 0; i + 1 < N; i++) {
			int t = 0;
			for (int j = 0; j < S[i].size(); j++) {
				t *= 10;
				t += v[S[i][j] - 'A'];
			}
			sum += t;
		}
		int t = 0;
		for (int i = 0; i < S[N - 1].size(); i++) {
			t *= 10;
			t += v[S[N - 1][i] - 'A'];
		}
		return t == sum;
	}
