using cd = complex<long double>;
const long double PI = acos(-1);
void fft(vector<cd>& a, bool invert) {
  int n = a.size();
  if (n == 1) return;
  vector<cd> a0(n / 2), a1(n / 2);
  for (int i = 0; 2 * i < n; i++) {
    a0[i] = a[2 * i];
    a1[i] = a[2 * i + 1];
  }
  fft(a0, invert);
  fft(a1, invert);
  long double ang = 2 * PI / n * (invert ? -1 : 1);
  cd w(1), wn(cos(ang), sin(ang));
  for (int i = 0; 2 * i < n; i++) {
    a[i] = a0[i] + w * a1[i];
    a[i + n / 2] = a0[i] - w * a1[i];
    if (invert) {
      a[i] /= 2;
      a[i + n / 2] /= 2;
    }
    w *= wn;
  }
}
vector<int> multiply(vector<int> const& a, vector<int> const& b) {
  vector<cd> fa(a.begin(), a.end()), fb(b.begin(), b.end());
  int pow = 1;
  while (pow < (a.size() + b.size())) {
    pow *= 2;
  }
  fa.resize(pow);
  fb.resize(pow);
  fft(fa, false);
  fft(fb, false);
  for (int i = 0; i < pow; i++) {
    fa[i] *= fb[i];
  }
  fft(fa, true);
  vector<int> result(pow);
  for (int i = 0; i < pow; i++) {
    result[i] = round(fa[i].real());
  }
  return result;
}
