int d[maxn][maxn];
bool inq[maxn][maxn];
int q[QSIZE][2];
int dir[4][2] = {{1, 0}, {0, 1}, {0, -1}, {-1, 0}};
bool relax(int x, int y, int val) {
  if (d[x][y] == 0 || d[x][y] > val) {
    d[x][y] = val;
    return true;
  }
  return false;
}
int cal(int x, int y) {
  memset(inq, false, sizeof(inq));
  memset(d, 0, sizeof(d));
  int top = 0, end = 0;
  q[end][0] = x;
  q[end][1] = y;
  d[x][y] = 1;
  end++;
  while (top != end) {
    x = q[top][0];
    y = q[top][1];
    top++;
    if (top == QSIZE) top = 0;
    inq[x][y] = false;
    for (int k = 0; k < 4; k++) {
      int tx = x + dir[k][0];
      int ty = y + dir[k][1];
      if (tx < 0 || ty < 0 || tx >= n || ty >= m) continue;
      int dis = (g[tx][ty] != g[x][y]);
      if (relax(tx, ty, d[x][y] + dis) && !inq[tx][ty]) {
        inq[tx][ty] = true;
        q[end][0] = tx;
        q[end][1] = ty;
        end++;
        if (end == QSIZE) end = 0;
      }
    }
  }
  int ret = 0;
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++)
      if (g[i][j] == 'B') ret = max(ret, d[i][j]);
  return ret;
}
