vector<int> sons[N];
#define Fs(x) for(vector<int>::iterator it=sons[x].begin();it!=sons[x].end();++it)

int po[N];
int bot[N];
int dep[N];
bool done[N];

int main(){
	int n;
	scanf("%d",&n);
	p[0]=-1;
	for(int i=1;i<n;i++){
		scanf("%d",&p[i]);
		sons[p[i]].push_back(i);
		s[p[i]]++;
	}
	for(int i=0;i<n;i++){
		scanf("%d",&a[i]);
		dep[i]=i==0?0:dep[p[i]]+1;
		// cerr<<i<<" "<<dep[i]<<endl;
	}
	while(!ok[0]){
		memset(color,0,sizeof color);
		memset(po,0,sizeof po);
		int cnt=0;
		for(int i=0;i<n;i++){
			if(s[i]==0&&!ok[i]){
				cnt++;
				bot[cnt]=i;
				for(int x=i;s[x]<=1;x=p[x]){
					// cerr<<x<<" "<<cnt<<endl;
					color[x]=cnt;
					if(x==0){
						break;
					}
				}
			}
		}
		int cr=0;
		for(int i=0;i<n;i++){
			if(color[i]&&!ok[i])cr++;
		}
		while(cr>0){
			int x=a[0];
			int c=color[x];
			if(c){
				// cerr<<"c"<<" "<<x<<endl;
				int v=bot[c];
				for(int i=0;i<=po[c];i++){
					if(dep[x]>dep[a[v]]||i==po[c]){
						op(v);
						break;
					}
					v=p[v];
				}
				po[c]++;
				cr--;
			}
			else{
				memset(done,false,sizeof done);
				for(int i=1;i<=cnt;i++){
					int v=bot[i];
					for(int j=0;j<po[i];j++){
						// cerr<<v<<endl;
						done[v]=true;
						v=p[v];
					}
				}
				int md=0;
				for(int i=0;i<n;i++){
					if(ok[i]||done[i]){
						continue;
					}
					if(color[a[i]]&&dep[i]>dep[md]){
						md=i;
					}
				}
				op(md);
			}
		}
		for(int i=0;i<n;i++){
			if(color[i]){
				assert(a[i]==i);
				ok[i]=true;
				color[i]=0;
				if(i!=0){
					s[p[i]]--;
				}
			}
		}
	}
	output();
	return 0;
}

