            for (int j = c[i]; j < dp[0].length; j++) {
                for(int cnt = 0; cnt<=(int)(a[i]/b[i]) && cnt*c[i] <= j; cnt++) {
                    dp[i][j] = Math.max(dp[i-1][j], dp[i-1][j-c[i]*cnt] + d[i]*cnt);
                }
            }
        }
        System.out.println(dp[numOfStuff-1][restOfDough]);
        sc.close();
    }

    public static void main(String args[]) {
        new C().run();
    }

}

