vector<pair<long long int, long long int>> pf;
vector<long long int> divIt;
bool stop = false;
void increment(long long int index) {
  if (divIt[index] < pf[index].second) {
    divIt[index]++;
  } else {
    if (index == divIt.size() - 1) {
      stop = true;
    } else {
      divIt[index] = 0;
      increment(index + 1);
    }
  }
}
long long int power(long long int x, long long int y, long long int m) {
  long long int res = 1;
  x = x % m;
  while (y > 0) {
    if (y & 1) res = (res * x) % m;
    y = y >> 1;
    x = (x * x) % m;
  }
  return (res + m) % m;
}
