public class ProblemE {
	static int N;
	static long Y;
	static long ycnt;
	static int[] place;
	static boolean[][] invalid;
	static boolean[][] invalidGraph;
	static boolean[][] rules;

	private static long cnt(int now) {
		long[][] dp = new long[N+1][1<<N];
		int fptn = 0;
		for (int i = 0 ; i < N ; i++) {
			if (place[i] != -1) {
				fptn |= 1<<i;
			}
		}

		dp[now][fptn] = 1;
		for (int i = now ; i < N ; i++) {
			for (int ptn = 0 ; ptn < (1<<N) ; ptn++) {
				if (dp[i][ptn] <= 0) {
					continue;
				}
				for (int next = 0 ; next < N ; next++) {
					if ((ptn & (1<<next)) >= 1) {
						continue;
					}
					if (invalid[ptn][next]) {
						continue;
					}
					int nptn = ptn | (1<<next);
					dp[i+1][nptn] += dp[i][ptn];
				}
			}
		}
		return dp[N][(1<<N)-1];
	}


	private static void dfs(int now) {
		for (int i = 0 ; i < N ; i++) {
			if (place[i] == -1) {
				place[i] = now;
				if (now >= 1) {
					boolean isok = true;
					for (int j = 0 ; j < N ; j++) {
						if (place[j] == now - 1) {
							if (invalidGraph[j][i]) {
								isok = false;
								break;
							}
						}
					}
					if (!isok) {
						place[i] = -1;
						continue;
					}
				}

				long dcnt = cnt(now+1);
				if (ycnt + dcnt >= Y) {
					dfs(now+1);
					break;
				}
				ycnt += dcnt;
				place[i] = -1;
			}
		}
	}

	public static void main(String[] args) throws IOException {
		BufferedReader s = new BufferedReader(new InputStreamReader(System.in));
		String[] line = s.readLine().split(" ");
		int n = Integer.valueOf(line[0]);
		long y = Long.valueOf(line[1]) - 2000;
		int m = Integer.valueOf(line[2]);

		invalid = new boolean[1<<n][n];
		invalidGraph = new boolean[n][n];
		for (int i = 0 ; i < m ; i++) {
			String[] data = s.readLine().split(" ");
			int senior = Integer.valueOf(data[0])-1;
			int junior = Integer.valueOf(data[1])-1;
			invalidGraph[junior][senior] = true;
			for (int j = 0 ; j < (1<<n) ; j++) {
				if ((j & (1<<junior)) >= 1) {
					invalid[j][senior] = true;
				}
			}
		}

		N = n;
		Y = y;
		ycnt = 0;
		place = new int[N];
		Arrays.fill(place, -1);

		dfs(0);

		if (place[0] == -1) {
			System.out.println("The times have changed");
			return;
		} else {
			int[] map = new int[N];
			for (int i = 0 ; i < n ; i++) {
				map[place[i]] = i;
			}

			StringBuffer b = new StringBuffer();
			for (int i = 0 ; i < n ; i++) {
				b.append(map[i]+1).append(" ");
			}
			System.out.println(b.substring(0, b.length()-1));
		}
	}
}

