void click(vector<vector<int> > &G, pair<int, int> pos) {
  G[pos.second][pos.first]++;
  if (G[pos.second][pos.first] < 5) return;
  deque<pair<pair<int, int>, int> > deq;
  int sec = 0;
  deq.push_back(pair<pair<int, int>, int>(pos, 0));
  while (!deq.empty()) {
    pair<pair<int, int>, int> p = deq.front();
    deq.pop_front();
    for (int i = (int)(0); i < (int)(4); i++) {
      int nx = p.first.first + dx[i];
      int ny = p.first.second + dy[i];
      while (0 <= nx && nx < 4 && 0 <= ny && ny < 4 &&
             (G[ny][nx] == -1 || G[ny][nx] == 0))
        nx += dx[i], ny += dy[i];
      if (!(0 <= nx && nx < 4 && 0 <= ny && ny < 4)) continue;
      assert(G[ny][nx] != -1 && G[ny][nx]);
      G[ny][nx]++;
      if (G[ny][nx] == 5) {
        pair<int, int> np = pair<int, int>(nx, ny);
        deq.push_back(pair<pair<int, int>, int>(np, p.second + 1));
      }
    }
    if (!deq.empty() && deq.front().second != sec) {
      bomb(G);
      sec++;
    }
  }
  bomb(G);
}
