int dp[N][32];
unsigned long long h1[N], h2[N], base[N];
inline unsigned long long get_hash(unsigned long long h[], int l, int r) {
  return (h[r] - (h[l - 1] * base[r - l + 1]) % mod + mod) % mod;
}
inline int LCP(int i, int j) {
  int l = 0, r = min(n - i + 1, m - j + 1) + 1;
  while (r - l > 1) {
    int mid = (l + r) >> 1;
    if (get_hash(h1, i, i + mid - 1) == get_hash(h2, j, j + mid - 1)) {
      l = mid;
    } else {
      r = mid;
    }
  }
  return l;
}
