template <typename T>
int sz(T &x) {
  return (int)(x.size());
}

int ban[51];
int dp[51][51];

int can(int x, int y) {
  if (x < y) {
    return 0;
  }
  if (x == y) {
    return 1;
  }
  if (~dp[x][y]) {
    return dp[x][y];
  }
  int &ans = dp[x][y];
  ans = 0;
  for (int i = x; i >=  1; --i) {
    if (!ban[i]) {
      ans |= can(x % i, y);
    }
  }
  return ans;
}

int ok(vector<int> &a, vector<int> &b) {
  for (int i = 0; i <= 50; ++i) {
    for (int j = 0; j <= 50; ++j) {
      dp[i][j] = -1;
    }
  }
  for (int i = 0; i < sz(a); ++i) {
    if (!can(a[i], b[i])) {
      return 0;
    }
  }
  return 1;
}

