#include <bits/stdc++.h>
using namespace std;
const int Max_N = 2020;
const int MOD = 998244353;
int n, fath[Max_N], dis[Max_N];
char str[Max_N];
int quick_pow(int a, int n) {
  int res = 1;
  a %= MOD;
  while (n) {
    if (n & 1) res = 1ll * res * a % MOD;
    a = 1ll * a * a % MOD;
    n >>= 1;
  }
  return res;
}
int get_fath(int x) {
  if (fath[x] == x) return x;
  int root = get_fath(fath[x]);
  dis[x] ^= dis[fath[x]];
  return fath[x] = root;
}
bool merge(int a, int b, int c) {
  int x = get_fath(a), y = get_fath(b);
  if (x == y) return dis[a] ^ dis[b] ^ c ^ 1;
  fath[x] = y;
  dis[x] = dis[a] ^ dis[b] ^ c;
  return 1;
}
int solve(int x) {
  for (int i = 1; i <= (n << 1); i++) {
    fath[i] = i;
    dis[i] = 0;
  }
  for (int i = 1; i <= n / 2; i++) merge(i, n - i + 1, 0);
  for (int i = 1; i <= x / 2; i++) merge(n + i, n + x - i + 1, 0);
  for (int i = x + 1; i < n; i++) merge(n + i, n << 1, 0);
  merge(1, n + 1, 0);
  for (int i = 1; i <= n; i++) {
    if (str[n - i + 1] == '?') continue;
    if (!merge(n + i, i, str[n - i + 1] - 48)) return 0;
  }
  int cnt = 0;
  for (int i = 1; i <= (n << 1); i++) cnt += fath[i] == i;
  return quick_pow(2, cnt - 1);
}
int main() {
  scanf("%s", str + 1);
  n = strlen(str + 1);
  int ans = 0;
  for (int i = 1; i < n; i++) ans = (ans + solve(i)) % MOD;
  printf("%d", (ans << 1) % MOD);
  return 0;
}

