void bfs() {
  queue<pair<int, int> > q;
  for (int i = (0); ((1) > 0 ? i < (n) : i > (n)); i += (1)) {
    for (int j = (0); ((1) > 0 ? j < (m) : j > (m)); j += (1)) {
