#include <bits/stdc++.h>
using namespace std;
const int MAXN = 256;
const int INF = 1e9;
struct Move {
  int id, r, c;
};
int n, k, A[4][MAXN], r[MAXN], c[MAXN], gr[MAXN], gc[MAXN];
pair<int, int> padre[4][MAXN];
int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, 1, 0, -1};
bool stored[MAXN];
bool used[4][MAXN];
vector<Move> ans;
bool won() {
  for (int i = (0); i < (int)(k); i++) {
    if (!stored[i]) return false;
  }
  return true;
}
struct dot {
  int r, c;
};
void MOVE(int ff, int cc, int tf, int tc) {
  assert(A[tf][tc] == -1);
  assert(A[ff][cc] != -1);
  ans.push_back((Move){A[ff][cc], tf, tc});
  r[A[ff][cc]] = tf;
  c[A[ff][cc]] = tc;
  swap(A[ff][cc], A[tf][tc]);
}
bool sacameeeee(int f, int c, int nf, int nc) {
  queue<pair<int, int>> Q;
  Q.push({f, c});
  memset(used, false, sizeof(used));
  used[f][c] = true;
  while (!Q.empty()) {
    pair<int, int> v = Q.front();
    Q.pop();
    for (int i = (0); i < (int)(4); i++) {
      int rr = v.first + dr[i];
      int cc = v.second + dc[i];
      if (rr == nf && cc == nc) continue;
      if ((0 <= (rr) && (rr) < 4) && (0 <= (cc) && (cc) < n)) {
        if ((rr == 1 || rr == 2)) {
          if (used[rr][cc]) continue;
          if (A[rr][cc] == -1) {
            pair<int, int> s = {rr, cc};
            padre[rr][cc] = v;
            while (s != make_pair(f, c)) {
              pair<int, int> t = padre[s.first][s.second];
              MOVE(t.first, t.second, s.first, s.second);
              s = t;
            }
            return true;
          } else {
            used[rr][cc] = true;
            padre[rr][cc] = v;
            Q.push({rr, cc});
          }
        }
      }
    }
  }
  return false;
}
int main() {
  while (scanf("%d%d", &n, &k) >= 1) {
    memset(stored, false, sizeof(stored));
    ans.clear();
    for (int i = (0); i < (int)(4); i++) {
      for (int j = (0); j < (int)(n); j++) {
        scanf("%d", &A[i][j]);
        A[i][j]--;
        if (i == 1 || i == 2) {
          if (A[i][j] >= 0) {
            r[A[i][j]] = i;
            c[A[i][j]] = j;
          }
        } else {
          if (A[i][j] >= 0) {
            gr[A[i][j]] = i;
            gc[A[i][j]] = j;
          }
        }
      }
    }
    while (!won()) {
      bool possible = true;
      int d = INF, who = -1;
      for (int i = (0); i < (int)(k); i++) {
        if (!stored[i]) {
          int dd = abs(gr[i] - r[i]) + abs(gc[i] - c[i]);
          if (dd < d) {
            d = dd;
            who = i;
          }
        }
      }
      while (c[who] != gc[who]) {
        int dir = c[who] < gc[who] ? 1 : -1;
        int ff = r[who];
        int cc = c[who] + dir;
        if (A[ff][cc] == -1) {
          MOVE(r[who], c[who], ff, cc);
        } else {
          bool b = sacameeeee(ff, cc, r[who], c[who]);
          if (!b) {
            possible = false;
            break;
          }
        }
      }
      if (!possible) break;
      while (r[who] != gr[who]) {
        int dir = r[who] < gr[who] ? 1 : -1;
        int ff = r[who] + dir;
        int cc = c[who];
        if (ff == 0 || ff == 3) {
          stored[who] = true;
          ans.push_back((Move){who, ff, cc});
          break;
        }
        if (A[ff][cc] == -1) {
          MOVE(r[who], c[who], ff, cc);
        } else {
          bool b = sacameeeee(ff, cc, r[who], c[who]);
          if (!b) {
            possible = false;
            break;
          }
        }
      }
      if (!possible) break;
    }
    if (!won()) {
      puts("-1");
      continue;
    }
    assert(((int)ans.size()) <= 20000);
    printf("%d\n", ((int)ans.size()));
    for (int i = (0); i < (int)(((int)ans.size())); i++) {
      printf("%d %d %d\n", ans[i].id + 1, ans[i].r + 1, ans[i].c + 1);
    }
  }
  return 0;
}

