using namespace std;

typedef complex<double> P;

int main(){
  for(int N,M;cin>>N>>M,N;){
    double V[10];
    P p[10];
    for(int i=0;i<N;i++){
      double Dx,Dy;
      cin>>Dx>>Dy>>V[i];
      p[i]=P(Dx,Dy);
    }
    int nf[10]={};
    while(M--){
      double FPx,FPy,FVx,FVy;
      cin>>FPx>>FPy>>FVx>>FVy;
      int dx;
      double m=1e9;
      bool move[10]={};
      P v[10];
      for(int i=0;i<N;i++){
	double x=FPx-p[i].real();
	double y=FPy-p[i].imag();
	double a=FVx*FVx+FVy*FVy-V[i]*V[i];
	double b=x*FVx+y*FVy;
	double c=x*x+y*y;
	double D=b*b-a*c;
	if(D>=0){
	  double t=(-b+sqrt(D))/a;
	  double t2=(-b-sqrt(D))/a;
	  if(t<0||t2>=0&&t2<t){
	    t=t2;
	  }
	  if(t>=0){
	    move[i]=true;
	    v[i]=P(x+FVx*t,y+FVy*t);
	    if(t<m){
	      m=t;
	      dx=i;
	    }
	  }
	}
      }
      nf[dx]++;
      for(int i=0;i<N;i++){
	if(move[i]){
	  p[i]+=v[i]/abs(v[i])*V[i]*m;
	}
      }
    }
    for(int i=0;i<N;i++){
      cout<<nf[i]<<" \n"[i==N-1];
    }
  }
}

