class Dice {
    //??????????????????????\\??????????????????
    private int[] numbers = new int[6];// = {1,2,3,5,4,6};
    private int sum = 1;

    public Dice(int[] numbers){
        for(int i = 0; i < 6; i++){
            this.numbers[i] = numbers[i];
        }
        this.numbers[3] = numbers[4];
        this.numbers[4] = numbers[3];
    }

    public void executeCommands(String commands){
    	for(int i = 0; i < commands.length() ; i++){
    		char c = commands.charAt(i);

    		if(c == 'N'){
    			north();
    		}
    		if(c == 'W'){
    			west();
    		}
    		if(c == 'S'){
    			south();
    		}
    		if(c == 'E'){
    			east();
    		}
    		if(c == 'L'){
    			left();
    		}
    		if(c == 'R'){
    			right();
    		}
    	}
    }

    public void move (String command){
        if(command.equals("North")) {
            north();
        }

        else if(command.equals("South")) {
            south();
        }
        else if(command.equals("East")) {
            east();
        }
        else if(command.equals("West")) {
            west();
        }
        else if(command.equals("Right")) {
            right();
        }
        else if(command.equals("Left")) {
            left();
        }

        sum += numbers[0];
    }

    public int getSum(){
        return sum;
    }

    private void north () {
        int[] tmp = numbers.clone();
        numbers[0] = tmp[1];
        numbers[1] = tmp[5];
        numbers[3] = tmp[0];
        numbers[5] = tmp[3];
    }

    private void east () {
        int[] tmp = numbers.clone();
        numbers[0] = tmp[4];
        numbers[2] = tmp[0];
        numbers[4] = tmp[5];
        numbers[5] = tmp[2];
    }

    private void west () {
        east(); east(); east();
    }

    private void south () {
        north(); north(); north();
    }

    private void right () {
        int[] tmp = numbers.clone();
        numbers[1] = tmp[2];
        numbers[2] = tmp[3];
        numbers[3] = tmp[4];
        numbers[4] = tmp[1];
    }

    private void left () {
        right(); right(); right();
    }

    public int top(){
        return numbers[0];
    }

