int n, k;
double A;
int b[maxN];
int l[maxN];
double ans;
void check() {
  double cur = 0;
  for (int mask = 0; mask < (1 << n); mask++) {
    int cnt = 0;
    double p = 1.0;
    double B = 0.0;
    for (int i = 0; i < n; i++) {
      if ((mask >> i) & 1) {
        p *= (l[i] / 100.0);
        cnt++;
      } else {
        B += b[i];
        p *= (1.0 - (l[i] / 100.0));
      }
    }
    if (cnt * 2 > n) {
      cur += p;
    } else {
      cur += p * A / (A + B);
    }
  }
  ans = max(cur, ans);
}
void dfs(int p, int k) {
  if (p == n) {
    check();
    return;
  }
  dfs(p + 1, k);
  if (k) {
    int v = l[p];
    l[p] = min(l[p] + 10, 100);
    dfs(p, k - 1);
    l[p] = v;
  }
}
