def getMinMoviments(char, string, left, right):
    if(left == right):
        if(string[left] == char):
            return 0
        else:
            return 1

    q = (left + right) // 2

    newChar = chr(ord(char) + 1)

    coustLeft = getCoustToChar(char, string, left, q)
    movRight = getMinMoviments(newChar, string, q + 1, right)
    coustRight = getCoustToChar(char,string, q + 1, right)
    movLeft = getMinMoviments(newChar, string, left, q)

    return min((coustLeft + movRight),(coustRight + movLeft))

