    static int findMaxElementIndex(int ar[])
    {
        int index=0;
        int max=0;
        int n=ar.length;
        for(int i=0;i<n;i++)
        {
            if(ar[i]>max)
            {
                max=ar[i];
                index=i;
            }
        }
        return index;
    }

    static int findMaxElement(int ar[])
    {
        int max=0;
        int n=ar.length;
        for(int i=0;i<n;i++)
        {
