        {
            out.write(ar[i]+" ");
        }
        out.write("\n");
        out.flush();
    }

    static int binarySearch(int arr[],int value,int start,int end)
    {
        int mid=(start+end)/2;
        int result;
        if(start<=end)
        {
            if(arr[mid]==value)
            {
                return mid;
            }
            else if(arr[mid]<value)
            {
                result=binarySearch(arr, value, mid+1, end);
            }
            else{
                result=binarySearch(arr, value, start, mid-1);
            }
        }
        else{
            return -1;
        }
        return result;
    }

