long long ans = 0;
long long gcd(long long a, long long b) { return b ? gcd(b, a % b) : a; }
long long lcm(long long a, long long b) { return a / gcd(a, b) * b; }
long long weight(int i) {
  if (nodes[i].w != -1) return nodes[i].w;
  long long sum = 1;
  for (int j = 0; j < nodes[i].v.size(); j++)
    sum = lcm(sum, weight(nodes[i].v[j]));
  nodes[i].w = sum * nodes[i].v.size();
  return nodes[i].w;
}
long long val(int i) {
  if (nodes[i].val != -1) return nodes[i].val;
  long long sum = 0;
  for (int j = 0; j < nodes[i].v.size(); j++) sum += val(nodes[i].v[j]);
  nodes[i].val = sum;
  return nodes[i].val;
}
void dfs(int i) {
  if (nodes[i].v.empty()) return;
  long long piece = nodes[i].div / nodes[i].v.size();
  long long minchild = val(nodes[i].v[0]);
  for (int j = 1; j < nodes[i].v.size(); j++)
    minchild = min(minchild, val(nodes[i].v[j]));
  long long onechild = min(minchild / piece, val(i) / nodes[i].div) * piece;
  for (int j = 0; j < nodes[i].v.size(); j++) {
    nodes[nodes[i].v[j]].div = piece;
    nodes[nodes[i].v[j]].val = onechild;
    dfs(nodes[i].v[j]);
  }
}
long long final(int i) {
  if (nodes[i].v.empty()) return nodes[i].val;
  long long minfinal = final(nodes[i].v[0]);
  for (int j = 1; j < nodes[i].v.size(); j++)
    minfinal = min(minfinal, final(nodes[i].v[j]));
  return minfinal * nodes[i].v.size();
}
void initdfs(int i, int fa) {
  for (int j = 0; j < nodes[i].vv.size(); j++)
    if (nodes[i].vv[j] != fa) nodes[i].v.push_back(nodes[i].vv[j]);
  for (int j = 0; j < nodes[i].v.size(); j++) initdfs(nodes[i].v[j], i);
}
