int pow(int x, int p) {
  int sol = 1;
  for (int i = 0; (1 << i) <= p && i < 31; ++i) {
    if ((1 << i) & p) sol = 1LL * sol * x % mod;
    x = 1LL * x * x % mod;
  }
  return sol;
}
int comb(int n, int k) {
  int rez = 1;
  static int val = 0;
  if (val == 0) {
    val = 1;
    for (int i = 1; i <= k; ++i) val = 1LL * val * pow(i, mod - 2) % mod;
  }
  for (int i = 1; i <= k; ++i) {
    rez = 1LL * rez * (n - i + 1) % mod;
  }
  return 1LL * rez * val;
}
