      Ans.push_back({min(x, y), max(x, y)});
    }
  }
  sort(Ans.begin(), Ans.end());
  cout << ans << "\n";
  for (auto x : Ans) {
    if (x.second == 0) swap(x.first, x.second);
    cout << x.first << " " << x.second << "\n";
  }
}

