  fill(vv, vv + n, -1);
  for (int i = 0; i < m; i++) {
    int f, t;
    scanf("%d%d", &f, &t);
    f--, t--;
    ee[2 * i] = E{f, t, -1, gg[f]};
    gg[f] = 2 * i;
    ee[i * 2 + 1] = E{t, f, -1, gg[t]};
    gg[t] = 2 * i + 1;
  }
  int seq = 0;
  for (int i = 0; i < n; i++) {
    if (vv[i] == -1) {
      int qq[n];
      int h = 0, t = 0;
      qq[t++] = i;
      vv[i] = seq++;
      while (h < t) {
        int nn = qq[h++];
        for (int e = gg[nn]; e != -1; e = ee[e].nxt) {
          if (ee[e].dir == -1) {
            ee[e].dir = 0;
            ee[e ^ 1].dir = 1;
            vv[ee[e].t] = seq++;
            qq[t++] = ee[e].t;
          }
        }
      }
    }
  }
