#include <bits/stdc++.h>
using namespace std;
const int N = 4e5 + 100;
int n, tot;
int head[N], ver[2 * N], Next[2 * N];
int siz[N], ans[N], maxson[N], son[N][2];
void add(int x, int y) {
  ver[++tot] = y, Next[tot] = head[x], head[x] = tot;
  ver[++tot] = x, Next[tot] = head[y], head[y] = tot;
}
void pre(int x, int f) {
  siz[x] = 1;
  for (int i = head[x]; i; i = Next[i]) {
    int y = ver[i];
    if (y == f) continue;
    pre(y, x);
    siz[x] += siz[y];
    if (siz[y] > siz[maxson[x]]) maxson[x] = y;
    if (siz[y] > siz[son[x][0]] && siz[y] <= n / 2)
      son[x][1] = son[x][0], son[x][0] = y;
    else if (siz[y] > siz[son[x][1]] && siz[y] <= n / 2)
      son[x][1] = y;
  }
}
void solve(int x, int f) {
  if (siz[maxson[x]] > n / 2)
    ans[x] = (siz[maxson[x]] - siz[son[maxson[x]][0]] <= n / 2);
  else if (n - siz[x] > n / 2)
    if (son[f][0] == x)
      ans[x] = (n - siz[x] - siz[son[f][1]] <= n / 2 ||
                (n - siz[f] <= n / 2 && siz[f] - siz[x] <= n / 2));
    else
      ans[x] = (n - siz[x] - siz[son[f][0]] <= n / 2 ||
                (n - siz[f] <= n / 2 && siz[f] - siz[x] <= n / 2));
  else
    ans[x] = 1;
  for (int i = head[x]; i; i = Next[i]) {
    int y = ver[i];
    if (y == f) continue;
    solve(y, x);
  }
}
