struct point {
  double x, y;
  point(double _x = 0, double _y = 0) : x(_x), y(_y) {}
  point operator+(const point &p) { return point(x + p.x, y + p.y); }
  point operator-(const point &p) { return point(x - p.x, y - p.y); }
  point operator*(const point &p) {
    double rx = x * p.x - y * p.y;
    double ry = x * p.y + y * p.x;
    return point(rx, ry);
  }
  point operator/(const point &p) {
    double rx = (x * p.x + y * p.y) / (p.x * p.x + p.y * p.y);
    double ry = (-1 * p.y + y * p.x) / (p.x * p.x + p.y * p.y);
    return point(rx, ry);
  }
  point operator*(double t) { return point(x * t, y * t); }
  point operator/(double t) { return point(x / t, y / t); }
  double abs() { return sqrt(x * x + y * y); }
  double abs2() { return x * x + y * y; }
  double arg() { return atan2(y, x); }
};
double dist(point a, point b) {
  return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}
double dot(point a, point b) { return a.x * b.x + a.y * b.y; }
double multi(point a, point b) { return a.x * b.y - a.y * b.x; }
double multi(point a, point b, point o) { return fabs(multi(a - o, b - o)); }
point intersect(point a, point b, point c, point d) {
  double al = multi(c, a, b) / (multi(c, a, b) + multi(a, d, b));
  return c + (d - c) * al;
}
