int astar(node cur) {
  priority_queue<node> pq;
  pq.push(cur);
  node LAST;
  while (!pq.empty()) {
    node u = LAST = pq.top();
    visit.push_back(copy_puzzle2(u.puzzle));
    while (!pq.empty()) pq.pop();
    if (check_if_goal(u.puzzle)) break;
    if (u.zeroI - 1 >= 0) {
      node v = copy_puzzle(u.puzzle);
      swap(v.puzzle[u.zeroI - 1][u.zeroJ], v.puzzle[u.zeroI][u.zeroJ]);
      if (!already_visited(v.puzzle)) {
        v.h = calc_heuristic(v.puzzle);
        v.g = u.g + 1;
        v.f = v.g + v.h;
        v.steps = u.steps + 1;
        v.zeroI = u.zeroI - 1;
        v.zeroJ = u.zeroJ;
        pq.push(v);
      }
    }
    if (u.zeroI + 1 < 3) {
      node v = copy_puzzle(u.puzzle);
      swap(v.puzzle[u.zeroI + 1][u.zeroJ], v.puzzle[u.zeroI][u.zeroJ]);
      if (!already_visited(v.puzzle)) {
        v.h = calc_heuristic(v.puzzle);
        v.g = u.g + 1;
        v.f = v.g + v.h;
        v.steps = u.steps + 1;
        v.zeroI = u.zeroI + 1;
        v.zeroJ = u.zeroJ;
        pq.push(v);
      }
    }
    if (u.zeroJ - 1 >= 0) {
      node v = copy_puzzle(u.puzzle);
      swap(v.puzzle[u.zeroI][u.zeroJ - 1], v.puzzle[u.zeroI][u.zeroJ]);
      if (!already_visited(v.puzzle)) {
        v.h = calc_heuristic(v.puzzle);
        v.g = u.g + 1;
        v.f = v.g + v.h;
        v.steps = u.steps + 1;
        v.zeroI = u.zeroI;
        v.zeroJ = u.zeroJ - 1;
        pq.push(v);
      }
    }
    if (u.zeroJ + 1 < 3) {
      node v = copy_puzzle(u.puzzle);
      swap(v.puzzle[u.zeroI][u.zeroJ + 1], v.puzzle[u.zeroI][u.zeroJ]);
      if (!already_visited(v.puzzle)) {
        v.h = calc_heuristic(v.puzzle);
        v.g = u.g + 1;
        v.f = v.g + v.h;
        v.steps = u.steps + 1;
        v.zeroI = u.zeroI;
        v.zeroJ = u.zeroJ + 1;
        pq.push(v);
      }
    }
  }
  return LAST.steps;
}
