void dfs(int x = 1, int pp = 0) {
  s[x] = ++timer;
  par[x] = pp;
  for (auto &it : g[x])
    if (it != par[x]) {
      dfs(it, x);
    }
  f[x] = ++timer;
}
struct node {
  int sum;
  bool set;
  void merge(node &lt, node &rt) { sum = lt.sum + rt.sum; }
} st[N << 2];
void push(int x, int lx, int rx) {
  if (st[x].set) {
    st[x].set = 0;
    st[x].sum = rx - lx + 1;
    if (lx == rx) return;
    st[x << 1].set = st[x << 1 | 1].set = 1;
  }
}
void bld(int x = 1, int lx = 1, int rx = n + n) {
  if (lx == rx) {
    st[x] = {0, 0};
    return;
  }
  int mid = lx + rx >> 1;
  bld(x << 1, lx, mid);
  bld(x << 1 | 1, mid + 1, rx);
  st[x].merge(st[x << 1], st[x << 1 | 1]);
}
void modify(bool z, int &u, int &v, int x = 1, int lx = 1, int rx = n + n) {
  push(x, lx, rx);
  if (v < lx or u > rx) return;
  if (u <= lx and rx <= v) {
    if (z) {
      st[x].set = 1;
      push(x, lx, rx);
    } else {
      st[x].sum = 0;
    }
    return;
  }
  int mid = lx + rx >> 1;
  modify(z, u, v, x << 1, lx, mid);
  modify(z, u, v, x << 1 | 1, mid + 1, rx);
  st[x].merge(st[x << 1], st[x << 1 | 1]);
}
int qry(int &u, int &v, int x = 1, int lx = 1, int rx = n + n) {
  push(x, lx, rx);
  if (v < lx or u > rx) return 0;
  if (u <= lx and rx <= v) return st[x].sum;
  int mid = lx + rx >> 1;
  return qry(u, v, x << 1, lx, mid) + qry(u, v, x << 1 | 1, mid + 1, rx);
}
