		int now;

		Road2(int fr, int to, int l, int r, int id) {
			this.fr = fr;
			this.to = to;
			this.l = l;
			this.r = r;
			this.id = id;
			this.now = l;
		}
	}

	ArrayList<Road>[] g;
	ArrayList<Road2>[] g2;

	class Event {
		int who;
		int where;
		long time;

		Event(int who, int where, long time) {
			this.who = who;
			this.where = where;
			this.time = time;
		}
	}

