pair<int, int> P[MAXN];
void solve() {
  int n, m;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < (n); ++i) maxi[i] = inft;
  for (int _ = 0; _ < (m); ++_) {
    scanf("%d%d%d%d", &C[_], &P[_].first, &P[_].second, &V[_]);
    P[_].first--;
