      for (int i = P[_].first; i <= P[_].second; i++) sum[i] += V[_];
    } else {
      for (int i = P[_].first; i <= P[_].second; i++)
        maxi[i] = min(maxi[i], -sum[i] + V[_]);
    }
  }
  for (int i = 0; i < (n); ++i) sum[i] = maxi[i];
