        for(int i = 0; i < n; i++) {
            if(done[i]) continue;
            ArrayDeque<Integer> cycle = new ArrayDeque<>();
            int u = i;
            while(!done[u]) {
                cycle.addFirst(u);
                done[u] = true;
                u = p[u];
            }
            SplayTree<Integer> st = new SplayTree<>(null);
            for(int x : cycle) st.join(new SplayTree<>(nodes[x]));
        }
        for(int qq = 0; qq < q; qq++) {
            int t = sc.nextInt();
            if(t == 1) {
                int x = sc.nextInt()-1;
                int y = sc.nextInt()-1;
                SplayTree<Integer> st_x = new SplayTree<Integer>(nodes[x]);
                if(nodes[x] == st_x.find_root(nodes[y])){
                    SplayTree<Integer> x1 = st_x;
                    SplayTree<Integer> x3 = new SplayTree<Integer>(x1.split_at(nodes[x]));
                    Node<Integer> root_y = x3.find_root(nodes[y]);
                    if(root_y == x3.root) {                        
                        x3 = new SplayTree<Integer>(x3.split_at(nodes[y]));
                    } else {
                        x1.split_at(nodes[y]);
                    }
                    x3.join(x1);
                } else {
                    SplayTree<Integer> x2 = new SplayTree<>(st_x.split_at(nodes[x]));
                    SplayTree<Integer> x1 = st_x;                    

                    SplayTree<Integer> st_y = new SplayTree<Integer>(nodes[y]);
