                int k = sc.nextInt();
                SplayTree<Integer> st = new SplayTree<Integer>(nodes[i]);
                int size = st.size();
                int pos = st.pos(nodes[i]);
                k += pos;
                Node<Integer> ans = st.find((k % size) + 1);
                println(ans.val+1);
            }

        }
    }

    class SplayTree<T> {

        Node<T> root;

        public SplayTree(Node<T> node) {
            if(node == null) return;
            splay(node);
        }

        Node<T> find_root(Node<T> node){
            while(node.p != null) node = node.p;
            return node;
        }

        int size(Node<T> node) {
            return node == null?0:node.sz;
        }
        int size() {
            return size(root);
        }

        void rotate(Node<T> node) {
            Node<T> p = node.p;
            int side = node.p.ch[0] == node?0:1;
            if (p.p != null) p.p.attach(p.side(), node);
            else node.p = null;
            p.attach(side, node.ch[1-side]);
            node.attach(1-side, p);
            p.update();
            node.update();
        }

        void splay(Node<T> node) {
            node.update();
            while(node.p != null) {
                if (node.p.p != null) {
                    rotate((node.side() == node.p.side() ? node.p: node));
                }
                rotate(node);
            }
            root = node;
        }

        Node<T> find(int v) {
            if (root == null) return root;
            Node<T> x = root;
            while (true) {
                //x->prop();
                Node<T> next = x.ch[0];
                int cnt = size(next)+1;
                if (cnt == v) break;
                else if(cnt < v){
                    v -= cnt;
                    next = x.ch[1];
                }
                x = next;
            }
            splay(x);
            return root;
        }

        int pos(Node<T> node) {
            splay(node);
            return size(root.ch[0]);
        }


        Node<T> split_at(Node<T> node) {
            splay(node);
            Node<T> r = root.ch[1];
            root.ch[1] = null;
            if (r != null) r.p = null;
            root.update();
            return r;
        }

        void join(SplayTree<T> l) { 
            if (size() == 0) {
                Node<T> temp = root;
                root = l.root;
                l.root = temp;
            }
            if (size() == 0 || l.size() == 0) return;
            Node<T> x = l.root;
            while (true) {
               // x->prop();
                if (x.ch[1] == null) break;
                x = x.ch[1];
            }
            l.splay(x);
            //root.prop();
            root.update();
            x.ch[1] = root;
            x.ch[1].p = x;
            root = l.root;
            l.root = null;
            root.update();
        }
    }

    class Node<T> {
        int sz;
        T val;
        Node<T>[] ch;
        Node<T> p;
        public Node(T key) {
            ch = new Node[2];
            this.val = key;
            this.sz = 1;
        }

        void update() {
            this.sz = 1;
            for (int i = 0; i < 2; i++) 
                if (ch[i] != null) {
                    this.sz += ch[i].sz;
                }
        }

        int side() {
            return p.ch[0] == this?0:1;
        }

        void attach(int side, Node<T> new_) {
            if (new_ != null) new_.p = this;
            ch[side] = new_;
        }
    }


