#include <bits/stdc++.h>
using namespace std;
const int N = int(5e5) + 10;
vector<int> A[N], g[N];
int sub[N];
long long int ans[N];
int chainParent[N], chainHead[N], blen, chainNo[N], pos[N], nchain;
long long int BIT[2][N];
inline void update(int t, int x, int v) {
  for (; x < N; x += x ^ (x & (x - 1))) BIT[t][x] += v;
}
inline void update(int l, int r) {
  update(0, l, 1);
  update(0, r + 1, -1);
  update(1, l, l - 1);
  update(1, r + 1, -r);
}
inline long long int query(int t, int x) {
  long long int ret = 0;
  for (; x; x = (x & (x - 1))) ret += BIT[t][x];
  return ret;
}
inline long long int query(int x) { return query(0, x) * x - query(1, x); }
inline long long int range_query(int l, int r) {
  return query(r) - query(l - 1);
}
inline void dfs(int x, int l = 1) {
  A[l].push_back(x);
  sub[x] = 1;
  for (auto y : g[x]) {
    dfs(y, l + 1);
    sub[x] += sub[y];
  }
}
inline void HLD(int x) {
  pos[x] = ++blen;
  chainNo[x] = nchain;
  int sc = -1;
  for (auto y : g[x])
    if (sc == -1 || sub[y] > sub[sc]) sc = y;
  if (sc == -1) return;
  HLD(sc);
  for (auto y : g[x])
    if (y != sc) {
      nchain++;
      chainParent[nchain] = x;
      chainHead[nchain] = y;
      HLD(y);
    }
}
int root = -1;
inline long long int query_up(int x) {
  long long int ret = 0;
  while (chainNo[x] != chainNo[root]) {
    int cno = chainNo[x];
    ret += range_query(pos[chainHead[cno]], pos[x]);
    x = chainParent[cno];
  }
  ret += range_query(pos[root], pos[x]);
  return ret;
}
inline void update_up(int x) {
  while (chainNo[x] != chainNo[root]) {
    int cno = chainNo[x];
    update(pos[chainHead[cno]], pos[x]);
    x = chainParent[cno];
  }
  update(pos[root], pos[x]);
}
int main() {
  int n;
  scanf("%d", &n);
  root = -1;
  for (int i = 1; i <= n; i++) {
    int p;
    scanf("%d", &p);
    if (p == 0)
      root = i;
    else
      g[p].push_back(i);
  }
  dfs(root);
  HLD(root);
  for (int i = 1; i <= n; i++) {
    int add = (int)(A[i].size()) - 1;
    for (auto x : A[i]) {
      ans[x] = add + query_up(x);
    }
    for (auto x : A[i]) {
      update_up(x);
    }
  }
  for (int i = 1; i <= n; i++) printf("%lld ", ans[i]);
  puts("");
  return 0;
}

