      for (int j = 2; j <= k; ++j) dp[i][j] = 0;
    }
    if (i > 0) {
      for (int j = 1; j <= k; ++j) {
        dp[i][j] += dp[i - 1][j];
      }
    }
    for (int j = 1; j <= k; ++j) dp[i][j] %= mod;
  }
  return dp[n - 1][k] % mod;
}
void solve() {
