  long long res = 0;
  const int MAX = 100001;
  vector<long long> f;
  for (int min_dist = 1; min_dist * (k - 1) <= MAX; ++min_dist) {
    f.push_back(calc(min_dist));
  }
  f.push_back(f.back());
  for (int i = 0; i + 1 < f.size(); ++i) {
    add_mod(res, (i + 1) * (f[i] - f[i + 1]) % mod, mod);
  }
  cout << res << '\n';
}
