#include <bits/stdc++.h>
using namespace std;
const long long OF_MAX = (1LL << 36) - 1;
const long long LEN_MAX = 11;
long long LENGTH[LEN_MAX + 1];
inline long long mul(const long long &a, const long long &b) {
  if (!a || !b) return 0;
  if (b > OF_MAX / a) return OF_MAX + 1;
  return a * b;
}
inline int len(const long long &a) {
  return upper_bound(LENGTH, LENGTH + LEN_MAX + 1, a) - LENGTH;
}
long long N;
int res;
map<long long, int> pows;
vector<long long> power[LEN_MAX + 1];
inline int len_cp(const long long &a) {
  return (pows.find(a) != pows.end()) ? pows[a] : len(a);
}
inline int check(const long long &n, const long long &x, const int &op) {
  switch (op) {
    case 0:
      return (n >= x) ? len_cp(n - x) : LEN_MAX;
    case 1:
      return (x >= n) ? len_cp(x - n) : LEN_MAX;
    case 2:
      return (x && x * (n / x) == n) ? len_cp(n / x) : LEN_MAX;
    default:
      return (n && x / n && x / (x / n) == n) ? len_cp(x / n) : LEN_MAX;
  }
}
inline int check_con(const long long &n, const long long &x, const int &op) {
  switch (op) {
    case 0:
      return (n >= x) ? len(n - x) : LEN_MAX;
    case 1:
      return (x >= n) ? len(x - n) : LEN_MAX;
    case 2:
      return (x && x * (n / x) == n) ? len(n / x) : LEN_MAX;
    default:
      return (n && x / n && x / (x / n) == n) ? len(x / n) : LEN_MAX;
  }
}
int main() {
