  for (int i = 2; i <= LEN_MAX; i++) LENGTH[i] = LENGTH[i - 1] * 10;
  for (long long a = 2; mul(a, a) <= OF_MAX; a++) {
    long long tmp = a;
    for (long long p = 2; (tmp = mul(a, tmp)) <= OF_MAX; p++) {
      int tmp_len = len(a) + len(p) + 1;
      if (len(tmp) <= tmp_len) continue;
      if (pows.find(tmp) == pows.end() || pows[tmp] > tmp_len) {
        pows[tmp] = tmp_len;
      }
    }
  }
  for (map<long long, int>::iterator it = pows.begin(); it != pows.end();
       it++) {
    power[it->second].push_back(it->first);
  }
  while (scanf("%lld", &N) && (N >= 0)) {
    res = len_cp(N);
    for (int l1 = 3; l1 < res - 2; l1++)
      for (long long fp : power[l1]) {
        for (int op = 0; op < 4; op++)
          res = min(res, l1 + 1 + check(N, fp, op));
        for (int l2 = 3; l2 < res - 3 - l1; l2++)
          for (long long sp : power[l2]) {
            for (int op = 0; op < 2; op++) {
              if (fp + sp <= OF_MAX)
                res = min(res, l1 + l2 + 2 + check_con(N, fp + sp, op));
