map<long long, long long> pfd(long long x) {
  map<long long, long long> res;
  long long e = sqrt(x) + 1;
  for (long long i = 2; i < e; i++) {
    if (x % i == 0) {
      int cnt = 0;
      while (x % i == 0) {
        cnt++;
        x /= i;
      }
      res[i] = cnt;
    }
  }
  return res;
