string str;
int n, len;
int dp[105][1 << 19];
int bin[19 << 1];
int num[105], sum[105];
int main() {
  std::cin >> str >> n;
  for (int i = 0; i <= 19; i++) bin[i] = 1 << i;
  for (int i = 0; i < str.length(); i++) {
    num[i] = str[i] - '0';
    sum[num[i]]++;
  }
  for (int i = 0; i < str.length(); i++) {
    if (num[i]) dp[num[i] % n][1 << i]++;
  }
  for (int i = 1; i < (1 << str.length()); i++) {
    for (int j = 0; j < n; j++) {
      if (!dp[j][i]) continue;
      for (int k = 0; k < str.length(); k++) {
        if (i & (1 << k)) continue;
        dp[(j * 10 + num[k]) % n][i | bin[k]] += dp[j][i];
      }
    }
  }
  for (int i = 0; i < 10; i++) {
    for (int j = 1; j <= sum[i]; j++) {
      dp[0][(1 << str.length()) - 1] /= j;
    }
  }
  printf("%d\n", dp[0][(1 << str.length()) - 1]);
  return 0;
}

