			else {
				in = new MyScanner();
				out = System.out;
			}
		}
		solve();
	}

	private static void solve() throws IOException
	{
		int N = in.nextInt();
		int[] nums = new int[N];
		for (int i = 0; i < N; i++) {
			nums[i] = in.nextInt();
		}
		Set<Integer> set = new HashSet<Integer>();
		Set<Integer> tmp = new HashSet<Integer>();
		Set<Integer> tmpset;
		int k = nums[0];
		set.add(k);
		for (int i = 1; i < N; i++) {
			k = nums[i];
			tmpset = new HashSet<Integer>();
			tmpset.add(k);
			for (Integer x : tmp) {
				tmpset.add(x | k);
			}
			tmp = tmpset;
			for (Integer xx : tmpset) {
				set.add(xx);
			}
		}
		int cnt = set.size();
		out.print(cnt);
	}

