bool check(long long a, long long b) {
  if (a % 2 == 1) {
    return (b / a - 1) % 2;
  } else {
    if (a >= 1000000000 || b < a * a) {
      return !((b / a) % 2);
    } else {
      long long res = b / a;
      long long c1 = (res % (a + 1)) % 2;
      long long c2 = res % (a + 1);
      return !c1 || (c2 == a);
    }
