using namespace std;
class Rule {
 public:
  vector<int> x;
  int y;
  int size() { return x.size(); }
};
void CYK(int memo[33][33], vector<Rule>& rule, vector<int>& num) {
  for (int i = 0; i < int(33); i++)
    for (int j = 0; j < int(33); j++) memo[i][j] = 0;
  int mod = num.size();
  for (int j = 0; j < int(num.size()); j++) {
    for (int i = 0; i < int(num.size()); i++) {
      if (j == 0) {
        memo[i][i] = (1 << num[i]);
        continue;
      }
      for (int k = 0; k < int(rule.size()); k++) {
        if (j + 1 < rule[k].size()) continue;
        int dp[33][33] = {0};
        for (int p = 0; p < int(rule[k].size()); p++) {
          for (int c = 0; c < int(j + 1); c++) {
            if (p == 0) {
              dp[0][c] = (memo[i][(i + c) % mod] & (1 << rule[k].x[0])) > 0;
              continue;
            }
            for (int t = 1; t < int(c + 1); t++) {
              dp[p][c] = max(dp[p][c],
                             dp[p - 1][c - t] *
                                 ((memo[(i + c - t + 1) % mod][(i + c) % mod] &
                                   (1 << rule[k].x[p])) > 0));
            }
          }
        }
        if (dp[rule[k].size() - 1][j] >= 1) {
          memo[i][(i + j) % mod] |= (1 << rule[k].y);
        }
      }
    }
  }
}
