}
void add(int l, int r, int x) {
  if (l >= r) return;
  if (l / 4 == r / 4) {
    for (int i = l; i < int(r); ++i) {
      a[i] += x;
    }
    update(l / 4);
    return;
  }
  for (int j = l / 4 + 1; j < int(r / 4); ++j) {
    b[j] += x;
  }
  for (int i = l; i < int((l / 4 + 1) * 4); ++i) {
    a[i] += x;
  }
  update(l / 4);
  for (int i = r - r % 4; i < int(r); ++i) {
    a[i] += x;
  }
  update(r / 4);
}
