/* constant */

const int MAX_N = 12;
const int MAX_M = 8;

/* typedef */

/* global variables */

int n, m, gn;
int ids[26], ds[10], exps[MAX_N][MAX_M];
bool zfs[10], used[10];

/* subroutines */

int rec(int x, int y, int co) {
  if (x >= m) return (co == 0) ? 1 : 0;

  int eid = exps[y][x];

  if (y == n - 1) {
    int sum = co;
    for (int i = 0; i < n - 1; i++)
      sum += (exps[i][x] >= 0) ? ds[exps[i][x]] : 0;

    int dn = sum % 10, de = ds[eid];
    if (de < 0) {
      if (! used[dn] && (! zfs[eid] || dn > 0)) {
	used[dn] = true;
	ds[eid] = dn;
	int r = rec(x + 1, 0, sum / 10);
	ds[eid] = -1;
	used[dn] = false;
	return r;
      }
    }
    else if (dn == de) return rec(x + 1, 0, sum / 10);

    return 0;
  }

  if (eid < 0 || ds[eid] >= 0) return rec(x, y + 1, co);

  int r = 0;
  for (int d = 0; d <= 9; d++)
    if (! used[d] && (! zfs[eid] || d > 0)) {
      used[d] = true;
      ds[eid] = d;
      r += rec(x, y + 1, co);
      ds[eid] = -1;
      used[d] = false;
    }
  return r;
}

/* main */

