      if (m < sn) m = sn;
      for (int j = 0; j < sn; j++) {
	int ch = s[sn - 1 - j] - 'A';
	if (ids[ch] < 0) ids[ch] = gn++;
	exps[i][j] = ids[ch];
      }
      for (int j = sn; j < MAX_M; j++) exps[i][j] = -1;
      if (sn > 1) zfs[exps[i][sn - 1]] = true;
    }

    if (false) {
      for (int i = 0; i < n; i++) {
	for (int j = m - 1; j >= 0; j--) {
	  if (exps[i][j] >= 0) printf("%d", exps[i][j]);
