            int v = i;
            int prod = 1;
            for (int j = 2; j * j <= v; j++) {
                int c = 0;
                if (v % j == 0) {
                    while (v % j == 0) {
                        v /= j;
                        c++;
                    }
                }
                if (c % 2 == 1) {
                    prod *= j;
                }
            }
            if (v > 1) {
                prod *= v;
            }
            if (prod == 1) {
                prime_map[i] = 0;
            } else {
                prime_map[i] = prod;
            }
        }
        int t = in.nextInt();
        while (t-- > 0) {
            solve();
        }
        long endTime = System.nanoTime();
        err.println("Execution Time : +" + (endTime - startTime) / 1000000 + " ms");
        exit(0);
    }

    static void solve() {
        int n = in.nextInt();
        int[] data = in.readAllInts(n);
        int q = in.nextInt();
        long[] queries = in.readAllLongs(q);
        int prime_even = 0;
        Map<Integer, Integer> prime_map_odd = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (prime_map[data[i]] == 0) {
                prime_even++;
            } else {
                prime_map_odd.merge(prime_map[data[i]], 1, ADD);
            }
        }
        int zero_ans = prime_even;

        int even_ans = prime_even;
        int odd_ans = 0;
        for (int i : prime_map_odd.keySet()) {
            zero_ans = Math.max(zero_ans, prime_map_odd.get(i));
            if (prime_map_odd.get(i) % 2 == 0) {
                even_ans += prime_map_odd.get(i);
            } else {
                odd_ans = Math.max(odd_ans, prime_map_odd.get(i));
            }
        }
        for (int i = 0; i < q; i++) {
            if (queries[i] == 0) {
                out.println(zero_ans);
            } else {
                out.println(Math.max(even_ans, odd_ans));
            }
        }
    }

