void Gaussian_elimination(vector<Bit> &v){
	int v_size = v.size();
    REP(i, m) {
        int pla = -1;
        for(int j = ran;j < v_size;j++){
            if(v[j][i] == 1){
                pla = j;
                break;
            }
        }

        if(pla != -1){
            swap(v[ran], v[pla]);
            for(int j = 0;j < v_size;j++){
				if(j == ran)continue;
                if(v[j][i] == 1)v[j] ^= v[ran];
            }
            ran++;
        }
    }
}

void makeBaseNum(vector<Bit> v) {
    REP(i,n){
        REP(j,BIT_N){
            if(v[i][j] == 1){
                baseNum.EB(j);
                break;
            }
        }
    }
}

void check(int c, vector<Bit> v){

    vector<int> num = baseNum;
    bool ism = false;
    REP(i,n){
        if(v[i][c] == 1){
            v[i][m] = 1;
            if(num[i] == c){
                do{
                    num[i]++;
                }while(v[i][num[i]] != 1);
            }
        }
        if(num[i] == m)ism = true;
        v[i][c] = 0;
    }

    REP(i,n-1){
        if(num[i] > num[i+1]){
            swap(num[i], num[i+1]);
            swap(v[i], v[i+1]);
        }
    }

    REP(i,n){
        bool pla = false;
        bool mai = false;
        REP(j,n){
            auto tmp = v[j][m] ^ v[j][m + 1 + i];
            if(j >= ran && tmp){
                pla = true;
            }
            if(j == ran - 1 && num[ran - 1] == m && !tmp)mai = true;
        }
        if(ism && !pla && mai){
            ans[i][c] = '-';
        }
        else if(!ism && pla){
            ans[i][c] = '+';
        }
        else {
            ans[i][c] = '0';
        }
    }

}

