class MergeSort {


	public static int[] mergeSort(int[] array,int startIndex, int end){
		int ans[] = new int[end-startIndex+1];
		if (startIndex>=end){			
			ans[0] = array[startIndex];
			return ans;
		}
		int len = end-startIndex+1;
		int lowBoundLeft = startIndex;
		int highBoundLeft = startIndex+len/2-1;
		int lowBoundRight = highBoundLeft+1;
		int highBoundRight = end;

		int b[] = mergeSort(array,lowBoundLeft,highBoundLeft);
		int c[] = mergeSort(array,lowBoundRight,highBoundRight);
		return mergeTwoArrays(b, c, len);

	}

	private static int[] mergeTwoArrays(int[] b, int[] c, int len){
		int lowBoundLeft   = 0;
		int highBoundLeft  = b.length-1;
		int lowBoundRight  = 0;
		int highBoundRight = c.length-1;

		int[] ans = new int[len];
		for(int i=0; i<len; i++){
			if (b[lowBoundLeft]<c[lowBoundRight]){
				ans[i] =  b[lowBoundLeft++];
				if (lowBoundLeft>highBoundLeft){
					while(lowBoundRight<=highBoundRight){
						ans[++i] = c[lowBoundRight++];
					}
					return ans;
				}
			}
			else if (c[lowBoundRight]<=b[lowBoundLeft]){
				ans[i] =  c[lowBoundRight++];

				if (lowBoundRight>highBoundRight){
					while(lowBoundLeft<=highBoundLeft){
						ans[++i] = b[lowBoundLeft++];
					}
					return ans;
				}
			}
		}
		return ans;
	}

}


class InsertionSort {


	public static int[][] insertionSort(int[][] arrElements,int ind,int n){
		for(int i = 1; i < n; i++){
            int j = i;
            while(j > 0)
            {
                  if(arrElements[j-1][ind] > arrElements[j][ind])
                  {
                        int temp = arrElements[j - 1][ind];
                        arrElements[j - 1][ind] = arrElements[j][ind];
                        arrElements[j][ind] = temp;
                        j--;
                  }
                  else
                        break;
            }
      }
		return arrElements;
	}

}

