queue<int> Q;
void ARUMIN(int x = 1, int lim = 0, int lvl = 0) {
  if (lvl == 8) {
    MAPPA[vec] = cnt;
    dic[cnt++] = vec;
    return;
  }
  for (int i = 0; x < 1e8; i++) {
    if (i >= lim) {
      vec.push_back(i);
      ARUMIN(x, i, lvl + 1);
      vec.pop_back();
    }
    x *= p[lvl];
  }
  return;
}
void BFS(int st) {
  for (int i = 1; i < cnt; i++)
    if (WIT[num[i]] == st) {
      Q.push(i);
      dist[st][i] = 0;
    }
  while (!Q.empty()) {
    int v = Q.front();
    Q.pop();
    for (int i = 0; i < 8; i++)
      for (int b = -1; b < 2; b += 2) {
        vec = dic[v];
        vec[i] += b;
        sort(vec.begin(), vec.end());
        if (MAPPA[vec]) {
          int u = MAPPA[vec];
          if (dist[st][u] > dist[st][v] + 1) {
            dist[st][u] = dist[st][v] + 1;
            Q.push(u);
          }
        }
        vec = dic[v];
      }
  }
  return;
}
vector<int> ANNIE(vector<int> &V, int v) {
  V.clear();
  while (v > 1) {
    int t = 0;
    for (int tmp = D[v]; v % tmp == 0; v /= tmp) t++;
    V.push_back(t);
  }
  while (V.size() < 8) V.push_back(0);
  sort(V.begin(), V.end());
  return V;
}
