	{
		if(x == 0 || y == 0)
			return 0;
		if(x <= upperLimit / y)
			return x * y;
		return upperLimit;
	}
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

	static long lcm(long a, long b) { return mult(a / gcd(a, b), b); }
    long dfs(int u,int p,long w[],long a[])
