long long S(long long n, long long k) {
  if (k > n) return 0;
  long long ans = 0;
  for (long long i = 0; i <= k; ++i)
    ((ans) = ((ans) + (ppow(i, n) * C(k, i) * ppow(-1, k - i))) % mod);
  return ans * Inv[k] % mod;
}
