#include <bits/stdc++.h>
using namespace std;
const double EPS = 1e-9;
const double PI = 3.1415926535897932384626433832795;
unsigned long long mod = 1000 * 1000 * 1000 + 7;
int INF = 1000 * 1000 * 1000;
const int NN = 5;
const int N = 1 << NN;
int treemin[N];
int treepos[N];
int treeadd[N];
int SHIFT = 1 << (NN - 1);
void update(int &res, int &pos, int i) {
  if (treemin[i] + treeadd[i] < res) {
    res = treemin[i] + treeadd[i];
    pos = treepos[i] - SHIFT;
  }
}
pair<int, int> getMin(int v, int tl, int tr, int l, int r) {
  if (v >= N || l > r || l > tr || r < tl) return make_pair(INF, 0);
  if (l == tl && tr == r)
    return make_pair(treemin[v] + treeadd[v], treepos[v]);
  else {
    int tm = (tl + tr) / 2;
    pair<int, int> rl = getMin(v * 2, tl, tm, l, min(r, tm));
    pair<int, int> rr = getMin(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
    if (rl.first != INF) rl.first += treeadd[v];
    if (rr.first != INF) rr.first += treeadd[v];
    return min(rl, rr);
  }
}
void update(int v, int tl, int tr, int l, int r, int add) {
  if (l > r || l > tr || r < tl) return;
  if (l == tl && tr == r)
    treeadd[v] += add;
  else {
    int tm = (tl + tr) / 2;
    update(v * 2, tl, tm, l, min(r, tm), add);
    update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, add);
  }
}
void build(vector<int> &v) {
  for (int i = 0; i < N; i++) treemin[i] = INF;
  for (int i = 0; i < v.size(); i++) {
    treemin[i + SHIFT] = v[i];
    treepos[i + SHIFT] = i + SHIFT;
  }
  for (int i = SHIFT - 1; i >= 1; i--) {
    if (treemin[i << 1] < treemin[(i << 1) + 1]) {
      treemin[i] = treemin[i << 1];
      treepos[i] = treepos[i << 1];
    } else {
      treemin[i] = treemin[(i << 1) + 1];
      treepos[i] = treepos[(i << 1) + 1];
    }
  }
}
int main() {
  int n;
  cin >> n;
  vector<int> v(n);
  for (int i = 0; i < n; i++) cin >> v[i];
  build(v);
  queue<pair<int, int> > q;
  q.push(make_pair(0, n - 1));
  vector<pair<int, int> > ret;
  while (!q.empty()) {
    pair<int, int> top = q.front();
    q.pop();
    pair<int, int> r =
        getMin(1, SHIFT, N - 1, SHIFT + top.first, SHIFT + top.second);
    if (r.first != 0) {
      for (int i = 0; i < r.first; i++)
        ret.push_back(make_pair(top.first, top.second));
      update(1, SHIFT, N - 1, SHIFT + top.first, SHIFT + top.second, -r.first);
    }
    r.second -= SHIFT;
    if (top.first <= r.second - 1) q.push(make_pair(top.first, r.second - 1));
    if (r.second + 1 <= top.second) q.push(make_pair(r.second + 1, top.second));
  }
  cout << ret.size() << endl;
  for (int i = 0; i < ret.size(); i++)
    cout << ret[i].first << " " << ret[i].second << endl;
  return 0;
}

