def match_same(col):
    if len(set(col)) == 1:
        return 0
    return 1

def match_exact(p, q):
    assert(len(p) == len(q))
    ret = 0
    for a,b in zip(p,q):
        if a != b:
            ret += 1
    return ret

def match_diff(col):
    if len(set(col)) == 1: return 1
    if len(col) == 2: return 0
    assert(len(col) == 3)

    return min(
        match_exact(col, (0,1,0)),
        match_exact(col, (1,0,1))
    )

def match(col, is_same):
    if is_same:
        return match_same(col)
    else:
        return match_diff(col)

def ans_s(A):
    is_same = True
    ret = 0
    for col in A:
        ret += match(col, is_same)
        is_same = not is_same
    return ret

def ans_d(A):
    is_same = False
    ret = 0
    for col in A:
        ret += match(col, is_same)
        is_same = not is_same
    return ret

def ans(A):
    return min(ans_s(A), ans_d(A))

