using namespace std;
struct Data {
  int x, y, idx;
  Data() {}
  Data(int x, int y) : x(x), y(y) {}
  bool operator<(const Data &a) const {
    return make_pair(x, y) < make_pair(a.x, a.y);
  }
};
bool vis[55], grid[55][55];
vector<pair<Data, Data> > ans, revAns;
pair<int, int> par[55][55];
int dist[55][55];
int m;
int fx[] = {1, -1, 0, 0};
int fy[] = {0, 0, 1, -1};
bool isvali(int x, int y) { return x <= m && x >= 1 && y <= m && y >= 1; }
bool bfs(int stx, int sty, int enx, int eny) {
  queue<pair<int, int> > Q;
  Q.push({stx, sty});
  memset(dist, -1, sizeof dist);
  dist[stx][sty] = 0;
  while (!Q.empty()) {
    auto top = Q.front();
    Q.pop();
    int x = top.first;
    int y = top.second;
    if (enx == x && eny == y) return true;
    for (int i = 0; i < 4; i++) {
      int a = x + fx[i];
      int b = y + fy[i];
      if (isvali(a, b) == false) continue;
      if (dist[a][b] == -1) {
        par[a][b] = {x, y};
        dist[a][b] = dist[x][y] + 1;
        Q.push({a, b});
      }
    }
  }
  return false;
}
int main() {
  int n;
  scanf("%d %d", &m, &n);
  Data st[n], now[n];
  memset(grid, 0, sizeof grid);
