    scanf("%d %d", &st[i].x, &st[i].y);
    grid[st[i].x][st[i].y] = 1;
    st[i].idx = i;
  }
  sort(st, st + n);
  for (int j = 0; j < n; j++)
    for (int i = 0; i < n; i++) {
      if (!vis[i]) {
        if (bfs(i + 1, st[i].y, st[i].x, st[i].y)) {
          vis[i] = 1;
          int x = st[i].x;
          int y = st[i].y;
          while (x != i + 1) {
            int nwx = par[x][y].first, nwy = par[x][y].second;
            ans.push_back({Data(x, y), Data(nwx, nwy)});
            x = nwx;
            y = nwy;
          }
          grid[st[i].x][st[i].y] = 0;
          grid[x][y] = 1;
          now[st[i].idx] = Data(x, y);
