inline int ksm(int x, int y) {
  int res = 1;
  while (y) {
    if (y & 1) res = (long long)res * x % mod;
    x = (long long)x * x % mod;
    y >>= 1;
  }
  return res;
}
int dp[maxn][maxn], fac[maxn * maxn], ifac[maxn * maxn];
inline int C(int n, int m) {
  return (long long)fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}
inline void init(int n) {
  fac[0] = 1;
  for (register int i = 1, iend = n; i <= iend; ++i)
    fac[i] = (long long)i * fac[i - 1] % mod;
  ifac[n] = ksm(fac[n], mod - 2);
  for (register int i = n, iend = 1; i >= iend; --i)
    ifac[i - 1] = (long long)i * ifac[i] % mod;
}
