      dp[i][j] = dp[i - 1][j];
      if (j)
        dp[i][j] =
            (dp[i][j] + (long long)dp[i][j - 1] * (n - j + 1) % mod *
                            C(n * k - i - (j - 1) * (k - 1) - 1, k - 2)) %
