void deleterpt(vector<pair<double, double> > &ans) {
  vector<pair<double, double> >::iterator it;
  for (it = ans.begin(); it != ans.end(); it++) {
    if (abs((*it).first - (*(it - 1)).first) < 1e-6 &&
        (abs((*it).second - (*(it - 1)).second) < 1e-6)) {
      ans.erase(it);
      it--;
    };
  };
}
int confirm(vector<pair<int, int> > &coords, pair<double, double> &central,
            int k) {
  int cont = 0, i = 0, j = (int)coords.size() - 1;
  while (i < j) {
    while (((double)coords[j].first >
            (2 * central.first - (double)coords[i].first)) &&
           (abs((double)coords[j].first -
                (2 * central.first - (double)coords[i].first)) > 1e-6) &&
           j > i) {
      cont++;
      if (j > i)
        j--;
      else
        break;
    };
    while (((double)coords[j].second >
            (2 * central.second - (double)coords[i].second)) &&
           (abs((double)coords[j].second -
                (2 * central.second - (double)coords[i].second)) > 1e-6) &&
           (abs((double)coords[j].first -
                (2 * central.first - (double)coords[i].first)) < 1e-6) &&
           j > i) {
      cont++;
      if (j > i)
        j--;
      else
        break;
    };
    if ((abs((double)coords[j].second -
             (2 * central.second - (double)coords[i].second)) < 1e-6) &&
        (abs((double)coords[j].first -
             (2 * central.first - (double)coords[i].first)) < 1e-6)) {
      i++;
      j--;
    } else {
      i++;
      cont++;
    }
    if (cont > k) break;
  };
  return cont <= k;
}
