  if (l == r) {
    seg[at] = a[l];
    return;
  }
  int mid = (l + r) >> 1;
  build(at << 1, l, mid);
  build(at << 1 | 1, mid + 1, r);
  seg[at] = min(seg[at << 1], seg[at << 1 | 1]);
}
int get(int at, int l, int r) {
  if (l > e || r < s) return 1e9;
  if (l >= s && r <= e) return seg[at];
  int mid = (l + r) >> 1;
  return min(get(at << 1, l, mid), get(at << 1 | 1, mid + 1, r));
}
