  }
  vector<bool> res(q);
  for (int t = lim; t--; ) {
    for (auto e : qs[t]) {
      res[e.id] = st.acc(e.x + 1, e.y, e.z + 1, e.w) > e.w;
    }
    for (auto e : rec[t]) {
