#include <bits/stdc++.h>
using namespace std;
long long int e = 1e7 + 5;
vector<long long int> p(e + 10000, 1);
void sieve() {
  long long int i, j;
  p[0] = 0;
  p[1] = 0;
  for (int i = 2; i * i < e; i++) {
    if (p[i]) {
      for (j = i * i; j < e; j += i) p[j] = 0;
    }
  }
}
vector<long long int> fact(long long int x) {
  vector<long long int> v;
  long long int i;
  if (x % 2 == 0) {
    v.push_back(2);
    while (x % 2 == 0) x /= 2;
  }
  for (i = 3; i <= sqrt(x); i += 2) {
    if (x % i == 0) {
      v.push_back(i);
      while (x % i == 0) x /= i;
    }
  }
  if (x > 2) v.push_back(x);
  return v;
}
long long int power(long long int a, long long int n) {
  long long int result = 1;
  while (n) {
    if (n & 1) result = (result * a);
