ull hasher[63];

struct mybitset {
	ui a[63];

	void set(ui x) {
		a[x >> 5u] |= 1u << (x & 31u);
	}

	void operator^= (const mybitset& b) {
		for (ui i=0; i<63; i++)
			a[i] ^= b.a[i];
	}

	ui ffs() const {
		for (ui i=0; i<63; i++) {
			if (a[i]) {
				return (i << 5u) | __builtin_ctz(a[i]);
			}
		}
		return 2016u;
	}

	ull hash() const {
		ull h = 0;
		for (ui i=0; i<63; i++) {
			h ^= a[i] * hasher[i];
		}
		return h;
	}

	ui popcnt() const {
		ui h = 0;
		for (ui i=0; i<63; i++) {
			h += __builtin_popcount(a[i]);
		}
		return h;
	}

	mybitset minus(const mybitset& b) const {
		mybitset t;
		for (ui i=0; i<63; i++) {
			t.a[i] = a[i] & ~b.a[i];
		}
		return t;
	}

	bool notsubset(const mybitset& b) const {
		for (ui i=0; i<63; i++) {
			if (a[i] & ~b.a[i]) {
				return true;
			}
		}
		return false;
	}
};

