	ui c = a[i].popcnt();

	// cerr << "dodajem " << i << ' ' << c << ' ' << h << '\n';

	// ako je ovo novi len raskini adj par?
	int oldsz = mp[c].size();
	if (oldsz == 0) {
		auto it = lens.lower_bound(c);
		if (it != lens.end() && it != lens.begin()) {
			// i da si bio tu i da nisi brisem te sad mi vise ne trebas
			adj.erase(*prev(it));
		}
	}
	// treba da raskinem jer se promenio mp[c].begin()
	if (mp[c].empty() || mp[c].begin()->first > h) {
		// opet raskini
		adj.erase(c);
		auto it = lens.lower_bound(c);
		if (it != lens.begin()) {
			adj.erase(*prev(it));
		}
	}
	// dodaj sve normalno
	mp[c][h].insert(i);


	int nusz = mp[c].size();
	// oldsz <= nusz <= oldsz + 1
	if (nusz == 1 && oldsz == 0) {
		lens.insert(c);
	} else if (nusz == 2 && oldsz == 1) {
		dulens.insert(c);
	}

	// dodaj potencijalne nove adj parove (sa sledecim, sa prethodnim)
	{
		auto it = lens.find(c);
		if (next(it) != lens.end()) {
			int y = *next(it);
			int i = *mp[c].begin()->second.begin();
			int j = *mp[y].begin()->second.begin();
			if (a[i].notsubset(a[j])) {
				adj.insert(c);
			}
		}

		if (it != lens.begin()) {
			int y = *prev(it);
			int i = *mp[y].begin()->second.begin();
			int j = *mp[c].begin()->second.begin();
			if (a[i].notsubset(a[j])) {
				adj.insert(y);
			}
		}
	}
}

void skloni(int i) {
	ull h = a[i].hash();
	ui c = a[i].popcnt();

	int oldsz = mp[c].size();
	// brisi ga iz ovog seta
	mp[c][h].erase(i);
	bool perhaps = false;
	if (mp[c][h].empty()) {
		if (mp[c].begin()->first == h) {
			perhaps = true;
		}
		mp[c].erase(h);
	}

	int nusz = mp[c].size();

	// hendluj promene u adj
	if (nusz == 0) {
		auto it = lens.find(c);
		adj.erase(c);
		if (it != lens.begin()) {
			adj.erase(*prev(it));
			if (next(it) != lens.end()) {
				// novi par?
				int i = *mp[*prev(it)].begin()->second.begin();
				int j = *mp[*next(it)].begin()->second.begin();
				if (a[i].notsubset(a[j])) {
					adj.insert(*prev(it));
				}
			}
		}
	} else if (perhaps) {
		// brisni
		auto it = lens.find(c);
		adj.erase(c);
		if (it != lens.begin()) {
			adj.erase(*prev(it));
			if (next(it) != lens.end()) {
				// novi par?
				int i = *mp[    c    ].begin()->second.begin();
				int j = *mp[*next(it)].begin()->second.begin();
				if (a[i].notsubset(a[j])) {
					adj.insert(c);
				}
			} else {
				// novi par?
				int i = *mp[*prev(it)].begin()->second.begin();
				int j = *mp[    c    ].begin()->second.begin();
				if (a[i].notsubset(a[j])) {
					adj.insert(*prev(it));
				}
			}
		}

	}

	// promene u lens i dulens
	if (oldsz == 2 && nusz == 1) {
		dulens.erase(c);
	} else if (oldsz == 1 && nusz == 0) {
		lens.erase(c);
	}
}

