#include <bits/stdc++.h>
using namespace std;
int DFS(int idx, vector<vector<int> >& node, vector<int>& prenum,
        vector<int>& lowest, vector<int>& parent, int& num) {
  if (prenum[idx]) return prenum[idx];
  prenum[idx] = num++;
  lowest[idx] = prenum[idx];
  for (int i = 0; i < node[idx].size(); i++) {
    if (node[idx][i] == parent[idx]) continue;
    if (parent[node[idx][i]] == -1) parent[node[idx][i]] = idx;
    int t = DFS(node[idx][i], node, prenum, lowest, parent, num);
    if (lowest[node[idx][i]] < lowest[idx]) {
      lowest[idx] = lowest[node[idx][i]];
    }
    if (t != -1) lowest[idx] = t;
  }
  return -1;
}
void AP(vector<vector<int> >& node, set<int>& ans) {
  int size = node.size();
  vector<int> prenum(size, 0);
  vector<int> lowest(size, 0);
  vector<int> parent(size, -1);
  int num = 1;
  DFS(0, node, prenum, lowest, parent, num);
  int n_zero = 0;
  for (int i = 1; i < size; i++) {
    if (parent[i] == 0) n_zero++;
  }
  if (n_zero >= 2) ans.insert(0);
  for (int i = 1; i < size; i++) {
    if (lowest[i] >= prenum[parent[i]] && parent[i] != 0) {
      ans.insert(parent[i]);
    }
  }
}
