const long long MOD = 998244353;
long long add(long long a, long long b) {
  a += b;
  if (a >= MOD) a -= MOD;
  return a;
}
long long times(long long a, long long b) {
  a *= b;
  a %= MOD;
  return a;
}
long long fexp(long long m) {
  long long h = MOD - 2ll;
  long long r = 1ll;
  while (h > 0) {
    m %= MOD;
    if (h & 1ll) r *= m;
    m *= m;
    h >>= 1ll;
    r %= MOD;
  }
  return r;
}
void conect(int vert, int dis) {
  for (int i = 0; i < t[dis]; i++)
    if (edge[dis][i] != vert) {
      edge[vert].push_back(edge[dis][i]);
      t[vert]++;
      for (int j = 0; j < t[edge[dis][i]]; j++)
        if (edge[edge[dis][i]][j] == dis) {
          edge[edge[dis][i]][j] = vert;
          break;
        }
    }
  t[dis] = 0;
}
void super_node(int vert, int color) {
  conf[vert] = 1;
  check[vert] = a[vert];
