void resp(int vert) {
  conf[vert] = -1;
  if (a[vert] == 0)
    dp[vert][0] = 1;
  else
    dp[vert][1] = 1;
  for (int i = 0; i < t[vert]; i++)
    if (conf[edge[vert][i]] == 0) {
      resp(edge[vert][i]);
      dp[vert][0] =
          times(dp[vert][0], add(dp[edge[vert][i]][0], dp[edge[vert][i]][1]));
      dp[vert][1] =
          times(dp[vert][1], add(dp[edge[vert][i]][0], dp[edge[vert][i]][1]));
    }
  if (a[vert] == 0) {
    long long hf = 1;
    for (int i = 0; i < t[vert]; i++)
      if (conf[edge[vert][i]] == 1)
        hf = times(hf, add(dp[edge[vert][i]][0], dp[edge[vert][i]][1]));
    for (int i = 0; i < t[vert]; i++)
      if (conf[edge[vert][i]] == 1) {
        long long h = dp[edge[vert][i]][1];
        h = times(h, hf);
        h = times(h, fexp(add(dp[edge[vert][i]][0], dp[edge[vert][i]][1])));
        dp[vert][1] = add(dp[vert][1], h);
      }
  }
  conf[vert] = 1;
}
