public class P038C {

    public static void main(String[] args) {
        Scanner inScanner = new Scanner(System.in);
        int n = inScanner.nextInt();
        int minLength = inScanner.nextInt();
        int[] barLengths = new int[n];
        int maxLength = 0;
        for (int i = 0; i < n; i++) {
            barLengths[i] = inScanner.nextInt();
            maxLength = Math.max(maxLength, barLengths[i]);
        }
        int maxSquare = 0;
        for (int length = minLength; length <= maxLength; length++) {
            int currentWidth = 0;
            for (int barLength : barLengths)
                currentWidth += barLength / length;
            maxSquare = Math.max(maxSquare, currentWidth * length);
        }
        System.out.println(maxSquare);
    }
}

