/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author lewin
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        GSpeckledBand solver = new GSpeckledBand();
        solver.solve(1, in, out);
        out.close();
    }

    static class GSpeckledBand {
        int n;
        char[] s;
        GSpeckledBand.Query[] qs;
        int[][] count;

        int sum(int let, int f, int t) {
            return count[let][t] - (f == 0 ? 0 : count[let][f - 1]);
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            s = in.next().toCharArray();
            Hashing ss = new Hashing(new String(s));
            int m = in.nextInt();
            qs = new GSpeckledBand.Query[m];
            for (int i = 0; i < m; i++) {
                qs[i] = new GSpeckledBand.Query(in.nextInt() - 1, in.nextInt() - 1, i);
            }
            count = new int[26][n];
            for (int i = 0; i < n; i++) {
                if (i > 0) {
                    for (int j = 0; j < 26; j++) count[j][i] += count[j][i - 1];
                }
                count[s[i] - 'a'][i]++;
            }
            int[] ans = new int[m];
            Arrays.fill(ans, 4);
            outer:
            for (int i = 0; i < m; i++) {
                boolean found = false;
                for (int j = 0; j < 26; j++) {
                    if (sum(j, qs[i].l, qs[i].r) > 1) {
                        found = true;
                    }
                }
                if (!found) {
                    ans[i] = -1;
                    continue;
                }
                int len = (qs[i].r - qs[i].l + 1) / 2;
                if ((qs[i].r - qs[i].l + 1) % 2 == 0) {
                    if (ss.getHash(qs[i].l, len) == ss.getHash(qs[i].l + len, len)) {
                        ans[i] = 1;
                        continue;
                    }
                }
                for (int w = 1; w <= len; w++) {
                    if (ss.getHash(qs[i].l, w) == ss.getHash(qs[i].r - w + 1, w)) {
                        ans[i] = 2;
                        continue outer;
                    }
                    if (ss.getHash(qs[i].l, w) == ss.getHash(qs[i].l + w, w)) {
                        ans[i] = 2;
                        continue outer;
                    }
                    if (ss.getHash(qs[i].r - w - w + 1, w) == ss.getHash(qs[i].r - w + 1, w)) {
                        ans[i] = 2;
                        continue outer;
                    }
                }

                if (sum(s[qs[i].l] - 'a', qs[i].l, qs[i].r) > 1 || sum(s[qs[i].r] - 'a', qs[i].l, qs[i].r) > 1) {
                    ans[i] = 3;
                }
            }
            out.println(ans);
        }

        static class Query {
            public int l;
            public int r;
            public int id;

            public Query(int l, int r, int id) {
                this.l = l;
                this.r = r;
                this.id = id;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1 << 20];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == -1) {
                throw new InputMismatchException();
            } else {
                if (this.curChar >= this.numChars) {
                    this.curChar = 0;

                    try {
                        this.numChars = this.stream.read(this.buf);
                    } catch (IOException var2) {
                        throw new InputMismatchException();
                    }

                    if (this.numChars <= 0) {
                        return -1;
                    }
                }

                return this.buf[this.curChar++];
            }
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
                ;
            }

            byte sgn = 1;
            if (c == 45) {
                sgn = -1;
                c = this.read();
            }

            int res = 0;

            while (c >= 48 && c <= 57) {
                res *= 10;
                res += c - 48;
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }

            throw new InputMismatchException();
        }

        public String next() {
            int c;
            while (isSpaceChar(c = this.read())) {
                ;
            }

            StringBuilder result = new StringBuilder();
            result.appendCodePoint(c);

            while (!isSpaceChar(c = this.read())) {
                result.appendCodePoint(c);
            }

            return result.toString();
        }

        public static boolean isSpaceChar(int c) {
            return c == 32 || c == 10 || c == 13 || c == 9 || c == -1;
        }

    }

    static class Hashing {
        static final int multiplier = 43;
        static final Random rnd = new Random();
        static final int mod1 = BigInteger.valueOf((int) (1e9 + rnd.nextInt((int) 1e9))).nextProbablePrime().intValue();
        static final int mod2 = BigInteger.valueOf((int) (1e9 + rnd.nextInt((int) 1e9))).nextProbablePrime().intValue();
        static final int invMultiplier1 = BigInteger.valueOf(multiplier).modInverse(BigInteger.valueOf(mod1)).intValue();
        static final int invMultiplier2 = BigInteger.valueOf(multiplier).modInverse(BigInteger.valueOf(mod2)).intValue();
        long[] hash1;
        long[] hash2;
        long[] inv1;
        long[] inv2;
        int n;

        public Hashing(String s) {
            n = s.length();
            hash1 = new long[n + 1];
            hash2 = new long[n + 1];
            inv1 = new long[n + 1];
            inv2 = new long[n + 1];
            inv1[0] = 1;
            inv2[0] = 1;

            long p1 = 1;
            long p2 = 1;
            for (int i = 0; i < n; i++) {
                hash1[i + 1] = (hash1[i] + s.charAt(i) * p1) % mod1;
                p1 = p1 * multiplier % mod1;
                inv1[i + 1] = inv1[i] * invMultiplier1 % mod1;
                hash2[i + 1] = (hash2[i] + s.charAt(i) * p2) % mod2;
                p2 = p2 * multiplier % mod2;
                inv2[i + 1] = inv2[i] * invMultiplier2 % mod2;
            }
        }

        public long getHash(int i, int len) {
            return (((hash1[i + len] - hash1[i] + mod1) * inv1[i] % mod1) << 32)
                    + (hash2[i + len] - hash2[i] + mod2) * inv2[i] % mod2;
        }

    }

