#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100000 + 10;
const int INF = (int)(1e9);
const int dx[] = {1, -1, -1, 1};
const int dy[] = {1, 1, -1, -1};
int n, m, k, mn, cnt = 0, t = 0;
int X[MAXN], Y[MAXN], res[MAXN];
vector<int> xmy[2 * MAXN], xpy[2 * MAXN];
void input() {
  scanf("%d %d %d\n", &n, &m, &k);
  for (int i = 1; i <= k; i++) scanf("%d %d\n", &X[i], &Y[i]);
}
void init() {
  mn = max(m, n);
  for (int i = 1; i <= k; i++) {
    xmy[mn + X[i] - Y[i]].push_back(i);
    xpy[X[i] + Y[i]].push_back(i);
  }
}
void eliminate_sensors(bool s, int i, int x) {
  if (s) {
    for (int j : xpy[i])
      if (res[j] == -1) {
        res[j] = t + abs(X[j] - x);
        cnt++;
      }
    xpy[i].clear();
  } else {
    for (int j : xmy[i])
      if (res[j] == -1) {
        res[j] = t + abs(X[j] - x);
        cnt++;
      }
    xmy[i].clear();
  }
}
int get_step(int x, int y, int dir) {
  return min(((dx[dir] == 1) ? n - x : x), ((dy[dir] == 1) ? m - y : y));
}
void deal_with(int x, int y, int dir) {
  int step = get_step(x, y, dir);
  if (dir == 0)
    eliminate_sensors(false, mn + x - y, x);
  else if (dir == 1)
    eliminate_sensors(true, x + y, x);
  else if (dir == 2)
    eliminate_sensors(false, mn + x - y, x);
  else
    eliminate_sensors(true, x + y, x);
}
bool update(int &x, int &y, int &dir) {
  int step = get_step(x, y, dir);
  t += step;
  int xx = x, yy = y, od = dir;
  x += step * dx[dir];
  y += step * dy[dir];
  if (od == 0) {
    if (x == n)
      dir = 1;
    else
      dir = 3;
  } else if (od == 1) {
    if (x == 0)
      dir = 0;
    else
      dir = 2;
  } else if (od == 2) {
    if (x == 0)
      dir = 3;
    else
      dir = 1;
  } else if (od == 3) {
    if (x == n)
      dir = 2;
    else
      dir = 0;
  }
  if ((x == 0) && (y == 0)) return true;
  if ((x == 0) && (y == m)) return true;
  if ((x == n) && (y == 0)) return true;
  if ((x == n) && (y == m)) return true;
  return false;
}
void solve() {
  for (int i = 1; i <= k; i++) res[i] = -1;
  int x = 0, y = 0, dir = 0;
  int loop = 0;
  while (true) {
    deal_with(x, y, dir);
    bool stop = update(x, y, dir) || (cnt == k);
    if (stop) break;
  }
  for (int i = 1; i <= k; i++) cout << res[i] << endl;
}
void run() {
  input();
  init();
  solve();
}
int main() {
  int ntests = 1;
  for (int tc = 1; tc <= ntests; tc++) {
    run();
  }
}

