#include <bits/stdc++.h>
using namespace std;
const long long B = (long long)1e4;
long long mult(long long x, long long y, long long mod) {
  if (y == 0) return 0;
  return (mult(x, y / B, mod) * B + x * (y % B)) % mod;
}
long long bin_pow(long long x, long long p, long long mod) {
  if (p == 0) return 1 % mod;
  if (p & 1) return mult(x, bin_pow(x, p - 1, mod), mod);
  return bin_pow(mult(x, x, mod), p / 2, mod);
}
long long gcd(long long x, long long y) { return y == 0 ? x : gcd(y, x % y); }
long long lcm(long long x, long long y) { return x * (y / gcd(x, y)); }
const int N = 50;
int n;
long long P[N][2];
long long a[N][N][2];
vector<pair<long long, long long> > factorize(long long m) {
  vector<pair<long long, long long> > res;
  for (long long y = 2; y * y <= m; y++) {
    if (m % y) continue;
    res.push_back(make_pair(y, 0LL));
    while (m % y == 0) {
      res.back().second++;
      m /= y;
    }
    n++;
  }
  if (m > 1) {
    res.push_back(make_pair(m, 1LL));
  }
  return res;
}
long long ans;
void brute(int pos, long long PP, long long Q) {
  if (pos == n) {
    ans += PP / Q;
    return;
  }
  for (int i = 0; i <= P[pos][1]; i++) {
    brute(pos + 1, PP * a[pos][i][0], lcm(Q, a[pos][i][1]));
  }
}
int main() {
  long long m, x;
  cin >> m >> x;
  vector<pair<long long, long long> > q = factorize(m);
  n = (int)q.size();
  for (int i = 0; i < n; i++) {
    P[i][0] = q[i].first;
    P[i][1] = q[i].second;
  }
  ans = 0;
  for (int i = 0; i < n; i++) {
    long long mod = 1;
    q = factorize(P[i][0] - 1);
    for (int pw = 0; pw <= P[i][1]; pw++) {
      if (pw == 0) {
        a[i][pw][0] = a[i][pw][1] = 1;
        continue;
      }
      mod *= P[i][0];
      long long cur = mod - mod / P[i][0];
      for (int j = 0; j < (int)q.size(); j++) {
        for (int k = 0; k < q[j].second; k++) {
          long long ncur = cur / q[j].first;
          if (bin_pow(x, ncur, mod) != 1) break;
          cur = ncur;
        }
      }
      for (int k = 0; k < pw - 1; k++) {
        long long ncur = cur / P[i][0];
        if (bin_pow(x, ncur, mod) != 1) break;
        cur = ncur;
      }
      a[i][pw][0] = mod - mod / P[i][0];
      a[i][pw][1] = cur;
    }
  }
  brute(0, 1, 1);
  printf("%lld\n", ans);
  return 0;
}

