int main() {
  long long n, k, m = 0;
  cin >> n >> k;
  for (int i = 0; i < n; i++) cin >> a[i];
  for (long long i = 2; i * i <= k; i++) {
    if (k % i == 0) {
      s[m] = i;
      while (k % i == 0) {
        x[m]++;
        k /= i;
      }
      m++;
    }
  }
  if (k > 1) {
    s[m] = k;
    x[m]++;
    m++;
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      while (a[i] % s[j] == 0) {
        dp[j][i + 1]++;
        a[i] /= s[j];
      }
    }
  }
  for (int j = 0; j < 15; j++) s[j] = 0;
  long long ans = 0, r = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) s[j] -= dp[j][i];
    while (r <= n) {
      int q = 0;
      for (int j = 0; j < m; j++) {
        if (s[j] >= x[j]) q++;
      }
      if (q == m) break;
      r++;
      for (int j = 0; j < m; j++) s[j] += dp[j][r];
    }
