using namespace std;
const int maxn = 300 * 1000 + 7, mod = 1000 * 1000 * 1000 + 7;
long long node[4 * maxn][2], flag[4 * maxn][2];
int st[maxn], ft[maxn], cnt = 0, d[maxn], q, place[maxn];
int n, m;
vector<int> adj[maxn], topol;
void dfs(int u) {
  topol.push_back(u);
  st[u] = cnt++;
  for (int i = 0; i < adj[u].size(); i++) {
    int v = adj[u][i];
    d[v] = d[u] + 1;
    dfs(v);
  }
  ft[u] = cnt;
}
void up(int idx) {
  int L = 2 * idx + 1, R = L + 1;
  flag[L][1] += flag[idx][1], flag[L][1] %= mod;
  flag[R][1] += flag[idx][1];
  flag[R][1] %= mod;
  flag[idx][1] = 0;
  flag[L][0] += flag[idx][0];
  flag[L][0] %= mod;
  flag[R][0] += flag[idx][0];
  flag[R][0] %= mod;
  flag[idx][0] = 0;
}
void modify(int s, int e, int l, int r, int idx, long long k, long long val) {
  if (s >= r or l >= e) return;
  if (s == l and r == e) {
    flag[idx][1] += k;
    flag[idx][1] %= mod;
    flag[idx][0] += val;
    flag[idx][0] %= mod;
    return;
  }
  int mid = (s + e) / 2, L = 2 * idx + 1, R = L + 1;
  up(idx);
  modify(s, mid, l, min(r, mid), L, k, val);
  modify(mid, e, max(l, mid), r, R, k, val);
}
long long get(int s, int e, int id, int idx, int v) {
  if (s == e - 1)
    return ((flag[idx][0] + mod) - ((flag[idx][1] * d[v]) % mod) % mod);
  up(idx);
  int mid = (s + e) / 2, L = 2 * idx + 1, R = L + 1;
  if (id < mid)
    return get(s, mid, id, L, v);
  else
    return get(mid, e, id, R, v);
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; i++) {
    int u;
    scanf("%d", &u);
    u--;
    adj[u].push_back(i);
  }
  dfs(0);
  for (int i = 0; i < n; i++) {
    place[topol[i]] = i;
  }
  cin >> q;
  while (q--) {
    int t, v;
    scanf("%d%d", &t, &v);
    v--;
    if (t == 1) {
      int x, k;
      scanf("%d%d", &x, &k);
      long long X = x * 1ll, K = k * 1ll;
      modify(0, n, st[v], ft[v], 0, K % mod, (X + K * d[v]) % mod);
    }
    if (t == 2) {
      printf("%d\n", get(0, n, place[v], 0, v) % mod);
    }
  }
}

