import java.util.*;
public class D {
	Scanner sc = new Scanner(System.in);
	int [] minprime;
	private void doIt()
	{
		int n = sc.nextInt(), q = sc.nextInt();
		HashMap<Integer, ArrayList<Integer>> data = new HashMap<Integer,ArrayList<Integer>>();
		int [] used = new int[n+1];

		minprime = new int[n+1];
		for(int i = 2; i <= n; i++) minprime[i] = i;
		for(int i = 2; i <= n; i++) {
			if(minprime[i] == i) {
				for(int j = i + i; j <= n; j += i) minprime[j] = i;
			}
		}
		for(int i = 0; i < q; i++ ) {
			String op = sc.next();
			int num = sc.nextInt();
			if(op.charAt(0) == '+') {
				if(data.containsKey(num)) {
					System.out.println("Already on"); // already registered
				} else {
					// check prime
					ArrayList<Integer> d = new ArrayList<Integer>();
					int tmp = num;
					int conflict = 0;
					while(tmp > 1 && conflict == 0) {
						int v = minprime[tmp];
						if(tmp % v == 0) {
							d.add(v);
							if(used[v] > 0) conflict = used[v];
							while(tmp % v == 0) tmp /= v;
						}
					}
					if(conflict > 0) {
						System.out.println("Conflict with " + conflict);
					} else {
						data.put(num, d);
						for(Integer v: d) used[v] = num;
						System.out.println("Success");
					}
				}

			} else { // '-'
				if(data.containsKey(num)) {
					for(Integer v: data.get(num)) used[v] = 0;
					data.remove(num);
					System.out.println("Success");
				} else {
					System.out.println("Already off");
				}
			}
		}

	}
	public static void main(String[] args) {
		new D().doIt();
	}

}

