#include <bits/stdc++.h>
using namespace std;
const int N_MAX = 100000;
struct raqSB {
  int dataSize;
  int bucketSize;
  unsigned long long data[N_MAX];
  unsigned long long bucket[N_MAX];
  raqSB(const int n) {
    bucketSize = (int)sqrt(n) + 1;
    dataSize = bucketSize * bucketSize;
    for (int i = 0; i < N_MAX; i++) {
      data[i] = 0ull;
      bucket[i] = 0ull;
    }
  }
  void add(int s, int t, unsigned long long x) {
    int ss = s / bucketSize;
    int tt = t / bucketSize;
    if (ss == tt) {
      for (int i = s; i < t + 1; i++) {
        data[i] += x;
      }
    } else {
      for (int i = s; i < (ss + 1) * bucketSize; i++) {
        data[i] += x;
      }
      for (int i = tt * bucketSize; i < t + 1; i++) {
        data[i] += x;
      }
      for (int i = ss + 1; i < tt; i++) {
        bucket[i] += x;
      }
    }
  }
  unsigned long long get(int i) { return data[i] + bucket[i / bucketSize]; }
};
int main() {
  int n, q, s, t, i;
  unsigned long long x;
  cin >> n >> q;
  bool qType;
  raqSB raqsb(n);
  for (int j = 0; j < q; j++) {
    cin >> qType;
    if (qType) {
      cin >> i;
      cout << raqsb.get(i) << endl;
    } else {
      cin >> s >> t >> x;
      raqsb.add(s, t, x);
    }
  }
  return 0;
}

