struct node {
    //data
    int add;
    int numLeaves;
    bool lazy;
    inline void combine(const node & left, const node & right) {
        numLeaves = left.numLeaves + right.numLeaves;
        //simple combine
    }
    node(){numLeaves = 0; lazy = 0;add = 0;}
    //node(**data**){};

} tree[N << 2], identity;

struct segmentTree {

    int n;
    node * T;

    void init(int m) {
        n = m;
        T = tree;
        build(0, 0, n - 1);
    }

    void build(int x, int l, int r) {
        T[x].lazy = 0;
        //set other lazy parameters to zero
        if(l == r) {
            //set base condition
            if(iso[l] == 1)
              T[x].add = -a[l];
            else
              T[x].add = a[l];
            T[x].numLeaves = 1;
            return;
        }
        int m = (l + r) >> 1;
        build(l(x), l, m);
        build(r(x), m + 1, r);
        // T[x].combine(T[l(x)], T[r(x)]);
    }

    inline void propagate(int x, int l, int r) {
        if(1) {
            //update data

            if(l != r) {
                //update here and set their lazy here

                //might need to change this
                // T[l(x)].lazy = 1;
                // T[r(x)].lazy = 1;
                T[l(x)].add += T[x].add;
                T[r(x)].add += T[x].add;
                T[x].add = 0;
            }
            //might need to change this
            // T[x].lazy = 0;
            //unset other lazy parameters
        }
    }

    //might need to add a value parameter here
    void updateRange(int x, int l, int r, int ql, int qr /*add value parameter here*/) {
        propagate(x, l, r);
        if(l > qr || r < ql) return;
        if(l >= ql && r <= qr) {
            //update lazy and other if necessary
            T[x].add += val;
            return;
        }
        int m = (l + r) >> 1;
        updateRange(l(x), l, m, ql, qr);
        updateRange(r(x), m + 1, r, ql, qr);

    }

    node queryRange(int x, int l, int r, int q) {
        propagate(x, l, r);
        if(l == r) {
          if(iso[l] == 1)
            return T[x];
          else
            return T[x];
            //base case return
        }
        node ret;
        int m = (l + r) >> 1;
        if(q <= m) ret = queryRange(l(x), l, m, q);
        if(q > m) ret = queryRange(r(x), m + 1, r, q);
        return ret;
    }

    //add value parameter here
    void update(int ql, int qr /*value parameter*/) {
        updateRange(0, 0, n - 1, ql, qr /*value parameter*/);
    }

    int query(int ql) {
        return (queryRange(0, 0, n - 1, ql)).add;
    }
};


