struct dsu
{
	struct node
	{
		int par;
		bool touched = false;
	};
	vector<node> nodes;
	dsu(int _n)
		: nodes(_n)
	{
		range(i, _n) {
			nodes[i].par = i;
		}
	}

	node& find(int i)
	{
		if (nodes[i].par == i) return nodes[i];
		return nodes[i] = find(nodes[i].par);
	}

	bool touch(int a) {
		node& pa = find(a);
		if (pa.touched) return false;
		pa.touched = true;
		return true;
	}

	bool merge(int a, int b) {
		node& pa = find(a);
		node& pb = find(b);
		if (pa.par == pb.par) {
			return false;
		}
		pa.par = pb.par;
		return true;
	}
};

