void rotate(int cx,int cy){
	for(int i=0;i<6;i++){
		int nx=cx+rx[cx%2][i];
		int ny=cy+ry[cx%2][i];
		if(nx<0 || nx>=w || ny<0 || ny>=h)return;
	}
	int n0x=cx+rx[cx%2][0];
	int n0y=cy+ry[cx%2][0];
	int tmp=fie[n0y][n0x];
	for(int i=5;i>=0;i--){
		int n1x=cx+rx[cx%2][i];
		int n1y=cy+ry[cx%2][i];
		int n2x=cx+rx[cx%2][(i+1)%6];
		int n2y=cy+ry[cx%2][(i+1)%6];
		fie[n2y][n2x]=fie[n1y][n1x];
	}
	int n1x=cx+rx[cx%2][1];
	int n1y=cy+ry[cx%2][1];
	fie[n1y][n1x]=tmp;
}

bool fall(int cx,int cy){
	for(int i=0;i<3;i++){
		int nx=cx+fx[cx%2][i];
		int ny=cy+fy[cx%2][i];
		if(nx>=0 && nx<w && ny>=0 && ny<h){
			if(fie[ny][nx]!=-1)return false;
		}
	}
	swap(fie[cy][cx],fie[cy-1][cx]);
	return true;
}

int cnt[2501];
int type[51][51];
bool used[51][51];

void dfs(int cx,int cy,int k){
	cnt[k]++;
	type[cy][cx]=k;
	used[cy][cx]=true;
	for(int i=0;i<6;i++){
		int nx=cx+rx[cx%2][i];
		int ny=cy+ry[cx%2][i];
		if(nx>=0 && nx<w && ny>=0 && ny<h){
			if(fie[ny][nx]==fie[cy][cx] && !used[ny][nx]){
				dfs(nx,ny,k);
			}
		}
	}
}

void process(){
	bool flag=true;
	while(flag){
		flag=false;
		bool flag2=true;
		while(flag2){
			flag2=false;
			for(int i=1;i<h;i++){
				for(int j=0;j<w;j++){
					if(fie[i][j]!=-1 && fall(j,i)){
						flag2=true;
					}
				}
			}
		}
		memset(cnt,0,sizeof(cnt));
		memset(used,false,sizeof(used));
		int sz=0;
		for(int i=0;i<h;i++){
			for(int j=0;j<w;j++){
				if(fie[i][j]!=-1 && !used[i][j]){
					dfs(j,i,sz++);
				}
			}
		}
		for(int i=0;i<h;i++){
			for(int j=0;j<w;j++){
				if(fie[i][j]!=-1 && cnt[type[i][j]]>=3){
					fie[i][j]=-1;
					flag=true;
				}
			}
		}
	}
}

