struct seg_tree {
  long long N;
  vector<long long> xv, yv, xc, yc, lz;
  void init(long long n, long long *v) {
    N = 1;
    while (n > N) N *= 2;
    xv.resize(N * 2 - 1, 0);
    yv.resize(N * 2 - 1, 0);
    xc.resize(N * 2 - 1, 0);
    yc.resize(N * 2 - 1, 0);
    lz.resize(N * 2 - 1, 0);
    for (long long i = 0; i < n - 1; i++) {
      if (v[i] < v[i + 1])
        xc[i + N - 1]++;
      else
        yc[i + N - 1]++;
    }
    for (long long i = N - 2; i >= 0; i--) update(i);
  }
  void evaluate(long long k) {
    xv[k] += xc[k] * lz[k];
    yv[k] -= yc[k] * lz[k];
