      lz[k * 2 + 2] += lz[k];
    }
    lz[k] = 0;
  }
  void update(long long k) {
    xv[k] = xv[k * 2 + 1] + xv[k * 2 + 2];
    yv[k] = yv[k * 2 + 1] + yv[k * 2 + 2];
    xc[k] = xc[k * 2 + 1] + xc[k * 2 + 2];
    yc[k] = yc[k * 2 + 1] + yc[k * 2 + 2];
  }
  void add(long long a, long long b, long long x) { add(a, b, x, 0, 0, N); }
  void add(long long a, long long b, long long x, long long k, long long l,
