    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      lz[k] += x;
      evaluate(k);
      return;
    }
    add(a, b, x, k * 2 + 1, l, (l + r) / 2);
    add(a, b, x, k * 2 + 2, (l + r) / 2, r);
    update(k);
  }
  long long getSum(long long a, long long b) { return getSum(a, b, 0, 0, N); }
  long long getSum(long long a, long long b, long long k, long long l,
