void dfs(long long v, long long p, long long d, long long &k) {
  vs[k] = v;
  in[v] = out[v] = k;
  par[0][v] = p;
  depth[v] = d;
  k++;
  for (long long i = 0; i < G[v].size(); i++) {
    long long to = G[v][i];
    if (to == p) continue;
    dfs(to, v, d + 1, k);
    vs[k] = v;
    out[v] = k;
    k++;
  }
}
void init() {
  long long k = 0;
  dfs(0, -1, 0, k);
  seg.init(N * 2 - 1, vs);
  for (long long i = 0; i < 19; i++) {
    for (long long j = 0; j < N; j++) {
      if (par[i][j] < 0)
        par[i + 1][j] = -1;
      else
        par[i + 1][j] = par[i][par[i][j]];
    }
  }
}
long long lca(long long u, long long v) {
  if (depth[v] < depth[u]) swap(v, u);
  for (long long i = 0; i < 20; i++) {
    if ((depth[v] - depth[u]) >> i & 1) {
      v = par[i][v];
    }
  }
  if (v == u) return v;
  for (long long i = 19; i >= 0; i--) {
    if (par[i][v] != par[i][u]) {
      v = par[i][v];
      u = par[i][u];
    }
  }
  return par[0][v];
}
