void fil(int p, int l, int r, int x, int y, int z) {
  if (y < l || r < x) return;
  if (x <= l && r <= y) {
    one[p] = z;
    sum[p] = (r - l + 1) * z;
    return;
  }
  int d = (l + r) / 2;
  if (one[p] != 0) {
    one[2 * p] = one[2 * p + 1] = one[p];
    sum[2 * p] = rao[2 * p] * one[p];
    sum[2 * p + 1] = rao[2 * p] * one[p];
  }
  one[p] = 0;
  fil(2 * p, l, d, x, y, z);
  fil(2 * p + 1, d + 1, r, x, y, z);
  sum[p] = sum[2 * p] + sum[2 * p + 1];
}
int sm(int p, int l, int r, int x, int y, int b) {
  if (y < l || r < x) return 0;
  if (x <= l && r <= y) {
    if (one[p] != 0 && b == 0) b = one[p];
    if (b != 0) return b * (r - l + 1);
