  int d = (l + r) / 2, s = 0;
  if (one[p] != 0 && b == 0) b = one[p];
  s = sm(2 * p, l, d, x, y, b);
  s += sm(2 * p + 1, d + 1, r, x, y, b);
  return s;
}
