}
void modify(int l, int r, int pos, int v, int cur) {
  if (l == r) {
    mn[cur] = v;
    return;
  }
  if (pos <= ((l + r) >> 1))
    modify(l, ((l + r) >> 1), pos, v, (cur << 1));
  else
    modify(((l + r) >> 1) + 1, r, pos, v, (cur << 1 | 1));
  mn[cur] = min(mn[(cur << 1)], mn[(cur << 1 | 1)]);
}
int query(int L, int R, int l, int r, int cur) {
  if (L <= l && R >= r) return mn[cur];
  int v = 2000000000;
  if (L <= ((l + r) >> 1))
    v = min(v, query(L, R, l, ((l + r) >> 1), (cur << 1)));
  if (R > ((l + r) >> 1))
    v = min(v, query(L, R, ((l + r) >> 1) + 1, r, (cur << 1 | 1)));
  return v;
}
void add(long long x, int v) { mp[x] += v, val += x * v; }
int update(int x) {
  int cnt = 0, top = 0;
  for (map<long long, int>::iterator it = mp.upper_bound(x); it != mp.end();
       ++it)
    st[++top] = it->first, cnt += it->second, val -= it->first * it->second;
  while (top) mp.erase(st[top--]);
  return cnt;
}
