    nxt[i] = pos + (s[pos + 1] == s[i]), col[i - 1] = s[i];
    for (int j = 0; j < 26; ++j) fa[i][j] = fa[nxt[i]][j];
    fa[i][col[nxt[i]]] = nxt[i];
