    d.push_back(a);
  }
  sort(d.begin(), d.end());
  vector<int> prefixSum = calPrefixSum(d);
  for (int i = 0; i < m; ++i) {
    int a, b;
    cin >> a >> b;
    process(a, b, d, prefixSum);
  }
}
