#include <bits/stdc++.h>
using namespace std;
const int N = 1e6 + 10;
const int mod = 1e9 + 7;
int read() {
  int x = 0, f = 1;
  char c = getchar();
  while (c < '0' || c > '9') {
    if (c == '-') f = -1;
    c = getchar();
  }
  while (c >= '0' && c <= '9') x = (x << 1) + (x << 3) + c - '0', c = getchar();
  return x * f;
}
int inc(int x, int y) { return (x + y >= mod) ? (x + y - mod) : (x + y); }
int del(int x, int y) { return (x - y < 0) ? (x - y + mod) : (x - y); }
int qpow(int a, int x, int mo) {
  int res = 1;
  while (x) {
    if (x & 1) res = 1ll * res * a % mod;
    a = 1ll * a * a % mod;
    x >>= 1;
  }
  return res;
}
vector<int> g[N];
int out[N];
int k[N], b[N];
void dfs(int x, int fa) {
  if (g[x].size() == 1) return;
  for (int to : g[x]) {
    if (to == fa) continue;
    dfs(to, x);
    k[x] = inc(k[to], k[x]);
    b[x] = inc(b[to], b[x]);
  }
  b[x] = 1ll * (b[x] + out[x]) % mod *
         qpow((g[x].size() - k[x] + mod) % mod, mod - 2, mod) % mod;
  k[x] = 1ll * qpow((g[x].size() - k[x] + mod) % mod, mod - 2, mod) % mod;
}
int main() {
  int n = read();
  for (int i = 1; i < n; i++) {
    int u = read(), v = read(), w = read();
    g[u].push_back(v);
    g[v].push_back(u);
    out[u] = inc(out[u], w);
    out[v] = inc(out[v], w);
  }
  dfs(0, 0);
  cout << b[0] << endl;
}

