    class Seg implements Comparable<Seg>{
        int jl, jr;
        Seg( int _jl, int _jr ){
            jl = _jl;
            jr = _jr;
        }
        public int compareTo(Seg b) {
            int val = Integer.compare(jl, b.jl);
            if( val == 0 )
                return Integer.compare(jr, b.jr);
            return val;
        }
        public String toString(){
            return String.format( "(%d, %d)", jl, jr );
        }
