        for( int it = 0; it < m; ++it ){
            int i = sc.nextInt();
            int j = sc.nextInt();
            if( !pt.containsKey(i) )
                pt.put( i, new TreeSet<Integer>() );
            pt.get(i).add( j );
        }

        TreeSet<Seg> ts = new TreeSet<>();
        if( pt.containsKey(1) )
            ts.add( new Seg(1,pt.get(1).first()-1) );
        else
            ts.add( new Seg(1,n) );

        int pri = 0;
        for( int i : pt.keySet() ){
            if( pri + 1 < i ){
                int jl = ts.first().jl;
                ts.clear();
                ts.add(new Seg(jl,n));
            }

            for( int j : pt.get(i) ){
                Seg s = ts.floor(new Seg(j,j));
                if( s!=null && s.jl <= j && j <= s.jr ){
                    ts.remove(s);
                    if( s.jl <= j-1 )
                        ts.add(new Seg(s.jl, j-1));
                    if( j+1 <= s.jr )
                        ts.add(new Seg(j+1, s.jr));
                }
            }
            if( ts.isEmpty() ){
                out.println("-1");
                return;
            }

            if( pt.containsKey(i-1) )
                for( int j : pt.get(i-1) ){
                    Seg a = ts.lower (new Seg(j,j));
                    Seg b = ts.higher(new Seg(j,j));
                    if( a==null || b==null ) continue;
                    Integer midP = pt.get(i).lower(b.jl);
                    if( midP==null || midP<a.jr ){
                        ts.remove(b);
                        a.jr = b.jr;
                    }
                }

            {
                int jLast = pt.get(i).last();
                int jl = -1;
                while( !ts.isEmpty() && jLast < ts.last().jl ){
                jl = ts.last().jl;
                    ts.pollLast();
                }
                if( jl != -1 ) ts.add( new Seg(jl,n) );
            }
            //
            pri = i;
        }
        if( pri != n ){
            int jl = ts.first().jl;
            ts.clear();
            ts.add(new Seg(jl,n));
        }
        if( ts.last().jr == n )
            out.println( 2*(n-1) );
        else
            out.println("-1");
    }









