pair<int, int> t[N];
void dfs(int v, int p) {
  t[v] = t[p];
  if (hi[t[v].second] > hi[v]) {
    t[v].second = v;
  }
  if (hi[t[v].second] < hi[t[v].first]) swap(t[v].second, t[v].first);
  for (auto &u : g[v]) {
    if (u == p) continue;
    dfs(u, v);
  }
}
void upd(int nod, int l, int r, int L, int R, int val) {
  if (l >= R || L >= r) return;
  if (l >= L && r <= R) {
    seg[nod] += val;
    lazy[nod] += val;
    return;
  }
  int mid = (r + l) >> 1;
  upd(nod << 1, l, mid, L, R, val);
  upd(nod << 1 | 1, mid, r, L, R, val);
  seg[nod] = min(seg[nod << 1], seg[nod << 1 | 1]) + lazy[nod];
}
inline bool check(int v, int val) {
  for (auto &u : y[v]) {
    int x = hi[t[u].first];
    int y = min(hi[t[u].second], hi[t[u].first] + val);
    int z = upper_bound(h + 1, h + n + 1, x) - h;
    int e = upper_bound(h + 1, h + n + 1, y) - h;
    upd(1, 1, N, z, e, +1);
  }
  bool p1 = 0;
  if (seg[1] >= 0) p1 = 1;
  for (auto &u : y[v]) {
    int x = hi[t[u].first];
    int y = min(hi[t[u].second], hi[t[u].first] + val);
    int z = upper_bound(h + 1, h + n + 1, x) - h;
    int e = upper_bound(h + 1, h + n + 1, y) - h;
    upd(1, 1, N, z, e, -1);
  }
  return p1;
}
