#include <bits/stdc++.h>
using namespace std;
const int maxn = 110;
int dp[maxn][maxn][maxn][maxn];
int n, m, tx, ty, add;
int a[maxn][maxn], sumc[maxn][maxn], sumr[maxn][maxn], ans;
char s[maxn];
void chkmax(int& x, int y) {
  if (x < y) x = y;
}
int calc(int* sum, int l, int r) {
  if (l > r) return 0;
  return sum[r] - sum[l - 1];
}
int main() {
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; i++) {
    scanf("%s", s + 1);
    for (int j = 1; j <= m; j++)
      if (s[j] == 'o')
        a[i][j] = 1;
      else if (s[j] == 'E')
        tx = i, ty = j;
  }
  swap(tx, ty);
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) sumr[i][j] = sumr[i][j - 1] + a[i][j];
  for (int j = 1; j <= m; j++)
    for (int i = 1; i <= n; i++) sumc[j][i] = sumc[j][i - 1] + a[i][j];
  swap(n, m);
  for (int i = 0; i < tx; i++)
    for (int j = 0; j < ty; j++)
      for (int k = 0; k <= n - tx; k++)
        for (int l = 0; l <= m - ty; l++) {
          int v = min(ty + l, m - j), u = max(ty - j, l + 1);
          int b = min(tx + k, n - i), a = max(tx - i, k + 1);
          int now = dp[i][j][k][l];
          if (i < tx - 1) {
            if (tx - i - 1 > k)
              add = calc(sumc[tx - i - 1], u, v);
            else
              add = 0;
            chkmax(dp[i + 1][j][k][l], now + add);
          }
          if (j < ty - 1) {
            if (ty - j - 1 > l)
              add = calc(sumr[ty - j - 1], a, b);
            else
              add = 0;
            chkmax(dp[i][j + 1][k][l], now + add);
          }
          if (k < n - tx) {
            if (tx + k + 1 <= n - i)
              add = calc(sumc[tx + k + 1], u, v);
            else
              add = 0;
            chkmax(dp[i][j][k + 1][l], now + add);
          }
          if (l < m - ty) {
            if (ty + l + 1 >= m - j)
              calc(sumr[ty + l + 1], a, b);
            else
              add = 0;
