    return n->s;
  else
    return 0;
}
long long int mm(node *n) {
  if (n != NULL)
    return n->m;
  else
    return 5e18;
}
int update(node *n) {
  if (n != NULL) {
    n->s = size(n->l) + size(n->r) + n->c;
    n->m = min(n->x, min(mm(n->l), mm(n->r)));
  }
  return 0;
}
int prop(node *n) {
  if (n != NULL) {
    n->x += n->lazy, n->m += n->lazy;
    if (n->l != NULL) n->l->lazy += n->lazy;
    if (n->r != NULL) n->r->lazy += n->lazy;
    n->lazy = 0;
  }
  return 0;
}
int split(node *n, node *&l, node *&r, int s) {
  prop(n);
  if (n == NULL)
    l = r = NULL;
  else if (s >= size(n->l) + n->c)
    prop(n->l), split(n->r, n->r, r, s - size(n->l) - n->c), l = n;
  else
    prop(n->r), split(n->l, l, n->l, s), r = n;
  update(l), update(r);
  return 0;
}
int merge(node *l, node *r, node *&n) {
  prop(l), prop(r);
  if (l == NULL)
    n = r;
  else if (r == NULL)
    n = l;
  else if (l->p > r->p)
    prop(l->l), merge(l->r, r, l->r), n = l;
  else
    prop(r->r), merge(l, r->l, r->l), n = r;
  if (n != NULL) prop(n->l), prop(n->r), assert(n->lazy == 0);
  update(n);
  return 0;
}
