#include <bits/stdc++.h>
using namespace std;
vector<int> adj[1000005];
vector<int> num[1000005];
int arr[1000005];
int sz[1000005];
int par[1000005];
int find(int x) {
  if (par[x] == x) return x;
  return par[x] = find(par[x]);
}
void unite(int a, int b) {
  a = find(a);
  b = find(b);
  if (sz[a] > sz[b]) swap(a, b);
  if (a != b) {
    par[a] = b;
    sz[b] += sz[a];
  }
}
void solve() {
  int n;
  cin >> n;
  for (int i = 1; i <= n; i++) {
    cin >> arr[i];
    par[i] = i;
    sz[i] = 1;
    num[arr[i]].push_back(i);
  }
  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    adj[u].push_back(v);
    adj[v].push_back(u);
  }
  long long ans = 0;
  for (int i = 1; i < 1000005; i++) {
    for (auto u : num[i]) {
      for (auto v : adj[u]) {
        if (arr[v] <= i) {
          unite(v, u);
        }
      }
    }
    for (auto u : num[i]) {
      ans += i * sz[find(u)];
    }
  }
  for (int i = 1; i <= n; i++) {
    par[i] = i;
    sz[i] = 1;
  }
  for (int i = 1000005 - 1; i > 0; i--) {
    for (auto u : num[i]) {
      for (auto v : adj[u]) {
        if (arr[v] >= i) {
          unite(v, u);
        }
      }
    }
    for (auto u : num[i]) {
      ans -= i * sz[find(u)];
    }
  }
  cout << ans << endl;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.tie(nullptr);
  int t = 1;
  while (t--) {
    solve();
  }
}

