vector<long long> G[100000];
long long deg[100000];
long long mark[100000];
vector<pair<vector<long long>, vector<pair<long long, long long> > > > arrange(
    vector<long long> &vs, vector<pair<long long, long long> > &es) {
  for (long long i = 0; i < (es.size()); i++) {
    G[es[i].first][deg[es[i].first]++] = es[i].second;
    G[es[i].second][deg[es[i].second]++] = es[i].first;
  }
  long long cnt = 0;
  for (long long i = 0; i < (vs.size()); i++) {
    if (mark[vs[i]] != -1) continue;
    long long c = cnt++;
    mark[vs[i]] = c;
    queue<long long> que;
    que.push(vs[i]);
    while (que.size()) {
      long long v = que.front();
      que.pop();
      for (long long i = 0; i < deg[v]; i++) {
        long long u = G[v][i];
        if (mark[u] != -1) continue;
        mark[u] = c;
        que.push(u);
      }
    }
  }
  vector<pair<vector<long long>, vector<pair<long long, long long> > > > latte(
      cnt);
  for (long long i = 0; i < (vs.size()); i++)
    latte[mark[vs[i]]].first.push_back(vs[i]);
  for (long long i = 0; i < (es.size()); i++)
    latte[mark[es[i].first]].second.push_back(es[i]);
  for (long long i = 0; i < (vs.size()); i++) {
    mark[vs[i]] = -1;
    deg[vs[i]] = 0;
  }
  return latte;
}
pair<long long, long long> solve(
    pair<vector<long long>, vector<pair<long long, long long> > > &g) {
  vector<long long> &vs = g.first;
  vector<pair<long long, long long> > &es = g.second;
  long long N = vs.size();
  long long M = es.size();
  if (N * (N - 1) / 2 == M) {
    return {1, N};
  }
  for (long long i = 0; i < (M); i++) deg[es[i].first]++, deg[es[i].second]++;
  long long cent = -1;
  for (long long i = 0; i < (N); i++) {
    if (deg[vs[i]] == N - 1) cent = vs[i];
    deg[vs[i]] = 0;
  }
  assert(cent != -1);
  long long t = 0;
  for (long long i = 0; i < (vs.size()); i++) {
    if (vs[i] == cent) continue;
    vs[t++] = vs[i];
  }
  vs.erase(vs.begin() + t, vs.end());
  t = 0;
  for (long long i = 0; i < (es.size()); i++) {
    if (es[i].first == cent || es[i].second == cent) continue;
    es[t++] = es[i];
  }
  es.erase(es.begin() + t, es.end());
  vector<pair<vector<long long>, vector<pair<long long, long long> > > > latte =
      arrange(vs, es);
  pair<long long, long long> ans(0, 1);
  for (long long i = 0; i < (latte.size()); i++) ans = op(ans, solve(latte[i]));
  return ans;
}
