  do {
    int tmp = 0;
    tmp += cnt[0][0][4] - cnt[0][0][p[0]];
    tmp += cnt[0][1][4] - cnt[0][1][p[1]];
    tmp += cnt[1][0][4] - cnt[1][0][p[2]];
