    for (int j = 2; j < m; ++j) {
      if (j % 2) {
        int cho1 =
            cnt[0][j][4] - cnt[0][j][p[1]] + cnt[1][j][4] - cnt[1][j][p[3]];
        int cho2 =
            cnt[0][j][4] - cnt[0][j][p[3]] + cnt[1][j][4] - cnt[1][j][p[1]];
        tmp += min(cho1, cho2);
        if (cho1 < cho2) {
          a0 += di[p[1]];
          a1 += di[p[3]];
        } else {
          a0 += di[p[3]];
          a1 += di[p[1]];
        }
      } else {
        int cho1 =
            cnt[0][j][4] - cnt[0][j][p[0]] + cnt[1][j][4] - cnt[1][j][p[2]];
        int cho2 =
            cnt[0][j][4] - cnt[0][j][p[2]] + cnt[1][j][4] - cnt[1][j][p[0]];
        tmp += min(cho1, cho2);
        if (cho1 < cho2) {
          a0 += di[p[0]];
          a1 += di[p[2]];
        } else {
          a0 += di[p[2]];
          a1 += di[p[0]];
        }
      }
    }
    if (step > tmp) {
      step = tmp;
      ans = (vector<string>){a0, a1};
    }
  } while (next_permutation(p.begin(), p.end()));
  for (int i = 2; i < n; ++i) {
    ans.push_back(ans[i % 2]);
  }
  return make_pair(step, ans);
}
