            d[i] = sc.nextInt();
        }

        int[][] dp = new int[n+1][m+1];
        for (int i=0; i<n+1; i++)
            dp[i][0]=0;

        int max=0;
        for (int i=1; i<n+1; i++) {
            for (int j=1; j<m+1; j++) {
                max=0;
                for(int k=0; k<=a[j-1]/b[j-1]; k++) {
