const int N = 500011;
struct DisjointSet {
  int p[N];
  void init() { iota(p, p + N, 0); }
  int find(int x) {
    if (p[x] == x) return x;
    return p[x] = find(p[x]);
  }
  bool query(int a, int b) { return find(a) == find(b); }
  void merge(int a, int b) { p[find(a)] = find(b); }
} ds;
vector<int> edges[2][N];
set<int> st[N];
int par[N];
void dfs1(int cur, int last) {
  for (auto &v : edges[1][cur])
    if (v != last) {
      par[v] = cur;
      dfs1(v, cur);
    }
}
void dfs0(int cur, int last, vector<pair<int, int> > &ans0,
          vector<pair<int, int> > &ans1) {
  for (auto &v : edges[0][cur])
    if (v != last) {
      dfs0(v, cur, ans0, ans1);
      ans0.push_back({v, cur});
      ans1.push_back({v, par[v]});
    }
}
