  long long nxt, to;
} e[N << 1];
inline void Add(long long u, long long v) {
  e[++maxE].nxt = head[u];
  head[u] = maxE;
  e[maxE].to = v;
}
void DFS1(long long x, long long fa) {
  F[x] = a[x];
  for (register long long i = head[x]; i; i = e[i].nxt) {
    long long v = e[i].to;
    if (v == fa) continue;
    DFS1(v, x);
    F[x] += max(F[v], 0ll);
  }
  Ans1 = max(Ans1, F[x]);
}
void DFS2(long long x, long long fa) {
  F[x] = a[x];
  for (register long long i = head[x]; i; i = e[i].nxt) {
    long long v = e[i].to;
    if (v == fa) continue;
    DFS2(v, x);
    F[x] += max(F[v], 0ll);
  }
  if (F[x] == Ans1) Ans2++, F[x] = 0;
}
