		int NN = 200005;
		int MOD = 1000000007;
		int INF = 2000000000;
		long INFINITY = 2000000000000000000L;

		Long [] a = new Long[NN];
		long [] dp = new long[NN];

		public void solve(InputReader in, PrintWriter out) {
			long n = in.nextLong(), m = in.nextLong();
			a = new Long[(int)n];
			long sum = 0;			
			for(int i=0;i<n;++i) {
				a[i] = in.nextLong();
			}
			Arrays.sort(a);
			for(int i=0;i<n;++i) {
				sum += a[i];
				dp[i] = sum;
			}
			long ans = n;
			if(sum < m) {
				out.println(-1);return;
			}
			sum = 0;
			for(int i=(int)n-1;i>=0;--i) {
				int lo = 0, hi = i, mid = 0;
				while(lo < hi) {
					mid = (lo + hi) / 2;
					if(a[mid] > (i - mid)) {
						hi = mid;
					} else {
						lo = mid + 1;
					}
				}
				long pages = dp[(int)n - 1] - (lo>0?dp[lo-1]:0);
				long cnt = i - lo + 1;
				pages -= cnt*(cnt-1L)/2L;
				if(pages >= m) {
					ans = n-i;break;
				}
			}
			out.println(ans);
		}
	}

