int treeIdx[10000], parent[10000], lowest[10000], treeNodeCounter;
void dfs(int curIdx, int prev) {
  treeIdx[curIdx] = lowest[curIdx] = treeNodeCounter;
  treeNodeCounter++;
  visited[curIdx] = true;
  int next;
  for (int i = 0; i < G[curIdx].size(); ++i) {
    next = G[curIdx][i];
    if (!visited[next]) {
      parent[next] = curIdx;
      dfs(next, curIdx);
      lowest[curIdx] = min(lowest[curIdx], lowest[next]);
    } else if (next != prev) {
      lowest[curIdx] = min(lowest[curIdx], treeIdx[next]);
    }
  }
}
void criticalPoints() {
  for (int i = 0; i < n; ++i) visited[i] = false;
  treeNodeCounter = 1;
  dfs(0, -1);
