  for (int i = 1; i < n; ++i) {
    int p = parent[i];
    if (0 == p)
      np++;
    else if (treeIdx[i] <= lowest[i])
      s.insert(p);
  }
  if (np > 1) cout << 0 << endl;
  for (auto v : s) cout << v << endl;
}
