template <typename Tp>
void read(Tp &x) {
  x = 0;
  char ch = 1;
  int fh;
  while (ch != '-' && (ch < '0' || ch > '9')) ch = getchar();
  if (ch == '-') {
    fh = -1;
    ch = getchar();
  } else
    fh = 1;
  while (ch >= '0' && ch <= '9') {
    x = (x << 1) + (x << 3) + ch - '0';
    ch = getchar();
  }
  x *= fh;
}
int main() {
  read(n);
  for (register int i = 0; i < n; i++) {
    read(a[i]);
    s[1 << i] = a[i];
  }
  read(k);
  for (register int j = 1; j <= k; j++) read(eps[j]);
  opt[0] = 1;
  for (register int i = 1; i < (1 << n); i++) {
    s[i] = (s[(i & (-i))] + s[i & ~(i & (-i))]) % 1000000007;
    bool flag = 0;
    for (register int j = 1; j <= k; j++)
      if (s[i] == eps[j]) flag = 1;
    if (flag) continue;
    for (register int j = i; j != 0; j -= (j & (-j))) {
      opt[i] = (opt[i] + opt[i & ~(j & (-j))]) % 1000000007;
    }
  }
