public class Codeforces1172C2 {

	public static void main(String[] args) throws IOException {
		int mod = 998244353;

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		st = new StringTokenizer(br.readLine());
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(st.nextToken());
		}
		st = new StringTokenizer(br.readLine());
		int[] w = new int[n];
		for (int i = 0; i < n; i++) {
			w[i] = Integer.parseInt(st.nextToken());
		}

		int badsum = 0;
		int goodsum = 0;
		for (int i = 0; i < n; i++) {
			if (a[i] == 0) {
				badsum += w[i];
			}
			else {
				goodsum += w[i];
			}
		}

		//arr[i][j] = probability that after i steps, we have done exactly j removals of bad boys
		int[][] arr = new int[m+1][m+1];
		arr[0][0] = 1;
		for (int i = 1; i <= m; i++) {
			for (int j = 0; j <= i; j++) {
				if (j > 0) {
					int num1 = badsum-j+1;
					int denom1 = badsum+goodsum+i-2*j+1;
					if (num1 > 0) {
						arr[i][j] = multiply(arr[i-1][j-1], multiply(num1, inverse(denom1, mod), mod), mod);
					}
				}

				if (j < i) {
					int num2 = goodsum+(i-j-1);
					int denom2 = badsum+goodsum+i-2*j-1;
					if (num2 <= denom2) {
						arr[i][j] = (arr[i][j] + multiply(arr[i-1][j], multiply(num2, inverse(denom2, mod), mod), mod))%mod;
					}
				}
			}
		}

		//expected number of bad/good
		int eBad = badsum;
		for (int j = 0; j <= m; j++) {
			eBad += mod - multiply(j, arr[m][j], mod);
			eBad %= mod;
		}
		int eGood = goodsum + m + (eBad-badsum);
		if (eGood < 0) {
			eGood += mod;
		}
		eGood %= mod;

		//ans
		int[] r = new int[n];
		for (int i = 0; i < n; i++) {
			if (a[i] == 0) {
				r[i] = multiply(eBad, multiply(w[i], inverse(badsum, mod), mod), mod);
			}
			else {
				r[i] = multiply(eGood, multiply(w[i], inverse(goodsum, mod), mod), mod);
			}
			System.out.println(r[i] + " ");
		}
	}

	public static int multiply (int a, int b, int n) {
		long ab = (long) a * (long) b;
		return ((int) (ab%n));
	}

	public static int inverse (int a, int n) {
		int m = n;
		int r1 = 1;
		int r2 = 0;
		int r3 = 0;
		int r4 = 1;
		while ((a > 0) && (n > 0)) {
			if (n >= a) {
				r3 -= r1*(n/a);
				r4 -= r2*(n/a);
				n = n%a;
			}
			else {
				int tmp = a;
				a = n;
				n = tmp;
				tmp = r1;
				r1 = r3;
				r3 = tmp;
				tmp = r2;
				r2 = r4;
				r4 = tmp;
			}
		}
		if (a == 0) {
			if (r3 >= 0)
				return (r3%m);
			else
				return (m+(r3%m));
		}
		else {
			if (r1 >= 0)
				return (r1%m);
			else
				return (m+(r1%m));
		}

	}
}

