using namespace std;
int b[110];
int dp[110][110];
int n;
inline int ABS(int a) { return max(a, -a); }
int solve(int l, int r) {
  if (~dp[l][r]) return dp[l][r];
  if (l == r) return dp[l][r] = 0;
  int tmp[110];
  for (int i = 0; i < 110; i++) {
    tmp[i] = -99999999;
  }
  tmp[0] = 0;
  for (int i = 0; i < (r - l + n) % n; i++) {
    dp[l][(l + i) % n] = tmp[i];
    int t = ABS(b[l] - b[(l + i + 1) % n]);
    for (int j = 1; i + j <= (r - l + n) % n; j++) {
      tmp[i + j] =
          max(tmp[i + j], tmp[i] + t + solve((l + i + 1) % n, (l + i + j) % n));
    }
  }
  return dp[l][r] = tmp[(r - l + n) % n];
}
int main() {
