    n = a;
    int ret = 0;
    for (int i = 0; i < a; i++)
      for (int j = 0; j < a; j++) dp[i][j] = -1;
    for (int i = 0; i < a; i++) {
      ret = max(ret, solve(i, (i + a - 1) % a));
    }
    printf("%d\n", ret);
  }
}

