int transPossible(int type, int s, int e, int ttype, int tind) {
  if (trans[ttype].size() == tind) {
    if (s == e) return 1;
    return 0;
  }
  if (s >= e) return 0;
  if (e - s < (int)trans[ttype].size() - tind) return 0;
  int &ret = dp2[type][s][e][ttype][tind];
  if (ret != -1) return ret;
  ret = 0;
  if (inp[type][s] == trans[ttype][tind] &&
      transPossible(type, s + 1, e, ttype, tind + 1))
    ret = 1;
  int tar = trans[ttype][tind],
      shouldLeft = (int)trans[ttype].size() - tind - 1;
  for (int i = 0; i < transHash[tar].size(); i++) {
    int ntind = transHash[tar][i];
    for (int j = s + trans[ntind].size(); j <= e - shouldLeft; j++)
      if (transPossible(type, s, j, ntind, 0) &&
          transPossible(type, j, e, ttype, tind + 1))
        ret = 1;
  }
  return ret;
}
int getAns(int s1, int e1, int s2, int e2) {
  if (s1 == e1 && s2 == e2) return 0;
  if (s1 >= e1) return -2;
  if (s2 == e2) return -2;
  int &ret = dp[s1][e1][s2][e2];
  if (ret != -1) return ret;
  ret = -2;
  int v1 = inp[0][s1], v2 = inp[1][s2];
  int res;
  if (v1 == v2 && (res = getAns(s1 + 1, e1, s2 + 1, e2)) != -2)
    ret = max(ret, res + 1);
  for (int i = 0; i < reqLength[1][s2][v1].size(); i++) {
    int req = reqLength[1][s2][v1][i];
    if ((res = getAns(s1 + 1, e1, s2 + req, e2)) != -2) ret = max(ret, res + 1);
  }
  for (int i = 0; i < reqLength[0][s1][v2].size(); i++) {
    int req = reqLength[0][s1][v2][i];
    if ((res = getAns(s1 + req, e1, s2 + 1, e2)) != -2) ret = max(ret, res + 1);
  }
  for (int tv = 0; tv <= 30; tv++) {
    for (int i = 0; i < reqLength[0][s1][tv].size(); i++)
      for (int j = 0; j < reqLength[1][s2][tv].size(); j++) {
        int req1 = reqLength[0][s1][tv][i];
        int req2 = reqLength[1][s2][tv][j];
        if ((res = getAns(s1 + req1, e1, s2 + req2, e2)) != -2)
          ret = max(ret, res + 1);
      }
  }
  return ret;
}
