    if (a[i] == make_pair(pos, side)) return 0;
  return 1;
}
void add(int lev, int pos, int dir, int who, int ne, int nf, int ns) {
  tp[lev] = who;
  while (1) {
    if (fit(lev, pos, 1)) {
      a[lev] = make_pair(pos, 1);
      if (who == 0)
        go(lev + 1, ne - 1, nf, ns);
      else if (who == 1)
        go(lev + 1, ne, nf - 1, ns);
      else
        go(lev + 1, ne, nf, ns - 1);
      return;
    }
    if (fit(lev, pos, -1)) {
      a[lev] = make_pair(pos, -1);
      if (who == 0)
        go(lev + 1, ne - 1, nf, ns);
      else if (who == 1)
        go(lev + 1, ne, nf - 1, ns);
      else
        go(lev + 1, ne, nf, ns - 1);
      return;
    }
    pos += dir;
  }
}
void go(int lev, int ne, int nf, int ns) {
  if (!ne && !nf && !ns) {
    vector<pair<double, int> > ev(0);
    for (int i = 0; i < lev; ++i) {
      if (tp[i] == 0) {
        ev.push_back(make_pair(a[i].first - xe, -1));
        ev.push_back(make_pair(a[i].first + xe, 1));
