      add(lev, (int)floor(a[i].first + shift - xf), -1, 1, ne, nf, ns);
      add(lev, (int)ceil(a[i].first + shift - xf), +1, 1, ne, nf, ns);
    } else if (ns) {
      add(lev, (int)floor(a[i].first - shift + xs), -1, 2, ne, nf, ns);
      add(lev, (int)ceil(a[i].first - shift + xs), +1, 2, ne, nf, ns);
      add(lev, (int)floor(a[i].first + shift - xs), -1, 2, ne, nf, ns);
      add(lev, (int)ceil(a[i].first + shift - xs), +1, 2, ne, nf, ns);
