    }

    static long nextLong() {
        return Long.parseLong(nextToken());
    }

    static String nextLine() throws IOException {
        return br.readLine();
    }

    static char nextChar() throws IOException {
        return (char) br.read();
    }

    public static void main(String[] args) {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(System.out);
        run();
        pw.close();
    }

    static ArrayList<Integer> graf[];
    static int[] c;

    private static void run() {
        int n = nextInt();
        graf = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graf[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            int x = nextInt() - 1;
            int y = nextInt() - 1;
            graf[x].add(y);
            graf[y].add(x);
        }
        c = new int[n];
        for (int i = 0; i < n; i++) {
            c[i] = nextInt();
        }
        used = new boolean[n];
        dfs(0);
        if(!was){
            pw.println("YES");
            pw.print(1);
        }else if(was && tr){
            pw.println("YES");
            pw.print(ans + 1);
        }else {
            pw.print("NO");
        }
    }

    static boolean[] used;

    private static void dfs(int v) {
        if (used[v] || was) return;
        used[v] = true;
        for (int i = 0; i < graf[v].size() && !was; i++) {
            if (c[v] != c[graf[v].get(i)]) {
                was = true;
                tr = true;
                for (int j = 0; j < graf[v].size(); j++) {
                    dfs2(v, c[graf[v].get(j)], graf[v].get(j));
                }
                if (!tr) {
                    tr = true;
                    for (int j = 0; j < graf[graf[v].get(i)].size(); j++) {
                        dfs2(graf[v].get(i), c[graf[graf[v].get(i)].get(j)], graf[graf[v].get(i)].get(j));
                    }
                    if (tr) {
                        ans = graf[v].get(i);
                    }
                } else {
                    ans = v;
                }
            } else {
                dfs(graf[v].get(i));
            }
        }
    }

    private static void dfs2(int parent, int C, int v) {
        if (C != c[v]) tr = false;
        if (!tr) return;
        for (int i = 0; i < graf[v].size() && tr; i++) {
            if (graf[v].get(i) != parent) {
                dfs2(v, C, graf[v].get(i));
            }
        }
    }

    static boolean tr = false;
    static boolean was = false;
    static int ans = 0;
}

