const long long N = 2e3 + 36;
const long long INF = 1e18 + 7;
const long long MOD = 998244353;
mt19937 gen(19937);
long long open[N][N], close[N][N];
signed main() {
  cin.tie(0);
  cout.tie(0);
  ios_base::sync_with_stdio(0);
