  cin >> s;
  s = '0' + s;
  long long n = int(s.size());
  open[0][0] = 1;
  for (long long i(1); i < n; ++i) {
    for (long long j(0); j <= n; ++j) {
      if (s[i] == ')') {
        (open[i][j] += open[i - 1][j]) % MOD;
      }
      if (s[i] == '(') {
        if (j) (open[i][j] += open[i - 1][j - 1]) % MOD;
      }
      if (s[i] == '?') {
        (open[i][j] += open[i - 1][j]) % MOD;
        if (j) (open[i][j] += open[i - 1][j - 1]) % MOD;
      }
    }
  }
  close[n][0] = 1;
  for (long long i(n - 1); i >= 0; --i) {
    for (long long j(0); j <= n; ++j) {
      if (s[i] == ')') {
        if (j) (close[i][j] += close[i + 1][j - 1]) % MOD;
      }
      if (s[i] == '(') {
        (close[i][j] += close[i + 1][j]) % MOD;
      }
      if (s[i] == '?') {
        (close[i][j] += close[i + 1][j]) % MOD;
        if (j) (close[i][j] += close[i + 1][j - 1]) % MOD;
      }
    }
  }
  long long ans = 0;
  for (long long i = 1; i < n - 1; ++i) {
    for (long long j = 1; j <= n; ++j) {
      (ans += open[i][j] * 1LL * close[i + 1][j] % MOD * 1LL * j) %= MOD;
    }
  }
  cout << ans << '\n';
  return 0;
}

