    public void process()
    {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();

        int hist[] = new int[n];
        for (int i = 0; i < n; i++)
        {
            hist[i] = s.nextInt();
        }

        int cur = 0;
        Stack<RangePair> q = new Stack<RangePair>();
        ArrayList<RangePair> ans = new ArrayList<RangePair>();

        for (int i = 0; i < n; i++)
        {
            if (cur != hist[i])
            {
                if (cur < hist[i])
                {
                    for (int j = 0; j < hist[i] - cur; j++)
                    {
                        RangePair r = new RangePair(i, -1);
                        q.add(r);
                    }
                    cur = hist[i];
                }
                else
                {
                    for (int j = 0; j < cur - hist[i]; j++)
                    {
                        RangePair pair = q.pop();
                        pair.right = i-1;
                        ans.add(pair);
                    }
                    cur = hist[i];
                }
            }
        }

        while (!q.isEmpty())
        {
            RangePair p = q.pop();
            p.right = n-1;
            ans.add(p);
        }

        System.out.println(ans.size());
        for (int i = 0; i < ans.size(); i++)
        {
            RangePair curPair = ans.get(i);
