        if (!a && b && !c && !f && !o) y = d / b;
        if (!e && f && !g && !b && !o) y = h / f;
        if (!l && o && !p && !b && !f) y = q / o;
        if (!a && !b && c && !g && !p) z = d / c;
        if (!e && !f && g && !c && !p) z = h / g;
        if (!l && !o && p && !c && !g) z = q / p;
        if (x != -1) X = x;
        if (y != -1) Y = y;
        if (z != -1) Z = z;
      }
    }
  }
