long long sum[2111], sm[2111];
int main() {
  int i, j, k, cas;
  cin >> n >> m;
  memset((dp), 0, sizeof(dp));
  dp[0][0][0] = 1;
  for (i = 1; i <= n; i++) {
    dp[i][0][0] += dp[i - 1][0][0];
    memset((sum), 0, sizeof(sum));
    memset((sm), 0, sizeof(sm));
    for (j = 2; j <= m; j++) dp[i][j][0] += dp[i - 1][0][0];
    for (j = 0; j <= m; j++) {
      sum[j] = (dp[i - 1][j][0] + dp[i - 1][j][1]) * j * (-1LL);
      sum[j] %= mod;
      sum[j] += mod;
      sum[j] %= mod;
      sm[j] = (dp[i - 1][j][0] + dp[i - 1][j][1]);
      sm[j] %= mod;
    }
    for (j = 1; j <= m; j++) {
      sum[j] += sum[j - 1];
      sum[j] %= mod;
      sm[j] += sm[j - 1];
      sm[j] %= mod;
    }
    for (j = 2; j <= m; j++) {
      dp[i][j][0] += (sum[j - 1] - sum[1]);
      dp[i][j][0] %= mod;
      dp[i][j][0] += mod;
      dp[i][j][0] %= mod;
      dp[i][j][0] += (sm[j - 1] - sm[1]) * (j + 1LL);
      dp[i][j][0] %= mod;
      dp[i][j][0] += mod;
      dp[i][j][0] %= mod;
      dp[i][j][1] += dp[i - 1][j][0];
      dp[i][j][1] += dp[i - 1][j][1];
      dp[i][j][1] %= mod;
    }
  }
  long long ans = 0;
  for (i = 1; i <= n; i++) {
    memset((sum), 0, sizeof(sum));
    memset((sm), 0, sizeof(sm));
    for (j = 0; j <= m; j++) {
      sum[j] = (dp[n - i][j][0] + dp[n - i][j][1]) * j * (-1LL);
      sum[j] %= mod;
      sum[j] += mod;
      sum[j] %= mod;
      sm[j] = (dp[n - i][j][0] + dp[n - i][j][1]);
      sm[j] %= mod;
    }
    for (j = 1; j <= m; j++) {
      sum[j] += sum[j - 1];
      sum[j] %= mod;
      sm[j] += sm[j - 1];
      sm[j] %= mod;
    }
    for (j = 2; j <= m; j++) {
      long long tmp = 1;
      tmp += (sum[j] - sum[1]);
      tmp %= mod;
      tmp += mod;
      tmp %= mod;
      tmp += (sm[j] - sm[1]) * (j + 1LL);
      ans += (((dp[i][j][0] * tmp) % mod) * (m - j + 1LL)) % mod;
      ans %= mod;
    }
  }
  cout << ans << endl;
  return 0;
}

