vector<pair<int, pair<int, int>>> answer;
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, k, select_x, select_y, current_x, current_y, future_x, future_y;
  bool isnt = true;
  cin >> n >> k;
  for (int i = 1; i <= 4; i++)
    for (int j = 1; j <= n; j++) cin >> a[i][j];
  for (int i = 1; i <= n; i++)
    if (a[1][i] == a[2][i] || a[2][i] == 0 || a[3][i] == a[4][i] ||
        a[3][i] == 0)
      isnt = false;
  for (int i = 1; i <= k; i++) s.insert(i);
  if (isnt) {
    cout << -1;
    return 0;
  }
  while (!s.empty()) {
    for (int i = 1; i <= n; i++) {
      if (a[1][i] == a[2][i] && a[2][i] != 0) {
        answer.push_back(make_pair(a[2][i], make_pair(1, i)));
        s.erase(a[2][i]);
        a[2][i] = 0;
      }
      if (a[3][i] == a[4][i] && a[3][i] != 0) {
        answer.push_back(make_pair(a[3][i], make_pair(4, i)));
        s.erase(a[3][i]);
        a[3][i] = 0;
      }
      if (a[2][i] == 0) {
        select_x = 2;
        select_y = i;
      } else if (a[3][i] == 0) {
        select_x = 3;
        select_y = i;
      }
    }
    current_x = select_x;
    current_y = select_y;
    future_x = current_x;
    future_y = current_y;
    if (current_y == n && current_x == 3)
      future_x--;
    else if (current_y == 1 && current_x == 2)
      future_x++;
    else
      future_y += (current_x == 2 ? -1 : 1);
    while (future_x != select_x || future_y != select_y) {
      if (a[future_x][future_y] != 0)
        answer.push_back(
            make_pair(a[future_x][future_y], make_pair(current_x, current_y)));
      swap(a[current_x][current_y], a[future_x][future_y]);
      current_x = future_x;
      current_y = future_y;
      if (current_y == n && current_x == 3)
        future_x--;
      else if (current_y == 1 && current_x == 2)
        future_x++;
      else
        future_y += (current_x == 2 ? -1 : 1);
    }
  }
  cout << answer.size() << '\n';
  for (pair<int, pair<int, int>> i : answer)
    cout << i.first << ' ' << i.second.first << ' ' << i.second.second << '\n';
