  vector<vector<int> > dp(n, vector<int>(m, mod));
  for (int i = n - 1; i >= 0; i--) {
    for (int j = m - 1; j >= 0; j--) {
      if (a[i][j] == '#') {
        queue<pair<int, int> > q;
        q.push({i, j});
        int dx[2] = {+1, 0};
        int dy[2] = {0, +1};
        while (q.size()) {
          int x = q.front().first;
          int y = q.front().second;
          if (x == n - 1 and y == m - 1) {
            dp[i][j] = 1;
            break;
          }
          q.pop();
          for (int ii = 0; ii < 2; ii++) {
            int tox = x + dx[ii];
            int toy = y + dy[ii];
            if (tox < n and toy < m) {
              if (a[tox][toy] == '#') {
                q.push({tox, toy});
              } else {
                dp[i][j] = min(dp[i][j], dp[tox][toy] + 1);
              }
            }
          }
        }
      } else {
        if (i == n - 1 and j == m - 1) {
          dp[i][j] = 0;
        } else if (i == n - 1) {
          dp[i][j] = dp[i][j + 1];
        } else if (j == m - 1) {
          dp[i][j] = dp[i + 1][j];
        } else {
          dp[i][j] = min(dp[i + 1][j], dp[i][j + 1]);
        }
      }
    }
  }
  cout << dp[0][0] << '\n';
  time_taken();
  return 0;
}

