import java.io.*;
import java.util.*;

public class cowavans {
  static BufferedReader cin;
  static StringTokenizer tk;
  static int thresh = 400;
  public static void main (String [] args) throws IOException {
    init();
    int numCows = gInt();
    long [] weights = new long[numCows];
    for (int count = 0; count < numCows; count ++)
      weights[count] = gLong();
    int numQueries = gInt();
    Query [] queries = new Query[numQueries];
    for (int count = 0; count < numQueries; count ++)
      queries[count] = new Query(gInt() - 1, gInt());
    Query [] orig = queries.clone();
    Arrays.sort(queries);
    int prev = -1;
    long [] sums = new long[numCows];
    for (Query q : queries) {
      int a = q.a, b = q.b;
      if (b > thresh) {
        long ans = 0;
        for (int count = a; count < numCows; count += b)
          ans += weights[count];
        q.ans = ans;
      }
      else {
        if (b > prev) {
          prev = b;
          for (int count = 0; count < numCows; count ++)
            sums[count] = 0;
          for (int count = numCows - 1; count > -1; count --) {
            sums[count] += weights[count];
            int newPos = count + b;
            if (newPos < numCows)
              sums[count] += sums[newPos];
          }
        }
        q.ans = sums[a];
      }
    }
    for (Query q : orig)
      System.out.println(q.ans);
    exit();
  }
  public static void init () {
    cin = new BufferedReader(new InputStreamReader(System.in));
    tk = new StringTokenizer("");
  }
  public static void exit () throws IOException {
    System.out.flush();
    System.exit(0);
  }
  public static String token () throws IOException {
    while (!tk.hasMoreTokens())
      tk = new StringTokenizer(cin.readLine());
    return tk.nextToken();
  }
  public static int gInt () throws IOException {
    return Integer.parseInt(token());
  }
  public static long gLong () throws IOException {
    return Long.parseLong(token());
  }
  public static double gDouble () throws IOException {
    return Double.parseDouble(token());
  }
}

class Query implements Comparable <Query> {
  int a, b;
  long ans;
  Query (int x, int y) {
    a = x;
    b = y;
  }
  public int compareTo (Query other) {
    if (b < other.b)
      return -1;
    return 1;
  }
}

