typedef long long int lli;

struct St{
  St() {}
  St(map<lli, lli> _mpp): mpp(_mpp) {}
  map<lli, lli> mpp;

  bool check(lli key){
    return (mpp.find(key) != mpp.end());
  }
};

map<char, lli> ainfo;
map<char, St> minfo;

void setAry(string str)
{
  int p = 2, l =str.size()-1;
  string s = "";
  map<lli, lli> mp;

  while(p < l) s += str[p++];
  ainfo[str[0]] = atoll(s.c_str());
  minfo[str[0]] = St(mp);
}

lli getVal(string str)
{
  int p = 2;
  lli pt;
  char ch = str[0];

  if(ainfo.find(ch) == ainfo.end()) return -1;
  if(isalpha(str[p])){
    pt = getVal(str.substr(p));
    if(pt == -1) return -1;
  } else {
    string s = "";
    while(isdigit(str[p])) s += str[p++];
    pt = atoll(s.c_str());
  }

  if(ainfo[ch] <= pt) return -1;
  if(!minfo[ch].check(pt)) return -1;

  return minfo[ch].mpp[pt];
}

bool setVal(string str, lli v)
{
  int p = 2;
  lli pt;
  char ch = str[0];

  if(ainfo.find(ch) == ainfo.end()) return false;
  if(isalpha(str[p])){
    pt = getVal(str.substr(p));
    if(pt == -1) return false;
  } else {
    string s = "";
    while(isdigit(str[p])) s += str[p++];
    pt = atoll(s.c_str());
  }

  if(ainfo[ch] <= pt) return false;
  minfo[ch].mpp[pt] = v;

  return true;
}

int strfind(string str)
{
  int p = 0;
  for(; p < str.size() && str[p] != '='; ++p);

  return p;
}

int main()
{
  string str;
  int n, p;
  lli v;
  bool f;

  while(cin>>str && str != "."){
    n = 1;
    f = true;

    do {
      if(!f) continue;
      if((p=strfind(str)) == str.size()){
	setAry(str);
      } else {
	if(isalpha(str[p+1])){
	  if((v=getVal(str.substr(p+1))) == -1){
	    cout << n << endl;
	    f = false;
	    continue;
	  }
	} else {
	  v = atoll((str.substr(p+1)).c_str());
	}
	if(!setVal(str.substr(0, p-1), v)){
	  cout << n << endl;
	  f = false;
	  continue;
	}
      }

      ++n;
    } while(cin>>str && str != ".");

    if(f) cout << 0 << endl;
    ainfo.clear();
    minfo.clear();
  }

  return 0;
}

