			hana = new TreeSet<Integer>();
			//配る
			for (int i = 0; i < n; i++) {
				cards[Integer.parseInt(br.readLine())] = true;
			}
			for (int i = 1; i < cards.length; i++) {
				if (cards[i]) {
					taro.add(i);
