const int N = 200;
const int M = 1e6 + 5;
int rev[M], mp[N];
int bij[N][N];
int k, t;
int fact(int k) { return (k == 0) ? 1 : k * fact(k - 1); }
int comp(int a, int b) {
  a = mp[a], b = mp[b];
  vector<int> p1(k + 1), p2(k + 1);
  int cnt = 1;
  while (cnt <= k) {
    p1[k - cnt + 1] = a % 10;
    a /= 10;
    p2[k - cnt + 1] = b % 10;
    b /= 10;
    cnt++;
  }
  int c = 0;
  for (int i = 1; i < k + 1; i++) {
    c = c * 10 + p1[p2[i]];
  }
  return rev[c];
}
vector<int> reach;
int vis[200];
int count(int i) {
  if (vis[i]) return (int)reach.size();
  queue<int> q;
  q.push(i);
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    reach.push_back(v);
    vis[v] = 1;
    for (auto i : reach) {
      int k = bij[v][i];
      if (!vis[k]) {
        q.push(k);
        vis[k] = 1;
      }
    }
  }
  return (int)reach.size();
}
int solve() {
  int n;
  cin >> n >> k;
  t = fact(k);
  vector<int> p(k);
  for (int i = 0; i < k; i++) p[i] = i + 1;
  int cnt = 0;
  do {
    int c = 0;
    for (auto i : p) {
      c = c * 10 + i;
    }
    mp[++cnt] = c;
    rev[c] = cnt;
  } while (next_permutation(p.begin(), p.end()));
  for (int i = 1; i < t + 1; i++) {
    for (int j = 1; j < t + 1; j++) {
      bij[i][j] = comp(i, j);
    }
  }
  vector<int> last(t + 1, -1);
  long long ans = 0;
  set<pair<int, int> > aux;
  aux.insert({0, 0});
  auto solve = [&](int i) {
    int cur = 0;
    int last = i;
    for (auto i : aux) {
      ans += cur * (last + i.first);
      if (i.second == 0) break;
      if (cur < t) {
        cur = count(i.second);
      }
      last = -i.first;
    }
    memset(vis, 0, sizeof(vis));
    reach.clear();
  };
  for (int i = 1; i < n + 1; i++) {
    int c = 0;
    for (int j = 0; j < k; j++) {
      int t;
      cin >> t;
      c = c * 10 + t;
    }
    c = rev[c];
    aux.erase({-last[c], c});
    last[c] = i;
    aux.insert({-last[c], c});
    solve(-i);
  }
  cout << ans << "\n";
  return 0;
}
signed main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  int t = 1;
  while (t--) {
    solve();
  }
  return 0;
}

