int main() {
  cin >> n;
  for (int i = 0; i < n; i++) cin >> p[i], a[i] = 0.03 / n;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < i; j++) {
      double sa = a[i] + a[j], sp = p[i] + p[j];
      double pl = p[i] / sp * sa, pr = p[j] / sp * sa;
      if (pl < lim) pr -= lim - pl, pl = lim;
      if (pr < lim) pl -= lim - pr, pr = lim;
      a[i] = pl, a[j] = pr;
