    envelopes = list()
    add_envelope = envelopes.append
    for k in range(1, n + 1):
        w, h = map(int, input().split())
        if w > card_width and h > card_height:
            add_envelope((-w, h, k))

    if not envelopes:
        print(0)
        return

    envelopes.sort(reverse=True)
    available = len(envelopes)
    chosen = 0
    candidate = [0] * available
    order = [0] * available
    for k, (_, h, _) in enumerate(envelopes):
        position = bisect_left(order, h, hi=chosen)
        candidate[k] = position
        if position < chosen:
            order[position] = h
        else:
            order[chosen] = h
            chosen += 1

    chain = [""] * chosen
    chosen -= 1
    for k in range(available - 1, -1, -1):
        if candidate[k] == chosen:
            chain[chosen] = envelopes[k][2]
            chosen -= 1

    print(len(chain))
    if chain:
        print(" ".join(str(n) for n in chain))


