#include <bits/stdc++.h>
using namespace std;
long long n, m;
vector<long long> tree;
vector<long long> val;
vector<long long> mx;
void build(long long v, long long le, long long ri) {
  if (le + 1 == ri) {
    tree[v] = val[le];
    mx[v] = val[le];
    return;
  }
  long long m = (le + ri) / 2;
  build(2 * v + 1, le, m);
  build(2 * v + 2, m, ri);
  tree[v] = tree[2 * v + 1] + tree[2 * v + 2];
  mx[v] = max(mx[2 * v + 1], mx[2 * v + 2]);
}
long long get(long long v, long long le, long long ri, long long l,
              long long r) {
  if (l <= le && ri <= r) {
    return tree[v];
  }
  if (ri <= l || r <= le) {
    return 0;
  }
  long long m = (le + ri) / 2;
  return get(2 * v + 1, le, m, l, r) + get(2 * v + 2, m, ri, l, r);
}
void mod(long long v, long long le, long long ri, long long l, long long r,
         long long x) {
  if (le + 1 == ri) {
    tree[v] %= x;
    val[le] %= x;
    mx[v] = val[le];
    return;
  }
  if (l <= le && ri <= r && mx[v] >= x) {
    long long m = (le + ri) / 2;
    mod(2 * v + 1, le, m, l, r, x);
    mod(2 * v + 2, m, ri, l, r, x);
    mx[v] = max(mx[2 * v + 1], mx[2 * v + 2]);
    tree[v] = tree[2 * v + 1] + tree[2 * v + 2];
    return;
  }
  if (r <= le || ri <= l) {
    return;
  }
  long long m = (le + ri) / 2;
  mod(2 * v + 1, le, m, l, r, x);
  mod(2 * v + 2, m, ri, l, r, x);
  mx[v] = max(mx[2 * v + 1], mx[2 * v + 2]);
  tree[v] = tree[2 * v + 1] + tree[2 * v + 2];
}
void update(long long v, long long le, long long ri, long long ind,
            long long x) {
  if (le + 1 == ri) {
    tree[v] = x;
    val[le] = x;
    return;
  }
  long long m = (le + ri) / 2;
  if (ind < m) {
    update(2 * v + 1, le, m, ind, x);
  } else {
    update(2 * v + 2, m, ri, ind, x);
  }
  tree[v] = tree[2 * v + 1] + tree[2 * v + 2];
  mx[v] = max(mx[2 * v + 1], mx[2 * v + 2]);
}
signed main() {
  cin >> n >> m;
  val.resize(n);
  tree.resize(4 * n);
  mx.assign(4 * n, -1e10);
  for (auto &elem : val) {
    cin >> elem;
  }
  build(0, 0, n);
  while (m--) {
    long long t;
    cin >> t;
    if (t == 1) {
      long long l, r;
      cin >> l >> r;
      cout << get(0, 0, n, l - 1, r) << endl;
    }
    if (t == 2) {
      long long l, r, x;
      cin >> l >> r >> x;
      mod(0, 0, n, l - 1, r, x);
    }
    if (t == 3) {
      long long k, x;
      cin >> k >> x;
      update(0, 0, n, k - 1, x);
    }
  }
  return 0;
}

