ll nElems, mod;
vector<ll> elems, mods;
ll phi(ll n) {
  ll ret = n;
  for (ll p = 2; p * p <= n; p++) {
    if ((n % p) == 0) {
      while ((n % p) == 0) n /= p;
      ret -= ret / p;
    }
  }
  return (n > 1 ? ret - ret / n : ret);
}
ll modPow(ll base, ll exp, ll m) {
  ll ret = 1;
  base %= m;
  while (exp > 0) {
    if (exp & 1) ret = (ret * base) % m;
    base = (base * base) % m;
    exp >>= 1;
  }
  return ret % m;
}
ll tower(int begin, int end, int mi) {
  if (begin >= end || mi >= int((mods).size()) - 1) return 1;
  ll naive = 1;
  bool usePhi = false;
  int i = begin;
  while (i < end - 1 && i < begin + 5 && elems[i] != 1) i++;
  for (; i > begin; i--) {
    ll times = naive;
    naive = 1;
    if (elems[i] > 1) {
      for (int j = (0); j < (times); j++) {
        naive *= elems[i];
        if (naive >= 32) {
          usePhi = true;
          goto outLoop;
        }
      }
    }
  }
outLoop:;
  if (!usePhi) return modPow(elems[begin], naive, mods[mi]);
  ll p = tower(begin + 1, end, mi + 1);
  return modPow(elems[begin], mods[mi + 1] + (p % mods[mi + 1]), mods[mi]);
}
