struct node {
  int i;
  int j;
};
bool operator<(const node &a, const node &b) { return a.i + a.j < b.i + b.j; }
int64 encode(int a, int b) {
  int64 val = a;
  return (val << 32) | b;
}
inline bool is_visited(const node &a, unordered_set<int64> &st) {
  int64 val = encode(a.i, a.j);
  return st.find(val) != st.end();
}
inline void insert(const node &a, std::priority_queue<node> &q,
                   unordered_set<int64> &st) {
  int64 val = encode(a.i, a.j);
  q.push(a);
  st.insert(val);
}
inline bool is_reverse(char a, char b) {
