  pq.push(now);
  while (pq.size()) {
    now = pq.top();
    pq.pop();
    if (now.i == n && now.j == n) break;
    if (now.i < n) {
      if (path1[now.i] == path2[now.j]) {
        next.i = now.i + 1;
