void addfac(int* p, int* e, int x) {
  for (int i = 2; i * i <= x; ++i)
    if (x % i == 0) {
      p[++*p] = i;
      while (x % i == 0) e[i]++, x /= i;
    }
  if (x > 1) p[++*p] = x, e[x]++;
}
void dfs1(int x, long long num) {
  if (num > n) return;
  if (x > *ps) {
    ++ans;
    return;
  }
  for (int i = 0; i <= es[ps[x]]; ++i, num *= ps[x]) dfs1(x + 1, num);
}
void dfs2(int x, long long num, int d, int* B) {
  if (x > *B) {
    ans += m / num * d;
    return;
  }
  dfs2(x + 1, num, d, B);
  dfs2(x + 1, num * B[x], -d, B);
}
int main() {
  int qwq = gi();
  while (qwq--) {
    memset(pn, 0, sizeof pn);
    memset(ps, 0, sizeof ps);
    int n1 = gi(), n2 = gi(), n3 = gi();
    ans = 0;
    n = 1ll * n1 * n2 * n3;
    addfac(pn, en, n1);
    addfac(pn, en, n2);
    addfac(pn, en, n3);
    std::sort(pn + 1, pn + *pn + 1);
    *pn = std::unique(pn + 1, pn + *pn + 1) - pn - 1;
    int m1 = gi(), m2 = gi(), m3 = gi();
    m = 1ll * m1 * m2 * m3;
    int s1 = gi() * 2, s2 = gi(), s3 = gi();
    s = 1ll * s1 * s2 * s3;
    addfac(ps, es, s1);
    addfac(ps, es, s2);
    addfac(ps, es, s3);
    std::sort(ps + 1, ps + *ps + 1);
    *ps = std::unique(ps + 1, ps + *ps + 1) - ps - 1;
    dfs1(1, 1);
    int B[60] = {0};
    for (int i = 1; i <= *pn; ++i)
      if (en[pn[i]] > es[pn[i]]) {
        B[++*B] = 1;
        for (int j = 1; j <= es[pn[i]] + 1; ++j) B[*B] *= pn[i];
      }
    dfs2(1, 1, 1, B);
