long long dp[1 << 19][20];
long long xy[20][20];
long long a[20];
long long solve(long long prev, long long M, long long mask) {
  if (M == 0) return 0;
  long long &ret = dp[mask][prev];
  if (ret != -1) return ret;
  ret = 0;
  for (int i = 0; i < n; i++) {
    if ((mask & (1 << i)) == 0) {
      long long c = xy[prev][i] + a[i] + solve(i, M - 1, (mask | (1 << i)));
      ret = max(ret, c);
    }
  }
  return ret;
}
