using namespace std;
struct UF {
  map<int, int> p;
  map<int, int> edge;
  UF() {}
  void Init(int u) {
    if (p.count(u)) return;
    p[u] = u;
    edge[u] = 0;
  }
  int Find(int u) {
    if (p[u] == u) return u;
    int pu = p[u];
    int root = Find(pu);
    edge[u] ^= edge[pu];
    p[u] = p[pu];
    return root;
  }
  void Join(int u, int v, int x) {
    int pu = Find(u), pv = Find(v);
    if (pu == pv) return;
    p[pv] = pu;
    edge[pv] = x ^ edge[u] ^ edge[v];
  }
};
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  int q, t, l, r, x, last = 0;
  cin >> q;
  UF uf;
  while (q--) {
    cin >> t;
    if (t == 1) {
      cin >> l >> r >> x;
      l ^= last;
      r ^= last;
      x ^= last;
      if (l > r) swap(l, r);
      r++;
      uf.Init(l);
      uf.Init(r);
      uf.Join(l, r, x);
    } else {
      cin >> l >> r;
      l ^= last;
      r ^= last;
      if (l > r) swap(l, r);
      r++;
      uf.Init(l);
      uf.Init(r);
      if (uf.Find(l) != uf.Find(r)) {
        cout << -1 << endl;
        last = 1;
      } else {
        last = uf.edge[l] ^ uf.edge[r];
        cout << last << endl;
      }
    }
  }
  return 0;
}

