  long long int co = 0;
  while (n % 2 == 0) {
    co++;
    n = n / 2;
  }
  if (co > 0) v.push_back({2, co});
  for (long long int i = 3; i <= sqrt(n); i = i + 2) {
    co = 0;
    while (n % i == 0) {
      co++;
      n = n / i;
