int n, p, k;
const int MAX = 100005;
pair<int, int> a[MAX];
int s[MAX][7];
long long dp[MAX][(1 << 7) + 5];
bool cmp(pair<int, int> x, pair<int, int> y) { return x.first > y.first; }
void run(int cur, int state) {
  if (cur > n) return;
  int chosen = 0;
  for (int i = 0; i < p; i++) {
    if (state & (1 << i)) {
      chosen++;
    }
  }
  if (cur - 1 - chosen < k) {
    if (dp[cur - 1][state] + a[cur].first > dp[cur][state]) {
      dp[cur][state] = dp[cur - 1][state] + a[cur].first;
      run(cur + 1, state);
    }
  } else {
    if (dp[cur - 1][state] > dp[cur][state]) {
      dp[cur][state] = dp[cur - 1][state];
      run(cur + 1, state);
    }
  }
  int rind = a[cur].second;
  for (int i = 0; i < p; i++) {
    if ((state & (1 << i)) == 0) {
      int newstate = state ^ (1 << i);
      if (dp[cur - 1][state] + s[rind][i] > dp[cur][newstate]) {
        dp[cur][newstate] = dp[cur - 1][state] + s[rind][i];
        run(cur + 1, newstate);
      }
    }
  }
}
