int g = 400;
void solve() {
  int n, q;
  cin >> n >> q;
  vector<int> Next(n);
  vector<int> Prev(n);
  vector<int> Skip(n, -1);
  for (int i = 0; i < (n); ++i) {
    cin >> Next[i];
    Next[i]--;
    Prev[Next[i]] = i;
  }
  vector<int> ans;
  int SKIP = 0;
  while (q--) {
    if (BREAKTIME(3.9)) {
      cout << q << '\n';
      return;
    }
    int t;
    cin >> t;
    if (t == 1) {
      int a, b;
      cin >> a >> b;
      a--;
      b--;
      swap(Prev[Next[a]], Prev[Next[b]]);
      swap(Next[a], Next[b]);
      int x = a;
      for (int i = 0; i < (g + 10); ++i) {
        Skip[x] = -1;
        x = Prev[x];
      }
      x = b;
      for (int i = 0; i < (g + 10); ++i) {
        Skip[x] = -1;
        x = Prev[x];
      }
    } else {
      int a, k;
      cin >> a >> k;
      --a;
      int d = 0;
      int x = a;
      int y = a;
      while (k) {
        if (Skip[x] != -1 && k >= g) {
          x = Skip[x];
          k -= g;
          d += g;
        } else {
          x = Next[x];
          --k;
          d++;
        }
        while (d > g) {
          if (Skip[y] != -1 && d - g >= g) {
            y = Skip[y];
            d -= g;
          } else {
            y = Next[y];
            --d;
          }
        }
        if (d == g) {
          Skip[y] = x;
        }
      }
      ans.push_back(x + 1);
    }
  }
  for (auto x : ans) {
    cout << x << " ";
  }
  cout << '\n';
}
