private static void fill_right(int[] arr, int n, int[] right) {
	// TODO Auto-generated method stub
	Stack<Integer> s=new Stack<>();

	for(int i=0;i<n;i++)
	{
		while(!s.isEmpty()&&arr[i]<arr[s.peek()])
			right[s.pop()]=i;
		s.push(i);


	}
	while(!s.isEmpty())
		right[s.pop()]=n;

}

private static void fill_left(int[] arr, int n, int[] left) {
	// TODO Auto-generated method stub
	Stack<Integer> s=new Stack<>();

	for(int i=n-1;i>=0;i--)
	{
		while(!s.isEmpty()&&arr[i]<arr[s.peek()])
		{
			left[s.pop()]=i;
		}
		s.push(i);
	}
	while(!s.isEmpty())
		left[s.pop()]=-1;	

}

}

