    static long power(long x, long y, long p)
    {

        // Initialize result
        long res = 1;

        // Update x if it is more than or
        // equal to p
        x = x % p;

        while (y > 0) {

            // If y is odd, multiply x
            // with result
            if (y % 2 == 1)
                res = (res * x) % p;

            // y must be even now
            y = y >> 1; // y = y/2
            x = (x * x) % p;
        }

        return res;
    }

    // Returns n^(-1) mod p
    static long modInverse(int n, int p)
    {
        return power(n, p - 2, p);
    }

    // Returns nCr % p using Fermat's
    // little theorem.
    static long nCrModPFermat(long n, long r,
                             long p)
    {

        if (n<r)
            return 0;
        // Base case
        if (r == 0)
            return 1;

        int[] fac = new int[(int)(n + 1)];
        fac[0] = 1;

        for (int i = 1; i <= (int)n; i++)
            fac[i] = (int) ( fac[i - 1] * i % p);

        return (fac[(int)n] * modInverse(fac[(int)r], (int) p)
                % p * modInverse(fac[(int) (n - r)], (int) p)
                % p)
                % p;
    }
