const long long int mxN = 1000;
const long long int mxT = 1e5;
long long int n, m, t;
string mat[mxN];
long long int query[mxT][3];
void Input() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  ;
  cin >> n >> m >> t;
  for (long long int i = 0; i < n; i++) cin >> mat[i];
  for (long long int i = 0; i < t; i++)
    for (long long int j = 0; j < 3; j++) cin >> query[i][j];
}
void Solve() {
  long long int off_y[4] = {0, 0, 1, -1};
  long long int off_x[4] = {1, -1, 0, 0};
  bool b_mat[n][m];
  for (long long int i = 0; i < n; i++) {
    for (long long int j = 0; j < m; j++) {
      b_mat[i][j] = 0;
      for (long long int k = 0; k < 4; k++) {
        long long int new_y = i + off_y[k];
        long long int new_x = j + off_x[k];
        if (new_x < 0 || new_x >= m) continue;
        if (new_y < 0 || new_y >= n) continue;
        if (mat[new_y][new_x] == mat[i][j]) {
          b_mat[i][j] = 1;
          break;
        }
      }
    }
  }
  long long int D[n][m];
  for (long long int i = 0; i < n; i++)
    for (long long int j = 0; j < m; j++) D[i][j] = 1e9;
  queue<pair<long long int, long long int> > q;
  for (long long int i = 0; i < n; i++) {
    for (long long int j = 0; j < m; j++) {
      if (b_mat[i][j]) q.push({i, j}), D[i][j] = 0;
    }
  }
  while (!q.empty()) {
    long long int second = q.front().first;
    long long int first = q.front().second;
    q.pop();
    for (long long int k = 0; k < 4; k++) {
      long long int new_y = second + off_y[k];
      long long int new_x = first + off_x[k];
      if (new_x < 0 || new_x >= m) continue;
      if (new_y < 0 || new_y >= n) continue;
      if (D[new_y][new_x] > D[second][first] + 1) {
        D[new_y][new_x] = D[second][first] + 1;
        q.push({new_y, new_x});
      }
    }
  }
  for (long long int i = 0; i < t; i++) {
    long long int second, first, p;
    second = query[i][0];
    first = query[i][1];
    p = query[i][2];
    second--;
    first--;
    if (D[second][first] + 1 >= p)
      cout << mat[second][first] << "\n";
    else if (mat[second][first] == '0')
      cout << (p - D[second][first]) % 2 << "\n";
    else
      cout << 1 - ((p - D[second][first]) % 2) << "\n";
  }
}
int main() {
  Input();
  Solve();
}

