void dfs(long long v, long long p, long long &k) {
  vis[v] = true;
  ord[v] = k++;
  low[v] = ord[v];
  for (long long i = 0; i < G[v].size(); i++) {
    if (!vis[G[v][i]]) {
      dfs(G[v][i], v, k);
      low[v] = min(low[v], low[G[v][i]]);
      if (ord[v] < low[G[v][i]])
        bridge.push_back(make_pair(min(v, G[v][i]), max(v, G[v][i])));
    } else if (G[v][i] != p) {
      low[v] = min(low[v], ord[G[v][i]]);
    }
  }
}
