    else {
      t3 = (t3 <= seglo[j][t2] ? t3 : seglo[j][t2]);
      t4 = (t4 >= seghi[j][t2] ? t4 : seghi[j][t2]);
      t2 = t2 / 2 - 1;
    }
  }
  if (t1 == t2) {
    t3 = (t3 <= seglo[j][t1] ? t3 : seglo[j][t1]);
