  Line(Point &p, Point &q)
      : A(q.y - p.y), B(p.x - q.x), C(p.y * q.x - p.x * q.y) {}
};
inline Point operator+(const Point &a, const Point &b) {
  return Point(a.x + b.x, a.y + b.y);
}
inline Point operator-(const Point &a, const Point &b) {
  return Point(a.x - b.x, a.y - b.y);
}
