public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        MaximDiscount solver = new MaximDiscount();
        solver.solve(1, in, out);
        out.close();
    }

    static class MaximDiscount {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int m = in.nextInt();
            int q[] = new int[m];

            for (int i = 0; i < m; i++) {
                q[i] = in.nextInt();
            }

            int n = in.nextInt();
            ArrayList<Integer> arr = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                arr.add(in.nextInt());
            }

            Collections.sort(arr, Collections.reverseOrder());


            int rem = 0;
            long cost = 0;

            while (rem != n) {
                for (int i = 0; i < m; i++) {
                    int k = q[i];

                    for (int j = 0; j < k; j++) {
                        if (arr.size() > 0) {
                            int val = arr.remove(0);
                            cost += val;
                            rem++;
                        } else {
                            break;
                        }
                    }


                    int temp = 0;
                    while (rem < n && temp < 2 && arr.size() > 0) {
                        int val = arr.remove(0);
                        rem++;
                        temp++;
                    }

                    if (rem == n) {
                        break;
                    }

                }
            }

            out.println(cost);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
