class BIT {

    public int n;
    public long[] bit;

    public BIT(int n){
        this.n = n;
        bit = new long[n+1];
    }

    public long sum(int i){
        long s = 0L;
        while(0 < i){
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    public void add(int i, int x){
        while(i <= n){
            bit[i] += x;
            i += i & -i;
        }
    }

}

