          dp[i][j] =
              ((dp[i][j] + 2 * dp[i + 1][j - 1]) % mod + gh[pq[i + 1][j - 1]]) %
              mod;
          dp[i][j] = (dp[i][j] + dp[i][j - 1]) % mod;
          dp[i][j] = (dp[i][j] + dp[i + 1][j]) % mod;
        }
      } else if (op[i] == '?') {
        if (j == i + 1 && op[j] == ')')
          dp[i][j] = 1;
        else if (j > i + 1) {
          if (op[j] == ')') {
            dp[i][j] = (dp[i][j] + dp[i + 1][j - 1] + gh[pq[i + 1][j - 1]] +
                        dp[i + 1][j]) %
                       mod;
          } else {
            dp[i][j] = (dp[i][j] + dp[i + 1][j - 1] + dp[i][j - 1]) % mod;
          }
        }
      } else if (op[j] == '?') {
        if (j == i + 1 && op[i] == '(')
