            dp[i][j] = (dp[i][j] + dp[i + 1][j - 1] + gh[pq[i + 1][j - 1]] +
                        dp[i][j - 1]) %
                       mod;
          } else {
            dp[i][j] = (dp[i][j] + dp[i + 1][j - 1] + dp[i + 1][j]) % mod;
          }
        }
      } else {
        if (j == i + 1 && op[i] == '(' && op[j] == ')')
          dp[i][j] = 1;
        else if (j > i + 1) {
          if (op[i] == '(' && op[j] == ')')
            dp[i][j] = (dp[i + 1][j - 1] + gh[pq[i + 1][j - 1]]) % mod;
          else if (op[i] == '(')
            dp[i][j] = dp[i][j - 1];
          else if (op[j] == ')')
            dp[i][j] = dp[i + 1][j];
          else
            dp[i][j] = dp[i + 1][j - 1];
        }
      }
