	public int[] getDigits(int i){
		int[] ret = new int[4];
		ret[3] = i % 10;
		i = i / 10;
		ret[2] = i % 10;
		i = i / 10;
		ret[1] = i % 10;
		ret[0] = i / 10;
		return ret;
	}

	private int[] match(int[] par, int[] guess){
		int[] ret = {0, 0};
		for(int i=0;i<par.length;i++) if(guess[i]==par[i]) ret[0] += 1;
		int[] count1 = new int[10], count2 = new int[10];
		Arrays.fill(count1, 0);
		Arrays.fill(count2, 0);
		for(int i=0;i<par.length;i++){
			count1[par[i]] += 1;
			count2[guess[i]] += 1;
		}
		for(int i=0;i<10;i++){
			ret[1] += Math.min(count1[i], count2[i]);
		}
		ret[1] -= ret[0];
		return ret;
	}

