  void set(int lf, int rr, int qq) { r = rr, l = lf, q = qq; }
} op[(100000 + 20)];
void update(int idx, int st, int ed, int s, int e, int val) {
  if (st == s && ed == e) {
    ans[idx] |= val;
    return;
  }
  int mid = (st + ed) / 2;
  if (mid >= e)
    update((idx << 1), st, mid, s, e, val);
  else if (mid < s) {
    update((idx << 1) + 1, mid + 1, ed, s, e, val);
  } else {
    update((idx << 1), st, mid, s, mid, val);
    update((idx << 1) + 1, mid + 1, ed, mid + 1, e, val);
  }
  ans[idx] = ans[(idx << 1)] & ans[(idx << 1) + 1];
  return;
}
void build(int idx, int st, int ed, int val) {
  if (st == ed) {
    ans[idx] |= val;
    return;
  }
  int mid = (st + ed) / 2;
  build(2 * idx, st, mid, val | ans[idx]);
  build(2 * idx + 1, mid + 1, ed, val | ans[idx]);
  ans[idx] = ans[2 * idx] & ans[2 * idx + 1];
}
int query(int idx, int st, int ed, int s, int e) {
  if (st == s && ed == e) {
    return ans[idx];
  }
  int ret;
  int mid = (st + ed) / 2;
  if (mid >= e) {
    return query((idx << 1), st, mid, s, e);
  } else if (s > mid) {
    return query((idx << 1) + 1, mid + 1, ed, s, e);
  } else {
    int r1 = query((idx << 1), st, mid, s, mid);
    int r2 = query((idx << 1) + 1, mid + 1, ed, mid + 1, e);
    ret = r1 & r2;
  }
  return ret;
}
