using namespace std;
const long long oo = 2000000000000000000LL + 1;
struct node {
  node *l, *r;
  long long sum;
  long long min_sum;
  node() : l(0), r(0), sum(0), min_sum(0) {}
};
long long get_sum(node* u) { return u ? u->sum : 0; }
long long get_min_sum(node* u) { return u ? u->min_sum : 0; }
void update(node* u, int b, int e, int x, long long v) {
  if (b + 1 == e) {
    u->sum = v;
    u->min_sum = min(0LL, v);
  } else {
    int m = (b + e) / 2;
    if (x < m) {
      if (u->l == nullptr) u->l = new node();
      update(u->l, b, m, x, v);
    } else {
      if (u->r == nullptr) u->r = new node();
      update(u->r, m, e, x, v);
    }
    u->sum = get_sum(u->l) + get_sum(u->r);
    u->min_sum = min(get_min_sum(u->l), get_sum(u->l) + get_min_sum(u->r));
  }
}
int find(node* u, int b, int e, int x, int y, long long& v) {
  if (x <= b && e <= y) {
    if (u->min_sum + v > 0) {
      v += u->sum;
      return -1;
    } else {
      if (b + 1 == e) {
        return b;
      } else {
        int m = (b + e) / 2;
        if (get_min_sum(u->l) + v <= 0)
          return find(u->l, b, m, x, y, v);
        else {
          v += get_sum(u->l);
          return find(u->r, m, e, x, y, v);
        }
      }
    }
  } else {
    int m = (b + e) / 2;
    if (x < m && u->l) {
      auto r = find(u->l, b, m, x, y, v);
      if (r >= 0) return r;
    }
    if (m < y && u->r) {
      auto r = find(u->r, m, e, x, y, v);
      if (r >= 0) return r;
    }
    return -1;
  }
}
class ESashaAndAPatientFriend {
 public:
  void solve(std::istream& in, std::ostream& out) {
    const int R = 1000000002;
    out.precision(10);
    auto root = new node();
    int q;
    in >> q;
    set<long long> active;
    map<long long, long long> speed;
    auto add = [&](long long p, long long s) {
      auto it = active.lower_bound(p);
      if (it != active.end()) {
        auto nxt = it;
        ++nxt;
        update(root, 1, R, p, s * (*nxt - p));
      } else if (s < 0) {
        update(root, 1, R, p, -oo);
      }
      if (it != active.begin()) {
        auto prev = it;
        --prev;
        update(root, 1, R, *prev, speed[*prev] * (p - *prev));
      }
      active.insert(p);
      speed[p] = s;
    };
    auto remove = [&](long long p) {
      update(root, 1, R, p, 0);
      auto it = active.lower_bound(p);
      assert(*it == p);
      if (it != active.begin()) {
        auto prev = it;
        --prev;
        if (it != active.end()) {
          auto nxt = it;
          ++nxt;
          update(root, 1, R, *prev, speed[*prev] * (*nxt - *prev));
        } else {
          if (speed[*prev] < 0) {
            update(root, 1, R, *prev, -oo);
          } else {
            update(root, 1, R, *prev, 0);
          }
        }
      }
      speed.erase(p);
      active.erase(p);
    };
    while (q-- > 0) {
      int t;
      in >> t;
      if (t == 1) {
        long long p, s;
        in >> p >> s;
        add(p, s);
      } else if (t == 2) {
        long long p;
        in >> p;
        remove(p);
      } else {
        long long l, r, v;
        in >> l >> r >> v;
        if (v == 0) {
          out << l << '\n';
          continue;
        }
        bool added = false;
        auto it = active.lower_bound(r);
        if (it == active.end() || *it != r) {
          added = true;
          add(r, 0);
        }
        auto x = find(root, 1, R, l, r, v);
        if (x == -1) {
          out << -1 << '\n';
        } else {
          auto s = speed[x];
          long double ans = -1. * v / s + x;
          out << fixed << ans << '\n';
        }
        if (added) {
          remove(r);
        }
      }
    }
  }
};
int main() {
  ESashaAndAPatientFriend solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 7;
int n, m, a[N];
struct Data {
  int x, y, u, k;
  Data(int _x = 0, int _y = 0, int _u = 0, int _k = 0) {
    x = _x;
    y = _y;
    u = _u;
    k = _k;
  }
  bool operator<(const Data &oth) const { return x < oth.x; }
};
struct SegmentTree {
  vector<Data> d[N * 4];
  void build(int id, int l, int r) {
    if (l == r) {
      int mid = (a[l + 1] - a[l]) % l;
      int k = (a[l + 1] - a[l] + l - 1) / l;
      int u = a[l] + l * k - a[l + 1];
      if (mid == 0) {
        d[id].push_back(Data(0, l - 1, u, k));
      } else {
        d[id].push_back(Data(0, mid - 1, u, k));
        d[id].push_back(Data(mid, l - 1, 0, k - 1));
      }
      return;
    }
    int mid = (l + r) >> 1;
    build(id << 1, l, mid);
    build(id << 1 | 1, mid + 1, r);
    int cur = 0;
    for (Data dat : d[id << 1])
      while (cur <= dat.y) {
        int x = cur;
        int nX = dat.u + (x - dat.x);
        Data nxt = *(--upper_bound(d[id << 1 | 1].begin(), d[id << 1 | 1].end(),
                                   Data(nX)));
        int u = nxt.u + (nX - nxt.x);
        int y = x + min(dat.y - x, nxt.y - nX);
        int k = dat.k + nxt.k;
        d[id].push_back(Data(x, y, u, k));
        cur = y + 1;
      }
  }
  void go(int id, int l, int r, int &x, int &k) {
    if (x < a[l] || a[r + 1] <= x) return;
    if (a[l] <= x && x < a[l] + l) {
      int curX = x - a[l];
      assert(curX < l);
      Data dat = *(--upper_bound(d[id].begin(), d[id].end(), Data(curX)));
      if (k >= dat.k) {
        k -= dat.k;
        x = a[r + 1] + dat.u + (curX - dat.x);
        return;
      }
    }
    if (l == r) return;
    int mid = (l + r) >> 1;
    go(id << 1, l, mid, x, k);
    go(id << 1 | 1, mid + 1, r, x, k);
  }
} ST;
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> m;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
    a[i] -= i - 1;
  }
  if (n > 1) ST.build(1, 1, n - 1);
  while (m--) {
    int x, k;
    cin >> x >> k;
    if (x < a[1]) {
      cout << x << '\n';
      continue;
    }
    if (a[n] <= x) {
      cout << x + (long long)n * k << '\n';
      continue;
    }
    int p = upper_bound(a + 1, a + 1 + n, x) - a - 1;
    int c = min(k, (a[p + 1] - x + p - 1) / p);
    x += c * p;
    k -= c;
    if (k == 0) {
      cout << x << '\n';
      continue;
    }
    ST.go(1, 1, n - 1, x, k);
    p = upper_bound(a + 1, a + 1 + n, x) - a - 1;
    cout << x + (long long)k * p << '\n';
  }
  return 0;
}

