const long long MOD = 1000000007;
int n;
int a[int(1e5) + 10];
long long q[int(1e6) + 10];
long long t[4 * int(1e6) + 10];
void update(int v, int l, int r, int pos, long long value) {
  if (l > r) return;
  if (l == r) {
    t[v] = value;
    return;
  }
  int middle = (l + r) / 2;
  if (pos <= middle)
    update(2 * v, l, middle, pos, value);
  else
    update(2 * v + 1, middle + 1, r, pos, value);
  t[v] = t[2 * v] + t[2 * v + 1];
}
long long sum(int v, int tl, int tr, int l, int r) {
  if (tl > tr || l > r) return 0;
  if (tl == l && tr == r) return t[v];
  int middle = (tl + tr) / 2;
  return sum(2 * v, tl, middle, l, min(middle, r)) +
         sum(2 * v + 1, middle + 1, tr, max(l, middle + 1), r);
}
void task() {
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    q[x] = sum(1, 1, int(1e6), 1, x) * (long long)x + x;
    q[x] %= MOD;
    update(1, 1, int(1e6), x, q[x]);
  }
  long long ans = 0;
  for (int i = 0; i <= int(1e6); ++i) ans += q[i];
  cout << ans % MOD;
}
