def linear_seive(n):
    is_composite = [False] * n
    is_composite[0] = is_composite[1] = True
    primes = []

    for i in range(2, n):
        if is_composite[i] == False:
            primes.append(i)
        j = 0
        while j < len(primes) and i * primes[j] < n:
            is_composite[i * primes[j]] = True
            if i % primes[j] == 0:
                break
            j += 1

    return primes

