pair<long long int, long long int> dfs(int node) {
  vis[node] = 1;
  long long int pos = 0;
  long long int neg = 0;
  for (long long int i = 0; i < gr[node].size(); i++) {
    if (vis[gr[node][i]]) continue;
    pair<long long int, long long int> temp = dfs(gr[node][i]);
    pos = max(pos, temp.first);
    neg = min(neg, temp.second);
  }
  long long int rem = val[node] - (pos + neg);
  if (rem > 0)
    return {pos + rem, neg};
  else
    return {pos, neg + rem};
}
