const int N = 401000;
vector<int> A, Ans, B;
namespace PAM {
struct Node {
  unordered_map<int, int> ch;
  int len, fail;
} T[N];
int tot, lst;
void Init(void) {
  T[tot = lst = 1].len = -1;
  T[0].len = 0;
  T[0].fail = 1;
}
int Insert(int pos, int val) {
  while (B[pos - T[lst].len - 1] != B[pos]) {
    lst = T[lst].fail;
  }
  if (T[lst].ch.find(val) == T[lst].ch.end()) {
    T[++tot].len = T[lst].len + 2;
    int cur = T[lst].fail;
    while (B[pos - T[cur].len - 1] != B[pos]) {
      cur = T[cur].fail;
    }
    T[tot].fail = T[cur].ch[val];
    T[lst].ch[val] = tot;
  }
  lst = T[lst].ch[val];
  return T[lst].len;
}
}  // namespace PAM
