vector<pair<int, int>> edge[N];
vector<tuple<int, int, int>> rev[N];
bool good[N], done[N];
void dfs(int now) {
  if (done[now]) return;
  done[now] = 1;
  for (auto it : rev[now]) {
    int to, cost, id;
    tie(to, cost, id) = it;
    if (d[to] + cost == d[now]) {
      good[id] = 1;
      dfs(to);
    }
  }
}
int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < m; i++) {
    scanf("%d %d %d", u + i, v + i, w + i);
    edge[u[i]].emplace_back(v[i], w[i]);
    rev[v[i]].emplace_back(u[i], w[i], i);
  }
  fill(d, d + N, inf);
  d[1] = 0;
  priority_queue<pair<long long, int>> pq;
  pq.emplace(-d[1], 1);
  while (!pq.empty()) {
    long long cost;
    int now;
    tie(cost, now) = pq.top();
    pq.pop();
    cost = -cost;
    if (d[now] != cost) continue;
    for (auto it : edge[now]) {
      long long ncos = cost + it.second;
      int near = it.first;
      if (ncos < d[near]) {
        d[near] = ncos;
        pq.emplace(-d[near], near);
      }
    }
  }
  dfs(2);
  for (int i = 0; i < m; i++) {
