int main() {
  int n, m, k;
  std::cin >> n >> m >> k;
  std::vector<Node> v(m);
  for (int i = 0; i < m; ++i) {
    std::cin >> v[i].a >> v[i].b >> v[i].c;
    v[i].i = i + 1;
  }
  std::sort(v.begin(), v.end());
  memset(dp, -1, sizeof(dp));
  memset(parent, -1, sizeof(dp));
  for (int i = 0; i < m; ++i) {
    for (int j = 0; j <= v[i].b - v[i].a; ++j) {
      dp[i][j][0] = v[i].a + j;
    }
  }
  for (int z = 0; z < n - 1; ++z) {
    for (int i = 0; i < m; ++i) {
      for (int j = 0; j <= v[i].b - v[i].a; ++j) {
        for (int l = i + 1; l < m; ++l) {
          if (v[i].c == v[l].c || dp[i][j][z] == -1) {
            continue;
          }
          long long add = v[i].a + j + k;
          if (v[l].a <= add && add <= v[l].b) {
            dp[l][add - v[l].a][z + 1] = dp[i][j][z] + add;
            parent[l][add - v[l].a][z + 1] =
                std::make_pair(i, std::make_pair(j, z));
          }
          long long mult = (v[i].a + j) * k;
          if (v[l].a <= mult && mult <= v[l].b) {
            dp[l][mult - v[l].a][z + 1] = dp[i][j][z] + mult;
            parent[l][mult - v[l].a][z + 1] =
                std::make_pair(i, std::make_pair(j, z));
          }
        }
      }
    }
  }
  long long res = -1;
  std::pair<int, std::pair<int, int> > p;
  for (int i = 0; i < m; ++i) {
    for (int j = 0; j <= v[i].b - v[i].a; ++j) {
      if (res < dp[i][j][n - 1]) {
        res = dp[i][j][n - 1];
        p = std::make_pair(i, std::make_pair(j, n - 1));
      }
    }
  }
  if (res == -1) {
    std::cout << "NO" << std::endl;
  } else {
    std::cout << "YES" << std::endl;
    std::stack<std::pair<int, long long> > s;
    while (p.first != -1) {
      s.push(std::make_pair(v[p.first].i, p.second.first + v[p.first].a));
      p = parent[p.first][p.second.first][p.second.second];
    }
    while (!s.empty()) {
      std::cout << s.top().first << " " << s.top().second << std::endl;
      s.pop();
    }
  }
}

