#include <bits/stdc++.h>
using namespace std;
typedef const complex<double> &refpoint;
inline vector<complex<double> > intersect(refpoint p1, double r1, refpoint p2,
                                          double r2) {
  double d = abs(p2 - p1);
  double phi = arg(p2 - p1);
  vector<complex<double> > ret;
  double costheta = (d * d + r1 * r1 - r2 * r2) / (2.0 * d * r1);
  if (abs(costheta) > 1.0) {
    return ret;
  }
  double theta = acos(costheta);
  ret.resize(2);
  ret[0] = p1 + polar(r1, phi + theta);
  ret[1] = p1 + polar(r1, phi - theta);
  if (ret[0] == ret[1]) ret.resize(1);
  return ret;
}
int main() {
  const double pi = acos(-1.0);
  const double EPS = 1e-5;
  int n;
  for (; scanf("%d", &n), n != 0;) {
    vector<complex<double> > pt(n);
    vector<double> r(n);
    double x, y;
    for (int i = 0; i < n; ++i) {
      scanf("%lf%lf%lf", &x, &y, &r[i]);
      pt[i] = complex<double>(x, y);
    }
    vector<vector<double> > intrs(n);
    for (int i = 0; i < n; ++i) {
      for (int j = i + 1; j < n; ++j) {
        vector<complex<double> > ret = intersect(pt[i], r[i], pt[j], r[j]);
        if (ret.size() == 2) {
          for (int k = 0; k < 2; ++k) {
            intrs[i].push_back(arg(ret[k] - pt[i]));
            intrs[j].push_back(arg(ret[k] - pt[j]));
          }
        }
      }
    }
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
      vector<double> &ci = intrs[i];
      if (ci.size() == 0) {
        int cnt = 0;
        complex<double> check = pt[i] + r[i];
        for (int j = 0; j < n; ++j) {
          if (norm(pt[j] - check) < r[j] * r[j] + EPS) {
            ++cnt;
          }
        }
        if (cnt <= 1) {
          sum += 2.0 * pi * r[i];
        }
      } else {
        sort(ci.begin(), ci.end());
        for (int cur = 0; cur < ci.size(); ++cur) {
          complex<double> check;
          double len;
          if (cur + 1 != ci.size()) {
            check = pt[i] + polar(r[i], (ci[cur] + ci[cur + 1]) * 0.5);
            len = r[i] * (ci[cur + 1] - ci[cur]);
          } else {
            check = pt[i] + polar(r[i], (ci[cur] + ci[0]) * 0.5 + pi);
            len = r[i] * (ci[0] + 2.0 * pi - ci[cur]);
          }
          int cnt = 0;
          for (int j = 0; j < n; ++j) {
            if (norm(check - pt[j]) < r[j] * r[j] + EPS) {
              ++cnt;
            }
          }
          if (cnt <= 1) {
            sum += len;
          }
        }
      }
    }
    printf("%.10f\n", sum);
  }
}

