long long dp[N][1 << N];
long long solve(int cnt, int subset, int prev) {
  if (cnt == m) return 0LL;
  long long &ret = dp[prev][subset];
  if (ret == -1) {
    for (int i = 0; i < n; ++i) {
      if (subset & (1 << i)) continue;
      ret = max(ret, solve(cnt + 1, subset | (1 << i), i + 1) + a[i + 1] +
                         c[prev][i + 1]);
    }
  }
  return ret;
}
