inline int Fp(int x, int k) {
  int ans = 1;
  for (; k; k >>= 1, x = 1ll * x * x % Mod)
    if (k & 1) ans = 1ll * ans * x % Mod;
  return ans;
}
inline void add(int& x, int y) { x += y, x >= Mod ? x -= Mod : 0; }
inline void sub(int& x, int y) { x -= y, x < 0 ? x += Mod : 0; }
