              dy[8] = {1, 0, 0, -1, -1, -1, 1, 1};
struct Rerooting {
  struct DP {
    long long dp;
    DP(long long dp_) : dp(dp_) {}
  };
  const DP identity = DP(0);
  function<DP(DP, DP)> merge_add = [](DP dp_cum, DP d) -> DP {
    return DP(dp_cum.dp + d.dp);
  };
  function<DP(DP, DP)> merge_max = [](DP dp_cum, DP d) -> DP {
    return DP(max(dp_cum.dp, d.dp));
  };
  function<DP(DP)> add_root = [](DP d) -> DP { return DP(d.dp + 1); };
  struct Edge {
    int to;
  };
  using Graph = vector<vector<Edge>>;
  vector<vector<DP>> dp;
  vector<DP> ans;
  Graph G;
  Rerooting(int N) : G(N) {
    dp.resize(N);
    ans.assign(N, identity);
  }
  void add_edge(int a, int b) { G[a].push_back({b}); }
  void build() {
    dfs(0);
    bfs(0, identity);
  }
  DP dfs(int v, int p = -1) {
    DP dp_cum = identity;
    int deg = G[v].size();
    dp[v] = vector<DP>(deg, identity);
    for (int i = 0; i < deg; i++) {
      int u = G[v][i].to;
      if (u == p) continue;
      dp[v][i] = dfs(u, v);
      dp_cum = merge_add(dp_cum, dp[v][i]);
    }
    return add_root(dp_cum);
  }
  void bfs(int v, const DP& dp_p, int p = -1) {
    int deg = G[v].size();
    for (int i = 0; i < deg; i++) {
      if (G[v][i].to == p) dp[v][i] = dp_p;
    }
    vector<DP> dp_l(deg + 1, identity), dp_r(deg + 1, identity);
    DP tmp = dp_p;
    for (int i = 0; i < deg; i++) {
      dp_l[i + 1] = merge_add(dp_l[i], dp[v][i]);
      tmp = merge_max(tmp, dp[v][i]);
    }
    for (int i = deg - 1; i >= 0; i--) {
      dp_r[i] = merge_add(dp_r[i + 1], dp[v][i]);
    }
    ans[v] = tmp;
    for (int i = 0; i < deg; i++) {
      int u = G[v][i].to;
      if (u == p) continue;
      bfs(u, add_root(merge_add(dp_l[i], dp_r[i + 1])), v);
    }
  }
};
