        for(int i = 0; i < n; i++){
            weight[i] = p[k][i];
            value[i] = p[k + 1][i] - p[k][i];
        }

        //dp
        for(int i = 0; i < n; i++){
            for(int j = 0; j <= w; j++){
                if(i == 0){
                    if(j >= weight[i]) dp[i][j] = max(dp[i][j], dp[i][j - weight[i]] + value[i]);
                }else{
                    if(j >= weight[i]) dp[i][j] = max(dp[i][j - weight[i]] + value[i], max(dp[i - 1][j], dp[i - 1][j - weight[i]] + value[i]));
                    else dp[i][j] = dp[i - 1][j];
                }
            }
        }


        //cout << dp[n - 1][w] << endl;
        w += dp[n - 1][w];
    }
    cout << w << endl;

    return 0;
}

