      if (a[i].first > f) {
        if (a[i - 1].second != n)
          b[top].push_back(make_pair(a[i - 1].second + 1, n));
        top++;
        if (a[i].first - f > 1) b[top++].push_back(make_pair(1, n));
        if (a[i].second > 1) b[top].push_back(make_pair(1, a[i].second - 1));
        f = a[i].first;
