using namespace std;
void bubble(int* a, int n) {
  int min = a[0];
  for (int i = 1; i < n; i++) {
    if (a[i] < min) {
      min = a[i];
    }
  }
  a[n - 1] = min;
}
int compare(const void* a, const void* b) { return (*(int*)a - *(int*)b); }
void bubble_inv(int* a, int n) {
  for (int i = n - 1; i > 0; i--) {
    for (int j = 0; j < i; j++) {
      if (a[j] > a[j + 1]) {
        int tmp = a[j];
        a[j] = a[j + 1];
        a[j + 1] = tmp;
      }
    }
  }
}
