    return pow(a, (LL)b);
}

inline int _I(int b){
    int a = MOD, x1 = 0, x2 = 1, q;
    while (true){
        q = a / b, a %= b;
        if (!a) return (x2 + MOD) % MOD;
        DEC(x1, pdt(q, x2));

        q = b / a, b %= a;
        if (!b) return (x1 + MOD) % MOD;
        DEC(x2, pdt(q, x1));
    }
}

inline void DIV(int &a, int b){MUL(a, _I(b));}
inline int qtt(int a, int b){return pdt(a, _I(b));}

struct Int{
    int val;

    operator int() const{return val;}

    Int(int _val = 0){
        _val %= MOD; if (_val < 0) _val += MOD; val = _val;
    }
    Int(LL _val){
        _val %= MOD; if (_val < 0) _val += MOD; val = _val;
    }
    Int& operator +=(const int& rhs){
        INC(val, rhs);
        return *this;
    }
    Int operator +(const int& rhs) const{
        return sum(val, rhs);
    }
    Int& operator -=(const int& rhs){
        DEC(val, rhs);
        return *this;
    }
    Int operator -(const int& rhs) const{
        return dff(val, rhs);
    }
    Int& operator *=(const int& rhs){
        MUL(val, rhs);
        return *this;
    }
    Int operator *(const int& rhs) const{
        return pdt(val, rhs);
    }
    Int& operator /=(const int& rhs){
        DIV(val, rhs);
        return *this;
    }
    Int operator /(const int& rhs) const{
        return qtt(val, rhs);
    }
    Int operator-()const{
        return MOD-*this;
    }
};

