long long int power(long long int a, long long int b) {
  long long int result;
  if (b == 0) return 1;
  if (b % 2 != 0) {
    result = a;
    result = (result * (power(a, b - 1)));
  } else {
    result = power(a, b / 2);
    result = (result * result);
  }
  return (long long int)result;
}
