public class Main {
	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static StringTokenizer st;
	static PrintWriter pr = new PrintWriter(new OutputStreamWriter(System.out));
	static String readLine() throws IOException {
		return br.readLine();
	}
	static String next() throws IOException {
		while (st == null || !st.hasMoreTokens())
			st = new StringTokenizer(readLine());
		return st.nextToken();
	}
	static int readInt() throws IOException {
		return Integer.parseInt(next());
	}
	static long readLong() throws IOException {
		return Long.parseLong(next());
	}
	static double readDouble() throws IOException {
		return Double.parseDouble(next());
	}
	static char readChar() throws IOException {
		return next().charAt(0);
	}
	static class Pair implements Comparable<Pair> {
		int f, s;
		Pair(int f, int s) {
			this.f = f; this.s = s;
		}
		public int compareTo(Pair other) {
			if (this.f != other.f) return this.f - other.f;
			return this.s - other.s;
		}
	}
	final static int M = 1000010;
	static boolean dp[][] = new boolean[2][M<<1];
	static void solve() throws IOException {
		int n = readInt(), a[] = new int[n + 1];
		for (int i = 1; i <= n; ++i) 
			a[i] = Math.abs(readInt());
		Arrays.sort(a, 1, n + 1);
		for (int i = 1, sum = 0; i <= n; ++i) {
			dp[0][M] = dp[1][M] = true;
			for (int j = 1, cur = 1; j <= n; ++j, cur ^= 1) {
				if (j == i) continue;
				for (int x = (M<<1) - 1; x - a[j] >= -sum + M; --x) dp[cur][x] |= dp[cur^1][x - a[j]];
				for (int x = 0; x + a[j] <= sum + M; ++x) dp[cur][x] |= dp[cur^1][x + a[j]];
				sum += a[j];
			}
			boolean flag = dp[n&1][a[i] + M];
			Arrays.fill(dp[0], -sum + M, sum + M, false);
			Arrays.fill(dp[1], -sum + M, sum + M, false);
			sum = 0;
			if (flag) {
				pr.println("YES");
				return;
			}
		}
		pr.println("NO");
	}
	public static void main(String[] args) throws IOException {
		//solve();
		for (int t = readInt(); t > 0; --t) solve();
		pr.close();
	}
}

