#define swap(i,j) { int tmp = i; i = j; j = tmp; }

int n;
vector<int> tree[100010];
int par[100010] = {};
int num[100010] = {};
int vid[100010];
int head[100010];
int team[100010];
int b = 0;


int setnum(int i){
  if(tree[i].size() == 0) return num[i] = 1;

  int ret = 0;
  for(int j = 0;j < tree[i].size();j++){
    ret += setnum(tree[i][j]);
  }

  return num[i] = ret;
}

void dis(int n){
  memset(team,-1,sizeof(team));
  int gnum = 0;
  int next;
  int pos = 0;
  for(int i = 0;i < n;i++){
    if(team[i] != -1) continue;
    team[i] = gnum;
    head[i] = i;
    vid[i] = pos;
    pos++;
    next = i;
    while(tree[next].size() != 0){
      int maxi = 0;
      for(int j = 1;j < tree[next].size();j++){
        if(num[tree[next][maxi]] < num[tree[next][j]]){
          maxi = j;
        }
      }
      team[tree[next][maxi]] = gnum;
      head[tree[next][maxi]] = i;
      vid[tree[next][maxi]] = pos;
      pos++;
      next = tree[next][maxi];
    }
    gnum++;
  }
  return;
}

void build(int n){
  setnum(0);
  dis(n);
  return;
}

int lca(int i, int j){
  while(1){
    if(vid[i] > vid[j]) swap(i, j);
    if(head[i] == head[j]) return i;
    j = par[head[j]];
  }
}

