using namespace std;
const int MAXC = 50;
const int MAXN = MAXC * MAXC;
char a[MAXC + 10][MAXC + 10];
int d[MAXC + 10][MAXC + 10];
const int drX[] = {0, 0, 1, -1};
const int drY[] = {1, -1, 0, 0};
int rowN, colN;
int spfa(int stx, int sty) {
  static pair<int, int> q[MAXN + 10];
  int head = 0, tail = 0;
  q[0] = make_pair(stx, sty);
  static bool been[MAXC + 10][MAXC + 10];
  memset(been, false, sizeof(been));
  been[stx][sty] = true;
  memset(d, '?', sizeof(d));
  d[stx][sty] = 0;
  while (head <= tail) {
    pair<int, int> now = q[head++ % MAXN];
    been[now.first][now.second] = false;
    for (int k = 0; k < 4; k++) {
      int x = now.first + drX[k], y = now.second + drY[k];
      if (1 <= x && x <= rowN && 1 <= y && y <= colN) {
        int tmp =
            d[now.first][now.second] + (a[x][y] != a[now.first][now.second]);
        if (d[x][y] > tmp) {
          d[x][y] = tmp;
          if (!been[x][y]) {
            been[x][y] = true;
            q[++tail % MAXN] = make_pair(x, y);
          }
        }
      }
    }
  }
  int ans = 0;
  for (int i = 1; i <= rowN; i++)
    for (int j = 1; j <= colN; j++) {
      ans = max(ans, d[i][j]);
    }
  return ans;
}
int main() {
  scanf("%d%d", &rowN, &colN);
  for (int i = 1; i <= rowN; i++) {
    char tmp[100];
    gets(tmp);
    for (int j = 1; j <= colN; j++) {
      a[i][j] = getchar();
    }
  }
  int ans = 0x3f3f3f3f;
  for (int i = 1; i <= rowN; i++)
    for (int j = 1; j <= colN; j++)
      ans = min(ans, spfa(i, j) + (a[i][j] == 'B'));
  printf("%d\n", ans);
  return 0;
}

