int ans, used;

void init()
{
    nonzero.clear();
    coef.clear();
    ans = used = 0;
}

void input()
{
    map<char,bool> nz;
    map<char,int> c;
    rep(i,N) {
        string s; cin >> s;
        if (s.length() >= 2)
            nz[s[0]] = true;
        rep(j,(int)s.length())
            if (i < N - 1)
                c[s[j]] += pw10[(int) s.length() - j - 1];
            else
                c[s[j]] -= pw10[(int) s.length() - j - 1];
    }
    repit(it,c) {
        nonzero.pb(nz[it->first]);
        coef.pb(it->second);
    }
    M = coef.size();
}

void dfs(int depth, int value)
{
    if (depth == M) {
        ans += value == 0;
        return;
    }
    if (!nonzero[depth] && ~used & 1) {
        used ^= 1;
        dfs(depth + 1, value);
        used ^= 1;
    }
    repi(i,1,10) {
        if (~used >> i & 1) {
            used ^= 1 << i;
            dfs(depth + 1, value + coef[depth] * i);
            used ^= 1 << i;
        }
    }
}

