}

int significantFigure(string num) {
    int p = 0;
    bool fp = false;
    while(num[p] == '0' || num[p] == '.') {
        if(num[p] == '.') fp = true;
        p++;
    }
    return num.length()-p-((num.find('.')!=string::npos && !fp)?1:0);
}

string normalize(string num, string prefix, int sigF) {
    int p,np,power;
    stringstream ss;
    assert(sigF > 0);

    for(np=0; np<num.length(); ++np) if(num[np] != '0' && num[np] != '.') break;
    for(p=0; p<num.length(); ++p) if(num[p] == '.') break;


    power = p-np;
    if(p > np) power--;

    num = num.substr(np);
    for(int i=0; i<num.length(); ++i) {
        if(num[i] == '.') {
            num = num.substr(0,i) + num.substr(i+1);
            break;
        }
    }
    //cout<<num<<" "<<sigF<<" "<<power<<endl;
    ss << power + pre[prefix];
    if(num.length() == 1 && sigF == 1) return num + " * 10^" + ss.str();
    else return num.substr(0,1) + "." + num.substr(1) + " * 10^" + ss.str();
}

