  matrix() { memset(x, 0, sizeof(x)); }
  matrix unit() {
    matrix res;
    for (int i = 0; i < tp; i++) res.x[i][i] = 1;
    return res;
  }
  matrix operator*(matrix A) {
    matrix res;
    for (int i = 0; i < tp; i++) {
      for (int j = 0; j < tp; j++) res.x[i][j] = 1e18 + 1;
    }
    for (int i = 0; i < tp; i++)
      for (int k = 0; k < tp; k++)
        for (int j = 0; j < tp; j++) {
          res.x[i][j] = min(res.x[i][j], (x[i][k] + A.x[k][j]));
        }
    return res;
  }
  matrix operator^(long long k) {
    if (!k) return unit();
    matrix res, tmp;
    for (int i = 0; i < tp; i++)
      for (int j = 0; j < tp; j++) {
        res.x[i][j] = tmp.x[i][j] = x[i][j];
      }
    k--;
    while (k) {
      if (k & 1) res = res * tmp;
      tmp = tmp * tmp;
      k >>= 1;
    }
    return res;
  }
