void nextStep(long long mask) {
  if (!(mask & (1 << 0))) {
    mt.x[mp[mask]][mp[mask / 2]] = -1;
    return;
  }
  for (int i = 1; i <= k; i++) {
    if (mask & (1 << i)) continue;
    long long nwmask = mask | (1 << i);
    nwmask /= 2;
    mt.x[mp[mask]][mp[nwmask]] = c[i];
  }
}
