struct Point {
  double x, y;
  Point(double x, double y) : x(x), y(y) {}
};
double dist(const Point& p, const Point& q) {
  double dx = p.x - q.x;
  double dy = p.y - q.y;
  return sqrt(dx * dx + dy * dy);
}
ostream& operator<<(ostream& os, const Point& p) {
  return os << "(" << p.x << "," << p.y << ")";
}
double heron(double a, double b, double c) {
  double s = (a + b + c) / 2.0;
  return sqrt(s * (s - a) * (s - b) * (s - c));
}
double R, X, Y;
int N;
vector<double> P;
void input() {
  cin >> R >> X >> Y >> N;
  P.clear();
  P.resize(N);
  cin >> P;
}
void solve() {
  double theta = 0;
  const Point O(0, 0);
  const Point Z(X, Y);
  vector<int> ans;
  for (int i = 0; i < N; i++) {
    double diff_area = 0;
    for (int j = 1; j <= P[i]; j++) {
      Point s(R * sin(theta), R * cos(theta));
      theta += 1.0 / 100 * 2 * acos(-1);
      Point t(R * sin(theta), R * cos(theta));
      diff_area += -heron(dist(O, s), dist(s, t), dist(t, O)) +
                   heron(dist(Z, s), dist(s, t), dist(t, Z));
    }
    double org_area = R * R * acos(-1) * (P[i] / 100);
    double mod_area = org_area + diff_area;
    ans.push_back(int(100 * mod_area / org_area));
  }
  cout << ans << endl;
}
}  // namespace
int main() {
  input();
  solve();
  return 0;
}

