using c_p_dd = pair<double, double>;

double f_slope(c_p_dd temp) { return temp.second / temp.first; }

int main() {
	vector<c_p_dd> v; int n; double t; cin >> n >> t; v.resize(n);
	for (int i = 0; i < n; i++) cin >> v[i].first >> v[i].second;
	sort(v.begin(), v.end(),
		[](const c_p_dd& l, const c_p_dd& r) { return f_slope(l) > f_slope(r); }
	);
	cout << fixed << setprecision(4) << f_slope(v[0]) * t << endl;
	return 0;
}

