import java.util.Arrays;
import java.util.Scanner;


public class Main {


	static int m;
	static int c0;
	static int d0;
	static int[]a ;
	static int[]b ;
	static int[]c ;
	static int[]d ;
	static int[]memo;
	public static void main(String[] args) {
		Scanner in = new Scanner (System.in);

		int n = in.nextInt();
		m = in.nextInt();
		c0 = in.nextInt();
		d0 = in.nextInt();
		a = new int[m];
		b = new int[m];
		c = new int[m];
		d = new int[m];
		memo = new int[n+1];
		for(int i=0;i<m;i++)
		{
			a[i] = in.nextInt();
			b[i] = in.nextInt();
			c[i] = in.nextInt();
			d[i] = in.nextInt();

		}
		Arrays.fill(memo, -1);
		System.out.println(getMaxProfit(n));

		in.close();


	}

	public static int getMaxProfit(int dough)
	{

		if(memo[dough]!=-1)
			return memo[dough];
		int max = 0;
		if(dough-c0>=0){
			memo[dough] = max = Math.max(max,d0+getMaxProfit(dough-c0));
		}
		for(int i = 0;i<m;i++)
		{
			if(dough-c[i]>=0 && a[i]-b[i]>=0){
				a[i]-=b[i];
				memo[dough] = max = Math.max(max,d[i]+getMaxProfit(dough-c[i]));
				a[i]+=b[i];
			}
		}
		return memo[dough] =  max;
	}

}

