struct Plate {
  double x, h;
  Plate(){}
  Plate(double x, double h):x(x), h(h){}
};

struct Tank {
  Plate l, r;
  double w;
  Tank(){}
  Tank(Plate l, Plate r, double w = 0.0):l(l), r(r), w(w){}
  void pour(double water) {
    w += water;
  }
  void reset() {
    w = 0.0;
  }
  double capacity() {
    return min(l.h, r.h)*fabs(l.x-r.x)*30;
  }
  double contain() {
    return w;
  }
  double overflow(double water = 0.0) {
    return max(0.0, water+contain() - capacity());
  }
  double waterlevel() {
    return min(50.0, contain()/(fabs(l.x-r.x)*30));
  }
};

struct Tap {
  double x, w;
  Tap(){}
  Tap(double x, double w):x(x), w(w){}
};

int N, M, L;
vector<Tank> tank;
vector<Tap> tap;
vector< tuple<double, double, int> > query;
vector<double> ans;

bool in(Tank ta, double x) {
  return ta.l.x <= x && x <= ta.r.x;
}

void unite(int idx) {
  tank[idx+1].l = tank[idx].l;
  tank[idx+1].pour(tank[idx].contain());
  tank.erase(begin(tank)+idx);
}

void simulate(int idx) {
  double flow = tank[idx].overflow();
  if(flow <= 0) return;
  tank[idx].pour(-flow);
  if(tank[idx].l.h < tank[idx].r.h) {
    if(0 < idx) {
      tank[idx-1].pour(flow);
      if(tank[idx-1].overflow() > 0) {
	if(tank[idx].l.h <= tank[idx-1].l.h) {
	  unite(idx-1);
	  simulate(idx-1);
	} else simulate(idx-1);
      }
    } else assert(false);
  } else if(tank[idx].l.h > tank[idx].r.h) {
    if(idx < (int)tank.size()-1) {
      tank[idx+1].pour(flow);
      if(tank[idx+1].overflow() > 0) {
	if(tank[idx].r.h <= tank[idx+1].r.h) {
	  unite(idx);
	  simulate(idx);
	}
	else simulate(idx+1);
      }
    } else assert(false);
  }
}

double solve(double p, double t) {
  rep(i, tank.size()) tank[i].reset();

  rep(i, tap.size()) {
    rep(j, tank.size()) {
      if(in(tank[j], tap[i].x)) {
	tank[j].pour(tap[i].w*t);
	break;
      }
    }
  }
  for(int i = tank.size()-1; i >= 0; i--) {
    if(i >= (int)tank.size()) continue;
    simulate(i);
  }

  rep(i, tank.size()) {
    if(in(tank[i], p)) return tank[i].waterlevel();
  }

  assert(false);
  return -1;
}

