public class CF1000F {
	static final int A = 500000;
	static int[] pp, tt;
	static void pull(int k) {
		int t1 = tt[k * 2 + 1], t2 = tt[k * 2 + 2];
		tt[k] = pp[t1] <= pp[t2] ? t1 : t2;
	}
	static void build(int k, int l, int r) {
		if (r - l == 1) {
			tt[k] = l;
			return;
		}
		int m = (l + r) / 2;
		build(k * 2 + 1, l, m);
		build(k * 2 + 2, m, r);
		pull(k);
	}
	static void update(int k, int l, int r, int i) {
		if (r - l == 1) {
			pp[i] = i;
			return;
		}
		int m = (l + r) / 2;
		if (i < m)
			update(k * 2 + 1, l, m, i);
		else
			update(k * 2 + 2, m, r, i);
		pull(k);
	}
	static int query(int k, int l, int r, int ql, int qr) {
		if (qr <= l || r <= ql)
			return 0;
		if (ql <= l && r <= qr)
			return tt[k];
		int m = (l + r) / 2;
		int t1 = query(k * 2 + 1, l, m, ql, qr);
		int t2 = query(k * 2 + 2, m, r, ql, qr);
		return pp[t1] <= pp[t2] ? t1 : t2;
	}
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(System.out);
		int n = Integer.parseInt(br.readLine());
