		int[] aa = new int[n];
		for (int i = 0; i < n; i++)
			aa[i] = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(br.readLine());
		int[] ll = new int[m];
		int[] rr = new int[m];
		int[] xx = new int[m];
		for (int h = 0; h < m; h++) {
			st = new StringTokenizer(br.readLine());
			int l = Integer.parseInt(st.nextToken()) - 1;
			int r = Integer.parseInt(st.nextToken());
			ll[h] = l;
			rr[h] = r;
		}
		pp = new int[n];
		Integer[] hh = new Integer[A + 1];
		Arrays.fill(hh, -1);
		for (int i = 0; i < n; i++) {
			int a = aa[i];
			pp[i] = hh[a];
			hh[a] = i;
		}
		for (int h = 0; h < m; h++)
			hh[h] = h;
		Arrays.sort(hh, 0, m, (i, j) -> rr[i] - rr[j]);
		int n_ = 1;
		while (n_ < n)
			n_ *= 2;
		tt = new int[n_ * 2];
		build(0, 0, n);
		int r_ = 0;
		for (int h_ = 0; h_ < m; h_++) {
			int h = hh[h_];
			int l = ll[h];
			int r = rr[h];
			while (r_ < r) {
				int p = pp[r_];
				if (p >= 0)
					update(0, 0, n, p);
				r_++;
			}
			int i = query(0, 0, n, l, r);
			if (pp[i] < l)
				xx[h] = aa[i];
		}
		for (int h = 0; h < m; h++)
			pw.println(xx[h]);
		pw.close();
	}
}

