#include <bits/stdc++.h>
using namespace std;
const int N = 200010;
int n, cnt, G[N], vis[N], size[N];
struct edge {
  int t, nx;
} E[N << 1];
struct Qry {
  int x, y, y1;
};
vector<Qry> ans;
int tot, mx, rt;
void getsz(int x, int f) {
  size[x] = 1;
  for (int i = G[x]; i; i = E[i].nx)
    if (E[i].t != f && !vis[E[i].t]) {
      getsz(E[i].t, x);
      size[x] += size[E[i].t];
    }
}
void getroot(int x, int f) {
  int mn = 0;
  for (int i = G[x]; i; i = E[i].nx)
    if (E[i].t != f && !vis[E[i].t]) {
      getroot(E[i].t, x);
      mn = max(mn, size[E[i].t]);
    }
  mn = max(mn, tot - size[x]);
  if (mn < mx) mx = mn, rt = x;
}
void solve(int x, int f) {
  getsz(x, 0);
  tot = size[x];
  mx = 1 << 30;
  getroot(x, 0);
  int cur = rt;
  if (rt != x && f) {
    ans.push_back((Qry){f, x, cur});
  }
  vis[cur] = 1;
  for (int i = G[cur]; i; i = E[i].nx)
    if (!vis[E[i].t]) solve(E[i].t, cur);
}
inline void addedge(int x, int y) {
  E[++cnt].t = y;
  E[cnt].nx = G[x];
  G[x] = cnt;
  E[++cnt].t = x;
  E[cnt].nx = G[y];
  G[y] = cnt;
}
