import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

public class NavigationSystem implements Closeable {

  private InputReader in = new InputReader(System.in);
  private PrintWriter out = new PrintWriter(System.out);

  public void solve() {
    int n = in.ni(), m = in.ni();
    dist = new Integer[n + 1];
    visited = new boolean[n + 1];
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
      next.add(new HashSet<>());
    }
    for (int i = 0; i < m; i++) {
      int u = in.ni(), v = in.ni();
      graph.get(u).add(v);
    }
    k = in.ni();
    route = new int[k];
    for (int i = 0; i < k; i++) {
      route[i] = in.ni();
    }
    for (int node : route) {
      if (dist[node] == null) {
        dfs(node);
      }
    }
    int min = 0;
    for (int idx = 1; idx < k; idx++) {
      if (!next.get(route[idx - 1]).contains(route[idx])) {
        min++;
      }
    }
    int max = 0;
    for (int idx = 1; idx < k; idx++) {
      if (!next.get(route[idx - 1]).contains(route[idx])) {
        max++;
      } else if (next.get(route[idx - 1]).size() > 1) {
        max++;
      }
    }
    out.println(min + " " + max);
  }

  private List<List<Integer>> graph = new ArrayList<>();
  private int k;
  private int[] route;

  private Integer[] dist;
  private boolean[] visited;
  private List<Set<Integer>> next = new ArrayList<>();

  private int dfs(int u) {
    if (u == route[k - 1]) return dist[u] = 0;
    visited[u] = true;
    if (dist[u] != null) return dist[u];

    int minDist = Integer.MAX_VALUE;
    for (int v : graph.get(u)) {
      int dst;
      if (!visited[v]) {
        dst = 1 + dfs(v);
        if (dst < minDist) {
          minDist = dst;
          next.get(u).clear();
          next.get(u).add(v);
        } else if (dst == minDist) {
          next.get(u).add(v);
        }
      }

    }
    return dist[u] = minDist;
  }

  @Override
  public void close() throws IOException {
    in.close();
    out.close();
  }

  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream), 32768);
      tokenizer = null;
    }

    public String next() {
      while (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public int ni() {
      return Integer.parseInt(next());
    }

    public long nl() {
      return Long.parseLong(next());
    }

    public void close() throws IOException {
      reader.close();
    }
  }

  public static void main(String[] args) throws IOException {
    try (NavigationSystem instance = new NavigationSystem()) {
      instance.solve();
    }
  }
}

