public class SolutionE extends Thread {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                                            InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    private static final FastReader scanner = new FastReader();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Thread(null, new SolutionE(), "Main", 1 << 26).start();
    }

    public void run() {
        int t = 1;
        for (int i = 0; i < t; i++) {
            solve();
        }
        out.close();
    }

    private static void solve() {
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        long lengthOrigin = 0;

        Integer[] a = new Integer[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            lengthOrigin += a[i];
        }

        int low = 0;
        int high = 1_000_010;

        while (high - low > 1) {
            int mid = (high + low) / 2;

            long amountCuts = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] > mid) {
                    amountCuts += (a[i]-1) / mid;
                }
            }

            if (amountCuts > k - n) {
                low = mid;
            } else {
                high = mid;
            }
        }

        int amountCuts = 0;
        Queue<Integer> queue = new PriorityQueue<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            if (a[i] <= high) {
                queue.add(a[i]);
            } else {
                long amountParts = (a[i] + high - 1) / high;
                amountCuts += (a[i]-1) / high;

                for (int j = 0; j < high * amountParts - a[i]; j++) {
                    queue.add(high-1);
                }

                for (int j = 0; j < amountParts - (high * amountParts - a[i]); j++) {
                    queue.add(high);
                }
            }
        }

        long sum = 0;
        for (int i = amountCuts; i < k - n; i++) {
            int max = queue.poll();
            queue.add(max / 2);
            queue.add(max - max / 2);
        }

        long lengthAfter = 0;

        while (!queue.isEmpty()) {
            long max = queue.poll();
            lengthAfter += max;
            sum += max * max;
        }

        assert lengthAfter == lengthOrigin;

        System.out.println(sum);
    }

    //WARNINGS:
    //- CHECK FOR INTEGER-OVERFLOW BEFORE SUBMITTING
}

