ll a[500005], q[500005];
ll sz = 720, ans;

struct ele{
  ll l,r, id;  

};

ele p[500005];
ll f[500005];
bool cmp(ele p1, ele p2){
    ll v1 = p1.l/sz;
    ll v2 = p2.l/sz;
    if(v1 == v2) {
        if(v1 & 1) return p1.r > p2.r;
        return p1.r < p2.r;
    }
    return p1.l < p2.l;
}

void add(ll v){
    if(f[v] == 0) ans+=1;
    f[v] += 1;
}

void rem(ll v){
    if(f[v] == 1) ans -=1;
    f[v]-=1;
}




