int dfs(vector<string> &v, int k) {
    if (k == 10) {
        return 1;
    }
    vector<string> S(1, v[k]);
    if (v[k] != rev(v[k])) {
        S.push_back(rev(v[k]));
    }
    int ret = 0;
    for (string bloc : S) {
        for (int i=0; i<10; ++i) {
            bool ok = true;
            vector<int> t;
            for (int j=0; j<5; ++j) {
                if ((lat[by[i][j]][bx[i][j]] & 1 && bloc[j] - '0' == 0) ||
                    (lat[by[i][j]][bx[i][j]] & 2 && bloc[j] - '0' == 1)) {
                    ok = false;
                    break;
                }
                t.push_back(lat[by[i][j]][bx[i][j]]);
            }
            if (ok) {
                for (int j=0; j<5; ++j) {
                    lat[by[i][j]][bx[i][j]] |= (bloc[j] - '0' + 1);
                }
                ret += dfs(v, k+1);
                for (int j=0; j<5; ++j) {
                    lat[by[i][j]][bx[i][j]] = t[j];
                }
            }
        }
    }
    return ret;
}

