struct article {
	char material;
	bool is_removed;
	int topmost;
	int bottommost;
	int leftmost;
	int rightmost;
};

typedef map<char, article> MCA;

VVC image;
MCA articles;

bool remove_all()
{
	bool all_removed = true;
	EACH (articles, itr) {
		article &art = itr->second;
		if (!art.is_removed) {
			all_removed = false;
			// Remove it and recurse
			VVC save = image;
			bool rect = true;
			FOR (i, art.topmost, art.bottommost + 1) {
				FOR (j, art.leftmost, art.rightmost + 1) {
					if (image[i][j] != '*' && image[i][j] != art.material) {
						rect = false;
					} else {
						image[i][j] = '*';
					}
				}
			}
			if (rect) {
				// Recurse
				art.is_removed = true;
				if (remove_all()) {
					return true;
				}
			}
			// Restore and continue trying
			art.is_removed = false;
			image = save;
		}
	}
	return all_removed;
}

