		REP (i, h) {
			REP (j, w) {
				cin >> image[i][j];
			}
		}

		// Scan Image
		REP (i, h) {
			REP (j, w) {
				if (image[i][j] != '.') {
					char c = image[i][j];
					if (!EXIST(articles, c)) {
						article a = {c, false, 50, 0, 50, 0};
						articles[c] = a;
					}
					articles[c].topmost = min(articles[c].topmost, i);
					articles[c].bottommost = max(articles[c].bottommost, i);
					articles[c].leftmost = min(articles[c].leftmost, j);
					articles[c].rightmost = max(articles[c].rightmost, j);
				}
			}
		}

		if (remove_all()) {
			cout << "SAFE" << endl;
		} else {
			cout << "SUSPICIOUS" << endl;
		}
	}
}

