import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solver {

    StringTokenizer st;
    BufferedReader in;
    PrintWriter out;

    public static void main(String[] args) throws NumberFormatException, IOException {
        Solver solver = new Solver();
        solver.open();
        solver.solve();
        solver.close();
    }

    public void open() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    public String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }

    public int nextInt() throws NumberFormatException, IOException {
        return Integer.parseInt(nextToken());
    }

    public long nextLong() throws NumberFormatException, IOException {
        return Long.parseLong(nextToken());
    }

    public double nextDouble() throws NumberFormatException, IOException {
        return Double.parseDouble(nextToken());
    }

    public int getEmpty(int[] ar){
        int empty = 0;
        while (ar[empty]!=0) empty++;
        return empty;
    }

    public void solve() throws NumberFormatException, IOException {
        int n = nextInt();
        int m = nextInt();
        int[] whatF = new int[n];
        int[] whatP = new int[n];
        int[][] files = new int[m][n+1];
        for(int i=0;i<m;i++){
            int ni = nextInt();
            files[i][0] = ni;
            for(int j=1;j<=ni;j++){
                int cl = nextInt()-1;
                whatF[cl] = i+1;
                whatP[cl] = j;
                files[i][j] = cl+1;
            }
        }

        int currentPlace = 1;
        int l = 0;
        StringBuilder sb = new StringBuilder();
        for(int i=0;i<m;i++){
            int ni = files[i][0];
            for(int j=1;j<=ni;j++){
                int fileNumber =  whatF[currentPlace-1];
                int peaceNumber = whatP[currentPlace-1];
                if (fileNumber!=i+1 && peaceNumber!=j){
                    if (fileNumber>0){
                        int empty = currentPlace;
                        while (whatF[empty]!=0) empty++;
                        l++;
                        sb.append(currentPlace).append(' ').append(empty).append('\n');
                        whatF[empty] = fileNumber;
                        whatP[empty] = peaceNumber;
                        files[fileNumber-1][peaceNumber] = empty+1;
                    }
                    int place = files[i][j];
                    l++;                    
                    sb.append(place).append(' ').append(currentPlace).append('\n');
                    whatF[place-1] = 0;
                    whatP[place-1] = 0;
                    whatF[currentPlace-1] = i+1;
                    whatP[currentPlace-1] = j;
                }
                currentPlace++;
            }

        }
        out.println(l);
        out.println(sb);
    }

    public void close() {
        out.flush();
        out.close();
    }

}

