  for (int i = (int)(0); i < (int)(4); i++)
    if (s[i] == t[i]) ret++;
  return ret;
}
int blow(string s, string t) {
  int ret = 0;
  for (int i = (int)(0); i < (int)(4); i++)
    for (int j = (int)(0); j < (int)(4); j++)
      if (i != j && s[i] == t[j]) ret++;
  return ret;
}
string next_query(int h, int b, string s, int id) {
  if (id >= 0) {
    for (int i = (int)(0); i < (int)(v[id].size()); i++) {
      if (hit(s, v[id][i]) == h && blow(s, v[id][i]) == b) {
        v[id + 1].push_back(v[id][i]);
      }
    }
    string t;
    int mini = INT_MAX / 3;
    int hb[5][5] = {};
    for (int i = (int)(0); i < (int)(v[id + 1].size()); i++) {
      for (int j = (int)(0); j < (int)(v[id + 1].size()); j++) {
        hb[hit(v[id + 1][j], v[id + 1][i])][blow(v[id + 1][j], v[id + 1][i])]++;
      }
      int maxi = 0;
      for (int j = (int)(0); j < (int)(5); j++)
        for (int k = (int)(0); k < (int)(5); k++) {
          maxi = max(maxi, hb[j][k]);
          hb[j][k] = 0;
        }
      if (maxi < mini) {
        mini = maxi;
        t = v[id + 1][i];
      }
    }
    return t;
  } else {
    return "0123";
  }
