long long read(long long idx) {
  int sum = 0;
  while (idx >= 1) {
    sum += tree[idx];
    idx -= idx & -idx;
  }
  return sum;
}
void update(long long idx, long long val) {
  while (idx <= MAXVAL) {
    tree[idx] += val;
    idx += idx & -idx;
  }
}
