const int INF = 2000000000;
vector<vector<int> > adj;
pair<int, int> dfsBamboo(int u, const function<void(int, int, int)> &emit,
                         int p = -1) {
  vector<pair<int, int> > leaves;
  for (int v : adj[u]) {
    if (v == p) continue;
    leaves.push_back(dfsBamboo(v, emit, u));
  }
  if (leaves.size() == 0) return pair<int, int>(u, u);
  for (int i = 0; i < leaves.size(); ++i) {
    if (i == 0) {
      emit(p, u, leaves[i].second);
    } else {
      emit(leaves[i - 1].first, u, leaves[i].second);
    }
  }
  return pair<int, int>(leaves[0].second, u);
}
int dfsStar(int u, const function<void(int, int, int)> &emit, int p = -1) {
  for (int v : adj[u]) {
    if (v == p) continue;
    int nch = dfsStar(v, emit, u);
    emit(p, u, nch);
    return nch;
  }
  return u;
}
pair<int, int> cp(int a, int b) { return pair<int, int>(min(a, b), max(a, b)); }
int SZ[200010];
int dfsSize(int u, int p = -1) {
  SZ[u] = 1;
  for (int v : adj[u])
    if (v != p) SZ[u] += dfsSize(v, u);
  return SZ[u];
}
