  for (int u = 0; u < N; ++u) {
    int b = 0;
    for (int v : adj[u]) {
      int csz = SZ[v] < SZ[u] ? SZ[v] : (N - SZ[u]);
      b = max(b, csz);
    }
    if (b * 2 <= N) {
      CD.push_back(u);
    }
  }
  vector<Change> CH;
  for (int c : CD) {
