	static int[][] adjMat;
	static int[] removal;
	static int[] allsum;
	static int n;
	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner(System.in);
		n = sc.nextInt();
		adjMat = new int[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				adjMat[i][j] = sc.nextInt();
			}
		}
		removal = new int[n];
		for (int i = 0; i < removal.length; i++) {
			removal[i] = sc.nextInt()-1;
		}
		floydWarshall();
		for (int i = 0; i < n; i++) {
			if(i < n-1)
				System.out.print(allsum[i] + " ");
			else
				System.out.println(allsum[i]);
		}

	}
	static void floydWarshall(){
		boolean[] added = new boolean[n];
		allsum = new int[n];
		for (int l = n-1; l >= 0; l--) {
			int k = removal[l];
			added[k] = true;
			for (int i = 0; i < adjMat.length; i++) {
				for (int j = 0; j < adjMat.length; j++) {
					adjMat[i][j] = Math.min(adjMat[i][j], adjMat[i][k] + adjMat[k][j]);
				}
			}
			int sum = 0;
			for (int i = 0; i < added.length; i++) {
				for (int j = 0; j < added.length; j++) {
					if(added[i] && added[j])
						sum += adjMat[i][j];
				}
			}

			allsum[l] = sum;
		}
	}
