#include <bits/stdc++.h>
using namespace std;
inline int xor128(void) {
  static int x = 123456789;
  static int y = 362436069;
  static int z = 521288629;
  static int w = 88675123;
  int t;
  t = x ^ (x << 11);
  x = y;
  y = z;
  z = w;
  return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
}
struct Node {
  int Value;
  int SubTreeSize;
  Node *Lch, *Rch;
  int Add;
  Node(int V) : Value(V), SubTreeSize(1) {
    Lch = (Node *)NULL;
    Rch = (Node *)NULL;
  };
};
inline int Count(Node *t) {
  if (t == (Node *)NULL)
    return (0);
  else
    return (t->SubTreeSize);
}
inline int Dist(Node *t) {
  if (t == (Node *)NULL)
    return (-1);
  else
    return (t->Value + t->Add);
}
inline Node *Update(Node *t) {
  if (t == (Node *)NULL) return ((Node *)NULL);
  if (t->Lch != (Node *)NULL) t->Lch->Add += t->Add;
  if (t->Rch != (Node *)NULL) t->Rch->Add += t->Add;
  t->Value += t->Add;
  t->Add = 0;
  t->SubTreeSize = Count(t->Lch) + Count(t->Rch) + 1;
  return (t);
}
inline Node *MakeRoot(int value) { return (new Node(value)); }
Node *Merge(Node *l, Node *r) {
  if (l == (Node *)NULL) return (r);
  if (r == (Node *)NULL) return (l);
  Update(l), Update(r);
  int Left = l->SubTreeSize;
  int Right = r->SubTreeSize;
  if (xor128() % (Left + Right) < Left) {
    l->Rch = Merge(l->Rch, r);
    return (Update(l));
  } else {
    r->Lch = Merge(l, r->Lch);
    return (Update(r));
  }
}
pair<Node *, Node *> Split(Node *t, int k) {
  if (t == (Node *)NULL) return (make_pair((Node *)NULL, (Node *)NULL));
  Update(t);
  if (k <= Count(t->Lch)) {
    pair<Node *, Node *> s = Split(t->Lch, k);
    t->Lch = s.second;
    return (make_pair(s.first, Update(t)));
  } else {
    pair<Node *, Node *> s = Split(t->Rch, k - Count(t->Lch) - 1);
    t->Rch = s.first;
    return (make_pair(Update(t), s.second));
  }
}
Node *Insert(Node *root, int pos, int value) {
  Node *p = MakeRoot(value);
  pair<Node *, Node *> s = Split(root, pos);
  return (Merge(Merge(s.first, p), s.second));
}
Node *Erase(Node *root, int pos) {
  pair<Node *, Node *> s = Split(root, pos);
  pair<Node *, Node *> t = Split(s.second, 1);
  delete t.first;
  return (Merge(s.first, t.second));
}
void EraseALL(Node *root) {
  if (root == (Node *)NULL) return;
  if (root->Lch != (Node *)NULL) EraseALL(root->Lch);
  if (root->Rch != (Node *)NULL) EraseALL(root->Rch);
  delete root;
}
int Lower_Bound(Node *root, int Value) {
  Update(root);
  if (root == (Node *)NULL) return (0);
  if (Value <= root->Value) return (Lower_Bound(root->Lch, Value));
  return (Lower_Bound(root->Rch, Value) + Count(root->Lch) + 1);
}
void Dump(Node *root) {
  Update(root);
  if (root == (Node *)NULL) return;
  cout << "(";
  Dump(root->Lch);
  cout << "" << root->Value << "";
  Dump(root->Rch);
  cout << ")";
}
int main() {
  int Q, L;
  char buff[32];
  Node *root = (Node *)NULL;
  while (true) {
    scanf("%d %d", &Q, &L);
    if (Q == 0 && L == 0) break;
    while (Q--) {
      int type;
      scanf("%d", &type);
      if (type == 0) {
        root = Insert(root, Lower_Bound(root, L), L);
      } else if (type == 1) {
        int d;
        scanf("%d", &d);
        if (root != (Node *)NULL) {
          root->Add -= d;
          pair<Node *, Node *> S = Split(root, Lower_Bound(root, 1));
          if (Count(S.first) > 0) {
            printf("damage %d\n", Count(S.first));
            EraseALL(S.first);
          }
          root = S.second;
        }
      } else if (type == 2) {
        int k;
        scanf("%d", &k);
        if (Count(root) >= k) {
          root = Erase(root, --k);
          puts("hit");
        } else {
          puts("miss");
        }
      } else if (type == 3) {
        int x, r;
        scanf("%d %d", &x, &r);
        pair<Node *, Node *> S = Split(root, Lower_Bound(root, x - r));
        pair<Node *, Node *> T =
            Split(S.second, Lower_Bound(S.second, x + r + 1));
        printf("bomb %d\n", Count(T.first));
        EraseALL(T.first);
        root = Merge(S.first, T.second);
      } else {
        int k;
        scanf("%d", &k);
        int dist = -1;
        if (Count(root) >= k) {
          pair<Node *, Node *> S = Split(root, --k);
          pair<Node *, Node *> T = Split(S.second, 1);
          dist = Dist(T.first);
          S.second = Merge(T.first, T.second);
          root = Merge(S.first, S.second);
        }
        printf("distance %d\n", dist);
      }
    }
    EraseALL(root);
    root = (Node *)NULL;
