public class absolute {
	public static long process(long n, long[] ar, long k)
	{
		int i=0,steps=0;
		long stdiv = ar[0]/k , st = (stdiv+1) *k;

		while(i<ar.length)
		{
			int count=0;
			//System.out.println("Ini "+st+" i "+i);
			while(i<ar.length && ar[i]<=st) {i++;count++;}
			if(count==0)
			{
				if(ar[i]<=st+k)st+=k;
				else
				{
					long div = ar[i]/k;
					if(st%k==0)st= k*(div+1);
					else
					{
						long prev =  st%k;
						st = k*(div)+prev;
					}
				}
			}
			else
				st += count;
			steps = steps + ((count>0)?1:0);
			//System.out.println(st+" "+i);
		}
		return steps;
	}
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		long n = sc.nextLong();
		int m = sc.nextInt();
		long k = sc.nextLong();
		long[] ar = new long[m];
		for(int i=0;i<m;i++)ar[i]=sc.nextLong();
		System.out.println(process(n,ar,k));
	}

}

