const int mod = 1e9 + 7;
int dp[2005][2005];
int n, m, s;
int main() {
  cin >> n >> m;
  s = max(n, m);
  for (int i = 1; i <= s; i++) {
    int ds1 = 0, ds2 = 0;
    for (int j = 2; j <= s; j++) {
      ds1 += dp[i - 1][j];
      ds2 += 1ll * dp[i - 1][j] * (j - 1) % mod;
      ds1 %= mod, ds2 %= mod;
      dp[i][j] = mod + 1 + 1ll * ds1 * j % mod - ds2;
      dp[i][j] %= mod;
    }
  }
  long long ret = 0;
  for (int i = 1; i <= n; i++) {
    int ds1 = 0, ds2 = 0;
    for (int j = 2; j <= m; j++) {
      int le = dp[i][j];
      int ri = 1 + 1ll * ds1 * j % mod + mod - ds2;
      ri %= mod;
      ds1 += dp[n - i][j];
      ds2 += 1ll * dp[n - i][j] * (j - 1) % mod;
      ds1 %= mod;
      ds2 %= mod;
      ret += 1ll * le * ri * (m - j + 1) % mod;
    }
  }
  cout << ret;
}

