    Tap z;
    z.small_count = z.large_count = 0;
    z.large = max(x.large, y.large);
    if(z.large == x.large) z.large_count += x.large_count;
    if(z.large == y.large) z.large_count += y.large_count;
    z.small = min(x.small, y.small);
    if(z.small == x.small) z.small_count += x.small_count;
    if(z.small == y.small) z.small_count += y.small_count;
