                catch(Exception e)
                {
                    e.printStackTrace();
                    System.exit(1);
                }
            }
        }.start();
    }
    static void solve() throws IOException
    {
        scan = new Reader();
        pw = new PrintWriter(System.out,true);
        StringBuilder sb = new StringBuilder();
        root = new int[MAX];
        size = new int[MAX];
        xor = new int[MAX];
        incc = new HashSet[MAX];
        for(int i=1;i<MAX;++i) {
            root[i] = i;
            size[i]++;
            incc[i] = new HashSet<>();
            incc[i].add(i);
        }
        int last = 0;
        int q = ni();
        while(q-->0) {
            if(last==-1) {
                last = 1;
            }
            if(ni()==1) {
                int l = ni(), r = ni(), x = ni();
                l^=last;
                r^=last;
                x^=last;
                //pl("l : "+l+" r : "+r+" x : "+x);
                if(l>r) {
                    int temp = l;
                    l = r;
                    r = temp;
                }
                --l;
                if(!map.containsKey(l)) {
                    map.put(l, id++);
                }
                if(!map.containsKey(r)) {
                    map.put(r, id++);
                }
                int lol = get(map.get(l),map.get(r));
                if(lol==-1) {
                    unite(map.get(l), map.get(r), x);
                }
            }
            else {
                int l = ni(), r = ni();
                l^=last;
                r^=last;
                //pl("l : "+l+" r : "+r);
                if(l>r) {
                    int temp = l;
                    l = r;
                    r = temp;
                }
                --l;
                if(map.containsKey(l) && map.containsKey(r)) {
                    last = get(map.get(l), map.get(r));
                }
                else last = -1;
                sb.append(last);
                sb.append("\n");
            }
        }
        psb(sb);
        pw.flush();
        pw.close();
    }
    static void unite(int a, int b, int x) {
        //pl("in unite : a : "+a+" b : "+b+" x : "+x);
        int ra = root[a];
        int rb = root[b];
        if(ra==rb) {
            return;
        }
        int lol = x;
        lol^=xor[a];
        lol^=xor[b];
        if(size[ra]>=size[rb]) {
            for(int e : incc[rb]) {
                incc[ra].add(e);
                xor[e]^=lol;
                root[e] = ra;
            }
            size[ra]+=size[rb];
        }
        else {
            for(int e: incc[ra]) {
                incc[rb].add(e);
                xor[e]^=lol;
                root[e] = rb;
            }
            size[rb]+=size[ra];
        }
    }
    static int get(int l, int r) {
        if(root[l]!=root[r]) {
            return -1;
        }
        return xor[l]^xor[r];
    }
