vector<int> len;
vector<map<int, int> > value;
int dfs(string& s, int& k) {
  if (isdigit(s[k])) {
    int ret = 0;
    while (isdigit(s[k])) {
      ret *= 10;
      ret += s[k] - '0';
      ++k;
    }
    return ret;
  }
  char c = s[k];
  k += 2;
  int a = dfs(s, k);
  ++k;
  if (a == -1) return -1;
  if (k < s.size() && s[k] == '=') {
    ++k;
    if (a >= len[c])
      return -1;
    else
      return value[c][a] = dfs(s, k);
  } else {
    if (value[c].find(a) == value[c].end())
      return -1;
    else
      return value[c][a];
  }
}
int solve(vector<string>& s) {
  int n = s.size();
  len.assign(128, 0);
  value.assign(128, map<int, int>());
  for (int i = 0; i < n; ++i) {
    if (s[i].find('=') == string::npos) {
      int k = 2;
      len[s[i][0]] = dfs(s[i], k);
    } else {
      int k = 0;
      if (dfs(s[i], k) == -1) return i + 1;
    }
  }
  return 0;
}
