__int64 gcd(__int64 x,__int64 y)
{
	int nTemp=x%y;
	while(nTemp)
	{
		x=y;
		y=nTemp;
		nTemp=x%y;
	}
	return y;
}
int main()
{
	__int64 n,m,nA,nB,nX,nY,nGcd,nTemp,nLen,nWid,nX1,nX2,nY1,nY2;
