	{
		nGcd=gcd(nA,nB);
		nA/=nGcd;nB/=nGcd;
		if(n/nA>m/nB)
			nTemp=n/nB;
		else
			nTemp=m/nA;
		nLen=nTemp*nA;
		nWid=nTemp*nB;
		if(nLen%2==0)
		{
			nX1=nX-nLen/2;
			nX2=nX1+nLen;
		}
		else
		{
			nX1=nX-nLen/2-1;
			nX2=nX1+nLen;
		}
		if(nWid%2==0)
		{
			nY1=nY-nWid/2;
			nY2=nY1+nWid;
		}
		else
		{
			nY1=nY-nWid/2-1;
			nY2=nY1+nWid;
