  int* dx = new int[n];
  int* c = new int[n];
  dx[0] = x[0];
  for (int i = 1; i < n; i++) dx[i] = x[i] - x[i - 1];
  c[0] = dx[0] / 2;
  for (int i = 1; i < n; i++) c[i] = (dx[i] - dx[i - 1]) / 2;
  string ret = "";
  for (int i = 0; i < n; i++) {
    if (i != n - 1) ret += "(";
    ret += singleFunction(c[i], i);
    if (i != n - 1) {
      if (c[i + 1] >= 0)
        ret += "+";
      else
        ret += "-";
    }
  }
  for (int i = 0; i < n - 1; i++) ret += ")";
  return ret;
