long long int fastPower(long long int a, long long int b) {
  long long int res = 1;
  a = a % 1000000007;
  if (a == 0) return 0;
  while (b > 0) {
    if (b & 1) res = (res * a) % 1000000007;
    b = b >> 1;
    a = (a * a) % 1000000007;
  }
  return res;
}
unordered_map<char, int> symbol = {{'[', -1}, {'(', -2}, {'{', -3},
                                   {']', 1},  {')', 2},  {'}', 3}};
bool isBalanced(string s) {
  stack<char> st;
  for (char bracket : s) {
    if (symbol[bracket] < 0) {
      st.push(bracket);
    } else {
      if (st.empty()) {
        return false;
      }
      char top = st.top();
      st.pop();
      if (symbol[top] + symbol[bracket] != 0) return false;
    }
  }
  if (st.empty())
