  for (int apair = 0; apair < 4; apair++) {
    if (((fcA >> apair) & 1) == 1) {
      for (int bpair = 0; bpair < 4; bpair++) {
        if (((fcB >> bpair) & 1) == 1) {
          int rpair = -1;
          switch (opchar) {
            case '&':
              rpair = apair & bpair;
              break;
            case '|':
              rpair = apair | bpair;
              break;
            case '^':
              rpair = apair ^ bpair;
              break;
          }
          fcRet |= (1 << rpair);
        }
      }
    }
  }
  return fcRet;
}
int fcParse(int start, int& end) {
