bool visited[10][10];
vector<int> sum;
vector<map<int, int> > to;
bool out(int x, int y) { return x < 0 || y < 0 || x >= w || y >= h; }
int labelling(int x, int y, int idx) {
  int res = 1;
  label[y][x] = idx;
  for (int i = 0; i < 4; ++i) {
    const int nx = x + dx[i], ny = y + dy[i];
    if (out(nx, ny)) continue;
    if (label[ny][nx] == -1 && p[ny][nx] == p[y][x])
      res += labelling(nx, ny, idx);
  }
  return res;
}
void dfs(int x, int y) {
  visited[y][x] = true;
  for (int i = 0; i < 4; ++i) {
    const int nx = x + dx[i], ny = y + dy[i];
    if (out(nx, ny)) {
      ++sum[label[y][x]];
      continue;
    }
    if (label[ny][nx] == label[y][x]) {
      if (!visited[ny][nx]) dfs(nx, ny);
    } else if (p[ny][nx] < p[y][x]) {
      if (p[ny][nx]) ++to[label[y][x]][label[ny][nx]];
      ++sum[label[y][x]];
    }
  }
}
