inline void remin(int& a, int b) { a = min(a, b); }
inline void remax(int& a, int b) { a = max(a, b); }
struct Tree {
  int offset, qbegin, qend, resmn, resmx;
  int mn[maxTS], mx[maxTS];
  void querypriv(int v, int left, int right) {
    if (left >= qend or right <= qbegin) return;
    if (left >= qbegin and right <= qend) {
      remin(resmn, mn[v]);
      remax(resmx, mx[v]);
      return;
    }
    querypriv(v * 2, left, (left + right) / 2);
    querypriv(v * 2 + 1, (left + right) / 2, right);
  }
  void resize(int n) {
    for (offset = 1; offset < n; offset *= 2)
      ;
    for (int(i) = (1); (i) < (offset * 2); (i)++) mn[i] = INF, mx[i] = -INF;
  }
  void init(pair<int, int>* t, int n) {
    for (int(i) = (0); (i) < (n); (i)++)
      mn[offset + i] = t[i].first, mx[offset + i] = t[i].second;
    for (int i = offset - 1; i > 0; i--)
      mn[i] = min(mn[i * 2], mn[i * 2 + 1]),
      mx[i] = max(mx[i * 2], mx[i * 2 + 1]);
  }
  pair<int, int> query(int a, int b) {
    qbegin = a + offset;
    qend = b + offset + 1;
    resmn = INF;
    resmx = -INF;
    querypriv(1, offset, offset * 2);
    return {resmn, resmx};
  }
} tree;
