  for (int(s) = (1); (s) < (maxL); (s)++) {
    for (int(i) = (n); (i) < (n * 2); (i)++) {
      temp[i - n] = dp[s - 1][i - n] = {moveleft(dp[s - 1][i].first),
                                        moveleft(dp[s - 1][i].second)};
      temp[i + n] = dp[s - 1][i + n] = {moveright(dp[s - 1][i].first),
                                        moveright(dp[s - 1][i].second)};
