#include <bits/stdc++.h>
using namespace std;
const int N = 110000, Le = 1800;
int a[N], lu[50], ln, isluc[N];
int h[600][N / 10], ad[600];
char s[10];
int main() {
  for (int i = 1; i < N / 10; i++) {
    int p = i, luc = 1;
    while (p) luc &= (p % 10 == 4 || p % 10 == 7), p /= 10;
    if (luc) lu[ln++] = i;
    isluc[i] = luc;
  }
  int n, q;
  scanf("%d%d", &n, &q);
  for (int i = 1; i <= n; i++) scanf("%d", a + i);
  for (int i = 1; i <= n; i++) {
    int id = (i - 1) / Le;
    h[id][a[i]]++;
  }
  while (q--) {
    int l, r, d;
    scanf("%s%d%d", s, &l, &r);
    int lid = (l - 1) / Le + (l % Le != 1), rid = r / Le;
    if (s[0] == 'a') {
      scanf("%d", &d);
      if (lid < rid) {
        for (int i = lid; i < rid; i++) ad[i] += d;
        for (int i = l; i <= min(lid * Le, r); i++)
          h[lid][a[i]]--, h[lid][a[i] + d]++, a[i] += d;
        for (int i = max(l, rid * Le + 1); i <= r; i++)
          h[rid][a[i]]--, h[rid][a[i] + d]++, a[i] += d;
      } else
        for (int i = l; i <= r; i++)
          h[(i - 1) / Le][a[i]]--, h[(i - 1) / Le][a[i] + d]++, a[i] += d;
    } else {
      int ans = 0;
      if (lid < rid) {
        for (int i = lid; i < rid; i++)
          for (int j = 0; j < ln; j++)
            if (lu[j] > ad[i]) ans += h[i][lu[j] - ad[i]];
        for (int i = l; i <= min(lid * Le, r); i++)
          if (isluc[a[i] + ad[lid]]) ans++;
        for (int i = max(l, rid * Le + 1); i <= r; i++)
          if (isluc[a[i] + ad[rid]]) ans++;
      } else
        for (int i = l; i <= r; i++)
          if (isluc[a[i] + ad[(i - 1) / Le]]) ans++;
      printf("%d\n", ans);
    }
  }
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

map<pair<char, int>, int > var;
map<char, int> arrSize;

char array_name(string& line, int& idx){
	return line[idx++];
}

int number(string& line, int& idx){
	char c = line[idx];
	if(c == '0'){
		idx++;
		return 0;
	}else{
		int ans = 0;
		c = line[idx];
		while('0' <= c && c <= '9'){
			ans = ans * 10 + (c - '0');
			++idx;
			if(idx >= line.size()) break;
			c = line[idx];
		}
		return ans;
	}
}

int expression(string& line, int& idx, bool& correct){
	char c = line[idx];
	correct = true;
	if('0' <= c && c <= '9'){
		return number(line, idx);
	}
	char arr = array_name(line, idx);
	idx++;
	int id = expression(line, idx, correct);
	if(!correct){
		correct = false;
		return 0;
	}
	pair<char, int> key(arr, id);
	if(var.count(key)){
		int ret = var[key];
		idx++;
		return ret;
	}else{
		correct = false;
		return 0;
	}
}

int declaration(string& line, int& idx){
	char name = array_name(line, idx);
	char c;
	c = line[idx++];
	//cout << 1 << endl;
	if(c != '['){
		return false;
	}

	//cout << 2 << endl;
	int id = number(line, idx);
	c = line[idx++];
	if(c != ']'){
		return false;
	}
	//cout << 3 << endl;
	if(line.size() != idx) return false;

	//cout << 4 <<  arrSize.count(c) << " " << c << endl;
	if(!arrSize.count(name)){
		arrSize[name] = id;
		return true;
	}else{
		return false;
	}
}

bool assignment(string& line, int& idx){
	char name = array_name(line, idx);
	char c = line[idx++];
	if(c != '['){
		return false;
	}
	bool correct;
	int id = expression(line, idx, correct);
	if(!correct) return false;

	c = line[idx++];
	if(c != ']'){
		return false;
	}
	c = line[idx++];

	if(c != '='){
		return false;
	}
	int val = expression(line, idx, correct);
	if(!correct) return false;
	if(idx != line.size()) return false;

	if(arrSize.count(name) && id < arrSize[name]){
		var[pair<char, int>(name, id)] = val;
		return true;
	}else{
		return false;
	}
}

int main(){
	while(true){
		var.clear();
		arrSize.clear();
		string str;
		getline(cin, str);
		if(str == ".") break;
		int line = 1;
		int ans = 0;
		do{
			int idx1= 0;
			int idx2 = 0;
			if(ans == 0 && !declaration(str, idx1) && !assignment(str, idx2)){
				ans = line;
			}
			line++;
		}while(getline(cin, str), str != ".");
		cout << ans << endl;	
	}
}

