const int INF = 1 << 29;
struct BIT {
  vector<int> dat;
  int size;
  BIT(int s) : size(s + 1) { dat.resize(size); }
  void add(int n, int x) {
    while (n < size) {
      dat[n] += x;
      n += n & -n;
    }
  }
  int dist(int l, int r) { return abs(sum(r) - sum(l)); }
  int sum(int n) {
    int s = 0;
    while (n > 0) {
      s += dat[n];
      n -= n & -n;
    }
    return s;
  }
};
int main() {
