  a.resize(unique(a.begin(), a.end()) - a.begin());
  for (int i = 0; i <= n; i++)
    if (c[i] != c[i + 1]) b[i] = ++t;
  for (int i = 0; i < l; i++)
    for (int j = 0; j + a[i] <= n; j++) {
      v[j].push_back(j + a[i]);
      v[j + a[i]].push_back(j);
    }
  for (int i = 0; i <= n; i++)
    if (b[i]) {
      r++;
      bfs(i);
    }
  int k = f((1 << r) - 1);
  if (k >= inf)
    cout << -1 << endl;
  else
    cout << k << endl;
  return 0;
}

