			long[][] rets = new long[3][m+1];
			long t = 0;
			for(int i = 1;i <= m;i++){
				t += b[l][m-i];
				rets[0][i] = t;
				rets[1][i] = t;
				rets[2][i] = t;
			}
			max = Math.max(max, rets[0][m]);
			tr(rets, l, max);
			return rets;
		}

		int h = (l+r)/2;
		long[][] L = dfs(l, h, b, a);
		long[][] R = dfs(h, r, b, a);
		tr("L", L);
		tr("R", R);
		for(int i = 1;i < m;i++){
			int j = m-i;
			max = Math.max(max, L[2][i]+R[1][j]-a[h-1]);
			tr(l, r, max, i, j);
		}
		long[][] rets = new long[3][m+1];
		for(int i = 0;i <= m;i++){
			rets[0][i] = Long.MIN_VALUE;
