          f[(i & 1) ^ 1][j][0] =
              (f[(i & 1) ^ 1][j][0] + f[(i & 1) ^ 1][j][k]) % mod,
                      f[(i & 1) ^ 1][j][k] = 0;
    x = (a[i] ^ a[i - 1]) ? 0 : x + 1;
    for (int j = 0; j <= i; j++) {
