				else up[j+1][k] = up[j][up[j][k]];
			}
		}
		int ans = INF;
		rep(i,vec.size()){
			if(vec[i].fi >= 2.*pi+EPS) break;

			int use = 0;
			int cur = i;
			for(int k=19;k>=0;k--){
				if(up[k][cur] == INF) continue;
				if(vec[up[k][cur]].fi - vec[i].fi < 2.*pi-EPS){
					use += (1<<k);
					cur = up[k][cur];
				}
			}
			ans = min(ans, cur+1);
		}

		if(ans <= m) lb = mid;
		else ub = mid;
	}
	printf("%.12Lf\n",lb);
}

