public class Solution {
	public static void main (String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 
		String[] temp=br.readLine().trim().split(" ");
		int V=Integer.parseInt(temp[0]);
		int E=Integer.parseInt(temp[1]);
		DSU graph=new DSU(V);
		for(int i=0;i<E;i++)
		{
		    temp=br.readLine().trim().split(" ");
		    int u=Integer.parseInt(temp[0]);
		    int v=Integer.parseInt(temp[1]);

		    graph.makeUnion(u,v);
		}
		int ans=0;
		boolean[] marked=new boolean[V+1];
		for(int i=1;i<=V;i++)
        {
            boolean isCyclePresentInComponent=graph.isCyclePresentInComponent(i);
            if(isCyclePresentInComponent==false)
            {
                int parent=graph.getParent(i);
                if(marked[parent]==true)
                {
                    continue;
                }
                marked[parent]=true;
                ans++;  
            }
        }
        System.out.println(ans);
	}
}

class DSU
{
    private int[] parent;
    private int[] size;
    private boolean[] isCycle;

    public DSU(int V)
    {
        parent=new int[V+1];
        size=new int[V+1];
        isCycle=new boolean[V+1];
        for(int i=0;i<=V;i++)
        {
            parent[i]=i;
            size[i]=1;
        }
    }

    public int getParent(int vertex)
    {
        while(parent[vertex]!=vertex)
        {
            vertex=parent[vertex];
        }
        return vertex;
    }
    public void makeUnion(int u,int v)
    {
        int parent1=getParent(u);
        int parent2=getParent(v);
        if(parent1==parent2)
        {
            isCycle[parent1]=true;
            isCycle[parent2]=true;
            return;
        }

        if(size[parent1]>size[parent2])
        {
            parent[parent2]=parent1;
            size[parent1]+=size[parent2];
        }
        else{
            parent[parent1]=parent2;
            size[parent2]+=size[parent1];
        }
    }
    public int size(int vertex)
    {
        int parent=getParent(vertex);
        return size[parent];
    }
    public boolean areConnected(int u,int v)
    {
        int parent1=getParent(u);
        int parent2=getParent(v);
        return parent1==parent2;
    }
    public int numComponents()
    {
        int count=0;
        int V=this.parent.length-1;
        for(int i=1;i<=V;i++)
        {
            if(parent[i]==i)
            {
                count++;
            }
        }
        return count;
    }

    public boolean isCyclePresentInComponent(int vertex)
    {
        int parent=this.getParent(vertex);
        return this.isCycle[parent];
    }
}

