#include <bits/stdc++.h>
using namespace std;
struct kek {
  int mod;
  int val;
};
char a[1000001];
kek t[4000001];
kek tt[4000001];
int maaa(int v, int tl, int tr, int l, int r) {
  if (l > r) return 0;
  if (l == tl && r == tr) return t[v].val + t[v].mod;
  int tm = (tl + tr) / 2;
  t[v * 2].mod += t[v].mod;
  t[v * 2 + 1].mod += t[v].mod;
  t[v].val += t[v].mod;
  t[v].mod = 0;
  return max(maaa(v * 2, tl, tm, l, min(r, tm)),
             maaa(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
}
int miii(int v, int tl, int tr, int l, int r) {
  if (l > r) return 100000000;
  if (l == tl && r == tr) return tt[v].val + tt[v].mod;
  int tm = (tl + tr) / 2;
  tt[v * 2].mod += tt[v].mod;
  tt[v * 2 + 1].mod += tt[v].mod;
  tt[v].val = tt[v].val + tt[v].mod;
  tt[v].mod = 0;
  return min(miii(v * 2, tl, tm, l, min(r, tm)),
             miii(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
}
void updatett(int v, int tl, int tr, int l, int r, int k) {
  if (l > r) return;
  if (l == tl && r == tr) {
    tt[v].mod += k;
    return;
  }
  int tm = (tl + tr) / 2;
  tt[v * 2].mod += tt[v].mod;
  tt[v * 2 + 1].mod += tt[v].mod;
  tt[v].val += tt[v].mod;
  tt[v].mod = 0;
  updatett(v * 2, tl, tm, l, min(r, tm), k);
  updatett(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, k);
}
void update(int v, int tl, int tr, int l, int r, int k) {
  if (l > r) return;
  if (l == tl && r == tr) {
    t[v].mod += k;
    return;
  }
  int tm = (tl + tr) / 2;
  t[v * 2].mod += t[v].mod;
  t[v * 2 + 1].mod += t[v].mod;
  t[v].mod = 0;
  t[v].val += t[v].mod;
  update(v * 2, tl, tm, l, min(r, tm), k);
  update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, k);
}
