using namespace std;
vector<pair<long long, long long> > V;
long long G[5010][210];
long long N, M;
long long A[5010];
long long updates[5010][5010];
int main() {
  cin >> N >> M;
  for (long long i = 1; i < N; ++i) cin >> A[i];
  for (long long i = 1; i <= M; ++i)
    for (long long j = 1; j <= N; ++j) cin >> G[i][j];
  for (long long j = 1; j <= N; ++j) {
    V.clear();
    V.emplace_back(1e9, 0);
    for (long long i = 1; i <= M; ++i) {
      long long val = G[i][j];
      while ((long long)V.size() && V.back().first < val) {
        pair<long long, long long> p = V.back();
        V.pop_back();
        long long st = V.back().second + 1;
        long long c = val - p.first;
        updates[st][i] += c;
        updates[p.second + 1][i] -= c;
      }
      updates[i][i] += val;
      updates[i + 1][i] -= val;
      V.emplace_back(val, i);
    }
  }
  for (long long i = 1; i <= M; ++i)
    for (long long j = 1; j <= M; ++j) updates[i][j] += updates[i - 1][j];
  long long ans = 0;
  long long cur = 0;
  for (long long st = 1; st <= M; ++st) {
    cur = updates[st][st];
    ans = max(ans, cur);
    for (long long ct = st + 1; ct <= M; ++ct) {
      cur += updates[st][ct];
      cur -= A[ct - 1];
      ans = max(ans, cur);
    }
  }
  cout << ans;
}

