struct Data {
  Data(int arg_node_id, int arg_sum_cost) {
    node_id = arg_node_id;
    sum_cost = arg_sum_cost;
  }
  bool operator<(const struct Data &arg) const {
    return sum_cost > arg.sum_cost;
  }
  int node_id, sum_cost;
};
struct Info {
  Info(int arg_to, int arg_cost, int arg_edge_id) {
    to = arg_to;
    cost = arg_cost;
    edge_id = arg_edge_id;
  }
  int to, cost, edge_id;
};
int V, E, number;
int order[100000], lowlink[100000];
int min_cost[100000], rev_min_cost[100000];
bool visited[100000], in_MIN_PATH[100000];
Edge edge[100000];
vector<Info> G[100000], rev_G[100000], MIN_G[100000];
void recursive(int node_id) {
  order[node_id] = number++;
  lowlink[node_id] = order[node_id];
  int next_node;
  for (int i = 0; i < MIN_G[node_id].size(); i++) {
    next_node = MIN_G[node_id][i].to;
    if (order[next_node] == -1) {
      visited[MIN_G[node_id][i].edge_id] = true;
      recursive(next_node);
      lowlink[node_id] = min(lowlink[node_id], lowlink[next_node]);
    } else if (visited[MIN_G[node_id][i].edge_id] == false) {
      lowlink[node_id] = min(lowlink[node_id], order[next_node]);
    }
  }
}
void dijkstra_NORMAL() {
  int start = 0, goal = 1;
  for (int i = 0; i < V; i++) min_cost[i] = 2000000000;
  min_cost[start] = 0;
  priority_queue<Data> Q;
  Q.push(Data(start, 0));
  int next_node;
  while (!Q.empty()) {
    if (Q.top().node_id == goal) {
      Q.pop();
    } else if (Q.top().sum_cost > min_cost[Q.top().node_id]) {
      Q.pop();
    } else {
      for (int i = 0; i < G[Q.top().node_id].size(); i++) {
        next_node = G[Q.top().node_id][i].to;
        if (min_cost[next_node] >
            Q.top().sum_cost + G[Q.top().node_id][i].cost) {
          min_cost[next_node] = Q.top().sum_cost + G[Q.top().node_id][i].cost;
          Q.push(Data(next_node, min_cost[next_node]));
        }
      }
      Q.pop();
    }
  }
}
void dijkstra_REVERSE() {
  int start = 1, goal = 0;
  for (int i = 0; i < V; i++) rev_min_cost[i] = 2000000000;
  rev_min_cost[start] = 0;
  priority_queue<Data> Q;
  Q.push(Data(start, 0));
  int next_node;
  while (!Q.empty()) {
    if (Q.top().node_id == goal) {
      Q.pop();
    } else if (Q.top().sum_cost > rev_min_cost[Q.top().node_id]) {
      Q.pop();
    } else {
      for (int i = 0; i < rev_G[Q.top().node_id].size(); i++) {
        next_node = rev_G[Q.top().node_id][i].to;
        if (rev_min_cost[next_node] >
            Q.top().sum_cost + rev_G[Q.top().node_id][i].cost) {
          rev_min_cost[next_node] =
              Q.top().sum_cost + rev_G[Q.top().node_id][i].cost;
          Q.push(Data(next_node, rev_min_cost[next_node]));
        }
      }
      Q.pop();
    }
  }
}
int main() {
  scanf("%d %d", &V, &E);
  for (int i = 0; i < E; i++) {
    scanf("%d %d %d", &edge[i].from, &edge[i].to, &edge[i].cost);
    edge[i].from--;
    edge[i].to--;
    G[edge[i].from].push_back(Info(edge[i].to, edge[i].cost, i));
    rev_G[edge[i].to].push_back(Info(edge[i].from, edge[i].cost, i));
  }
  dijkstra_NORMAL();
  dijkstra_REVERSE();
  int goal = 1;
  for (int i = 0; i < E; i++) in_MIN_PATH[i] = false;
  for (int i = 0; i < E; i++) {
    if (min_cost[edge[i].from] + edge[i].cost + rev_min_cost[edge[i].to] ==
        min_cost[goal]) {
      in_MIN_PATH[i] = true;
      MIN_G[edge[i].from].push_back(Info(edge[i].to, edge[i].cost, i));
    }
  }
  number = 0;
  for (int i = 0; i < V; i++) {
    order[i] = -1;
    lowlink[i] = -1;
  }
  for (int i = 0; i < E; i++) {
    visited[i] = false;
  }
  recursive(0);
  int from, to;
  for (int i = 0; i < E; i++) {
    if ((min_cost[edge[i].to] != 2000000000) &&
        (rev_min_cost[edge[i].from] != 2000000000) &&
        (min_cost[edge[i].to] + edge[i].cost + rev_min_cost[edge[i].from]) <=
            min_cost[goal]) {
      if (min_cost[edge[i].to] + edge[i].cost + rev_min_cost[edge[i].from] <
          min_cost[goal]) {
        printf("HAPPY\n");
      } else {
        printf("SOSO\n");
      }
      continue;
    }
    from = edge[i].from;
    to = edge[i].to;
    if (order[to] < order[from]) {
      swap(from, to);
    }
    if (order[from] < lowlink[to]) {
      printf("SAD\n");
      continue;
    }
    printf("SOSO\n");
  }
  return 0;
}

