int cups[1001];
int main() {
  int size;
  cin >> size;
  int sum = 0;
  int avg;
  for (int i = 1; i <= size; ++i) {
    cin >> cups[i];
    sum += cups[i];
  }
  avg = sum / size;
  if (size * avg != sum) {
    cout << "Unrecoverable configuration." << endl;
    return 0;
  }
  int diff = 0;
  int from, to;
  bool done = false;
  for (int i = 1; i <= size; ++i) {
    if (cups[i] != avg) {
      if (diff == 0) {
        diff = avg - cups[i];
        if (diff > 0)
          from = i;
        else
          to = i;
      } else if (done) {
        cout << "Unrecoverable configuration." << endl;
        return 0;
      } else {
        if (cups[i] - diff == avg) {
          done = true;
          if (diff > 0)
            to = i;
          else
            from = i;
          diff = abs(diff);
        } else {
          cout << "Unrecoverable configuration." << endl;
          return 0;
        }
      }
    }
  }
  if (diff == 0) {
    cout << "Exemplary pages." << endl;
    return 0;
  }
  cout << diff << " ml. from cup #" << from << " to cup #" << to << "." << endl;
  return 0;
}

