#include <bits/stdc++.h>
using namespace std;
unordered_map<int, int> dp, Prime;
unordered_map<int, int>::iterator it;
int Count;
void Insert(int n) {
  for (int i = 2; i * i <= n; i++) {
    Count = 0;
    while (n % i == 0) {
      n = n / i;
      Count++;
    }
    Prime[i] |= (1 << Count);
  }
  if (n > 1) Prime[n] |= 1 << 1;
}
int Grundy(int mask) {
  if (!mask) return 0;
  if (dp.count(mask)) return dp[mask];
  int SET = 31 - __builtin_clz(mask);
  unordered_map<int, bool> Mark;
  for (int k = SET; k >= 0; k--) {
    int newMask = (mask >> k) | (mask & ((1 << k) - 1));
    if (mask == newMask) continue;
    Mark[Grundy(newMask)] = true;
  }
  int ans = 0;
  while (Mark.count(ans)) ans++;
  return dp[mask] = ans;
}
int main() {
  int n, p;
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &p);
    Insert(p);
  }
  int ans = 0;
  for (it = Prime.begin(); it != Prime.end(); it++) ans ^= Grundy(it->second);
  if (ans)
    printf("Mojtaba");
  else
    printf("Arpa");
}

