using namespace std;
int n, Dp[1 << 25], X[25], Y[25], sx, sy, pre[1 << 25];
vector<int> ans;
inline int f(int x) { return x * x; }
inline int getlen(int XA, int YA, int XB, int YB) {
  return f(XA - XB) + f(YA - YB);
}
inline int getFlen(int x, int y) { return f(x - sx) + f(y - sy); }
inline int getClen(int xA, int yA, int xB, int yB) {
  return getFlen(xA, yA) + getFlen(xB, yB) + getlen(xA, yA, xB, yB);
}
int Go(int mask) {
  if (Dp[mask] != -1) return Dp[mask];
  int res = 1000000000;
  for (int i = 0; i < n - 1; i++)
    if (mask & (1 << i)) {
      for (int j = i + 1; j < n; j++)
        if (mask & (1 << j)) {
          if (res > Go(mask ^ ((1 << i) | (1 << j))) +
                        getClen(X[i], Y[i], X[j], Y[j])) {
            res = Go(mask ^ ((1 << i) | (1 << j))) +
                  getClen(X[i], Y[i], X[j], Y[j]);
            pre[mask] = (mask ^ ((1 << i) | (1 << j)));
          }
        }
      break;
    }
  return Dp[mask] = res;
}
void getpre(int mask) {
  int pree = pre[mask];
  ans.push_back(0);
  if (mask == 0) return;
  for (int i = 0; i < n; i++)
    if ((mask & (1 << i)) && (!(pree & (1 << i)))) ans.push_back(i + 1);
  getpre(pree);
}
int main() {
  scanf("%d%d", &sx, &sy);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) scanf("%d%d", X + i, Y + i);
  memset(Dp, -1, sizeof(Dp));
  Dp[0] = 0;
  int res = 1000000000, mask = (1 << n) - 1, ppp = -1;
  if (n & 1) {
    for (int i = 0; i < n; i++) {
      if (Go(mask ^ (1 << i)) + 2 * getFlen(X[i], Y[i]) < res) {
        res = Go(mask ^ (1 << i)) + 2 * getFlen(X[i], Y[i]);
        ppp = i;
      }
    }
    ans.push_back(0);
    ans.push_back(ppp);
  } else
    res = Go(mask);
  printf("%d\n", res);
  getpre((1 << n) - 1);
  reverse(ans.begin(), ans.end());
  for (int i = 0; i < ans.size(); i++)
    printf("%d%c", ans[i], (i == ans.size() - 1) ? '\n' : ' ');
  return 0;
}

