        if(!vtces.containsKey(b)){
            vtces.put(b,new vertex());
        }
        vtces.get(a).children.put(b,cost);
//        vtces.get(b).children.put(a,cost);
    }
    public boolean isCyclicDirected(){
        boolean isdone[]=new boolean[vtces.size()+1];
        boolean check[]=new boolean[vtces.size()+1];
        for(int i=1;i<=vtces.size();i++) {
            if (!isdone[i] && isCyclicDirected(i,isdone, check)) {
                return true;
            }
        }
        return false;
    }
    private boolean isCyclicDirected(int i,boolean isdone[],boolean check[]){
        if(check[i])
            return true;
        if(isdone[i])
            return false;
        check[i]=true;
        isdone[i]=true;
        Set<Integer> set=vtces.get(i).children.keySet();
        for(Integer ii:set){
            if(isCyclicDirected(ii,isdone,check))
                return true;
        }
        check[i]=false;
        return false;
    }
}
class union_find {
    int n;
    int[] sz;
    int[] par;

    union_find(int nval) {
        n = nval;
        sz = new int[n + 1];
        par = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            par[i] = i;
            sz[i] = 1;
        }
    }

    int root(int x) {
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }

    boolean find(int a, int b) {
        return root(a) == root(b);
    }

    int union(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        if (ra == rb)
            return 0;
        if(a==b)
            return 0;
        if (sz[a] > sz[b]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }
        par[ra] = rb;
        sz[rb] += sz[ra];
        return 1;
    }
}

#include <bits/stdc++.h>
using namespace std;
const int INF = (int)(1e9) + 10;
int N;
template <class Type>
class VeniceSet {
 private:
  std::multiset<Type> S;
  Type water_level = static_cast<Type>(0);

 public:
  VeniceSet(){};
  ~VeniceSet(){};
  void add(Type val) { S.insert(val + water_level); }
  void remove(Type val) { S.erase(S.find(val + water_level)); }
  void updateAll(Type val) { water_level += val; }
  Type getmin() { return (*S.begin()) - water_level; }
  int size() { return (int)S.size(); }
};
int main() {
  ios::sync_with_stdio(0);
  cin.tie(nullptr);
  cout.tie(nullptr);
  cin >> N;
  vector<long long> V(N + 1);
  vector<long long> T(N + 1);
  for (int i = 1; i <= N; i++) cin >> V[i];
  for (int i = 1; i <= N; i++) cin >> T[i];
  VeniceSet<long long> vset;
  for (int i = 1; i <= N; i++) {
    vset.add(V[i]);
    vset.updateAll(T[i]);
    long long ansi = T[i] * (long long)vset.size();
    while (vset.size() > 0) {
      long long delta = vset.getmin();
      if (delta >= 0) break;
      ansi -= llabs(delta);
      vset.remove(delta);
    }
    cout << ansi << ' ';
  }
  return 0;
}

