public class IlyaAndTheTree {

    int N = (int) 2e5 + 10;

    int n;
    int[] a;
    int[][] G;

    int[] res = new int[N];
    List<Integer> div = new ArrayList<>();
    int[] cnt = new int[N];

    void solve() {
        n = in.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        int[] fr = new int[n - 1], to = new int[n - 1];
        for (int i = 0; i < n - 1; i++) {
            fr[i] = in.nextInt() - 1;
            to[i] = in.nextInt() - 1;
        }
        G = build_graph(n, fr, to);

        res[0] = 0;
        dfs(0, -1);

        res[0] = a[0];
        for (int i = 1; i * i <= a[0]; i++) {
            if (a[0] % i == 0) {
                div.add(i);
                if (i != a[0] / i) div.add(a[0] / i);
            }
        }

        dfs(0, -1, 0);

        for (int i = 0; i < n; i++) {
            if (i > 0) out.print(' ');
            out.print(res[i]);
        }
    }

    void dfs(int u, int p, int d) {
        for (int v : G[u]) {
            if (v != p) {
                for (int i = 0; i < div.size(); i++) {
                    if (a[v] % div.get(i) == 0) cnt[i]++;
                    if (cnt[i] >= d) res[v] = Math.max(res[v], div.get(i));
                }
                dfs(v, u, d + 1);
                for (int i = 0; i < div.size(); i++) {
                    if (a[v] % div.get(i) == 0) cnt[i]--;
                }
            }
        }
    }

    void dfs(int u, int p) {
        for (int v : G[u]) {
            if (v != p) {
                res[v] = gcd(res[u], a[v]);
                dfs(v, u);
            }
        }
    }

    int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    int[][] build_graph(int n, int[] from, int[] to) {
        int[][] G = new int[n][];
        int[] cnt = new int[n];
        for (int i = 0; i < from.length; i++) {
            cnt[from[i]]++;
            cnt[to[i]]++;
        }
        for (int i = 0; i < n; i++) G[i] = new int[cnt[i]];
        for (int i = 0; i < from.length; i++) {
            G[from[i]][--cnt[from[i]]] = to[i];
            G[to[i]][--cnt[to[i]]] = from[i];
        }
        return G;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new IlyaAndTheTree().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

