  for (int i = (0); i < (n); i++) {
    if (p[s[i] - 'a'] == -1) {
      while (ch >= 0 && invp[ch] != -1) ch--;
      assert(ch >= 0);
      p[s[i] - 'a'] = ch;
      invp[ch] = s[i] - 'a';
