  }
}
void fixB() {
  int ch = 0;
  for (int i = (0); i < (n); i++) {
    if (p[s[i] - 'a'] == -1) {
      while (ch < k && invp[ch] != -1) ch++;
      assert(ch < k);
      p[s[i] - 'a'] = ch;
      invp[ch] = s[i] - 'a';
