		for (int i = 2; i <= c; i++)
		{
			for (int d : new int[]{-1, 1})
			{
				m[c][c - d*i] = 1;
				for (int k = -i; k <= i; k++)
				{
					m[c - d*k][c - d*i] = 1;
				}
			}
