template <class T>
inline void rd(T& x) {
  int f = 1;
  x = 0;
  char ch = nc();
  for (; !isdigit(ch); ch = nc())
    if (ch == '-') f = -1;
  for (; isdigit(ch); ch = nc()) x = x * 10 + ch - '0';
  x *= f;
}
const int maxn = 1e5 + 10;
struct op {
  int type;
  int t, l, r, v, s;
} querys[maxn];
int times[maxn], n;
inline int upper(double time) {
  int l = 1, r = n, ans = n + 1;
  while (l <= r) {
    int mid = l + r >> 1;
    if (times[mid] >= time) {
      ans = mid;
      r = mid - 1;
    } else {
      l = mid + 1;
    }
  }
  return ans;
}
inline int lower(double time) {
  int l = 1, r = n, ans = 0;
  while (l <= r) {
    int mid = l + r >> 1;
    if (times[mid] <= time) {
      ans = mid;
      l = mid + 1;
    } else {
      r = mid - 1;
    }
  }
  return ans;
}
int mark[maxn];
namespace Fenwick {
int tr[maxn];
inline void update(int x, int v) {
  for (; x < maxn; x += x & (-x)) tr[x] += v;
}
inline int query(int x) {
  int ans = 0;
  for (; x; x ^= x & (-x)) ans += tr[x];
  return ans;
}
inline int val(int x) { return query(x) - query(x - 1); }
inline int bs(int x) {
  int l = 0, r = n, ans = 0;
  while (l <= r) {
    int mid = l + r >> 1;
    if (query(mid) >= x) {
      ans = mid;
      r = mid - 1;
    } else {
      l = mid + 1;
    }
  }
  return ans;
}
inline int pre(int x) {
  int d = query(x - 1);
  return bs(d);
}
inline int suc(int x) { return bs(query(x) + 1); }
}  // namespace Fenwick
double cur[maxn];
const double inf = 2e20;
namespace Segment {
double tra[maxn << 2], tri[maxn << 2];
double lazy[maxn << 2];
int mk[maxn << 2];
inline void pushup(int rt) {
  tra[rt] = max(tra[rt << 1], tra[rt << 1 | 1]);
  tri[rt] = min(tri[rt << 1], tri[rt << 1 | 1]);
}
inline void pushdown(int rt) {
  if (!mk[rt]) return;
  mk[rt] = 0;
  mk[rt << 1] = 1;
  mk[rt << 1 | 1] = 1;
  lazy[rt << 1] += lazy[rt];
  lazy[rt << 1 | 1] += lazy[rt];
  tra[rt << 1] += lazy[rt];
  tri[rt << 1] += lazy[rt];
  tra[rt << 1 | 1] += lazy[rt];
  tri[rt << 1 | 1] += lazy[rt];
  lazy[rt] = 0;
}
void _update(double* target, int pos, double v, int l, int r, int rt) {
  if (l == r) {
    target[rt] = v;
    return;
  }
  pushdown(rt);
  int mid = l + r >> 1;
  if (pos <= mid)
    _update(target, pos, v, l, mid, rt << 1);
  else
    _update(target, pos, v, mid + 1, r, rt << 1 | 1);
  pushup(rt);
}
void setVoid(int pos) {
  _update(tra, pos, -inf, 1, n, 1);
  _update(tri, pos, inf, 1, n, 1);
}
void setZero(int pos) {
  _update(tra, pos, 0, 1, n, 1);
  _update(tri, pos, 0, 1, n, 1);
}
void build(int l, int r, int rt) {
  if (l == r) {
    tra[rt] = -inf;
    tri[rt] = inf;
    return;
  }
  int mid = l + r >> 1;
  build(l, mid, rt << 1);
  build(mid + 1, r, rt << 1 | 1);
  pushup(rt);
}
void update(int L, int R, double v, int l, int r, int rt) {
  if (L <= l && r <= R) {
    lazy[rt] += v;
    tra[rt] += v;
    tri[rt] += v;
    mk[rt] = 1;
    return;
  }
  pushdown(rt);
  int mid = l + r >> 1;
  if (L <= mid) update(L, R, v, l, mid, rt << 1);
  if (R > mid) update(L, R, v, mid + 1, r, rt << 1 | 1);
  pushup(rt);
}
double querya(int L, int R, int l, int r, int rt) {
  if (L <= l && r <= R) {
    return tra[rt];
  }
  pushdown(rt);
  int mid = l + r >> 1;
  double ans = -inf;
  if (L <= mid) ans = max(ans, querya(L, R, l, mid, rt << 1));
  if (R > mid) ans = max(ans, querya(L, R, mid + 1, r, rt << 1 | 1));
  return ans;
}
double queryi(int L, int R, int l, int r, int rt) {
  if (L <= l && r <= R) {
    return tri[rt];
  }
  pushdown(rt);
  int mid = l + r >> 1;
  double ans = inf;
  if (L <= mid) ans = min(ans, queryi(L, R, l, mid, rt << 1));
  if (R > mid) ans = min(ans, queryi(L, R, mid + 1, r, rt << 1 | 1));
  return ans;
}
}  // namespace Segment
double getV(double l) {
  int x = lower(l);
  if (x == 0) return 0;
  if (Fenwick::val(x) == 0) x = Fenwick::pre(x);
  if (x == 0) return 0;
  return cur[x];
}
double calc(double l) {
  int x = lower(l);
  if (x == 0) return 0;
  if (Fenwick::val(x) == 0) x = Fenwick::pre(x);
  if (x == 0) return 0;
  return (double)(l - times[x]) * cur[x] + Segment::querya(x, x, 1, n, 1);
}
const double eps = 1e-15;
bool check(double l, double r, double c) {
  double qa = -inf, qi = inf;
  if (fabs(l - r) <= eps) return fabs(calc(l) - c) <= eps;
  qa = max(calc(l), qa);
  qi = min(calc(l), qi);
  qa = max(calc(r), qa);
  qi = min(calc(r), qi);
  int lx = upper(l), rx = lower(r);
  if (lx <= rx && lx != 0 && rx != 0) {
    qa = max(qa, Segment::querya(lx, rx, 1, n, 1));
    qi = min(qi, Segment::queryi(lx, rx, 1, n, 1));
  }
  return qa - c >= 0 && qi - c <= 0;
}
int main() {
  int TAT;
  rd(TAT);
  for (int i = 1; i <= TAT; i++) {
    int type, t, l, r, v, s;
    rd(type);
    if (type == 1) {
      rd(t);
      rd(v);
      times[++n] = t;
      querys[i].type = 1;
      querys[i].t = t;
      querys[i].v = v;
    } else if (type == 2) {
      rd(t);
      querys[i].type = 2;
      querys[i].t = t;
    } else {
      rd(l);
      rd(r);
      rd(s);
      querys[i].type = 3;
      querys[i].l = l;
      querys[i].r = r;
      querys[i].s = s;
    }
  }
  sort(times + 1, times + n + 1);
  n = unique(times + 1, times + n + 1) - times - 1;
  if (n != 0) Segment::build(1, n, 1);
  for (int i = 1; i <= TAT; i++) {
    int type = querys[i].type;
    if (type == 1) {
      int t = querys[i].t, v = querys[i].v;
      int pos = upper(t);
      Fenwick::update(pos, 1);
      int pre = Fenwick::pre(pos), suc = Fenwick::suc(pos);
      cur[pos] = v;
      assert(pos != n + 1);
      Segment::setZero(pos);
      if (pre) {
        double delta = (double)cur[pre] * (times[pos] - times[pre]) +
                       Segment::querya(pre, pre, 1, n, 1);
        Segment::update(pos, pos, delta, 1, n, 1);
      }
      if (suc) {
        double delta = (double)(v - cur[pre]) * (times[suc] - times[pos]);
        Segment::update(suc, n, delta, 1, n, 1);
      }
    } else if (type == 2) {
      int t = querys[i].t;
      int pos = upper(t);
      int pre = Fenwick::pre(pos), suc = Fenwick::suc(pos);
      Fenwick::update(pos, -1);
      if (suc) {
        double delta =
            (double)(cur[pre] - cur[pos]) * (times[suc] - times[pos]);
        Segment::update(suc, n, delta, 1, n, 1);
      }
      Segment::setVoid(pos);
      cur[pos] = 0;
    } else {
      double l = querys[i].l, r = querys[i].r, s = -querys[i].s;
      int lx = upper(l);
      if (Fenwick::val(lx) == 0) lx = Fenwick::suc(lx);
      l = times[lx];
      if (s == 0) {
        printf("%d\n", querys[i].l);
        continue;
      }
      if (n == 0 || Fenwick::query(n) == 0 || !lx || l > r) {
        printf("-1\n");
        continue;
      }
      s += Segment::querya(lx, lx, 1, n, 1);
      bool ok = 0, done = 0;
      l -= eps * 2;
      r += eps * 2;
      for (int k = 0; k < 50; k++) {
        double mid = (l + r) / 2;
        if (check(l, mid, s)) {
          int t1 = lower(l), t2 = lower(mid);
          if (t1 == t2 && t1) {
            done = 1;
            double tt = times[t1];
            printf("%.9f\n", tt + (double)(s - calc(tt)) / getV(tt));
            break;
          }
          r = mid;
          ok = 1;
        } else {
          l = mid;
        }
      }
      if (done) continue;
      if (fabs(calc(l) - s) <= eps) ok = 1;
      if (ok)
        printf("%.9f\n", r);
      else
        printf("-1\n");
    }
  }
}

