const int INF = 1 << 29;
const int mod = 1000000007;
int dx[] = {1, 0, -1, 0};
int dy[] = {0, -1, 0, 1};
int h, w, l;
int mat[10][10];
int id[10][10];
bool visit[10][10];
int x[10];
int y[10];
pair<int, int> times[10];
int res[10];
struct tank {
  int s;
  double water;
  int x;
  int y;
  int height;
  vector<int> g;
};
tank ts[100];
tank bfs(int y, int x, int cnt) {
  tank res;
  int height = mat[y][x];
  id[y][x] = cnt;
  res.s = 900;
  res.water = 0;
  res.x = x;
  res.y = y;
  res.height = height;
  queue<pair<int, int> > que;
  que.push(pair<int, int>(y, x));
  while (!que.empty()) {
    pair<int, int> p = que.front();
    que.pop();
    y = p.first;
    x = p.second;
    for (int i = 0; i < 4; i++) {
      int y2 = y + dy[i];
      int x2 = x + dx[i];
      if (0 <= x2 && x2 < w && 0 <= y2 && y2 < h && mat[y2][x2] == height &&
          id[y2][x2] == -1) {
        id[y2][x2] = cnt;
        res.s += 900;
        que.push(pair<int, int>(y2, x2));
      }
    }
  }
  return res;
}
void calc(tank &t) {
  int over = max(0.0, t.water - 30 * t.s);
  t.water -= over;
  for (int i = 0; i < (int)t.g.size(); i++) {
    if (t.g[i] == -1) continue;
    tank &nxt = ts[t.g[i]];
    nxt.water += (double)over / t.g.size();
    calc(ts[t.g[i]]);
  }
}
void make_edge(tank &t) {
  int y = t.y;
  int x = t.x;
  memset(visit, false, sizeof(visit));
  queue<pair<int, int> > que;
  que.push(pair<int, int>(y, x));
  visit[y][x] = true;
  while (!que.empty()) {
    pair<int, int> p = que.front();
    que.pop();
    y = p.first;
    x = p.second;
    for (int i = 0; i < 4; i++) {
      int y2 = y + dy[i];
      int x2 = x + dx[i];
      if (0 <= x2 && x2 < w && 0 <= y2 && y2 < h) {
        if (mat[y2][x2] == t.height && !visit[y2][x2]) {
          visit[y2][x2] = true;
          que.push(pair<int, int>(y2, x2));
        } else if (mat[y2][x2] < t.height && !visit[y2][x2]) {
          t.g.push_back(id[y2][x2]);
        }
      } else {
        t.g.push_back(-1);
      }
    }
  }
}
void simulate(int fx, int fy, int fp) {
  memset(id, -1, sizeof(id));
  for (int i = 0; i < 100; i++) ts[i].g.clear();
  int cnt = 0;
  for (int i = 0; i < h; i++)
    for (int j = 0; j < w; j++) {
      if (id[i][j] == -1) {
        ts[cnt] = bfs(i, j, cnt);
        cnt++;
      }
    }
  for (int i = 0; i < cnt; i++) make_edge(ts[i]);
  int now = 0;
  for (int i = 0; i < l; i++) {
    int dif = times[i].first - now;
    now = times[i].first;
    ts[id[fy][fx]].water += fp * dif;
    calc(ts[id[fy][fx]]);
    tank &tan = ts[id[y[times[i].second]][x[times[i].second]]];
    res[times[i].second] = floor(tan.water / tan.s);
  }
}
int main() {
  int fx, fy, fp;
  while (cin >> w >> h && (w || h)) {
    cin >> fx >> fy >> fp;
    for (int i = 0; i < h; i++)
      for (int j = 0; j < h; j++) {
        cin >> mat[i][j];
      }
    cin >> l;
    for (int i = 0; i < l; i++) {
      cin >> times[i].first >> x[i] >> y[i];
      times[i].second = i;
    }
    sort(times, times + l);
    simulate(fx, fy, fp);
    for (int i = 0; i < l; i++) {
      cout << res[i] << endl;
    }
  }
  return 0;
}

