#include <bits/stdc++.h>
using namespace std;
const long long N = 10100, oo = 1 << 28;
long long n, k, l;
long long lha[111], dis[25][25], tdis[N];
bool inp[N];
vector<long long> adl[N], ones, halat[25];
map<pair<long long, long long>, long long> ans;
long long javab;
inline void bfs(long long v) {
  long long depth = 0;
  bool chk[N] = {};
  queue<long long> list;
  chk[v] = 1;
  list.push(v);
  list.push(-1);
  long long u;
  while (list.size() - 1) {
    u = list.front();
    list.pop();
    if (u == -1) {
      list.push(-1);
      ++depth;
      continue;
    }
    tdis[u] = depth;
    for (int i = 0; i < adl[u].size(); ++i)
      if (!chk[adl[u][i]]) {
        list.push(adl[u][i]);
        chk[adl[u][i]] = 1;
      }
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin >> n >> k >> l;
  for (int i = 1, x; i <= k; ++i) {
    cin >> x;
    inp[x] = 1;
  }
  inp[n + 1] = inp[n];
  for (int i = n; i > 1; --i) {
    inp[i] ^= inp[i - 1];
  }
  for (int i = 1; i <= l; ++i) cin >> lha[i];
  sort(lha + 1, lha + l + 1);
  for (int i = 1; i <= n + 1; ++i)
    for (int j = 1; j <= l; ++j) {
      if (i + lha[j] > n + 1) break;
      adl[i].push_back(i + lha[j]);
      adl[i + lha[j]].push_back(i);
    }
  for (int i = 1; i <= n + 1; ++i)
    if (inp[i]) ones.push_back(i);
  if (ones.size() & 1) {
    cout << -1 << "\n";
    return 0;
  }
  for (int i = 0; i < ones.size(); ++i) {
    long long v = ones[i];
    memset(tdis, 0, sizeof tdis);
    bfs(v);
    for (int j = 0; j < ones.size(); ++j)
      if (!tdis[ones[j]])
        dis[i][j] = oo;
      else
        dis[i][j] = tdis[ones[j]];
  }
  for (int i = (1 << ones.size()) - 1, x, cnt; i > 0; --i) {
    x = i;
    cnt = 0;
    while (x) {
      if (x & 1) ++cnt;
      x /= 2;
    }
    halat[cnt - 1].push_back(i);
  }
  for (int i = 0; i < ones.size(); ++i)
    for (int j = 0; j < halat[i].size(); ++j) {
      long long now = halat[i][j];
      ans[pair<long long, long long>(i, now)] = oo;
      long long x = halat[i][j];
      long long cnt = 0;
      while (x) {
        if (x & 1) {
          if (now - (1 << cnt) == 0)
            ans[pair<long long, long long>(i, now)] =
                ((ans[pair<long long, long long>(i, now)]) < (dis[i][cnt])
                     ? (ans[pair<long long, long long>(i, now)])
                     : (dis[i][cnt]));
          else
            ans[pair<long long, long long>(i, now)] =
                ((ans[pair<long long, long long>(i, now)]) <
                         (ans[pair<long long, long long>(i - 1,
                                                         now - (1 << cnt))] +
                          dis[i][cnt])
                     ? (ans[pair<long long, long long>(i, now)])
                     : (ans[pair<long long, long long>(i - 1,
                                                       now - (1 << cnt))] +
                        dis[i][cnt]));
        }
        x /= 2;
        ++cnt;
      }
    }
  javab =
      ans[pair<long long, long long>(ones.size() - 1, (1 << ones.size()) - 1)];
  if (javab >= oo)
    cout << -1 << "\n";
  else
    cout << javab / 2 << "\n";
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;
int bx[2], p[N], vis[N], n;
bool in[N];
vector<int> ans;
bool dfs(int pos, int step) {
  vis[pos] = step;
  ans.push_back(pos);
  if (!vis[p[pos]]) return dfs(p[pos], step + 1);
  int t = step + 1 - vis[p[pos]];
  return bx[0] == bx[1] || t == 1 || t % 2 == 0;
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &p[i]);
    in[p[i]] = 1;
    if (i == p[i]) bx[0] = bx[1] = i;
  }
  if (bx[0] == 0) {
    for (int i = 1; i <= n; i++) {
      if (i == p[p[i]]) {
        bx[0] = i;
        bx[1] = p[i];
        break;
      }
    }
  }
  if (bx[0] == 0)
    puts("NO");
  else {
    vis[bx[0]] = vis[bx[1]] = 1;
    bool flag = 1;
    for (int i = 1; flag && i <= n; i++)
      if (!in[i]) flag = dfs(i, 1);
    if (!flag) {
      puts("NO");
      return 0;
    }
    for (int i = 1; flag && i <= n; i++)
      if (!vis[i]) flag = dfs(i, 1);
    if (!flag) {
      puts("NO");
      return 0;
    }
    puts("YES");
    if (bx[0] != bx[1]) printf("%d %d\n", bx[0], bx[1]);
    int len = ans.size();
    for (int i = 0; i < len; i++) printf("%d %d\n", bx[i & 1], ans[i]);
  }
}

