int HtoS(int h, int m, int s) { return h * 3600 + m * 60 + s * 60; }
string StoH(double sec) {
  int h = (int)sec / 3600;
  int m = (int)sec % 3600 / 60;
  double ms = sec - (h * 3600 + m * 60);
  char str[1000];
  if (ms < 10.0) {
    sprintf(str, "%02d %02d 0%.6f", h, m, ms);
  } else {
    sprintf(str, "%02d %02d %.6f", h, m, ms);
  }
  return str;
}
struct State {
  int use;
  double t;
  complex<double> p;
  int last;
  State() { ; }
  State(int use, double t, complex<double> p, int last)
      : use(use), t(t), p(p), last(last) {
    ;
  }
  bool operator<(const State &rhs) const { return t > rhs.t; }
};
const double SPEED_N = 80.0 / 60.0;
const double SPEED_C = 50.0 / 60.0;
complex<double> sp, ep;
int startTime;
int endTime;
int n;
vector<complex<double> > route[20];
vector<double> ts[20];
int bisect(State state, int target) {
  int lower = 0;
  int upper = 1 << 20;
  while (lower != upper) {
    int mid = (lower + upper) / 2;
    int cycle = mid / ts[target].size();
    int index = mid % ts[target].size();
    double et = cycle * ts[target].back() + ts[target][index] + startTime;
    complex<double> p = route[target][(index + 1) % route[target].size()];
    if (abs(state.p - p) / SPEED_N <= et - state.t) {
      upper = mid;
    } else {
      lower = mid + 1;
      if (et >= endTime) {
        break;
      }
    }
  }
  return lower;
}
pair<double, complex<double> > calc(State state, int target) {
  int from = bisect(state, target);
  complex<double> vect =
      route[target][(from + 1) % route[target].size()] - route[target][from];
  vect /= abs(vect);
  double lower;
  double upper;
  {
    int cycle = from / ts[target].size();
    int index = from % ts[target].size();
    lower = cycle * ts[target].back() + startTime;
    if (index != 0) {
      lower += ts[target][index - 1];
    }
    upper = cycle * ts[target].back() + ts[target][index] + startTime;
  }
  double stime = lower;
  pair<double, complex<double> > ret(endTime + 1, complex<double>(0, 0));
  if (lower > endTime) {
    return ret;
  }
  from %= ts[target].size();
  for (int i = 0; i < (int)(50); i++) {
    double mid = (lower + upper) / 2.0;
    double t = mid - stime;
    complex<double> tp = route[target][from] + vect * (t * SPEED_C);
    if (abs(state.p - tp) / SPEED_N <= mid - state.t) {
      upper = mid;
      ret = make_pair(mid, tp);
    } else {
      lower = mid;
    }
  }
  return ret;
}
bool visit[1 << 14][15];
double times[1 << 14][15];
int main() {
  int test;
  scanf("%d", &test);
  while (test--) {
    for (int i = 0; i < (int)(1 << 14); i++)
      for (int j = 0; j < (int)(15); j++) {
        times[i][j] = 1e+100;
      }
    memset((visit), false, sizeof(visit));
    {
      double sx, sy, ex, ey;
      scanf("%lf %lf %lf %lf", &sx, &sy, &ex, &ey);
      sp = complex<double>(sx, sy);
      ep = complex<double>(ex, ey);
    }
    {
      int h, m, s;
      scanf("%d:%d:%d", &h, &m, &s);
      startTime = HtoS(h, m, s);
      scanf("%d:%d:%d", &h, &m, &s);
      endTime = HtoS(h, m, s);
    }
    scanf("%d", &n);
    for (int i = 0; i < (int)(n); i++) {
      route[i].clear();
      ts[i].clear();
      int k;
      scanf("%d", &k);
      for (int j = 0; j < (int)(k); j++) {
        int x, y;
        scanf("%d %d", &x, &y);
        route[i].push_back(complex<double>(x, y));
      }
      double pt = 0.0;
      for (int j = 0; j < (int)(k); j++) {
        ts[i].push_back(pt +
                        abs(route[i][j] - route[i][(j + 1) % route[i].size()]) /
                            SPEED_C);
        pt = ts[i].back();
      }
    }
    priority_queue<State> que;
    que.push(State(0, startTime, sp, 14));
    int cnt = 0;
    pair<int, double> ans(-1, -1e+100);
    while (!que.empty()) {
      cnt++;
      State state = que.top();
      que.pop();
      if (visit[state.use][state.last]) {
        continue;
      }
      visit[state.use][state.last] = true;
      {
        double et = state.t + abs(state.p - ep) / SPEED_N;
        if (et > endTime) {
          continue;
        }
        pair<int, double> lans(__builtin_popcount(state.use), -et);
        ans = max(ans, lans);
      }
      for (int i = 0; i < (int)(n); i++) {
        if ((state.use >> i) & 1) {
          continue;
        }
        int nuse = state.use | (1 << i);
        if (visit[nuse][i]) {
          continue;
        }
        pair<double, complex<double> > next = calc(state, i);
        if (next.first > endTime) {
          continue;
        }
        if (next.first - times[nuse][i] > EPS) {
          continue;
        }
        times[nuse][i] = next.first;
        que.push(State(nuse, next.first, next.second, i));
      }
    }
    printf("%d\n%s\n", ans.first, StoH(-ans.second).c_str());
  }
}

