  for(const char cc : s){
    const int c = static_cast<int>(cc);
    const int dist = (c + 5) / 10;

    if(pos < dist){
      REP(i,dist-pos) putchar('>');
    }else{
      REP(i,pos-dist) putchar('<');
    }
    pos = dist;

    if(memo[pos] < c){
      REP(i,c-memo[pos]) putchar('+');
    }else{
      REP(i,memo[pos]-c) putchar('-');
    }
    memo[pos] = c;

    putchar('.');
  }

  return 0;
}

