  int indL = min(len, (l - 1) / len + 1), indR = max(0, (r + 1) / len - 1);
  int oldl = l, oldr = r;
  int counter = 0;
  for (int i = indL; i <= indR; i++) {
    for (int lu : lucky) {
      counter += cnt[i][lu + bonus[i]];
    }
  }
  while (l / len < indL && l <= r) {
    counter += lucky.count(mas[l] + bonus[l / len]);
    l++;
  }
  while (r / len > indR && r > l) {
    counter += lucky.count(mas[r] + bonus[r / len]);
    r--;
  }
  if (oldl / len == oldr / len)
    for (int i = l; i <= oldr; i++)
      counter += lucky.count(mas[i] + bonus[oldr / len]);
  return counter;
}
void update(int l, int r, int num) {
  int indL = min(len, l / len + 1), indR = max(0, r / len - 1);
  int oldl = l, oldr = r;
