struct NODE {
  int lchd, rchd;
  int lm, rm;
  int limit;
} node[MAXN];
struct CONS {
  int par, chd;
  bool left;
  bool operator<(const CONS& b) const {
    if (par != b.par) {
      return par < b.par;
    } else if (left != b.left) {
      return left;
    } else {
      return chd < b.chd;
    }
  }
} cons[MAXM];
int n, m;
bool MakeTree(int id, int r, int b) {
  if (b >= r) {
    return false;
  }
  if (node[id].lm > 0) {
    if (node[id].lm <= id) {
      return false;
    }
    if (!MakeTree(id + 1, node[id].rm > 0 ? min(r, node[id].rm) : r,
                  node[id].lm)) {
      return false;
    }
    node[id].lchd = id + 1;
    node[id].lm = max(id + 1, node[id + 1].limit);
  } else {
    node[id].lchd = 0;
  }
  if (node[id].rm > 0 || b > id) {
    if (node[id].rm <= node[id].lm || node[id].limit >= r) {
