const int N = 3e5 + 6;
vector<int> adj[N];
int sub[N], big[N], ans[N], p[N];
void dfs(int u) {
  sub[u] = 1;
  for (auto v : adj[u]) {
    dfs(v);
    sub[u] += sub[v];
    if (sub[v] > sub[big[u]]) big[u] = v;
  }
}
bool is_centeroid(int u, int root) {
  int mx = max(sub[big[u]], sub[root] - sub[u]);
  return 2 * mx <= sub[root];
}
void solve(int u) {
  if (adj[u].size() == 0) {
    ans[u] = u;
    return;
  }
  for (auto v : adj[u]) solve(v);
  int t = ans[big[u]];
  while (!is_centeroid(t, u)) t = p[t];
  ans[u] = t;
}
