template <typename T> struct ImosNijikansu {
    int n;
    vector<T> v;
    vector<pair<int, T>> pre, prepre;
    ImosNijikansu(int n) { init(n); } ImosNijikansu() {}
    void init(int _n) { n = _n; v.resize(n, 0); pre.clear(), prepre.clear(); }
    void set(int l, int r) {
        v[l] += 1;
        if(l + 1 < n) v[l + 1] += 1;
        if (r < n) v[r] -= 2;

        prepre.push_back({ r, -(r-l)*2+1 });
        pre.push_back({ r, -1LL*(1 + 2 * (r-l) - 1)*(r-l)/2 });
    }
    void build() {
        rep(i, 1, v.size()) v[i] += v[i - 1];
        fore(p, prepre) if(p.first < n) v[p.first] += p.second;
        rep(i, 1, v.size()) v[i] += v[i - 1];
        fore(p, pre) if (p.first < n) v[p.first] += p.second;
        rep(i, 1, v.size()) v[i] += v[i - 1];
    }
    T operator[](int i) { return v[i]; }
    void dump() {
        cout << "dump : [";
        for (T i : v) cout << "\t" << i;
        cout << " ]" << endl;
    }
};
template <typename T> struct ImosNijikansuSpread {
    int n;
    vector<T> v;
    ImosNijikansu<T> imos1, imos2;
    vector<int> sub;
    ImosNijikansuSpread(int n) { init(n); } ImosNijikansuSpread() {}
    void init(int _n) { n = _n; v.resize(n); imos1.init(n); imos2.init(n); sub.clear(); }
    void set_start1(int cent, int len) { // from 1 to len^2
        imos1.set(cent, cent + len);
        imos2.set(n - 1 - cent, n - 1 - cent + len);
        sub.push_back(cent);
    }
    void set_start0(int cent, int len) { // from 0 to len^2
        if(cent + 1 < n) imos1.set(cent + 1, cent + 1 + len);
        if (n - 1 - cent + 1 < n) imos2.set(n - 1 - cent + 1, n - 1 - cent + 1 + len);
    }
    void build() {
        imos1.build();
        imos2.build();

        rep(i, 0, n) v[i] += imos1[i];
        rep(i, 0, n) v[i] += imos2[n - 1 - i];
        fore(i, sub) v[i]--;
    }
    T operator[](int i) { return v[i]; }
    void dump() {
        cout << "dump : [";
        for (T i : v) cout << "\t" << i;
        cout << " ]" << endl;
    }
};
