int check(ll mi) {
    rep(i, 0, N) w[i] = 0;
    rep(i, 0, N) {
        if (v[i] + AM < mi) return 0;

        int ok = 0, ng = N;
        while (ok + 1 != ng) {
            int md = (ok + ng) / 2;
            if (mi <= v[i] + max(0LL, AM - 1LL * md * md)) ok = md;
            else ng = md;
        }

        int L = max(0, i - ok);
        int R = min(N, i + ok + 1);
        w[L]++;
        if (R < N) w[R]--;
    }
    rep(i, 1, N) w[i] += w[i - 1];
    rep(i, 0, N) if (w[i] == N) return 1;
    return 0;
}
