struct UndirectedGraph {
  vector<vector<int>> g;
  vector<int> clr;
  vector<int> dis;
  int V;
  UndirectedGraph(int V)
      : V(V), g(vector<vector<int>>(V)), clr(vector<int>(V, 0)) {}
  void add_edge(int u, int v) {
    g[u].push_back(v);
    g[v].push_back(u);
  }
  bool dfs_nib(int v, int c) {
    clr[v] = c;
    for (auto x : g[v]) {
      if (clr[x] == c) return false;
      if (clr[x] == 0 && !dfs_nib(x, -c)) return false;
    }
    return true;
  }
  bool isNib() {
    bool ret = true;
    for (int i = 0; i < V; i++)
      if (clr[i] == 0) {
        if (!dfs_nib(i, 1)) {
          ret = false;
          break;
        }
      }
    return ret;
  }
  void bfs(int st) {
    dis = vector<int>(V, 1000000000);
    vector<bool> checked(V, false);
    dis[st] = 0;
    queue<int> q;
    q.push(st);
    while (!q.empty()) {
      auto now = q.front();
      q.pop();
      checked[now] = true;
      for (auto x : g[now])
        if (!checked[x]) {
          dis[x] = dis[now] + 1;
          q.push(x);
        }
    }
  }
};
signed main() {
  int n;
  cin >> n;
  UndirectedGraph g(n);
  char s[n][n];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      char t;
      cin >> t;
      s[i][j] = t;
      if (t == '1' && i > j) {
        g.add_edge(i, j);
      }
    }
  }
  if (!g.isNib()) {
    cout << -1 << endl;
    return 0;
  }
  int ans = 0;
  for (int i = 0; i < n; i++) {
    g.bfs(i);
    int x = *max_element(g.dis.begin(), g.dis.end());
    ans = max(x, ans);
  }
  cout << ans + 1 << endl;
  return 0;
}

