            long [][]matrix = new long[n][m];
            for(int i = 0; i < n; i++ ){
                matrix[i] = readlongarr();
            }
            long ans = Long.MAX_VALUE;
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    long base = matrix[i][j] - i - j;
                    long [][]dp = new long[n][m];
                    for(int k = 0; k < n; k++){
                        for(int l = 0; l < m; l++){
                            dp[k][l] = Long.MAX_VALUE/2;
                        }
                    }
                    outer: for(int k = 0; k < n; k++){
                        for(int l = 0; l < m; l++){
                            if(matrix[k][l]<base + k + l){
                                break outer;
                            }
                            dp[k][l] = Math.min(k>=1?dp[k - 1][l]: Long.MAX_VALUE/2,
                                    l>=1?dp[k][l - 1]: Long.MAX_VALUE/2) + matrix[k][l] - base - k - l;
