double getPackWidth(vector<int> &v) {
    int n = v.size();
    double ret = v[0] + v[n-1];
    for (int i=0; i+1<n; ++i) {
        ret += sqrt(pow(v[i] + v[i+1], 2) - pow(v[i] - v[i+1], 2));
    }
    return ret;
}

