			long max=a[end-2];

			long low=(long)Math.ceil(b[i-1]/2.0);
			long high=b[i-1];

			long z=binary_search(low,high,min,max);

			a[end-1]=z;
			a[start-1]=b[i-1]-a[end-1];

		}

		for(long x: a)
			System.out.print(x+" ");



	}

	static long binary_search(long low,long high,long min,long max){

		long temp=0;

		long start=low;
		long end=high;

		while(start<=end){

			long mid=(start+end)/2;

			if(mid>=max&&(high-mid)<=min)
				temp=mid;

			if(mid<max||high-mid>min)
				start=mid+1;
			else
				end=mid-1;
		}

		return temp;
	}

}

