bool operator<(const complex<long double> &a, const complex<long double> &b) {
  return (abs((real(a)) - (real(b))) < EPS) ? imag(a) < imag(b)
                                            : real(a) < real(b);
}
bool operator==(const complex<long double> &a, const complex<long double> &b) {
  return (abs((a) - (b)) < EPS);
}
