int dfs(int x,int zt,int fg)
{
	if(x<0)return 0;
	if(dp[x][zt][fg]!=-1)return dp[x][zt][fg];
	int i,j,tmp=N;
	for(i=0;i<(1<<n);i++)
	{
		if(i&zt)continue;
		ll v=a[x];
		int flag=1,tp=bit[x]+1;
		for(j=0;j<n;j++)if(i&(1<<j))
		{
			if(j>=x){flag=0;break;}
			//printf("v:%I64d aj:%I64d \n",v,a[j]);
			if(v%a[j]!=0){flag=0;break;}
			v/=a[j];
			tp-=bit[j];
		}
		if(flag)
		{
			int fg1=fg;
			if(!fg1&&i!=(1<<n)-1-(1<<x))fg1=1;
			tp=tp+dfs(x-1,zt|(1<<x)|(i),fg1);
			if(bit[x]==1)tp--;
			//printf("x:%d i:%d tp:%d \n",x,i,tp);
			if(x==n-1)
			{
				if(!fg1&&i!=(1<<n)-1-(1<<x))tp++;
			}
			if(tmp>tp)tmp=tp;
		}
	}
	dp[x][zt][fg]=tmp;
	return tmp;
}
