using namespace std;
const int nmax = 50;
const int lmax = 20;
const int base = 61;
double d[1 << lmax];
unsigned short int h[1 << lmax][nmax + 1];
char s[nmax + 1][lmax + 1];
int val(char x) {
  if ('a' <= x && x <= 'z') return 1 + x - 'a';
  return x - 'A' + 27;
}
int main() {
  int n;
  fscanf(stdin, "%d", &n);
  for (int i = 0; i < n; ++i) fscanf(stdin, "%s", s[i]);
  int m = strlen(s[0]);
  d[(1 << m) - 1] = 0;
  for (int i = 1; i < (1 << m); ++i) {
    int lst = 0;
    for (int j = 0; j < m; ++j) {
      if (i & (1 << j)) lst = j;
    }
    for (int j = 0; j < n; ++j) {
      h[i][j] = h[i - (1 << lst)][j] * base + val(s[j][m - 1 - lst]);
    }
  }
  for (int i = (1 << m) - 2; i >= 0; --i) {
    int nr_zero = 0;
    for (int j = 0; j < m; ++j) {
      if ((i & (1 << j)) == 0) {
        ++nr_zero;
        d[i] += d[i + (1 << j)];
      }
    }
    sort(h[i], h[i] + n);
    int unic = 0;
    for (int j = 0; j < n;) {
      int ind = j;
      while (ind < n && h[i][ind] == h[i][j]) ++ind;
      if (ind - j == 1) ++unic;
      j = ind;
    }
    d[i] = (1 + d[i] / nr_zero) * (n - unic) / n;
  }
  fprintf(stdout, "%.12lf\n", d[0]);
  return 0;
}

