bool adj(int a, int b) {
  if (0 <= a && a <= w - 2 && 0 <= b && b <= w - 2) {
    return a == b;
  }
  if (w - 2 <= a && a <= w - 2 + h - 3 && w <= b && b <= w + h - 3) {
    return a - (w - 2) == b - w;
  }
  if (w - 2 + h - 3 <= a && w + h - 1 <= b) {
    return a - (w - 2 + h - 3) == b - (w + h - 1);
  }
  return false;
}
