    for (int stage_idx = 0; stage_idx < N; stage_idx++) {
      int H, W;
      char stage[50 * 50];
      memset(stage, '.', sizeof(stage));
      scanf("%d %d", &H, &W);
      map<char, Belongings> layer;
      for (int y = 0; y < H; y++) {
        char line[51];
        scanf("%s", line);
        for (int x = 0; x < W; x++) {
          stage[y * W + x] = line[x];
          Belongings& it = layer[stage[y * W + x]];
          it.left = min(it.left, x);
          it.right = max(it.right, x);
          it.upper = min(it.upper, y);
          it.lower = max(it.lower, y);
        }
      }
      bool is_safe = false;
      vector<char> order;
      for (map<char, Belongings>::iterator it = layer.begin();
           it != layer.end(); it++) {
        order.push_back(it->first);
      }
      sort(order.begin(), order.end());
      char hypothesis[50 * 50];
