        long [] results = new long[nums.length * 2];

        long lastMax = nums[0];
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] - lastMax <= 0) {
                results[i] = 0;
                results[results.length - i - 1] = nums[i];
                lastMax = nums[i];
            } else {
                results[i] = nums[i] - lastMax;
                results[results.length - i - 1] = lastMax;
            }
        }

        return results;
    }
}

