int add(int a, int b) {
  a += b - MOD;
  return (a < 0 ? a + MOD : a);
}
int mul(int a, int b) { return (1ll * a * b) % MOD; }
int Pow(int a, int b) {
  return b ? (1ll * (b & 1 ? a : 1) * (Pow(mul(a, a), b >> 1))) % MOD : 1;
}
int inv(int a) { return Pow(a, MOD - 2); }
void dfs(int v = 1, int _par = 0) {
  c[a[v]].push_back(v);
  for (int u : adj[v])
    if (u ^ _par) par[u] = v, h[u] = h[v] + 1, dfs(u, v);
}
void set_color(int u, int v, int color) {
  while (u ^ v) {
    if (h[u] < h[v]) swap(u, v);
    if (a[u] && a[u] ^ color) {
      flag = true;
      return;
    }
    a[u] = color, u = par[u];
  }
  if (a[u] && a[u] ^ color) {
    flag = true;
    return;
  }
  a[u] = color;
}
void dfs_dp(int v = 1, int par = 0) {
  for (int u : adj[v])
    if (u ^ par) dfs_dp(u, v);
  int cnt = 1;
  for (int u : adj[v])
    if (u ^ par) cnt = mul(cnt, add(dp[0][u], dp[1][u]));
  dp[1][v] = (v <= k ? 0 : cnt);
  if (adj[v].size() == 0 || (adj[v].size() == 1 && adj[v][0] == par)) {
    dp[0][v] = (v <= k);
    return;
  }
  if (v <= k)
    dp[0][v] = cnt;
  else
    for (int u : adj[v])
      if (u ^ par)
        dp[0][v] = add(dp[0][v],
                       mul(dp[0][u], mul(cnt, inv(add(dp[0][u], dp[1][u])))));
}
