      set_color(c[i][j], c[i][j + 1], i);
  if (flag) return cout << "0\n", 0;
  for (int i = 1; i <= n; i++) idx[i] = (a[i] ? a[i] : ++cnt);
  for (int i = 1; i <= n; i++) c[i].clear();
  for (int i = 1; i <= n; i++)
    for (int u : adj[i])
      if (idx[u] ^ idx[i]) c[idx[i]].push_back(idx[u]);
  for (int i = 1; i <= n; i++) adj[i].clear();
  for (int i = 1; i <= n; i++)
