void solve()
{
    int n, p;
    cin >> n >> p;
    vi tmp;
    repn(i, 1, n){
        cin >> arr[i];
        tmp.pb(arr[i]);
    }

    sort(all(tmp));
    tmp.erase(unique(all(tmp)), tmp.end());
    int c = 0;
    rep(i, 0, sz(tmp)){
        fw[tmp[i]] = c;
        bw[c] = tmp[i];
        c++;
    }

    repn(i, 1, n){
        st[fw[arr[i]]].insert(i);
    }

    set<int> ready;
    set<int> vacant;
    vacant.insert(N+1);
    queue<int> q;

    int ind = 0;
    ll rt = 0;
    ll curt = 0;

    while(ind < sz(tmp)){

        q.push(*st[fw[tmp[ind]]].begin());
        ans[q.front()] = tmp[ind];
        vacant.insert(*st[fw[tmp[ind]]].begin());

        st[fw[tmp[ind]]].erase(st[fw[tmp[ind]]].begin());
        while(sz(st[fw[tmp[ind]]])){
            ready.insert(*st[fw[tmp[ind]]].begin());
            st[fw[tmp[ind]]].erase(st[fw[tmp[ind]]].begin());
        }

        rt = tmp[ind] + p;
        ind++;
        if(ind == sz(tmp)) curt = infi;
        else curt = tmp[ind];

        while(sz(q)){
            while(curt <= rt){

                while(sz(st[fw[curt]])){
                    int nw = *st[fw[curt]].begin();
                    if(nw < *vacant.begin()){
                        q.push(nw);
                        ans[nw] = curt;
                        vacant.insert(nw);
                    }
                    else {
                        ready.insert(nw);
                    }
                    st[fw[curt]].erase(st[fw[curt]].begin());
                }

                ind++;
                if(ind == sz(tmp)) curt = infl;
                else curt = tmp[ind];
            }
            int t = q.front();
            vacant.erase(t);
            q.pop();

            int nw = infi;
            if(sz(ready)) nw = *ready.begin();
            if(nw < *vacant.begin()){
                q.push(nw);
                ans[nw] = rt;
                vacant.insert(nw);
                ready.erase(ready.begin());
            }

            if(sz(q)) chmax(rt, ans[q.front()] + p);
        }
    }
    repn(i, 1, n) cout << ans[i] + p << " ";
    cout << endl;
}

