        {
            mid = (double) start + (((double) end - (double)start) /2);

            if (mid * mid == num)
            {
                ans = Math.floor(mid);
                break;
            }

            if (mid * mid < num) {
                start = (long) (Math.floor(mid) + 1);
                ans = Math.floor(mid);
            }

            else {
                end =(long) Math.floor(mid) - 1;
            }
        }
        ans = Math.floor(mid);

        double increment = 0.1;
        for (int i = 0; i <9; i++) {
            while (ans * ans <= num) {
                ans += increment;
            }
            ans = ans - increment;
            increment = increment / 10;
        }
        return (double)ans;
    }


