const int N = 1e5 + 10, inf = 0x3f3f3f3f;
struct QwQ {
  int tp, t, x, y, id;
  bool operator<(const QwQ &a) const { return t == a.t ? tp < a.tp : t > a.t; }
};
QwQ q[N << 1], tmp[N << 1];
int n, m, k, c[N << 2];
pair<int, int> tree[N], ans[N];
void reset(int x) {
  for (; x <= k; x += (x & (-x))) tree[x] = make_pair(inf, inf);
}
void update(int x, pair<int, int> val) {
  for (; x <= k; x += (x & (-x)))
    tree[x] = (tree[x].first < val.first ? tree[x] : val);
}
pair<int, int> query(int x) {
  pair<int, int> ans = make_pair(inf, inf);
  for (; x >= 1; x -= (x & (-x)))
    ans = (ans.first < tree[x].first ? ans : tree[x]);
  return ans;
}
void cdq(int l, int r) {
  if (l == r) return;
  int mid = (l + r) >> 1;
  cdq(l, mid);
  cdq(mid + 1, r);
  int i = l, j = mid + 1, cnt = l - 1;
  while (i <= mid && j <= r) {
    if (q[i].x <= q[j].x) {
      tmp[++cnt] = q[i];
      if (q[i].tp == 0) update(k - q[i].y + 1, make_pair(q[i].t, q[i].id));
      i++;
    } else {
      tmp[++cnt] = q[j];
      if (q[j].tp == 1)
        ans[q[j].id] = (ans[q[j].id].first < query(k - q[j].y + 1).first
                            ? ans[q[j].id]
                            : query(k - q[j].y + 1));
      j++;
    }
  }
  while (i <= mid) {
    tmp[++cnt] = q[i];
    i++;
  }
  while (j <= r) {
    tmp[++cnt] = q[j];
    if (q[j].tp == 1)
      ans[q[j].id] = (ans[q[j].id].first < query(k - q[j].y + 1).first
                          ? ans[q[j].id]
                          : query(k - q[j].y + 1));
    j++;
  }
  for (int i = l; i <= r; i++) {
    reset(k - q[i].y + 1);
    q[i] = tmp[i];
  }
}
