    c[++k] = f;
  }
  for (int i = 1; i <= m; i++) {
    int b, l, r;
    scanf("%d%d%d", &l, &r, &b);
    q[i + n] = (QwQ){1, b, l, r, i};
    c[++k] = r;
  }
  sort(c + 1, c + 1 + k);
  k = unique(c + 1, c + 1 + k) - c - 1;
  for (int i = 1; i <= n + m; i++)
    q[i].y = lower_bound(c + 1, c + 1 + k, q[i].y) - c;
  sort(q + 1, q + 1 + n + m);
  cdq(1, n + m);
  for (int i = 1; i <= m; i++) {
    if (ans[i].first == inf)
      printf("-1 ");
    else
      printf("%d ", ans[i].second);
  }
