import java.util.Scanner;

public class C {

    private static Scanner in;

    private static long n, s, count;
    private static int[] digitsN = new int[20];
    private static long[] val = new long[20];

    private static void solve() {
        n = in.nextLong();
        for (int i = 19; i >= 0; i--) {
            digitsN[i] = (int) (n % 10);
            n /= 10;
        }
        for (int i = 18; i >= 0; i--)
            val[i] = val[i + 1] * 10 + 9;
        s = in.nextLong();
        search(0, 0);
        System.out.println(count);
    }

    private static void search(int p, long v) {
        if (p == 20) {
            count++;
            return;
        }
        int max = digitsN[p];
        int min;
        if (val[p] != 0)
            min = (int) ((s - v) / val[p]);
        else if (v >= s)
            min = 0;
        else
            min = Integer.MAX_VALUE;
        min = Math.max(0, min);
        for (int i = min; i <= max; i++)
            search(p + 1, v + val[p] * i);
    }

    public static void main(String[] args) {
        in = new Scanner(System.in);
        solve();
        System.exit(0);
    }
}

