template <typename T>
struct slope_trick {
  T offset_l, offset_r, zero_height;
  multiset<T> L;
  multiset<T> R;
  slope_trick() {
    offset_l = 0;
    offset_r = 0;
    zero_height = 0;
  }
  T zero_start() {
    if (L.empty()) {
      return numeric_limits<T>::min();
    } else {
      return *L.rbegin() + offset_l;
    }
  }
  T zero_end() {
    if (R.empty()) {
      return numeric_limits<T>::max();
    } else {
      return *R.begin() + offset_r;
    }
  }
  inline size_t size() { return L.size() + R.size(); }
  void add_simple(const T &center, const T &height = 0) {
    T s = zero_start(), e = zero_end();
    zero_height += height;
    if (s <= center && center <= e) {
      L.insert(center - offset_l);
      R.insert(center - offset_r);
    } else if (center < s) {
      L.insert(center - offset_l);
      L.insert(center - offset_l);
      L.erase(prev(L.end()));
      R.insert(s - offset_r);
      zero_height += abs(center - s);
    } else {
      R.insert(center - offset_r);
      R.insert(center - offset_r);
      R.erase(R.begin());
      L.insert(e - offset_r);
      zero_height += abs(center - e);
    }
  }
  void prefix_min() { R.clear(); }
  void suffix_min() { L.clear(); }
  void local_min(const T &strip_width) {
    if (!L.empty()) {
      offset_l -= strip_width;
    }
    if (!R.empty()) {
      offset_r += strip_width;
    }
  }
  void add(const slope_trick &other) {}
  void add_with_destroy(slope_trick &other) {}
};
int n;
vector<pair<int, int>> P;
void read() {
  cin >> n;
  for (int i = 0; i < n; i++) {
    int x, y;
    cin >> x >> y;
    P.push_back({x + y, x - y});
  }
}
void solve() {
  slope_trick<int64_t> dp;
  sort(P.begin(), P.end());
  int last_x = 0;
  for (int i = 0; i < ((int)P.size());) {
    int delta = P[i].first - last_x;
    last_x = P[i].first;
    dp.local_min(delta);
    while (i < ((int)P.size()) && P[i].first == last_x) {
      dp.add_simple(P[i].second);
      i++;
    }
  }
  assert(dp.zero_height % 2 == 0);
  cout << dp.zero_height / 2 << '\n';
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int T = 1;
  for (int test = 1; test <= T; test++) {
    read();
    solve();
  }
  return 0;
}

