// モジュール
ll sp_hash(const string &s, const string &p) {
    stack<ll> lstk;
    stack<char> lop;
    for (const char &c : s) {

        switch(c) {
            case '[': continue;
            case ']':
                {
                    ll c1 = lstk.top(); lstk.pop();
                    ll c2 = lstk.top(); lstk.pop();
                    ll res;
                    char op = lop .top(); lop .pop();
                    switch (op) {
                        case '+': res = c1 | c2; break;
                        case '*': res = c1 & c2; break;
                        case '^': res = c1 ^ c2; break;
                    }
                    lstk.push(res);
                }
                break;
            case 'a':
            case 'b':
            case 'c':
            case 'd':
                lstk.push(p[c - 'a'] - '0');
                break;
            case '+':
            case '*':
            case '^':
                lop.push(c);
                break;
        }

    }

    return lstk.top();

}

