const double INF = LLONG_MAX/5;
struct Node;
Node* nullNode;
struct Node{
    Node* l = nullNode;
    Node* r = nullNode;
    ll sum = 0;
    ll mn = INF;
};
Node* root;
set<int> st;
map<int, ll> speed;
void combineNodes(Node* left, Node* right, Node* cur){
    left = (left) ? (left) : (nullNode);
    right = (right) ? (right) : (nullNode);
    cur->mn = min(left->mn, min(right->mn, left->sum + right->mn));
    cur->sum = left->sum + right->sum;
}
Node* update(Node* cur, int l, int r, ll idx, ll val, bool reset = false){
    if(cur == nullNode || cur == nullptr){
        cur = new Node();
    }
    if(l == r){
        cur->sum = val;
        cur->mn = (reset) ? (INF) : val;
        return cur;
    }
    int mid = (l+r)/2;
    if(idx <= mid){
        cur->l = update(cur->l, l, mid, idx, val);
    }else{
        cur->r = update(cur->r, mid+1, r, idx, val);
    }
    combineNodes(cur->l , cur->r, cur);
    return cur;
}
