pair<double,ll> query(Node* cur, int l, int r, int qL, int qR, ll val){
    if(r < qL || l > qR || (cur == nullNode || cur == nullptr)){
        return {INF, 0};
    }
    if(qL <= l && r <= qR){
        Node* temp = cur;
        ll sum = temp->sum;
        while(l != r){
            int mid = (l+r)/2;
            //Debug{} << print(mid);
            //Debug{} << print(temp->mn);
            //Debug{} << print(temp->l->mn);
            //Debug{} << print(temp->r->mn+val + temp->l->sum);
            if(temp->l->mn + val <= 0){
                temp = temp->l;
                r = mid;
            }else if(temp->r->mn + val + temp->l->sum <= 0){
                val += temp->l->sum;
                temp = temp->r;
                l = mid+1;
            }else{
                return {INF, sum};
            }
        }
        if(temp->sum+val > 0){
            return {INF, sum};
        }
        double time = l + 1.0*val/(-speed[l]);
        return (time <= qR) ? (make_pair(time, sum)) : make_pair(INF, sum);
    }
    int mid = (l+r)/2;
    pair<double,ll> left = query(cur->l, l, mid, qL, qR, val);
    if(left.ff != INF){
        return left;
    }
    pair<double, ll> right = query(cur->r, mid+1, r, qL, qR, val+left.ss);
    right.ss += left.ss;
    return right;
}
void addEvent(ll t, ll s){
    st.insert(t);
    speed[t] = s;
    auto it = st.upper_bound(t);
    if(it == st.end()){
        if(s < 0){
            root = update(root, 1, 1e9, t, -INF);
        }
    }else{
        root = update(root, 1, 1e9, t, s*(*it-t));
    }
    it = st.lower_bound(t);
    if(it != st.begin()){
        it--;
        root = update(root, 1, 1e9, *it,speed[*it]*(t-*it));
    }
}
void deleteEvent(int t){
    auto lower = st.lower_bound(t);
    root = update(root, 1, 1e9, t, 0, true);
    if(lower != st.begin()){
        lower--;
        auto high = st.upper_bound(t);
        int s = speed[*lower];
        if(high == st.end()){
            if(s < 0){
                root = update(root, 1, 1e9, *lower, -INF);
            }
        }else{
            root = update(root, 1, 1e9, *lower, s*(*high-*lower));
        }
    }
    st.erase(t);
    speed.erase(t);
}
