unsigned long long w[N];
unsigned long long wfac[N];
void init() {
  for (int i = 2; i <= N - 1; ++i)
    if (d[i] == 0) {
      for (int j = 1; i * j <= N - 1; ++j) {
        if (d[i * j] == 0) d[i * j] = i;
      }
    }
  for (int i = 1; i <= N - 1; ++i) {
    if (d[i] == i) w[i] = rnd();
  }
  for (int i = 1; i <= N - 1; ++i) {
    wfac[i] = wfac[i - 1];
    int cur = i;
    while (cur > 1) {
      wfac[i] ^= w[d[cur]];
      cur /= d[cur];
    }
  }
}
