		for (int i = 0; i < arr.length; i++) {
			arr[i] = i+1;
		}

		for (int i = 1; i < arr.length; i = i + 2) {
			int tmp = arr[i];
			arr[i] = arr[i-1];
			arr[i-1] = tmp;
		}

