inline long long gcd(long long a, long long b) {
  if (a == b) return a;
  if (a == 0) return b;
  if (b == 0) return a;
  if (a > b)
    return gcd(a % b, b);
  else
    return gcd(a, b % a);
}
vector<string> splitstring(string s, char* tokens) {
  bool b[256];
  memset(b, 0, sizeof(b));
  for (int i = 0; i < strlen(tokens); i++) {
    b[int(tokens[i])] = true;
  }
  vector<string> r;
  string t = "";
  for (int i = 0; i < s.size(); i++) {
    if (b[s[i]]) {
      if (!t.empty()) {
        r.push_back(t);
        t.clear();
      }
    } else {
      t += s[i];
    }
  }
  if (!t.empty()) {
    r.push_back(t);
    t.clear();
  }
  return r;
}
vector<int> kmp(string s, string t) {
  string r = s + "\r" + t;
  int sz = r.size();
  int ssz = s.size();
  int tsz = t.size();
  vector<int> p(sz);
  p[0] = 0;
  int j;
  for (int i = 1; i < sz; ++i) {
    j = p[i - 1];
    while (j > 0 && r[i] != r[j]) j = p[j - 1];
    if (r[i] == r[j]) ++j;
    p[i] = j;
  }
  vector<int> ans;
  for (int i = s.size() + 1; i < sz; i++) {
