public class Kyoya {
    public static final int mod = 1000000007;
    public static final int max = 1001;
    public static int[][] triangle;

    public static void initPascalTriangle() {
        triangle = new int[max][max];

        for(int i=0; i<max; i++) {
            triangle[i][0] = 1;
        }

        for(int i=1; i<max; i++) {
            for(int j=1; j<=i; j++) {
                triangle[i][j] = ((triangle[i-1][j-1]%mod) + (triangle[i-1][j] % mod) % mod);
            }
        }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        int[] c = new int[k];
        for(int i=0; i<k; i++) {
            c[i] = sc.nextInt();
        }
        sc.close();

        initPascalTriangle();

        int result = 1;
        int count = 0;
        for(int i=0; i<k; i++) {
            result = (result * triangle[count + c[i] - 1][c[i] - 1]) % mod;
            count += c[i];
        }

        System.out.println(result);
    }
}

