vector<P> getIntersectCC(Circle c1, Circle c2){
  vector<P> res;
  double r1 = c1.r, r2 = c2.r, d;
  P p1 = c1.c, p2 = c2.c;
  d = abs(p1-p2);

  if(d < EPS && abs(r1-r2) < EPS) return res; //テ・ツ??ッツシツ妥」ツ?ィテ・ツ??ッツシツ津」ツ?古・ツ青古」ツ?佚・ツ?エテ・ツ青暗ッツシツ暗ァツ?。テゥツ卍静・ツ?凝」ツ?ォテ」ツ?ェテ」ツつ凝」ツ?淌」ツつ?ゥツ卍、テ・ツ、ツ姪ッツシツ?
  if(r1 + r2< d - EPS || d + EPS < abs(r1-r2)) return res; //テ、ツコツ、テ」ツつ湘」ツつ嘉」ツ?ェテ」ツ??

  double a = (r1*r1 - r2*r2 + d*d) / (2*d);
  double h = sqrt(max(r1*r1 - a*a, 0.0));
  P tmp1 = p1 + a / d * (p2-p1);
  P tmp2 = h / d * (p2-p1);

  if(abs(tmp2) < EPS) res.push_back(tmp1);
  else {
    res.push_back(P(real(tmp1) - imag(tmp2), imag(tmp1) + real(tmp2)));
    res.push_back(P(real(tmp1) + imag(tmp2), imag(tmp1) - real(tmp2)));
  }
  return res;
}


