double get( int id ){
  double ret = C[id].r * 2.0 * M_PI;
  //cout << C[id].c << " "<< C[id].r << " " << ret << endl;
  if( F[id].empty() ) return ret;
  sort( F[id].begin(), F[id].end() );
  PA pa = F[id][0];
  for(int i=0;i<(int)F[id].size();i++){
    //cout << F[id][i].first / M_PI * 180.0 << " "<< F[id][i].second / M_PI * 180.0 << endl;
    if( F[id][i].first <= pa.second ){      
      pa.first = min( pa.first, F[id][i].first );
      pa.second = max( pa.second, F[id][i].second );
    } else {
      ret -= (pa.second-pa.first) * C[id].r;
      pa = F[id][i];
    }
  }
  ret -= (pa.second - pa.first ) * C[id].r;
  return ret;
}

