public class B1470 {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        int t = fs.nextInt();

        StringBuilder output = new StringBuilder();

        while (t-- > 0) {
            int n = fs.nextInt();
            int nums[] = new int[n];

            for (int i = 0; i < n; i++) {
                nums[i] = fs.nextInt();
            }

            Map<Integer, Integer> freqMap = new HashMap<>();

            for (int i = 0; i < nums.length; i++) {
                int canonicalGroup = findCanonicalGroup(nums[i]);

                freqMap.put(canonicalGroup, freqMap.getOrDefault(canonicalGroup, 0) + 1);
            }

            int zeroResult = 0;
            int zeroPlusResult = 0;

            for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
                if (entry.getValue() % 2 == 0) {
                    zeroPlusResult += entry.getValue();
                }

                zeroResult = Math.max(zeroPlusResult, entry.getValue());
            }

            int q = fs.nextInt();

            while (q-- > 0) {
                int w = fs.nextInt();

                if (w == 0) {
                    output.append(zeroResult).append("\n");
                } else {
                    output.append(Math.max(zeroPlusResult, zeroResult)).append("\n");
                }
            }
        }

        System.out.print(output);
    }

    private static int findCanonicalGroup(int num) {
        List<Factor> primeFactors = findPrimeFactors(num);

        int group = 1;

        for (Factor factor : primeFactors) {
            if (factor.times % 2 == 1) {
                group *= factor.num;
            }
        }

        return group;
    }

    private static List<Factor> findPrimeFactors(int num) {
        List<Factor> primeFactors = new ArrayList<>();

        int c = 0;

        while (num % 2 == 0) {
            c++;
            num /= 2;
        }

        if (c > 0) {
            primeFactors.add(new Factor(2, c));
        }

        int sqrtNum = (int) Math.sqrt(num);

        for (int i = 3; i <= sqrtNum && num > 0; i++) {
            if (num % i == 0) {
                c = 0;

                while (num > 0 && num % i == 0) {
                    c++;
                    num /= i;
                }

                primeFactors.add(new Factor(i, c));
            }
        }

        if (num > 2) {
            primeFactors.add(new Factor(num, 1));
        }

        return primeFactors;
    }

    private static class Factor {
        int num;
        int times;

        public Factor(int num, int times) {
            this.num = num;
            this.times = times;
        }
    }

    static class FastScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public FastScanner(FileInputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

