long long par[100005];
long long find_set(long long v) {
  if (v == par[v]) return v;
  return par[v] = find_set(par[v]);
}
void make_set(long long v) { par[v] = v; }
void union_sets(long long a, long long b) {
  a = find_set(a);
  b = find_set(b);
  if (a != b) {
    if (a > b) swap(a, b);
    par[b] = a;
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  long long n, m, i, j, x, y, ans = 0, cnt = 0;
  cin >> n >> m;
  vector<pair<long long int, long long int> > s;
  s.push_back({1000000007, 1000000007});
  for (i = 1; i <= n; i++) {
    cin >> x >> y;
    s.push_back({y, x});
  }
  sort((s).begin(), (s).end());
  reverse((s).begin(), (s).end());
  for (i = 0; i <= n; i++) {
    make_set(i);
  }
  for (i = 1; i <= n; i++) {
    long long nxt = m - s[i].second + 1;
    if (nxt < 0) continue;
    long long ff = find_set(nxt);
    if (ff > 0) {
      ans += s[i].first;
      union_sets(ff, ff - 1);
      union_sets(nxt, ff - 1);
      cnt++;
      if (cnt >= m) {
        break;
      }
    }
  }
  cout << ans;
  return 0;
}

