bool kakutei() {
  bool change = true;
  while (change) {
    change = false;
    for (int i = 0; i < (int)(3); ++i) {
      for (int j = 0; j < (int)(3); ++j) {
        if (dices[0][i][j] == 0) {
          for (int k = 0; k < (int)(3); ++k) {
            if (dices[1][k][j] > 0 && dices[2][k][2 - i] > 0) {
              dices[0][i][j] =
                  dice_right[dices[1][k][j] - 1][dices[2][k][2 - i] - 1];
              if (dices[0][i][j] == 0) return false;
              change = true;
            }
          }
        }
        if (dices[1][i][j] == 0) {
          for (int k = 0; k < (int)(3); ++k) {
            if (dices[0][k][j] > 0 && dices[2][i][2 - k] > 0) {
              dices[1][i][j] =
                  dice_right[dices[2][i][2 - k] - 1][dices[0][k][j] - 1];
              if (dices[1][i][j] == 0) return false;
              change = true;
            }
          }
        }
        if (dices[2][i][j] == -1) {
          for (int k = 0; k < (int)(3); ++k) {
            if (dices[0][2 - j][k] > 0 && dices[1][i][k] > 0) {
              dices[2][i][j] =
                  dice_right[dices[0][2 - j][k] - 1][dices[1][i][k] - 1];
              if (dices[2][i][j] == 0) return false;
              change = true;
            }
          }
        }
      }
    }
  }
  return true;
}
void dfs() {
  vector<vector<vector<int> > > copy_dices = dices;
  for (int i = 0; i < (int)(3); ++i) {
    for (int j = 0; j < (int)(3); ++j) {
      if (dices[0][i][j] == 0) {
        for (int k = 0; k < (int)(6); ++k) {
          bool clear = true;
          for (int l = 0; l < (int)(3); ++l) {
            if (dices[1][l][j] > 0)
              if (dices[1][l][j] == k + 1 || dices[1][l][j] + k + 1 == 7)
                clear = false;
            if (dices[2][l][2 - i] > 0)
              if (dices[2][l][2 - i] == k + 1 ||
                  dices[2][l][2 - i] + k + 1 == 7)
                clear = false;
          }
          if (clear) {
            dices[0][i][j] = k + 1;
            if (!kakutei()) {
              dices = copy_dices;
              continue;
            }
            dfs();
            dices = copy_dices;
          }
        }
        return;
      }
    }
  }
  for (int i = 0; i < (int)(3); ++i) {
    for (int j = 0; j < (int)(3); ++j) {
      if (dices[1][i][j] == 0) {
        for (int k = 0; k < (int)(6); ++k) {
          bool clear = true;
          for (int l = 0; l < (int)(3); ++l)
            if (dices[0][l][j] == k + 1 || dices[0][l][j] + k + 1 == 7)
              clear = false;
          if (clear) {
            dices[1][i][j] = k + 1;
            if (!kakutei()) {
              dices = copy_dices;
              continue;
            }
            dfs();
            dices = copy_dices;
          }
        }
        return;
      }
    }
  }
  int sum = 0;
  for (int i = 0; i < (int)(3); ++i) {
    for (int j = 0; j < (int)(3); ++j) {
      sum += dice_right[dices[0][2 - j][2] - 1][dices[1][i][2] - 1];
    }
  }
  ans.push_back(sum);
}
