  int ed = itv[1].l + (itv[1].r - itv[1].l) / p * p;
  for (int i = 2; i <= n; ++i) {
    if (ed + t > itv[i].r) continue;
    if (ed + t > itv[i].l) {
      int add = (itv[i].r - (ed + t)) / p;
      ed = ed + t + add * p;
      ans += add;
    } else {
      int add = (itv[i].r - itv[i].l) / p;
      ed = itv[i].l + (itv[i].r - itv[i].l) / p * p;
      ans += add;
    }
  }
