  set<int> ss;
  if (a == 0)
    for (int i = 0; i < (n); i++) ss.insert(solve(i, 1) ^ solve(n - 1 - i, 1));
  else if (a == 1) {
    for (int i = 0; i < (n - 1); i++) {
      ss.insert(solve(i, 1) ^ solve(n - 1 - i, 2));
      ss.insert(solve(i, 1) ^ solve(n - 1 - i, 3));
    }
    ss.insert(solve(n - 1, 1));
  } else if (a == 2) {
    for (int i = 0; i < (n - 2); i++) {
      ss.insert(solve(i + 1, 2) ^ solve(n - 2 - i, 2));
      ss.insert(solve(i + 1, 3) ^ solve(n - 2 - i, 3));
    }
    ss.insert(solve(n - 1, 3));
  } else {
    for (int i = 0; i < (n - 2); i++) {
      ss.insert(solve(i + 1, 2) ^ solve(n - 2 - i, 3));
    }
    ss.insert(solve(n - 1, 2));
  }
  for (int k = 0;; k++)
    if (ss.find(k) == ss.end()) return ans = k;
}
