public class D {

	static ArrayList<Integer>[] adj;
	static int indexChange;

	public static void main(String[] args) throws Exception {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
//		BufferedReader f = new BufferedReader(new FileReader("src/out.rtf"));
		PrintWriter out = new PrintWriter(System.out);
		Scanner s = new Scanner(System.in);

		int n = Integer.parseInt(f.readLine());
		adj = new ArrayList[n];
		for(int i = 0; i < n; i++) adj[i] = new ArrayList<>();
		int[] a = new int[n], change = new int[n];
		String[] split = f.readLine().split("\\s+");
		for(int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(split[i])-1;
			adj[i].add(a[i]);
			adj[a[i]].add(i);
			change[i] = a[i];
		}
		int root = -1;
		for(int i = 0; i < n; i++) {
			if(change[i] == i && root == -1) {
				root = i;
			} else if(change[i] == i) {
				change[i] = root;
			}
		}
		boolean[] V = new boolean[n];
		for(int i = 0; i < n; i++) {
			if(!V[i]) {
//				System.out.println("I " + i);
				indexChange = -1;
				V[i] = true;
				dfs(i, -1, V);
				if(indexChange != -1) {
					if(root == -1) {
						root = i;
						change[i] = root;
					} else {
						change[indexChange] = root;
					}
					adj[indexChange].add(root);
				}
			}
		}
		int res = 0;
		for(int i = 0; i < n; i++) if(a[i] != change[i]) res++;
		out.println(res);
		for(int i = 0; i < n; i++) out.print((change[i]+1) + " ");
		out.println();
		out.close();
	}

	static void dfs(int at, int parent, boolean[] V) {
//		System.out.printf("At node %d\n", at+1);
		for(Integer i : adj[at]) {
//			System.out.printf("Node %d is looking at %d\n", at+1, i+1);
			if(V[i] && parent != i) {
				indexChange = at;
			} else if(!V[i]) {
//				System.out.printf("Going from %d to %d\n", at+1, i+1);
				V[i] = true;
				dfs(i, at, V);
			}
		}
//		System.out.printf("Done with Node %d\n", at+1);
	}
}

import java.io.*;
import java.util.*;

public class D{
	public static boolean DEBUG = false;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(System.out);
		StringTokenizer st;

		st = getst(br);

		int n = nextInt(st);
		int m = nextInt(st);
		int k = nextInt(st);

		long[] a = new long[n];
		st = getst(br);

		for(int i = 0; i < n; i++){
			a[i] = nextInt(st);
		}

		long[][] v = new long[n][n];

		for(int i = 0; i < k; i++){
			st = getst(br);
			v[nextInt(st)-1][nextInt(st)-1] = nextInt(st);
		}

		HashMap<Integer, long[]> dp = new HashMap<Integer, long[]>();
		HashMap<Integer, long[]> next = new HashMap<Integer, long[]>();

		dp.put(0, new long[n]);
		Arrays.fill(dp.get(0), -1);

		for(int i = 0; i < m; i++){
			for(int x : dp.keySet()){
				for(int j = 0; j < n; j++){
					int y = (x | (1 << j));
					if(y != x){
						if(!next.keySet().contains(y)){
							next.put(y, new long[n]);
							Arrays.fill(next.get(y), -1);
						}

						long newVal = 0;

						for(int t = 0; t < n; t++){
							if(dp.get(x)[t] >= 0){
								//debug(t + " " + j + " " + v[t][j]);
								newVal = Math.max(newVal, dp.get(x)[t] + v[t][j]);
							}
						}

						newVal += a[j];

						next.get(y)[j] = Math.max(next.get(y)[j], newVal);
					}
				}
			}
			HashMap<Integer, long[]> temp = dp;
			dp = next;
			next = temp;
			next.clear();

			if(DEBUG){
				for(int x : dp.keySet()){
					debug(Integer.toString(x, 2) + " " + Arrays.toString(dp.get(x)));
				}
				debug("");
			}
		}

		long ans = 0;

		for(int x : dp.keySet()){
			for(int i = 0; i < n; i++){
				ans = Math.max(ans, dp.get(x)[i]);
			}
		}

		pw.println(ans);

		br.close();
		pw.close();
	}

	public static void debug(Object o){
		if(DEBUG){
			System.out.println("~" + o);
		}
	}

	public static StringTokenizer getst(BufferedReader br) throws Exception{
		return new StringTokenizer(br.readLine(), " ");
	}

	public static int nextInt(BufferedReader br) throws Exception{
		return Integer.parseInt(br.readLine());
	}

	public static int nextInt(StringTokenizer st) throws Exception{
		return Integer.parseInt(st.nextToken());
	}

	public static long nextLong(BufferedReader br) throws Exception{
		return Long.parseLong(br.readLine());
	}

	public static long nextLong(StringTokenizer st) throws Exception{
		return Long.parseLong(st.nextToken());
	}

	public static double nextDouble(BufferedReader br) throws Exception{
		return Double.parseDouble(br.readLine());
	}

	public static double nextDouble(StringTokenizer st) throws Exception{
		return Double.parseDouble(st.nextToken());
	}
}

