bool intersectSS(const L& s, const L& t){
    return ( ccw(s[0],s[1],t[0]) *ccw(s[0],s[1],t[1]) <= 0 ) &&
        ( ccw(t[0],t[1],s[0]) *ccw(t[0],t[1],s[1]) <= 0 );
}
bool strictItsSS(const L& s, const L& t){
    return ( ccw(s[0],s[1],t[0]) *ccw(s[0],s[1],t[1]) == -1 ) &&
        ( ccw(t[0],t[1],s[0]) *ccw(t[0],t[1],s[1]) == -1);
}
bool intersectSP(const L& s, const P& p){
    return abs(s[0]-p) +abs(s[1]-p) -abs(s[1]-s[0]) < EPS;
}
bool strictItsSP(const L& l, const P &p){
    return intersectSP(l,p) && !EQ(l[0],p) && !EQ(l[1],p);
}

P projection(const L& l, const P& p) {
    double t = dot(p-l[0], l[0]-l[1]) / norm(l[0]-l[1]);
    return l[0] + t*(l[0]-l[1]);
}

double distanceLP(const L &l, const P &p) {
    return abs(p - projection(l, p));
}
/*
double distanceLL(const L &l, const L &m) {
    return intersectLL(l, m) ? 0 : distanceLP(l, m[0]);
}
double distanceLS(const L &l, const L &s) {
    if (intersectLS(l, s)) return 0;
    return min( distanceLP(l, s[0]), distanceLP(l, s[1]) );
}
*/
double distanceSP(const L &s, const P &p) {
    const P r = projection(s, p);
    if (intersectSP(s, r)) return abs(r - p);
    return min(abs(s[0]-p), abs(s[1]-p));
}
double distanceSS(const L &s, const L &t) {
    if (intersectSS(s, t)) return 0;
    return min(min(distanceSP(s, t[0]), distanceSP(s, t[1])),
               min(distanceSP(t, s[0]), distanceSP(t, s[1])));
}

P crosspointLL(const L &l, const L &m) {
    double A = cross(l[1]-l[0], m[1]-m[0]);
    double B = cross(l[1]-l[0], l[1]-m[0]);
    return m[0] + B /A *(m[1]-m[0]);
}

VP crosspointLC(const L &l, const C &c){
    VP ret;
    P mid = projection(l, c.p);
    double dlp = distanceLP(l, c.p);
    if(EQ(dlp, c.r)){
        ret.push_back(mid);
        return ret;
    }
    if(dlp > c.r){
        return ret;
    }
    P d = sqrt(c.r*c.r -dlp*dlp)/abs(l[1]-l[0]) *(l[1]-l[0]);
    ret.push_back(mid+d);
    ret.push_back(mid-d);
    return ret;
}
VP crosspointSC(const L &s, const C &c){
    VP ret;
    VP cp = crosspointLC(s,c);
    for(int i=0; i<(int)cp.size(); i++){
        if(dot(s[1]-s[0], cp[i]-s[0]) < EPS) continue;
        if(norm(s[1]-s[0]) < norm(cp[i]-s[0]) +EPS) continue;
        ret.push_back(cp[i]);
    }
    return ret;
}
VP crosspointCC(C a, C b){
    VP ps;
    if(a.r < b.r) swap(a, b);
    P ab = b.p-a.p;
    double dist = abs(ab);
    if(GE(dist, a.r +b.r) || LE(dist, abs(a.r-b.r))){
        return ps;
    }
    if(EQ(dist, a.r+b.r) || EQ(dist, a.r-b.r)){
        ps.push_back( a.p +ab*(a.r/dist) );
        return ps;
    }
    double l = ((a.r*a.r -b.r*b.r)/dist +dist) /2;
    double n = sqrt(a.r*a.r -l*l);
    P mid = a.p + (ab)*(l/dist);
    P d = ab *(n/dist) *P(0,1);
    ps.push_back(mid+d);
    ps.push_back(mid-d);
    return ps;
}

double getangle(P p, P a, P b){
    a -= p;
    b -= p;
    return acos(dot(a,b)/(abs(a)*abs(b)));
}
double getangle(P a, P b){
    return acos(dot(a,b)/(abs(a)*abs(b)));
}

VP crosspointSDA(const L& l, const C& c, double as, double ae){
    VP cp = crosspointSC(l, c);
    VP ret;
    for(int i=0; i<(int)cp.size(); i++){
        P cpvec = cp[i] - c.p;
        if(cpvec.Y <0) cpvec = -cpvec;
        double angle = getangle(P(1,0), cpvec);
        if(as <= angle && angle <= ae){
            ret.push_back(cp[i]);
        }
    }
    return ret;
}
VP crosspointDADA(const C &a, const C& b, double as, double ae){
    VP cp = crosspointCC(a,b);
    VP ret;
    for(int i=0; i<(int)cp.size(); i++){
        P cen[2] = {a.p, b.p};
        double angle[2];
        for(int j=0; j<2; j++){
            P cpv = cp[i] -cen[j];
            if(cpv.Y <0) cpv = -cpv;
            angle[j] = getangle(P(1,0), cpv);
        }
        if(as <= angle[0] && angle[0] <= ae && as <= angle[1] && angle[1] <= ae){
            ret.push_back(cp[i]);
        }
    }
    return ret;
}
bool isParallel(const P &a, const P &b){
    return abs(cross(a,b)) < EPS;
}
bool isParallel(const L &a, const L &b){
    return isParallel(a[1]-a[0], b[1]-b[0]);
}

