import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class E_Carrots {
	static int n;
	public static void main(String[] args) throws NumberFormatException, IOException
	{
		BufferedReader scan = new BufferedReader(new InputStreamReader(System.in));
		String[] in = scan.readLine().split(" ");

		n = parse(in[0]);
		int k = parse(in[1]);

		PriorityQueue<Carrot> set = new PriorityQueue<Carrot>();
		long ans = 0;
		in = scan.readLine().split(" ");
		int val;
		for(int i = 0; i < n; i++)
		{
			val = parse(in[i]);
			if(val == 1)
			{
				k--;
				ans ++;
				continue;
			}
			set.add( new Carrot(parse(in[i]), i) );
		}

		Carrot temp;
		k -= set.size();

		while(k > 0)
		{
			temp = set.poll();

			temp.cut();
			k--;
			set.add(temp);
		}


		for(Carrot c : set)
			ans += c.time();

		System.out.println(ans);
	}

	public static int parse(String num)
	{
		return Integer.parseInt(num);
	}

	static class Carrot implements Comparable<Carrot>
	{
		long maxLen, length;
		long numCarrots;
		int id;

		public Carrot(int size, int i)
		{
			length = size;
			maxLen = size;
			numCarrots = 1;
			id = i;
		}

		public long cut()
		{
			numCarrots ++;
			maxLen = length / numCarrots + (length % numCarrots == 0 ? 0 : 1);
			return 1;
		}

		public long time()
		{
			long remain = length % numCarrots;

			return remain * (maxLen * maxLen) + (numCarrots - remain) * (length / numCarrots ) * (length / numCarrots);
		}

		public long delta()
		{
			if(length == 1 || numCarrots == length) return 0;

			long remain = length % (numCarrots + 1);
			long len = length / (numCarrots + 1);

			return time() - (remain * (len + 1) * (len + 1) + (numCarrots - remain) * len * len);
		}

		@Override
		public int compareTo(Carrot c) {
			long delta = delta();
			long cDelta = c.delta();

			if(delta == cDelta)
				return id - c.id;

			return Long.compare(cDelta, delta);
		}

		public String toString()
		{
			return length + " split into " + numCarrots + " carrots"; 
		}

	}
}

#include <bits/stdc++.h>
using namespace std;
const int N = (int)1e5 + 100;
const int K = 350;
int A[N];
int B[N];
int id[N];
int lef[N];
int rig[N];
int tot[N];
bool block[N];
void compute(int bl) {
  if (tot[bl] >= K) return;
  for (int i = lef[bl]; i <= rig[bl]; i++) {
    if (A[i] - tot[bl] < lef[bl]) {
      B[i] = i;
    } else {
      B[i] = B[A[i] - tot[bl]];
    }
  }
}
int gob(int idx) {
  if (tot[id[idx]] >= K) return idx;
  return B[idx];
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  ;
  int n, q;
  cin >> n >> q;
  int sz = K + 1;
  int cnt = 0;
  for (int i = 2; i <= n; i++) {
    cin >> A[i];
    sz++;
    if (sz > K) {
      cnt++;
      sz = 1;
      lef[cnt] = i;
    }
    rig[cnt] = i;
    id[i] = cnt;
  }
  for (int i = 2; i <= n; i++) {
    if (rig[id[i]] == i) compute(id[i]);
  }
  int typ;
  int li, ri, x;
  int lf, rf;
  for (int i = 1; i <= q; i++) {
    cin >> typ;
    if (typ == 1) {
      cin >> li >> ri >> x;
      lf = li;
      rf = ri;
      while (li <= ri) {
        if (lef[li] >= lf && rig[ri] <= rf) {
          if (tot[id[li]] < n) {
            tot[id[li]] += x;
            compute(id[li]);
          }
          li = rig[li] + 1;
        } else {
          A[li] = max(1, A[li] - x);
          if (li == rig[id[li]] || li == rf) compute(id[li]);
          li++;
        }
      }
    } else {
      cin >> li >> ri;
      while (li != ri) {
        if (li > ri) swap(li, ri);
        if (id[li] == id[ri]) {
          if (gob(li) == gob(ri)) {
            ri = max(1, A[ri] - tot[id[ri]]);
          } else {
            ri = gob(ri);
            ri = max(1, A[ri] - tot[id[ri]]);
          }
        } else {
          ri = max(1, A[ri] - tot[id[ri]]);
        }
      }
      cout << ri << "\n";
    }
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const double kEps = 1E-9;
const int kMaxN = 20;
int nf, ne, ns, rf, re, rs, df, de;
double ans, lenf, lene, lens;
int cnt[13];
double dp[2][kMaxN + 1][kMaxN + 1];
double ff[13], ee[13];
pair<double, int> seq[kMaxN << 1 | 1];
int buf[(kMaxN << 1) + 2], *sum = buf + 1;
void Solve() {
  int t = 0;
  for (int i = 0; i < 11; ++i)
    for (int j = 1; j <= cnt[i]; ++j) {
      seq[t++] = make_pair(i - lens, 1);
      seq[t++] = make_pair(i + lens + kEps, -1);
    }
  seq[t++] = make_pair(1E10, 0);
  sort(seq, seq + t);
  sum[-1] = 0;
  for (int i = 0; i < t; ++i) sum[i] = sum[i - 1] + seq[i].second;
  for (int i = 0; i < 11; ++i) {
    double lb = i - lenf, rb = i + lenf;
    ff[i] = 0.0;
    while (lb + kEps < rb) {
      int q = lower_bound(seq, seq + t, make_pair(lb, -1)) - seq;
      ff[i] += (sum[q - 1] + 1) * (min(rb, seq[q].first) - lb) * df;
      lb = seq[q].first + kEps;
    }
  }
  for (int i = 0; i < 11; ++i) {
    double lb = i - lene, rb = i + lene;
    ee[i] = 0.0;
    while (lb + kEps < rb) {
      int q = lower_bound(seq, seq + t, make_pair(lb, -1)) - seq;
      ee[i] += (sum[q - 1] + 1) * (min(rb, seq[q].first) - lb) * de;
      lb = seq[q].first + kEps;
    }
  }
  int des = 0, src = 1;
  for (int i = 0; i <= nf; ++i)
    for (int j = 0; j <= ne; ++j) dp[des][i][j] = 0.0;
  for (int k = 0; k < 11; ++k) {
    if (cnt[k] == 2) continue;
    des ^= 1, src ^= 1;
    for (int i = 0; i <= nf; ++i)
      for (int j = 0; j <= ne; ++j) {
        dp[des][i][j] = dp[src][i][j];
        for (int l = 1; l <= 2 - cnt[k]; ++l) {
          if (i >= l)
            dp[des][i][j] = max(dp[des][i][j], dp[src][i - l][j] + l * ff[k]);
          if (j >= l)
            dp[des][i][j] = max(dp[des][i][j], dp[src][i][j - l] + l * ee[k]);
        }
        if (cnt[k] == 0 && i >= 1 && j >= 1)
          dp[des][i][j] =
              max(dp[des][i][j], dp[src][i - 1][j - 1] + ff[k] + ee[k]);
      }
  }
  ans = max(ans, dp[des][nf][ne]);
}
void Dfs(int step, int rest) {
  if (step == 11) {
    if (!rest) Solve();
    return;
  }
  for (int i = 0; i <= 2; ++i)
    if (rest >= i) {
      cnt[step] = i;
      Dfs(step + 1, rest - i);
    }
}
int main() {
  scanf("%d%d%d%d%d%d%d%d", &nf, &ne, &ns, &rf, &re, &rs, &df, &de);
  lenf = sqrt(rf * rf - 1);
  lene = sqrt(re * re - 1);
  lens = sqrt(rs * rs - 1);
  Dfs(0, ns);
  printf("%.8lf\n", ans);
  return 0;
}

