        int v = Pair.xx , d = Pair.yy ;

        if( dis[u][x-1] == d + dis[v][x-1] )
        {
            dfs(v,x) ;
            return ;
        }
        if( dis[v][x-1] == d + dis[u][x-1] ) continue ;

        int c = ( dis[u][x-1] + dis[v][x-1] - d )/2 ;
        int a = dis[u][x-1] - c , b = dis[v][x-1] - c ;

        int w = Parents[v][b-1] ;

        addEdge(w,x,c) ;
        return ;
    }

    addEdge(u,x,dis[u][x-1]) ;
}

