    if ((i * i) % 4 == 0 and ((i * i) / 4) % 2 == 0) {
      cout << -1 << '\n';
      return;
    }
  }
  vector<vector<long long int>> o(m, vector<long long int>(2, 0));
  for (int i = (0); i <= (m - 1); i += (1)) {
    for (int j = (0); j <= (n - 1); j += (1))
      if (arr[j][i] == '1') o[i][j % 2]++;
  }
  int ans = INT_MAX;
  for (int i = (0); i <= (n - 1); i += (1)) {
    int cnt = 0, cnt1 = 0, cnt2 = 0;
    for (int j = (0); j <= (m - 1); j += (1))
      if (arr[i][j] == '0')
        cnt += o[j][i % 2];
      else
        cnt += n / 2 - o[j][i % 2] + (i % 2 == 0);
    vector<int> temp(m, 0);
    for (int j = (0); j <= (m - 2); j += (1)) {
      if (j == 0) {
        if ((arr[i][j] - '0' + arr[i][j + 1] - '0') & 1)
          continue;
        else
          temp[j] = 1;
      } else {
        int init = temp[j - 1];
        int left = init + (arr[i][j - 1] - '0') + (arr[i][j] - '0');
        int right = (arr[i][j + 1] - '0') + (arr[i][j] - '0');
        if ((left & 1) and (right & 1))
          continue;
        else
          temp[j] = 1;
      }
    }
    for (int j = (0); j <= (m - 1); j += (1))
      if (temp[j] == 0)
        cnt2 += o[j][!(i % 2)];
      else
        cnt2 += n / 2 - o[j][!(i % 2)] + (i & 1);
    for (int j = (0); j <= (m - 1); j += (1))
      if (temp[j] == 1)
        cnt1 += o[j][!(i % 2)];
      else
        cnt1 += n / 2 - o[j][!(i % 2)] + (i & 1);
    ans = min(ans, cnt + cnt1);
    ans = min(ans, cnt + cnt2);
  }
  cout << ans << '\n';
}
