bool isWinner(LL a, LL b){
	if((a==0) || (b==0)){
		return false;
	}
	LL bmoda=b%a;
	if(bmoda==0){
		return true;
	}
	if(S.find(make_pair(a,b))!=S.end()){
		return true;
	}
	if(!isWinner(bmoda, a)){
		S.insert(make_pair(bmoda, a));
		return true;
	}
	LL sub=a;
	while(sub<=b){
		LL newB=b-sub;
		if(newB<a){
			if(!isWinner(newB, a)){
				S.insert(make_pair(newB, a));
				return true;
			}
		}else{
			if(!isWinner(a, newB)){
				S.insert(make_pair(a, newB));
				return true;
			}
		}
		sub*=a;
	}
	return false;
}

