namespace DP {
int dp[1 << 18];
inline vector<int> solve(int cl, int cr,
                         vector<pair<pair<int, int>, int> > ve) {
  vector<vector<pair<int, int> > > G(cr);
  for (auto &P : ve)
    G[P.first.second].push_back(make_pair(P.first.first, P.second));
  memset(dp, 0, (1 << cl) << 2);
  dp[0] = 1;
  for (int i = 0; i < cr; i++) {
    for (int mask = (1 << cl) - 1; mask >= 0; mask--) {
      for (auto &P : G[i]) {
        int j = P.first;
        if (!(mask >> j & 1)) continue;
        int nmask = mask ^ (1 << j);
        dp[mask] = (dp[mask] + 1ll * dp[nmask] * P.second) % mod;
      }
    }
  }
  vector<int> ret(cl + 1, 0);
  for (int mask = 0; mask < (1 << cl); mask++) {
    int c = __builtin_popcount(mask);
    ret[c] = (ret[c] + dp[mask]) % mod;
  }
  while (!ret.back()) ret.pop_back();
  return ret;
}
}  // namespace DP
namespace TR {
inline vector<int> solve(int cl, int cr,
                         vector<pair<pair<int, int>, int> > ve) {
  int n = cl + cr;
  vector<vector<pair<int, int> > > G(n), T(n);
  vector<pair<pair<int, int>, int> > nte;
  for (auto &P : ve) {
    G[P.first.first].push_back(make_pair(P.first.second + cl, P.second));
    G[P.first.second + cl].push_back(make_pair(P.first.first, P.second));
  }
  vector<int> dep(n, -1);
  function<void(int, int, int)> dfs = [&](int u, int lst, int depth) {
    dep[u] = depth;
    for (auto &P : G[u]) {
      int v = P.first;
      if (v == lst) continue;
      if (dep[v] == -1) {
        T[u].push_back(P);
        dfs(v, u, depth + 1);
      } else if (dep[v] < dep[u]) {
        nte.push_back(make_pair(make_pair(u, v), P.second));
      }
    }
  };
  dfs(0, -1, 0);
  vector<int> ret(cl + 1, 0);
  for (int mask = 0; mask < (1 << nte.size()); mask++) {
    vector<int> lab(n, 0);
    int bad = 0, c = 0, prd = 1;
    for (int i = 0; i < (int)nte.size(); i++)
      if (mask >> i & 1) {
        c++;
        prd = 1ll * prd * nte[i].second % mod;
        int u = nte[i].first.first, v = nte[i].first.second;
        if (lab[u] || lab[v]) {
          bad = 1;
          break;
        }
        lab[u] = lab[v] = 1;
      }
    if (bad) continue;
    vector<vector<int> > f0(n), f1(n);
    function<void(int)> go = [&](int u) {
      f0[u].push_back(1);
      f1[u].push_back(0);
      for (auto &P : T[u]) {
        int v = P.first;
        go(v);
        int su = f0[u].size(), sv = f0[v].size();
        vector<int> nf0(su + sv, 0), nf1(su + sv, 0);
        for (int i = 0; i < su; i++) {
          for (int j = 0; j < sv; j++) {
            nf0[i + j] =
                (nf0[i + j] + 1ll * f0[u][i] * (f0[v][j] + f1[v][j])) % mod;
            nf1[i + j + 1] =
                (nf1[i + j + 1] + 1ll * f0[u][i] * f0[v][j] % mod * P.second) %
                mod;
            nf1[i + j] =
                (nf1[i + j] + 1ll * f1[u][i] * (f0[v][j] + f1[v][j])) % mod;
          }
        }
        while (nf0.size() && !nf0.back() && !nf1.back())
          nf0.pop_back(), nf1.pop_back();
        f0[u] = nf0;
        f1[u] = nf1;
      }
    };
    go(0);
    for (int i = 0; i < (int)f0[0].size(); i++) {
      ret[i + c] = (ret[i + c] + 1ll * (f0[0][i] + f1[0][i]) * prd) % mod;
    }
  }
  while (!ret.back()) ret.pop_back();
  return ret;
}
}  // namespace TR
