  scanf("%d%d", &n, &m);
  for (int i = fact[0] = 1; i <= n; i++) fact[i] = 1ll * fact[i - 1] * i % mod;
  for (int i = 1; i <= 2 * n; i++) fa[i] = i;
  for (int i = 1; i <= m; i++) {
    scanf("%d%d%d", &eu[i], &ev[i], &ew[i]);
    ew[i] = (ew[i] - 1 + mod) % mod;
    fa[Find(ev[i] + n)] = Find(eu[i]);
  }
  for (int i = 1; i <= 2 * n; i++) buck[Find(i)].push_back(i);
  vector<int> res;
  res.push_back(1);
  for (int i = 1; i <= 2 * n; i++)
    if (buck[i].size() > 1) {
      int cl = 0, cr = 0;
      for (int u : buck[i])
        if (u <= n)
          id[u] = cl++;
        else
          id[u] = cr++;
      vector<pair<pair<int, int>, int> > ve;
      for (int j = 1; j <= m; j++)
        if (Find(eu[j]) == i)
          ve.push_back(make_pair(make_pair(id[eu[j]], id[ev[j] + n]), ew[j]));
      if (cl > cr) {
        swap(cl, cr);
        for (auto &P : ve) swap(P.first.first, P.first.second);
      }
      res =
          Merge(res, cl <= 18 ? DP::solve(cl, cr, ve) : TR::solve(cl, cr, ve));
    }
  int ans = 0;
  for (int i = 0; i < (int)res.size(); i++) {
    ans = (ans + 1ll * fact[n - i] * res[i]) % mod;
  }
  printf("%d\n", ans);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 1100;
vector<int> sx, sy;
int n, x, y, xx, yy, ans;
bool vis[maxn][maxn];
vector<pair<int, pair<int, int> > > h, v;
queue<pair<int, int> > q;
const int go[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
void init() {
  string st;
  int len, tt;
  cin >> n;
  x = y = 1e9 + 100;
  sx.push_back(0);
  sy.push_back(0);
  sx.push_back(2 * x);
  sy.push_back(2 * y);
  for (int i = 1; i <= n; i++) {
    cin >> st >> len;
    if (st == "R")
      tt = 0;
    else if (st == "L")
      tt = 1;
    else if (st == "U")
      tt = 2;
    else
      tt = 3;
    if (go[tt][0] != 0) {
      xx = x + go[tt][0] * len;
      int sta = min(xx, x), end = max(xx, x) + 1;
      sx.push_back(sta);
      sx.push_back(end);
      sy.push_back(y);
      sy.push_back(y + 1);
      h.push_back(make_pair(y, make_pair(sta, end)));
      x = xx;
    } else {
      yy = y + go[tt][1] * len;
      int sta = min(y, yy), end = max(y, yy) + 1;
      sx.push_back(x);
      sx.push_back(x + 1);
      sy.push_back(sta);
      sy.push_back(end);
      v.push_back(make_pair(x, make_pair(sta, end)));
      y = yy;
    }
  }
  sort(sx.begin(), sx.end());
  sort(sy.begin(), sy.end());
  sx.erase(unique(sx.begin(), sx.end()), sx.end());
  sy.erase(unique(sy.begin(), sy.end()), sy.end());
}
void run1() {
  vis[0][0] = true;
  for (int i = 0; i < h.size(); i++) {
    int y = h[i].first;
    pair<int, int> X = h[i].second;
    int xi = lower_bound(sx.begin(), sx.end(), X.first) - sx.begin();
    int yi = lower_bound(sy.begin(), sy.end(), y) - sy.begin();
    for (; sx[xi] < X.second; xi++)
      if (!vis[xi][yi]) {
        vis[xi][yi] = true;
        ans += sx[xi + 1] - sx[xi];
      }
  }
  for (int i = 0; i < v.size(); i++) {
    int x = v[i].first;
    pair<int, int> Y = v[i].second;
    int yi = lower_bound(sy.begin(), sy.end(), Y.first) - sy.begin();
    int xi = lower_bound(sx.begin(), sx.end(), x) - sx.begin();
    for (; sy[yi] < Y.second; yi++)
      if (!vis[xi][yi]) {
        vis[xi][yi] = true;
        ans += sy[yi + 1] - sy[yi];
      }
  }
}
void run2() {
  q.push(make_pair(0, 0));
  while (!q.empty()) {
    int x = q.front().first, y = q.front().second;
    q.pop();
    for (int i = 0; i < 4; i++) {
      int xx = x + go[i][0], yy = y + go[i][1];
      if (xx >= 0 && xx <= sx.size() && yy >= 0 && yy <= sy.size()) {
      } else
        continue;
      if (!vis[xx][yy]) {
        vis[xx][yy] = true;
        q.push(make_pair(xx, yy));
      }
    }
  }
  for (int i = 0; i < sx.size(); i++)
    for (int j = 0; j < sy.size(); j++)
      if (!vis[i][j]) ans += (sx[i + 1] - sx[i]) * (sy[j + 1] - sy[j]);
}
int main() {
  init();
  run1();
  run2();
  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<int, int>;
const ll MOD = 1000000007;
const int INF = 1<<29;

int N;
vector<string> strs;

set<int> non_zero;
int mapped_num[26];
bool used[10];
int max_len;


int dfs(int x, int y, int s){
    if(x >= max_len){
        if(s == 0) return 1;
        else return 0;
    }
    if(y == N - 1){
        if(x >= strs[y].size()) return 0;
        int d = strs[y][strs[y].size()-1-x] - 'A';
        if(mapped_num[d] == -1){
            int i = s % 10;
            if(used[i]) return 0;
            if(i == 0 && non_zero.count(d) > 0) return 0;
            used[i] = true;
            mapped_num[d] = i;
            int ret = dfs(x+1, 0, s / 10);
            mapped_num[d] = -1;
            used[i] = false;
            return ret;
        }else{
            if(mapped_num[d] != s % 10) return 0;
            return dfs(x+1, 0, s / 10);
        }
    }else{
        if(x >= strs[y].size()) return dfs(x, y+1, s);
        int d = strs[y][strs[y].size()-1-x] - 'A';
        if(mapped_num[d] != -1) return dfs(x, y+1, s+mapped_num[d]);
        int ret = 0;
        for(int i=0;i<10;i++){
            if(used[i]) continue;
            if(i == 0 && non_zero.count(d) > 0) continue;
            used[i] = true;
            mapped_num[d] = i;
            ret += dfs(x, y+1, s+i);
            mapped_num[d] = -1;
            used[i] = false;
        }
        return ret;
    }
}


int main(){
    while(true){
        cin >> N;
        if(N == 0) break;

        strs.resize(N);
        non_zero.clear();
        max_len = 0;
        for(int i=0;i<N;i++){
            cin >> strs[i];
            if(strs[i].size() > 1) non_zero.insert(strs[i][0] - 'A');
            max_len = max(max_len, int(strs[i].size()));
        }

        memset(mapped_num, -1, sizeof(mapped_num));
        memset(used, 0, sizeof(used));
        cout << dfs(0, 0, 0) << endl;
    }

    return 0;
}

