#include <bits/stdc++.h>
using namespace std;
const int mod = 1e9 + 7;
const int MN = 200010;
int exp(int x, int n) {
  int ret = 1;
  while (n) {
    if (n & 1) ret = 1LL * ret * x % mod;
    x = 1LL * x * x % mod;
    n >>= 1;
  }
  return ret;
}
int inv(int x) { return exp(x, mod - 2); }
int fact[MN], invf[MN];
int comb(int n, int k) {
  return 1LL * fact[n] * invf[k] % mod * invf[n - k] % mod;
}
int S(int n, int k) {
  int ret = 0;
  for (int i = 0; i <= k; i++) {
    if (i % 2) {
      ret += mod - 1LL * comb(k, i) * exp(k - i, n) % mod;
      ret %= mod;
    } else {
      ret += 1LL * comb(k, i) * exp(k - i, n) % mod;
      ret %= mod;
    }
  }
  ret = 1LL * ret * invf[k] % mod;
  return ret;
}
int N, K;
int A[MN];
