const int maxN = 10005;
int n;
int current[maxN];
bool DivideThree() {
  int sum = 0;
  for (int j = 1; j <= n; j++) sum += current[j];
  return (sum % 3 == 0) ? true : false;
}
bool DivideSeven() {
  int factor[] = {1, 3, 2, 6, 4, 5};
  int i = 0;
  int j = 1;
  long long sum = 0;
  while (j <= n) {
    if (i == 6) i = 0;
    sum += factor[i] * current[j];
    i++;
    j++;
  }
  return (sum % 7 == 0) ? true : false;
}
bool needIncreasement(int index) {
  if (index == 2) return true;
  if (current[index - 1] == 9) return true;
  return false;
}
int main() {
