    cout << -1;
    return 0;
  }
  for (int k = 1; k <= n; k++) current[k] = 0;
  current[1] = 0;
  current[n] = 1;
  while (true) {
    for (int i = n; i >= 2; i--) {
      if (i == n && current[i] == 9 && current[i - 1] == 9) {
        cout << -1;
        return 0;
      }
      if (needIncreasement(i)) {
        current[i]++;
        current[i - 1] = 0;
      }
    }
    if (DivideThree() && DivideSeven()) break;
  }
  for (int j = n; j >= 1; j--) cout << current[j];
}

