    if (n == 0) break;
    ca = cb = n;
    for (int i = 0; i < n; ++i) {
      int t;
      scanf("%d", &t);
      a[t - 1] = true;
    }
    for (int i = 0; i < 2 * n; ++i) b[i] = !a[i];
    int cur = -1;
    int turn = 0;
    while (ca > 0 && cb > 0) {
      if (turn == 0) {
        for (int i = max(cur, 0); i < 2 * n; ++i) {
          if (a[i]) {
            a[i] = false;
            cur = i;
            ca -= 1;
            break;
          }
        }
        cur = -1;
      } else {
        for (int i = max(cur, 0); i < 2 * n; ++i) {
          if (b[i]) {
            b[i] = false;
            cur = i;
            cb -= 1;
            break;
          }
        }
        cur = -1;
      }
      turn = (turn + 1) % 2;
    }
    printf("%d\n%d\n", cb, ca);
  }
  return 0;
}

