    t[y].push_back(x);
  }
  cin >> num;
  for (int i = 1; i <= num; i++) {
    cin >> x;
    p.push_back(x);
  }
  memset(dis, -1, sizeof(dis));
  q.push(p[num - 1]);
  cnt[p[num - 1]] = 1;
  dis[p[num - 1]] = 0;
  while (!q.empty()) {
    x = q.front();
    q.pop();
    for (int i = 0; i < t[x].size(); i++) {
      y = t[x][i];
      if (dis[y] == -1) {
        dis[y] = dis[x] + 1;
        q.push(y);
      }
      if (dis[x] + 1 == dis[y]) {
        cnt[y] += cnt[x];
      }
    }
  }
  int ans[2] = {0, 0};
  for (int i = 0; i < num - 1; i++) {
    x = p[i];
    y = p[i + 1];
    if (dis[x] != dis[y] + 1) ans[0] += 1;
    if (cnt[x] != cnt[y]) ans[1] += 1;
  }
  cout << ans[0] << ' ' << ans[1] << endl;
