		TR.put(0.0, -1);
		TR.put(1000*1000*1000+1.0, n-1);


		for(int i=n-2; i>=0; i--) {
			int j = TR.ceilingEntry(B[i]+0.0).getValue();
			F[i] = F[j] + A[j]*B[i];
			//System.out.println(i+" "+F[i]+" "+j+" "+TR);

			while(TR.size() > 1) {
				double x1 = TR.lastKey();
