    static class TaskB {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();
            if (n > m) {
                int t = n;
                n = m;
                m = t;
            }
            if (n == 1) {
                int d1 = Math.abs(x2 - x1) - 1;
                int d2 = Math.abs(y2 - y1) - 1;
                if (d1 == 0) d1 = d2;
                if (d1 == 1) {
                    out.println("First");
                    return;
                }
                out.println(d1 >= 4 ? "Second" : "First");
            } else {
                int d1 = Math.abs(x2 - x1) - 1;
                int d2 = Math.abs(y2 - y1) - 1;
                int min = Math.max(d1, d2);
                if (d1 == 1) {
                    out.println("First");
                    return;
                }
                out.println(min >= 4 ? "Second" : "First");
            }
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int pread() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = pread();
            while (isSpaceChar(c))
                c = pread();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = pread();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = pread();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = pread();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

