const int sink = 500;
const int source = 0;
vector<int> g[507];
vector<int>::iterator u;
queue<int> Q;
int needFlow, x, y, z, minFlow, totalFlow, N, M, i, node, to;
int fh[507], flag[507], start[507], final[507];
int C[507][507], flow[507][507];
void addEdge(int x, int y, int z) {
  C[x][y] += z;
  g[x].push_back(y);
  g[y].push_back(x);
}
bool bf() {
  Q.push(source);
  flag[source] = 1;
  memset(flag, 0, sizeof(flag));
  while (Q.size()) {
    int crt = Q.front();
    Q.pop();
    if (crt == sink) continue;
    for (u = g[crt].begin(); u != g[crt].end(); ++u) {
      int to = *u;
      if (flag[to] || C[crt][to] == flow[crt][to]) continue;
      Q.push(to);
      flag[to] = 1;
      fh[to] = crt;
    }
  }
  return flag[sink];
}
int main() {
  cin >> N >> M;
  for (i = 1; i <= N; ++i) {
    cin >> start[i];
    needFlow += start[i];
  }
  for (i = 1; i <= N; ++i) cin >> final[i];
  for (i = 1; i <= N; ++i) {
    addEdge(source, i, start[i]);
    addEdge(i, i + 200, ((int)1e9));
    addEdge(i + 200, sink, final[i]);
  }
  for (i = 1; i <= M; ++i) {
    cin >> x >> y;
    addEdge(x, y + 200, ((int)1e9));
    addEdge(y, x + 200, ((int)1e9));
  }
  while (bf()) {
    for (u = g[sink].begin(); u != g[sink].end(); ++u) {
      to = *u;
      if (flow[to][sink] == C[to][sink] || !flag[to]) continue;
      for (node = sink, fh[sink] = to, minFlow = ((int)1e9); node != source;
           node = fh[node])
        minFlow = min(minFlow, C[fh[node]][node] - flow[fh[node]][node]);
      if (minFlow == 0) continue;
      for (node = sink; node != source; node = fh[node]) {
        flow[fh[node]][node] += minFlow;
        flow[node][fh[node]] -= minFlow;
      }
      totalFlow += minFlow;
    }
  }
  if (totalFlow != needFlow)
    cout << "NO" << '\n';
  else {
    cout << "YES" << '\n';
    for (i = 1; i <= N; ++i, cout << '\n')
      for (int j = 1; j <= N; ++j) cout << flow[i][j + 200] << " ";
  }
  return 0;
}

