        public str(ArrayList<Integer> rd, int cur_m) {
            this.rd = rd;
            this.cur_m = cur_m;
        }
    }

    void merge(str a1, str a2) {
        a2.rd.add(0);
        if (a1.rd.size() >= a2.rd.size()) {
            int n = a1.rd.size() - a2.rd.size();
            for (int i = 0; i < a2.rd.size(); i++) {
                a1.rd.set(n + i, a1.rd.get(n + i) + a2.rd.get(i));
            }
        } else {
            int n = a2.rd.size() - a1.rd.size();
            for (int i = 0; i < a1.rd.size(); i++) {
                a2.rd.set( n + i, a2.rd.get(n + i) + a1.rd.get(i));
            }
            a1.rd = a2.rd;
        }
        for (int i = 0; i < a1.rd.size(); i++) {
            if (a1.rd.get(i) >= a1.rd.get(a1.cur_m)) {
                a1.cur_m = i;
            }
        }
    }

    str dfs(int v) {
        if (ch[v].size() == 0) {
            ans[v] = 0;
            ArrayList<Integer> rd = new ArrayList<>();
            rd.add(1);
            return new str(rd, 0);
