        ArrayList<Integer> rd = new ArrayList<>();
        rd.add(1);
        str ca = new str(rd, ans[v]);
        for (Integer child : ch[v]) {
            merge(ca, dfs(child));
        }
        ans[v] = ca.rd.size() - ca.cur_m - 1;
        return ca;
    }

