struct LinearBasis {
  int cnt;
  long long b[MAXL + 1];
  LinearBasis() : cnt(0) { memset(b, 0, sizeof(b)); }
  bool insert(long long x) {
    for (int i = MAXL; i >= 0; i--) {
      if (!(x >> i & 1)) continue;
      if (b[i])
        x ^= b[i];
      else {
        for (int j = i - 1; j >= 0; j--) {
          if (1LL << j & x) x ^= b[j];
        }
        for (int j = i + 1; j <= MAXL; j++) {
          if (1LL << i & b[j]) b[j] ^= x;
        }
        b[i] = x;
        return cnt++, true;
      }
    }
    return false;
  }
