#include <bits/stdc++.h>
using namespace std;
long long n, q;
vector<vector<long long> > g;
vector<vector<long long> > heavy;
long long sz[300005];
long long pos[300005];
void input() {
  cin >> n >> q;
  g.assign(n, vector<long long>());
  for (long long i = 1; i < n; ++i) {
    long long x;
    cin >> x;
    --x;
    g[x].push_back(i);
    g[i].push_back(x);
  }
}
void getsz(long long v, long long p) {
  sz[v] = 1;
  for (long long u : g[v]) {
    if (u == p) continue;
    getsz(u, v);
    sz[v] += sz[u];
  }
}
void dfs(long long v, long long p, long long num) {
  heavy[num].emplace_back(v);
  pos[v] = num;
  long long big = -1, mxsz = -1;
  for (long long u : g[v]) {
    if (u == p) continue;
    if (sz[u] > mxsz) mxsz = sz[u], big = u;
  }
  for (long long u : g[v]) {
    if (u == p) continue;
    if (u == big) dfs(u, v, num);
    if (u != big) {
      heavy.emplace_back(vector<long long>());
      dfs(u, v, heavy.size() - 1);
    }
  }
}
void solve() {
  memset(pos, -1, sizeof pos);
  heavy.emplace_back(vector<long long>());
  getsz(0, -1);
  dfs(0, -1, 0);
  while (q--) {
    long long u;
    cin >> u;
    --u;
    long long l = 0, r = heavy[pos[u]].size() - 1, ans = -1;
    while (l <= r) {
      long long mid = (l + r) >> 1;
      if (2 * sz[heavy[pos[u]][mid]] > sz[u])
        ans = heavy[pos[u]][mid], l = mid + 1;
      else
        r = mid - 1;
    }
    cout << ans + 1 << "\n";
  }
}
signed main(signed argc, char** argv) {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  input();
  solve();
  return 0;
}

