#define INF (1<<28)

struct edge{int to,cost;};
struct state{
  int pos,pos2,cost;
  bool operator < (const state &p)const{
    return cost > p.cost;
  }
};

vector<edge> G[1005];
int T[1005][1005];
int n,m,k,p;
vector<int> cpoint;

int di[1005][(1<<13)];

void solve(){
  for(int i=0;i<1005;i++)
    for(int j=0;j<(1<<13);j++)
	di[i][j]=INF;

  di[p][0]=0;
  priority_queue<state> Q;
  Q.push((state){p,0,0});
  while(!Q.empty()){
    state s=Q.top();Q.pop();
    if(s.pos2+1==(1<<(k+k))){
      cout<<s.cost<<endl;
      return;
    }
    if(s.cost>di[s.pos][s.pos2])continue;
    for(int i=1;i<(int)cpoint.size();i++){
      int to=cpoint[i];
      int ncost=s.cost+T[s.pos][to];
      int npos2=s.pos2;
      int a=(i-1)/2,b=a+k;
      if(i%2){
	npos2|=(1<<a);
      }else if(i%2==0&&(s.pos2>>a)&1){
	npos2|=(1<<b);
      }
      if(ncost>=di[to][npos2])continue;
      di[to][npos2]=ncost;
      Q.push((state){to,npos2,ncost});
    }
  }
  cout<<"Cannot deliver"<<endl;
}

void dijkstra(int si){
  int d[1005];
  for(int i=0;i<1005;i++)d[i]=INF;
  d[si]=0;
  priority_queue<state> Q;
  Q.push((state){si,si,0});
  while(!Q.empty()){
    state s=Q.top();Q.pop();
    if(s.cost>d[s.pos])continue;
    for(int i=0;i<(int)G[s.pos].size();i++){
      edge e=G[s.pos][i];
      int ncost=s.cost+e.cost;
      if(ncost<d[e.to]){
	d[e.to]=ncost;
	Q.push((state){e.to,e.to,ncost});
      }
    }
  }

  for(int i=0;i<n;i++)T[si][i]=d[i];
}

void init(){
  cpoint.clear();
  for(int i=0;i<1005;i++){
    G[i].clear();
    for(int j=0;j<1005;j++){
      T[i][j]=INF;
    }
  }
}


int main(){
  while(cin>>n>>m>>k>>p){
    init();
    p--;
    cpoint.push_back(p);
    for(int i=0;i<m;i++){
      int x,y,z;
      cin>>x>>y>>z;
      x--,y--;
      G[x].push_back( (edge){y,z} );
      G[y].push_back( (edge){x,z} );
    }
    for(int i=0;i<k;i++){
      int a,b;
      cin>>a>>b;
      a--,b--;
      cpoint.push_back(a);
      cpoint.push_back(b);
    }
    for(int i=0;i<(int)cpoint.size();i++)
      dijkstra(cpoint[i]);

    //    for(int i=0;i<n;i++)      for(int j=0;j<n;j++)	cout<<i<<" "<<j<<" "<<T[i][j]<<endl;


    solve();
  }
  return 0;
}

