const long long Mod = 1e9 + 7;
long long a[2020];
int main() {
  long long n, k;
  cin >> n >> k;
  for (long long i = 0; i < n; i++) scanf("%I64d", &a[i]);
  for (long long i = 0; i < n; i++) {
    long long Res = 0;
    for (long long j = i, p = 1, d = 1, r = 1; j >= 0; j--, p *= k + r - 1,
                   d *= r, p = ((p % Mod) * (InverseMod(d)) % Mod), r++)
      Res = (Res + p * a[j]) % Mod;
    printf("%I64d ", Res);
  }
}
long long FastPower(long long x, long long y) {
  if (!y) return 1;
  long long Res = FastPower(x, y >> 1);
  Res = (Res * Res) % Mod;
  if (y & 1) Res *= x;
  return Res % Mod;
}
long long InverseMod(long long b) { return FastPower(b, Mod - 2); }

