};
vector<op> ops;
vector<int> gr[200005], grn[200005];
int last;
void dfs1(int v, int prev) {
  for (int i = 0; i < gr[v].size(); i++) {
    if (gr[v][i] != prev) {
      dfs1(gr[v][i], v);
    }
  }
  if (prev != -1) {
    op a;
    a.x = v;
    a.y = prev;
    a.yi = last;
    grn[last].push_back(v);
    grn[v].push_back(last);
    last = v;
    ops.push_back(a);
  }
}
void dfs2(int v, int prev) {
  for (int i = 0; i < grn[v].size(); i++) {
    if (grn[v][i] != prev && grn[v][i] != 1) {
      op a;
      a.x = v;
      a.y = grn[v][i];
      a.yi = 1;
      ops.push_back(a);
      dfs2(grn[v][i], v);
    }
  }
}
