class Point {
 public:
  double x, y;
  Point(double x = 0.0, double y = 0.0) : x(x), y(y) {}
  Point operator+(const Point& p) const { return Point(x + p.x, y + p.y); }
  Point& operator+=(const Point& p) {
    x += p.x;
    y += p.y;
    return *this;
  }
  Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
  Point& operator-=(const Point& p) {
    x -= p.x;
    y -= p.y;
    return *this;
  }
  Point operator*(double a) const { return Point(a * x, a * y); }
  Point& operator*=(double a) {
    x *= a;
    y *= a;
    return *this;
  }
  Point operator/(double a) const { return Point(x / a, y / a); }
  Point& operator/=(double a) {
    x /= a;
    y /= a;
    return *this;
  }
  double abs() { return sqrt(norm()); }
  double norm() { return x * x + y * y; }
};
class Circle {
 public:
  Point c;
  double r;
};
double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
Point rotate(Point p, double angle) {
  return Point(p.x * cos(angle) - p.y * sin(angle),
               p.x * sin(angle) + p.y * cos(angle));
}
pair<Point, Point> getCrossPoints(const Circle& c1, const Circle& c2) {
  double d = (c2.c - c1.c).abs();
  double a = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * d);
  Point e = (c2.c - c1.c) / d;
  Point h = rotate(e, PI / 2) * sqrt(max(c1.r * c1.r - a * a, 0.));
  return make_pair(c1.c + e * a + h, c1.c + e * a - h);
}
void partCircles(const vector<Circle>& cs, set<LL>& res) {
  int N = int((cs).size());
  vector<Point> ps;
  for (int i = (0); i < (N); ++i)
    for (int j = (0); j < (N); ++j) {
      if (i == j) continue;
      auto cc = getCrossPoints(cs[i], cs[j]);
      Point crossPoints[2] = {cc.first, cc.second};
      for (int k = (0); k < (2); ++k) {
        Point delta = crossPoints[1 - k] - crossPoints[k];
        if (delta.abs() == 0) delta.x = 1;
        delta /= delta.abs();
        for (int d = (0); d < (4); ++d) {
          ps.push_back(crossPoints[k] + delta * EPS);
          delta = rotate(delta, PI / 2);
        }
      }
    }
  for (auto&& p : ps) {
    LL bit = 0;
    for (int i = (0); i < (N); ++i)
      if ((cs[i].c - p).abs() < cs[i].r) bit |= 1LL << i;
    res.insert(bit);
  }
}
void partPoints(vector<Point> ps, set<PLL>& res) {
  int N = int((ps).size());
  for (int i = (0); i < (N); ++i) {
    Point e(0, 1);
    for (int d = (0); d < (4); ++d) {
      ps.push_back(ps[i] + e * EPS);
      e = rotate(e, PI / 2);
    }
  }
  for (int i = (0); i < (int((ps).size())); ++i)
    for (int j = (0); j < (int((ps).size())); ++j) {
      if (i == j) continue;
      Point p1 = ps[i];
      Point p2 = ps[j];
      Point e = p2 - p1;
      e /= e.abs();
      e = rotate(e, PI / 2);
      LL b1 = 0, b2 = 0;
      for (int k = (0); k < (N); ++k)
        if (dot(e, ps[k] - p1) >= 0)
          b1 |= 1LL << k;
        else
          b2 |= 1LL << k;
      if (b1 > b2) swap(b1, b2);
      res.insert(make_pair(b1, b2));
    }
}
int N, M;
double calcBest(LL bps, LL bcs, VI& as, vector<double>& vs,
                vector<Circle>& cs) {
  Point q(0, 0);
  double inv = 0.;
  for (int i = (0); i < (M); ++i) {
    if ((bcs >> i & 1) == 0 || (bps >> as[i] & 1) == 0) continue;
    double tmp = 1. / (vs[i] * vs[i]);
    q.x += cs[i].c.x * tmp;
    q.y += cs[i].c.y * tmp;
    inv += tmp;
  }
  if (inv <= 0) return 0;
  q.x /= inv;
  q.y /= inv;
  double res = 0.;
  for (int i = (0); i < (M); ++i) {
    if ((bcs >> i & 1) == 0 || (bps >> as[i] & 1) == 0) continue;
    res += ((cs[i].c - q).norm() - (cs[i].r * cs[i].r)) / (vs[i] * vs[i]);
  }
  return res;
}
Point calcBestQ(LL bps, LL bcs, VI& as, vector<double>& vs,
                vector<Circle>& cs) {
  Point q(0, 0);
  double inv = 0.;
  for (int i = (0); i < (M); ++i) {
    if ((bcs >> i & 1) == 0 || (bps >> as[i] & 1) == 0) continue;
    double tmp = 1. / (vs[i] * vs[i]);
    q.x += cs[i].c.x * tmp;
    q.y += cs[i].c.y * tmp;
    inv += tmp;
  }
  if (inv <= 0) return 0;
  q.x /= inv;
  q.y /= inv;
  return q;
}
