public class Timus2063 {

	static TreeMap<Long,Long> primes = new TreeMap();

	public static long pfac(long n,long p) {
		long sum = 0;
		for (long i = p ; i <= n ;) {
			sum += n / i;
			if(i <= n / p) i *= p;
			else break;
		}
		return sum;
	}
	public static boolean ok(long x) {
		for(Entry<Long, Long> primes : primes.entrySet()) {
			long key = primes.getKey();
			long val = primes.getValue();
			if(val > pfac(x,key)) return false;
		}
		return true;
	}
	public static void main(String[]args)throws Throwable {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = new Integer(br.readLine());
		StringTokenizer tok = new StringTokenizer(br.readLine());
		for (int i = 0 ; i < n ; ++i) {
			long x = new Long(tok.nextToken());
			long m = x;
			for (long j = 2 ; j * j <= x ; ++j) {
				if(x % j == 0) {
					long f = pfac(m,j);
					if(primes.get(j) == null) primes.put(j, 0L);
					primes.put(j, primes.get(j) + f);
				}
			}
			if(x != 1) {
				if(primes.get(x) == null) primes.put(x, 0L);
				primes.put(x, primes.get(x) + pfac(m,x));
			}

		}
		long lo = 1, hi = 1L << 50;
		long ans = -1;
		while (lo <= hi) {
			long mid = lo + (hi - lo) / 2;
			if(ok(mid)) {
				ans = mid;
				hi = mid - 1;
			}
			else lo = mid + 1;
		}
		System.out.println(ans);
	}
}

