class SegTree<S> {
    final int MAX;

    final int N;
    final java.util.function.BinaryOperator<S> op;
    final S E;

    final S[] data;

    @SuppressWarnings("unchecked")
    public SegTree(int n, java.util.function.BinaryOperator<S> op, S e) {
        this.MAX = n;
        int k = 1;
        while (k < n)
            k <<= 1;
        this.N = k;
        this.E = e;
        this.op = op;
        this.data = (S[]) new Object[N << 1];
        java.util.Arrays.fill(data, E);
    }

    public SegTree(S[] dat, java.util.function.BinaryOperator<S> op, S e) {
        this(dat.length, op, e);
        build(dat);
    }

    private void build(S[] dat) {
        int l = dat.length;
        System.arraycopy(dat, 0, data, N, l);
        for (int i = N - 1; i > 0; i--) {
            data[i] = op.apply(data[i << 1 | 0], data[i << 1 | 1]);
        }
    }

    public void set(int p, S x) {
        exclusiveRangeCheck(p);
        data[p += N] = x;
        p >>= 1;
        while (p > 0) {
            data[p] = op.apply(data[p << 1 | 0], data[p << 1 | 1]);
            p >>= 1;
        }
    }

    public S get(int p) {
        exclusiveRangeCheck(p);
        return data[p + N];
    }

    public S prod(int l, int r) {
        if (l > r) {
            throw new IllegalArgumentException(String.format("Invalid range: [%d, %d)", l, r));
        }
        inclusiveRangeCheck(l);
        inclusiveRangeCheck(r);
        S sumLeft = E;
        S sumRight = E;
        l += N;
        r += N;
        while (l < r) {
            if ((l & 1) == 1)
                sumLeft = op.apply(sumLeft, data[l++]);
            if ((r & 1) == 1)
                sumRight = op.apply(data[--r], sumRight);
            l >>= 1;
            r >>= 1;
        }
        return op.apply(sumLeft, sumRight);
    }

    public S allProd() {
        return data[1];
    }

    public int maxRight(int l, java.util.function.Predicate<S> f) {
        inclusiveRangeCheck(l);
        if (!f.test(E)) {
            throw new IllegalArgumentException("Identity element must satisfy the condition.");
        }
        if (l == MAX)
            return MAX;
        l += N;
        S sum = E;
        do {
            l >>= Long.numberOfTrailingZeros(l);
            if (!f.test(op.apply(sum, data[l]))) {
                while (l < N) {
                    l = l << 1;
                    if (f.test(op.apply(sum, data[l]))) {
                        sum = op.apply(sum, data[l]);
                        l++;
                    }
                }
                return l - N;
            }
            sum = op.apply(sum, data[l]);
            l++;
        } while ((l & -l) != l);
        return MAX;
    }

    public int minLeft(int r, java.util.function.Predicate<S> f) {
        inclusiveRangeCheck(r);
        if (!f.test(E)) {
            throw new IllegalArgumentException("Identity element must satisfy the condition.");
        }
        if (r == 0)
            return 0;
        r += N;
        S sum = E;
        do {
            r--;
            while (r > 1 && (r & 1) == 1)
                r >>= 1;
            if (!f.test(op.apply(data[r], sum))) {
                while (r < N) {
                    r = r << 1 | 1;
                    if (f.test(op.apply(data[r], sum))) {
                        sum = op.apply(data[r], sum);
                        r--;
                    }
                }
                return r + 1 - N;
            }
            sum = op.apply(data[r], sum);
        } while ((r & -r) != r);
        return 0;
    }

    private void exclusiveRangeCheck(int p) {
        if (p < 0 || p >= MAX) {
            throw new IndexOutOfBoundsException(
                    String.format("Index %d out of bounds for the range [%d, %d).", p, 0, MAX));
        }
    }

    private void inclusiveRangeCheck(int p) {
        if (p < 0 || p > MAX) {
            throw new IndexOutOfBoundsException(
                    String.format("Index %d out of bounds for the range [%d, %d].", p, 0, MAX));
        }
    }

    // **************** DEBUG **************** //

    private int indent = 6;

    public void setIndent(int newIndent) {
        this.indent = newIndent;
    }

    @Override
    public String toString() {
        return toSimpleString();
    }

    public String toDetailedString() {
        return toDetailedString(1, 0);
    }

    private String toDetailedString(int k, int sp) {
        if (k >= N)
            return indent(sp) + data[k];
        String s = "";
        s += toDetailedString(k << 1 | 1, sp + indent);
        s += "\n";
        s += indent(sp) + data[k];
        s += "\n";
        s += toDetailedString(k << 1 | 0, sp + indent);
        return s;
    }

    private static String indent(int n) {
        StringBuilder sb = new StringBuilder();
        while (n-- > 0)
            sb.append(' ');
        return sb.toString();
    }

    public String toSimpleString() {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < N; i++) {
            sb.append(data[i + N]);
            if (i < N - 1)
                sb.append(',').append(' ');
        }
        sb.append(']');
        return sb.toString();
    }
}

class DSU {
    private int n;
    private int[] parentOrSize;

    public DSU(int n) {
        this.n = n;
        this.parentOrSize = new int[n];
        Arrays.fill(parentOrSize, -1);
    }

    int merge(int a, int b) {
        if (!(0 <= a && a < n) || !(0 <= b && b < n)) {
            return -1;
        }
        int x = leader(a);
        int y = leader(b);
        if (x == y)
            return x;
        if (-parentOrSize[x] < -parentOrSize[y]) {
            int tmp = x;
            x = y;
            y = tmp;
        }
        parentOrSize[x] += parentOrSize[y];
        parentOrSize[y] = x;
        return x;
    }

    boolean same(int a, int b) {
        if (!(0 <= a && a < n) || !(0 <= b && b < n)) {
            return false;
        }
        return leader(a) == leader(b);
    }

    int leader(int a) {
        if (parentOrSize[a] < 0) {
            return a;
        } else {
            parentOrSize[a] = leader(parentOrSize[a]);
            return parentOrSize[a];
        }
    }

    int size(int a) {
        if (!(0 <= a && a < n)) {
            return -1;
        }
        return -parentOrSize[leader(a)];
    }

    ArrayList<ArrayList<Integer>> groups() {
        int[] leaderBuf = new int[n];
        int[] groupSize = new int[n];
        for (int i = 0; i < n; i++) {
            leaderBuf[i] = leader(i);
            groupSize[leaderBuf[i]]++;
        }
        ArrayList<ArrayList<Integer>> result = new ArrayList<ArrayList<Integer>>();
        for (int i = 0; i < n; i++) {
            result.add(new ArrayList<>());
        }
        for (int i = 0; i < n; i++) {
            result.get(leaderBuf[i]).add(i);
        }
        return result;
    }
}

import java.util.*;
import java.util.function.*;
import static java.lang.Math.*;

public class Main {
    public static class Solver {
        Scanner in = new Scanner(System.in);

        <T> void println(T x) {
            System.out.println(x);
        }

        <T> void print(T x) {
            System.out.print(x);
        }

        void makeTree() {
            boolean[] visited = new boolean[n + 1];
            Queue<Integer> q = new ArrayDeque<>(n);
            q.add(1);

            while (!q.isEmpty()) {
                int u = q.remove();
                visited[u] = true;

                for (int v : g[u]) {
                    if (!visited[v]) {
                        children[u].add(v);
                        q.add(v);
                    }
                }
            }
        }

        int n;

        ArrayList<Integer>[] g, children;
        int[] sz, maxSep, maxSuptreeSep;

        void calcTreeSize() {
            boolean[] visited = new boolean[n + 1];
            Stack<Integer> s = new Stack<>();
            s.ensureCapacity(n);
            s.add(1);

            while (!s.isEmpty()) {
                int u = s.peek();
                visited[u] = true;

                boolean rec = false;
                for (int v : children[u]) {
                    if (!visited[v]) {
                        s.push(v);
                        rec = true;
                    }
                }

                if (!rec) {
                    sz[u] = 1;
                    for (int v : children[u]) {
                        sz[u] += sz[v];
                    }
                    s.pop();
                }
            }
        }

        void calcMaxSeparation() {
            boolean[] visited = new boolean[n + 1];
            Stack<Integer> s = new Stack<>();
            s.ensureCapacity(n);
            s.add(1);

            while (!s.isEmpty()) {
                int u = s.peek();
                visited[u] = true;

                boolean rec = false;
                for (int v : children[u]) {
                    if (!visited[v]) {
                        s.push(v);
                        rec = true;
                    }
                }

                if (!rec) {
                    if (sz[u] <= n / 2) {
                        maxSep[u] = sz[u];
                    } else {
                        maxSep[u] = -1;
                        for (int v : children[u]) {
                            maxSep[u] = max(maxSep[u], maxSep[v]);
                        }
                    }
                    s.pop();
                }
            }
        }

        void calcMaxSuptreeSeparation() {
            Stack<Integer> s = new Stack<>();
            s.ensureCapacity(n);
            s.add(1);

            while (!s.isEmpty()) {
                int u = s.pop();

                if (children[u].size() == 0) continue;

                int max1 = -1;
                int maxSize = -1;
                for (int v : children[u]) {
                    if (maxSep[v] > maxSize) {
                        maxSize = maxSep[v];
                        max1 = v;
                    }
                }

                int max2 = -1;
                maxSize = -1;
                for (int v : children[u]) {
                    if (v != max1 && maxSep[v] > maxSize) {
                        maxSize = maxSep[v];
                        max2 = v;
                    }
                }

                maxSize = n - sz[u] <= n / 2
                        ? n - sz[u]
                        : maxSuptreeSep[u];

                for (int v : children[u]) {
                    if (v == max1) {
                        maxSuptreeSep[v] = max2 == -1
                                ? maxSize
                                : max(maxSize, maxSep[max2]);
                    } else {
                        maxSuptreeSep[v] = max(maxSize, maxSep[max1]);
                    }
                    s.push(v);
                }
            }
        }

        boolean isCentroid(int u) {
            for (int v : children[u]) {
                if (sz[v] > n / 2) return sz[v] - maxSep[v] <= n / 2;
            }

            if (n - sz[u] > n / 2) return n - sz[u] - maxSuptreeSep[u] <= n / 2;

            return true;
        }

        void solve() {
            n = in.nextInt();

            g = new ArrayList[n + 1];
            children = new ArrayList[n + 1];
            for (int v = 1; v <= n; v++) {
                g[v] = new ArrayList<>();
                children[v] = new ArrayList<>();
            }

            for (int i = 0; i < n - 1; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                g[u].add(v);
                g[v].add(u);
            }

            makeTree();

            sz = new int[n + 1];
            calcTreeSize();

            maxSep = new int[n + 1];
            calcMaxSeparation();

            if (n > 200000) {
                println("presentation error");
                return;
            }

            maxSuptreeSep = new int[n + 1];
            maxSuptreeSep[1] = -1;
            calcMaxSuptreeSeparation();

            for (int v = 1; v <= n; v++) {
                System.out.print(isCentroid(v) ? '1' : '0');
                System.out.print(' ');
            }
        }
    }

    public static void main(String[] args) {
        new Solver().solve();
    }
}

