#include <bits/stdc++.h>
using namespace std;
const int nmax = 26;
int ret[nmax];
bool used[nmax];
int k;
string s, a, b;
bool test(int &i, bool &le, bool &ri) {
  for (i = 0; i < k; i++) ret[i] = -1, used[i] = 0;
  int SZ = a.size();
  le = 0;
  ri = 0;
  i = 0;
  while (le == 0 && ri == 0 && i < SZ &&
         (a[i] == b[i] || ret[s[i] - 'a'] != -1)) {
    if (ret[s[i] - 'a'] != -1) {
      if ((a[i] - 'a' > ret[s[i] - 'a'] && le == 0) ||
          (ret[s[i] - 'a'] > b[i] - 'a' && ri == 0)) {
        return 0;
      }
      if (a[i] - 'a' < ret[s[i] - 'a']) le = 1;
      if (ret[s[i] - 'a'] < b[i] - 'a') ri = 1;
    } else if (ret[s[i] - 'a'] == -1) {
      if (used[a[i] - 'a']) {
        return 0;
      }
      ret[s[i] - 'a'] = a[i] - 'a';
      used[a[i] - 'a'] = 1;
    }
    i++;
  }
  while (i < SZ && ret[s[i] - 'a'] != -1) {
    if ((a[i] - 'a' > ret[s[i] - 'a'] && le == 0) ||
        (ret[s[i] - 'a'] > b[i] - 'a' && ri == 0)) {
      return 0;
    }
    if (a[i] - 'a' < ret[s[i] - 'a']) le = 1;
    if (ret[s[i] - 'a'] < b[i] - 'a') ri = 1;
    i++;
  }
  return 1;
}
void random_fill() {
  int p = 0;
  for (int i = 0; i < k; i++)
    if (ret[i] == -1) {
      while (used[p]) p++;
      ret[i] = p;
      used[p] = 1;
    }
  cout << "YES" << endl;
  for (int j = 0; j < k; j++) cout << char(ret[j] + 'a');
  cout << endl;
}
void query() {
  cin >> k >> s >> a >> b;
  int i;
  bool le, ri;
  int SZ = a.size();
  if (test(i, le, ri) == 0) {
    cout << "NO" << endl;
    return;
  }
  if ((le && ri) || i == SZ) {
    random_fill();
    return;
  }
  for (int j = 0; j < k; j++)
    if (ret[s[i] - 'a'] == -1 && used[j] == 0 && a[i] - 'a' < j &&
        j < b[i] - 'a') {
      ret[s[i] - 'a'] = j;
      used[j] = 1;
      random_fill();
      return;
    }
  if (used[a[i] - 'a'] == 0) {
    ret[s[i] - 'a'] = a[i] - 'a';
    used[a[i] - 'a'] = 1;
    if (le) {
      random_fill();
      return;
    }
    int p;
    for (p = i + 1; p < SZ; p++)
      if (ret[s[p] - 'a'] != -1) {
        if (a[p] - 'a' < ret[s[p] - 'a']) {
          random_fill();
          return;
        }
        if (a[p] - 'a' > ret[s[p] - 'a']) {
          break;
        }
      } else {
        for (int j = k - 1; j >= a[i] - 'a'; j--)
          if (used[j] == 0) {
            if (j != a[i] - 'a') {
              ret[s[p] - 'a'] = j;
              used[a[i] - 'a'] = 1;
              random_fill();
              return;
            } else {
              ret[s[p] - 'a'] = a[i] - 'a';
              used[a[i] - 'a'] = 1;
            }
          }
        if (ret[s[p] - 'a'] == -1) break;
      }
    if (p == SZ) {
      random_fill();
      return;
    }
  }
  if (test(i, le, ri) == 0) {
    cout << "NO" << endl;
    return;
  }
  if (i == SZ) {
    random_fill();
    return;
  }
  for (int j = 0; j < k; j++)
    if (used[j] == 0 && a[i] - 'a' < j && j < b[i] - 'a') {
      ret[s[i] - 'a'] = j;
      used[j] = 1;
      random_fill();
      return;
    }
  if (used[b[i] - 'a'] == 0) {
    ret[s[i] - 'a'] = b[i] - 'a';
    used[b[i] - 'a'] = 1;
    if (ri) {
      random_fill();
      return;
    }
    int p;
    for (p = i + 1; p < SZ; p++)
      if (ret[s[p] - 'a'] != -1) {
        if (b[p] - 'a' > ret[s[p] - 'a']) {
          random_fill();
          return;
        }
        if (b[p] - 'a' < ret[s[p] - 'a']) {
          break;
        }
      } else {
        for (int j = 0; j <= b[i] - 'a'; j++)
          if (used[j] == 0) {
            if (j != b[i] - 'a') {
              ret[s[p] - 'a'] = j;
              used[b[i] - 'a'] = 1;
              random_fill();
              return;
            } else {
              ret[s[p] - 'a'] = b[i] - 'a';
              used[b[i] - 'a'] = 1;
            }
          }
        if (ret[s[p] - 'a'] == -1) break;
      }
    if (p == SZ) {
      random_fill();
      return;
    }
  }
  cout << "NO" << endl;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie();
  cout.tie();
  int t;
  cin >> t;
  for (int i = 1; i <= t; i++) query();
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 20;
const int M = 20;
int n, m;
ll k, a[N][M];
map<ll, int> xor_cnt[N][M];
int dist(int r, int c) { return r + c; }
void dfs0(int r, int c, ll sofar = 0) {
  if (r >= n || c >= m) return;
  if (dist(r, c) == (n + m - 1) / 2) {
    xor_cnt[r][c][sofar]++;
    return;
  }
  sofar ^= a[r][c];
  dfs0(r + 1, c, sofar);
  dfs0(r, c + 1, sofar);
}
ll dfs1(int r, int c, ll sofar = 0) {
  if (r < 0 || c < 0) return 0;
  sofar ^= a[r][c];
  if (dist(r, c) == (n + m - 1) / 2) {
    return xor_cnt[r][c][sofar ^ k];
  }
  return dfs1(r - 1, c, sofar) + dfs1(r, c - 1, sofar);
}
int main() {
  cin >> n >> m >> k;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      cin >> a[i][j];
    }
  }
  dfs0(0, 0);
  cout << dfs1(n - 1, m - 1) << "\n";
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN = (1 << 20) + 50;
const int MAXLOG = 21;
long long int a[MAXN];
long long int data[MAXLOG][MAXN];
long long int answer[2][MAXN];
long long int n;
void build(int s = 0, int e = (1 << n), int h = 0) {
  if (e - s < 2) {
    data[h][s] = a[s];
    return;
  }
  int mid = (s + e) / 2;
  build(s, mid, h + 1);
  build(mid, e, h + 1);
  merge(data[h + 1] + s, data[h + 1] + mid, data[h + 1] + mid, data[h + 1] + e,
        data[h] + s);
  for (int i = s; i < mid; i++) {
    long long int now = lower_bound(data[h + 1] + mid, data[h + 1] + e, a[i]) -
                        (data[h + 1] + mid);
    answer[0][h] += now;
  }
  for (int i = mid; i < e; i++) {
    long long int now = lower_bound(data[h + 1] + s, data[h + 1] + mid, a[i]) -
                        (data[h + 1] + s);
    answer[1][h] += now;
  }
}
int main() {
  scanf("%I64d", &n);
  for (int i = 0; i < (1 << n); i++) {
    scanf("%I64d", a + i);
  }
  build();
  long long int q;
  scanf("%I64d", &q);
  while (q--) {
    long long int ans = 0;
    long long int cur;
    scanf("%I64d", &cur);
    for (int i = n - cur; i < n; ++i) {
      swap(answer[0][i], answer[1][i]);
    }
    for (int i = 0; i < n; i++) {
      ans += answer[0][i];
    }
    printf("%I64d\n", ans);
  }
}

