using namespace std;

int dp[50][51][50][51], dp2[2][50][51][60][10], dp3[2][50][51][31];
int visited1[50][51][50][51], visited2[2][50][51][60][10], visited3[2][50][51][31];
vector <int> trans[60];
vector <int> transHash[31];
vector <int> reqLength[2][50][31];

deque <int> inp[2];
int n, m, r;

int caseN;

int transPossible(int, int, int, int, int);

int canConvergeTo(int type, int s, int e, int tarnum)
{
	if(s >= e) return 0;
	int &ret = dp3[type][s][e][tarnum];
	if(visited3[type][s][e][tarnum]) return ret;

	ret = 0;
	for(int i = 0; i < transHash[tarnum].size(); i++)
	{
		int ntind = transHash[tarnum][i];
		if(transPossible(type, s, e, ntind, 0)) return ret = 1;
	}

	return ret;
}

int transPossible(int type, int s, int e, int ttype, int tind)
{
	if(trans[ttype].size() == tind)
	{
		if(s == e) return 1;
		return 0;
	}
	if(s >= e) return 0;
	if(e - s < (int)trans[ttype].size() - tind) return 0;

	int &ret = dp2[type][s][e][ttype][tind];
	if(visited2[type][s][e][ttype][tind] == caseN) return ret;
	visited2[type][s][e][ttype][tind] = caseN;

	ret = 0;
	if(inp[type][s] == trans[ttype][tind] && transPossible(type, s + 1, e, ttype, tind + 1)) return ret = 1;
	int tar = trans[ttype][tind], shouldLeft = (int)trans[ttype].size() - tind - 1;
	for(int i = s + 1; i <= e - shouldLeft; i++)
		if(canConvergeTo(type, s, i, tar) && transPossible(type, i, e, ttype, tind + 1)) return ret = 1;

	return ret;
}

int getAns(int s1, int e1, int s2, int e2)
{
	if(s1 == e1 && s2 == e2) return 0;
	if(s1 >= e1 || s2 >= e2) return -2;

	int &ret = dp[s1][e1][s2][e2];
	if(visited1[s1][e1][s2][e2] == caseN) return ret;
	visited1[s1][e1][s2][e2] = caseN;

	ret = -2;
	int v1 = inp[0][s1], v2 = inp[1][s2];
	int res;

	if(v1 == v2 && (res = getAns(s1 + 1, e1, s2 + 1, e2)) != -2) ret = max(ret, res + 1);

	for(int i = 0; i < reqLength[1][s2][v1].size(); i++)
	{
		int req = reqLength[1][s2][v1][i];
