constexpr auto mxN = 1000010;
bitset<mxN> primes;
vector<long long> primeset;
void sieve() {
  primes.set();
  primes.reset(1);
  for (auto i = (2); i <= (mxN - 1); i++) {
    if (!primes.test(i)) {
      continue;
    }
    for (auto j = i * 2; j < mxN; j += i) {
      primes.reset(j);
    }
  }
  for (auto i = (2); i <= (mxN - 1); i++) {
    if (primes.test(i)) {
      primeset.push_back(long long(i));
    }
  }
}
long long maxn(long long p) {
  auto t = p * 2;
  auto ret = long long(sqrt(t));
  while (ret * (ret + 1) / 2 <= p) ret++;
  return ret - 1;
}
bool isprime(long long n) {
  auto lim = long long(sqrt(n)) + 1;
  for (auto i = (2); i <= (lim); i++) {
    if (n % i == 0) {
      return false;
    }
  }
  return true;
}
long long times(long long num, long long div) {
  auto t = 0;
  while (num % div == 0) {
    t++;
    num /= div;
  }
  return t;
}
void solve() {
  long long n;
  cin >> n;
  if (isprime(n)) {
    cout << "1\n";
    return;
  }
  sieve();
  auto lim = long long(sqrt(n)) + 1LL;
  auto idx = 0;
  auto tot = 0LL;
  while (primeset[idx] <= lim) {
    auto t = times(n, primeset[idx]);
    tot += maxn(t);
    ++idx;
  }
  cout << tot;
  cout << "\n";
}
