class TaskC {

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int[] a = new int[2 * n];
        int sum = 0;
        int countZ = 0;
        for (int i = 0; i < 2 * n; ++i) {
            int x = in.nextInt();
            x = in.nextInt();
            sum += x;
            if (x == 0) ++countZ;
        }

        int res = Math.abs(sum - n * 1000);
        if (countZ > n) countZ = n;
        for (int i = 1; i <= countZ; ++i)
            res = Math.min(res, Math.abs(sum - (n - i) * 1000));

        out.printf(Locale.US, "%.3f\n", res / 1000D);
    }
}

class InputReader {
    BufferedReader in;
    StringTokenizer st;

    public InputReader(InputStream stream) {
        in = new BufferedReader(new InputStreamReader(stream));
        eat("");
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public String next() {
        while (!st.hasMoreTokens())
            eat(nextLine());
        return st.nextToken();
    }

    public String nextLine() {
        try {
            return in.readLine();
        } catch (IOException e) {
            throw new InputMismatchException();
        }
    }

    public void eat(String str) {
        if (str == null) throw new InputMismatchException();
        st = new StringTokenizer(str, " ,.\n");
    }
}

