set<pair<int, int>> gnext[1048576];
const char impossible[] = "IMPOSSIBLE";
int par[1048576];
pair<int, int> range[1048576];
int division[1048576];
int findroot(int nod) {
  return par[nod] == nod ? nod : (par[nod] = findroot(par[nod]));
}
void mergerange(pair<int, int> &dest, pair<int, int> from) {
  if (dest.first == -1) {
    dest = from;
    return;
  }
  dest.first = min(dest.first, from.first);
  dest.second = max(dest.second, from.second);
}
vector<int> ans;
vector<int> pos;
void dfs(int nod, int r) {
  if (nod > r) return;
  if (division[nod] == -1) {
    dfs(nod + 1, r);
    ans.push_back(nod + 1);
  } else {
    dfs(nod + 1, division[nod] - 1);
    ans.push_back(nod + 1);
    dfs(division[nod], r);
  }
}
int main() {
  scanf("%d%d", &n, &c);
  for (int i = 0; i < c; i++) {
    char str[20];
    int a, b;
    scanf("%d%d%s", &a, &b, str);
    a--, b--;
    if (a >= b) {
      puts(impossible);
      return 0;
    }
    if (str[0] == 'L') {
      gnext[a].insert(make_pair(b, 0));
    } else {
      gnext[a].insert(make_pair(b, 1));
    }
  }
  for (int i = 0; i < n; i++) {
    par[i] = i;
    range[i] = make_pair(i, i);
  }
  for (int i = n - 1; i >= 0; i--) {
    auto leftrange = make_pair(-1, -1);
    auto rightrange = make_pair(-1, -1);
    for (auto edge : gnext[i]) {
      if (edge.second == 0) {
        mergerange(leftrange, range[findroot(edge.first)]);
      } else {
        mergerange(rightrange, range[findroot(edge.first)]);
      }
    }
    if (leftrange.first != -1 && rightrange.first != -1 &&
        leftrange.second >= rightrange.first) {
      puts(impossible);
      return 0;
    }
    division[i] = rightrange.first;
    for (auto edge : gnext[i]) {
      int pp = findroot(edge.first);
      par[pp] = i;
      mergerange(range[i], range[pp]);
    }
  }
  dfs(0, n - 1);
  pos.resize(n);
  for (int i = 0; i < n; i++) {
    pos[ans[i] - 1] = i;
  }
  for (int i = 0; i < n; i++) {
    for (auto edge : gnext[i]) {
      int childpos = pos[edge.first];
      int mypos = pos[i];
      if (edge.second == 0) {
        if (!(childpos < mypos)) {
          puts(impossible);
          return 0;
        }
      } else {
        if (!(childpos > mypos)) {
          puts(impossible);
          return 0;
        }
      }
    }
  }
  for (int i = 0; i < n; i++) {
    printf("%d%c", ans[i], " \n"[i + 1 == n]);
  }
  return 0;
}

