#include <bits/stdc++.h>
using namespace std;
const long long mod = 998244353;
const int NMAX = 300300;
const int LMAX = 20;
long long n, k;
int a[NMAX];
vector<int> adj[NMAX];
int par[NMAX][LMAX], dep[NMAX], lc[NMAX];
long long ans = 1;
long long dp[NMAX][2];
bool bad;
void dfs(int u, int p, int d) {
  if (dep[u]) return;
  par[u][0] = p;
  dep[u] = d;
  for (auto& v : adj[u]) {
    dfs(v, u, d + 1);
  }
}
long long modpow(long long b, long long p) {
  long long a = 1;
  while (p) {
    if (p & 1) a = (a * b) % mod;
    b = (b * b) % mod;
    p >>= 1;
  }
  return a;
}
void build() {
  for (int l = 1; l < LMAX; ++l) {
    for (int i = 1; i <= n; ++i) {
      par[i][l] = par[par[i][l - 1]][l - 1];
    }
  }
}
inline void swim(int& u, int d) {
  int l = 0;
  while (d) {
    if (d & 1) u = par[u][l];
    d >>= 1;
    ++l;
  }
}
inline int lca(int u, int v) {
  if (dep[u] < dep[v]) swap(u, v);
  int d = dep[u] - dep[v];
  swim(u, dep[u] - dep[v]);
  for (int l = LMAX - 1; l >= 0; l--) {
    if (par[u][l] != par[v][l]) {
      u = par[u][l];
      v = par[v][l];
    }
  }
  if (u != v) u = par[u][0];
  return u;
}
int dfs2(int u) {
  int tc = 0;
  for (auto& v : adj[u]) {
    if (dep[v] != dep[u] + 1) continue;
    int nc = dfs2(v);
    if (tc == 0)
      tc = nc;
    else if (tc != nc && nc) {
      tc = -1;
    }
  }
  if (tc == 0) {
    tc = a[u];
  }
  if (tc != a[u] && a[u]) {
    tc = -1;
  }
  if (tc == -1) {
    return -1;
  }
  if (lc[u]) {
    if (lc[u] != tc) {
      return -1;
    }
    return 0;
  }
  return tc;
}
int dfs3(int u) {
  int cc = 0;
  int tc = 0;
  for (auto& v : adj[u]) {
    if (dep[v] != dep[u] + 1) continue;
    ++cc;
    tc = max(tc, dfs3(v));
  }
  if (cc = 0) {
    dp[u][0] = 0;
    dp[u][1] = 1;
    return 0;
  }
  if (!tc && a[u]) {
    dp[u][0] = 1;
    dp[u][1] = 0;
    for (auto& v : adj[u]) {
      if (dep[v] != dep[u] + 1) continue;
      dp[u][0] = (dp[v][1] + (dp[v][0] != 0)) * dp[u][0] % mod;
    }
    tc = a[u];
  } else if (tc) {
    dp[u][0] = 1;
    dp[u][1] = 0;
    for (auto& v : adj[u]) {
      if (dep[v] != dep[u] + 1) continue;
      dp[u][0] = (dp[v][0] + dp[v][1]) * dp[u][0] % mod;
    }
  } else {
    dp[u][1] = 1;
    for (auto& v : adj[u]) {
      if (dep[v] != dep[u] + 1) continue;
      dp[u][1] = (dp[v][1] + dp[v][0]) * dp[u][1] % mod;
    }
    dp[u][0] = 0;
    for (auto& v : adj[u]) {
      dp[u][0] = (dp[u][0] + (dp[u][1] * dp[v][0] % mod) *
                                 modpow(dp[v][0] + dp[v][1], mod - 2)) %
                 mod;
    }
  }
  if (lc[u]) {
    assert(tc);
    return 0;
  }
  return tc;
}
