const long long N = 1e5 + 9;
long long n, k, add, ans, lim;
long long pw[N], pos[N];
vector<long long> luck;
vector<long long> v;
void rec(long long num, long long x) {
  if (!x) return;
  luck.push_back(num);
  rec(num * 10 + 4, x - 1);
  rec(num * 10 + 7, x - 1);
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> k;
  rec(0, 15);
  sort(luck.begin(), luck.end());
  pw[1] = pw[0] = 1;
  long long z = 2;
  long long cur = 2;
  if (k > 1) {
    while (1) {
      pw[cur] = pw[cur - 1] * z;
      z++;
      if (pw[cur] >= k) break;
      cur++;
    }
  } else
    cur = 1;
  if (pw[n] != 0 && pw[n] < k) {
    cout << "-1";
    return 0;
  }
  lim = cur;
  if (n > lim) {
    add = n - lim;
    ans += upper_bound(luck.begin(), luck.end(), n - lim) - luck.begin() - 1;
    n = lim;
  }
  for (long long i = 0; i < (n); i++) v.push_back(i + 1);
  for (long long i = n - 1; i >= 0; i--) {
    long long kam = ((k - 1) / pw[i]) * pw[i];
    pos[i] = v[(k - 1) / pw[i]];
    k -= kam;
    long long del = 0;
    while (v[del] != pos[i]) del++;
    for (long long j = del + 1; j < v.size(); j++) swap(v[j], v[j - 1]);
    v.pop_back();
    if (find(luck.begin(), luck.end(), add + n - i) != luck.end() &&
        pos[i] == n - i)
      ans++;
  }
  cout << ans;
}

