public class Main {
    static ArrayList<Integer> tree[];
    static int n;
    static long cost[];
    static boolean isviable[];
    static int size[],atob[],btoa[],change[];
    static long ans;
    static boolean[] ini,fin;
    static Node dfs(int u,int p,int mincost){
        if(cost[u]<mincost)
            isviable[u]=true;
        int s=1,ntr=0,ftr=0,ch=0;
        for(int v:tree[u]){
            if(v!=p){
                Node nod=dfs(v,u,(int)Math.min(mincost,cost[u]));
                s+=nod.nsize;
                ntr+=nod.atob;
                ftr+=nod.btoa;
                ch+=nod.change;
            }
        }
        if(ini[u] && !fin[u])
            ntr++;
        if(!ini[u] && fin[u])
            ftr++;
        if(ini[u]!=fin[u])
            ch++;
        size[u]=s;
        atob[u]=ntr;
        btoa[u]=ftr;
        change[u]=ch;
        return new Node(s,ntr,ftr,ch);

    }

    static Node1 dfs1(int u,int p){
        int ab=0,ba=0;
        for(int v:tree[u]){
            if(v!=p){
                Node1 nod=dfs1(v,u);
                ab+=nod.ab;
                ba+=nod.ba;
            }
        }
        atob[u]-=ab;
        btoa[u]-=ba;
        if(!isviable[u]){
            return new Node1(ab,ba);
        }
        int z=Math.min(atob[u],btoa[u]);
        ans+=2*z*cost[u];
        ab+=z;
        ba+=z;
        return new Node1(ab,ba);

    }
