public class Polycarp_Restores_Permutation {

	public static void main(String[] args) {

		int n,i,sum=0,minm=0;
		boolean flag=true;
		Set<Integer> set = new HashSet<>();

		int[] p=new int[200002];
		int[] q=new int[200002];
		int[] r=new int[200002];


		Scanner scanner=new Scanner(System.in);

		n=scanner.nextInt();

		for(i=0;i<n-1;i++) {
			int x=scanner.nextInt();
			q[i]=x;
			sum+=x;
			r[i]=sum;
			minm=Math.min(minm,sum);
		}

		p[0]=1-minm;
		set.add(p[0]);

		for(i=1;i<n;i++) {
			p[i]=p[0]+r[i-1];
			set.add(p[i]);
		}

		if(set.size() != n) {
			flag=false;
		}

		for(i=0;i<n;i++) {
			if(p[i]<0 || p[i]>n) flag=false;
		}

		if(flag) {
			for(i=0;i<n;i++) {
				System.out.print(p[i]+" ");
			}
