public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;OutputStream outputStream = System.out;FastScanner in = new FastScanner(inputStream);PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();solver.solve(1, in, out);
        out.close();
    }
    static class TaskA {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();int k = in.nextInt();
            int[][] a = new int[4][n];
            for (int i = 0; i < 4; i++) for (int j = 0; j < n; j++) a[i][j] = in.nextInt();
            List<String> ans = new ArrayList<>();
            while (true) {
                for (int i = 0; i < n; i++) {
                    if (a[1][i] != 0 && a[1][i] == a[0][i]) {
                        ans.add(a[1][i] + " " + 1 + " " + (i + 1));
                        a[0][i] = 0;
                        a[1][i] = 0;
                    }
                    if (a[2][i] != 0 && a[2][i] == a[3][i]) {
                        ans.add(a[2][i] + " " + 4 + " " + (i + 1));
                        a[2][i] = 0;
                        a[3][i] = 0;
                    }
                }
                boolean haveEmpty = false;
                boolean allDone = true;
                int er = -1;
                int ec = -1;
                for (int i = 0; i < n; i++) {
                    if (a[1][i] == 0) {
                        haveEmpty = true;
                        er = 1;
                        ec = i;
                    }
                    if (a[2][i] == 0) {
                        haveEmpty = true;
                        er = 2;
                        ec = i;
                    }
                    if (a[1][i] != 0 || a[2][i] != 0) {
                        allDone = false;
                    }
                }
                if (!haveEmpty || allDone) {
                    break;
                }
                // Shift clockwise.
                List<Integer> orderR = new ArrayList<>();
                List<Integer> orderC = new ArrayList<>();
                if (er == 1) {
                    for (int c = ec; c < n; c++) {
                        orderR.add(1);
                        orderC.add(c);
                    }
                    for (int c = n - 1; c >= 0; c--) {
                        orderR.add(2);
                        orderC.add(c);
                    }
                    for (int c = 0; c < ec; c++) {
                        orderR.add(1);
                        orderC.add(c);
                    }
                } else {
                    for (int c = ec; c >= 0; c--) {
                        orderR.add(2);
                        orderC.add(c);
                    }
                    for (int c = 0; c < n; c++) {
                        orderR.add(1);
                        orderC.add(c);
                    }
                    for (int c = n - 1; c > ec; c--) {
                        orderR.add(2);
                        orderC.add(c);
                    }
                }
                for (int i = 1; i < orderR.size(); i++) {
                    int r = orderR.get(i);
                    int c = orderC.get(i);
                    int pr = orderR.get(i - 1);
                    int pc = orderC.get(i - 1);
                    if (a[r][c] != 0) {
                        ans.add(a[r][c] + " " + (pr + 1) + " " + (pc + 1));
                        a[pr][pc] = a[r][c];
                        a[r][c] = 0;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                if (a[1][i] != 0 || a[2][i] != 0) {
                    out.println(-1);
                    return;
                }
            }
            out.println(ans.size());
            for (String s : ans) {
                out.println(s);
            }
        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String rl = in.readLine();
                    if (rl == null) {
                        return null;
                    }
                    st = new StringTokenizer(rl);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

