public class Main {

    public static void main(String[] args) throws UnsupportedEncodingException, IOException {
        Reader.init(System.in);
        StringBuilder out = new StringBuilder();
        int n = Reader.nextInt(), m[] = new int[n];
        for(int i = 0; i < n; i++)
            m[i] = Reader.nextInt();
        int cur = -1;
        for(int i = n - 1; i > -1; i--)
            if(m[i] == i) {
                cur = i;
                break;
            }
        long[] d = new long[n];
        long sum = 0;
        for(int i = n - 2; i > -1; i--)
            d[i] = Math.max(d[i], m[i + 1] - m[i] - 1);
        for(int i = 1; i < n; i++) {
            if(i <= cur)
                d[i] = i - m[i];
            else d[i] = Math.max(d[i - 1] + m[i - 1] - m[i], Math.max(d[i], 0));
        }
        for(int i = 0; i < n; i++)
            sum += d[i];
        out.append(sum).append('\n');
        PrintWriter pw = new PrintWriter(System.out);
        pw.print(out);
        pw.close();
    }
}

