#include <bits/stdc++.h>
using namespace std;
const double PI = acos(-1);
complex<double> unit(complex<double> p) { return p / abs(p); }
pair<complex<double>, complex<double> > norm(complex<double> p) {
  return make_pair(p * complex<double>(0, 1), p * complex<double>(0, -1));
}
double dot(complex<double> x, complex<double> y) { return real(conj(x) * y); }
double cross(complex<double> x, complex<double> y) { return imag(conj(x) * y); }
complex<double> rotate(complex<double> v, double s) {
  return complex<double>(real(v) * cos(s) - imag(v) * sin(s),
                         real(v) * sin(s) + imag(v) * cos(s));
}
double arg(complex<double> a, complex<double> b, complex<double> c) {
  return acos(dot(b - a, c - a) / (abs(b - a) * abs(c - a)));
}
double arg(double a, double b, double c) {
  return acos((b * b + c * c - a * a) / (2 * b * c));
}
bool in_cir(pair<complex<double>, double> c, complex<double> x) {
  return (abs(x - c.first) + (1e-8) < c.second);
}
bool on_cir(pair<complex<double>, double> c, complex<double> x) {
  return (abs((abs(x - c.first)) - (c.second)) < (1e-8));
}
int cpr(pair<complex<double>, double> a, pair<complex<double>, double> b) {
  double d = abs(a.first - b.first);
  if (a.second + b.second + (1e-8) < d) return -1;
  if (b.second + d + (1e-8) < a.second) return 1;
  if (a.second + d + (1e-8) < b.second) return 2;
  if (abs(a.second + b.second - d) < (1e-8)) return -3;
  if (abs(b.second + d - a.second) < (1e-8)) return 3;
  if (abs(a.second + d - b.second) < (1e-8)) return 4;
  return 0;
}
vector<complex<double> > cp_cir_to_cir(pair<complex<double>, double> a,
                                       pair<complex<double>, double> b) {
  vector<complex<double> > v;
  int pos = cpr(a, b);
  if (pos == 0) {
    double s = arg(b.second, abs(b.first - a.first), a.second);
    complex<double> x = a.second * unit(b.first - a.first);
    v.push_back(a.first + rotate(x, s));
    v.push_back(a.first + rotate(x, -s));
  } else if (abs(pos) >= 3) {
    v.push_back(a.first + a.second * unit(b.first - a.first));
  }
  return v;
}
double angle(complex<double> p, pair<complex<double>, double> c) {
  complex<double> O = c.first,
                  A = complex<double>(c.first.real(),
                                      c.first.imag() + c.second),
                  B = p;
  double res = arg(O, A, B);
  if (cross(A - O, B - O) > (1e-8)) res = 2 * PI - res;
  return res;
}
int n;
pair<complex<double>, double> c[110];
double x, y, r;
int main() {
  while (cin >> n, n) {
    for (int i = 0; i < (int)(n); i++) {
      cin >> x >> y >> r;
      c[i] = pair<complex<double>, double>(complex<double>(x, y), r);
    }
    vector<double> cp_list[110];
    for (int i = 0; i < (int)(n); i++) {
      for (int j = (int)(i + 1); j < (int)(n); j++) {
        vector<complex<double> > p = cp_cir_to_cir(c[i], c[j]);
        if ((int)p.size() == 2) {
          for (int k = 0; k < (int)(2); k++)
            cp_list[i].push_back(angle(p[k], c[i]));
          for (int k = 0; k < (int)(2); k++)
            cp_list[j].push_back(angle(p[k], c[j]));
        }
      }
    }
    for (int i = 0; i < (int)(n); i++)
      sort((cp_list[i]).begin(), (cp_list[i]).end());
    double ans = 0;
    for (int i = 0; i < (int)(n); i++) {
      if (cp_list[i].empty()) {
        bool f = true;
        for (int j = 0; j < (int)(n); j++) {
          if (i == j) continue;
          if (in_cir(c[j], c[i].first)) f = false;
        }
        if (f) ans += 2 * PI * c[i].second;
      } else {
        for (int j = 0; j < (int)(cp_list[i].size()); j++) {
          double s;
          if (j + 1 < (int)cp_list[i].size())
            s = (cp_list[i][j] + cp_list[i][j + 1]) / 2;
          else
            s = (cp_list[i][j] + cp_list[i][0] + 2 * PI) / 2;
          complex<double> p =
              rotate(complex<double>(0, c[i].second), -s) + c[i].first;
          bool f = true;
          for (int k = 0; k < (int)(n); k++) {
            if (in_cir(c[k], p)) f = false;
          }
          double seta = cp_list[i][(j + 1) % cp_list[i].size()] - cp_list[i][j];
          if (seta < 0) seta += 2 * PI;
          if (f) ans += seta * c[i].second;
        }
      }
    }
    cout << fixed << setprecision(10) << ans << endl;
  }
}

