#include <bits/stdc++.h>
using namespace std;
int K[10], n, L[10], Lv[10], a;
long double res;
void gen(int st, int col) {
  if (st != n - 1) {
    for (int i = 0; i < col; i++) {
      K[st] = i;
      gen(st + 1, col - i);
    }
    return;
  }
  int p, j, cnt, cnt2;
  long double v, tres;
  K[st] = col, tres = 0.0;
  for (p = 0; p < (1 << n); p++) {
    v = 1.0;
    for (j = 0, cnt = 0, cnt2 = 0; j < n; j++) {
      if (p & (1 << j))
        v *= min(1.0, ((double)(L[j] + K[j])) / 10.0), cnt++;
      else
        v *= max(0.0, ((double)(10.0 - L[j] - K[j]) / 10.0)), cnt2 += Lv[j];
    }
    if (2 * cnt > n) continue;
    tres += (v * ((double)cnt2)) / ((double)(cnt2 + a));
  }
  res = max(res, 1.0 - tres);
}
int main() {
  int i, k;
  scanf("%d%d%d", &n, &k, &a);
  for (i = 0; i < n; i++) {
    scanf("%d%d", &Lv[i], &L[i]);
    L[i] /= 10;
  }
  gen(0, k);
  printf("%.8lf\n", (double)res);
  return 0;
}

