template <class T>
T next_combination(T combi)
{
	T leastBit = combi & -combi;
	T mostBits = combi + leastBit;
	T leastSequentialBits = combi & ~mostBits;
	return mostBits | ((leastSequentialBits / leastBit) >> 1);
}
