int dfs(int x, int y) {
  if (vis[x][y] == 1) return 0;
  if ((grid[x][y] == grid[x][y + 1]) || (grid[x][y] == grid[x][y - 1]) ||
      (grid[x - 1][y] == grid[x][y]) || (grid[x + 1][y] == grid[x][y])) {
    if (it < com) {
      com = it;
      return com;
    }
  }
  vis[x][y] = 1;
  it++;
  if (y < col) dfs(x, y + 1);
  if (x < row) dfs(x + 1, y);
  if (x > 1) dfs(x - 1, y);
  if (y > 1) dfs(x, y - 1);
  return com;
}
