		{
		//	System.out.println(node+"--");
			stree[node] = a[ll];
			return;

		}

		int mid = (ll+rl)/2;
		build(2*node +1, ll, mid);
		build(2*node +2, mid+1, rl);
		//System.out.println(node+stree[2*node+1]+" "+stree[2*node+2]+" "+(2*node+1));

		stree[node] = stree[2*node+1] & stree[2*node+2];


