	public static void update(int node, int ll, int rl, int idx, int n, long el)
	{


		if(ll>rl)
			return;

		if(ll==rl)
		{
			stree[node] = el;
			return;
		}

		int mid = (ll+rl)/2;

		if(ll<=idx && idx<=mid)
			update(2*node+1, ll, mid, idx, n-1, el);
		else
			update(2*node+2, mid+1, rl, idx, n-1, el);

		if(n%2==0)
			stree[node] = stree[2*node+1] ^ stree[2*node+2];
		else
			stree[node] = stree[2*node+1] | stree[2*node+2];




	}

	public static int query(int node, int start, int end, int l, int r)
	{
	    if(r < start ||  end < l)
	       return -1;

	    if(l <= start && end <= r)
	    	return (int)stree[node];

	    int mid = (start + end) / 2;
	    int p1 = query(2*node, start, mid, l, r);
	    int p2 = query(2*node+1, mid+1, end, l, r);
	    return (p1 + p2);
	}

