    long long tmp = dp[k];
    for (long long i = 0; i < min(k, (long long)a[l].size()); i++) {
      tmp = max(tmp, dp[k - i - 1] + a[l][i]);
    }
    ans = max(ans, tmp);
    return;
  }
  vector<pair<long long, long long> > changes;
  long long mid = (l + r) / 2;
  for (long long i = mid + 1; i <= r; i++) {
    long long sz = a[i].size();
    long long val = a[i].back();
    for (long long j = sz; j <= k; j++) {
      if (dp[j] < dp[j - sz] + val) {
        changes.push_back({j, dp[j]});
        dp[j] = dp[j - sz] + val;
      }
    }
  }
  solve(l, mid);
  for (long long i = (long long)changes.size() - 1; i >= 0; i--) {
    pair<long long, long long> foo = changes[i];
    dp[foo.first] = foo.second;
  }
  changes.clear();
  for (long long i = l; i <= mid; i++) {
    long long sz = a[i].size();
    long long val = a[i].back();
    for (long long j = sz; j <= k; j++) {
      if (dp[j] < dp[j - sz] + val) {
        changes.push_back({j, dp[j]});
        dp[j] = dp[j - sz] + val;
