#include <bits/stdc++.h>
using namespace std;
long long mod0 = 10000000000LL, mod1 = 10000000001LL, mod;
long long sum1(long long a, long long b) {
  long long v = b, w = b + 1, x = a, y = a - 1;
  if (v % 2 == 0)
    v /= 2;
  else
    w /= 2;
  if (x % 2 == 0)
    x /= 2;
  else
    y /= 2;
  long long ret = (v * w - x * y) % mod;
  return ret;
}
long long sum2(long long a, long long b) {
  long long v = b, w = b + 1, u = 2 * b + 1, p = a, r = a - 1, s = 2 * a - 1;
  if (v % 2 == 0)
    v /= 2;
  else
    w /= 2;
  if (p % 2 == 0)
    p /= 2;
  else
    r /= 2;
  if (v % 3 == 0)
    v /= 3;
  else if (w % 3 == 0)
    w /= 3;
  else
    u /= 3;
  if (p % 3 == 0)
    p /= 3;
  else if (r % 3 == 0)
    r /= 3;
  else
    s /= 3;
  long long l = ((v * w) % mod * u) % mod - ((p * r) % mod * s) % mod;
  return l % mod;
}
long long sumUp(long long x1, long long x2, long long y1, long long y2) {
  long long ret = ((1 + x2 - x1) * sum2(y1, y2)) % mod;
  long long v = y2 - y1 + 1, w = x2 * x2 + 2 + 3 * x2 - x1 - x1 * x1;
  if (v % 2 == 0)
    v /= 2;
  else
    w /= 2;
  w %= mod;
  return (ret + v * w) % mod;
}
long long sumDn(long long x1, long long x2, long long y1, long long y2) {
  long long ret = ((1 + y2 - y1) * sum2(x1 + 1, x2 + 1)) % mod;
  long long v = x2 - x1 + 1, w = y1 * y1 - y2 * y2 - y1 - y2;
  if (v % 2 == 0)
    v /= 2;
  else
    w /= 2;
  w %= mod;
  return (ret + v * w) % mod;
}
long long sumUhl(long long a, long long b) {
  long long v = ((b + 1) * (b + 1) + 1), u = b + 1, w = (a * a + 1), p = a;
  if (v % 2 == 0)
    v /= 2;
  else
    u /= 2;
  if (w % 2 == 0)
    w /= 2;
  else
    p /= 2;
  v %= mod;
  w %= mod;
  long long ret = ((v * u) % mod * (b + 1)) % mod - ((w * p) % mod * a) % mod;
  return (ret - sumUp(0, a - 1, a, b) - sumDn(a, b, 0, a - 1)) % mod;
}
