public class Close_Tuples_easy_version {
    public static int findGoalsIndex(int max, int hi, int lo, Integer[] arr) {
        int mid = 0;
        while (lo <= hi) {
            mid = lo + (hi - lo) / 2;
            if (max - arr[mid] <= 2) {
                hi = mid - 1;
            } else lo = mid + 1;
            mid = lo + (hi - lo) / 2;
        }
        return mid;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st;
        int t = Integer.parseInt(br.readLine());
        while (t-- > 0) {
            int n = Integer.parseInt(br.readLine());
            Integer[] arr = new Integer[n];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i++) {
                arr[i] = Integer.parseInt(st.nextToken());
            }
            Arrays.sort(arr);
            long ans = 0;
            for (int i = n - 1; i >= 2; i--) {
                int hiSecond = i - 1;
                int hiThird = i - 2;
                int lo = 0;

                long idxSecond = findGoalsIndex(arr[i], hiSecond, lo, arr);
                long idxThird = findGoalsIndex(arr[i], hiThird, lo, arr);

                ans += ((hiThird - idxThird + 1) * (hiSecond - idxSecond + 1)) /2;
               // System.out.println(idxSecond + " " + idxThird + " " + ans);

            }
            pw.println(ans);
        }
        pw.close();
        pw.flush();
    }
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 2;
long long gcd(long long a, long long b) {
  if (b > a) {
    return gcd(b, a);
  }
  if (b == 0) {
    return a;
  }
  return gcd(b, a % b);
}
long long expo(long long a, long long b, long long mod) {
  long long res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % mod;
    a = (a * a) % mod;
    b = b >> 1;
  }
  return res;
}
long long mminvprime(long long a, long long b) { return expo(a, b - 2, b); }
vector<long long> sieve(int n) {
  int* arr = new int[n + 1]();
  vector<long long> vect;
  for (int i = 2; i <= n; i++)
    if (arr[i] == 0) {
      vect.push_back(i);
      for (int j = 2 * i; j <= n; j += i) arr[j] = 1;
    }
  return vect;
}
long long mod_add(long long a, long long b, long long m) {
  a = a % m;
  b = b % m;
  return (((a + b) % m) + m) % m;
}
long long mod_mul(long long a, long long b, long long m) {
  a = a % m;
  b = b % m;
  return (((a * b) % m) + m) % m;
}
long long mod_sub(long long a, long long b, long long m) {
  a = a % m;
  b = b % m;
  return (((a - b) % m) + m) % m;
}
long long mod_div(long long a, long long b, long long m) {
  a = a % m;
  b = b % m;
  return (mod_mul(a, mminvprime(b, m), m) + m) % m;
}
int fact[N];
void precalc() {
  fact[0] = 1;
  for (int i = 1; i < N; i++) {
    fact[i] = mod_mul(fact[i - 1], i, 1000000007);
  }
}
long long mod(long long x) {
  return ((x % 1000000007 + 1000000007) % 1000000007);
}
long long inv(long long x) { return expo(x, 1000000007 - 2, 1000000007); }
long long divide(long long a, long long b) {
  return mod_mul(a, inv(b), 1000000007);
}
long long nCr(long long n, long long r) {
  return divide(fact[n], mod_mul(fact[r], fact[n - r], 1000000007));
}
long long computeXOR(long long n) {
  if (n % 4 == 0) return n;
  if (n % 4 == 1) return 1;
  if (n % 4 == 2) return n + 1;
  return 0;
}
