#include <bits/stdc++.h>
using namespace std;
double eps = 1e-8;
struct P {
  long long x, y;
  P(long long a = 0, long long b = 0) : x(a), y(b) {}
};
int n;
long long w, h, x, y, r, W, H;
P A, V;
P t[20];
double calc(P p) {
  double vx = V.x;
  double vy = V.y;
  double px = p.x - A.x;
  double py = p.y - A.y;
  double dot = vx * px + vy * py;
  if (dot < 0) return 1.0 / 0.0;
  double cross = abs(px * vy - vx * py);
  return cross / sqrt(vx * vx + vy * vy);
}
double calc2(P p) {
  double ax = A.x;
  double ay = A.y;
  double px = p.x - A.x;
  double py = p.y - A.y;
  return sqrt((ax - px) * (ax - px) + (ay - py) * (ay - py));
}
void func() {
  double xx = (double)(W - A.x) / (double)V.x;
  double yy = (double)(H - A.y) / (double)V.y;
  if (xx < yy - eps) {
    for (int i = 0; i < n; i++) t[i].x = W + w - t[i].x;
    W += w;
  } else if (yy < xx - eps) {
    for (int i = 0; i < n; i++) t[i].y = H + h - t[i].y;
    H += h;
  } else {
    for (int i = 0; i < n; i++) {
      t[i].x = W + w - t[i].x;
      t[i].y = H + h - t[i].y;
    }
    W += w;
    H += h;
  }
}
int solve() {
  for (int I = 0; I < 100000; I++) {
    double mini = 1e9;
    int id;
    for (int i = 0; i < n; i++) {
      double dist = calc(t[i]);
      if (dist > r + r) continue;
      double dist2 = calc2(t[i]);
      double dist3 = sqrt(abs(4.0 * (double)r * (double)r - dist * dist));
      double dist4 = sqrt(abs(dist2 * dist2 - dist * dist)) - dist3;
      if (dist4 < mini) mini = dist, id = i;
    }
    if (mini < 1e9) {
      if (mini > 10000.0) break;
      return id + 2;
    }
    func();
  }
  return -1;
}
int main() {
  while (1) {
    cin >> n;
    if (n == 0) break;
    n--;
    cin >> w >> h >> r;
    W = w;
    H = h;
    cin >> V.x >> V.y >> A.x >> A.y;
    for (int i = 0; i < n; i++) cin >> t[i].x >> t[i].y;
    if (V.x < 0) {
      V.x *= -1;
      for (int i = 0; i < n; i++) t[i].x = w - t[i].x;
      A.x = w - A.x;
    }
    if (V.y < 0) {
      V.y *= -1;
      for (int i = 0; i < n; i++) t[i].y = h - t[i].y;
      A.y = h - A.y;
    }
    cout << solve() << endl;
  }
  return 0;
}

