public class Main {
    class Node implements Comparable<Node> {
        long val;
        int id;

        @Override
        public int compareTo(Node o) {
            // TODO Auto-generated method stub
            if (val < o.val) {
                return -1;
            } else if (val == o.val) {
                return 0;
            } else {
                return 1;
            }
        }

    }

    int n;
    long A, cf, cm;
    long m;
    Node[] a;
    long[] sum;
    int MIN = 0;
    int left = 0;

    boolean judge(long mm, long target, int r) {
        for (int i = 0; i <= r; i++) {
            if (target > a[i].val) {
                mm -= (target - a[i].val);
                if (mm < 0)
                    return false;
            }
        }
        return true;
    }

    long calc(int pos) {
        long mm = m - sum[pos];
        long l = a[0].val;
        long r = A;
        long res = 0;
        while (l <= r) {
            long mid = (l + r) >> 1;
            if (judge(mm, mid, pos - 1)) {
                l = mid + 1;
                res = Math.max(res, (n - pos) * cf + mid * cm);
                MIN = (int) mid;
            } else {
                r = mid - 1;
            }
        }
        return res;
    }

    //ternary search
    long Search(int l, int r) {
        left = l;
        int mid_left;
        int mid_right;
        long res = 0;
        while (l +64<= r) {
            int d = (r - l + 1) / 3;
            mid_left = l + d;
            mid_right = r - d;

            int oldMIN = MIN;
            long ansl = calc(mid_left);
            long lmin = MIN;
            long ansr = calc(mid_right);
            long rmin = MIN;
            if (ansl < ansr) {
                l = mid_left + 1;
                if(ansr>res){
                    res = ansr;
                    left = mid_right;
                    MIN = (int) rmin;
                }else{
                    MIN =oldMIN;
                }
            } else {
                r = mid_right - 1;
                if(ansl>res){
                    res = ansl;
                    left = mid_left;
                    MIN = (int) lmin;
                }else{
                    MIN =oldMIN;
                }
            }
        }

        for (int i = l; i <= r; i++) {
            int pMIN = MIN;
            long ans = calc(i);
            if (ans > res) {
                res = ans;
                left = i;
            }else{
                MIN = pMIN;
            }
        }

        return res;
    }

    void solve() {
        FastScanner scan = new FastScanner();
        n = scan.nextInt();
        A = scan.nextLong();
        cf = scan.nextLong();
        cm = scan.nextLong();
        m = scan.nextLong();
        a = new Node[n + 1];
        sum = new long[n + 1];

        for (int i = 0; i < n; i++) {
            a[i] = new Node();
            a[i].val = scan.nextLong();
            a[i].id = i;
        }

        Arrays.sort(a, 0, n);
        int leftMost = 0;
        for (int i = n - 1; i >= 0; i--) {
            sum[i] = sum[i + 1] + (A - a[i].val);
            if (sum[i] > m) {
                leftMost = i + 1;
                break;
            }
        }
        long ans = Search(leftMost, n);
        long[] ansA = new long[n + 1];
        PrintWriter out = new PrintWriter(System.out);
        for (int i = 0; i < n; i++) {
            int id = a[i].id;
            ansA[id] = a[i].val;

            if (i >= left) {
                ansA[id] = A;
            }else if (ansA[id] < MIN) {
                ansA[id] = MIN;
            }
        }

        out.println(ans);
        for (int i = 0; i < n; i++) {
            out.print(ansA[i] + " ");
        }
        out.println();

        out.flush();
    }

    public static void main(String[] args) {
        new Main().solve();
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public boolean EOF() {
            if (st != null && st.hasMoreTokens()) {
                return false;
            } else {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (line == null)
                    return true;
                st = new StringTokenizer(line);
                return false;
            }
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

