int solve(string &num){
	if(num.size() <= 1) return 0;

	vector<vector<int>> dp(num.size()+1,vector<int>(2,INF));

	if((num[0] - '1')%3 <= (num[1] - '1')%3)dp[1][1] = 0;
	if((num[0] - '1')%3 >= (num[1] - '1')%3)dp[1][0] = 0;

	for(int i = 2; i < num.size(); i++){
		if((num[i] - '1')%3 >= (num[i-1] - '1')%3) dp[i][1] = min(dp[i-1][0],dp[i-1][1] + 1);
		if((num[i] - '1')%3 <= (num[i-1] - '1')%3) dp[i][0] = min(dp[i-1][1],dp[i-1][0] + 1);
	}

	return min(dp[num.size()-1][0],dp[num.size()-1][1]);
}

