bool increase(vector<long long>& v) {
  for (int i = 1; i < v.size(); ++i)
    if (v[i] <= v[i - 1]) return false;
  return true;
}
bool pre(vector<long long>& v) {
  if (!increase(v)) {
    reverse(v.begin(), v.end());
    s += 'R';
  }
  if (!increase(v)) return false;
  s += 'P';
  ++m;
  for (int i = n - 1; i; --i) v[i] -= v[i - 1];
  return true;
}
string rec(long long x, long long y, long long a, long long b) {
  if (min(a, b) < min(x, y)) return "+";
  if (x == a && y == b) return "";
  if (x == b && y == a) return "R";
  if (a > b) {
    string s = rec(x, y, b, a);
    if (s == "+") return s;
    if (s[0] == '!') return s;
    return s + "R";
  }
  if (min(x, y) == a) {
    long long z = max(x, y);
    if (b < z || (b - z) % a) return "+";
    m += (b - z) / a;
    if (m > 200000) return "!" + to_string(m);
    return rec(x, y, a, z) + string((b - z) / a, 'P');
  }
  string s = rec(x, y, a, b % a);
  if (s == "+") return s;
  m += b / a;
  if (m > 200000) return "!" + to_string(m);
  return s + string(b / a, 'P');
}
