using namespace std;

typedef pair<int,int> pii;

int dp[1 << 20];
int prev[1 << 20];

void output(int n, int x){
	printf("You can go home in %d steps.\n", x);

	vector<int> v;
	v.push_back(n << 16 | 1 << n);
	while(prev[v.back()] != -1){
		v.push_back(prev[v.back()]);
	}

	for(int i = v.size() - 1; i > 0; --i){
		int now = v[i], next = v[i-1];
		if((now >> 16) != (next >> 16)){
			printf("Move to room %d.\n", next >> 16);
		}
		else{
			for(int j = 1; j <= n; ++j){
				if((now ^ next) >> j & 1){
					if(now >> j & 1){
						printf("Switch off room %d.\n", j);
					}
					else{
						printf("Switch on room %d.\n", j);
					}
				}
			}
		}
	}
}

int solve(int n, int m){
	memset(dp, 127, sizeof dp);
	memset(prev, -1, sizeof prev);

	vector<vector<int> > G(n + 1), sw(n + 1);
	int s, t;
	for(int i = 0; i < m; ++i){
		scanf("%d%d", &s, &t);
		G[s].push_back(t);
		G[t].push_back(s);
	}

	int state = 1 << 16;
	for(int i = 1; i <= n; ++i){
		scanf("%d", &s);
		state |= s << i;
	}

	for(int i = 1; i <= n; ++i){
		scanf("%d", &s);
		sw[i].resize(s);
		for(int j = 0; j < s; ++j){
			scanf("%d", &sw[i][j]);
		}
		sort(sw[i].begin(), sw[i].end());
	}

	if(!(state & 2)){ return 2; }

	int goal = n << 16 | 1 << n;

	priority_queue<pii,vector<pii>,greater<pii> > pq;
	pq.push(pii(0, state));
	dp[state] = 0;
	int result = 2;
	while(!pq.empty()){
		int x = pq.top().first;
		state = pq.top().second;
		pq.pop();
		if(dp[state] != x){ continue; }

		if(state == goal){
			output(n, x);
			return 0;
		}

		int room = state >> 16;
		if(room == n){
			result = 1;
		}

		for(int i = 0; i < G[room].size(); ++i){
			int to = G[room][i];
			int next = state & 0xffff | to << 16;
			if(state >> to & 1 && dp[next] > x + 1){
				dp[next] = x + 1;
				prev[next] = state;
				pq.push(pii(x + 1, next));
			}
		}

		for(int i = 0; i < sw[room].size(); ++i){
			int next = state ^ (1 << sw[room][i]);
			if(state >> room & 1 && dp[next] > x + 1){
				dp[next] = x + 1;
				prev[next] = state;
				pq.push(pii(x + 1, next));
			}
		}
	}

	return result;
}

int main(){
	int n, m;
	while(scanf("%d%d", &n, &m), n){
		int res = solve(n, m);
		if(res == 1){
			puts("You can not switch off all lights.");
		}
		else if(res == 2){
			puts("Help me!");
		}
	}
}

#include <bits/stdc++.h>
using namespace std;

#define rep(i, N) for (int i = 0; i < N; i++)
#define pb push_back

typedef long long ll;
typedef pair<ll, int> ll_i;
struct edge { int v, w; };
const ll INF = LLONG_MAX / 3;
const int MOD = 1e9 + 114514;

pair<vector<ll>, vector<int>> dijkstra(int N, vector<vector<edge>>& G, int s) {
	vector<ll> d(N, INF); d[s] = 0;
	vector<int> way(N); way[s] = 1;
	priority_queue<ll_i, vector<ll_i>, greater<ll_i>> pq;
	pq.push(ll_i(0, s));
	while (pq.size()) {
		ll_i p = pq.top(); pq.pop();
		int u = p.second;
		if (p.first > d[u]) continue;
		for (edge e: G[u]) {
			if (d[e.v] > d[u] + e.w) {
				d[e.v] = d[u] + e.w;
				way[e.v] = 0;
				pq.push(ll_i(d[e.v], e.v));
			}
			if (d[e.v] == d[u] + e.w)
				way[e.v] = (way[e.v] + way[u]) % MOD;
		}
	}
	return {d, way};
}

int main() {
	int N, M; cin >> N >> M;
	vector<int> a(M), b(M), c(M);
	rep(i, M) scanf("%d%d%d", &a[i], &b[i], &c[i]), a[i]--, b[i]--;
	vector<vector<edge>> G(N), _G(N);
	rep(i, M) G[a[i]].pb({b[i], c[i]}), _G[b[i]].pb({a[i], c[i]});
	auto z = dijkstra(N, G, 0), _z = dijkstra(N, _G, 1);
	vector<ll> d = z.first, _d = _z.first;
	vector<int> way = z.second, _way = _z.second;
	ll D = d[1]; int WAY = way[1];
	rep(i, M) {
		int u = a[i], v = b[i];
		if (d[u] + c[i] + _d[v] == D && (ll)way[u] * _way[v] % MOD == WAY)
			printf("SAD\n");
		else if (d[v] + c[i] + _d[u] < D)
			printf("HAPPY\n");
		else
			printf("SOSO\n");
	}
}

