using namespace std;
const long long inf = 1e17;
const long long mod = 924844033;
vector<long long> NG[2005], G[2005];
long long dp[2005][2005][2];
long long used[2005];
long long C[2005];
long long kj[2010], kji[2010];
long long modpow(long long a, long long x) {
  long long res = 1;
  while (x) {
    if (x & 1) res = res * a % mod;
    a = a * a % mod;
    x >>= 1;
  }
  return res;
}
void setkj(long long n) {
  kj[0] = 1;
  for (long long i = 0; i < n; i++) kj[i + 1] = kj[i] * (i + 1) % mod;
  for (long long i = 0; i < n + 1; i++) kji[i] = modpow(kj[i], mod - 2);
}
signed main() {
  long long n, k;
  cin >> n >> k;
  setkj(n + 1);
  for (long long i = 0; i < n - k; i++) {
    NG[i + k].push_back(i);
    NG[n - 1 - i - k].push_back(n - i - 1);
    C[i]++;
    C[n - i - 1]++;
  }
  for (long long i = 0; i < n; i++) {
    sort(NG[i].begin(), NG[i].end());
    if (NG[i].size() > 1) {
      G[NG[i][0]].push_back(NG[i][1]);
      G[NG[i][1]].push_back(NG[i][0]);
    }
  }
  dp[0][0][0] = 1;
  long long cnt = 0;
  long long now = 0, fs = 0;
  while (cnt != n) {
    if (fs) {
      for (long long j = 0; j < n; j++) {
        dp[cnt + 1][j][0] += dp[cnt][j][0] + dp[cnt][j][1];
        dp[cnt + 1][j + 1][1] +=
            C[now] * dp[cnt][j][0] + (C[now] - 1) * dp[cnt][j][1];
        for (long long p = 0; p < 2; p++)
          for (long long q = 0; q < 2; q++) dp[cnt + 1][j + p][q] %= mod;
      }
    } else {
      for (long long j = 0; j < n; j++) {
        dp[cnt + 1][j][0] += dp[cnt][j][0] + dp[cnt][j][1];
        dp[cnt + 1][j + 1][1] += C[now] * (dp[cnt][j][0] + dp[cnt][j][1]);
        for (long long p = 0; p < 2; p++)
          for (long long q = 0; q < 2; q++) dp[cnt + 1][j + p][q] %= mod;
      }
    }
    used[now]++;
    cnt++;
    long long nxt = -1;
    for (long long e : G[now]) {
      if (!used[e]) nxt = e;
    }
    if (nxt == -1) {
      for (long long i = 0; i < n; i++) {
        if (!used[i]) {
          now = i;
          break;
        }
      }
      fs = 0;
    } else {
      now = nxt;
      fs = 1;
    }
  }
  long long ans = 0;
  for (long long i = n; i >= 0; i--) {
    long long X = dp[n][i][0] + dp[n][i][1];
    if (i & 1)
      ans -= X * kj[n - i] % mod;
    else
      ans += X * kj[n - i] % mod;
    ans = (ans + mod) % mod;
  }
  cout << ans << endl;
}

