long long mod(long long i) { return i % 1000000007; }
void swap(long long& a, long long& b) {
  long long t;
  t = a;
  a = b;
  b = t;
  return;
}
long long modinv(long long a, long long m) {
  long long b = m, u = 1, v = 0;
  while (b) {
    long long t = a / b;
    a = a - t * b;
    swap(a, b);
    u = u - t * v;
    swap(u, v);
  }
  u = u % m;
  if (u < 0) {
    u = u + m;
  }
  return u;
}
long long division(long long a, long long b, long long m) {
  return mod(mod(a) * modinv(b, m));
}
long long numperm_mod(long long x, long long y) {
  long long res = 1;
  for (long long i = x; i >= y; i--) {
    res = mod(res * mod(i));
  }
  return mod(res);
}
long long numperm(long long x, long long y) {
  long long res = 1;
  for (long long i = x; i >= y; i--) {
    res *= i;
  }
  return res;
}
long long pow_mod(long long x, long long y) {
  x = mod(x);
  if (y == 1) {
    return mod(x);
  }
  long long res = mod(pow_mod(mod(x * x), y / 2));
  if (y % 2 == 0) {
    return res;
  } else {
    return mod(x * res);
  }
}
long long pow(long long x, long long y) {
  if (y == 1) {
    return x;
  }
  if (y % 2 == 0) {
    return pow(x * x, y / 2);
  } else {
    return x * pow(x * x, y / 2);
  }
}
long long gcd(long long i, long long j) {
  if (j != 0)
    return gcd(j, i % j);
  else
    return i;
}
pair<long long, long long> extgcd(long long a, long long b, long long c) {
  pair<long long, long long> ans;
  if (c % gcd(a, b) != 0) {
    return pair<long long, long long>(-1, -1);
  } else {
    if (b != 0) {
      pair<long long, long long> next = extgcd(b, a % b, c);
      ans.first = next.second;
      ans.second = next.first - (a / b) * next.second;
    } else {
      ans = pair<long long, long long>(c / a, 0);
    }
  }
  return ans;
}
vector<long long> Eratosthenes(long long n) {
  bool isPrime[n];
  fill(isPrime, isPrime + n, true);
  isPrime[0] = isPrime[1] = false;
  for (long long i = 2; i < sqrt(n) + 1; i++) {
    if (isPrime[i]) {
      for (long long j = 2 * i; j <= n; j += i) {
        isPrime[j] = false;
      }
    }
  }
  vector<long long> P;
  for (long long i = 2; i < n + 1; i++) {
    if (isPrime[i]) {
      P.push_back(i);
    }
  }
  return P;
