    return;
  }
  void setUDE(long long i, long long j, long long cos) {
    edge ei, ej;
    ei.to = j;
    ej.to = i;
    ei.cost = ej.cost = cos;
    vertices[i].edges.push_back(ei);
    vertices[j].edges.push_back(ej);
    return;
  }
  void setUDE(long long i, long long j, double dcos) {
    edge ei, ej;
    ei.to = j;
    ej.to = i;
    ei.dcost = ej.dcost = dcos;
    vertices[i].edges.push_back(ei);
    vertices[j].edges.push_back(ej);
    return;
  }
  void setKey(long long i, long long newKey) { vertices[i].key = newKey; }
  void setKey(long long i, double newKey) { vertices[i].key = newKey; }
  edge getEdge(long long i, long long j) {
    for (long long a = 0; a < vertices[i].edges.size(); a++) {
      if (vertices[i].edges[a].to == j) {
        return vertices[i].edges[a];
      }
    }
    return (edge){j, LLONG_MAX / 2, DBL_MAX / 2};
  }
  void bellman_ford(long long s, long long b[]) {
    fill(b, b + V, LLONG_MAX / 2);
    b[s] = 0;
    while (true) {
      bool update = false;
      for (long long i = 0; i < V; i++) {
        for (long long j = 0; j < vertices[i].edges.size(); j++) {
          edge e = vertices[i].edges[j];
          if (b[e.to] > b[i] + e.cost) {
            b[e.to] = b[i] + e.cost;
            update = true;
          }
        }
      }
      if (!update) break;
    }
    return;
  }
  void dijkstra(long long s, long long d[]) {
    priority_queue<pair<long long, long long>,
                   vector<pair<long long, long long>>,
                   greater<pair<long long, long long>>>
        que;
    fill(d, d + V, LLONG_MAX / 2);
    d[s] = 0;
    que.push(pair<long long, long long>(0, s));
    while (!que.empty()) {
      pair<long long, long long> p = que.top();
      que.pop();
      long long v = p.second;
      if (d[v] < p.first) continue;
      for (long long i = 0; i < vertices[v].edges.size(); i++) {
        edge e = vertices[v].edges[i];
        if (d[e.to] > d[v] + e.cost) {
          d[e.to] = d[v] + e.cost;
          que.push(pair<long long, long long>(d[e.to], e.to));
        }
      }
    }
    return;
  }
  void warshall_floyd(long long** w) {
    for (long long i = 0; i < V; i++) {
      for (long long j = 0; j < V; j++) {
        w[i][j] = LLONG_MAX / 2;
      }
    }
    for (long long i = 0; i < V; i++) {
      for (long long j = 0; j < vertices[i].edges.size(); j++) {
        w[i][vertices[i].edges[j].to] = vertices[i].edges[j].cost;
      }
    }
    for (long long i = 0; i < V; i++) {
      w[i][i] = 0;
    }
    for (long long i = 0; i < V; i++) {
      for (long long j = 0; j < V; j++) {
        for (long long k = 0; k < V; k++) {
          w[i][j] = min(w[i][j], w[i][k] + w[k][j]);
        }
      }
    }
  }
};
class UF {
 public:
  long long N;
  long long* par;
  long long* rank;
  UF(long long n) {
    N = n;
    par = new long long[N];
    rank = new long long[N];
    for (long long i = 0; i < N; i++) {
      par[i] = i;
      rank[i] = i;
    }
    return;
  }
  long long root(long long x) {
    if (x == par[x])
      return x;
    else
      return par[x] = root(par[x]);
  }
  bool same(long long x, long long y) { return (root(x) == root(y)); }
  void Union(long long x, long long y) {
    long long rtx = root(x);
    long long rty = root(y);
    if (rank[rtx] < rank[rty]) {
      par[rtx] = rty;
    } else {
      par[rty] = rtx;
      if (rank[rtx] == rank[rty]) {
        rank[rtx]++;
      }
    }
  }
};
