void CreatTree(int t, int x, int y) {
  a[t].x = x;
  a[t].y = y;
  a[t].flag = 0;
  if (x == y) {
    a[t].sum = b[x];
    return;
  }
  int temp = t * 2;
  int mid = (a[t].x + a[t].y) / 2;
  CreatTree(temp, x, mid);
  CreatTree(temp + 1, mid + 1, y);
  return;
}
void InsertTree(int t, int x, int y, int k, int tt) {
  if (a[t].x == x && a[t].y == y) {
    if (tt == 2)
      a[t].flag += k;
    else if (tt == 1) {
      a[t].sum = k;
      a[t].flag = 0;
    }
    return;
  }
  int temp = t * 2;
  int mid = (a[t].x + a[t].y) / 2;
  if (a[t].flag) {
    a[temp].flag += a[t].flag;
    a[temp + 1].flag += a[t].flag;
    a[t].flag = 0;
  }
  if (x <= mid)
    InsertTree(temp, x, y, k, tt);
  else
    InsertTree(temp + 1, x, y, k, tt);
  return;
}
long long FindTree(int t, int x) {
  if (a[t].x == a[t].y) {
    a[t].sum += a[t].flag;
    a[t].flag = 0;
    return a[t].sum;
  }
  int temp = t * 2;
  int mid = (a[t].x + a[t].y) / 2;
  if (a[t].flag) {
    a[temp].flag += a[t].flag;
    a[temp + 1].flag += a[t].flag;
    a[t].flag = 0;
  }
  if (x <= mid)
    return FindTree(temp, x);
  else
    return FindTree(temp + 1, x);
}
