  int c = -1;
  long long d = -1;
};
vector<vert> info;
struct layer {
  std::vector<pair<int, long long>> srt;
  std::vector<int> x;
  std::vector<long long> S;
  int depth = 0;
} L[N];
bool rem[N];
int sz[N];
vector<pair<int, int>> E[N];
int centroid(int x, int all_sz, int p = -1) {
  sz[x] = 1;
  int glob_res = -1;
  for (auto pr : E[x]) {
    int y = pr.first;
    if (rem[y] || p == y) continue;
    int res = centroid(y, all_sz, x);
    if (res != -1) {
      glob_res = res;
    }
    sz[x] += sz[y];
  }
  if (glob_res != -1) return glob_res;
  bool is_centroid = all_sz - sz[x] <= all_sz / 2;
  for (auto pr : E[x]) {
    int y = pr.first;
    if (rem[y] || p == y) continue;
    is_centroid &= sz[y] <= all_sz / 2;
  }
  if (is_centroid) return x;
  return -1;
}
int A[N], IA[N];
void DFS(int x, int depth, int c, int p = -1, long long d = 0) {
  info[x * LGN + depth].c = c;
  info[x * LGN + depth].d = d;
  sz[x] = 1;
  L[c].srt.emplace_back(IA[x],
                        d - ((depth > 0) ? info[x * LGN + depth - 1].d : 0));
  for (auto pr : E[x]) {
    int y = pr.first;
    int w = pr.second;
    if (y == p || rem[y]) continue;
    DFS(y, depth, c, x, d + w);
    sz[x] += sz[y];
  }
}
void build_layer(int x, int all_sz, int depth) {
  assert(!rem[x]);
  int c = centroid(x, all_sz);
  assert(c != -1);
  x = c;
  L[x].depth = depth;
  for (auto pr : E[x]) {
    int y = pr.first;
    int w = pr.second;
    if (rem[y]) continue;
    DFS(y, depth, x, x, w);
  }
  L[x].srt.emplace_back(IA[x],
                        0 - ((depth > 0) ? info[x * LGN + depth - 1].d : 0));
  info[x * LGN + depth].c = x;
  info[x * LGN + depth].d = 0;
  rem[x] = true;
  for (auto pr : E[x]) {
    int y = pr.first;
    if (!rem[y]) {
      build_layer(y, sz[y], depth + 1);
    }
  }
}
long long query(int v, int l, int r) {
  assert(1 <= l && l <= r && r <= n);
  assert(1 <= v && v <= n);
  long long sum = 0;
  long long c1 = 0, c2 = 0;
  for (int depth = 0;; depth++) {
    int c = info[v * LGN + depth].c;
    long long d = info[v * LGN + depth].d;
    if (c == -1) break;
    long long sumd = 0;
    int i1 = lower_bound(L[c].x.begin(), L[c].x.end(), l) - L[c].x.begin() - 1;
    int i2 = upper_bound(L[c].x.begin(), L[c].x.end(), r) - L[c].x.begin() - 1;
    if (i1 >= 0) {
      sumd -= L[c].S[i1];
    }
    if (i2 >= 0) {
      sumd += L[c].S[i2];
    }
    sum += sumd + (d + c2) * (i2 - i1);
    c1 = -1, c2 = -d;
  }
  return sum;
}
void change(int x1, int x2, int v1, int v2) {
  assert(v1 != v2);
  assert(x1 + 1 == x2);
  int depth;
  for (depth = 0;; depth++) {
    if (info[v1 * LGN + depth].c != info[v2 * LGN + depth].c) break;
    int c = info[v1 * LGN + depth].c;
    int i1 = lower_bound(L[c].x.begin(), L[c].x.end(), x1) - L[c].x.begin();
    assert(i1 + 1 <= L[c].S.size() && L[c].x[i1] == x1);
    int i2 = i1 + 1;
    assert(i2 + 1 <= L[c].S.size() && L[c].x[i2] == x2);
    auto pi = i1 - 1;
    long long ps = 0;
    if (pi >= 0) {
      ps = L[c].S[pi];
    }
    long long s1 = L[c].S[i1] - ps;
    long long s2 = L[c].S[i2] - L[c].S[i1];
    L[c].S[i1] = ps + s2;
  }
  for (int depth1 = depth;; depth1++) {
    int c = info[v1 * LGN + depth1].c;
    if (c == -1) break;
    int i1 = lower_bound(L[c].x.begin(), L[c].x.end(), x1) - L[c].x.begin();
    assert(i1 < (int)L[c].x.size() && L[c].x[i1] == x1);
    L[c].x[i1]++;
  }
  for (int depth2 = depth;; depth2++) {
    int c = info[v2 * LGN + depth2].c;
    if (c == -1) break;
    int i2 = lower_bound(L[c].x.begin(), L[c].x.end(), x2) - L[c].x.begin();
    assert(i2 < (int)L[c].x.size() && L[c].x[i2] == x2);
    L[c].x[i2]--;
  }
  A[x1] = v2, A[x2] = v1, IA[v1] = x2, IA[v2] = x1;
}
const bool bitch_input = true;
int main() {
  info.resize(N * LGN);
  int q;
  scanf("%d %d", &n, &q);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &A[i]);
    IA[A[i]] = i;
  }
  for (int i = 0; i < n - 1; i++) {
    int u, v, w;
    scanf("%d %d %d", &u, &v, &w);
    E[u].emplace_back(v, w);
    E[v].emplace_back(u, w);
  }
  build_layer(1, n, 0);
  for (int i = 1; i <= n; i++) assert(rem[i]);
  long long pans = 0;
  const int BIT = (1 << 30) - 1;
  for (int i = 1; i <= n; i++) {
    sort(L[i].srt.begin(), L[i].srt.end());
    long long s = 0;
    int cnt = 0;
    for (int j = 0; j < (int)L[i].srt.size(); j++) {
      L[i].x.emplace_back(L[i].srt[j].first);
      s += L[i].srt[j].second;
      cnt++;
      L[i].S.emplace_back(s);
    }
    L[i].srt.clear();
  }
  for (int i = 0; i < q; i++) {
    int t;
    scanf("%d", &t);
    if (t == 1) {
      int a, b, c;
      scanf("%d %d %d", &a, &b, &c);
      int l, r, v;
      if (bitch_input) {
        l = (pans & BIT) ^ a;
        r = (pans & BIT) ^ b;
        v = (pans & BIT) ^ c;
      } else {
        l = a, r = b, v = c;
      }
      long long ans = query(v, l, r);
      printf("%lld\n", ans);
      pans = ans;
    } else {
      int a;
      scanf("%d", &a);
      int x;
      if (bitch_input) {
        x = (pans & BIT) ^ a;
      } else {
        x = a;
      }
      change(x, x + 1, A[x], A[x + 1]);
    }
  }
}

#include <bits/stdc++.h>
using namespace std;
int seg_tree_f[400000 * 4 + 9];
int lazy_f[400000 * 4 + 9];
void init_tree_f(int node, int beg, int end) {
  if (beg == end) {
    seg_tree_f[node] = 0;
    lazy_f[node] = 0;
    return;
  }
  int mid = (beg + end) >> 1;
  init_tree_f((node << 1), beg, mid);
  init_tree_f((node << 1) | 1, mid + 1, end);
  seg_tree_f[node] = 0;
  lazy_f[node] = 0;
}
inline void split_node_f(int node) {
  if (lazy_f[node] == 0) return;
  seg_tree_f[(node << 1)] += lazy_f[node];
  lazy_f[(node << 1)] += lazy_f[node];
  seg_tree_f[(node << 1) | 1] += lazy_f[node];
  lazy_f[(node << 1) | 1] += lazy_f[node];
  lazy_f[node] = 0;
}
inline void merge_node_f(int node) {
  seg_tree_f[node] = min(seg_tree_f[(node << 1)], seg_tree_f[(node << 1) | 1]);
}
void update_f(int node, int beg, int end, int i, int j, int value) {
  if (beg > j || end < i) return;
  if (beg >= i && end <= j) {
    seg_tree_f[node] += value;
    lazy_f[node] += value;
    return;
  }
  split_node_f(node);
  int mid = (beg + end) >> 1;
  update_f((node << 1), beg, mid, i, j, value);
  update_f((node << 1) | 1, mid + 1, end, i, j, value);
  merge_node_f(node);
}
int query_f_leftmost(int node, int beg, int end, int i, int j, int target) {
  if (i > end || j < beg) return (1 << 30);
  if (seg_tree_f[node] > target) return (1 << 30);
  if (beg == end) return beg;
  split_node_f(node);
  int mid = (beg + end) >> 1;
  int ind = query_f_leftmost((node << 1), beg, mid, i, j, target);
  if (ind != (1 << 30)) return ind;
  return query_f_leftmost(((node << 1) | 1), mid + 1, end, i, j, target);
}
int query_f_rightmost(int node, int beg, int end, int i, int j, int target) {
  if (i > end || j < beg) return (-(1 << 30));
  if (seg_tree_f[node] > target) return (-(1 << 30));
  if (beg == end) return beg;
  split_node_f(node);
  int mid = (beg + end) >> 1;
  int ind = query_f_rightmost(((node << 1) | 1), mid + 1, end, i, j, target);
  if (ind != (-(1 << 30))) return ind;
  return query_f_rightmost((node << 1), beg, mid, i, j, target);
}
int query_f(int node, int beg, int end, int i, int j) {
  if (i > end || j < beg) return (1LL << 30);
  if (beg >= i && end <= j) return seg_tree_f[node];
  split_node_f(node);
  int mid = (beg + end) >> 1;
  int leftnode = query_f((node << 1), beg, mid, i, j);
  int rightnode = query_f(((node << 1) | 1), mid + 1, end, i, j);
  return min(leftnode, rightnode);
}
int seg_tree[400000 * 4 + 9];
int lazy[400000 * 4 + 9];
void init_tree(int node, int beg, int end) {
  if (beg == end) {
    seg_tree[node] = 0;
    lazy[node] = 0;
    return;
  }
  int mid = (beg + end) >> 1;
  init_tree((node << 1), beg, mid);
  init_tree((node << 1) | 1, mid + 1, end);
  seg_tree[node] = 0;
  lazy[node] = 0;
}
void split_node(int node) {
  if (lazy[node] == 0) return;
  seg_tree[(node << 1)] += lazy[node];
  lazy[(node << 1)] += lazy[node];
  seg_tree[(node << 1) | 1] += lazy[node];
  lazy[(node << 1) | 1] += lazy[node];
  lazy[node] = 0;
}
void merge_node(int node) {
  seg_tree[node] = max(seg_tree[(node << 1)], seg_tree[(node << 1) | 1]);
}
void update(int node, int beg, int end, int i, int j, int value) {
  if (beg > j || end < i) return;
  if (beg >= i && end <= j) {
    seg_tree[node] += value;
    lazy[node] += value;
    return;
  }
  split_node(node);
  int mid = (beg + end) >> 1;
  update((node << 1), beg, mid, i, j, value);
  update((node << 1) | 1, mid + 1, end, i, j, value);
  merge_node(node);
}
int query_leftmost(int node, int beg, int end, int i, int j, int target) {
  if (i > end || j < beg) return (1 << 30);
  if (seg_tree[node] < target) return (1 << 30);
  if (beg == end) return beg;
  split_node(node);
  int mid = (beg + end) >> 1;
  int ind = query_leftmost((node << 1), beg, mid, i, j, target);
  if (ind != (1 << 30)) return ind;
  return query_leftmost(((node << 1) | 1), mid + 1, end, i, j, target);
}
int query_rightmost(int node, int beg, int end, int i, int j, int target) {
  if (i > end || j < beg) return (-(1 << 30));
  if (seg_tree[node] < target) return (-(1 << 30));
  if (beg == end) return beg;
  split_node(node);
  int mid = (beg + end) >> 1;
  int ind = query_rightmost(((node << 1) | 1), mid + 1, end, i, j, target);
  if (ind != (-(1 << 30))) return ind;
  return query_rightmost((node << 1), beg, mid, i, j, target);
}
int query(int node, int beg, int end, int i, int j) {
  if (i > end || j < beg) return (-(1LL << 30));
  if (beg >= i && end <= j) return seg_tree[node];
  split_node(node);
  int mid = (beg + end) >> 1;
  int leftnode = query((node << 1), beg, mid, i, j);
  int rightnode = query(((node << 1) | 1), mid + 1, end, i, j);
  return max(leftnode, rightnode);
}
int MAP[400000 + 9];
int ar[400000 + 9];
int ANC[400000 + 9];
void GO(int l, int r, int n, int carry) {
  if (l > r) return;
  int m = MAP[query_f(1, 1, n, l, r)];
  ANC[m] = carry;
  GO(l, m - 1, n, carry + 1);
  GO(m + 1, r, n, carry + 1);
}
int main() {
  int i, j, k, l, cas, ne, test, n, m, x, y, temp, val, now, q, w, e, root,
      flag, ii, o, p, ans, r;
  cin >> n;
  for (i = 1; i <= n; i++) scanf("%d", &ar[i]);
  for (i = 1; i <= n; i++) MAP[ar[i]] = i;
  init_tree_f(1, 1, n);
  for (i = 1; i <= n; i++) update_f(1, 1, n, i, i, ar[i]);
  GO(1, n, n, 0);
  init_tree_f(1, 1, 2 * n);
  for (i = 1; i <= n; i++) ar[i + n] = ar[i];
  for (i = 1; i <= 2 * n; i++) update_f(1, 1, 2 * n, i, i, ar[i]);
  init_tree(1, 1, 2 * n);
  for (i = 1; i <= n; i++) ANC[i + n] = ANC[i];
  for (i = 1; i <= 2 * n; i++) update(1, 1, 2 * n, i, i, ANC[i]);
  ans = seg_tree[1];
  val = 0;
  for (i = 1; i < n; i++) {
    l = query_f_leftmost(1, 1, 2 * n, i + 1, n + i - 1, ar[i]);
    if (l != (1 << 30)) update(1, 1, 2 * n, i + 1, l - 1, -1);
    r = query_f_rightmost(1, 1, 2 * n, i + 1, n + i - 1, ar[i]);
    if (r != (-(1 << 30))) update(1, 1, 2 * n, r + 1, n + i - 1, 1);
    update(1, 1, 2 * n, n + i, n + i, -(query(1, 1, 2 * n, n + i, n + i)));
    if (r != (-(1 << 30)))
      update(1, 1, 2 * n, n + i, n + i, (query(1, 1, 2 * n, r, r) + 1));
    temp = query(1, 1, 2 * n, i + 1, i + n);
    if (temp < ans) {
      ans = temp;
      val = i;
    }
  }
  cout << ans + 1 << " " << val << endl;
}

