#include <bits/stdc++.h>
using namespace std;
const long long mod = 1e9 + 7;
class segtree {
 public:
  struct node {
    long long val = 0;
    long long put = 0;
    void apply(long long l, long long r, long long v) {
      val |= v;
      put |= v;
    }
  };
  node unite(const node &a, const node &b) const {
    node res;
    res.val = a.val | b.val;
    return res;
  }
  inline void push(long long x, long long l, long long r) {
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    if (tree[x].put != 0) {
      tree[x + 1].apply(l, y, tree[x].put);
      tree[z].apply(y + 1, r, tree[x].put);
      tree[x].put = 0;
    }
  }
  inline void pull(long long x, long long z) {
    tree[x] = unite(tree[x + 1], tree[z]);
  }
  long long n;
  vector<node> tree;
  void build(long long x, long long l, long long r) {
    if (l == r) {
      return;
    }
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    build(x + 1, l, y);
    build(z, y + 1, r);
    pull(x, z);
  }
  template <typename M>
  void build(long long x, long long l, long long r, const vector<M> &v) {
    if (l == r) {
      tree[x].apply(l, r, v[l]);
      return;
    }
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    build(x + 1, l, y, v);
    build(z, y + 1, r, v);
    pull(x, z);
  }
  node get(long long x, long long l, long long r, long long ll, long long rr) {
    if (ll <= l && r <= rr) {
      return tree[x];
    }
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    push(x, l, r);
    node res{};
    if (rr <= y) {
      res = get(x + 1, l, y, ll, rr);
    } else {
      if (ll > y) {
        res = get(z, y + 1, r, ll, rr);
      } else {
        res = unite(get(x + 1, l, y, ll, rr), get(z, y + 1, r, ll, rr));
      }
    }
    pull(x, z);
    return res;
  }
  template <typename... M>
  void modify(long long x, long long l, long long r, long long ll, long long rr,
              const M &...v) {
    if (ll <= l && r <= rr) {
      tree[x].apply(l, r, v...);
      return;
    }
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    push(x, l, r);
    if (ll <= y) {
      modify(x + 1, l, y, ll, rr, v...);
    }
    if (rr > y) {
      modify(z, y + 1, r, ll, rr, v...);
    }
    pull(x, z);
  }
  long long find_first_knowingly(long long x, long long l, long long r,
                                 const function<bool(const node &)> &f) {
    if (l == r) {
      return l;
    }
    push(x, l, r);
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    long long res;
    if (f(tree[x + 1])) {
      res = find_first_knowingly(x + 1, l, y, f);
    } else {
      res = find_first_knowingly(z, y + 1, r, f);
    }
    pull(x, z);
    return res;
  }
  long long find_first(long long x, long long l, long long r, long long ll,
                       long long rr, const function<bool(const node &)> &f) {
    if (ll <= l && r <= rr) {
      if (!f(tree[x])) {
        return -1;
      }
      return find_first_knowingly(x, l, r, f);
    }
    push(x, l, r);
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    long long res = -1;
    if (ll <= y) {
      res = find_first(x + 1, l, y, ll, rr, f);
    }
    if (rr > y && res == -1) {
      res = find_first(z, y + 1, r, ll, rr, f);
    }
    pull(x, z);
    return res;
  }
  long long find_last_knowingly(long long x, long long l, long long r,
                                const function<bool(const node &)> &f) {
    if (l == r) {
      return l;
    }
    push(x, l, r);
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    long long res;
    if (f(tree[z])) {
      res = find_last_knowingly(z, y + 1, r, f);
    } else {
      res = find_last_knowingly(x + 1, l, y, f);
    }
    pull(x, z);
    return res;
  }
  long long find_last(long long x, long long l, long long r, long long ll,
                      long long rr, const function<bool(const node &)> &f) {
    if (ll <= l && r <= rr) {
      if (!f(tree[x])) {
        return -1;
      }
      return find_last_knowingly(x, l, r, f);
    }
    push(x, l, r);
    long long y = (l + r) >> 1;
    long long z = x + ((y - l + 1) << 1);
    long long res = -1;
    if (rr > y) {
      res = find_last(z, y + 1, r, ll, rr, f);
    }
    if (ll <= y && res == -1) {
      res = find_last(x + 1, l, y, ll, rr, f);
    }
    pull(x, z);
    return res;
  }
  segtree(long long _n) : n(_n) {
    assert(n > 0);
    tree.resize(2 * n - 1);
    build(0, 0, n - 1);
  }
  template <typename M>
  segtree(const vector<M> &v) {
    n = v.size();
    assert(n > 0);
    tree.resize(2 * n - 1);
    build(0, 0, n - 1, v);
  }
  node get(long long ll, long long rr) {
    assert(0 <= ll && ll <= rr && rr <= n - 1);
    return get(0, 0, n - 1, ll, rr);
  }
  node get(long long p) {
    assert(0 <= p && p <= n - 1);
    return get(0, 0, n - 1, p, p);
  }
  template <typename... M>
  void modify(long long ll, long long rr, const M &...v) {
    assert(0 <= ll && ll <= rr && rr <= n - 1);
    modify(0, 0, n - 1, ll, rr, v...);
  }
  long long find_first(long long ll, long long rr,
                       const function<bool(const node &)> &f) {
    assert(0 <= ll && ll <= rr && rr <= n - 1);
    return find_first(0, 0, n - 1, ll, rr, f);
  }
  long long find_last(long long ll, long long rr,
                      const function<bool(const node &)> &f) {
    assert(0 <= ll && ll <= rr && rr <= n - 1);
    return find_last(0, 0, n - 1, ll, rr, f);
  }
};
void solve() {
  long long k, q;
  cin >> k >> q;
  vector<long long> l(q), r(q), v(q);
  for (long long i = 0; i < q; i++) cin >> l[i] >> r[i] >> v[i];
  segtree msb(1 << k), lsb(1 << k);
  for (long long i = 0; i < q; i++) {
    long long from = l[i] >> k;
    long long to = r[i] >> k;
    msb.modify(from, to, v[i]);
    {
      if (r[i] - l[i] + 1 >= (1 << k)) {
        lsb.modify(0, (1 << k) - 1, v[i]);
      } else {
        long long from = l[i] & ((1 << k) - 1);
        long long to = r[i] & ((1 << k) - 1);
        if (from <= to) {
          lsb.modify(from, to, v[i]);
        } else {
          lsb.modify(from, (1 << k) - 1, v[i]);
          lsb.modify(0, to, v[i]);
        }
      }
    }
  }
  for (long long i = 0; i < q; i++) {
    long long x = l[i];
    long long y = r[i];
    while (x <= y) {
      if ((x & ((1 << k) - 1)) == 0 and y - x + 1 >= (1 << k)) {
        long long f = (y - x + 1) >> k;
        long long a = msb.get(x >> k, (x >> k) + f - 1).val;
        long long b = lsb.get(0, (1 << k) - 1).val;
        if ((a & b) != v[i]) {
          cout << "impossible\n";
          return;
        }
        x += f << k;
        continue;
      }
      long long z = min(y, x | ((1 << k) - 1));
      long long a = msb.get(x >> k, x >> k).val;
      long long b = lsb.get(x & ((1 << k) - 1), z & ((1 << k) - 1)).val;
      if ((a & b) != v[i]) {
        cout << "impossible\n";
        return;
      }
      x = z + 1;
    }
  }
  cout << "possible\n";
  for (long long i = 0; i < (1 << k); i++) cout << lsb.get(i, i).val << '\n';
  for (long long i = 0; i < (1 << k); i++) cout << msb.get(i, i).val << '\n';
}
signed main() {
  ios_base::sync_with_stdio(0), cin.tie(nullptr);
  long long qq = 1;
  while (qq--) solve();
  return 0;
}

