  for (int i = 1; i <= n; i++) {
    int u = i;
    for (int j = 1; j <= B; j++) u = nxt[u];
    np[i] = u;
  }
  while (q--) {
    int opt, x, y;
    cin >> opt >> x >> y;
    if (opt == 1) {
      swap(lst[nxt[x]], lst[nxt[y]]);
      swap(nxt[x], nxt[y]);
      update(x), update(y);
    } else
