const static long long INF = 1LL << 55LL;
#define int long long
struct edge {
  int to, cost;
  edge(int to, int cost):to(to), cost(cost){};
};
struct state {
  int now;
  long long cost;
  int bitsIn, bitsOut;
  bool operator<(const state& s) const {
    return(cost > s.cost);
  }
  state(int n, long long c, int i, int o):now(n), cost(c), bitsIn(i), bitsOut(o){};
};

int n, m, k, p;
vector< edge > Graph[1000];
long long v[1000][1 << 6][1 << 6];
int Idx[1000];

long long Dijkstra()
{
  priority_queue< state > Que;
  fill_n((long long *)v, 1000 * (1 << 6) * (1 << 6), INF);
  Que.push(state(p, 0, 0, 0));
  v[p][0][0] = 0;

  while(!Que.empty()) {
    const state p = Que.top(); Que.pop();
    if(p.cost > v[p.now][p.bitsIn][p.bitsOut]) continue;
    if(p.bitsOut == (1 << k) - 1) return(p.cost);
    for(int i = 0; i < Graph[p.now].size(); i++) {
      const edge& e = Graph[p.now][i];
      int nextIn = p.bitsIn, nextOut = p.bitsOut;
      if(Idx[e.to] > 0) {
        nextIn |= (1 << (Idx[e.to] - 1));
      } else if(Idx[e.to] < 0) {
        nextOut |= ((nextIn >> (-Idx[e.to] - 1)) & 1) << (-Idx[e.to] - 1);
      }
      if(p.cost + e.cost >= v[e.to][nextIn][nextOut]) continue;
      v[e.to][nextIn][nextOut] = p.cost + e.cost;
      Que.push(state(e.to, p.cost + e.cost, nextIn, nextOut));
    }
  }
  return(-1);
}


