                                   (n + 1 - 2 * (n + 1 - r) - j) +
                               3 * (n + 1 - i) * (n + 1 - i) +
                               (n + 1 - 2 * (n + 1 - r) + i) *
                                   (n + 1 - 2 * (n + 1 - r) + i) >=
                           t)
        r--;
      if (l > r) break;
      ans = ans + (r - l + 1) + (i == j ? 0 : (r - l + 1));
    }
  }
  cout << ans * 3;
  return 0;
}

