struct segTree {
  int value[2000010];
  int lazy[2000010];
  void setValue(int ind, int val, int l = 0, int r = 500000, int v = 1) {
    if (l == r)
      value[v] = val;
    else {
      int h = (l + r) / 2;
      if (ind <= h)
        setValue(ind, val, l, h, 2 * v);
      else
        setValue(ind, val, h + 1, r, 2 * v + 1);
      value[v] =
          value[2 * v] > value[2 * v + 1] ? value[2 * v] : value[2 * v + 1];
    }
  }

  int getValue(int L, int R, int l = 0, int r = 500000, int v = 1) {
    if (L <= l && r <= R)
      return value[v];
    else if (r < L)
      return 0;
    else if (R < l)
      return 0;
    else {
      int h = (l + r) / 2;
      int s1 = getValue(L, R, l, h, 2 * v);
      int s2 = getValue(L, R, h + 1, r, 2 * v + 1);
      return s1 > s2 ? s1 : s2;
    }
  }
} T1, T2;
