        T2.setValue(*it, T2.getValue(*it, *it) + 1);
      }
      while (S.begin() != S.end() && ((*S.begin()) <= x[i])) S.erase(S.begin());
      T2.setValue(x[i], s1 > s2 ? s1 : s2);
