public class CF276_B {

	/**
	 * @param args
	 */
	public static void main(String[] args) {

		MyScanner in = new MyScanner();

		int N = in.nextInt();
		boolean[] seen = new boolean[1000005];
		ArrayList<Integer> valsList = new ArrayList<Integer>();
		for (int i = 0; i < N; i++) {
			int num = in.nextInt();
			if (seen[num]) {
				continue;
			}
			seen[num] = true;
			valsList.add(num);
		}

		if(valsList.size() == 1){ 
			System.out.println(0);
			return;
		}

		Collections.sort(valsList);
		int[] vals = new int[valsList.size()];
		for (int i = 0; i < vals.length; i++) {
			vals[i] = valsList.get(i);
		}

		N = valsList.size();
		int max = vals[N - 1];

		int bestAns = 0;
		for (int i = N - 1; i >= 0; i--) {

			int modNum = vals[i];
			if (modNum <= bestAns) {
				break;
			}

			for (int testNum = modNum; testNum <= (max + modNum); testNum += modNum) {

				// Find the largest number less than testNum
				int lowInd = i;
				int highInd = N - 1;
				while ((highInd - lowInd) > 1) {
					int mid = (lowInd + highInd) / 2;
					if (vals[mid] < testNum) {
						lowInd = mid;
					} else {
						highInd = mid;
					}
				}

				int resInd = highInd;
				if (vals[resInd] >= testNum && resInd > 0) {
					resInd--;
				}

				int res = vals[resInd];
				if (res > modNum) {
					bestAns = Math.max(bestAns, res % modNum);
				}
			}

		}
		System.out.println(bestAns);
	}

