};

struct state{
  int n,bit,c;
  bool operator < (const state &s) const{
    return c > s.c;
  }
};


int n,m,m2,p;
vector<edge> G[N];
data v[M];
int d[N][1<<(M+M)];
int vs[N];
int vt[N];

void solve(){
  priority_queue<state> Q;
  state u,u2;

  fill(d[0],d[n],INF);
  d[p][0] = 0;

  for(Q.push((state){p,0,0}); !Q.empty();){
    u = Q.top();
    Q.pop();

    if(u.bit == ((1 << m2) - 1) << m2){
      cout << u.c << endl;
      return;
    }

    for(int i=0;i<G[u.n].size();i++){
      edge &e = G[u.n][i];
      u2 = (state){e.n, u.bit, u.c+e.c};
      if(vs[u2.n] >= 0 && (u2.bit & (1 << vs[u2.n])) == 0 && (u2.bit & (1 << (vs[u2.n] + m2))) == 0) {
        u2.bit |= 1 << vs[u2.n];
      }
      if(vt[u2.n] >= 0 && (u2.bit & (1 << (vt[u2.n]))) != 0){
        u2.bit ^= 1 << vt[u2.n];
        u2.bit |= 1 << (vt[u2.n] + m2);
      }
      if(d[u2.n][u2.bit] > u2.c){
        d[u2.n][u2.bit] = u2.c;
        Q.push(u2);
      }
    }
  }

  cout << "Cannot deliver" << endl;
}

