bool is_prime(long long n){
	if(n == 1) return false; 
	if(n == 2 || n == 3) return true; 
	if(n % 6 != 1 && n % 6 != 5) return false; 
	for(long long i = 2; i * i <= n; i++){
		if(n % i == 0) return false; 
	}
	return true; 
}
long long gcd(long long a, long long b){
	return (b > 0)? gcd(b, a % b) : a ;
}
