const int D = 30;
int calc(vector<int>& v, int p) {
  int res = 0;
  for (int i = 0; i < v.size(); i++) res += 2 * abs(p - v[i]);
  return res;
}
int main() {
  int W, H, N;
  cin >> W >> H >> N;
  vector<int> X(N), Y(N);
  vector<pair<int, int> > points(N);
  for (int i = 0; i < N; i++) {
    cin >> X[i] >> Y[i];
    points[i] = mp(X[i], Y[i]);
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  long long best = INF, best_x = 0, best_y = 0;
  int mid_x = X[N / 2], mid_y = Y[N / 2];
  for (int last = 0; last < N; last++) {
    for (int x = mid_x - D; x <= mid_x + D; x++) {
      for (int y = mid_y - D; y <= mid_y + D; y++) {
        long long sub = calc(X, x) + calc(Y, y);
        sub -= abs(x - points[last].first);
        sub -= abs(y - points[last].second);
        if (sub < best) {
          best = sub;
          best_x = x;
          best_y = y;
        }
