using namespace std;
int findnext(vector<int> &m, int prev) {
  if (m.size() == 1) return m[0];
  int pos = -1;
  for (int i = 0; i < m.size(); i++) {
    if (m[i] > prev) {
      pos = i;
      break;
    }
  }
  if (pos == -1) {
    return m[m.size() - 1];
  }
  int ans = m[pos - 1];
  m.erase(m.begin() + pos - 1);
  return ans;
}
