  long double ans = 1234567890123456789;
  for (int i = 1; i <= n; ++i) {
    ans = min(ans, len(v[i], v[i - 1]));
    go(v[i - 1], v[i + 1]);
    ans = min(ans, dist(v[i]));
  }
  cout << fixed << setprecision(10) << ans / 2 << endl;
}

