#include <bits/stdc++.h>
const int N = 2e6 + 10;
const int mod = 998244353;
using namespace std;
const int G = 3, P = mod;
long long ksm(long long a, long long k, long long mo = P) {
  long long ans = 1;
  while (k) {
    if (k & 1) ans = ans * a % mo;
    a = a * a % mo;
    k >>= 1;
  }
  return ans;
}
int D(int x) {
  ((x >= P) && (x -= P)) || ((x < 0) && (x += P));
  return x;
}
void NTT(int A[], int n, int op) {
  for (int i = 1, j = n >> 1; i < n - 1; ++i) {
    if (i < j) swap(A[i], A[j]);
    int k = n >> 1;
    while (k <= j) {
      j -= k;
      k >>= 1;
    }
    j += k;
  }
  for (int len = 2; len <= n; len <<= 1) {
    int rt = ksm(G, (P - 1) / len, P);
    for (int i = 0; i < n; i += len) {
      int w = 1;
      for (int j = i; j < i + len / 2; ++j) {
        int u = A[j], t = 1LL * A[j + len / 2] * w % P;
        A[j] = D(u + t), A[j + len / 2] = D(u - t);
        w = 1LL * w * rt % P;
      }
    }
  }
  if (op == -1) {
    reverse(A + 1, A + n);
    int inv = ksm(n, P - 2, P);
    for (int i = 0; i < n; ++i) A[i] = 1LL * A[i] * inv % P;
  }
}
vector<int> Conv(vector<int> a, vector<int> b, int nn) {
  int la = a.size(), lb = b.size(), n = 1;
  while (n < (la + lb)) n <<= 1;
  n <<= 1;
  static int A[N], B[N];
  for (int i = 0; i < n; ++i) {
    A[i] = i < la ? a[i] : 0;
    B[i] = i < lb ? b[i] : 0;
  }
  NTT(A, n, 1);
  NTT(B, n, 1);
  for (int i = 0; i < n; ++i) A[i] = 1LL * A[i] * B[i] % P;
  NTT(A, n, -1);
  vector<int> c(nn);
  for (int i = 0; i < nn; ++i) c[i] = A[i];
  return c;
}
int dp[N];
void solve() {
  int n, x, y;
  scanf("%d%d%d", &n, &x, &y);
  vector<int> a(x + 1, 0), b(x + 1, 0);
  for (int i = 0, xx; i <= n; ++i) scanf("%d", &xx), a[xx] = 1, b[x - xx] = 1;
  vector<int> c = Conv(a, b, x * 2 + 1);
  memset(dp, -1, sizeof(dp));
  for (int i = x + 1; i <= 2 * x; ++i)
    if (c[i]) {
      int o = (i - x + y) * 2;
      for (int j = o; j < N; j += o) dp[j] = max(dp[j], o);
    }
  int q;
  scanf("%d", &q);
  while (q--) {
    int l;
    scanf("%d", &l);
    ;
    printf("%d ", dp[l]);
  }
}
