void get_sufm() {
  int alf = 'z' - 'a' + 2;
  for (int i = 0; i < len; ++i) cnt[s[i] - 'a' + 1] += 1;
  for (int i = 1; i < alf; ++i) cnt[i] += cnt[i - 1];
  for (int i = len - 1; i >= 0; --i) sufm[--cnt[s[i] - 'a' + 1]] = i;
  int cntclas = 1;
  clas[sufm[0]] = 0;
  for (int i = 1; i < len; ++i) {
    if (s[sufm[i - 1]] != s[sufm[i]]) cntclas += 1;
    clas[sufm[i]] = cntclas - 1;
  }
  for (int t = 0, step = 1; step <= len; step *= 2, t += 1) {
    for (int i = 0; i < len; ++i) sufmn[i] = (sufm[i] - step + len) % len;
    memset(cnt, 0, cntclas * sizeof(int));
    for (int i = 0; i < len; ++i) cnt[clas[sufmn[i]]] += 1;
    for (int i = 1; i < cntclas; ++i) cnt[i] += cnt[i - 1];
    for (int i = len - 1; i >= 0; --i) sufm[--cnt[clas[sufmn[i]]]] = sufmn[i];
    clasn[sufm[0]] = 0;
    cntclas = 1;
    for (int i = 1; i < len; ++i) {
      if (clas[sufm[i]] != clas[sufm[i - 1]] ||
          clas[(sufm[i] + step) % len] != clas[(sufm[i - 1] + step) % len])
        cntclas += 1;
      clasn[sufm[i]] = cntclas - 1;
    }
    memcpy(clas, clasn, len * sizeof(int));
  }
}
void get_lcp() {
  int nw = 0;
  for (int i = 0; i < len; ++i) clas[sufm[i]] = i;
  for (int i = 0; i < len; ++i) {
    if (nw > 0) nw -= 1;
    if (clas[i] == len - 1) {
      lcp[clas[i]] = -1;
      nw = 0;
    } else {
      int j = sufm[clas[i] + 1];
      while (j + nw < len && i + nw < len && s[i + nw] == s[j + nw]) nw += 1;
      lcp[clas[i]] = nw;
    }
  }
}
void build(int v, int tl, int tr) {
  if (tl == tr)
    tri[v] = lcp[tl - 1];
  else {
    int tm = (tl + tr) >> 1;
    build(v << 1, tl, tm);
    build((v << 1) | 1, tm + 1, tr);
    tri[v] = min(tri[v << 1], tri[(v << 1) | 1]);
  }
}
int get_min(int v, int tl, int tr, int l, int r) {
  if (l > r) return inf;
  if (tl == l && tr == r) return tri[v];
  int tm = (tl + tr) >> 1;
  return min(get_min(v << 1, tl, tm, l, min(tm, r)),
             get_min((v << 1) | 1, tm + 1, tr, max(l, tm + 1), r));
}
