      int ps = clas[i + 1], ts = clas[dp[i][j] + n + 2];
      if (ps > ts) swap(ps, ts);
      int lcp = get_min(1, 1, len, ps + 1, ts);
      dp[min(i + lcp, n)][j + 1] = max(dp[i + lcp][j + 1], dp[i][j] + lcp);
