    static class TaskC {
        public void solve(int testNumber, QuickScanner in, QuickWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n * n);
            SortedMultiSet<Integer> st = new SortedMultiSet<>();
            Arrays.sort(a);
            ArrayUtils.reverse(a);
            for (int num : a) st.add(num);
            List<Integer> ans = new ArrayList<>();
            while (!st.isEmpty()) {
                int largest = st.lastKey();
                st.remove(largest);
                ans.add(largest);
                for (int alr : ans) {
                    int g = (int) IntegerUtils.gcd(alr, largest);
                    st.remove(g);
                    st.remove(g);
                }
            }
            out.writeLine(ans);
        }

    }

    static class QuickScanner {
        BufferedReader br;
        StringTokenizer st;
        InputStream is;

        public QuickScanner(InputStream stream) {
            is = stream;
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public int[] nextIntArray(int len) {
            int[] a = new int[len];
            for (int i = 0; i < len; i++) {
                a[i] = nextInt();
            }
            return a;
        }

    }

    static class SortedMultiSet<T> implements Iterable<T> {
        private final SortedMap<T, Integer> map;
        private int size;

        public SortedMultiSet() {
            map = new TreeMap<T, Integer>();
            size = 0;
        }

        public boolean isEmpty() {
            return size == 0;
        }

        public void add(T key) {
            Integer count = map.get(key);
            if (count == null) {
                count = 0;
            }
            count++;
            size++;
            map.put(key, count);
        }

        public void remove(T key) {
            Integer count = map.get(key);
            if (count == null) return;
            count--;
            size--;
            if (count == 0)
                map.remove(key);
            else
                map.put(key, count);
        }


        public Iterator<T> iterator() {
            return map.keySet().iterator();
        }

        public T lastKey() {
            return map.lastKey();
        }

    }

    static class IntegerUtils {
        public static long gcd(long a, long b) {
            return (b == 0) ? a : gcd(b, a % b);
        }

    }

