            super(out);
        }

        public QuickWriter(OutputStream out, boolean autoFlush) {
            super(out, autoFlush);
        }

        public QuickWriter(Writer out, boolean autoFlush) {
            super(out, autoFlush);
        }

        public <T> void writeLine(List<T> a) {
            for (int i = 0; i < a.size(); i++) {
                print((i != 0 ? " " : "") + a.get(i));
            }
        }

    }

    static class ArrayUtils {
        public static void reverse(int[] array) {
            int n = array.length;
            for (int i = 0, j = n - 1; i < n / 2; i++, j--) {
                array[i] ^= array[j];
                array[j] ^= array[i];
                array[i] ^= array[j];
            }
        }

    }
