const long long INF = 1LL << 60;
template <class T>
pair<vector<T>, map<T, int> > compress(vector<T>& a) {
  vector<T> v;
  for (int i = 0; i < a.size(); i++) v.push_back(a[i]);
  sort(v.begin(), v.end());
  v.erase(unique(v.begin(), v.end()), v.end());
  map<T, int> m;
  for (int i = 0; i < v.size(); i++) m[v[i]] = i;
  return {v, m};
}
struct edge {
