  long long cost;
  bool operator<(const S& x) const { return cost > x.cost; }
};
using P = pair<int, int>;
vector<edge> G[300][300][11];
long long dist[300][300][11];
long long sum[300][300];
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int N, M, K, R;
  vector<int> X(100), Y(100), Z(100), xl(50), xr(50), yt(50), yb(50), h(50);
  while (cin >> N, N) {
    cin >> M >> K >> R;
    vector<int> xs, ys;
    for (int i = 0; i < N; i++) {
      cin >> X[i] >> Y[i] >> Z[i];
      xs.push_back(X[i]);
      ys.push_back(Y[i]);
    }
    for (int i = 0; i < M; i++) {
      cin >> xl[i] >> yt[i] >> xr[i] >> yb[i] >> h[i];
      xs.push_back(xl[i]);
      xs.push_back(xr[i]);
      ys.push_back(yt[i]);
      ys.push_back(yb[i]);
      if (h[i] == K) {
        if (xl[i] - 1 >= 1) xs.push_back(xl[i] - 1);
        if (xr[i] + 1 <= R) xs.push_back(xr[i] + 1);
        if (yt[i] - 1 >= 1) ys.push_back(yt[i] - 1);
        if (yb[i] + 1 <= R) ys.push_back(yb[i] + 1);
      }
    }
    auto zipX = compress(xs);
    auto zipY = compress(ys);
    int XN = zipX.first.size();
    int YN = zipY.first.size();
    for (int k = 1; k <= K; k++) {
      for (int i = 0; i < XN; i++) {
        for (int j = 0; j < YN; j++) {
          G[i][j][k].clear();
        }
      }
    }
    for (int k = 1; k < K; k++) {
      for (int i = 0; i < XN; i++) {
        for (int j = 0; j < YN; j++) {
          int cx = zipX.first[i];
          int cy = zipY.first[j];
          for (int m = 0; m < M; m++) {
            if (k + 1 != h[m]) continue;
            long long cost = INF;
            int ii = 0, jj = 0;
            int li = zipX.second[xl[m]];
            int ri = zipX.second[xr[m]];
            int tj = zipY.second[yt[m]];
            int bj = zipY.second[yb[m]];
            if (li <= i && i <= ri && tj <= j && j <= bj) {
              if (cost > 100) {
                cost = 100;
                ii = i, jj = j;
              }
            } else if (li <= i && i <= ri) {
              if (cost > 100 + abs(cy - yt[m])) {
                cost = 100 + abs(cy - yt[m]);
                ii = i, jj = tj;
              }
              if (cost > 100 + abs(cy - yb[m])) {
                cost = 100 + abs(cy - yb[m]);
                ii = i, jj = bj;
              }
            } else if (tj <= j && j <= bj) {
              if (cost > 100 + abs(cx - xl[m])) {
                cost = 100 + abs(cx - xl[m]);
                ii = li, jj = j;
              }
              if (cost > 100 + abs(cx - xr[m])) {
                cost = 100 + abs(cx - xr[m]);
                ii = ri, jj = j;
              }
            } else {
              if (cost > 100 + abs(cx - xl[m]) + abs(cy - yt[m])) {
                cost = 100 + abs(cx - xl[m]) + abs(cy - yt[m]);
                ii = li, jj = tj;
              }
              if (cost > 100 + abs(cx - xr[m]) + abs(cy - yt[m])) {
                cost = 100 + abs(cx - xr[m]) + abs(cy - yt[m]);
                ii = ri, jj = tj;
              }
              if (cost > 100 + abs(cx - xl[m]) + abs(cy - yb[m])) {
                cost = 100 + abs(cx - xl[m]) + abs(cy - yb[m]);
                ii = li, jj = bj;
              }
              if (cost > 100 + abs(cx - xr[m]) + abs(cy - yb[m])) {
                cost = 100 + abs(cx - xr[m]) + abs(cy - yb[m]);
                ii = ri, jj = bj;
              }
            }
            G[i][j][k].push_back({ii, jj, k + 1, cost});
          }
        }
      }
    }
    vector<P> goal;
    for (int i = 0; i < XN; i++) {
      for (int j = 0; j < YN; j++) {
        int cx = zipX.first[i];
        int cy = zipY.first[j];
        bool ok = true;
        for (int m = 0; m < M; m++) {
          if (K == h[m] && xl[m] <= cx && cx <= xr[m] && yt[m] <= cy &&
              cy <= yb[m]) {
            ok = false;
            break;
          }
        }
        if (ok) goal.push_back({i, j});
      }
    }
    memset(sum, 0, sizeof sum);
    for (int n = 0; n < N; n++) {
      for (int k = 1; k <= K; k++) {
        for (int i = 0; i < XN; i++) {
          for (int j = 0; j < YN; j++) {
            dist[i][j][k] = INF;
          }
        }
      }
      dist[zipX.second[X[n]]][zipY.second[Y[n]]][Z[n]] = 0;
      priority_queue<S> q;
      q.push({zipX.second[X[n]], zipY.second[Y[n]], Z[n], 0});
      while (q.size()) {
        S s = q.top();
        q.pop();
        if (dist[s.x][s.y][s.z] < s.cost) continue;
        for (auto& e : G[s.x][s.y][s.z]) {
          long long ncost = s.cost + e.cost;
          if (dist[e.x][e.y][e.z] > ncost) {
            dist[e.x][e.y][e.z] = ncost;
            q.push({e.x, e.y, e.z, ncost});
          }
        }
      }
      for (auto& g : goal) {
        int xx = zipX.first[g.first];
        int yy = zipY.first[g.second];
        long long minCost = INF;
        for (int i = 0; i < XN; i++) {
          for (int j = 0; j < YN; j++) {
            minCost = min(minCost, dist[i][j][K] + abs(xx - zipX.first[i]) +
                                       abs(yy - zipY.first[j]));
          }
        }
        sum[g.first][g.second] += minCost;
      }
    }
    long long ans = INF;
    for (auto& g : goal) {
      ans = min(ans, sum[g.first][g.second]);
    }
    cout << ans << endl;
  }
}

import java.time.LocalDate;
import java.util.Scanner;
import java.util.concurrent.Callable;

public class Solution implements Callable<Long> {

    private long m;
    private long x;

    public Solution(long m, long x) {
        this.m = m;
        this.x = x;
    }

    private class DisjointSet {

        int[] parrent;
        int[] rank;
        int count;

        public DisjointSet(int cap) {
            parrent = new int[cap];
            for (int i = 0; i < parrent.length; i++) {
                parrent[i] = i;
            }
            rank = new int[cap];
            count = cap;
        }

        void union(int c1, int c2) {
            int f1 = find(c1);
            int f2 = find(c2);
            if (f1 == f2) {
                return;
            }
            count--;
            if (rank[f1] > rank[f2]) {
                parrent[f2] = f1;
            } else {
                parrent[f1] = f2;
                if (rank[f1] == rank[f2]) {
                    rank[f2]++;
                }
            }
        }

        int find(int i) {
            if (i < 0 || i > parrent.length) {
                return -1;
            }
            while (parrent[i] != i) {
                i = parrent[i];
            }
            return i;
        }

        int size() {
            return count;
        }

    }

    public Long call() {
        double fx = (double) x;
        double fm = (double) m;
        double lEdge = (fm / (fm - 1));
        double hEdge = fm - lEdge;
        boolean rule = lEdge < hEdge;
        if (rule && (fx < lEdge || fx > hEdge)) {
            return 1 + (m - 1) / 2 + (m - 1) % 2;
        }
        DisjointSet ds = new DisjointSet((int)m);
        for (int i = 0; i < m; i++) {
            long next = (i * x) % m;
            ds.union(i, (int) next);
        }
        return Long.valueOf(ds.size());
    }

    public static void main(String... args) {
        Scanner s = new Scanner(System.in);
        long m = s.nextLong();
        long x = s.nextLong();
        System.out.println(new Solution(m, x).call());

    }
}

#include <bits/stdc++.h>
using namespace std;
const int N = 212345;
int seg[4 * N], v[N], tin[N], tout[N], ans[N];
int a, b, n, q;
void init(int r, int i, int j) {
  if (i == j) {
    seg[r] = v[i];
  } else {
    init(2 * r, i, (i + j) / 2);
    init(2 * r + 1, (i + j) / 2 + 1, j);
    seg[r] = min(seg[2 * r], seg[2 * r + 1]);
  }
}
int query(int r, int i, int j) {
  if (b < i || a > j) return 0x3f3f3f3f;
  if (i >= a && j <= b) {
    return seg[r];
  } else {
    int L = query(2 * r, i, (i + j) / 2);
    int R = query(2 * r + 1, (i + j) / 2 + 1, j);
    return min(L, R);
  }
}
void update(int r, int i, int j, int pos, int val) {
  if (pos < i || pos > j) return;
  if (i == j) {
    seg[r] = val;
  } else {
    update(2 * r, i, (i + j) / 2, pos, val);
    update(2 * r + 1, (i + j) / 2 + 1, j, pos, val);
    seg[r] = min(seg[2 * r], seg[2 * r + 1]);
  }
}
set<int> zeros;
int main(void) {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> q;
  int mx = 0;
  for (int i = 1; i <= n; i++) {
    cin >> v[i];
    if (v[i] == 0) {
      zeros.emplace(i);
      v[i] = 0x3f3f3f3f;
    } else {
      if (tin[v[i]] == 0) tin[v[i]] = i;
      tout[v[i]] = i;
      mx = max(mx, v[i]);
    }
  }
  if (zeros.size() == n) {
    cout << "YES" << endl;
    for (int i = 1; i <= n; i++) cout << q << " ";
    cout << endl;
    return 0;
  }
  if (mx != q and zeros.size() == 0) {
    cout << "NO" << endl;
    return 0;
  }
  init(1, 1, n);
  if (mx != q and zeros.size()) {
    auto it = zeros.begin();
    update(1, 1, n, *it, q);
    zeros.erase(it);
  }
  for (int i = q; i >= 1; i--) {
    if (tin[i] == 0) continue;
    a = tin[i];
    b = tout[i];
    if (query(1, 1, n) < i) {
      cout << "NO" << endl;
      return 0;
    }
    auto it = zeros.lower_bound(tin[i]);
    while (it != zeros.end() and *it <= tout[i]) {
      update(1, 1, n, *it, i);
      it = zeros.erase(it);
    }
  }
  for (int i = 1; i <= n; i++) {
    a = i;
    b = i;
    ans[i] = query(1, 1, n);
  }
  for (int i = 2; i <= n; i++) {
    if (ans[i] == 0x3f3f3f3f and ans[i - 1] != 0x3f3f3f3f) ans[i] = ans[i - 1];
  }
  for (int i = n - 1; i >= 1; i--) {
    if (ans[i] == 0x3f3f3f3f and ans[i + 1] != 0x3f3f3f3f) ans[i] = ans[i + 1];
  }
  cout << "YES" << endl;
  for (int i = 1; i <= n; i++) {
    assert(ans[i] != 0x3f3f3f3f);
    cout << ans[i] << " ";
  }
  cout << endl;
  return 0;
}

